// Hyperrealist Grey Felt Valenki Boots in a Snowdrift
// Soviet children's-book gouache backdrop (brick red, mustard ochre, cold turquoise)
// with dense, patient coloured-pencil rendering of matted wool, ankle cracks, and snow crusts.

const SEED = 4281;

const PALETTE = {
  paper: "#f5ede0",
  paperDark: "#eadec9",
  paperShadow: "#dfd1b8",

  // Flat gouache backdrop (soft pastel-infused Soviet lithograph colors)
  turquoise: "#89bdbc",
  turquoiseGhost: "#a8d4d2",
  turquoiseDeep: "#6da3a3",

  brick: "#cb6857",
  brickGhost: "#e08978",
  brickDeep: "#b05040",

  ochre: "#e0b358",
  ochreGhost: "#edd683",
  ochreDeep: "#c7963b",

  overlapOrange: "#c87846",
  overlapTealOchre: "#8eab78",
  sunDisk: "#f7dfb0",
  sunGhost: "#fae9c8",

  // Snowdrift pastels (low winter light from left)
  snowBright: "#fefcf6",
  snowSun: "#faefd5",
  snowWarm: "#f3e1b9",
  snowMid: "#dce6ef",
  snowShadowLight: "#c2d3e3",
  snowShadowMid: "#a2b9cf",
  snowShadowDeep: "#849fb9",
  snowCrevice: "#627a96",

  // Felt valenki coloured-pencil palette
  feltCrackBright: "#fbf6ea",
  feltHighlight: "#ece5d7",
  feltLightWarm: "#dbd3c3",
  feltLightCool: "#cfd4d8",
  feltMidLight: "#bdb5a7",
  feltMid: "#9f988d",
  feltMidWarm: "#918679",
  feltMidCool: "#8c9399",
  feltDark: "#736e67",
  feltShadow: "#58585c",
  feltDeepShadow: "#424347",
  feltCrevice: "#2d2d30",
  feltBounceBlue: "#727e8c",
  feltOchreTint: "#bfa97e",
  feltBrickTint: "#b3877d",
  feltTurqTint: "#88a1a6"
};

let bootA, bootB;

async function setup() {
  createCanvas(1200, 1200, WEBGL);
  brush.scaleBrushes(3);
  angleMode(DEGREES);
  randomSeed(SEED);
  noiseSeed(SEED);

  // Register ultra-fine coloured pencil and wool-fibre custom brushes
  brush.add("wool_pencil", {
    type: "default",
    weight: 0.9,
    scatter: 0.18,
    sharpness: 0.78,
    grain: 14,
    opacity: 175,
    spacing: 0.18,
    pressure: [0.35, 1.15, 0.3],
    rotate: "natural",
    noise: 0.65
  });

  brush.add("fine_whisker", {
    type: "default",
    weight: 0.55,
    scatter: 0.08,
    sharpness: 0.88,
    grain: 9,
    opacity: 210,
    spacing: 0.14,
    pressure: [0.9, 0.65, 0.08],
    rotate: "natural",
    noise: 0.4
  });

  brush.add("gouache_flat", {
    type: "marker",
    weight: 6,
    scatter: 0.06,
    opacity: 32,
    spacing: 0.35,
    pressure: [0.9, 1.0, 0.9],
    markerTip: false,
    noise: 0.25
  });

  initBoots();
}

function draw() {
  translate(-width / 2, -height / 2);
  background(PALETTE.paper);

  // 1. Aged storybook paper grain & warm undertone
  drawPaperGround();

  // 2. Crisp, slightly off-register gouache backdrop (Turquoise, Mustard Ochre, Brick Red)
  drawGouacheBackdrop();

  // 3. Rear & mid snowdrift washes + boot cast shadows
  drawSnowdriftBackgroundAndShadows();

  // 4. Knock-out print registration halos behind the boots
  drawBootRegistrationKnockouts();

  // 5. Render Left Boot (Boot A - angled front-left) & Right Boot (Boot B - angled front-right)
  renderBootUnderpainting(bootA);
  renderBootUnderpainting(bootB);

  renderBootColouredPencil(bootA);
  renderBootColouredPencil(bootB);

  renderBootTopRimAndInterior(bootA);
  renderBootTopRimAndInterior(bootB);

  renderBootAnkleCracks(bootA);
  renderBootAnkleCracks(bootB);

  renderBootSilhouetteFuzz(bootA);
  renderBootSilhouetteFuzz(bootB);

  // 6. Clinging snow crusts on soles, toes, heels, and lower felt + foreground snow lip
  drawSnowTroughAndClingingCrusts();

  // 7. Crisp storybook margin & lithographic registration marks
  drawPrintMarginsAndMarks();

  noLoop();
}

// ============================================================================
// GEOMETRY & PARAMETRIC BOOT DEFINITIONS
// ============================================================================

