    yBottom: 906,
    rim: { cx: 656, cy: 286, rx: 84, ry: 23, tilt: 3.2 },
    leftProfile: [
      [572, 286],
      [570, 395],
      [574, 520],
      [581, 640],
      [584, 706], // Achilles hollow
      [570, 770],
      [561, 822], // heel bulge
      [568, 868],
      [584, 892]
    ],
    soleProfile: [
      [584, 892],
      [662, 902],
      [760, 906],
      [854, 900]
    ],
    rightProfile: [
      [740, 286],
      [738, 395],
      [734, 515],
      [729, 622],
      [720, 680],
      [726, 704], // ankle ridge
      [718, 728], // deep ankle flex notch
      [772, 764], // upper instep
      [836, 798], // lower instep
      [882, 832], // upper toe dome
      [896, 860], // bulbous toe tip
      [882, 886], // upturned lower toe
      [854, 900]  // front sole contact
    ],
    creases: [
      // Primary deep ankle crease with prominent pale crack catching left light
      {
        x0: 608, y0: 682,
        cx: 668, cy: 696,
        x1: 725, y1: 705,
        width: 16,
        depth: 0.98,
        hasPaleCrack: true,
        crackStartT: 0.08,
        crackEndT: 0.92
      },
      // Deep lower ankle flex crease with pale split
      {
        x0: 604, y0: 712,
        cx: 664, cy: 724,
        x1: 718, y1: 729,
        width: 17,
        depth: 0.88,
        hasPaleCrack: true,
        crackStartT: 0.14,
        crackEndT: 0.86
      },
      // Instep bridge fold
      {
        x0: 632, y0: 752,
        cx: 704, cy: 760,
        x1: 770, y1: 765,
        width: 22,
        depth: 0.58,
        hasPaleCrack: false
      },
      // Upper ankle fold
      {
        x0: 616, y0: 654,
