function sampleCatmullRomChain(pts, samplesPerSeg = 8) {
  let out = [];
  for (let i = 0; i < pts.length - 1; i++) {
    let p0 = pts[Math.max(0, i - 1)];
    let p1 = pts[i];
    let p2 = pts[i + 1];
    let p3 = pts[Math.min(pts.length - 1, i + 2)];
    for (let s = 0; s < samplesPerSeg; s++) {
      let t = s / samplesPerSeg;
      let t2 = t * t;
      let t3 = t2 * t;
      let x =
        0.5 *
        (2 * p1[0] +
          (-p0[0] + p2[0]) * t +
          (2 * p0[0] - 5 * p1[0] + 4 * p2[0] - p3[0]) * t2 +
          (-p0[0] + 3 * p1[0] - 3 * p2[0] + p3[0]) * t3);
      let y =
        0.5 *
        (2 * p1[1] +
          (-p0[1] + p2[1]) * t +
          (2 * p0[1] - 5 * p1[1] + 4 * p2[1] - p3[1]) * t2 +
          (-p0[1] + 3 * p1[1] - 3 * p2[1] + p3[1]) * t3);
      out.push([x, y]);
    }
  }
  out.push(pts[pts.length - 1]);
  return out;
}

function buildBootOutline(boot) {
  let leftCurve = sampleCatmullRomChain(boot.leftProfile, 6);
  let soleCurve = sampleCatmullRomChain(boot.soleProfile, 6);
  let rightCurve = sampleCatmullRomChain(boot.rightProfile, 6).reverse();

  // Top rim front arc (lower half of ellipse) or back arc (upper half)
  let topArc = [];
  let steps = 18;
  let tiltRad = (boot.rim.tilt * Math.PI) / 180;
  for (let i = 1; i < steps; i++) {
    let u = i / steps; // right to left across back of rim
    let ang = Math.PI + u * Math.PI; // upper half of ellipse (-PI to 0)
    let ex = Math.cos(ang) * boot.rim.rx;
    let ey = Math.sin(ang) * boot.rim.ry;
    let rx = boot.rim.cx + ex * Math.cos(tiltRad) - ey * Math.sin(tiltRad);
    let ry = boot.rim.cy + ex * Math.sin(tiltRad) + ey * Math.cos(tiltRad);
    topArc.push([rx, ry]);
  }

  boot.leftDense = leftCurve;
  boot.rightDense = sampleCatmullRomChain(boot.rightProfile, 6);
  boot.soleDense = soleCurve;

  return [
    ...leftCurve,
    ...soleCurve.slice(1),
    ...rightCurve.slice(1),
    ...topArc
  ];
}

// Point-in-polygon check (fast ray casting)
function pointInPoly(x, y, vs) {
  let inside = false;
  for (let i = 0, j = vs.length - 1; i < vs.length; j = i++) {
    let xi = vs[i][0], yi = vs[i][1];
    let xj = vs[j][0], yj = vs[j][1];
    let intersect =
      yi > y !== yj > y && x < ((xj - xi) * (y - yi)) / (yj - yi + 1e-9) + xi;
    if (intersect) inside = !inside;
  }
  return inside;
}

function evalProfileXAtY(denseCurve, y) {
  let bestX = denseCurve[0][0];
  let minD = 1e9;
  for (let i = 0; i < denseCurve.length - 1; i++) {
    let y0 = denseCurve[i][1], y1 = denseCurve[i + 1][1];
    if ((y >= y0 && y <= y1) || (y >= y1 && y <= y0)) {
      let t = Math.abs(y1 - y0) < 1e-4 ? 0 : (y - y0) / (y1 - y0);
      return denseCurve[i][0] + t * (denseCurve[i + 1][0] - denseCurve[i][0]);
    }
    let d = Math.abs(y - y0);
    if (d < minD) {
      minD = d;
      bestX = denseCurve[i][0];
    }
  }
  return bestX;
}

function evalQuadBezier(p0x, p0y, cx, cy, p1x, p1y, t) {
  let mt = 1 - t;
  return [
    mt * mt * p0x + 2 * mt * t * cx + t * t * p1x,
    mt * mt * p0y + 2 * mt * t * cy + t * t * p1y
  ];
}

function evalBootSurface(boot, x, y) {
  let xL = evalProfileXAtY(boot.leftDense, y);
  let xR = evalProfileXAtY(boot.rightDense, y);
  if (xR < xL + 4) xR = xL + 4;

  let midX = 0.5 * (xL + xR);
  let halfW = 0.5 * (xR - xL);
  let u = constrain((x - midX) / halfW, -1, 1);

  // Base cylindrical normal across horizontal section
  let nx = Math.sin(u * Math.PI * 0.47);
  let ny = -0.04;
  let nz = Math.cos(u * Math.PI * 0.47);

  // Foot / instep / bulbous toe 3D dome shaping below ankle
  if (y > boot.yAnkle - 20) {
    let footFactor = constrain((y - (boot.yAnkle - 20)) / (boot.yBottom - boot.yAnkle + 20), 0, 1);
    // Instep faces upward-forward; sole faces downward
    let footMidY = boot.yAnkle + (boot.yBottom - boot.yAnkle) * 0.62;
    let vFoot = (y - footMidY) / ((boot.yBottom - boot.yAnkle) * 0.45);
    let instepTilt = constrain(vFoot, -1, 1) * 0.68;
    ny = lerp(ny, instepTilt, footFactor * 0.85);

    // Bulbous toe rounding
    if (boot.toeDir < 0) {
      // Toe extends left: strong left-upward curvature on left half
      let toeReach = constrain((415 - x) / 155, 0, 1);
      ny -= toeReach * (1 - footFactor * 0.7) * 0.35;
      nx = lerp(nx, -0.75 * toeReach + nx * 0.5, toeReach * 0.55);
    } else {
      // Toe extends right
      let toeReach = constrain((x - 715) / 175, 0, 1);
      ny -= toeReach * (1 - footFactor * 0.7) * 0.35;
      nx = lerp(nx, 0.75 * toeReach + nx * 0.5, toeReach * 0.55);
    }
  }

  // Evaluate ankle & instep creases
  let creaseDeltaY = 0;
  let creaseTrough = 0;
  let crackSignal = 0;
  let fiberAngle = boot.toeDir < 0 ? -8 + u * 16 : 8 + u * 16;

  for (let c of boot.creases) {
    let t = constrain((x - c.x0) / (c.x1 - c.x0 + 1e-5), 0, 1);
    let [cx, cy] = evalQuadBezier(c.x0, c.y0, c.cx, c.cy, c.x1, c.y1, t);
    let dy = y - cy;
    let normD = dy / c.width;
    if (Math.abs(normD) < 2.4) {
      // Fade crease strength near heel edge
      let edgeWeight = boot.toeDir < 0 ? Math.pow(1 - t * 0.72, 0.8) : Math.pow(0.28 + t * 0.72, 0.8);
      let gauss = Math.exp(-normD * normD * 1.4) * c.depth * edgeWeight;
      creaseTrough = Math.max(creaseTrough, gauss);
      // Derivative tilts ny: upper wall tilts down (+ny, dark), lower lip tilts up (-ny, bright)
      creaseDeltaY += -normD * 1.85 * gauss;

      if (c.hasPaleCrack && t >= c.crackStartT && t <= c.crackEndT) {
        if (Math.abs(normD - 0.32) < 0.28) {
          crackSignal = Math.max(crackSignal, 1.0); // bright stretched pale crack lip
        } else if (Math.abs(normD + 0.08) < 0.16) {
          crackSignal = Math.min(crackSignal, -1.0); // dark split fissure
        }
      }
    }
  }

  ny += creaseDeltaY * 0.52;

  // Normalize 3D normal
  let len = Math.hypot(nx, ny, nz) || 1;
  nx /= len;
  ny /= len;
  nz /= len;

  // Low winter light from the left: L = normalize(-0.81, -0.25, 0.53)
  let lx = -0.81, ly = -0.25, lz = 0.53;
  let ndotl = nx * lx + ny * ly + nz * lz;

  // Subtle cast shadow from Boot A onto Boot B's lower-left heel/calf edge
  let castAtten = 1.0;
  if (boot.id === "B" && y > 540 && u < -0.45) {
    let sFactor = constrain((y - 540) / 180, 0, 1) * constrain((-0.45 - u) / 0.5, 0, 1);
    castAtten = 1.0 - 0.38 * sFactor;
  }

  let directLight = constrain((ndotl + 0.18) / 1.18, 0, 1) * castAtten;
  // Deepen inside crease troughs
  directLight = constrain(directLight - creaseTrough * 0.28 + (crackSignal > 0 ? 0.26 : 0), 0, 1);

  // Cool bounce light on right-facing shadow edges from snowdrift
  let snowBounce = constrain((nx - 0.35) / 0.65, 0, 1) * constrain((y - 420) / 450, 0.25, 1.0);

  // Cross-contour angle for form-following pencil hatching
  let contourAngle = u * 22 + (y > boot.yAnkle ? boot.toeDir * 18 : 0);

  return {
    u,
    nx,
    ny,
    nz,
    light: directLight,
    snowBounce,
    creaseTrough,
    crackSignal,
    contourAngle,
    fiberAngle
  };
}

// ============================================================================
// DRAWING HELPERS
// ============================================================================

function drawPolyShape(pts, curvature = 0.08, closeShape = true) {
  brush.beginShape(curvature);
  for (let i = 0; i < pts.length; i++) {
    brush.vertex(pts[i][0], pts[i][1]);
  }
  brush.endShape(closeShape);
}

function offsetPoly(pts, dx, dy) {
  return pts.map((p) => [p[0] + dx, p[1] + dy]);
}

// ============================================================================
// 1. PAPER GROUND
// ============================================================================

function drawPaperGround() {
  brush.noField();
  brush.noStroke();
  brush.wash(PALETTE.paper, 255);
  brush.rect(0, 0, width, height, "corner");

  // Warm vignette and vintage paper mottling
  brush.fill(PALETTE.paperDark, 42);
  brush.fillBleed(0.35, "in");
  brush.fillTexture(0.55, 0.25);
  brush.rect(40, 40, width - 80, height - 80, "corner");
  brush.noFill();
  brush.noWash();

  // Subtle paper fibres across the sheet
  brush.set("2H", "#dfd2bc", 0.35);
  for (let i = 0; i < 240; i++) {
    let x = random(30, width - 30);
    let y = random(30, height - 30);
    let a = random(-25, 25) * (Math.PI / 180);
    let l = random(8, 28);
    brush.line(x, y, x + Math.cos(a) * l, y + Math.sin(a) * l);
  }
}

// ============================================================================
// 2. FLAT GOUACHE-LIKE WATERCOLOUR BACKDROP (CRISP & SLIGHTLY OFF-REGISTER)
// ============================================================================

function drawGouacheBackdrop() {
  brush.noField();

  // Define the three crisp storybook backdrop plates:
  // Plate 1: Cold Turquoise Sky (upper register)
  const skyPoly = [
    [96, 94],
    [1104, 94],
    [1104, 332],
    [736, 304],
    [474, 378],
    [96, 352]
  ];

  // Plate 2: Mustard Ochre Field (right & center-midground diagonal gable/wall plane)
  const ochrePoly = [
    [464, 374],
    [738, 298],
    [1104, 326],
    [1104, 628],
    [452, 608]
  ];

  // Plate 3: Brick Red Field (left & center-midground architectural/fence plane)
  const brickPoly = [
    [96, 348],
    [522, 376],
    [514, 616],
    [96, 598]
  ];

  // --- A. Off-Register Print Ghosts (shifted plates for lithographic character) ---
  brush.noStroke();
  brush.wash(PALETTE.turquoiseGhost, 155);
  drawPolyShape(offsetPoly(skyPoly, -9, -7), 0.02);

  brush.wash(PALETTE.ochreGhost, 165);
  drawPolyShape(offsetPoly(ochrePoly, 10, -7), 0.02);

  brush.wash(PALETTE.brickGhost, 160);
  drawPolyShape(offsetPoly(brickPoly, -8, 8), 0.02);
  brush.noWash();

  // --- B. Main Flat Gouache-Watercolour Fields (batched by color with crisp edges) ---
  // 1) Cold Turquoise Sky
  brush.noStroke();
  brush.wash(PALETTE.turquoise, 215);
  brush.fill(PALETTE.turquoise, 115);
  brush.fillBleed(0.025, "out");
  brush.fillTexture(0.52, 0.42);
  drawPolyShape(skyPoly, 0.02);
  brush.noFill();
  brush.noWash();

  // Flat gouache horizontal brush-pull bands inside the turquoise sky
  drawGouacheBrushBands(skyPoly, "#7bb0af", "#9ccbc9", 0, 26);

  // Low winter sun disk on upper left (cheerful, flat printed pastel disk)
  brush.noStroke();
  brush.wash(PALETTE.sunGhost, 180);
  brush.circle(226 + 7, 206 - 5, 55, 0.08);
  brush.wash(PALETTE.sunDisk, 230);
  brush.fill("#f4d08e", 90);
  brush.fillBleed(0.02, "out");
  brush.fillTexture(0.4, 0.35);
  brush.circle(226, 206, 54, 0.08);
  brush.noFill();
  brush.noWash();

  // 2) Mustard Ochre Field
  brush.noStroke();
  brush.wash(PALETTE.ochre, 222);
  brush.fill(PALETTE.ochre, 120);
  brush.fillBleed(0.025, "out");
  brush.fillTexture(0.55, 0.45);
  drawPolyShape(ochrePoly, 0.02);
  brush.noFill();
  brush.noWash();

  drawGouacheBrushBands(ochrePoly, "#cfa043", "#ebd07e", 2, 24);

  // 3) Brick Red Field
  brush.noStroke();
  brush.wash(PALETTE.brick, 225);
  brush.fill(PALETTE.brick, 125);
  brush.fillBleed(0.025, "out");
  brush.fillTexture(0.55, 0.48);
  drawPolyShape(brickPoly, 0.02);
  brush.noFill();
  brush.noWash();

  drawGouacheBrushBands(brickPoly, "#b85544", "#dc7f6e", -1, 24);

  // --- C. Crisp Off-Register Plate Overlaps & Unprinted Slivers ---
  // Overlap glaze strip where Brick Red and Mustard Ochre plates overlap (x: 460..522)
  const overlapBrickOchre = [
    [464, 374],
    [522, 376],
    [514, 612],
    [454, 608]
  ];
  brush.noStroke();
  brush.wash(PALETTE.overlapOrange, 145);
  drawPolyShape(overlapBrickOchre, 0.01);

  // Narrow unprinted paper registration gap between Sky and Brick Red on the left
  const paperGapStrip = [
    [96, 345],
    [464, 371],
    [464, 378],
    [96, 353]
  ];
  brush.wash(PALETTE.paper, 235);
  drawPolyShape(paperGapStrip, 0.01);

  // Narrow off-register teal-ochre overprint strip along right sky/ochre seam
  const seamTealOchre = [
    [736, 298],
    [1104, 326],
    [1104, 335],
    [736, 307]
  ];
  brush.wash(PALETTE.overlapTealOchre, 130);
  drawPolyShape(seamTealOchre, 0.01);
  brush.noWash();

  // Crisp gouache/litho edge lines along the background blocks
  brush.set("cpencil", PALETTE.turquoiseDeep, 0.55);
  drawPolyOutline(offsetPoly(skyPoly, -3, -2));

  brush.set("cpencil", PALETTE.ochreDeep, 0.6);
  drawPolyOutline(offsetPoly(ochrePoly, 4, -3));

  brush.set("cpencil", PALETTE.brickDeep, 0.65);
  drawPolyOutline(offsetPoly(brickPoly, -3, 3));
}

function drawPolyOutline(pts) {
  for (let i = 0; i < pts.length; i++) {
    let p0 = pts[i];
    let p1 = pts[(i + 1) % pts.length];
    brush.line(p0[0], p0[1], p1[0], p1[1]);
  }
}

function drawGouacheBrushBands(polyPts, darkCol, lightCol, angleDeg, stepY) {
  let minX = 1e9, maxX = -1e9, minY = 1e9, maxY = -1e9;
  for (let p of polyPts) {
    if (p[0] < minX) minX = p[0];
    if (p[0] > maxX) maxX = p[0];
    if (p[1] < minY) minY = p[1];
    if (p[1] > maxY) maxY = p[1];
  }
  let pObj = new brush.Polygon(polyPts);
  let rad = (angleDeg * Math.PI) / 180;
  let dy = Math.tan(rad) * (maxX - minX);

  for (let y = minY + 10; y < maxY - 8; y += stepY) {
    let linePts = [
      [minX - 20, y - dy * 0.5],
      [maxX + 20, y + dy * 0.5]
    ];
    let hits = pObj.intersect(linePts);
    if (hits && hits.length >= 2) {
      hits.sort((a, b) => a.x - b.x);
      let col = random() < 0.5 ? darkCol : lightCol;
      brush.set("gouache_flat", col, random(0.8, 1.45));
      brush.line(hits[0].x + 3, hits[0].y, hits[hits.length - 1].x - 3, hits[hits.length - 1].y);
    }
  }
}

