// ============================================================================
// 5. OBSESSIVE COLOURED-PENCIL RENDERING OF THE VALENKI BOOTS
// ============================================================================

function renderBootUnderpainting(boot) {
  brush.noField();
  brush.noStroke();

  // Base mid-grey felt wash
  brush.wash(PALETTE.feltMid, 195);
  brush.fill(PALETTE.feltMidWarm, 85);
  brush.fillBleed(0.02, "in");
  brush.fillTexture(0.58, 0.35);
  drawPolyShape(boot.outline, 0.08);
  brush.noFill();

  // Horizontal slices to build smooth 3D cylindrical + toe lighting foundation
  let yStep = 14;
  for (let y = boot.yTop + 8; y < boot.yBottom - 6; y += yStep) {
    let xL = evalProfileXAtY(boot.leftDense, y);
    let xR = evalProfileXAtY(boot.rightDense, y);
    let w = xR - xL;
    if (w < 12) continue;

    // Left sunlit strip
    let sunStrip = [
      [xL + 2, y],
      [xL + w * 0.42, y],
      [xL + w * 0.42, y + yStep + 2],
      [xL + 2, y + yStep + 2]
    ];
    brush.wash(PALETTE.feltHighlight, 135);
    drawPolyShape(sunStrip, 0.02);

    // Core shadow strip on right-center
    let shadowStrip = [
      [xL + w * 0.56, y],
      [xL + w * 0.88, y],
      [xL + w * 0.88, y + yStep + 2],
      [xL + w * 0.56, y + yStep + 2]
    ];
    brush.wash(PALETTE.feltShadow, 130);
    drawPolyShape(shadowStrip, 0.02);

    // Right edge cool snow-bounce strip
    let bounceStrip = [
      [xL + w * 0.85, y],
      [xR - 2, y],
      [xR - 2, y + yStep + 2],
      [xL + w * 0.85, y + yStep + 2]
    ];
    brush.wash(PALETTE.feltBounceBlue, 105);
    drawPolyShape(bounceStrip, 0.02);
  }
  brush.noWash();
}

function pickFeltPencilColor(surf, y, jitter = 0) {
  let l = constrain(surf.light + jitter, 0, 1);

  // Subtle environmental color reflections from the backdrop & snow
  if (random() < 0.09) {
    if (y < 380) return PALETTE.feltTurqTint;
    if (surf.u < -0.25 && y < 620) return PALETTE.feltBrickTint;
    if (surf.u > -0.2 && y < 620) return PALETTE.feltOchreTint;
    if (surf.snowBounce > 0.35) return PALETTE.feltBounceBlue;
  }

  if (l > 0.84) return PALETTE.feltCrackBright;
  if (l > 0.71) return PALETTE.feltHighlight;
  if (l > 0.59) return random() < 0.6 ? PALETTE.feltLightWarm : PALETTE.feltLightCool;
  if (l > 0.47) return PALETTE.feltMidLight;
  if (l > 0.35) return random() < 0.55 ? PALETTE.feltMid : PALETTE.feltMidWarm;
  if (l > 0.24) return random() < 0.5 ? PALETTE.feltDark : PALETTE.feltMidCool;
  if (l > 0.14) return surf.snowBounce > 0.3 ? PALETTE.feltBounceBlue : PALETTE.feltShadow;
  return random() < 0.65 ? PALETTE.feltDeepShadow : PALETTE.feltCrevice;
}

function renderBootColouredPencil(boot) {
  brush.noField();

  // --- PASS A: Patient Cross-Contour Coloured-Pencil Shading ---
  // Wraps around the cylindrical shaft, ankle flex, instep arch, and bulbous toe
  for (let y = boot.yTop + 8; y < boot.yBottom - 4; y += 3.4) {
    let xL = evalProfileXAtY(boot.leftDense, y);
    let xR = evalProfileXAtY(boot.rightDense, y);
    let span = xR - xL;
    if (span < 10) continue;

    let segCount = Math.floor(span / 16) + 2;
    for (let s = 0; s < segCount; s++) {
      let x1 = xL + 3 + random(0, span - 6);
      let y1 = y + random(-2.2, 2.2);
      if (!pointInPoly(x1, y1, boot.outline)) continue;

      let surf = evalBootSurface(boot, x1, y1);
      let strokeLen = random(14, 32);
      let ang = (surf.contourAngle + random(-14, 14)) * (Math.PI / 180);
      let dx = Math.cos(ang) * strokeLen * 0.5;
      let dy = Math.sin(ang) * strokeLen * 0.5 + (1 - Math.abs(surf.u)) * 3.2;

      let x0 = x1 - dx;
      let y0 = y1 - dy;
      let x2 = x1 + dx;
      let y2 = y1 + dy;

      if (!pointInPoly(x0, y0, boot.outline) || !pointInPoly(x2, y2, boot.outline)) continue;

      let col = pickFeltPencilColor(surf, y1, random(-0.08, 0.08));
      let bName = surf.light < 0.35 ? "2B" : "cpencil";
      let w = map(surf.light, 0, 1, 0.52, 0.32) * random(0.85, 1.15);

      brush.set(bName, col, w);
      brush.spline(
        [
          [x0, y0],
          [x1, y1 + 1.8],
          [x2, y2]
        ],
        0.35
      );
    }
  }

  // --- PASS B: Dense Matted Wool Fibres (Thousands of Interlocking Short Curved Hairs) ---
  // Non-woven felt has tangled, multi-directional curly sheep's wool fibres
  let minX = boot.id === "A" ? 250 : 558;
  let maxX = boot.id === "A" ? 568 : 900;
  let fiberCount = 2400;

  for (let i = 0; i < fiberCount; i++) {
    let x = random(minX, maxX);
    let y = random(boot.yTop + 6, boot.yBottom - 4);
    if (!pointInPoly(x, y, boot.outline)) continue;

    let surf = evalBootSurface(boot, x, y);

    // Tangled wool orientation: biased slightly along cross-contour, but with wild matted tangles
    let baseAng = surf.contourAngle + random(-75, 75);
    let rad1 = (baseAng * Math.PI) / 180;
    let rad2 = ((baseAng + random(-45, 45)) * Math.PI) / 180;
    let len = random(4.5, 13.5);

    let xm = x + Math.cos(rad1) * len * 0.5;
    let ym = y + Math.sin(rad1) * len * 0.5;
    let x2 = xm + Math.cos(rad2) * len * 0.5;
    let y2 = ym + Math.sin(rad2) * len * 0.5;

    if (!pointInPoly(x2, y2, boot.outline)) continue;

    // Pick wool fibre color: mix of local lit tone, raw dark sheep hairs, and bright silver wool knots
    let col;
    let r = random();
    if (r < 0.11) {
      // Raw dark sheep's wool guard hair fleck
      col = surf.light > 0.5 ? PALETTE.feltDark : PALETTE.feltCrevice;
    } else if (r < 0.24 && surf.light > 0.38) {
      // Luminous pale wool fibre catching low left winter sun
      col = surf.light > 0.65 ? PALETTE.feltCrackBright : PALETTE.feltHighlight;
    } else {
      col = pickFeltPencilColor(surf, y, random(-0.14, 0.14));
    }

    let bType = r < 0.35 ? "wool_pencil" : r < 0.75 ? "cpencil" : "2H";
    let weight = bType === "wool_pencil" ? random(0.22, 0.42) : random(0.24, 0.48);

    brush.set(bType, col, weight);
    brush.spline(
      [
        [x, y],
        [xm, ym],
        [x2, y2]
      ],
      0.55
    );
  }

  // --- PASS C: Extra Raking-Light Texture on Bulbous Toe & Sunlit Left Ridge ---
  for (let i = 0; i < 420; i++) {
    let y = random(boot.yTop + 10, boot.yBottom - 10);
    let xL = evalProfileXAtY(boot.leftDense, y);
    let xR = evalProfileXAtY(boot.rightDense, y);
    // Concentrate on sunlit left 45% and toe dome
    let t = Math.pow(random(), 1.6) * 0.55;
    let x = lerp(xL + 3, xR - 3, t);
    if (!pointInPoly(x, y, boot.outline)) continue;

    let surf = evalBootSurface(boot, x, y);
    if (surf.light < 0.48) continue;

    let col = surf.light > 0.72 ? PALETTE.feltCrackBright : PALETTE.feltHighlight;
    brush.set("fine_whisker", col, random(0.25, 0.45));
    let ang = random(-60, 60) * (Math.PI / 180);
    let l = random(4, 10);
    brush.line(x, y, x + Math.cos(ang) * l, y + Math.sin(ang) * l);
  }
}

// ============================================================================
// TOP FELT RIM & HOLLOW BOOT INTERIOR
// ============================================================================

function renderBootTopRimAndInterior(boot) {
  let { cx, cy, rx, ry, tilt } = boot.rim;
  let tiltRad = (tilt * Math.PI) / 180;

  function rimPt(rScaleX, rScaleY, angRad) {
    let ex = Math.cos(angRad) * rx * rScaleX;
    let ey = Math.sin(angRad) * ry * rScaleY;
    return [
      cx + ex * Math.cos(tiltRad) - ey * Math.sin(tiltRad),
      cy + ex * Math.sin(tiltRad) + ey * Math.cos(tiltRad)
    ];
  }

  let outerRing = [];
  let innerRing = [];
  let steps = 36;
  for (let i = 0; i < steps; i++) {
    let a = (i / steps) * Math.PI * 2;
    outerRing.push(rimPt(1.0, 1.0, a));
    innerRing.push(rimPt(0.84, 0.74, a));
  }

  // 1. Thick cut-felt top rim face (11px thick matted wool wall)
  brush.noField();
  brush.noStroke();
  brush.wash(PALETTE.feltLightWarm, 235);
  drawPolyShape(outerRing, 0.1);

  // 2. Hollow interior opening of the boot shaft
  brush.wash(PALETTE.feltDeepShadow, 245);
  drawPolyShape(innerRing, 0.1);

  // Right inner wall of the hollow shaft catches raking low-left sunlight
  let sunlitInnerCrescent = [];
  for (let i = -8; i <= 8; i++) {
    let a = (i / 8) * (Math.PI * 0.45);
    sunlitInnerCrescent.push(rimPt(0.83, 0.72, a));
  }
  for (let i = 8; i >= -8; i--) {
    let a = (i / 8) * (Math.PI * 0.45);
    let p = rimPt(0.42, 0.45, a);
    sunlitInnerCrescent.push([p[0] - 6, p[1] + 8]);
  }
  brush.wash(PALETTE.feltMidWarm, 185);
  drawPolyShape(sunlitInnerCrescent, 0.12);
  brush.noWash();

  // 3. Detailed coloured-pencil hatching inside the hollow opening and across the thick felt rim
  for (let i = 0; i < 180; i++) {
    let a = random(-Math.PI, Math.PI);
    let pIn1 = rimPt(random(0.1, 0.82), random(0.1, 0.7), a);
    let isRightSide = Math.cos(a) > 0.15;
    let col = isRightSide
      ? random() < 0.5 ? PALETTE.feltMid : PALETTE.feltDark
      : random() < 0.6 ? PALETTE.feltCrevice : PALETTE.feltDeepShadow;
    brush.set("cpencil", col, random(0.28, 0.5));
    let l = random(6, 15);
    brush.line(pIn1[0], pIn1[1], pIn1[0] + random(-2, 2), pIn1[1] + l * 0.45);
  }

  // Dense wool fibre stipples on the thick flat-cut top rim ring
  for (let i = 0; i < 220; i++) {
    let a = (i / 220) * Math.PI * 2 + random(-0.03, 0.03);
    let pOut = rimPt(random(0.95, 1.02), random(0.94, 1.03), a);
    let pIn = rimPt(random(0.82, 0.88), random(0.72, 0.8), a);
    let lightFactor = -Math.cos(a); // left side of rim is brightest
    let col =
      lightFactor > 0.25
        ? PALETTE.feltCrackBright
        : lightFactor > -0.25
        ? PALETTE.feltLightWarm
        : PALETTE.feltMid;
    brush.set("fine_whisker", col, random(0.24, 0.42));
    brush.line(pOut[0], pOut[1], pIn[0], pIn[1]);
  }

  // Crisp inner rim shadow lip
  brush.set("2B", PALETTE.feltCrevice, 0.48);
  for (let i = 0; i < steps; i++) {
    let p0 = innerRing[i];
    let p1 = innerRing[(i + 1) % steps];
    brush.line(p0[0], p0[1], p1[0], p1[1]);
  }
}

// ============================================================================
// PALE CRACKS WHERE THE FELT HAS CREASED (ANKLE & INSTEP FLEX ZONES)
// ============================================================================

function renderBootAnkleCracks(boot) {
  brush.noField();

  for (let c of boot.creases) {
    let steps = 42;
    // 1. Deepen the compression trough along the crease
    for (let i = 0; i < steps; i++) {
      let t0 = i / steps;
      let t1 = (i + 1) / steps;
      let [x0, y0] = evalQuadBezier(c.x0, c.y0, c.cx, c.cy, c.x1, c.y1, t0);
      let [x1, y1] = evalQuadBezier(c.x0, c.y0, c.cx, c.cy, c.x1, c.y1, t1);

      let surf = evalBootSurface(boot, x0, y0);
      let troughCol = surf.light > 0.45 ? PALETTE.feltDark : PALETTE.feltCrevice;
      brush.set("2B", troughCol, random(0.32, 0.55) * c.depth);
      brush.line(x0, y0 - 1.5, x1, y1 - 1.5);

      // Soft lower shadow transition
      brush.set("cpencil", PALETTE.feltShadow, 0.35 * c.depth);
      brush.line(x0, y0 - 4.5, x1, y1 - 4.5);
    }

    // 2. Render the signature PALE CRACK where the thick felt has creased & split
    if (c.hasPaleCrack) {
      let crackSteps = 55;
      for (let i = 0; i < crackSteps; i++) {
        let t = lerp(c.crackStartT, c.crackEndT, i / crackSteps);
        let tNext = lerp(c.crackStartT, c.crackEndT, (i + 1) / crackSteps);
        let [x0, y0] = evalQuadBezier(c.x0, c.y0, c.cx, c.cy, c.x1, c.y1, t);
        let [x1, y1] = evalQuadBezier(c.x0, c.y0, c.cx, c.cy, c.x1, c.y1, tNext);

        // Taper crack towards its ends
        let midEnv = Math.sin(((t - c.crackStartT) / (c.crackEndT - c.crackStartT)) * Math.PI);
        let jitterY = (noise(x0 * 0.08, y0 * 0.08) - 0.5) * 2.8;

        // a) Dark micro-fissure where felt surface split open
        brush.set("2B", PALETTE.feltCrevice, (0.28 + 0.25 * midEnv));
        brush.line(x0, y0 + jitterY, x1, y1 + jitterY);

        // b) Luminous PALE CRACK lip immediately below & inside the split (exposed unweathered inner wool)
        let paleCol = t < 0.65 ? PALETTE.feltCrackBright : PALETTE.feltHighlight;
        brush.set("fine_whisker", paleCol, 0.38 + 0.32 * midEnv);
        brush.line(x0, y0 + jitterY + 2.4, x1, y1 + jitterY + 2.4);

        brush.set("cpencil", PALETTE.feltCrackBright, 0.32 + 0.25 * midEnv);
        brush.line(x0, y0 + jitterY + 4.2, x1, y1 + jitterY + 4.2);

        // c) Tiny teased pale wool fibres bridging across the split crack
        if (random() < 0.75) {
          let fx = lerp(x0, x1, random());
          let fy = lerp(y0, y1, random()) + jitterY;
          let fLen = random(4, 9.5) * (0.4 + 0.6 * midEnv);
          let fAng = random(-75, 75) * (Math.PI / 180);
          brush.set("fine_whisker", PALETTE.feltCrackBright, random(0.22, 0.38));
          brush.line(
            fx - Math.sin(fAng) * 1.5,
            fy - 1.5,
            fx + Math.sin(fAng) * fLen * 0.6,
            fy + fLen
          );
        }
      }
    }
  }
}

// ============================================================================
// FUZZY BACKLIT SILHOUETTE WOOL HALO
// ============================================================================

function renderBootSilhouetteFuzz(boot) {
  brush.noField();

  // Left contour: catches bright low winter sunlight -> glowing pale cream wool fuzz
  for (let i = 0; i < boot.leftDense.length - 1; i++) {
    let [x0, y0] = boot.leftDense[i];
    let [x1, y1] = boot.leftDense[i + 1];
    let segLen = Math.hypot(x1 - x0, y1 - y0);
    let count = Math.max(2, Math.floor(segLen / 2.2));

    for (let k = 0; k < count; k++) {
      let t = (k + random()) / count;
      let px = lerp(x0, x1, t);
      let py = lerp(y0, y1, t);
      if (py > boot.yBottom - 16) continue;

      let ang = random(145, 225) * (Math.PI / 180);
      let len = random(3.5, 8.5);
      let col = random() < 0.7 ? PALETTE.feltCrackBright : PALETTE.feltHighlight;
      brush.set("fine_whisker", col, random(0.18, 0.34));
      brush.line(px + 1, py, px + Math.cos(ang) * len, py + Math.sin(ang) * len);
    }
  }

  // Right contour: crisp wool hairs against the ochre/red backdrop & snow shadow
  for (let i = 0; i < boot.rightDense.length - 1; i++) {
    let [x0, y0] = boot.rightDense[i];
    let [x1, y1] = boot.rightDense[i + 1];
    let segLen = Math.hypot(x1 - x0, y1 - y0);
    let count = Math.max(2, Math.floor(segLen / 2.6));

    for (let k = 0; k < count; k++) {
      let t = (k + random()) / count;
      let px = lerp(x0, x1, t);
      let py = lerp(y0, y1, t);
      if (py > boot.yBottom - 16) continue;

      let ang = random(-45, 45) * (Math.PI / 180);
      let len = random(3.0, 7.5);
      let col = random() < 0.5 ? PALETTE.feltMidCool : PALETTE.feltShadow;
      brush.set("fine_whisker", col, random(0.18, 0.32));
      brush.line(px - 1, py, px + Math.cos(ang) * len, py + Math.sin(ang) * len);
    }
  }
}

