function drawSingleSnowCrust(sc) {
  let { cx, cy, rx, ry, rot } = sc;
  let rotRad = (rot * Math.PI) / 180;
  let pts = [];
  let shadowPts = [];
  let steps = 18;

  for (let i = 0; i < steps; i++) {
    let a = (i / steps) * Math.PI * 2;
    let n = 0.72 + 0.48 * noise(cx * 0.05 + Math.cos(a) * 1.3, cy * 0.05 + Math.sin(a) * 1.3);
    let lx = Math.cos(a) * rx * n;
    let ly = Math.sin(a) * ry * n;
    let gx = cx + lx * Math.cos(rotRad) - ly * Math.sin(rotRad);
    let gy = cy + lx * Math.sin(rotRad) + ly * Math.cos(rotRad);
    pts.push([gx, gy]);
    shadowPts.push([gx + 2.2, gy + 3.0]);
  }

  // 1) Damp dark-felt occlusion rim underneath the snow crust
  brush.noStroke();
  brush.wash(PALETTE.feltCrevice, 155);
  drawPolyShape(shadowPts, 0.18);

  // 2) Snow crust body (sunlit left vs cool pastel blue shadow right)
  let isSunlitSide = (sc.boot.id === "A" && cx < 470) || (sc.boot.id === "B" && cx < 720);
  brush.wash(isSunlitSide ? PALETTE.snowBright : PALETTE.snowShadowLight, 235);
  drawPolyShape(pts, 0.18);
  brush.noWash();

  // 3) Crystalline snow granules & coloured-pencil highlights/shadows on the crust
  let grainCount = Math.floor((rx * ry) / 7);
  for (let i = 0; i < grainCount; i++) {
    let r = Math.sqrt(random()) * 0.95;
    let a = random(Math.PI * 2);
    let lx = Math.cos(a) * rx * r;
    let ly = Math.sin(a) * ry * r;
    let gx = cx + lx * Math.cos(rotRad) - ly * Math.sin(rotRad);
    let gy = cy + lx * Math.sin(rotRad) + ly * Math.cos(rotRad);

    // Left/top of each crust catches crisp white/cream winter light; right/bottom gets ice-blue shadow
    let localLit = -Math.cos(a + rotRad) * 0.65 - Math.sin(a + rotRad) * 0.35;
    let col;
    if (localLit > 0.15) {
      col = random() < 0.7 ? "#ffffff" : PALETTE.snowSun;
    } else if (localLit > -0.25) {
      col = PALETTE.snowMid;
    } else {
      col = random() < 0.6 ? PALETTE.snowShadowMid : PALETTE.snowCrevice;
    }

    brush.set("cpencil", col, random(0.28, 0.52));
    let gl = random(2.0, 5.5);
    let ga = random(-35, 35) * (Math.PI / 180);
    brush.line(gx, gy, gx + Math.cos(ga) * gl, gy + Math.sin(ga) * gl);
  }

  // 4) Individual stray snow grains clinging to wool fibres just outside the crust
  for (let i = 0; i < 16; i++) {
    let a = random(Math.PI * 2);
    let distScale = random(0.95, 1.48);
    let gx = cx + Math.cos(a) * rx * distScale;
    let gy = cy + Math.sin(a) * ry * distScale - random(0, 8);
    let col = gx < cx ? "#ffffff" : PALETTE.snowShadowLight;
    brush.set("fine_whisker", col, random(0.32, 0.55));
    brush.line(gx, gy, gx + random(-2.5, 2.5), gy + random(-2, 2));
  }
}

