// ============================================================================
// ANATOMICAL PARAMETRIC GEOMETRY (FOREARM, WRIST, HAND, CUFF)
// ============================================================================

// u in [0, 1] spans from cuff exit (x=175) to wrist ulnar head (x=850)
function armX(u) {
  return lerp(175, 850, u);
}

// Upper (radial/brachioradialis) contour of the forearm
function armTopY(u) {
  let base = lerp(458, 554, u);
  // Swell of brachioradialis muscle belly near u=0.26, slight dip before radial styloid
  let muscleSwell = -34 * Math.sin(Math.pow(u, 0.78) * Math.PI) * Math.exp(-1.4 * u);
  let wristTaper = 10 * Math.sin(u * Math.PI * 2.0) * Math.pow(u, 1.3);
  let skinWave = 3.5 * Math.sin(u * 19 + 0.6) * Math.pow(u, 0.5);
  return base + muscleSwell + wristTaper + skinWave;
}

// Lower (ulnar) contour resting on the tabletop
function armBotY(u) {
  let base = lerp(816, 744, u);
  // Loose sagging skin along proximal ulnar border, tightening toward ulnar head
  let sag = 38 * Math.sin(u * Math.PI * 0.92) * Math.exp(-1.1 * u);
  // Prominent ulnar head near wrist (u ~ 0.92)
  let ulnarHead = 11 * Math.exp(-Math.pow((u - 0.93) / 0.07, 2));
  let microFold = 2.8 * Math.sin(u * 27 + 1.2);
  return base + sag + ulnarHead + microFold;
}

// Map (u, v) on forearm surface to canvas (x, y) and 3D cylindrical normal
// v in [0, 1]: 0 = top radial ridge, 1 = bottom ulnar edge on table
function armSurface(u, v) {
  let x = armX(u);
  let topY = armTopY(u);
  let botY = armBotY(u);
  let h = botY - topY;
  // Slight cylindrical longitudinal bow along the cross-section
  let crossCurve = Math.sin(v * Math.PI) * (18 * (1 - 0.35 * u));
  let y = lerp(topY, botY, v);
  // z represents relative height above table (0 at edges, 1 at dorsal crest v~0.38)
  let z = Math.sin( clamp01(Math.pow(v, 0.85)) * Math.PI );
  return { x: x + crossCurve * 0.25, y, topY, botY, h, z };
}

function clamp01(val) {
  return Math.max(0, Math.min(1, val));
}

// Hand & fingers coordinate mapper for u > 1.0 (x from 850 to 1145)
function handTopY(t) {
  // t in [0, 1] from wrist (850) to knuckles/curled fingers (1135)
  let base = lerp(554, 618, t);
  let knucklearch = -16 * Math.sin(t * Math.PI) + 12 * Math.pow(t, 2.5);
  return base + knucklearch;
}

function handBotY(t) {
  let base = lerp(744, 808, t);
  let thumbSwell = 34 * Math.sin(t * Math.PI * 0.88);
  return base + thumbSwell;
}

// ============================================================================
// DRAWING HELPERS
// ============================================================================

function fillPoly(pts, col, alpha, bleed = 0.15, tex = 0.42, border = 0.25, curv = 0.25) {
  if (!pts || pts.length < 3) return;
  brush.noField();
  brush.noStroke();
  brush.noHatch();
  brush.noMass();
  brush.fill(col, alpha);
  brush.fillBleed(bleed, "out");
  brush.fillTexture(tex, border);
  brush.beginShape(curv);
  for (let i = 0; i < pts.length; i++) {
    brush.vertex(pts[i][0], pts[i][1]);
  }
  brush.endShape(true);
  brush.noFill();
}

function washPoly(pts, col, alpha, curv = 0.2) {
  if (!pts || pts.length < 3) return;
  brush.noField();
  brush.noStroke();
  brush.noFill();
  brush.noHatch();
  brush.wash(col, alpha);
  brush.beginShape(curv);
  for (let i = 0; i < pts.length; i++) {
    brush.vertex(pts[i][0], pts[i][1]);
  }
  brush.endShape(true);
  brush.noWash();
}

function ribbonBandPoints(uStart, uEnd, vTopFn, vBotFn, steps = 24) {
  let pts = [];
  for (let i = 0; i <= steps; i++) {
    let u = lerp(uStart, uEnd, i / steps);
    let p = armSurface(u, vTopFn(u));
    pts.push([p.x, p.y]);
  }
  for (let i = steps; i >= 0; i--) {
    let u = lerp(uStart, uEnd, i / steps);
    let p = armSurface(u, vBotFn(u));
    pts.push([p.x, p.y]);
  }
  return pts;
}

// ============================================================================
// MAIN RENDER PIPELINE
// ============================================================================

function draw() {
  translate(-width / 2, -height / 2);
  background(PAL.paper);
  brush.noField();

  // 1. Ambient paper & tabletop washes (washed denim grey-blues & warm chalk)
  drawBackgroundAndTabletop();

  // 2. Deep cast shadow of the resting forearm, cuff, and hand on the tabletop
  drawTableCastShadow();

  // 3. Watercolor base & anatomical planes of the forearm, wrist, and hand
  drawForearmWatercolorBase();

  // 4. The decades-old sailor tattoo (Swallow & Anchor) blurred into dermis
  drawAgedSailorTattoo();

  // 5. Over-tattoo skin veil, freckles (solar lentigines), and mottled sun-worn tan
  drawSkinFrecklesAndMottling();

  // 6. Twill-weave contour crosshatching across the forearm, wrist, and hand
  drawTwillContourCrosshatching();

  // 7. Loose skin wrinkles, rhomboid micro-creases, wrist folds, and knuckles
  drawWrinklesAndSkinFolds();

  // 8. Raised subcutaneous veins (crossing over the aged tattoo & wrist)
  drawRaisedVeins();

  // 9. Rolled faded denim shirt cuff on the left
  drawRolledDenimCuff();

  // 10. Hyperreal silver hairs, follicle roots, and bleached skin highlights
  drawSilverHairsAndSpeculars();

  noLoop();
}

