}

// ============================================================================
// 2. TABLE CAST SHADOW
// ============================================================================

function drawTableCastShadow() {
  // Broad soft penumbra in grey-blue denim
  let penumbra = [];
  for (let i = 0; i <= 24; i++) {
    let u = i / 24;
    let p = armSurface(u, 0.94);
    penumbra.push([p.x, p.y - 6]);
  }
  penumbra.push([960, 745], [1145, 785], [1155, 865], [960, 885], [560, 925], [180, 935], [40, 905], [40, 795]);
  fillPoly(penumbra, PAL.denimSoft, 68, 0.42, 0.55, 0.2, 0.25);

  // Mid-shadow under forearm and wrist
  let midShadow = [];
  for (let i = 0; i <= 24; i++) {
    let u = i / 24;
    let p = armSurface(u, 0.98);
    midShadow.push([p.x, p.y - 2]);
  }
  midShadow.push([940, 755], [1135, 800], [1130, 838], [920, 845], [520, 885], [190, 890], [50, 865], [50, 810]);
  fillPoly(midShadow, PAL.denimMid, 82, 0.32, 0.5, 0.3, 0.25);

  // Deep chalky-indigo umbra right beneath ulnar contact line
  let coreShadow = [];
  for (let i = 0; i <= 24; i++) {
    let u = i / 24;
    let p = armSurface(u, 1.0);
    coreShadow.push([p.x, p.y - 1]);
  }
  coreShadow.push([930, 765], [1115, 808], [1105, 824], [890, 805], [510, 856], [210, 855], [70, 840], [70, 815]);
  fillPoly(coreShadow, PAL.denimDeep, 95, 0.2, 0.45, 0.35, 0.2);

  // Warm bounce reflection inside the cast shadow from the sun-worn skin
  let bouncePts = [
    [220, 828], [520, 838], [810, 775], [810, 812], [520, 865], [220, 858]
  ];
  fillPoly(bouncePts, PAL.skinUmber, 42, 0.3, 0.4, 0.2, 0.25);

  // Twill cross-hatching in the cast shadow to tie table & arm together
  for (let i = 0; i < 140; i++) {
    let u = random(-0.08, 1.28);
    let x, yTop, yBot;
    if (u < 0) {
      x = map(u, -0.08, 0, 70, 175);
      yTop = 815;
      yBot = 885;
    } else if (u <= 1.0) {
      let p = armSurface(u, 1.0);
      x = p.x;
      yTop = p.y - 2;
      yBot = p.y + map(Math.sin(u * Math.PI), 0, 1, 38, 72);
    } else {
      let ht = map(u, 1.0, 1.28, 0, 1);
      x = lerp(850, 1130, ht);
      yTop = handBotY(ht) - 4;
      yBot = yTop + lerp(42, 24, ht);
    }
    let y1 = random(yTop, lerp(yTop, yBot, 0.5));
    let len = random(18, 48);
    let ang = random(-12, 16);
    brush.set("twill_needle", i % 2 === 0 ? PAL.denimDeep : PAL.denimDark, random(0.45, 0.85));
    brush.line(x, y1, x + len * cos(ang), y1 + len * sin(ang));
  }
}

