// Helper to convert local tattoo coords into curved forearm surface coords
function tattooPt(u, v) {
  let p = armSurface(u, v);
  // Subtle skin-crease warp so ink follows dermal undulations
  let warpX = 2.2 * Math.sin(u * 42 + v * 14);
  let warpY = 2.8 * Math.cos(u * 36 - v * 19);
  return [p.x + warpX, p.y + warpY];
}

// Draw a blurred, sub-dermal tattoo stroke (simulating 50 years of macrophage ink migration)
function drawBlurredTattooSpline(pts, coreColor, weight = 1.0) {
  if (pts.length < 2) return;
  // Pass 1: Wide pale indigo dispersion halo
  for (let pass = 0; pass < 3; pass++) {
    let haloPts = pts.map(p => [
      p[0] + random(-5.5, 5.5),
      p[1] + random(-5.5, 5.5)
    ]);
    brush.set("dermal_soft", PAL.indigoHalo, weight * 1.35);
    brush.spline(haloPts, 0.35);
  }
  // Pass 2: Mid faded chalky indigo blur
  for (let pass = 0; pass < 3; pass++) {
    let midPts = pts.map(p => [
      p[0] + random(-2.6, 2.6),
      p[1] + random(-2.6, 2.6)
    ]);
    brush.set("dermal_soft", PAL.indigoFade, weight * 1.05);
    brush.spline(midPts, 0.35);
  }
  // Pass 3: Broken deep slate-indigo core in the dermis
  let corePts = pts.map(p => [
    p[0] + random(-1.1, 1.1),
    p[1] + random(-1.1, 1.1)
  ]);
  brush.set("charcoal", coreColor, weight * 0.72);
  brush.spline(corePts, 0.35);
}

