// ============================================================================
// 5. OVER-TATTOO SKIN VEIL, FRECKLES (SOLAR LENTIGINES) & MOTTLING
// ============================================================================

function drawSkinFrecklesAndMottling() {
  // Translucent warm epidermis wash over the tattoo so the ink sits UNDER the skin
  let epidermisVeil = ribbonBandPoints(0.20, 0.80, (u) => 0.12, (u) => 0.78, 20);
  fillPoly(epidermisVeil, PAL.skinBase, 46, 0.25, 0.35, 0.1, 0.25);

  // Sun-worn tan mottling patches across the dorsal forearm and back of hand
  let mottleCenters = [
    { u: 0.18, v: 0.28, r: 26, col: PAL.skinTan, a: 48 },
    { u: 0.29, v: 0.22, r: 22, col: PAL.skinWeather, a: 42 },
    { u: 0.44, v: 0.38, r: 30, col: PAL.skinTan, a: 45 },
    { u: 0.56, v: 0.25, r: 24, col: PAL.skinWeather, a: 44 },
    { u: 0.68, v: 0.42, r: 28, col: PAL.skinTan, a: 46 },
    { u: 0.79, v: 0.32, r: 25, col: PAL.skinWeather, a: 50 },
    { u: 0.89, v: 0.48, r: 22, col: PAL.skinTan, a: 48 }
  ];

  for (let m of mottleCenters) {
    let c = armSurface(m.u, m.v);
    let pts = [];
    for (let a = 0; a < 360; a += 45) {
      let rad = m.r * random(0.7, 1.3);
      pts.push([c.x + rad * cos(a) * 1.3, c.y + rad * sin(a) * 0.85]);
    }
    fillPoly(pts, m.col, m.a, 0.35, 0.5, 0.2, 0.4);
  }

  // Larger solar lentigines (age spots / sun freckles) with organic irregular borders
  for (let i = 0; i < 42; i++) {
    let u = random(0.06, 1.18);
    let v = random(0.08, 0.78);
    let cx, cy;
    if (u <= 1.0) {
      let p = armSurface(u, v);
      cx = p.x;
      cy = p.y;
    } else {
      let ht = map(u, 1.0, 1.18, 0, 0.85);
      cx = lerp(850, 1085, ht);
      cy = lerp(handTopY(ht), handBotY(ht), v);
    }
    let rx = random(3.5, 9.5);
    let ry = rx * random(0.55, 0.85) * (1 - 0.35 * Math.abs(v - 0.4));
    let spotPts = [];
    for (let a = 0; a < 360; a += 60) {
      let rMod = random(0.75, 1.25);
      spotPts.push([cx + rx * rMod * cos(a), cy + ry * rMod * sin(a)]);
    }
    let col = random() < 0.55 ? PAL.skinWeather : PAL.skinUmber;
    washPoly(spotPts, col, random(45, 95), 0.35);
  }

  // Hundreds of fine sun freckles & pigment macules rendered with cpencil & dermal_soft
  for (let i = 0; i < 620; i++) {
    let u = random(0.04, 1.22);
    // Concentrate freckles on the sun-exposed dorsal/radial surface (v in 0.06 .. 0.72)
    let v = clamp01(randomGaussian(0.36, 0.20));
    let cx, cy;
    if (u <= 1.0) {
      let p = armSurface(u, v);
      cx = p.x;
      cy = p.y;
    } else {
      let ht = clamp01(map(u, 1.0, 1.22, 0, 0.92));
      cx = lerp(850, 1105, ht);
      cy = lerp(handTopY(ht) + 8, handBotY(ht) - 8, v);
    }

    let col = random() < 0.5 ? PAL.skinTan : (random() < 0.7 ? PAL.skinWeather : PAL.skinUmber);
    let sz = random(1.2, 4.2);
    let ang = random(5, 35);
    brush.set("cpencil", col, random(0.45, 0.95));
    brush.line(cx, cy, cx + sz * cos(ang), cy + sz * sin(ang));
    if (random() < 0.35) {
      brush.set("dermal_soft", col, random(0.4, 0.75));
      brush.line(cx - 1, cy + 0.8, cx + sz * 0.8, cy - 0.5);
    }
  }
}

// ============================================================================
// 6. TWILL-WEAVE CONTOUR CROSSHATCHING
// ============================================================================

function drawTwillContourCrosshatching() {
  // Like the diagonal ribs of washed denim twill (/// and \\\ wrapping around the 3D cylinder),
  // fine crosshatching sculpts the topography of the muscle bellies, bones, and loose skin.

  let uSteps = 76;
  let vSteps = 26;

  for (let iu = 0; iu < uSteps; iu++) {
    let u0 = (iu + random(-0.25, 0.25)) / uSteps;
    u0 = clamp01(u0);

    for (let iv = 0; iv < vSteps; iv++) {
      let v0 = (iv + random(-0.25, 0.25)) / vSteps;
      v0 = clamp01(v0);

      let p0 = armSurface(u0, v0);

      // Compute twill weave rib direction that wraps around the forearm contour
      // Near top (v->0) and bottom (v->1), strokes foreshorten and align more with longitudinal edge
      let wrapAngle = map(v0, 0, 1, -28, 38);
      let twillShift = ((iu + iv) % 3 === 0) ? 18 : -16;

      let du = 0.022;
      let dv = 0.048 * Math.sin((wrapAngle + twillShift) * Math.PI / 180);

      let u1 = clamp01(u0 + du * 0.5);
      let v1 = clamp01(v0 + dv * 0.5);
      let u2 = clamp01(u0 + du);
      let v2 = clamp01(v0 + dv);

      let p1 = armSurface(u1, v1);
      let p2 = armSurface(u2, v2);

      // Select color from the washed-denim + sun-worn tan palette based on 3D lighting (v0)
      let col;
      let wt = random(0.32, 0.68);

      // Check if over tattoo to blend indigo & skin twill
      let inTattoo = (dist(u0, v0, 0.61, 0.51) < 0.14 || dist(u0, v0, 0.35, 0.33) < 0.12);

      if (v0 < 0.22) {
        // Sunlit radial ridge: bleached white & pale tan
        col = random() < 0.6 ? PAL.bleached : PAL.skinTan;
        wt *= 0.85;
      } else if (v0 < 0.55) {
        // Dorsal sun-worn plane
        if (inTattoo && random() < 0.42) {
          col = random() < 0.5 ? PAL.indigoFade : PAL.indigoHalo;
        } else {
          col = random() < 0.55 ? PAL.skinTan : (random() < 0.5 ? PAL.skinWeather : PAL.skinLight);
        }
      } else if (v0 < 0.78) {
        // Core shadow turn: weathered tan meeting washed denim grey-blue
        col = random() < 0.5 ? PAL.skinWeather : PAL.denimMid;
        wt *= 1.08;
      } else {
        // Lower ulnar shadow & reflected table light
        col = random() < 0.55 ? PAL.denimDeep : (random() < 0.6 ? PAL.denimMid : PAL.skinUmber);
        wt *= 1.15;
      }

      brush.set("twill_needle", col, wt);
      brush.spline([[p0.x, p0.y], [p1.x, p1.y], [p2.x, p2.y]], 0.3);

      // Secondary counter-twill crosshatch in midtones and shadows (creating rhomboid Langer's mesh)
      if (v0 > 0.32 || random() < 0.35) {
        let cv1 = clamp01(v0 - dv * 0.45);
        let cv2 = clamp01(v0 - dv * 0.9);
        let cp1 = armSurface(u1, cv1);
        let cp2 = armSurface(u2, cv2);
        let crossCol = v0 > 0.65 ? PAL.denimMid : (v0 < 0.28 ? PAL.skinLight : PAL.skinTan);
        brush.set("twill_needle", crossCol, wt * 0.82);
        brush.spline([[p0.x, p0.y], [cp1.x, cp1.y], [cp2.x, cp2.y]], 0.3);
      }
    }
  }

  // Twill contour crosshatching extending over the wrist, back of hand, thumb, and knuckles
  for (let i = 0; i < 420; i++) {
    let t = random(0.0, 0.98);
    let v = random(0.04, 0.96);
    let x0 = lerp(845, 1130, t);
    let yTop = handTopY(t);
    let yBot = handBotY(t);
    let y0 = lerp(yTop, yBot, v);

    let ang = map(v, 0, 1, -22, 34) + (i % 2 === 0 ? 14 : -14);
    let len = random(12, 26);
    let x1 = x0 + len * cos(ang);
    let y1 = y0 + len * sin(ang);

    let col;
    if (v < 0.28) col = random() < 0.5 ? PAL.bleached : PAL.skinTan;
    else if (v < 0.68) col = random() < 0.5 ? PAL.skinWeather : PAL.skinTan;
    else col = random() < 0.55 ? PAL.denimMid : PAL.skinUmber;

    brush.set("twill_needle", col, random(0.35, 0.68));
    brush.line(x0, y0, x1, y1);
  }
}

// ============================================================================
// 7. LOOSE SKIN WRINKLES, RHOMBOID CREASES, WRIST FOLDS & HAND DETAILS
// ============================================================================

function drawWrinklesAndSkinFolds() {
  // 1. Sagging longitudinal/oblique folds of loose aged skin along the lower forearm & elbow crook
  for (let i = 0; i < 38; i++) {
    let uStart = random(0.02, 0.78);
    let uEnd = clamp01(uStart + random(0.08, 0.22));
    let vBase = random(0.56, 0.95);
    let ptsShadow = [];
    let ptsLight = [];
    let steps = 8;
    for (let s = 0; s <= steps; s++) {
      let st = s / steps;
      let u = lerp(uStart, uEnd, st);
      let v = clamp01(vBase + 0.04 * Math.sin(st * Math.PI) + 0.03 * st);
      let p = armSurface(u, v);
      ptsShadow.push([p.x, p.y]);
      ptsLight.push([p.x, p.y - 2.2]);
    }
    brush.set("2H", vBase > 0.78 ? PAL.denimDeep : PAL.skinUmber, random(0.38, 0.65));
    brush.spline(ptsShadow, 0.35);
    brush.set("twill_needle", PAL.skinLight, random(0.35, 0.55));
    brush.spline(ptsLight, 0.35);
  }

  // 2. Transverse wrist flexion/extension creases & skin folds around the ulnar head (u = 0.82 .. 1.02)
  for (let i = 0; i < 28; i++) {
    let uCenter = random(0.83, 1.01);
    let vStart = random(0.08, 0.55);
    let vEnd = clamp01(vStart + random(0.22, 0.42));
    let creasePts = [];
    let ridgePts = [];
    for (let s = 0; s <= 6; s++) {
      let st = s / 6;
      let v = lerp(vStart, vEnd, st);
      let u = uCenter + 0.018 * Math.sin(st * Math.PI * 1.5);
      let p = armSurface(clamp01(u), v);
      let xOff = u > 1.0 ? (u - 1.0) * 650 : 0;
      creasePts.push([p.x + xOff, p.y]);
      ridgePts.push([p.x + xOff - 1.8, p.y - 1.2]);
    }
    brush.set("HB", PAL.skinUmber, random(0.35, 0.62));
    brush.spline(creasePts, 0.35);
    brush.set("twill_needle", PAL.bleached, random(0.4, 0.65));
    brush.spline(ridgePts, 0.35);
  }

  // 3. Extensor tendons & weathered knuckles on the back of the hand
  let tendonPaths = [
    [[848, 576], [925, 582], [1005, 594], [1068, 612]],
    [[845, 602], [932, 614], [1018, 632], [1092, 658]],
    [[842, 636], [930, 652], [1012, 678], [1085, 708]],
    [[846, 678], [918, 704], [985, 738], [1038, 772]] // extensor pollicis longus to thumb
  ];

  for (let tPath of tendonPaths) {
    // Tendon sunlit ridge
    brush.set("dermal_soft", PAL.bleached, 1.15);
    brush.spline(tPath, 0.3);
    // Tendon lower shadow edge
    let shadowPath = tPath.map(pt => [pt[0] - 2, pt[1] + 5.5]);
    brush.set("dermal_soft", PAL.skinWeather, 0.95);
    brush.spline(shadowPath, 0.3);
    // Tendon upper cool groove
    let groovePath = tPath.map(pt => [pt[0] + 1, pt[1] - 4.5]);
    brush.set("2H", PAL.denimMid, 0.45);
    brush.spline(groovePath, 0.3);
  }

  // Knuckle concentric skin wrinkles & finger joint creases
  let knuckles = [
    { x: 1058, y: 612, r: 16 },
    { x: 1082, y: 656, r: 18 },
    { x: 1076, y: 706, r: 17 },
    { x: 992,  y: 742, r: 16 }, // thumb joint
    { x: 838,  y: 708, r: 22 }  // prominent ulnar styloid head
  ];

  for (let k of knuckles) {
    for (let w = 0; w < 7; w++) {
      let a1 = random(-75, -15);
      let a2 = a1 + random(55, 110);
      let rad = k.r * random(0.45, 1.15);
      let arcPts = [];
      for (let a = a1; a <= a2; a += 20) {
        arcPts.push([k.x + rad * cos(a) * 0.85, k.y + rad * sin(a) * 1.1]);
      }
      brush.set("2H", PAL.skinUmber, random(0.35, 0.6));
      brush.spline(arcPts, 0.35);
      let hiPts = arcPts.map(p => [p[0] - 1.5, p[1] - 1.2]);
      brush.set("twill_needle", PAL.bleached, 0.45);
      brush.spline(hiPts, 0.35);
    }
  }

  // Thumbnail on the resting thumb in lower right foreground
  let nailPts = [
    [1018, 762], [1042, 774], [1044, 794], [1020, 796], [1012, 778]
  ];
  fillPoly(nailPts, PAL.bleached, 120, 0.1, 0.25, 0.2, 0.25);
  brush.set("2H", PAL.skinUmber, 0.5);
  brush.spline([[1042, 774], [1018, 762], [1012, 778], [1020, 796]], 0.3);
  // Longitudinal ridges on aged thumbnail
  brush.set("twill_needle", PAL.bleached, 0.55);
  brush.line(1018, 768, 1040, 780);
  brush.line(1016, 775, 1038, 787);

  // Crisp yet soft anatomical boundary contour of the forearm and hand
  let topContour = [];
  for (let i = 0; i <= 32; i++) {
    let p = armSurface(i / 32, 0.0);
    topContour.push([p.x, p.y]);
  }
  brush.set("2H", PAL.skinWeather, 0.55);
  brush.spline(topContour, 0.3);

  let botContour = [];
  for (let i = 0; i <= 32; i++) {
    let p = armSurface(i / 32, 1.0);
    botContour.push([p.x, p.y]);
  }
  brush.set("HB", PAL.denimDark, 0.72);
  brush.spline(botContour, 0.3);
}

// ============================================================================
// 8. RAISED SUBCUTANEOUS VEINS (SUPERFICIAL VENOUS NETWORK)
// ============================================================================

// Renders a raised, three-dimensional subcutaneous vein with dermal blue core,
// lower shadow trough, upper specular skin crest, and cross-contour twill wraps
function drawSingleVein(uvPoints, baseWidth = 6.5) {
  let canvasPts = [];
  for (let i = 0; i < uvPoints.length; i++) {
    let u = uvPoints[i][0];
    let v = uvPoints[i][1];
    if (u <= 1.0) {
      let p = armSurface(u, v);
      canvasPts.push([p.x, p.y, v]);
    } else {
      let ht = clamp01(map(u, 1.0, 1.25, 0, 1));
      let x = lerp(850, 1110, ht);
      let y = lerp(handTopY(ht), handBotY(ht), v);
      canvasPts.push([x, y, v]);
    }
  }

  // Interpolate smooth high-res path with organic venous tortuosity
  let dense = [];
  let steps = 28;
  for (let i = 0; i < canvasPts.length - 1; i++) {
    let pA = canvasPts[i];
    let pB = canvasPts[i + 1];
    for (let s = 0; s < steps; s++) {
      if (i > 0 && s === 0) continue;
      let t = s / (steps - 1);
      let x = lerp(pA[0], pB[0], t);
      let y = lerp(pA[1], pB[1], t);
      let v = lerp(pA[2], pB[2], t);
      let wave = Math.sin((i * steps + s) * 0.45) * (baseWidth * 0.28);
      dense.push([x + wave * 0.25, y + wave, v]);
    }
  }

  // 1. Sub-dermal blue-grey venous core wash
  let veinPoly = [];
  for (let i = 0; i < dense.length; i++) {
    let taper = Math.sin(map(i, 0, dense.length - 1, 0.15, 0.85) * Math.PI);
    let w = baseWidth * (0.55 + 0.45 * taper);
    veinPoly.push([dense[i][0], dense[i][1] - w * 0.48]);
  }
  for (let i = dense.length - 1; i >= 0; i--) {
    let taper = Math.sin(map(i, 0, dense.length - 1, 0.15, 0.85) * Math.PI);
    let w = baseWidth * (0.55 + 0.45 * taper);
    veinPoly.push([dense[i][0], dense[i][1] + w * 0.52]);
  }
  fillPoly(veinPoly, PAL.veinBlue, 54, 0.22, 0.4, 0.15, 0.25);

  // 2. Lower shadow edge of the raised vein ridge
  let lowerShadow = dense.map((pt, idx) => {
    let taper = Math.sin(map(idx, 0, dense.length - 1, 0.15, 0.85) * Math.PI);
    let w = baseWidth * (0.5 + 0.5 * taper);
    return [pt[0], pt[1] + w * 0.55];
  });
  brush.set("dermal_soft", PAL.skinUmber, baseWidth * 0.16);
  brush.spline(lowerShadow, 0.35);
  brush.set("2H", PAL.denimDeep, baseWidth * 0.09);
  brush.spline(lowerShadow, 0.35);

  // 3. Soft blue-slate inner core stroke
  let coreLine = dense.map(pt => [pt[0], pt[1] + 0.6]);
  brush.set("dermal_soft", PAL.denimMid, baseWidth * 0.18);
  brush.spline(coreLine, 0.35);

  // 4. Warm skin-tone dome over the vein
  let skinDome = dense.map(pt => [pt[0], pt[1] - 0.8]);
  brush.set("dermal_soft", PAL.skinBase, baseWidth * 0.15);
  brush.spline(skinDome, 0.35);

  // 5. Crisp sunlit highlight along the top crest of the raised vein
  let upperHighlight = dense.map((pt, idx) => {
    let taper = Math.sin(map(idx, 0, dense.length - 1, 0.15, 0.85) * Math.PI);
    let w = baseWidth * (0.45 + 0.55 * taper);
    return [pt[0], pt[1] - w * 0.38];
  });
  brush.set("twill_needle", PAL.bleached, baseWidth * 0.14);
  brush.spline(upperHighlight, 0.35);

  // 6. Micro cross-contour hatches wrapping up and over the vein
  for (let i = 2; i < dense.length - 2; i += 2) {
    let pt = dense[i];
    let w = baseWidth * 0.85;
    brush.set("twill_needle", i % 4 === 0 ? PAL.bleached : PAL.skinTan, 0.42);
    brush.spline([
      [pt[0] - 3, pt[1] - w * 0.65],
      [pt[0] + 1, pt[1] - w * 0.15],
      [pt[0] - 2, pt[1] + w * 0.65]
    ], 0.4);
  }
}

function drawRaisedVeins() {
  // Prominent Cephalic / Accessory Cephalic vein sweeping across the dorsal forearm,
  // passing right over the Swallow's lower wing and Anchor stock/shank toward the wrist & hand!
  drawSingleVein([
    [0.04, 0.36],
    [0.18, 0.33],
    [0.33, 0.38], // crosses swallow body/wing
    [0.49, 0.44], // crosses anchor ring/stock
    [0.66, 0.39], // crosses upper anchor shank
    [0.83, 0.35],
    [0.98, 0.38],
    [1.14, 0.42]  // dorsal metacarpal vein on hand
  ], 7.5);

  // Tributary vein branching from upper radial border into main cephalic vein
  drawSingleVein([
    [0.14, 0.16],
    [0.26, 0.22],
    [0.38, 0.29], // passes across swallow neck
    [0.49, 0.44]
  ], 5.2);

  // Lower Median/Basilic tributary crossing the lower fluke of the anchor toward the ulnar head
  drawSingleVein([
    [0.22, 0.68],
    [0.41, 0.64],
    [0.58, 0.58], // crosses lower anchor stock & shank
    [0.74, 0.63],
    [0.90, 0.66],
    [1.06, 0.64]
  ], 6.4);

  // Anastomosing bridge vein on mid-forearm connecting the upper and lower veins over the anchor
  drawSingleVein([
    [0.49, 0.44],
    [0.54, 0.52],
    [0.58, 0.58]
  ], 4.8);

  // Branching dorsal venous arch on the back of the hand
  drawSingleVein([
    [0.83, 0.35],
    [0.94, 0.24],
    [1.08, 0.26],
    [1.18, 0.32]
  ], 5.0);

  drawSingleVein([
    [0.98, 0.38],
    [1.05, 0.52],
    [1.15, 0.58]
  ], 4.6);
}

