    if (x > 185 && (y < 455 || y > 825)) continue;
    let isLower = y > 660;
    let col = isLower
      ? (random() < 0.6 ? PAL.denimDark : PAL.denimMid)
      : (random() < 0.45 ? PAL.denimMid : (random() < 0.5 ? PAL.bleached : PAL.denimDeep));
    let ang = (i % 4 === 0) ? -42 : 48; // classic right-hand denim twill angle
