// ============================================================================
// 10. SILVER HAIRS, FOLLICLES & BLEACHED SPECULAR SKIN GLINTS
// ============================================================================

function drawSilverHairsAndSpeculars() {
  // Sparse, luminous silver and bleached-white hairs sweeping in natural streams
  // from the radial-dorsal ridge down and toward the wrist/ulnar edge.

  let totalHairs = 340;
  for (let i = 0; i < totalHairs; i++) {
    // Distribute across forearm (u = 0.03 .. 0.98) and back of hand (u = 0.98 .. 1.14)
    let u = random(0.03, 1.14);
    // Hairs are densest on dorsal and lateral surfaces (v = 0.04 .. 0.86)
    let v = random(0.03, 0.88);

    let rootX, rootY;
    if (u <= 1.0) {
      let p = armSurface(u, v);
      rootX = p.x;
      rootY = p.y;
    } else {
      let ht = map(u, 1.0, 1.14, 0, 0.65);
      rootX = lerp(850, 1020, ht);
      rootY = lerp(handTopY(ht) + 10, handBotY(ht) - 18, v);
    }

    // Tiny follicle pore shadow at the base of the hair
    brush.set("2H", v > 0.65 ? PAL.denimDeep : PAL.skinUmber, random(0.4, 0.7));
    brush.line(rootX, rootY, rootX + 1.8, rootY + 1.2);

    // Natural hair-stream flow angle (sweeping toward ulnar border and wrist)
    let streamAngle = map(v, 0, 1, 22, 46) + 8 * Math.sin(u * 12) + random(-14, 14);
    // Hairs near the top radial contour or bottom ulnar contour project slightly beyond the silhouette!
    if (v < 0.09) streamAngle = random(-28, 12);
    if (v > 0.82) streamAngle = random(18, 52);

    let hairLen = random(18, 42) * (u > 0.95 ? 0.68 : 1.0);
    let curveBend = random(-18, 22);

    let midX = rootX + (hairLen * 0.52) * cos(streamAngle);
    let midY = rootY + (hairLen * 0.52) * sin(streamAngle);
    let tipX = midX + (hairLen * 0.48) * cos(streamAngle + curveBend);
    let tipY = midY + (hairLen * 0.48) * sin(streamAngle + curveBend);

    // Subtle dark-silver underside shadow of hair shaft for hyperreal contrast over pale skin
    let underCol = v < 0.35 ? PAL.denimSoft : PAL.denimMid;
    brush.set("twill_needle", underCol, random(0.28, 0.48));
    brush.spline([
      [rootX, rootY + 0.9],
      [midX, midY + 0.9],
      [tipX, tipY + 0.9]
    ], 0.35);

    // Luminous silver / bleached-white hair shaft catching raking light
    let hairCol = random() < 0.68 ? PAL.bleached : PAL.silver;
    let hairWt = random(0.45, 0.92);
    brush.set("silver_hair", hairCol, hairWt);
    brush.spline([
      [rootX, rootY],
      [midX, midY],
      [tipX, tipY]
    ], 0.35);
  }

  // Fine specular skin micro-highlights along rhomboid skin crests & radial bone ridge
  for (let i = 0; i < 190; i++) {
    let u = random(0.05, 1.08);
    let v = random(0.04, 0.45);
    let sx, sy;
    if (u <= 1.0) {
      let p = armSurface(u, v);
      sx = p.x;
      sy = p.y;
    } else {
      let ht = map(u, 1.0, 1.08, 0, 0.45);
      sx = lerp(850, 975, ht);
      sy = lerp(handTopY(ht) + 6, handBotY(ht) - 30, v);
    }
    let len = random(4, 11);
    let ang = random(-15, 25);
    brush.set("silver_hair", PAL.bleached, random(0.35, 0.65));
    brush.line(sx, sy, sx + len * cos(ang), sy + len * sin(ang));
  }
}

// Hyperreal Mackerel on a Hinoki Board over Katazome Stencilled Ground
// p5.js 2.x + p5.brush (WEBGL)

const SEED = 4279;

// Board geometry in canvas space [0..1200, 0..1200]
const BOARD = {
  cx: 600,
  cy: 600,
  w: 960,
  h: 530,
  angle: -20 // degrees
};

async function setup() {
  createCanvas(1200, 1200, WEBGL);
  angleMode(DEGREES);
  randomSeed(SEED);
  noiseSeed(SEED);

  // Register custom brushes before scaling so they scale proportionally
  brush.add("kata_rinse", {
    type: "default",
    weight: 1.8,
    scatter: 0.4,
    sharpness: 0.25,
    grain: 0.65,
    opacity: 48,
    spacing: 0.28,
    pressure: [0.6, 1.15, 0.5],
    rotate: "natural"
  });

  brush.add("fine_pen", {
    type: "default",
    weight: 0.35,
    scatter: 0.02,
    sharpness: 0.94,
    grain: 0.08,
    opacity: 235,
    spacing: 0.1,
    pressure: [0.5, 1.2, 0.4],
    rotate: "natural"
  });

  brush.add("glaze_soft", {
    type: "marker",
    weight: 3.8,
    scatter: 0.12,
    opacity: 26,
    spacing: 0.22,
    pressure: [0.7, 1.1, 0.7],
    markerTip: false,
    rotate: "natural"
  });

  brush.add("cloth_slub", {
    type: "default",
    weight: 0.55,
    scatter: 0.45,
    sharpness: 0.48,
    grain: 0.85,
    opacity: 62,
    spacing: 0.32,
    pressure: [0.4, 1.0, 0.4],
    rotate: "natural"
  });

  brush.scaleBrushes(3);
}

function draw() {
  translate(-width / 2, -height / 2);

  // Warm unbleached asa (hemp/ramie) paste-resist base cloth
  background("#ede0c8");

  // 1. Katazome dyed cloth ground & repeating stencilled wave pattern (Seigaiha)
  drawKatazomeGround();
  drawStencilledWaves();
  drawClothWeaveOverlay();

  // 2. Hinoki wooden cutting board (Manaita) with cast shadow, end-grain, and mokume wood grain
  drawBoardShadow();
  drawWoodenBoard();

  // 3. Damp moisture halos and water droplets on the board beneath the fish
  drawBoardMoisture();

  // 4. Two fresh mackerel lying head to tail
  // Fish 1: Upper position, head facing top-left, tail fork toward bottom-right
  const fish1 = createMackerelRig({
    bx0: -380, by0: -78,
    bx1: 258,  by1: -96,
    archAmp: -18,
    archPhase: -10,
    dorsalSign: -1, // dorsal tiger-striped back on upper (-y) side, silver-green belly on lower (+y) side
    bodyWidthScale: 1.02,
    seedOffset: 100
  });

  // Fish 2: Lower position, head facing bottom-right, tail fork toward top-left (head-to-tail)
  const fish2 = createMackerelRig({
    bx0: 380,  by0: 82,
    bx1: -258, by1: 96,
    archAmp: -18,
    archPhase: -14,
    dorsalSign: -1, // rotated 180 deg so its dorsal back frames the lower (+y) side and bellies gleam in center
    bodyWidthScale: 1.0,
    seedOffset: 500
  });

  drawMackerelShadow(fish1);
  drawMackerelShadow(fish2);

  drawMackerel(fish1);
  drawMackerel(fish2);

  // 5. Final water droplets & wet specular surface glints
  drawSurfaceDroplets(fish1, fish2);

  noLoop();
}

// ============================================================================
// GEOMETRY & DRAWING UTILITIES
// ============================================================================

function boardToWorld(bx, by) {
  const c = cos(BOARD.angle);
  const s = sin(BOARD.angle);
  return [
    BOARD.cx + bx * c - by * s,
    BOARD.cy + bx * s + by * c
  ];
}

function worldToBoard(wx, wy) {
  const dx = wx - BOARD.cx;
  const dy = wy - BOARD.cy;
  const c = cos(-BOARD.angle);
  const s = sin(-BOARD.angle);
  return [
    dx * c - dy * s,
    dx * s + dy * c
  ];
}

function isDeepInsideBoard(wx, wy, margin = 42) {
  const [bx, by] = worldToBoard(wx, wy);
  return (
    Math.abs(bx) < BOARD.w / 2 - margin &&
    Math.abs(by) < BOARD.h / 2 - margin
  );
}

function drawWashPoly(pts, col, op, curvature = 0) {
  if (!pts || pts.length < 3) return;
  brush.noStroke();
  brush.noFill();
  brush.noHatch();
  brush.wash(col, op);
  brush.beginShape(curvature);
  for (let i = 0; i < pts.length; i++) {
    brush.vertex(pts[i][0], pts[i][1]);
  }
  brush.endShape(true);
  brush.noWash();
}

function drawFillPoly(pts, col, op, bleed = 0.18, tex = 0.55, border = 0.45, curvature = 0.2) {
  if (!pts || pts.length < 3) return;
  brush.noStroke();
  brush.noWash();
  brush.noHatch();
  brush.fill(col, op);
  brush.fillBleed(bleed, "out");
  brush.fillTexture(tex, border);
  brush.beginShape(curvature);
  for (let i = 0; i < pts.length; i++) {
    brush.vertex(pts[i][0], pts[i][1]);
  }
  brush.endShape(true);
  brush.noFill();
}

function makeBlobPoly(cx, cy, rx, ry, nPts = 16, irr = 0.18, rotDeg = 0) {
  const pts = [];
  const c = cos(rotDeg);
  const s = sin(rotDeg);
  const nOff = random(1000);
  for (let i = 0; i < nPts; i++) {
    const a = (i / nPts) * 360;
    const nv = noise(nOff + cos(a) * 1.3, nOff + sin(a) * 1.3);
    const rScale = 1 + (nv - 0.5) * 2 * irr;
    const lx = cos(a) * rx * rScale;
    const ly = sin(a) * ry * rScale;
    pts.push([cx + lx * c - ly * s, cy + lx * s + ly * c]);
  }
  return pts;
}

// ============================================================================
// 1. KATAZOME CLOTH GROUND & STENCILLED WAVE PATTERN (SEIGAIHA)
// ============================================================================

function drawKatazomeGround() {
  // Persimmon rust (kaki-iro / bengara) watercolor dye washes
  const rustZones = [
    [220, 210, 340, 280, "#9e361b", 145],
    [950, 220, 360, 290, "#a83e21", 140],
    [240, 960, 380, 300, "#8f2c14", 150],
    [960, 940, 350, 310, "#a33a1e", 145],
    [600, 160, 420, 210, "#b84b29", 125],
    [610, 1040, 440, 220, "#963117", 135],
    [130, 580, 240, 360, "#ab4122", 130],
    [1070, 590, 250, 370, "#852610", 140]
  ];

  for (const [cx, cy, rx, ry, col, op] of rustZones) {
    const poly = makeBlobPoly(cx, cy, rx, ry, 18, 0.25, random(-30, 30));
    drawFillPoly(poly, col, op, 0.32, 0.68, 0.42, 0.3);
  }

  // Soot black (sumi-iro) watercolor dye pools
  const sootZones = [
    [120, 130, 270, 240, "#1c1816", 160],
    [1080, 140, 260, 230, "#211c19", 150],
    [140, 1070, 290, 240, "#181513", 165],
    [1060, 1060, 280, 250, "#1e1a17", 160],
    [420, 90, 240, 150, "#241f1c", 135],
    [790, 1110, 260, 160, "#221d1a", 140],
    [70, 460, 160, 250, "#1b1715", 145],
    [1130, 740, 170, 260, "#1c1816", 145]
  ];

  for (const [cx, cy, rx, ry, col, op] of sootZones) {
    const poly = makeBlobPoly(cx, cy, rx, ry, 16, 0.28, random(-25, 25));
    drawFillPoly(poly, col, op, 0.28, 0.72, 0.5, 0.3);
  }
}

function drawStencilledWaves() {
  // Repeating katazome Seigaiha (imbricated ocean waves) with paste-resist arcs,
  // softened rinsed edges, stencil tie-bridges (tsunagi), and foam dots (arare).
  const R = 90;
  const dx = 152;
  const dy = 72;
  const tilt = 5; // subtle hand-laid fabric angle

  const cT = cos(tilt);
  const sT = sin(tilt);
  const toGridWorld = (gx, gy) => [
    600 + (gx - 600) * cT - (gy - 600) * sT,
    600 + (gx - 600) * sT + (gy - 600) * cT
  ];

  for (let row = -2; row <= 18; row++) {
    const gyBase = row * dy - 30;
    const xShift = (row % 2 !== 0) ? dx * 0.5 : 0;

    for (let col = -1; col <= 9; col++) {
      const gxBase = col * dx + xShift - 40;
      const [wcx, wcy] = toGridWorld(gxBase, gyBase);

      // Skip wave fans completely buried under the central wooden board
      if (isDeepInsideBoard(wcx, wcy, 58)) continue;

      // Slight hand-stencilled registration jitter
      const jx = (noise(row * 0.7, col * 0.7) - 0.5) * 9;
      const jy = (noise(col * 0.7 + 30, row * 0.7 + 30) - 0.5) * 9;
      const cx = wcx + jx;
      const cy = wcy + jy;
      const rotWobble = tilt + (noise(row * 1.3, col * 1.3) - 0.5) * 6;

      // Determine local dye dominance (persimmon rust vs soot black)
      const dyeN = noise(cx * 0.0028, cy * 0.0028);
      const isSootHeavy = dyeN > 0.51;

      drawSingleKatazomeWave(cx, cy, R, rotWobble, isSootHeavy, row, col);
    }
  }
}

function makeArcBandPoly(cx, cy, rInner, rOuter, aStart, aEnd, steps = 16) {
  const pts = [];
  for (let i = 0; i <= steps; i++) {
    const a = lerp(aStart, aEnd, i / steps);
    const jitter = (noise(cx * 0.02 + i * 0.3, cy * 0.02) - 0.5) * 1.8;
    pts.push([cx + cos(a) * (rOuter + jitter), cy + sin(a) * (rOuter + jitter)]);
  }
  for (let i = steps; i >= 0; i--) {
    const a = lerp(aStart, aEnd, i / steps);
    const jitter = (noise(cy * 0.02 + i * 0.3, cx * 0.02) - 0.5) * 1.8;
    pts.push([cx + cos(a) * (rInner + jitter), cy + sin(a) * (rInner + jitter)]);
  }
  return pts;
}

function drawSingleKatazomeWave(cx, cy, R, rotWobble, isSootHeavy, row, col) {
  const a0 = -176 + rotWobble;
  const a1 = -4 + rotWobble;

  // 1. Dyed backing fan for this wave unit
  const fanPts = [];
  const fanSteps = 18;
  for (let i = 0; i <= fanSteps; i++) {
    const a = lerp(a0 - 4, a1 + 4, i / fanSteps);
    fanPts.push([cx + cos(a) * (R + 2), cy + sin(a) * (R + 2)]);
  }
  fanPts.push([cx + cos(a1 + 4) * (R * 0.35), cy + 28]);
  fanPts.push([cx + cos(a0 - 4) * (R * 0.35), cy + 28]);

  const baseDye = isSootHeavy
    ? (random() < 0.6 ? "#1b1715" : "#28211e")
    : (random() < 0.6 ? "#993419" : "#b04324");
  drawWashPoly(fanPts, baseDye, 195, 0.1);

  // Secondary dye richness band
  const innerDye = isSootHeavy ? "#8c2e15" : "#1e1917";
  const midBand = makeArcBandPoly(cx, cy, R * 0.44, R * 0.72, a0, a1, 14);
  drawWashPoly(midBand, innerDye, 150, 0.08);

  // 2. Concentric paste-resist arcs (flat resist shapes with stencil tie-bridges & rinsed edges)
  const radii = [
    [R * 0.87, R * 0.96],
    [R * 0.67, R * 0.76],
    [R * 0.47, R * 0.56],
    [R * 0.27, R * 0.36],
    [R * 0.09, R * 0.17]
  ];

  for (let b = 0; b < radii.length; b++) {
    const [rIn, rOut] = radii[b];
    // Split each resist arc into 2 or 3 stencil segments separated by small tsunagi bridges
    const nSegs = b < 2 ? 3 : 2;
    const bridgeGap = 5.5 + b * 1.4;
    const span = (a1 - a0) / nSegs;

    for (let s = 0; s < nSegs; s++) {
      const sa0 = a0 + s * span + (s === 0 ? 2 : bridgeGap * 0.5);
      const sa1 = a0 + (s + 1) * span - (s === nSegs - 1 ? 2 : bridgeGap * 0.5);
      if (sa1 <= sa0 + 4) continue;

      const segPts = makeArcBandPoly(cx, cy, rIn, rOut, sa0, sa1, 8);

      // Softened rinsed halo around the paste-resist cutout
      const rinseCol = b % 2 === 0 ? "#d99d73" : "#c77d52";
      drawWashPoly(segPts, rinseCol, 95, 0.12);

      // Crisp inner paste-resist shape in warm cloth cream
      const insetPts = makeArcBandPoly(cx, cy, rIn + 1.1, rOut - 1.1, sa0 + 0.8, sa1 - 0.8, 8);
      const resistCol = (b + s) % 2 === 0 ? "#efe2cb" : "#e3d1b4";
      drawWashPoly(insetPts, resistCol, 225, 0.06);
    }

    // Softened rinsed edge stroke along the arc
    const rMid = (rIn + rOut) * 0.5;
    brush.set("kata_rinse", isSootHeavy ? "#362721" : "#6e2310", 0.55);
    brush.arc(cx, cy, rMid, a0 + 6, a1 - 6);
  }

  // 3. Stencilled radial wave-rib ticks between arcs & arare (foam) resist dots at crest
  brush.set("cpencil", "#efe3cc", 0.52);
  const nDots = 7;
  for (let d = 0; d < nDots; d++) {
    const da = lerp(a0 + 18, a1 - 18, d / (nDots - 1)) + random(-2.5, 2.5);
    const dr = R * 0.99 + random(-2, 2.5);
    const dxDot = cx + cos(da) * dr;
    const dyDot = cy + sin(da) * dr;
    const dotPoly = makeBlobPoly(dxDot, dyDot, 2.8, 2.5, 7, 0.15, da);
    drawWashPoly(dotPoly, "#f2e6d0", 230, 0.1);
  }
}

function drawClothWeaveOverlay() {
  // Subtle woven textile threads (warp & weft slubs) across the visible katazome border
  const step = 11;
  for (let y = 10; y < 1190; y += step) {
    if (y > 290 && y < 910) {
      // Left and right strips outside the board center
      brush.set("cloth_slub", y % 22 === 0 ? "#f2e5ce" : "#261c18", 0.35);
      brush.line(8, y + random(-1.5, 1.5), 240 + random(-20, 20), y + random(-1.5, 1.5));
      brush.line(960 + random(-20, 20), y + random(-1.5, 1.5), 1192, y + random(-1.5, 1.5));
    } else {
      brush.set("cloth_slub", y % 22 === 0 ? "#f2e5ce" : "#381c12", 0.35);
      brush.line(8, y + random(-1.5, 1.5), 1192, y + random(-1.5, 1.5));
    }
  }

  for (let x = 14; x < 1190; x += 15) {
    const col = x % 30 < 15 ? "#211916" : "#ead9be";
    brush.set("cloth_slub", col, 0.3);
    if (x > 240 && x < 960) {
      brush.line(x + random(-1, 1), 8, x + random(-1, 1), 270);
      brush.line(x + random(-1, 1), 930, x + random(-1, 1), 1192);
    } else {
      brush.line(x + random(-1, 1), 8, x + random(-1, 1), 1192);
    }
  }
}

// ============================================================================
// 2. HINOKI WOODEN BOARD (MANAITA)
// ============================================================================

function getBoardCornerPts(dxWorld = 0, dyWorld = 0, inset = 0) {
  const hw = BOARD.w / 2 - inset;
  const hh = BOARD.h / 2 - inset;
  const ch = 12; // subtle chamfered corners of a crafted hinoki board
  const localCorners = [
    [-hw + ch, -hh],
    [hw - ch, -hh],
    [hw, -hh + ch],
    [hw, hh - ch],
    [hw - ch, hh],
    [-hw + ch, hh],
    [-hw, hh - ch],
    [-hw, -hh + ch]
  ];
  return localCorners.map(([bx, by]) => {
    const [wx, wy] = boardToWorld(bx, by);
    return [wx + dxWorld, wy + dyWorld];
  });
}

function drawBoardShadow() {
  // Deep cast shadow on the katazome cloth from the thick board and its underside geta cleats
  const sh1 = getBoardCornerPts(28, 42, -6);
  drawFillPoly(sh1, "#120f0e", 185, 0.35, 0.65, 0.35, 0.12);

  const sh2 = getBoardCornerPts(17, 26, -2);
  drawFillPoly(sh2, "#191412", 215, 0.2, 0.5, 0.4, 0.08);

  const sh3 = getBoardCornerPts(9, 14, 0);
  drawWashPoly(sh3, "#0f0d0c", 220, 0.04);
}

function drawWoodenBoard() {
  const hw = BOARD.w / 2;
  const hh = BOARD.h / 2;
  const ch = 12;

  // 1. 3D Side Thickness & End-Grain of the Board (extruded by dx=12, dy=20)
  const ex = 12;
  const ey = 20;

  // Bottom bevel face
  const botEdgeLocal = [
    [-hw, hh - ch],
    [-hw + ch, hh],
    [hw - ch, hh],
    [hw, hh - ch]
  ];
  const botFacePts = [
    ...botEdgeLocal.map(([bx, by]) => boardToWorld(bx, by)),
    ...botEdgeLocal.slice().reverse().map(([bx, by]) => {
      const [wx, wy] = boardToWorld(bx, by);
      return [wx + ex, wy + ey];
    })
  ];
  drawWashPoly(botFacePts, "#7d4d25", 245, 0.02);
  drawFillPoly(botFacePts, "#593416", 130, 0.1, 0.55, 0.5, 0.02);

  // Right end-grain face
  const rightEdgeLocal = [
    [hw - ch, -hh],
    [hw, -hh + ch],
    [hw, hh - ch],
    [hw - ch, hh]
  ];
  const rightFacePts = [
    ...rightEdgeLocal.map(([bx, by]) => boardToWorld(bx, by)),
    ...rightEdgeLocal.slice().reverse().map(([bx, by]) => {
      const [wx, wy] = boardToWorld(bx, by);
      return [wx + ex, wy + ey];
    })
  ];
  drawWashPoly(rightFacePts, "#633a1a", 245, 0.02);

  // End-grain vertical growth ring striations on right face and bottom edge
  brush.set("2B", "#3d210c", 0.45);
  for (let by = -hh + 14; by <= hh - 14; by += 8) {
    const [x1, y1] = boardToWorld(hw, by);
    brush.line(x1, y1, x1 + ex, y1 + ey);
  }
  brush.set("cpencil", "#9c683b", 0.4);
  for (let bx = -hw + 20; bx <= hw - 20; bx += 22) {
    const [x1, y1] = boardToWorld(bx, hh);
    brush.line(x1, y1, x1 + ex * 0.9, y1 + ey * 0.9);
  }

  // 2. Top Surface of the Hinoki Cutting Board
  const topPts = getBoardCornerPts(0, 0, 0);
  drawWashPoly(topPts, "#dfc090", 252, 0.02);
  drawWashPoly(getBoardCornerPts(0, 0, 3), "#e7cc9f", 210, 0.02);

  // Warm watercolor wood tones & heartwood bands across the board
  const plankBands = [
    [-260, -165, "#d1a168", 110],
    [-165, -45,  "#e8cfa4", 95],
    [-45,  75,   "#c99559", 115],
    [75,   185,  "#e3c494", 95],
    [185,  260,  "#cf9d63", 115]
  ];
  for (const [y0, y1, col, op] of plankBands) {
    const bPts = [
      boardToWorld(-hw + 8, y0),
      boardToWorld(hw - 8, y0 + random(-8, 8)),
      boardToWorld(hw - 8, y1 + random(-8, 8)),
      boardToWorld(-hw + 8, y1)
    ];
    drawFillPoly(bPts, col, op, 0.14, 0.48, 0.3, 0.05);
  }

  // 3. Detailed Mokume (Wood Grain Cathedrals & Straight Quarter-Sawn Lines)
  const grainColors = ["#b57e46", "#9c6430", "#f2dec0", "#824e20", "#cfa06b"];
  for (let i = 0; i < 115; i++) {
    const byBase = map(i, 0, 114, -hh + 10, hh - 10);
    const col = grainColors[i % grainColors.length];
    const w = (i % 5 === 0) ? 0.52 : 0.34;
    brush.set(i % 4 === 0 ? "2H" : "cpencil", col, w);

    const pts = [];
    const steps = 26;
    // Cathedral arch centers at (-160, -35) and (190, 65)
    for (let s = 0; s <= steps; s++) {
      const bx = lerp(-hw + 10, hw - 10, s / steps);
      const d1 = (bx + 160) / 220;
      const d2 = (bx - 190) / 240;
      const wave =
        sin(bx * 0.008 + byBase * 0.03) * 7 +
        exp(-d1 * d1 * 2.2) * sin((byBase + 35) * 0.08) * 14 +
        exp(-d2 * d2 * 2.0) * cos((byBase - 65) * 0.07) * 12 +
        (noise(bx * 0.01, byBase * 0.025) - 0.5) * 6;
      const by = constrain(byBase + wave, -hh + 6, hh - 6);
      pts.push(boardToWorld(bx, by));
    }
    brush.spline(pts, 0.4);
  }

  // Subtle wood knots (fushi) near the corners of the board
  const knots = [
    [-370, -195, 16, 9],
    [355, -180, 14, 8],
    [-290, 210, 18, 10]
  ];
  for (const [kx, ky, krx, kry] of knots) {
    const [wx, wy] = boardToWorld(kx, ky);
    const kPoly = makeBlobPoly(wx, wy, krx, kry, 12, 0.12, BOARD.angle);
    drawWashPoly(kPoly, "#8a5224", 170, 0.2);
    const kCore = makeBlobPoly(wx, wy, krx * 0.5, kry * 0.5, 10, 0.1, BOARD.angle);
    drawWashPoly(kCore, "#4a270d", 210, 0.2);
  }

  // 4. Fine culinary knife-score marks (hocho-ato) in the central cutting area
  for (let i = 0; i < 65; i++) {
    const bx = random(-360, 360);
    const by = random(-185, 185);
    const len = random(35, 130);
    const ang = random(72, 108) + (random() < 0.25 ? random(-35, 35) : 0);
    const dx = cos(ang) * len * 0.5;
    const dy = sin(ang) * len * 0.5;
    const p1 = boardToWorld(bx - dx, constrain(by - dy, -hh + 12, hh - 12));
    const p2 = boardToWorld(bx + dx, constrain(by + dy, -hh + 12, hh - 12));

    brush.set("fine_pen", i % 2 === 0 ? "#f5e4c8" : "#9e6937", 0.28);
    brush.line(p1[0], p1[1], p2[0], p2[1]);
  }

  // 5. Crisp bevel highlight along top & left board edges, dark rim along bottom & right
  const topLeftRim = [
    boardToWorld(-hw, hh - ch),
    boardToWorld(-hw, -hh + ch),
    boardToWorld(-hw + ch, -hh),
    boardToWorld(hw - ch, -hh)
  ];
  brush.set("cpencil", "#f7ead2", 0.75);
  brush.spline(topLeftRim, 0.05);

  const botRightRim = [
    boardToWorld(hw - ch, -hh),
    boardToWorld(hw, -hh + ch),
    boardToWorld(hw, hh - ch),
    boardToWorld(hw - ch, hh),
    boardToWorld(-hw + ch, hh),
    boardToWorld(-hw, hh - ch)
  ];
  brush.set("2B", "#472810", 0.65);
  brush.spline(botRightRim, 0.05);
}

function drawBoardMoisture() {
  // Damp darkened hinoki wood patches where the wet mackerel rest
  const dampZones = [
    [-65, -88, 365, 84, "#9c6735", 85],
    [65,   90, 365, 84, "#9c6735", 85],
    [-90, -82, 290, 58, "#7a4a21", 75],
    [90,   86, 290, 58, "#7a4a21", 75],
    [0,     0, 210, 68, "#b3804c", 60]
  ];

  for (const [bx, by, rx, ry, col, op] of dampZones) {
    const [wx, wy] = boardToWorld(bx, by);
    const poly = makeBlobPoly(wx, wy, rx, ry, 20, 0.16, BOARD.angle);
    drawFillPoly(poly, col, op, 0.24, 0.55, 0.35, 0.25);
  }
}

// ============================================================================
// 3. MACKEREL ANATOMICAL RIG & HYPERREAL + KATAZOME RENDERING
// ============================================================================

function evalProfile(t, table) {
  if (t <= table[0][0]) return table[0][1];
  if (t >= table[table.length - 1][0]) return table[table.length - 1][1];
  for (let i = 0; i < table.length - 1; i++) {
    const [t0, v0] = table[i];
    const [t1, v1] = table[i + 1];
    if (t >= t0 && t <= t1) {
      const u = (t - t0) / (t1 - t0);
      const su = u * u * (3 - 2 * u); // smoothstep
      return lerp(v0, v1, su);
    }
  }
  return 0;
}

const DORSAL_PROFILE = [
  [0.00, 0.0],
  [0.02, 8.5],
  [0.06, 22.0],
  [0.11, 36.5],
  [0.18, 53.0],
  [0.25, 65.5],
  [0.36, 73.5],
  [0.48, 69.0],
  [0.60, 55.0],
  [0.72, 36.0],
  [0.83, 19.0],
  [0.91, 10.8], // narrow mackerel caudal wrist
  [0.95, 10.2],
  [1.00, 15.5]
];

const VENTRAL_PROFILE = [
  [0.00, 0.0],
  [0.02, 9.5],
  [0.06, 24.0],
  [0.12, 41.5],
  [0.20, 60.0],
  [0.29, 73.0],
  [0.40, 77.5],
  [0.52, 70.5],
  [0.64, 53.0],
  [0.75, 33.0],
  [0.84, 18.0],
  [0.91, 10.8],
  [0.95, 10.2],
  [1.00, 15.5]
];

function createMackerelRig(cfg) {
  const { bx0, by0, bx1, by1, archAmp, archPhase, dorsalSign, bodyWidthScale, seedOffset } = cfg;

  const dx = bx1 - bx0;
  const dy = by1 - by0;
  const len = Math.hypot(dx, dy);
  const ux = dx / len;
  const uy = dy / len;
  const nx = -uy;
  const ny = ux;

  // Spine point in board local coordinates for t in [-0.05 .. 1.25]
  function spineLocal(t) {
    const bx = bx0 + ux * (t * len);
    const by = by0 + uy * (t * len);
    const arch = archAmp * sin(t * 195 + archPhase) * sin(constrain(t, 0, 1.15) * 155);
    return [bx + nx * arch, by + ny * arch];
  }

  // Point on fish at longitudinal station t and cross-sectional coordinate s:
  // s = -1.0 is the Dorsal Ridge (tiger-striped back edge)
  // s =  0.0 is the Spine Centerline
  // s = +1.0 is the Ventral Ridge (silver-green belly edge)
  function pt(t, s, extraPx = 0) {
    const eps = 0.004;
    const [cx, cy] = spineLocal(t);
    const [cx2, cy2] = spineLocal(t + eps);
    const tx = cx2 - cx;
    const ty = cy2 - cy;
    const tl = Math.hypot(tx, ty) || 1;
    const lnx = (-ty / tl) * dorsalSign;
    const lny = (tx / tl) * dorsalSign;

    const dW = evalProfile(constrain(t, 0, 1), DORSAL_PROFILE) * bodyWidthScale;
    const vW = evalProfile(constrain(t, 0, 1), VENTRAL_PROFILE) * bodyWidthScale;
    const halfW = s < 0 ? dW : vW;
    const dist = s * halfW + (s < 0 ? -extraPx : extraPx);

    const bx = cx + lnx * dist;
    const by = cy + lny * dist;
    return boardToWorld(bx, by);
  }

  // Raw offset in pixels along dorsal (-px) or ventral (+px) normal
  function ptPx(t, signedPx) {
    const eps = 0.004;
    const [cx, cy] = spineLocal(t);
    const [cx2, cy2] = spineLocal(t + eps);
    const tx = cx2 - cx;
    const ty = cy2 - cy;
    const tl = Math.hypot(tx, ty) || 1;
    const lnx = (-ty / tl) * dorsalSign;
    const lny = (tx / tl) * dorsalSign;

    const bx = cx + lnx * signedPx;
    const by = cy + lny * signedPx;
    return boardToWorld(bx, by);
  }

  return { pt, ptPx, seedOffset, dorsalSign, bodyWidthScale };
}

function buildStripPoly(rig, t0, t1, sTopFn, sBotFn, steps = 28) {
  const pts = [];
  for (let i = 0; i <= steps; i++) {
    const t = lerp(t0, t1, i / steps);
    pts.push(rig.pt(t, typeof sTopFn === "function" ? sTopFn(t) : sTopFn));
  }
  for (let i = steps; i >= 0; i--) {
    const t = lerp(t0, t1, i / steps);
    pts.push(rig.pt(t, typeof sBotFn === "function" ? sBotFn(t) : sBotFn));
  }
  return pts;
}

function drawMackerelShadow(rig) {
  // Cast shadow of the mackerel body & tail fork onto the damp hinoki board
  const shx = 12;
  const shy = 19;

  const bodyPts = buildStripPoly(rig, 0.0, 1.0, -0.96, 1.02, 36).map(([x, y]) => [x + shx, y + shy]);
  drawFillPoly(bodyPts, "#26170c", 165, 0.26, 0.58, 0.4, 0.15);

  const corePts = buildStripPoly(rig, 0.02, 0.98, -0.7, 0.96, 30).map(([x, y]) => [x + shx * 0.55, y + shy * 0.55]);
  drawWashPoly(corePts, "#170e07", 195, 0.12);

  // Tail fin shadow
  const tailShPts = getTailFinOutline(rig).map(([x, y]) => [x + shx * 0.85, y + shy * 0.85]);
  drawFillPoly(tailShPts, "#24160b", 150, 0.2, 0.5, 0.35, 0.1);
}

function getTailFinOutline(rig) {
  return [
    rig.ptPx(0.95, -11),
    rig.ptPx(1.01, -24),
    rig.ptPx(1.09, -50),
    rig.ptPx(1.175, -72), // sharp upper caudal lobe tip
    rig.ptPx(1.185, -67),
    rig.ptPx(1.12, -35),
    rig.ptPx(1.055, -2),  // deep central V-fork notch
    rig.ptPx(1.12, 33),
    rig.ptPx(1.18, 65),   // sharp lower caudal lobe tip
    rig.ptPx(1.17, 70),
    rig.ptPx(1.09, 48),
    rig.ptPx(1.01, 23),
    rig.ptPx(0.95, 11)
  ];
}

function drawMackerel(rig) {
  randomSeed(SEED + rig.seedOffset);
  noiseSeed(SEED + rig.seedOffset);

  // 1. Dorsal, Ventral, Pelvic, Caudal Fins & Finlets (drawn just behind body contour)
  drawMackerelExteriorFins(rig);

  // 2. Base Body Silhouette & Glazed Watercolor Belly / Dorsal Underpainting
  drawMackerelBodyGlazes(rig);

  // 3. Katazome + Hyperreal Tiger-Striped Back (Saba-Gara Vermiculations)
  drawMackerelTigerStripes(rig);

  // 4. Lateral Line, Myomere Muscle Chevrons & Micro-Scale Shimmer
  drawMackerelScaleAndLateralDetail(rig);

  // 5. Head, Cranial Plates, Metallic Gill Cover (Operculum), Jaw & Glassy Wet Eye
  drawMackerelHeadAndEye(rig);

  // 6. Translucent Pectoral Fin overlapping the anterior flank
  drawMackerelPectoralFin(rig);

  // 7. Crisp White Pen Highlights & Wet Mucous Specular Streaks
  drawMackerelPenHighlights(rig);
}

function drawMackerelExteriorFins(rig) {
  // --- A. First Spiny Dorsal Fin (t = 0.265 .. 0.455) ---
  const d1Pts = [
    rig.pt(0.265, -0.96, 0),
    rig.pt(0.285, -1.0, 26),
    rig.pt(0.305, -1.0, 42),
    rig.pt(0.335, -1.0, 35),
    rig.pt(0.375, -1.0, 22),
    rig.pt(0.415, -1.0, 11),
    rig.pt(0.455, -0.96, 0)
  ];
  drawWashPoly(d1Pts, "#2c3d40", 175, 0.12);
  drawFillPoly(d1Pts, "#4f6b6e", 110, 0.12, 0.45, 0.4, 0.1);

  // Spiny rays of first dorsal fin
  const nD1Rays = 12;
  for (let i = 0; i < nD1Rays; i++) {
    const u = i / (nD1Rays - 1);
    const tBase = lerp(0.27, 0.445, u);
    const tTip = tBase + 0.014 * (1 - u * 0.4);
    const h = sin(pow(1 - u, 0.72) * 155) * 41 + 3;
    const p0 = rig.pt(tBase, -0.97, 0);
    const p1 = rig.pt(tTip, -1.0, h);
    brush.set("fine_pen", i < 3 ? "#151c1e" : "#2b3a3d", 0.42);
    brush.line(p0[0], p0[1], p1[0], p1[1]);
    if (i % 2 === 0) {
      brush.set("fine_pen", "#e6f5f0", 0.28);
      brush.line(p0[0], p0[1], lerp(p0[0], p1[0], 0.8), lerp(p0[1], p1[1], 0.8));
    }
  }

  // --- B. Second Soft Dorsal Fin (t = 0.595 .. 0.685) ---
  const d2Pts = [
    rig.pt(0.595, -0.95, 0),
    rig.pt(0.610, -1.0, 21),
    rig.pt(0.635, -1.0, 14),
    rig.pt(0.665, -1.0, 9),
    rig.pt(0.688, -0.95, 0)
  ];
  drawWashPoly(d2Pts, "#283b3e", 185, 0.1);
  for (let i = 0; i < 8; i++) {
    const u = i / 7;
    const tB = lerp(0.60, 0.68, u);
    const h = lerp(20, 6, pow(u, 0.7));
    const p0 = rig.pt(tB, -0.96, 0);
    const p1 = rig.pt(tB + 0.01, -1.0, h);
    brush.set("fine_pen", "#1a2629", 0.35);
    brush.line(p0[0], p0[1], p1[0], p1[1]);
  }

  // --- C. 5 Characteristic Dorsal Finlets (t = 0.72 .. 0.90) ---
  const dFinletStations = [0.722, 0.766, 0.810, 0.854, 0.896];
  for (let f = 0; f < dFinletStations.length; f++) {
    const tf = dFinletStations[f];
    const flPts = [
      rig.pt(tf - 0.008, -0.95, 0),
      rig.pt(tf + 0.003, -1.0, 13.5),
      rig.pt(tf + 0.018, -1.0, 10.5),
      rig.pt(tf + 0.012, -0.95, 0)
    ];
    drawWashPoly(flPts, "#1f3033", 210, 0.08);
    const p0 = rig.pt(tf, -0.96, 0);
    const p1 = rig.pt(tf + 0.011, -1.0, 12);
    brush.set("fine_pen", "#d8ede6", 0.3);
    brush.line(p0[0], p0[1], p1[0], p1[1]);
  }

  // --- D. Pelvic Fin (t = 0.255 .. 0.325, along belly) ---
  const pelvPts = [
    rig.pt(0.255, 0.95, 0),
    rig.pt(0.275, 1.0, 17),
    rig.pt(0.315, 1.0, 12),
    rig.pt(0.330, 0.95, 0)
  ];
  drawWashPoly(pelvPts, "#c2d4cc", 175, 0.1);
  for (let i = 0; i < 6; i++) {
    const tB = lerp(0.26, 0.32, i / 5);
    const p0 = rig.pt(tB, 0.96, 0);
    const p1 = rig.pt(tB + 0.012, 1.0, lerp(16, 8, i / 5));
    brush.set("fine_pen", "#6d8287", 0.3);
    brush.line(p0[0], p0[1], p1[0], p1[1]);
  }

  // --- E. Anal Fin (t = 0.61 .. 0.695, along belly) ---
  const analPts = [
    rig.pt(0.610, 0.95, 0),
    rig.pt(0.625, 1.0, 19),
    rig.pt(0.655, 1.0, 12),
    rig.pt(0.688, 1.0, 7),
    rig.pt(0.698, 0.95, 0)
  ];
  drawWashPoly(analPts, "#b5c9c2", 180, 0.1);
  for (let i = 0; i < 7; i++) {
    const u = i / 6;
    const tB = lerp(0.615, 0.69, u);
    const p0 = rig.pt(tB, 0.96, 0);
    const p1 = rig.pt(tB + 0.01, 1.0, lerp(18, 6, u));
    brush.set("fine_pen", "#5c7075", 0.32);
    brush.line(p0[0], p0[1], p1[0], p1[1]);
  }

  // --- F. 5 Ventral / Anal Finlets (t = 0.728 .. 0.902) ---
  const vFinletStations = [0.728, 0.772, 0.816, 0.860, 0.902];
  for (let f = 0; f < vFinletStations.length; f++) {
    const tf = vFinletStations[f];
    const flPts = [
      rig.pt(tf - 0.008, 0.95, 0),
      rig.pt(tf + 0.004, 1.0, 12.5),
      rig.pt(tf + 0.018, 1.0, 9.5),
      rig.pt(tf + 0.012, 0.95, 0)
    ];
    drawWashPoly(flPts, "#9eb5b0", 195, 0.08);
    const p0 = rig.pt(tf, 0.96, 0);
    const p1 = rig.pt(tf + 0.011, 1.0, 11);
    brush.set("fine_pen", "#4f6469", 0.28);
    brush.line(p0[0], p0[1], p1[0], p1[1]);
  }

  // --- G. Deeply Forked Caudal (Tail) Fin ---
  const tailOutline = getTailFinOutline(rig);
  drawWashPoly(tailOutline, "#263336", 225, 0.08);
  drawFillPoly(tailOutline, "#3b5254", 130, 0.14, 0.5, 0.4, 0.08);

  // Warm greenish-bronze sheen at the base of the tail lobes
  const upperLobeGlow = [
    rig.ptPx(0.97, -9),
    rig.ptPx(1.06, -34),
    rig.ptPx(1.14, -56),
    rig.ptPx(1.08, -22),
    rig.ptPx(1.02, -4)
  ];
  drawWashPoly(upperLobeGlow, "#5d8278", 150, 0.12);

  const lowerLobeGlow = [
    rig.ptPx(0.97, 9),
    rig.ptPx(1.06, 32),
    rig.ptPx(1.14, 54),
    rig.ptPx(1.08, 20),
    rig.ptPx(1.02, 4)
  ];
  drawWashPoly(lowerLobeGlow, "#7ea398", 145, 0.12);

  // Radiating caudal fin rays
  for (let r = -12; r <= 12; r++) {
    if (r === 0) continue;
    const u = Math.abs(r) / 12;
    const sign = Math.sign(r);
    const pStart = rig.ptPx(0.985, sign * u * 11);
    const tEnd = lerp(1.06, 1.18, pow(u, 0.72));
    const spreadPx = sign * pow(u, 0.85) * 69;
    const pMid = rig.ptPx(lerp(0.985, tEnd, 0.52), spreadPx * 0.48);
    const pEnd = rig.ptPx(tEnd, spreadPx);

    brush.set("fine_pen", u > 0.75 ? "#121719" : "#1f2b2e", 0.42);
    brush.spline([pStart, pMid, pEnd], 0.3);

    if (Math.abs(r) % 3 === 1) {
      brush.set("fine_pen", "#dceee8", 0.26);
      brush.line(pStart[0], pStart[1], pMid[0], pMid[1]);
    }
  }

  // Two small diagnostic caudal keels at the tail wrist (t = 0.94..1.00)
  for (const kSign of [-1, 1]) {
    const k0 = rig.ptPx(0.94, kSign * 5.2);
    const k1 = rig.ptPx(1.005, kSign * 6.2);
    brush.set("fine_pen", "#141b1d", 0.5);
    brush.line(k0[0], k0[1], k1[0], k1[1]);
    brush.set("fine_pen", "#eefaf6", 0.32);
    brush.line(k0[0], k0[1] - 0.8, k1[0], k1[1] - 0.8);
  }
}

function drawMackerelBodyGlazes(rig) {
  // 1. Opaque Mother-of-Pearl Base Body Silhouette (prevents wood grain bleed-through)
  const fullBody = buildStripPoly(rig, 0.0, 1.0, -1.0, 1.0, 42);
  drawWashPoly(fullBody, "#f0ebe0", 252, 0.12);
  drawWashPoly(fullBody, "#f6f3ea", 230, 0.12);

  // 2. Iridescent Silver-Green Belly & Nacreous Flank Glazes (built in glazed watercolour)
  // Pale celadon-viridian belly wash
  const bellyViridian = buildStripPoly(rig, 0.16, 0.96, 0.02, 0.88, 32);
  drawFillPoly(bellyViridian, "#a7d4be", 125, 0.22, 0.52, 0.35, 0.15);

  // Stronger emerald-silver mid-flank glaze
  const midFlankGreen = buildStripPoly(rig, 0.18, 0.92, -0.08, 0.42, 30);
  drawFillPoly(midFlankGreen, "#73b59c", 120, 0.2, 0.5, 0.38, 0.15);

  // Warm nacreous rose-persimmon reflection band (mirroring the warm katazome ground)
  const roseIridescence = buildStripPoly(
    rig, 0.20, 0.84,
    (t) => 0.14 + sin(t * 180) * 0.05,
    (t) => 0.46 + cos(t * 160) * 0.06,
    28
  );
  drawFillPoly(roseIridescence, "#e3b09e", 105, 0.24, 0.48, 0.32, 0.18);

  // Golden-olive lateral shimmer band along the spine midline
  const goldLateral = buildStripPoly(rig, 0.19, 0.94, -0.05, 0.15, 28);
  drawWashPoly(goldLateral, "#cad496", 115, 0.12);

  // Luminous mother-of-pearl highlight strip along the rounded lower belly
  const pearlBelly = buildStripPoly(rig, 0.21, 0.88, 0.40, 0.74, 28);
  drawWashPoly(pearlBelly, "#f7f8f2", 180, 0.12);

  // Cool silver-slate core shadow & reflected edge along the ventral belly contour
  const ventralShadow = buildStripPoly(rig, 0.12, 0.97, 0.72, 1.0, 32);
  drawFillPoly(ventralShadow, "#6c848c", 135, 0.16, 0.52, 0.42, 0.12);

  const ventralRim = buildStripPoly(rig, 0.16, 0.96, 0.88, 1.0, 30);
  drawWashPoly(ventralRim, "#475c63", 160, 0.1);

  // 3. Dorsal Back Ground (Deep Turquoise, Viridian & Soot-Teal for the Tiger Stripes)
  const dorsalBase = buildStripPoly(rig, 0.16, 0.97, -1.0, 0.08, 34);
  drawFillPoly(dorsalBase, "#245759", 185, 0.16, 0.58, 0.45, 0.14);

  const dorsalDeep = buildStripPoly(rig, 0.17, 0.96, -1.0, -0.22, 32);
  drawWashPoly(dorsalDeep, "#183b3f", 190, 0.12);

  // Iridescent aqua-viridian glow along the lower dorsal transition (s = -0.38 .. +0.08)
  const dorsalAqua = buildStripPoly(rig, 0.20, 0.93, -0.40, 0.08, 30);
  drawWashPoly(dorsalAqua, "#549e91", 165, 0.12);

  // Rinsed paste-resist pale silver-aqua glow along the cylindrical highlight ridge (s = -0.58 .. -0.24)
  const dorsalHighlightChannel = buildStripPoly(rig, 0.21, 0.90, -0.58, -0.24, 28);
  drawWashPoly(dorsalHighlightChannel, "#a6d9cc", 170, 0.12);
}

function drawMackerelTigerStripes(rig) {
  // Exacting hyperreal mackerel dorsal vermiculations (Saba-Gara) rendered with
  // katazome flat resist channels, softened rinsed edges, Y-bifurcations, and soot-black dye.
  const nStripes = 31;
  const tStart = 0.205;
  const tEnd = 0.935;

  // Helper to compute a wavy myotome-following path for stripe at base station tBase
  function sampleStripeCenter(tBase, u, branchDir = 0, seedIdx = 0) {
    // u goes from 0 (dorsal ridge s = -0.99) to 1 (lateral line boundary s ~ +0.10)
    const s = lerp(-0.99, 0.11, u);
    // Characteristic S-chevron wave of mackerel dorsal bars across muscle segments
    const chevron =
      -0.011 * sin(u * 180) +
      0.014 * sin(u * 350 - 35) +
      (noise(seedIdx * 0.4, u * 2.6) - 0.5) * 0.016;
    // Branch offset for Y-forking stripes in lower half (u > 0.38)
    const forkOffset = branchDir !== 0 && u > 0.36
      ? branchDir * pow((u - 0.36) / 0.64, 1.15) * 0.0115
      : 0;
    const t = constrain(tBase + chevron + forkOffset, 0.18, 0.96);
    return [t, s];
  }

  // Pass 1: Katazome Paste-Resist Channels between the dark stripes
  for (let i = 0; i < nStripes - 1; i++) {
    const tMid = lerp(tStart, tEnd, (i + 0.5) / (nStripes - 1));
    const resistPts = [];
    const steps = 10;
    const halfDt = 0.0042 * (1 - 0.35 * (i / nStripes));

    for (let k = 0; k <= steps; k++) {
      const u = k / steps;
      const [t, s] = sampleStripeCenter(tMid, u, 0, i + 50);
      resistPts.push(rig.pt(t - halfDt, s));
    }
    for (let k = steps; k >= 0; k--) {
      const u = k / steps;
      const [t, s] = sampleStripeCenter(tMid, u, 0, i + 50);
      resistPts.push(rig.pt(t + halfDt, s));
    }

    // Rinsed turquoise-cream resist channel
    const col = i % 2 === 0 ? "#cbe6dc" : "#9fd1c2";
    drawWashPoly(resistPts, col, 185, 0.15);
  }

  // Pass 2: Soot-Black & Deep Indigo-Charcoal Tiger Stripes with Rinsed Edges
  for (let i = 0; i < nStripes; i++) {
    const frac = i / (nStripes - 1);
    const tBase = lerp(tStart, tEnd, frac) + (noise(i * 0.8) - 0.5) * 0.005;

    // Every 3rd or 4th stripe bifurcates (forks into a Y) or breaks into stencil dots near lateral line
    const isBifurcated = (i % 3 === 1) && i > 2 && i < nStripes - 4;
    const branches = isBifurcated ? [-1, 1] : [0];

    for (const bDir of branches) {
      const uStart = (bDir === 1) ? 0.34 : 0.0;
      const uEnd = (i % 4 === 2 && bDir === 0) ? 0.76 : 0.96;
      const steps = 12;

      const leftEdge = [];
      const rightEdge = [];
      const spineLine = [];

      for (let k = 0; k <= steps; k++) {
        const u = lerp(uStart, uEnd, k / steps);
        const [t, s] = sampleStripeCenter(tBase, u, bDir, i);

        // Stripe width tapers at dorsal crest and toward lateral line, with organic pinch
        const taper = sin(pow(u, 0.75) * 168) * (1 - 0.28 * frac);
        const pinch = 0.75 + 0.45 * noise(i * 1.7, u * 3.5);
        const halfW = (bDir !== 0 && u > 0.38 ? 0.0044 : 0.0058) * taper * pinch + 0.0012;

        leftEdge.push(rig.pt(t - halfW, s));
        rightEdge.push(rig.pt(t + halfW, s));
        spineLine.push(rig.pt(t, s));
      }

      const stripePoly = [...leftEdge, ...rightEdge.reverse()];

      // Softened rinsed katazome halo around the dark stripe
      drawWashPoly(stripePoly, "#1d4245", 135, 0.18);

      // Core soot-black & deep indigo-soot stencil shape
      const coreCol = (i % 2 === 0) ? "#111618" : "#182226";
      drawWashPoly(stripePoly, coreCol, 232, 0.15);

      // Crisp charcoal/pen spine reinforcement for hyperreal definition
      brush.set("cpencil", "#0d1113", 0.45);
      brush.spline(spineLine, 0.35);
    }

    // Stencilled oblong spots / broken dash below shortened stripes along lateral zone
    if (i % 2 === 0 && i > 1 && i < nStripes - 2) {
      const [tDot, sDot] = sampleStripeCenter(tBase + 0.004, 1.03, 0, i);
      const [wx, wy] = rig.pt(tDot, sDot);
      const spotPoly = makeBlobPoly(wx, wy, 5.5, 3.2, 8, 0.18, BOARD.angle + 25);
      drawWashPoly(spotPoly, "#162024", 205, 0.15);
    }
  }

  // Pass 3: Dark Dorsal Ridge Spine & Translucent Cylindrical Specular Glaze across the Back
  const dorsalCrestStrip = buildStripPoly(rig, 0.18, 0.96, -1.0, -0.84, 34);
  drawWashPoly(dorsalCrestStrip, "#11181b", 215, 0.12);

  // Cylindrical wet highlight glaze running longitudinally along s = -0.52 .. -0.30
  // (softens the stripes where overhead studio light reflects off the wet curvature)
  const wetBackSheen = buildStripPoly(rig, 0.21, 0.89, -0.52, -0.32, 30);
  drawWashPoly(wetBackSheen, "#c5ebe2", 82, 0.14);
}

function drawMackerelScaleAndLateralDetail(rig) {
  // 1. Subtle Myomere Muscle Chevrons & Scale Shimmer along the Iridescent Belly
  const nChevrons = 36;
  for (let i = 0; i < nChevrons; i++) {
    const t0 = lerp(0.22, 0.92, i / (nChevrons - 1));
    const pTop = rig.pt(t0 + 0.008, 0.12);
    const pMid = rig.pt(t0 - 0.010, 0.48);
    const pBot = rig.pt(t0 + 0.012, 0.86);

    const col = i % 3 === 0 ? "#ffffff" : (i % 3 === 1 ? "#8ab8a8" : "#7a949c");
    brush.set("2H", col, 0.32);
    brush.spline([pTop, pMid, pBot], 0.35);
  }

  // Fine longitudinal iridescent scale rows along the lower flank
  for (const sRow of [0.22, 0.36, 0.52, 0.68, 0.82]) {
    const rowPts = [];
    for (let k = 0; k <= 24; k++) {
      const t = lerp(0.22, 0.92, k / 24);
      rowPts.push(rig.pt(t, sRow));
    }
    brush.set("2H", sRow < 0.6 ? "#e8f5ee" : "#5e767e", 0.3);
    brush.spline(rowPts, 0.3);
  }

  // 2. The Lateral Line (t = 0.225 .. 0.97, sinuous sensory canal with stitched pores)
  const latPts = [];
  const latSteps = 44;
  for (let k = 0; k <= latSteps; k++) {
    const u = k / latSteps;
    const t = lerp(0.225, 0.97, u);
    const sLat = lerp(-0.14, 0.0, pow(u, 0.65)) + sin(u * 280) * 0.025;
    latPts.push(rig.pt(t, sLat));
  }

  // Golden-olive and dark teal double-line along the lateral canal
  brush.set("cpencil", "#9ab072", 0.58);
  brush.spline(latPts, 0.35);
  brush.set("fine_pen", "#1f363a", 0.38);
  brush.spline(latPts, 0.35);

  // Tiny stitched sensory pores along the lateral line
  for (let k = 1; k < latSteps; k += 2) {
    const [lx, ly] = latPts[k];
    brush.set("fine_pen", "#eefaf5", 0.32);
    brush.line(lx - 1.2, ly - 0.8, lx + 1.2, ly + 0.8);
  }
}

