// Hyperreal watercolour & technical pen rendering:
// A child's bicycle wheel half-sunk in a roadside runnel of spring meltwater

const SEED = 4279;

// Wheel 3D projection constants
const WCX = 580;
const WCY = 548;
const WRX = 356;
const WRY = 302;
const WTILT = -7; // degrees
const RIM_3D_DX = 16;
const RIM_3D_DY = 12;

async function setup() {
  createCanvas(1200, 1200, WEBGL);
  brush.scaleBrushes(3);
  angleMode(DEGREES);
  randomSeed(SEED);
  noiseSeed(SEED);

  // Custom brushes for hyperreal detail
  brush.add("fine_pen", {
    type: "default",
    weight: 0.32,
    scatter: 0.03,
    sharpness: 0.96,
    grain: 0.08,
    opacity: 235,
    spacing: 0.15,
    pressure: [0.7, 1.15, 0.6],
    noise: 0.25
  });

  brush.add("gouache_glint", {
    type: "default",
    weight: 0.95,
    scatter: 0.05,
    sharpness: 0.9,
    grain: 0.15,
    opacity: 245,
    spacing: 0.12,
    pressure: [0.4, 1.3, 0.3],
    noise: 0.15
  });

  brush.add("grit_spray", {
    type: "spray",
    weight: 5.5,
    scatter: 3.2,
    opacity: 175,
    spacing: 0.65,
    pressure: [0.8, 1.1, 0.8]
  });

  brush.add("slush_grain", {
    type: "default",
    weight: 1.5,
    scatter: 1.35,
    sharpness: 0.38,
    grain: 0.88,
    opacity: 115,
    spacing: 0.35,
    pressure: [0.6, 1.2, 0.5],
    noise: 0.8
  });

  // Custom vector field for moving meltwater currents around the wheel
  brush.addField("melt_stream", (t, field) => {
    for (let col = 0; col < field.length; col++) {
      for (let row = 0; row < field[0].length; row++) {
        let x = map(col, 0, field.length - 1, 0, 1200);
        let y = map(row, 0, field[0].length - 1, 0, 1200);
        // Base current angle flowing left-to-right slightly downward
        let baseAng = 5 + 8 * sin(x * 0.4 + y * 0.3);
        // Deflection around tire entry (left) and exit (right)
        let dLeft = dist(x, y, 255, 575);
        if (dLeft < 180) {
          baseAng += map(dLeft, 0, 180, -28, 0) * (y < 575 ? 1 : -1.2);
        }
        let dRight = dist(x, y, 910, 580);
        if (dRight < 180) {
          baseAng += map(dRight, 0, 180, 24, 0) * (y < 580 ? -1 : 1.2);
        }
        field[col][row] = baseAng;
      }
    }
    return field;
  });
}

// =========================================================================
// GEOMETRY & OPTICAL REFRACTION HELPERS
// =========================================================================

// Upper slush bank edge (background bank behind/around upper wheel)
function getUpperBankY(x) {
  let n1 = (noise(x * 0.004, 1.2) - 0.5) * 90;
  let n2 = (noise(x * 0.018, 4.7) - 0.5) * 34;
  let base = 365 + (x - 600) * 0.07 - 38 * sin(map(x, 0, 1200, 0, 180));
  return base + n1 + n2;
}

// Lower slush bank edge (foreground crumbling slush margin)
function getLowerBankY(x) {
  let n1 = (noise(x * 0.0045, 8.3) - 0.5) * 110;
  let n2 = (noise(x * 0.02, 2.9) - 0.5) * 38;
  let base = 915 - (x - 500) * 0.11 + 35 * sin(map(x, 0, 1200, 20, 200));
  return base + n1 + n2;
}

// The waterline plane intersecting the upright wheel & runnel
function getWaterlineY(x) {
  let base = 570 + (x - 580) * 0.038;
  // Upstream standing bow wave at left tire entry (x ~ 245..340)
  let bowLeft = -21 * exp(-pow((x - 270) / 36, 2)) + 11 * exp(-pow((x - 328) / 28, 2));
  // Capillary ripples upstream of left tire
  let capLeft = x < 260 ? 3.5 * sin((260 - x) * 18) * exp(-(260 - x) / 90) : 0;
  // Hub / central spokes standing wave (x ~ 540..640)
  let hubWave = -11 * exp(-pow((x - 580) / 38, 2)) + 6 * exp(-pow((x - 630) / 28, 2));
  // Downstream rim/tire standing wave (x ~ 840..950)
  let bowRight = -17 * exp(-pow((x - 882) / 34, 2)) + 10 * exp(-pow((x - 938) / 28, 2));
  // Turbulent wake ripples downstream
  let wakeRight = x > 900 ? 5.5 * sin((x - 900) * 12) * exp(-(x - 900) / 220) : 0;
  let organic = (noise(x * 0.015, 5.5) - 0.5) * 8;
  return base + bowLeft + capLeft + hubWave + bowRight + wakeRight + organic;
}

// Project a point (theta in deg, rNorm where 1.0 = outer tire) onto the wheel ellipse
function wheelPt(theta, rNorm, offX = 0, offY = 0) {
  let lx = cos(theta) * WRX * rNorm;
  let ly = sin(theta) * WRY * rNorm;
  let ct = cos(WTILT);
  let st = sin(WTILT);
  let x = WCX + offX + lx * ct - ly * st;
  let y = WCY + offY + lx * st + ly * ct;
  return [x, y];
}

// Snell's Law + wave-lens optical refraction for submerged points (y > getWaterlineY(x))
function refractPt(x, y) {
  let wl = getWaterlineY(x);
  if (y <= wl) return [x, y];
  let depth = y - wl;
  // Apparent vertical lift toward surface + immediate meniscus step at interface
  let lift = 15.5 * (1 - exp(-depth / 7.5)) + 0.21 * depth;
  // Lateral refractive offset
  let shiftX = 18.0 * (1 - exp(-depth / 8.5)) + 0.045 * depth;
  // Wave-lens sinusoidal distortion from moving surface ripples
  let waveEnv = min(1, depth / 14);
  let lensX = 6.2 * sin(depth * 4.2 + x * 2.1) * waveEnv;
  let lensY = 3.8 * cos(depth * 3.6 - x * 1.7) * waveEnv;
  return [x + shiftX + lensX, y - lift + lensY];
}

// Helper to draw a closed or open shape via brush.beginShape / brush.vertex
function drawPoly(pts, closed = true, curvature = 0.25) {
  if (!pts || pts.length < 3) return;
  brush.beginShape(curvature);
  for (let i = 0; i < pts.length; i++) {
    brush.vertex(pts[i][0], pts[i][1]);
  }
  brush.endShape(closed);
}

// Generate jittered polygon points for organic watercolour washes
function makeBlob(cx, cy, rx, ry, rotDeg = 0, nPts = 14, irreg = 0.28) {
  let pts = [];
  let c = cos(rotDeg);
  let s = sin(rotDeg);
  let seedOff = random(1000);
  for (let i = 0; i < nPts; i++) {
    let ang = map(i, 0, nPts, 0, 360);
    let n = noise(cos(ang) * 1.3 + seedOff, sin(ang) * 1.3 + seedOff);
    let rScale = 1 + (n - 0.5) * 2 * irreg;
    let lx = cos(ang) * rx * rScale;
    let ly = sin(ang) * ry * rScale;
    pts.push([cx + lx * c - ly * s, cy + lx * s + ly * c]);
  }
  return pts;
}

// =========================================================================
// MAIN RENDER PIPELINE
// =========================================================================

function draw() {
  translate(-width / 2, -height / 2);

  // 1. Cold sunlit watercolor paper ground
  background("#ece9df");

  // 2. Wet-on-wet base watercolor washes (batched by color for performance & richness)
  renderWetOnWetUnderpainting();

  // 3. Tarmac bed underwater, submerged wheel shadow, caustics & gravel grit
  renderSubmergedTarmacAndGrit();

  // 4. Submerged half of the child's wheel (refracted bent spokes, rim, tire & silt)
  renderSubmergedWheel();

  // 5. Moving water surface glazes, sky/slush reflections & tiny rushing standing waves
  renderWaterSurfaceAndStandingWaves();

  // 6. Crumbling grey slush banks on either side (wet-on-wet, granular crust, overhangs)
  renderCrumblingSlushBanks();

  // 7. Above-water half of the wheel (crisp chrome, reflections, pitted rust, tire, hub)
  renderAboveWaterWheel();

  // 8. Low raking March sunlight glints across wet chrome, wave crests & ice granules
  renderMarchSunGlints();

  noLoop();
}

