// =========================================================================
// 3. SUBMERGED TARMAC BED, CAST SHADOWS, CAUSTICS & GRIT
// =========================================================================
function renderSubmergedTarmacAndGrit() {
  // 3A. Underwater cast shadow of the wheel and spokes on the tarmac bed
  // Sun is low and raking from upper-right -> shadow falls toward lower-left
  brush.noStroke();
  brush.fill("#0e1824", 95);
  brush.fillBleed(0.28, "out");
  brush.fillTexture(0.65, 0.45);

  let shadowRimOuter = [];
  for (let a = 10; a <= 190; a += 8) {
    let p = wheelPt(a, 1.02, -48, 62);
    let rp = refractPt(p[0], max(p[1], getWaterlineY(p[0]) + 8));
    shadowRimOuter.push([rp[0], rp[1] + 22]);
  }
  for (let a = 190; a >= 10; a -= 8) {
    let p = wheelPt(a, 0.72, -48, 62);
    let rp = refractPt(p[0], max(p[1], getWaterlineY(p[0]) + 8));
    shadowRimOuter.push([rp[0], rp[1] + 22]);
  }
  drawPoly(shadowRimOuter, true, 0.2);
  brush.noFill();

  // Underwater spoke shadows on tarmac bed
  brush.set("charcoal", "#101a26", 1.8);
  for (let i = 0; i < 10; i++) {
    let ang = map(i, 0, 10, 18, 178);
    let p1 = wheelPt(ang, 0.15, -42, 54);
    let p2 = wheelPt(ang, 0.75, -48, 62);
    let wl1 = getWaterlineY(p1[0]);
    let rp1 = refractPt(p1[0], max(p1[1], wl1 + 12));
    let rp2 = refractPt(p2[0], max(p2[1], getWaterlineY(p2[0]) + 12));
    brush.line(rp1[0], rp1[1] + 15, rp2[0], rp2[1] + 20);
  }

  // 3B. Tarmac directional asphalt grain & hatch in the runnel bed
  brush.hatchStyle("2B", "#1b2836", 0.75);
  brush.hatch(9, 6, { rand: 0.18, continuous: false });
  brush.noStroke();
  let runnelBed = [
    [40, 470], [450, 410], [850, 420], [1160, 470],
    [1160, 770], [780, 880], [360, 910], [40, 850]
  ];
  drawPoly(runnelBed, true, 0.1);
  brush.noHatch();

  // 3C. Underwater caustic light networks dancing on the tarmac
  brush.field("melt_stream");
  let causticColors = ["#4fa3cc", "#7cc6e8", "#96ad52", "#d9e8c5"];
  for (let c = 0; c < causticColors.length; c++) {
    brush.set("cpencil", causticColors[c], c === 3 ? 0.55 : 0.85);
    let count = c === 3 ? 35 : 55;
    for (let i = 0; i < count; i++) {
      let gx = random(60, 1140);
      let topY = max(getUpperBankY(gx) + 25, getWaterlineY(gx) - 80);
      let botY = getLowerBankY(gx) - 25;
      if (botY > topY + 30) {
        let gy = random(topY, botY);
        brush.flowLine(gx, gy, random(35, 95), random(-8, 14));
      }
    }
  }
  brush.noField();

  // 3D. Hyperreal grit, gravel, quartz sand and road cinders on the tarmac below
  // Spray pass for fine sand/silt
  let sprayPalette = ["#121a22", "#2b3947", "#526044", "#8c7a5b", "#b86b35", "#c9d6de"];
  for (let c = 0; c < sprayPalette.length; c++) {
    brush.set("grit_spray", sprayPalette[c], c < 2 ? 1.1 : 0.8);
    let nStrokes = c < 3 ? 28 : 16;
    for (let i = 0; i < nStrokes; i++) {
      let sx = random(50, 1150);
      let minY = getUpperBankY(sx) + 20;
      let maxY = getLowerBankY(sx) - 20;
      if (maxY > minY + 20) {
        let sy = random(minY, maxY);
        brush.line(sx, sy, sx + random(-45, 45), sy + random(-12, 12));
      }
    }
  }

  // Individual sculpted pebbles & grit stones on the tarmac bed (batched washes + crisp shadows)
  let pebbles = [];
  for (let i = 0; i < 210; i++) {
    let px = random(45, 1155);
    let minY = getUpperBankY(px) + 18;
    let maxY = getLowerBankY(px) - 18;
    if (maxY <= minY + 20) continue;
    let py = random(minY, maxY);
    // Concentrate extra grit near the bottom of the wheel and along bank margins
    if (random() < 0.35) {
      px = random(380, 820);
      py = random(720, 895);
    }
    let sz = random(2.2, 8.5) * (random() < 0.15 ? 1.6 : 1.0);
    let colIdx = floor(random(5));
    pebbles.push({ x: px, y: py, sz: sz, colIdx: colIdx });
  }

  // Pebble underwater cast shadows
  brush.set("2B", "#0b121a", 1.1);
  for (let p of pebbles) {
    brush.line(p.x - p.sz * 0.9, p.y + p.sz * 0.5, p.x + p.sz * 0.3, p.y + p.sz * 0.7);
  }

  // Pebble bodies by color batch
  let pebbleCols = ["#2c3a47", "#5c6642", "#9e582a", "#7a8c99", "#c9ba9b"];
  brush.noStroke();
  for (let ci = 0; ci < pebbleCols.length; ci++) {
    brush. wash(pebbleCols[ci], 185);
    for (let p of pebbles) {
      if (p.colIdx === ci) {
        let pts = makeBlob(p.x, p.y, p.sz, p.sz * 0.72, random(-30, 30), 6, 0.25);
        drawPoly(pts, true, 0.15);
      }
    }
  }
  brush.noWash();

  // Crisp refracted edges and sunlit top facets on underwater grit
  brush.set("fine_pen", "#101820", 0.65);
  for (let i = 0; i < pebbles.length; i += 2) {
    let p = pebbles[i];
    brush.arc(p.x, p.y, p.sz * 0.8, 20, 195);
  }
  brush.set("fine_pen", "#bce6fa", 0.55);
  for (let i = 0; i < pebbles.length; i += 3) {
    let p = pebbles[i];
    brush.line(p.x + p.sz * 0.1, p.y - p.sz * 0.45, p.x + p.sz * 0.65, p.y - p.sz * 0.15);
  }
}

// =========================================================================
// 4. SUBMERGED HALF OF THE BICYCLE WHEEL (HYPERREAL REFRACTION)
// =========================================================================
function renderSubmergedWheel() {
  // Helper to build a refracted arc strip between rIn and rOut from angStart to angEnd
  function getRefractedBand(angStart, angEnd, step, rIn, rOut, offX = 0, offY = 0) {
    let pts = [];
    for (let a = angStart; a <= angEnd; a += step) {
      let p = wheelPt(a, rOut, offX, offY);
      let wl = getWaterlineY(p[0]);
      let clampedY = max(p[1], wl + 0.5);
      pts.push(refractPt(p[0], clampedY));
    }
    for (let a = angEnd; a >= angStart; a -= step) {
      let p = wheelPt(a, rIn, offX, offY);
      let wl = getWaterlineY(p[0]);
      let clampedY = max(p[1], wl + 0.5);
      pts.push(refractPt(p[0], clampedY));
    }
    return pts;
  }

  // Submerged angles roughly span from theta = 8 deg (right entry) to theta = 188 deg (left entry)
  const SUB_A1 = 7;
  const SUB_A2 = 188;

  // 4A. Submerged 3D inner rim wall (offset for 3D depth)
  brush.noStroke();
  brush.fill("#284c66", 165);
  brush.fillBleed(0.18, "out");
  brush.fillTexture(0.55, 0.4);
  drawPoly(getRefractedBand(SUB_A1 + 3, SUB_A2 - 3, 4, 0.63, 0.75, RIM_3D_DX, RIM_3D_DY), true, 0.2);

  // 4B. Submerged black/slate rubber tire (r = 0.85 .. 1.00)
  brush.fill("#192836", 205);
  brush.fillBleed(0.15, "in");
  brush.fillTexture(0.6, 0.45);
  drawPoly(getRefractedBand(SUB_A1, SUB_A2, 3, 0.84, 1.00, 0, 0), true, 0.2);
  // 3D thickness of submerged tire tread
  drawPoly(getRefractedBand(SUB_A1, SUB_A2, 4, 0.94, 1.02, RIM_3D_DX * 0.85, RIM_3D_DY * 0.85), true, 0.2);

  // 4C. Submerged muddy whitewall stripe (r = 0.77 .. 0.845), tinted by olive-blue water
  brush.fill("#8fa89e", 175);
  brush.fillBleed(0.12, "out");
  brush.fillTexture(0.5, 0.35);
  drawPoly(getRefractedBand(SUB_A1 + 1, SUB_A2 - 1, 3, 0.77, 0.845, 0, 0), true, 0.2);

  // 4D. Submerged chrome rim face (r = 0.64 .. 0.77) reflecting steel-blue & olive water
  brush.fill("#3c789e", 175);
  brush.fillBleed(0.15, "out");
  brush.fillTexture(0.55, 0.4);
  drawPoly(getRefractedBand(SUB_A1 + 2, SUB_A2 - 2, 3, 0.64, 0.77, 0, 0), true, 0.2);

  // Olive & dark slate refracted bands inside submerged chrome rim
  brush.fill("#4f6132", 140);
  drawPoly(getRefractedBand(25, 165, 4, 0.68, 0.73, 0, 0), true, 0.2);

  // Submerged rust patches on the rim
  brush.fill("#a84219", 155);
  drawPoly(getRefractedBand(42, 66, 3, 0.64, 0.76, 0, 0), true, 0.25);
  drawPoly(getRefractedBand(118, 142, 3, 0.65, 0.77, 0, 0), true, 0.25);
  brush.noFill();

  // 4E. Knobby tire lugs underwater (refracted & wavy)
  brush.set("2B", "#111b24", 1.3);
  for (let a = SUB_A1 + 2; a <= SUB_A2 - 2; a += 4.5) {
    let p1 = wheelPt(a, 0.98, 0, 0);
    let p2 = wheelPt(a + 2.2, 1.035, 4, 3);
    let p3 = wheelPt(a + 2.2, 0.98, 8, 6);
    if (p1[1] > getWaterlineY(p1[0])) {
      let rp1 = refractPt(p1[0], p1[1]);
      let rp2 = refractPt(p2[0], p2[1]);
      let rp3 = refractPt(p3[0], p3[1]);
      brush.spline([rp1, rp2, rp3], 0.3);
    }
  }

  // Refracted contour splines along the submerged rim & tire (showing the wavy lens distortion)
  let subRings = [
    { r: 1.00, col: "#0f1822", w: 1.1 },
    { r: 0.845, col: "#182938", w: 0.95 },
    { r: 0.77, col: "#1e3447", w: 1.0 },
    { r: 0.70, col: "#9ad9f5", w: 0.85 },
    { r: 0.64, col: "#162836", w: 1.05 }
  ];
  for (let ring of subRings) {
    brush.set("rotring", ring.col, ring.w);
    let pts = [];
    for (let a = SUB_A1; a <= SUB_A2; a += 2.5) {
      let p = wheelPt(a, ring.r, 0, 0);
      let wl = getWaterlineY(p[0]);
      if (p[1] >= wl - 2) {
        let rp = refractPt(p[0], max(p[1], wl + 0.5));
        pts.push([rp[0], rp[1], 0.8 + 0.4 * sin(a * 5)]);
      }
    }
    if (pts.length > 2) brush.spline(pts, 0.35);
  }

  // 4F. HYPERREAL BENT SPOKES BENEATH THE SURFACE
  // 20 spokes total (10 front flange, 10 rear flange, 2-cross lacing)
  let spokes = getWheelSpokes();
  for (let idx = 0; idx < spokes.length; idx++) {
    let sp = spokes[idx];
    // Sample points along spoke from hub (t=0) to rim nipple (t=1)
    let subPts = [];
    let subGlowPts = [];
    for (let step = 0; step <= 28; step++) {
      let t = step / 28;
      let sx = lerp(sp.x1, sp.x2, t);
      let sy = lerp(sp.y1, sp.y2, t);
      let wl = getWaterlineY(sx);
      if (sy >= wl) {
        let rp = refractPt(sx, sy);
        subPts.push([rp[0], rp[1], 0.9]);
        subGlowPts.push([rp[0] + 2.2, rp[1] - 1.5, 0.7]);
      }
    }
    if (subPts.length >= 2) {
      // Chromatic/caustic cyan refraction fringe on underwater spoke
      brush.set("fine_pen", "#7ad4f0", 0.85);
      brush.spline(subGlowPts, 0.35);

      // Dark steel underwater spoke shaft (visibly bent & undulating)
      brush.set("rotring", "#1b3347", 1.05);
      brush.spline(subPts, 0.35);

      // Submerged spoke nipple at the rim
      let endPt = subPts[subPts.length - 1];
      brush.set("rotring", "#10202e", 1.5);
      brush.line(endPt[0], endPt[1], endPt[0] - 4, endPt[1] - 4);
    }
  }

  // 4G. Submerged plastic child's spoke bead (refracted vivid orange-red bead on spoke #4)
  let beadSpoke = spokes[4];
  let bx = lerp(beadSpoke.x1, beadSpoke.x2, 0.58);
  let by = lerp(beadSpoke.y1, beadSpoke.y2, 0.58);
  let rBead = refractPt(bx, by);
  brush.noStroke();
  brush.wash("#e04819", 210);
  drawPoly(makeBlob(rBead[0], rBead[1], 9.5, 7.2, 25, 8, 0.12), true, 0.25);
  brush.noWash();
  brush.set("fine_pen", "#ffd2a6", 0.75);
  brush.arc(rBead[0], rBead[1], 6, 190, 340);

  // 4H. Silt & gravel mound partially burying the lowest arc of the tire (theta ~ 72..108)
  brush.noStroke();
  brush.fill("#3b4728", 150);
  brush.fillBleed(0.3, "out");
  brush.fillTexture(0.75, 0.5);
  let siltPts = [];
  for (let a = 68; a <= 114; a += 5) {
    let p = wheelPt(a, 0.90, 0, 0);
    siltPts.push(refractPt(p[0], p[1]));
  }
  for (let a = 116; a >= 66; a -= 5) {
    let p = wheelPt(a, 1.07, 8, 12);
    siltPts.push(refractPt(p[0], p[1]));
  }
  drawPoly(siltPts, true, 0.3);
  brush.noFill();

  brush.set("grit_spray", "#232e1d", 0.95);
  brush.line(490, 815, 690, 825);
  brush.set("grit_spray", "#8c7b56", 0.75);
  brush.line(510, 820, 675, 830);
}

// =========================================================================
// 5. MOVING WATER SURFACE GLAZES & TINY RUSHING STANDING WAVES
// =========================================================================
function renderWaterSurfaceAndStandingWaves() {
  // 5A. Translucent surface reflection ribbons (cold steel-blue sky & olive slush banks)
  brush.noStroke();
  brush.fill("#4da6d9", 45);
  brush.fillBleed(0.35, "out");
  brush.fillTexture(0.5, 0.3);
  // Flowing reflection ribbons along the waterline and stream
  drawPoly([[60, 545], [265, 550], [310, 578], [55, 582]], true, 0.3);
  drawPoly([[340, 565], [565, 562], [595, 595], [325, 602]], true, 0.3);
  drawPoly([[620, 568], [875, 565], [910, 600], [610, 608]], true, 0.3);
  drawPoly([[915, 568], [1165, 580], [1165, 635], [895, 618]], true, 0.3);

  // Vivid steel-blue concave wave trough shadows just behind the standing wave crests
  brush.fill("#164c78", 92);
  brush.fillBleed(0.22, "out");
  brush.fillTexture(0.6, 0.45);
  // Left tire entry bow-wave trough
  drawPoly([[205, 558], [275, 542], [335, 566], [305, 588], [210, 578]], true, 0.35);
  // Hub/center spokes wave trough
  drawPoly([[525, 562], [585, 552], [645, 568], [625, 588], [535, 582]], true, 0.35);
  // Right rim exit standing wave trough
  drawPoly([[825, 568], [888, 552], [958, 575], [935, 602], [835, 592]], true, 0.35);
  brush.noFill();

  // 5B. Streamlines following the meltwater vector field
  brush.field("melt_stream");
  let streamCols = ["#245f8c", "#5eb5e0", "#6e7d32", "#b8e4fa"];
  for (let c = 0; c < streamCols.length; c++) {
    brush.set("fine_pen", streamCols[c], c === 3 ? 0.65 : 0.8);
    let nLines = c === 3 ? 45 : 65;
    for (let i = 0; i < nLines; i++) {
      let sx = random(30, 1150);
      let sy = getWaterlineY(sx) + random(-25, 240);
      if (sy < getLowerBankY(sx) - 15 && sy > getUpperBankY(sx) + 15) {
        brush.flowLine(sx, sy, random(45, 135), 4);
      }
    }
  }
  brush.noField();

  // 5C. THE TINY RUSHING STANDING WAVES (around tire entry, hub, spokes & exit)
  // Draw multi-layered glassy wave ridges along getWaterlineY(x)
  let waveZones = [
    { x1: 165, x2: 385, amp: 1.0 },  // Upstream left tire bow-wave & capillary train
    { x1: 495, x2: 675, amp: 0.75 }, // Central hub & spoke cluster wave
    { x1: 795, x2: 1060, amp: 0.95 } // Downstream right rim standing wave & V-wake
  ];

  for (let wz of waveZones) {
    // 3 concentric wave ripples per standing wave zone
    for (let k = 0; k < 4; k++) {
      let yOff = k * 7.5 - 4;
      let ptsDark = [];
      let ptsMid = [];
      let ptsCrest = [];
      for (let x = wz.x1; x <= wz.x2; x += 6) {
        let env = sin(map(x, wz.x1, wz.x2, 0, 180));
        let wy = getWaterlineY(x) + yOff * (0.5 + 0.6 * env) + 3.2 * sin(x * 7 + k * 55) * env;
        let p = 0.4 + 0.9 * env;
        ptsDark.push([x, wy + 3.2, p]);
        ptsMid.push([x, wy + 1.4, p]);
        ptsCrest.push([x, wy, p]);
      }
      // Deep slate-blue wave base
      brush.set("rotring", "#163854", 1.15 - k * 0.15);
      brush.spline(ptsDark, 0.35);
      // Olive-cyan translucent wave body
      brush.set("pen", k % 2 === 0 ? "#4ba3c7" : "#6c7a38", 0.95 - k * 0.12);
      brush.spline(ptsMid, 0.35);
      // Crisp bright crest line
      brush.set("fine_pen", "#d9f3ff", 0.9 - k * 0.12);
      brush.spline(ptsCrest, 0.35);
    }
  }

  // Continuous meniscus & waterline refraction seam across the entire wheel width
  let wlSeam = [];
  for (let x = 80; x <= 1120; x += 8) {
    wlSeam.push([x, getWaterlineY(x), 0.7 + 0.4 * sin(x * 3)]);
  }
  brush.set("fine_pen", "#1d496b", 0.9);
  brush.spline(wlSeam, 0.3);

  // Tiny V-shaped capillary standing wavelets around each spoke piercing the water surface!
  let spokes = getWheelSpokes();
  for (let sp of spokes) {
    // Find where spoke crosses y = getWaterlineY(x)
    for (let step = 1; step <= 24; step++) {
      let t1 = (step - 1) / 24;
      let t2 = step / 24;
      let x1 = lerp(sp.x1, sp.x2, t1);
      let y1 = lerp(sp.y1, sp.y2, t1);
      let x2 = lerp(sp.x1, sp.x2, t2);
      let y2 = lerp(sp.y1, sp.y2, t2);
      let wl1 = getWaterlineY(x1);
      let wl2 = getWaterlineY(x2);
      if ((y1 - wl1) * (y2 - wl2) <= 0) {
        let ix = (x1 + x2) * 0.5;
        let iy = getWaterlineY(ix);
        // Draw tiny V-wake & meniscus ring around spoke entry point
        brush.set("fine_pen", "#153b59", 0.85);
        brush.spline([[ix - 10, iy - 2, 0.6], [ix - 3, iy - 5, 1.1], [ix + 16, iy + 2, 0.4]], 0.35);
        brush.spline([[ix - 10, iy + 1, 0.6], [ix - 2, iy + 5, 1.1], [ix + 18, iy + 7, 0.4]], 0.35);
        brush.set("gouache_glint", "#f0fbff", 0.75);
        brush.spline([[ix - 8, iy - 1, 0.5], [ix - 2, iy - 4, 1.2], [ix + 9, iy, 0.4]], 0.35);
        break;
      }
    }
  }
}

// =========================================================================
// 6. CRUMBLING GREY SLUSH BANKS ON EITHER SIDE
// =========================================================================
function renderCrumblingSlushBanks() {
  // 6A. Sculpted wet-on-wet watercolor & dry pigment masses for the upper and lower slush banks
  // Upper bank body polygons (crumbling shelf from y=0 down to getUpperBankY(x))
  let upperShelfPts = [[0, 0], [1200, 0]];
  for (let x = 1200; x >= 0; x -= 25) {
    upperShelfPts.push([x, getUpperBankY(x)]);
  }
  // Lower bank body polygons (from getLowerBankY(x) down to y=1200)
  let lowerShelfPts = [];
  for (let x = 0; x <= 1200; x += 25) {
    lowerShelfPts.push([x, getLowerBankY(x)]);
  }
  lowerShelfPts.push([1200, 1200], [0, 1200]);

  // Wet-on-wet slate-grey & muddy-olive slush bank base washes
  brush.noStroke();
  brush.fill("#48545e", 62);
  brush.fillBleed(0.42, "in");
  brush.fillTexture(0.78, 0.55);
  drawPoly(upperShelfPts, true, 0.15);
  drawPoly(lowerShelfPts, true, 0.15);

  // Overhanging undercut shadow ledges along the crumbling water edge of both banks
  brush.fill("#182533", 125);
  brush.fillBleed(0.25, "out");
  brush.fillTexture(0.7, 0.5);
  for (let x = 20; x < 1160; x += 75) {
    let uy = getUpperBankY(x);
    let w = random(45, 95);
    drawPoly([
      [x, uy - 12], [x + w, uy - 8],
      [x + w - 8, uy + random(14, 28)], [x + 6, uy + random(16, 30)]
    ], true, 0.25);

    let ly = getLowerBankY(x);
    drawPoly([
      [x, ly - random(14, 26)], [x + w, ly - random(12, 24)],
      [x + w + 6, ly + 10], [x - 6, ly + 12]
    ], true, 0.25);
  }

  // Crumbling slush clumps & detached ice islands breaking off into the meltwater
  let slushClumps = [];
  for (let i = 0; i < 68; i++) {
    let isUpper = i < 32;
    let cx = random(25, 1175);
    // Avoid covering the center of the wheel where the wheel sits in front of the upper bank
    if (isUpper && cx > 310 && cx < 860 && random() < 0.55) continue;
    let edgeY = isUpper ? getUpperBankY(cx) : getLowerBankY(cx);
    let cy = isUpper ? edgeY + random(-95, 22) : edgeY + random(-24, 115);
    let rx = random(18, 62);
    let ry = random(12, 38);
    let tone = floor(random(4));
    slushClumps.push({ cx, cy, rx, ry, rot: random(-18, 18), tone, isUpper });
  }

  // Batch fill slush clumps by tone:
  // 0: Cold steel-blue shadow slush, 1: Muddy olive road slush, 2: Slate-grey wet snow, 3: Sunlit pale ice crust
  let clumpPalette = [
    { col: "#2e648c", op: 88 },
    { col: "#6a7532", op: 82 },
    { col: "#3d4b59", op: 90 },
    { col: "#dce8ed", op: 115 }
  ];
  for (let t = 0; t < clumpPalette.length; t++) {
    brush.fill(clumpPalette[t].col, clumpPalette[t].op);
    brush.fillBleed(0.32, "out");
    brush.fillTexture(0.75, 0.5);
    for (let cl of slushClumps) {
      if (cl.tone === t) {
        drawPoly(makeBlob(cl.cx, cl.cy, cl.rx, cl.ry, cl.rot, 10, 0.32), true, 0.28);
      }
    }
  }
  brush.noFill();

  // 6B. Dry-media crystalline slush mass & hatching on the banks
  brush.hatchStyle("slush_grain", "#2d3b47", 0.9);
  brush.hatch(11, -14, { rand: 0.35, gradient: 0.4 });
  brush.noStroke();
  drawPoly([[0, 0], [440, 0], [380, 340], [0, 410]], true, 0.1);
  drawPoly([[780, 0], [1200, 0], [1200, 400], [830, 340]], true, 0.1);
  drawPoly([[0, 880], [480, 930], [520, 1200], [0, 1200]], true, 0.1);
  drawPoly([[680, 910], [1200, 800], [1200, 1200], [640, 1200]], true, 0.1);
  brush.noHatch();

  // 6C. Granular road-grit, salt speckles & porous ice-crust stippling on the slush banks
  let bankSpeckCols = ["#1b242c", "#4b5728", "#27587d", "#8f431e", "#f5f9fa"];
  for (let c = 0; c < bankSpeckCols.length; c++) {
    brush.set("grit_spray", bankSpeckCols[c], c === 4 ? 1.15 : 0.85);
    for (let i = 0; i < 32; i++) {
      let bx = random(20, 1180);
      let isTop = random() < 0.48;
      let by = isTop
        ? random(15, getUpperBankY(bx) + 10)
        : random(getLowerBankY(bx) - 10, 1185);
      // Keep upper wheel silhouette clean where wheel overlaps bank
      if (isTop && dist(bx, by, WCX, WCY) < 340) continue;
      brush.line(bx, by, bx + random(-35, 35), by + random(-14, 14));
    }
  }

  // 6D. Crisp pen and pencil fracture lines along the crumbling slush edges
  for (let cl of slushClumps) {
    if (cl.isUpper && dist(cl.cx, cl.cy, WCX, WCY) < 330) continue;
    // Jagged underside shadow crevice
    brush.set("rotring", "#172330", 0.85);
    brush.arc(cl.cx, cl.cy, cl.rx * 0.78, 15, 165);
    // Sunlit upper crystalline ridge
    brush.set("gouache_glint", "#f2f8fa", 0.8);
    brush.arc(cl.cx, cl.cy, cl.rx * 0.75, 195, 345);
  }
}

// =========================================================================
// 7. ABOVE-WATER HALF OF THE BICYCLE WHEEL (CRISP CHROME, RUST & RUBBER)
// =========================================================================
function renderAboveWaterWheel() {
  // Helper to build an unrefracted arc band above the waterline
  function getAboveWaterBand(angStart, angEnd, step, rIn, rOut, offX = 0, offY = 0) {
    let pts = [];
    for (let a = angStart; a <= angEnd; a += step) {
      let p = wheelPt(a, rOut, offX, offY);
      let wl = getWaterlineY(p[0]);
      pts.push([p[0], min(p[1], wl)]);
    }
    for (let a = angEnd; a >= angStart; a -= step) {
      let p = wheelPt(a, rIn, offX, offY);
      let wl = getWaterlineY(p[0]);
      pts.push([p[0], min(p[1], wl)]);
    }
    return pts;
  }

  // Above-water angles span from theta = 186 deg through 270 (top) to 368 (8 deg)
  const ABV_A1 = 186;
  const ABV_A2 = 368;

  // 7A. 3D Inner Rim Depth Band & Rear Tire Edge (offset by RIM_3D_DX, RIM_3D_DY)
  brush.noStroke();
  // Rear tire 3D thickness
  brush.wash("#141a22", 235);
  drawPoly(getAboveWaterBand(ABV_A1, ABV_A2, 3, 0.94, 1.015, RIM_3D_DX * 0.85, RIM_3D_DY * 0.85), true, 0.15);
  // 3D inner chrome rim cylinder wall
  brush.wash("#36536b", 215);
  drawPoly(getAboveWaterBand(ABV_A1 + 2, ABV_A2 - 2, 3, 0.62, 0.74, RIM_3D_DX, RIM_3D_DY), true, 0.15);
  // Dark reflection band inside 3D rim wall
  brush.wash("#1b2a38", 220);
  drawPoly(getAboveWaterBand(205, 345, 4, 0.62, 0.67, RIM_3D_DX, RIM_3D_DY), true, 0.15);

  // 7B. Main Rubber Tire Body Above Water (r = 0.845 .. 1.00)
  brush.wash("#1c232d", 242);
  drawPoly(getAboveWaterBand(ABV_A1, ABV_A2, 3, 0.845, 1.00, 0, 0), true, 0.15);

  // Cold sky-blue wet sheen along the sun-facing upper-right tire shoulder
  brush.wash("#3e6887", 145);
  drawPoly(getAboveWaterBand(245, 352, 3, 0.92, 0.99, 0, 0), true, 0.2);
  brush.wash("#7cb8db", 110);
  drawPoly(getAboveWaterBand(275, 338, 3, 0.945, 0.98, 0, 0), true, 0.2);

  // 7C. Weathered Cream Whitewall Stripe Above Water (r = 0.77 .. 0.845)
  brush.wash("#e6d8b8", 230);
  drawPoly(getAboveWaterBand(ABV_A1, ABV_A2, 3, 0.77, 0.845, 0, 0), true, 0.15);
  // Shadowed left side of whitewall
  brush.wash("#8c9478", 160);
  drawPoly(getAboveWaterBand(186, 248, 3, 0.77, 0.845, 0, 0), true, 0.15);

  // 7D. Chrome Steel Rim Face Above Water (r = 0.64 .. 0.77)
  // Base silver-sky reflection
  brush.wash("#c8e2f0", 235);
  drawPoly(getAboveWaterBand(ABV_A1, ABV_A2, 3, 0.64, 0.77, 0, 0), true, 0.15);

  // Hyperreal chrome reflection bands (high-contrast horizon, slush & cobalt sky reflections)
  // Dark slate horizon band following the rim profile
  brush.wash("#1c2d3d", 225);
  drawPoly(getAboveWaterBand(192, 265, 3, 0.68, 0.74, 0, 0), true, 0.15);
  drawPoly(getAboveWaterBand(295, 362, 3, 0.66, 0.715, 0, 0), true, 0.15);

  // Vivid cold steel-blue sky reflection band in chrome
  brush.wash("#2470a6", 205);
  drawPoly(getAboveWaterBand(210, 355, 3, 0.72, 0.76, 0, 0), true, 0.15);

  // Muddy olive slush reflection band in lower-left & right curves of chrome rim
  brush.wash("#6c782e", 185);
  drawPoly(getAboveWaterBand(187, 232, 3, 0.64, 0.69, 0, 0), true, 0.15);
  drawPoly(getAboveWaterBand(325, 366, 3, 0.71, 0.755, 0, 0), true, 0.15);
  brush.noWash();

  // 7E. Pitted Rust on the Chrome Rim (wet-on-wet sienna bleed + stipple + crisp corrosion pits)
  let rustZones = [
    { a1: 196, a2: 218, r1: 0.64, r2: 0.75 },
    { a1: 248, a2: 266, r1: 0.65, r2: 0.76 },
    { a1: 308, a2: 332, r1: 0.64, r2: 0.74 },
    { a1: 348, a2: 364, r1: 0.66, r2: 0.77 }
  ];
  brush.noStroke();
  // Burnt sienna rust bleed
  brush.fill("#b83e14", 170);
  brush.fillBleed(0.28, "out");
  brush.fillTexture(0.8, 0.6);
  for (let rz of rustZones) {
    drawPoly(getAboveWaterBand(rz.a1, rz.a2, 3, rz.r1, rz.r2, 0, 0), true, 0.25);
  }
  // Vivid cadmium orange oxide cores
  brush.fill("#e8621c", 165);
  brush.fillBleed(0.2, "in");
  for (let rz of rustZones) {
    drawPoly(getAboveWaterBand(rz.a1 + 3, rz.a2 - 3, 3, rz.r1 + 0.02, rz.r2 - 0.02, 0, 0), true, 0.25);
  }
  brush.noFill();

  // Dark iron-oxide pitted rust stippling & jagged pen outlines
  for (let rz of rustZones) {
    let midA = (rz.a1 + rz.a2) * 0.5;
    let rp = wheelPt(midA, (rz.r1 + rz.r2) * 0.5, 0, 0);
    brush.set("grit_spray", "#591906", 0.65);
    brush.line(rp[0] - 14, rp[1] - 8, rp[0] + 14, rp[1] + 8);

    // Crisp pen corrosion pits
    brush.set("fine_pen", "#421104", 0.75);
    for (let k = 0; k < 9; k++) {
      let pa = random(rz.a1, rz.a2);
      let pr = random(rz.r1, rz.r2);
      let pt = wheelPt(pa, pr, 0, 0);
      brush.circle(pt[0], pt[1], random(1.5, 4.2), 0.45);
    }
  }

  // 7F. Knobby Tire Tread Blocks Around the Upper Circumference
  for (let a = ABV_A1 + 1; a <= ABV_A2 - 2; a += 4.2) {
    let p1 = wheelPt(a, 0.985, 0, 0);
    let p2 = wheelPt(a + 0.6, 1.032, 2, 1);
    let p3 = wheelPt(a + 2.6, 1.032, 3, 2);
    let p4 = wheelPt(a + 3.0, 0.985, 0, 0);
    if (p1[1] <= getWaterlineY(p1[0])) {
      brush.noStroke();
      brush.wash("#141920", 240);
      drawPoly([p1, p2, p3, p4], true, 0.1);
      brush.noWash();
      // Crisp tread edge & sun highlight on upper-right lugs
      brush.set("fine_pen", a > 250 && a < 350 ? "#a3d5f5" : "#2f3e4f", 0.7);
      brush.line(p2[0], p2[1], p3[0], p3[1]);
    }
  }

  // Crisp technical pen lines for tire bead, whitewall border, and chrome rim profiles
  let aboveRings = [
    { r: 1.00, offX: 0, offY: 0, col: "#0d1217", w: 1.15 },
    { r: 0.845, offX: 0, offY: 0, col: "#172029", w: 0.95 },
    { r: 0.77, offX: 0, offY: 0, col: "#141f2b", w: 1.1 },
    { r: 0.705, offX: 0, offY: 0, col: "#1c3347", w: 0.75 },
    { r: 0.64, offX: 0, offY: 0, col: "#12202e", w: 1.15 },
    { r: 0.62, offX: RIM_3D_DX, offY: RIM_3D_DY, col: "#0f1c29", w: 1.0 }
  ];
  for (let ring of aboveRings) {
    brush.set("rotring", ring.col, ring.w);
    let pts = [];
    for (let a = ABV_A1; a <= ABV_A2; a += 2.5) {
      let p = wheelPt(a, ring.r, ring.offX, ring.offY);
      let wl = getWaterlineY(p[0]);
      if (p[1] <= wl + 1) {
        pts.push([p[0], p[1], 0.9]);
      }
    }
    if (pts.length > 2) brush.spline(pts, 0.35);
  }

  // Rubber Schrader valve stem protruding inward from inner rim at theta = 235 deg
  let vBase = wheelPt(235, 0.63, 4, 3);
  let vTip = wheelPt(235, 0.53, 6, 4);
  brush.set("rotring", "#1a222b", 2.6);
  brush.line(vBase[0], vBase[1], vTip[0], vTip[1]);
  // Brass/plastic valve cap highlight
  brush.set("fine_pen", "#e8b84a", 1.1);
  brush.line(vBase[0] + 1, vBase[1] + 1, vTip[0] + 1, vTip[1] + 1);

  // 7G. THE HUB, CAPPED AXLE NUT & CHILD'S BICYCLE FORK BLADE
  renderHubAndAxle();

  // 7H. ABOVE-WATER SPOKES, NIPPLES & COLORFUL PLASTIC SPOKE BEADS
  let spokes = getWheelSpokes();
  for (let idx = 0; idx < spokes.length; idx++) {
    let sp = spokes[idx];
    let abvPts = [];
    let glintPts = [];
    for (let step = 0; step <= 28; step++) {
      let t = step / 28;
      let sx = lerp(sp.x1, sp.x2, t);
      let sy = lerp(sp.y1, sp.y2, t);
      let wl = getWaterlineY(sx);
      if (sy <= wl + 0.5) {
        abvPts.push([sx, sy, 0.95]);
        glintPts.push([sx + 1.1, sy - 0.9, 0.8]);
      }
    }
    if (abvPts.length >= 2) {
      // Crisp dark chrome spoke shadow edge
      brush.set("rotring", "#1c2d3d", 0.95);
      brush.spline(abvPts, 0.15);

      // Razor-sharp sunlight reflection along the spoke shaft
      brush.set("fine_pen", "#edf8ff", 0.75);
      brush.spline(glintPts, 0.15);

      // Spoke nipple & pitted rust collar at the rim (if rim end is above water)
      if (sp.y2 <= getWaterlineY(sp.x2) + 1) {
        let dx = (sp.x1 - sp.x2) * 0.055;
        let dy = (sp.y1 - sp.y2) * 0.055;
        brush.set("rotring", "#3b2314", 1.8);
        brush.line(sp.x2, sp.y2, sp.x2 + dx, sp.y2 + dy);
        brush.set("fine_pen", "#fff6d6", 0.9);
        brush.line(sp.x2 + 1, sp.y2 - 1, sp.x2 + dx + 1, sp.y2 + dy - 1);
      }
    }
  }

  // Two vivid child's plastic spoke beads above water (cobalt-cyan & lemon-ochre)
  let aboveBeads = [
    { spIdx: 12, t: 0.52, col: "#1d8ce0", hi: "#b8ecff" },
    { spIdx: 16, t: 0.64, col: "#eb9e1a", hi: "#fff4bd" }
  ];
  for (let b of aboveBeads) {
    let sp = spokes[b.spIdx];
    let bx = lerp(sp.x1, sp.x2, b.t);
    let by = lerp(sp.y1, sp.y2, b.t);
    brush.noStroke();
    brush.wash(b.col, 235);
    drawPoly(makeBlob(bx, by, 8.5, 6.5, 35, 8, 0.1), true, 0.2);
    brush.noWash();
    brush.set("fine_pen", "#14202b", 0.7);
    brush.circle(bx, by, 7.2, 0.15);
    brush.set("gouache_glint", b.hi, 0.85);
    brush.line(bx - 2, by - 3, bx + 4, by - 1);
  }
}

// Helper to compute all 20 spokes (10 front flange, 10 rear flange, 2-cross pattern)
function getWheelSpokes() {
  let list = [];
  // Rear hub flange center
  let rfx = WCX + 13;
  let rfy = WCY + 9;
  // Front hub flange center
  let ffx = WCX - 9;
  let ffy = WCY - 6;

  for (let i = 0; i < 20; i++) {
    let rimAng = i * 18 + 5;
    let isFront = i % 2 === 0;
    let crossDir = (i % 4 < 2) ? 1 : -1;
    let hubAng = rimAng + crossDir * 58;
    let hcx = isFront ? ffx : rfx;
    let hcy = isFront ? ffy : rfy;
    let hRad = isFront ? 36 : 33;

    let x1 = hcx + cos(hubAng) * hRad * 0.92;
    let y1 = hcy + sin(hubAng) * hRad * 0.82;
    let rimPt = wheelPt(rimAng, 0.685, isFront ? 2 : 9, isFront ? 1 : 6);
    list.push({ x1, y1, x2: rimPt[0], y2: rimPt[1], isFront, rimAng });
  }
  return list;
}

// Render the 3D chrome hub, rusted washer, dome axle nut & chipped fork tip
function renderHubAndAxle() {
  let rfx = WCX + 14;
  let rfy = WCY + 10;
  let ffx = WCX - 9;
  let ffy = WCY - 6;

  brush.noStroke();
  // Rear hub flange
  brush.wash("#2a4054", 230);
  drawPoly(makeBlob(rfx, rfy, 35, 30, WTILT, 16, 0.04), true, 0.25);

  // Central chrome hub barrel connecting rear and front flanges
  brush.wash("#8cb8d4", 235);
  drawPoly([
    [ffx - 16, ffy + 18], [rfx - 14, rfy + 19],
    [rfx + 18, rfy - 16], [ffx + 16, ffy - 18]
  ], true, 0.15);
  // Dark reflection band across hub barrel
  brush.wash("#192a3b", 230);
  drawPoly([
    [ffx - 6, ffy + 8], [rfx - 5, rfy + 9],
    [rfx + 9, rfy - 5], [ffx + 8, ffy - 6]
  ], true, 0.15);

  // Front hub flange (chrome with sky & rust reflections)
  brush.wash("#cde6f5", 240);
  drawPoly(makeBlob(ffx, ffy, 38, 32, WTILT, 16, 0.04), true, 0.25);
  brush.wash("#215680", 195);
  drawPoly(makeBlob(ffx - 4, ffy + 6, 26, 18, WTILT, 12, 0.08), true, 0.25);

  // Pitted rust stain around axle washer
  brush.wash("#bd4418", 210);
  drawPoly(makeBlob(ffx - 11, ffy - 6, 21, 18, WTILT, 12, 0.18), true, 0.25);

  // Chipped crimson-orange child's bicycle fork / training-wheel bracket tab attached to axle
  // Reaching down from upper-left toward the hub axle
  brush.wash("#c92e1d", 235);
  drawPoly([
    [ffx - 95, ffy - 125], [ffx - 68, ffy - 132],
    [ffx - 8, ffy - 4], [ffx - 28, ffy + 6]
  ], true, 0.12);
  // Shadow edge and chipped paint on fork blade
  brush.wash("#5e160e", 220);
  drawPoly([
    [ffx - 95, ffy - 125], [ffx - 86, ffy - 128],
    [ffx - 18, ffy + 2], [ffx - 28, ffy + 6]
  ], true, 0.12);

  // Chrome hexagonal dome axle nut protruding at (ffx - 20, ffy - 12)
  let nx = ffx - 20;
  let ny = ffy - 12;
  brush.wash("#e6f4fc", 245);
  drawPoly(makeBlob(nx, ny, 14, 12, WTILT, 8, 0.05), true, 0.15);
  brush.wash("#1b3247", 225);
  drawPoly(makeBlob(nx - 3, ny + 4, 9, 6, WTILT, 6, 0.05), true, 0.15);
  brush.noWash();

  // Crisp technical pen outlines for hub flanges, fork blade, and dome nut facets
  brush.set("rotring", "#121e2b", 1.1);
  brush.circle(rfx, rfy, 33, 0.05);
  brush.circle(ffx, ffy, 36, 0.05);
  brush.circle(nx, ny, 13, 0.06);
  brush.line(ffx - 95, ffy - 125, ffx - 28, ffy + 6);
  brush.line(ffx - 68, ffy - 132, ffx - 8, ffy - 4);
}

// =========================================================================
// 8. LOW RAKING MARCH SUNLIGHT GLINTS
// =========================================================================
function renderMarchSunGlints() {
  // Blinding solar highlights on wet chrome, wave crests, spoke shafts & ice crystals
  // 8A. Chrome rim sun glints (along upper-right sun-facing arc, theta = 260..348)
  brush.set("gouache_glint", "#ffffff", 1.45);
  for (let a = 258; a <= 346; a += 14) {
    let p1 = wheelPt(a, 0.695, 0, 0);
    let p2 = wheelPt(a + 4.5, 0.695, 0, 0);
    let p3 = wheelPt(a + 9, 0.695, 0, 0);
    brush.spline([[p1[0], p1[1], 0.5], [p2[0], p2[1], 1.4], [p3[0], p3[1], 0.5]], 0.3);
  }

  // Secondary warm solar cream glint along outer rim lip & wet tire droplets
  brush.set("gouache_glint", "#fff9d2", 1.15);
  for (let a = 245; a <= 355; a += 9) {
    let p1 = wheelPt(a, 0.762, 0, 0);
    let p2 = wheelPt(a + 3.5, 0.762, 0, 0);
    brush.line(p1[0], p1[1], p2[0], p2[1]);

    // Pinpoint water droplet glints on the wet black rubber tire
    if (a % 18 === 0) {
      let tp = wheelPt(a + 2, random(0.91, 0.98), 0, 0);
      brush.circle(tp[0], tp[1], random(1.5, 3.2), 0.1);
    }
  }

  // Blinding specular star-glint on the chrome hub dome nut & front flange
  let glints = [
    [WCX - 24, WCY - 20, 14], // Axle dome nut peak
    [WCX + 6, WCY - 34, 11],  // Top of front hub flange
    [wheelPt(302, 0.70)[0], wheelPt(302, 0.70)[1], 16], // Main chrome rim specular blaze
    [wheelPt(318, 0.75)[0], wheelPt(318, 0.75)[1], 13],
    [272, getWaterlineY(272) - 2, 13], // Left standing wave peak glint
    [578, getWaterlineY(578) - 2, 11], // Hub standing wave peak glint
    [884, getWaterlineY(884) - 2, 14]  // Right standing wave peak glint
  ];

  for (let g of glints) {
    let gx = g[0], gy = g[1], rad = g[2];
    brush.noStroke();
    brush.wash("#ffffff", 245);
    drawPoly(makeBlob(gx, gy, rad * 0.42, rad * 0.28, -15, 8, 0.1), true, 0.2);
    brush.noWash();

    // Crisp 4-point optical diffraction rays from raking March sun
    brush.set("gouache_glint", "#ffffff", 1.1);
    brush.line(gx - rad * 1.4, gy + rad * 0.25, gx + rad * 1.4, gy - rad * 0.25);
    brush.line(gx - rad * 0.25, gy - rad * 1.1, gx + rad * 0.25, gy + rad * 1.1);
    brush.set("fine_pen", "#fff7c2", 0.85);
    brush.line(gx - rad * 0.7, gy - rad * 0.6, gx + rad * 0.7, gy + rad * 0.6);
  }

  // 8B. Sparkling raking sunlight along the tiny rushing standing waves & downstream ripples
  brush.set("gouache_glint", "#ffffff", 1.15);
  for (let i = 0; i < 65; i++) {
    let wx = random(95, 1130);
    let wy = getWaterlineY(wx) + random(-6, 38);
    // Concentrate extra sparkles in the standing wave zones
    if (random() < 0.55) {
      let pick = floor(random(3));
      if (pick === 0) wx = random(220, 355);
      else if (pick === 1) wx = random(530, 650);
      else wx = random(835, 985);
      wy = getWaterlineY(wx) + random(-4, 22);
    }
    let len = random(6, 22);
    brush.spline([
      [wx - len * 0.5, wy + 1, 0.4],
      [wx, wy - 1.5, 1.3],
      [wx + len * 0.5, wy + 0.5, 0.4]
    ], 0.35);
  }

  // 8C. Crystalline ice-granule glints along the sunlit top edges of the crumbling slush banks
  brush.set("gouache_glint", "#fffdf0", 1.0);
  for (let x = 35; x < 1165; x += 28) {
    // Upper bank sunlit lip (skip behind wheel top)
    if (x < 290 || x > 880) {
      let uy = getUpperBankY(x) - random(4, 18);
      brush.line(x, uy, x + random(8, 18), uy + random(-3, 3));
    }
    // Lower bank sunlit top ridge
    let ly = getLowerBankY(x) + random(2, 16);
    brush.line(x, ly, x + random(9, 22), ly + random(-4, 2));
  }
}

async function setup() {
  createCanvas(1200, 1200, WEBGL);
  brush.scaleBrushes(3);
  angleMode(DEGREES);
  randomSeed(8472);
  noiseSeed(8472);
}

function draw() {
  translate(-width / 2, -height / 2);

  // Cool daylight porcelain watercolor paper ground
  background("#edf4f9");

  // Scene geometry constants
  const mug = {
    cx: 355,
    cy: 390,
    rx: 148,
    ry: 162,
    rimY: 272,
    rimRx: 118,
    rimRy: 54,
    baseY: 515,
    baseRx: 108,
    baseRy: 50
  };

  const concha = {
    cx: 710,
    cy: 700,
    rx: 278,
    ry: 238,
    height: 188
  };

  // Helper: 3D surface height z(x, y) of the scene for accurate light/banner projection wrapping
  function getSceneHeight(x, y) {
    // Check concha dome (ellipsoid with slight organic bulge)
    let dxC = (x - concha.cx) / concha.rx;
    let dyC = (y - (concha.cy + 14)) / concha.ry;
    let dC2 = dxC * dxC + dyC * dyC;
    if (dC2 < 1.0) {
      let zDome = Math.sqrt(Math.max(0, 1 - dC2)) * concha.height;
      let ribMod = 4.5 * Math.sin(dxC * 18 + dyC * 6);
      return Math.max(0, zDome + ribMod * (1 - dC2));
    }

    // Check clay mug volume
    if (y > mug.rimY - mug.rimRy && y < mug.baseY + mug.baseRy) {
      let tY = constrain((y - mug.rimY) / (mug.baseY - mug.rimY), 0, 1);
      let bellyProfile = Math.sin(tY * 180) * 0.24 + (1 - tY * 0.08);
      let curRx = mug.rx * bellyProfile;
      let dxM = (x - mug.cx) / Math.max(40, curRx);
      if (Math.abs(dxM) < 1.0) {
        let zMug = (1 - tY * 0.35) * 165 + Math.sqrt(Math.max(0, 1 - dxM * dxM)) * 95;
        return zMug;
      }
    }
    return 0;
  }

  // Helper: Project (x, y, z) along noon sun ray to overhead Papel Picado banner plane
  function projectToBanner(x, y, z) {
    // Noon sun slightly from upper-right-front casts rays toward lower-left
    let px = x + z * 0.46;
    let py = y + z * 0.58;
    // Rotate into diagonal hanging banner coordinates
    let ang = -28 * (Math.PI / 180);
    let u = (px - 600) * Math.cos(ang) - (py - 600) * Math.sin(ang);
    let v = (px - 600) * Math.sin(ang) + (py - 600) * Math.cos(ang);
    return { u, v, px, py };
  }

  // Helper: Evaluate overhead papel picado filtered color & cutouts
  // Returns { type: "cutout" | "glaze" | "gap", color, secondary, tintHex }
  function samplePapelPicado(x, y, z) {
    let { u, v } = projectToBanner(x, y, z);
    let bandW = 230;
    let flagL = 310;
    let colIdx = Math.floor((u + 1200) / bandW);
    let rowIdx = Math.floor((v + 1200) / flagL);
    let lu = ((u + 1200) % bandW + bandW) % bandW; // 0..bandW
    let lv = ((v + 1200) % flagL + flagL) % flagL; // 0..flagL

    // Gap between strung banners -> direct crisp noon sunlight
    if (lv > flagL - 36 || lu < 14 || lu > bandW - 14) {
      return { type: "cutout", color: "#fffdf2", name: "sun" };
    }

    // Center coordinates within a single tissue-paper flag
    let cu = lu - bandW * 0.5;
    let cv = lv - (flagL - 36) * 0.5;

    // Classic Mexican papel picado geometric cutouts (diamonds, lattice, rosettes)
    let manhattan = Math.abs(cu) + Math.abs(cv);
    let subU = (( Math.abs(cu) % 48 ) - 24);
    let subV = (( Math.abs(cv) % 48 ) - 24);
    let subDia = Math.abs(subU) + Math.abs(subV);

    // Central diamond window with inner tissue fretwork or border picado teeth
    let isCutout =
      (manhattan > 34 && manhattan < 64) ||
      (manhattan < 16) ||
      (subDia < 13 && Math.abs(cu) > 28 && Math.abs(cv) > 28) ||
      (lv > flagL - 62 && Math.abs(cu % 32) < 12);

    if (isCutout) {
      return { type: "cutout", color: "#fffef5", name: "sun" };
    }

    // Banner colors: Turquoise, Magenta, Lime, Tangerine
    const bannerPalette = [
      { name: "turquoise", hex: "#00b4d8", light: "#72efdd", deep: "#0077b6" },
      { name: "magenta", hex: "#e51c74", light: "#ff70a6", deep: "#9b0f53" },
      { name: "lime", hex: "#76c818", light: "#b5e48c", deep: "#3f7d20" },
      { name: "tangerine", hex: "#ff6d00", light: "#ffaa4c", deep: "#c44900" }
    ];
    let idx = Math.abs(colIdx * 3 + rowIdx * 2) % 4;
    let b = bannerPalette[idx];
    return { type: "glaze", color: b.hex, light: b.light, deep: b.deep, name: b.name };
  }

  // Helper: Oilcloth warped perspective coordinate
  function clothPt(gx, gy) {
    // gx, gy in [-2..22] grid units
    let tY = gy / 18.0; // 0 at top, 1 at bottom
    let perspScale = 0.78 + tY * 0.44;
    let x = 600 + (gx - 9.0) * 68 * perspScale;
    let y = -40 + gy * 70 * (0.86 + tY * 0.22);
    // Subtle vinyl oilcloth drape & crease undulation
    let waveX = Math.sin(gy * 0.55 + gx * 0.25) * 7 + Math.cos(gy * 0.9 - gx * 0.4) * 4;
    let waveY = Math.cos(gx * 0.45 + gy * 0.3) * 8 + Math.sin((gx - gy) * 0.35) * 5;
    return [x + waveX, y + waveY];
  }

  // Helper: Draw a closed polygon using beginShape/vertex/endShape
  function drawPoly(pts, curvature = 0.05) {
    if (!pts || pts.length < 3) return;
    brush.beginShape(curvature);
    for (let i = 0; i < pts.length; i++) {
      brush.vertex(pts[i][0], pts[i][1]);
    }
    brush.endShape(true);
  }

  // =========================================================================
  // 1. AMBIENT COOL PALETTE WATERCOLOR UNDERPAINTING
  // =========================================================================
  brush.noStroke();
  brush.fillBleed(0.28, "out");
  brush.fillTexture(0.5, 0.35);

  const ambientWashes = [
    { col: "#cfe8f7", op: 52, pts: [[0, 0], [1200, 0], [1200, 620], [0, 740]] },
    { col: "#d5dcf5", op: 48, pts: [[0, 480], [1200, 360], [1200, 1200], [0, 1200]] },
    { col: "#bce3ec", op: 45, pts: [[40, 60], [720, 40], [640, 680], [30, 620]] },
    { col: "#d8e2f8", op: 42, pts: [[520, 420], [1180, 380], [1180, 1180], [440, 1180]] }
  ];
  for (let w of ambientWashes) {
    brush.fill(w.col, w.op);
    drawPoly(w.pts, 0.1);
  }
  brush.noFill();

  // =========================================================================
  // 2. THE GINGHAM OILCLOTH (COOL PALETTE WASHES + COLORED PENCIL WEAVE)
  // =========================================================================
  const gridCols = 20;
  const gridRows = 19;

  // Batch 2A: Horizontal & Vertical cool-blue gingham bands (even indices)
  brush.noStroke();
  for (let r = -1; r < gridRows; r++) {
    for (let c = -1; c < gridCols; c++) {
      let isColStripe = ((c + 10) % 2 === 0);
      let isRowStripe = ((r + 10) % 2 === 0);
      if (!isColStripe && !isRowStripe) continue;

      let p00 = clothPt(c, r);
      let p10 = clothPt(c + 1, r);
      let p11 = clothPt(c + 1, r + 1);
      let p01 = clothPt(c, r + 1);
      let midX = (p00[0] + p11[0]) * 0.5;
      let midY = (p00[1] + p11[1]) * 0.5;

      // Skip cells completely hidden deep inside the concha or mug core to save render budget
      let dConcha = Math.hypot((midX - concha.cx) / (concha.rx * 0.82), (midY - concha.cy) / (concha.ry * 0.82));
      let dMug = Math.hypot((midX - mug.cx) / (mug.rx * 0.72), (midY - (mug.cy + 15)) / (mug.ry * 0.72));
      if (dConcha < 0.85 || dMug < 0.8) continue;

      let banner = samplePapelPicado(midX, midY, 0);

      if (isColStripe && isRowStripe) {
        // Dark gingham intersection check (deep cool cobalt / Prussian / teal)
        let colHex = "#255f91";
        let op = 135;
        if (banner.type === "cutout") {
          colHex = "#3882b8";
          op = 110;
        } else if (banner.name === "magenta") {
          colHex = "#4f3a8e";
        } else if (banner.name === "turquoise") {
          colHex = "#117899";
        } else if (banner.name === "lime") {
          colHex = "#237a78";
        } else if (banner.name === "tangerine") {
          colHex = "#52587a";
        }
        brush.wash(colHex, op);
      } else {
        // Mid-tone gingham warp or weft check (cool cerulean / ice blue)
        let colHex = isColStripe ? "#68add8" : "#76b8e0";
        let op = 88;
        if (banner.type === "cutout") {
          colHex = "#8fd0f5";
          op = 68;
        } else if (banner.name === "magenta") {
          colHex = "#9c78c9";
        } else if (banner.name === "turquoise") {
          colHex = "#48bfe3";
        } else if (banner.name === "lime") {
          colHex = "#6cc9a8";
        } else if (banner.name === "tangerine") {
          colHex = "#9ca5c7";
        }
        brush.wash(colHex, op);
      }
      drawPoly([p00, p10, p11, p01], 0.02);
    }
  }
  brush.noWash();

  // Batch 2B: Fine colored-pencil gingham weave threads across the oilcloth
  for (let r = -1; r < gridRows; r++) {
    for (let c = -1; c < gridCols; c++) {
      let p00 = clothPt(c, r);
      let p10 = clothPt(c + 1, r);
      let p11 = clothPt(c + 1, r + 1);
      let p01 = clothPt(c, r + 1);
      let midX = (p00[0] + p11[0]) * 0.5;
      let midY = (p00[1] + p11[1]) * 0.5;

      if (midX < -60 || midX > 1260 || midY < -60 || midY > 1260) continue;
      let dConcha = Math.hypot((midX - concha.cx) / (concha.rx * 0.88), (midY - concha.cy) / (concha.ry * 0.88));
      let dMug = Math.hypot((midX - mug.cx) / (mug.rx * 0.78), (midY - (mug.cy + 15)) / (mug.ry * 0.78));
      if (dConcha < 0.9 || dMug < 0.85) continue;

      let isColStripe = ((c + 10) % 2 === 0);
      let isRowStripe = ((r + 10) % 2 === 0);

      // Vertical warp threads in colored pencil
      if (isColStripe) {
        let threadCol = isRowStripe ? "#173f66" : "#3a7ca5";
        brush.set("cpencil", threadCol, 0.58);
        let steps = 6;
        for (let k = 1; k < steps; k++) {
          let t = k / steps;
          let sx = lerp(p00[0], p10[0], t);
          let sy = lerp(p00[1], p10[1], t);
          let ex = lerp(p01[0], p11[0], t);
          let ey = lerp(p01[1], p11[1], t);
          brush.line(sx, sy, ex, ey);
        }
      }

      // Horizontal weft threads in colored pencil
      if (isRowStripe) {
        let threadCol = isColStripe ? "#123456" : "#4389b5";
        brush.set("cpencil", threadCol, 0.58);
        let steps = 6;
        for (let k = 1; k < steps; k++) {
          let t = k / steps;
          let sx = lerp(p00[0], p01[0], t);
          let sy = lerp(p00[1], p01[1], t);
          let ex = lerp(p10[0], p11[0], t);
          let ey = lerp(p10[1], p11[1], t);
          brush.line(sx, sy, ex, ey);
        }
      }

      // White gingham square subtle cool thread cross-weave & vinyl sheen
      if (!isColStripe && !isRowStripe && (c + r) % 2 === 0) {
        brush.set("2H", "#b6d4e8", 0.42);
        for (let k = 1; k <= 3; k++) {
          let t = k / 4;
          brush.line(lerp(p00[0], p10[0], t), lerp(p00[1], p10[1], t), lerp(p01[0], p11[0], t), lerp(p01[1], p11[1], t));
          brush.line(lerp(p00[0], p01[0], t), lerp(p00[1], p01[1], t), lerp(p10[0], p11[0], t), lerp(p10[1], p11[1], t));
        }
      }
    }
  }

  // Subtle oilcloth fold specular ridge lines across the table
  brush.set("cpencil", "#ffffff", 0.9);
  brush.spline([[60, 790, 0.3], [320, 745, 0.8], [520, 725, 0.4]], 0.5);
  brush.spline([[780, 250, 0.3], [980, 210, 0.9], [1160, 185, 0.3]], 0.5);
  brush.set("cpencil", "#74a8cc", 0.55);
  brush.spline([[60, 796, 0.3], [320, 752, 0.7], [520, 731, 0.3]], 0.5);

  // =========================================================================
  // 3. TRANSLUCENT WATERCOLOUR GLAZES & HARD-EDGED LIGHT ON THE OILCLOTH
  // =========================================================================
  brush.noStroke();
  brush.fillBleed(0.16, "out");
  brush.fillTexture(0.55, 0.48);

  // Overlapping diagonal tissue-paper watercolor glazes on the table
  const tableGlazes = [
    // Turquoise glazes
    { col: "#00b4d8", op: 52, pts: [[-40, 220], [540, -40], [670, 60], [-40, 410]] },
    { col: "#0096c7", op: 48, pts: [[180, 760], [1180, 260], [1230, 410], [280, 910]] },
    { col: "#48cae4", op: 44, pts: [[560, 980], [1220, 650], [1220, 860], [680, 1160]] },
    // Magenta glazes (overlapping turquoise to create cool violet optical mixes)
    { col: "#e51c74", op: 50, pts: [[-30, 370], [760, -30], [880, 85], [40, 520]] },
    { col: "#ff2a85", op: 46, pts: [[380, 880], [1220, 450], [1220, 620], [490, 1040]] },
    // Lime glazes
    { col: "#80ed99", op: 50, pts: [[40, 510], [960, 40], [1080, 165], [150, 650]] },
    { col: "#70e000", op: 42, pts: [[-20, 920], [540, 630], [620, 750], [60, 1080]] },
    // Tangerine glazes (warm festive noon accents against the cool ground)
    { col: "#ff7b00", op: 46, pts: [[130, 630], [1120, 130], [1200, 250], [230, 760]] },
    { col: "#ff9e00", op: 42, pts: [[-40, 120], [320, -40], [420, 35], [-40, 255]] }
  ];

  for (let g of tableGlazes) {
    brush.fill(g.col, g.op);
    drawPoly(g.pts, 0.08);
  }
  brush.noFill();

  // Hard-edged geometric papel picado cutouts of noon light & vivid tissue patches on the oilcloth
  function makeDiamond(cx, cy, rx, ry, rotDeg = -28) {
    let rad = rotDeg * (Math.PI / 180);
    let c = Math.cos(rad), s = Math.sin(rad);
    const raw = [[0, -ry], [rx, 0], [0, ry], [-rx, 0]];
    return raw.map(([dx, dy]) => [cx + dx * c - dy * s, cy + dx * s + dy * c]);
  }

  const hardTablePatches = [
    // Crisp noon sun diamond cutouts on the table
    { cx: 145, cy: 235, rx: 46, ry: 32, col: "#fffef4", op: 165, border: "#72efdd" },
    { cx: 235, cy: 185, rx: 30, ry: 22, col: "#fffef4", op: 160, border: "#ff70a6" },
    { cx: 565, cy: 165, rx: 52, ry: 36, col: "#fffef4", op: 170, border: "#ff9e00" },
    { cx: 660, cy: 118, rx: 32, ry: 22, col: "#fffef4", op: 160, border: "#00b4d8" },
    { cx: 885, cy: 195, rx: 56, ry: 38, col: "#fffef4", op: 165, border: "#80ed99" },
    { cx: 995, cy: 140, rx: 36, ry: 25, col: "#fffef4", op: 160, border: "#e51c74" },
    { cx: 1035, cy: 365, rx: 50, ry: 34, col: "#fffef4", op: 165, border: "#00b4d8" },
    { cx: 1115, cy: 320, rx: 30, ry: 21, col: "#fffef4", op: 155, border: "#ff7b00" },
    { cx: 155, cy: 675, rx: 54, ry: 36, col: "#fffef4", op: 165, border: "#e51c74" },
    { cx: 255, cy: 625, rx: 34, ry: 24, col: "#fffef4", op: 160, border: "#70e000" },
    { cx: 215, cy: 965, rx: 58, ry: 40, col: "#fffef4", op: 165, border: "#00b4d8" },
    { cx: 325, cy: 910, rx: 36, ry: 25, col: "#fffef4", op: 160, border: "#ff7b00" },
    { cx: 1055, cy: 875, rx: 52, ry: 35, col: "#fffef4", op: 165, border: "#e51c74" },
    // Saturated hard-edged colored light cutouts
    { cx: 745, cy: 235, rx: 44, ry: 30, col: "#ff388c", op: 85, border: "#e51c74" },
    { cx: 830, cy: 310, rx: 48, ry: 32, col: "#00d2ff", op: 85, border: "#0096c7" },
    { cx: 960, cy: 270, rx: 42, ry: 28, col: "#9ef01a", op: 85, border: "#70e000" },
    { cx: 120, cy: 525, rx: 45, ry: 30, col: "#ff8500", op: 82, border: "#ff6d00" },
    { cx: 430, cy: 990, rx: 48, ry: 33, col: "#00d2ff", op: 82, border: "#0096c7" },
    { cx: 880, cy: 1045, rx: 50, ry: 34, col: "#ff388c", op: 80, border: "#e51c74" }
  ];

  for (let p of hardTablePatches) {
    let pts = makeDiamond(p.cx, p.cy, p.rx, p.ry, -28);
    brush.noStroke();
    brush.wash(p.col, p.op);
    drawPoly(pts, 0.01);
    brush.noWash();
    // Crisp prismatic chromatic edge in colored pencil
    brush.set("cpencil", p.border, 0.65);
    drawPoly(pts, 0.01);
  }

  // =========================================================================
  // 4. COOL NOON CAST SHADOWS (MUG & CONCHA ON OILCLOTH)
  // =========================================================================
  // Noon sun from upper-right casts cool indigo/cobalt/prussian shadows to lower-left
  brush.noStroke();
  brush.fillBleed(0.22, "out");
