  // Filtered papel picado light & glaze wrapping around the 3D mug belly
  brush.noStroke();
  // Magenta glaze band curving across upper mug belly
  brush.fill("#e51c74", 72);
  drawPoly([
    [mug.cx - 85, 345], [mug.cx + 55, 295], [mug.cx + 135, 335],
