  // =========================================================================
  // 6. THE HERO PINK & YELLOW CONCHA SWEET BUN (CRUMB & CRACKED SUGAR CRUST)
  // =========================================================================
  // Helper: Point on the concha's 3D dome projected to 2D canvas
  // (u, v) in unit disk: u^2 + v^2 <= 1
  function conchaDomePt(u, v, extraHeight = 0) {
    let r2 = u * u + v * v;
    let zNorm = Math.sqrt(Math.max(0, 1 - Math.min(1, r2)));
    // Slight organic lobing around the bun perimeter
    let ang = Math.atan2(v, u);
    let lobe = 1 + 0.028 * Math.cos(ang * 7) + 0.018 * Math.sin(ang * 5);
    let x = concha.cx + u * concha.rx * lobe;
    // Vertical dome projection rises upward (-y) proportional to zNorm
    let y = (concha.cy + 36) + v * concha.ry * lobe - (zNorm * 72 + extraHeight);
    let z = zNorm * concha.height + extraHeight;
    // 3D normal vector
    let nx = u;
    let ny = v * 0.85 - 0.35 * zNorm;
    let nz = zNorm;
    let nLen = Math.hypot(nx, ny, nz) || 1;
    return { x, y, z, nx: nx / nLen, ny: ny / nLen, nz: nz / nLen, r2 };
  }

  // Step 6A: Concha Baked Brioche Base & Soft Crumb Under-layer
  const bunBasePts = [];
  const bunCrownPts = [];
  for (let a = 0; a < 360; a += 8) {
    let rad = a * (Math.PI / 180);
    let pt = conchaDomePt(Math.cos(rad) * 1.02, Math.sin(rad) * 1.02, 0);
    bunBasePts.push([pt.x, pt.y]);
    let ptInner = conchaDomePt(Math.cos(rad) * 0.94, Math.sin(rad) * 0.94, 4);
    bunCrownPts.push([ptInner.x, ptInner.y]);
  }

  brush.noStroke();
  // Golden-amber baked brioche outer skirt
  brush.wash("#c97a24", 245);
  drawPoly(bunBasePts, 0.2);
  // Warm honey-saffron inner crumb base visible through the cracks
  brush.wash("#e6a83e", 240);
  drawPoly(bunCrownPts, 0.2);
  brush.noWash();

  // Watercolor shading across the brioche dome (cool noon shadow on lower-left, warm golden sun on upper-right)
  brush.fillBleed(0.15, "in");
  brush.fillTexture(0.55, 0.45);
  // Shadowed lower-left brioche skirt (rich toasted umber + cool violet-slate shadow)
  const bunShadowSkirt = [];
  for (let a = 85; a <= 245; a += 12) {
    let rad = a * (Math.PI / 180);
    let pOut = conchaDomePt(Math.cos(rad) * 1.02, Math.sin(rad) * 1.02, 0);
    bunShadowSkirt.push([pOut.x, pOut.y]);
