    let pOut = conchaDomePt(Math.cos(rad) * 1.01, Math.sin(rad) * 1.01, 0);
    bakingRing.push([pOut.x, pOut.y]);
  }
  for (let a = 140; a >= -30; a -= 12) {
    let rad = a * (Math.PI / 180);
    let pIn = conchaDomePt(Math.cos(rad) * 0.90, Math.sin(rad) * 0.90, 2);
    bakingRing.push([pIn.x, pIn.y]);
