  brush.noFill();

  // Step 6B: Hyperreal Soft Crumb Texture in the Crevices & Exposed Tear
  // On the front-left edge (around u = -0.78, v = 0.45), a small bite/tear reveals the pillowy interior crumb
  const exposedCrumbPatch = [];
  const tearAngles = [122, 132, 144, 156, 168];
  for (let a of tearAngles) {
    let rad = a * (Math.PI / 180);
    let p = conchaDomePt(Math.cos(rad) * 1.02, Math.sin(rad) * 1.02, 0);
    exposedCrumbPatch.push([p.x, p.y]);
  }
  for (let a of [164, 150, 138, 126]) {
    let rad = a * (Math.PI / 180);
    let p = conchaDomePt(Math.cos(rad) * 0.72, Math.sin(rad) * 0.72, 4);
    exposedCrumbPatch.push([p.x + random(-6, 6), p.y + random(-6, 6)]);
  }
  brush.noStroke();
  brush.wash("#fff0bf", 235);
  drawPoly(exposedCrumbPatch, 0.25);
  brush.noWash();

  // Render fibrous, airy soft crumb across the entire dome crevices and exposed tear
  // Thousands of fine colored-pencil & dry-media crumb filaments and cellular air pockets
  for (let i = 0; i < 420; i++) {
    let r = Math.sqrt(random(0.02, 0.98));
    let th = random(0, 360) * (Math.PI / 180);
    let u = Math.cos(th) * r;
    let v = Math.sin(th) * r;
    let pt = conchaDomePt(u, v, 2);

    // Lighting on the crumb
    let sunDot = pt.nx * 0.52 - pt.ny * 0.48 + pt.nz * 0.70;
    let isTearZone = (u < -0.52 && v > 0.22 && r > 0.68);

    let crumbCol;
    if (isTearZone) {
      crumbCol = random(["#fff7d6", "#f5dc98", "#d9b978", "#b39c82", "#8e8294"]);
    } else if (sunDot > 0.35) {
      crumbCol = random(["#f7d070", "#e69f35", "#fff0b3", "#c9741c"]);
    } else {
