    if (i % 3 === 0 || isTearZone) {
      brush.set("2B", isTearZone ? "#8c6d46" : "#59260b", 0.48);
      brush.arc(pt.x + random(-3, 3), pt.y + random(-3, 3), random(2.2, 4.8), 0, 290);
