  // Step 6C: Generate the Cracked Sugar Crust Islands (Pink & Yellow Shell Pattern)
  // A concha's sugar topping is scored into curved shell ribs radiating/arching across the top.
  // Left/Upper-Left hemisphere = Hibiscus Pink sugar crust
  // Right/Lower-Right hemisphere = Marigold/Canary Yellow sugar crust
  const sugarIslands = [];
  const numRibs = 9; // 9 curved shell flutes across the dome

  for (let rIdx = 0; rIdx < numRibs; rIdx++) {
    // s0, s1 in [-0.92, 0.92] across the shell axis
    let s0 = map(rIdx, 0, numRibs, -0.92, 0.92);
    let s1 = map(rIdx + 1, 0, numRibs, -0.92, 0.92);
    let sMid = (s0 + s1) * 0.5;

    // Baked oven-spring crack gap between ribs (wider near crown, tapering near edges)
    let ribGap = 0.024 + 0.012 * (1 - sMid * sMid);
    let uA = s0 + ribGap;
    let uB = s1 - ribGap;
    if (uB <= uA) continue;

    // Determine how far this rib extends along the perpendicular shell arch t in [-tMax, tMax]
    let tMax = Math.sqrt(Math.max(0.05, 0.90 - sMid * sMid * 0.88));
    // Number of transverse crack segments along this rib
    let numSegs = rIdx === 0 || rIdx === numRibs - 1 ? 3 : (Math.abs(sMid) < 0.45 ? 5 : 4);

    // Build irregular transverse crack positions
    let tSplits = [-tMax];
    for (let k = 1; k < numSegs; k++) {
      let baseT = lerp(-tMax, tMax, k / numSegs);
      let jitter = random(-0.045, 0.045) * tMax;
      tSplits.push(constrain(baseT + jitter, -tMax + 0.08, tMax - 0.08));
    }
    tSplits.push(tMax);

    for (let k = 0; k < numSegs; k++) {
      let t0 = tSplits[k] + (k === 0 ? 0 : 0.032);
      let t1 = tSplits[k + 1] - (k === numSegs - 1 ? 0 : 0.032);
      if (t1 - t0 < 0.07) continue;

      let tMid = (t0 + t1) * 0.5;
      // Leave the small front-left torn crumb area exposed
      if (sMid < -0.55 && tMid > 0.25 && k === numSegs - 1) continue;

      // Helper to map (s, t) in shell coordinates into curved shell (u, v) on dome
      function shellToUV(s, t) {
        // Curved shell flutes fan out from a hinge near the bottom-right toward top-left
        let bend = 0.24 * (1 - t * t) * Math.sin(s * 2.1) + 0.12 * t * s;
        let su = s + bend;
        let sv = t - 0.14 * s * s;
        // Rotate the shell pattern by -22 degrees for natural placement on the bun
        let rot = -22 * (Math.PI / 180);
        let u = su * Math.cos(rot) - sv * Math.sin(rot);
        let v = su * Math.sin(rot) + sv * Math.cos(rot);
        // Clamp inside dome radius 0.93
        let mag = Math.hypot(u, v);
        if (mag > 0.93) {
          u *= 0.93 / mag;
          v *= 0.93 / mag;
        }
        return { u, v };
      }

      // Trace polygon perimeter of this sugar crust island with organic crumbly edge jitter
      const topPts = [];
      const sideWallPts = [];
      const shadowPts = [];
      const perimeterSamples = [];

      // Sample 4 sides of the curved (s, t) patch
      const edgeSteps = 4;
      for (let i = 0; i <= edgeSteps; i++) perimeterSamples.push([lerp(uA, uB, i / edgeSteps), t0]);
      for (let i = 1; i <= edgeSteps; i++) perimeterSamples.push([uB, lerp(t0, t1, i / edgeSteps)]);
      for (let i = 1; i <= edgeSteps; i++) perimeterSamples.push([lerp(uB, uA, i / edgeSteps), t1]);
      for (let i = 1; i < edgeSteps; i++) perimeterSamples.push([uA, lerp(t1, t0, i / edgeSteps)]);

      let sumX = 0, sumY = 0, sumZ = 0, sumNx = 0, sumNy = 0, sumNz = 0;

      for (let pIdx = 0; pIdx < perimeterSamples.length; pIdx++) {
        let [sVal, tVal] = perimeterSamples[pIdx];
        // Crumbly sugar edge irregularity
        let nJitS = (noise(rIdx * 10 + k * 3 + pIdx * 0.7) - 0.5) * 0.028;
        let nJitT = (noise(rIdx * 10 + k * 3 + pIdx * 0.7 + 99) - 0.5) * 0.028;
        let { u, v } = shellToUV(sVal + nJitS, tVal + nJitT);

        // Sugar crust sits 7px proud of the soft crumb base
        let dPt = conchaDomePt(u, v, 8.5);
        let bPt = conchaDomePt(u, v, 1.5);

        topPts.push([dPt.x, dPt.y]);
        sideWallPts.push([bPt.x - 1.5, bPt.y + 4.5]);
        shadowPts.push([bPt.x - 5.5, bPt.y + 8.5]);

        sumX += dPt.x;
        sumY += dPt.y;
        sumZ += dPt.z;
        sumNx += dPt.nx;
        sumNy += dPt.ny;
        sumNz += dPt.nz;
      }

      let count = perimeterSamples.length;
      let cx = sumX / count;
      let cy = sumY / count;
      let cz = sumZ / count;
      let nx = sumNx / count;
      let ny = sumNy / count;
      let nz = sumNz / count;

      // Determine whether this shell rib is PINK or YELLOW:
      // Left/upper ribs (rIdx < 4) are Pink; center rib (rIdx === 4) alternates/marbles; right/lower ribs (rIdx > 4) are Yellow!
      let isPink = rIdx < 4 || (rIdx === 4 && (k % 2 === 0));

      sugarIslands.push({
        rIdx,
        k,
        isPink,
        topPts,
        sideWallPts,
        shadowPts,
        cx,
        cy,
        cz,
        nx,
        ny,
        nz
      });
    }
  }

  // Sort sugar islands back-to-front (by cy) so 3D overlapping edges stack naturally
  sugarIslands.sort((a, b) => a.cy - b.cy);

  // Step 6D: Render Sugar Island Cast Shadows into the Crumb Crevices & Thick Sugar Side Walls
  brush.noStroke();
  for (let isl of sugarIslands) {
    // Crevice cast shadow on the golden crumb
    brush.wash("#5c280e", 155);
    drawPoly(isl.shadowPts, 0.08);
  }
  for (let isl of sugarIslands) {
    // Thick crumbly sugar crust side wall (3D thickness of the costra)
    let wallCol = isl.isPink ? "#f2b8cb" : "#f5e29c";
    let sunDot = isl.nx * 0.55 - isl.ny * 0.45 + isl.nz * 0.70;
    if (sunDot < 0.25) {
      wallCol = isl.isPink ? "#9e4b6c" : "#ad8434";
    }
    brush.wash(wallCol, 240);
    drawPoly(isl.sideWallPts, 0.06);
  }
  brush.noWash();

  // Step 6E: Render the Top Surface of Each Pink & Yellow Sugar Crust Island
  for (let isl of sugarIslands) {
    let sunDot = isl.nx * 0.55 - isl.ny * 0.45 + isl.nz * 0.70;
    let banner = samplePapelPicado(isl.cx, isl.cy, isl.cz);

    let baseCol, glazeCol, glazeOp;
    if (isl.isPink) {
      // Pink concha sugar crust palette (cool rose, hibiscus, magenta-pink, cool plum shadow)
      if (banner.type === "cutout" && sunDot > 0.25) {
        baseCol = "#ff9ebb"; // Blazing noon sun on pink sugar
        glazeCol = "#ffd6e4";
        glazeOp = 95;
      } else if (sunDot > 0.38) {
        baseCol = "#f26493";
        glazeCol = banner.name === "turquoise" ? "#b565c9" : (banner.name === "lime" ? "#e88896" : "#ff4785");
        glazeOp = 75;
      } else if (sunDot > 0.12) {
        baseCol = "#d14576";
        glazeCol = "#9d3670";
        glazeOp = 80;
      } else {
        // Cool palette shadow on pink sugar crust (deep berry-violet / plum)
        baseCol = "#8f2d5e";
        glazeCol = "#4f2958";
        glazeOp = 95;
      }
    } else {
      // Yellow concha sugar crust palette (canary, lemon-saffron, cool ochre-olive shadow)
      if (banner.type === "cutout" && sunDot > 0.25) {
        baseCol = "#ffea75"; // Blazing noon sun on yellow sugar
        glazeCol = "#fff8c4";
        glazeOp = 95;
      } else if (sunDot > 0.38) {
        baseCol = "#f7c625";
        glazeCol = banner.name === "turquoise" ? "#78c679" : (banner.name === "magenta" ? "#ff8552" : "#ffd60a");
        glazeOp = 75;
      } else if (sunDot > 0.12) {
        baseCol = "#d49b1a";
        glazeCol = "#a87e2b";
        glazeOp = 80;
      } else {
        // Cool palette shadow on yellow sugar crust (cool amber-slate / olive-ochre)
        baseCol = "#9c7125";
        glazeCol = "#5c5338";
        glazeOp = 95;
      }
    }

    // Solid opaque sugar paste base
    brush.noStroke();
    brush.wash(baseCol, 238);
    drawPoly(isl.topPts, 0.06);
    brush. wash(glazeCol, glazeOp);
    drawPoly(isl.topPts, 0.06);
    brush.noWash();

    // Dry-media / colored-pencil sugar crust texture inside each island
    let edgeHighlightCol = isl.isPink
      ? (sunDot > 0.2 ? "#ffd9e6" : "#b85d89")
      : (sunDot > 0.2 ? "#fff5b5" : "#bfa04e");
    let edgeShadowCol = isl.isPink ? "#63173d" : "#6e4711";

    // Draw crumbly sunlit upper-right bevel & shadowed lower-left bevel on each sugar plate
    brush.set("cpencil", edgeHighlightCol, 0.85);
    for (let i = 0; i < Math.floor(isl.topPts.length * 0.55); i++) {
      let p1 = isl.topPts[i];
      let p2 = isl.topPts[(i + 1) % isl.topPts.length];
      brush.line(p1[0], p1[1], p2[0], p2[1]);
    }

    brush.set("cpencil", edgeShadowCol, 0.8);
    for (let i = Math.floor(isl.topPts.length * 0.55); i < isl.topPts.length; i++) {
      let p1 = isl.topPts[i];
      let p2 = isl.topPts[(i + 1) % isl.topPts.length];
      brush.line(p1[0], p1[1], p2[0], p2[1]);
    }

    // Fine secondary hairline cracks branching across the dry sugar island
    brush.set("pen", edgeShadowCol, 0.42);
    let pStart = isl.topPts[Math.floor(random(isl.topPts.length))];
    let midX = lerp(pStart[0], isl.cx, 0.65) + random(-8, 8);
    let midY = lerp(pStart[1], isl.cy, 0.65) + random(-8, 8);
    brush.spline([
      [pStart[0], pStart[1], 0.7],
      [midX, midY, 0.5],
      [isl.cx + random(-12, 12), isl.cy + random(-12, 12), 0.2]
    ], 0.35);

    // Highlight alongside the micro-crack
    brush.set("cpencil", edgeHighlightCol, 0.5);
    brush.line(pStart[0] + 1.5, pStart[1] - 1.5, midX + 1.5, midY - 1.5);
  }

  // =========================================================================
  // 7. TRANSLUCENT WATERCOLOUR GLAZES & HARD-EDGED LIGHT ACROSS THE CONCHA
  // =========================================================================
  // Project papel picado color bands & diamond cutouts directly over the 3D dome of the concha
  function projectPolygonOntoConcha(uCenter, vCenter, du, dv, rotDeg = -26) {
    let rad = rotDeg * (Math.PI / 180);
    let c = Math.cos(rad), s = Math.sin(rad);
    const localPts = [
      [0, -dv], [du * 0.55, -dv * 0.45], [du, 0], [du * 0.55, dv * 0.45],
      [0, dv], [-du * 0.55, dv * 0.45], [-du, 0], [-du * 0.55, -dv * 0.45]
    ];
    return localPts.map(([lu, lv]) => {
      let u = uCenter + (lu * c - lv * s);
      let v = vCenter + (lu * s + lv * c);
      let pt = conchaDomePt(u, v, 9.5);
      return [pt.x, pt.y];
    });
  }

  // Translucent watercolor glazes draping over the curved concha shell
  brush.noStroke();
  brush.fillBleed(0.14, "out");
  brush.fillTexture(0.5, 0.45);

  const conchaGlazes = [
    // Magenta filtered tissue band wrapping across the crown
    { col: "#e51c74", op: 56, u: -0.18, v: -0.22, du: 0.52, dv: 0.22 },
    // Turquoise filtered tissue band wrapping across the lower-right yellow ribs (mixing emerald/aqua!)
    { col: "#00b4d8", op: 58, u: 0.22, v: 0.18, du: 0.54, dv: 0.22 },
    // Lime filtered light band across the upper-right shoulder
    { col: "#70e000", op: 50, u: 0.32, v: -0.32, du: 0.44, dv: 0.18 },
    // Tangerine warm glaze across the left-center pink ribs
    { col: "#ff6d00", op: 48, u: -0.35, v: 0.12, du: 0.42, dv: 0.18 }
  ];

  for (let cg of conchaGlazes) {
    brush.fill(cg.col, cg.op);
    drawPoly(projectPolygonOntoConcha(cg.u, cg.v, cg.du, cg.dv, -26), 0.15);
  }
  brush.noFill();

  // Hard-edged geometric patches of noon light falling across the concha's curved 3D dome
  const conchaLightCutouts = [
    { u: -0.12, v: -0.38, du: 0.17, dv: 0.12, col: "#fffef5", op: 145, rim: "#ff70a6" },
    { u: 0.08, v: -0.46, du: 0.11, dv: 0.08, col: "#fffef5", op: 140, rim: "#72efdd" },
    { u: 0.28, v: -0.14, du: 0.19, dv: 0.13, col: "#fffef5", op: 150, rim: "#80ed99" },
    { u: 0.44, v: -0.22, du: 0.11, dv: 0.08, col: "#fffef5", op: 140, rim: "#ff9e00" },
    { u: -0.26, v: -0.02, du: 0.18, dv: 0.12, col: "#fffef5", op: 140, rim: "#00b4d8" },
    { u: 0.12, v: 0.24, du: 0.18, dv: 0.13, col: "#fffef5", op: 145, rim: "#e51c74" },
    { u: 0.32, v: 0.15, du: 0.12, dv: 0.08, col: "#fffef5", op: 135, rim: "#00b4d8" },
    { u: -0.05, v: 0.52, du: 0.16, dv: 0.11, col: "#fffef5", op: 130, rim: "#ff7b00" }
  ];

  for (let lc of conchaLightCutouts) {
    let pts = projectPolygonOntoConcha(lc.u, lc.v, lc.du, lc.dv, -26);
    brush.noStroke();
    brush.wash(lc.col, lc.op);
    drawPoly(pts, 0.04);
    brush.noWash();
    brush.set("cpencil", lc.rim, 0.7);
    drawPoly(pts, 0.04);
  }

  // =========================================================================
  // 8. HYPERREAL SUGAR GRANULES (COLORED PENCIL CRYSTALLINE SPARKLE)
  // =========================================================================
  // Thousands of individual colored pencil marks capturing the coarse sugar crystals on the crust
  for (let isl of sugarIslands) {
    let sunDot = isl.nx * 0.55 - isl.ny * 0.45 + isl.nz * 0.70;
    let banner = samplePapelPicado(isl.cx, isl.cy, isl.cz);

    // Compute bounding box of island for fast crystal placement
    let minX = 9999, maxX = -9999, minY = 9999, maxY = -9999;
    for (let pt of isl.topPts) {
      if (pt[0] < minX) minX = pt[0];
      if (pt[0] > maxX) maxX = pt[0];
      if (pt[1] < minY) minY = pt[1];
      if (pt[1] > maxY) maxY = pt[1];
    }

    let crystalCount = 34;
    for (let c = 0; c < crystalCount; c++) {
      // Blend toward center so crystals stay inside the sugar island
      let pA = isl.topPts[Math.floor(random(isl.topPts.length))];
      let pB = isl.topPts[Math.floor(random(isl.topPts.length))];
      let t1 = random(0.15, 0.85);
      let t2 = random(0.15, 0.75);
      let sx = lerp(lerp(pA[0], pB[0], t1), isl.cx, t2);
      let sy = lerp(lerp(pA[1], pB[1], t1), isl.cy, t2);

      let granCol;
      let granWeight = random(0.45, 1.05);

      if (c % 5 === 0 && sunDot > 0.15) {
        // Pure glistening crystal facet catching noon sun
        granCol = "#ffffff";
        granWeight = random(0.75, 1.25);
      } else if (c % 7 === 0) {
        // Filtered banner light glint on sugar crystal
        granCol = random(["#72efdd", "#ff70a6", "#b5e48c", "#ffaa4c", "#e0fbfc"]);
      } else if (isl.isPink) {
        granCol = sunDot > 0.22
          ? random(["#ffe5ef", "#ffadc8", "#ff6ea1", "#d93870"])
          : random(["#c9658f", "#8a305b", "#6e2954", "#9e82a8"]);
      } else {
        granCol = sunDot > 0.22
          ? random(["#fffbe0", "#ffea85", "#f5b716", "#d98a14"])
          : random(["#c49a3d", "#876522", "#695d3e", "#8fa69b"]);
      }

      brush.set("cpencil", granCol, granWeight);
      let dx = random(-2.4, 2.4);
      let dy = random(-2.0, 2.0);
      brush.line(sx, sy, sx + dx, sy + dy);
    }
  }

  // =========================================================================
  // 9. FALLEN SUGAR CRUST FLAKES & GRANULES ON THE OILCLOTH
  // =========================================================================
  const fallenFlakes = [
    { x: 435, y: 785, r: 9, isPink: true },
    { x: 462, y: 812, r: 6, isPink: true },
    { x: 418, y: 825, r: 5, isPink: false },
    { x: 525, y: 928, r: 11, isPink: true },
    { x: 552, y: 945, r: 7, isPink: false },
    { x: 645, y: 975, r: 10, isPink: false },
    { x: 675, y: 992, r: 6, isPink: false },
    { x: 855, y: 955, r: 12, isPink: false },
    { x: 888, y: 938, r: 7, isPink: false },
    { x: 965, y: 845, r: 8, isPink: false },
    { x: 390, y: 695, r: 7, isPink: true }
  ];

  for (let f of fallenFlakes) {
    let fPts = [];
    let sPts = [];
    for (let a = 0; a < 360; a += 60) {
      let rad = (a + random(-15, 15)) * (Math.PI / 180);
      let radLen = f.r * random(0.75, 1.25);
      fPts.push([f.x + Math.cos(rad) * radLen, f.y + Math.sin(rad) * radLen * 0.75]);
      sPts.push([f.x - 4 + Math.cos(rad) * radLen, f.y + 5 + Math.sin(rad) * radLen * 0.75]);
    }
    brush.noStroke();
    // Tiny noon shadow under each crumb
    brush.wash("#14264c", 160);
    drawPoly(sPts, 0.1);
    // Sugar flake body
    brush.wash(f.isPink ? "#ff7aa8" : "#ffd645", 235);
    drawPoly(fPts, 0.1);
    brush.noWash();

    // Sparkling sugar crystals on and around the fallen crumbs
    for (let k = 0; k < 10; k++) {
      let gx = f.x + random(-22, 22);
      let gy = f.y + random(-16, 16);
      brush.set("cpencil", k % 2 === 0 ? "#ffffff" : (f.isPink ? "#ffc2da" : "#fff5b0"), random(0.55, 0.95));
      brush.line(gx, gy, gx + random(-2, 2), gy + random(-2, 2));
    }
  }

  noLoop();
}

// Hyperrealism in p5.brush: Weathered Pine Crate with Lithographic Sunburst Label & Cut Blood Orange

