  brush.scaleBrushes(3);
  angleMode(DEGREES);
  randomSeed(2026);
  noiseSeed(2026);

  // Custom brushes for period airbrush, dry-brushed pine grain, juicy pulp vesicles, and wet gloss
  brush.add("airbrush", {
    type: "spray",
    weight: 16,
