}

function draw() {
  translate(-width / 2, -height / 2);
  background("#F6EFE4");

  brush.noField();

  // 1. Weathered Pine Crate End & Foreground Tabletop
  drawCrateAndTable();

  // 2. Flat Saturated Lithographic Label with Period Airbrush Glow (clipped to torn shape)
  drawLithoLabel();

  // 3. Torn Paper Deckle Edges, Exposed Wood Shadows & 3D Peeling Corner Flap
  drawTornPaperAndCurl();

  // 4. Whole Tilted Blood Orange (Left-Center, Resting Against Crate)
  drawBackOrange(455, 815, 174);

  // 5. Hero Cut Blood Orange Half (Hyperreal Segments, Pith Fibres, Wet Glisten & Running Juice Drop)
  drawCutBloodOrange(748, 825, 222, 210);

  noLoop();
}

// =============================================================================
// GEOMETRY & CLIPPING HELPERS
// =============================================================================

function drawShapePoly(pts, curvature = 0.05, closed = true) {
  if (!pts || pts.length < 2) return;
  brush.beginShape(curvature);
  for (let i = 0; i < pts.length; i++) {
    brush.vertex(pts[i][0], pts[i][1]);
  }
  brush.endShape(closed);
}

// Jagged tear offset functions
function bottomLeftTearY(x) {
  let base = 535 + (x - 180) * 0.85;
  let n1 = (noise(x * 0.018, 12.3) - 0.5) * 68;
  let n2 = (noise(x * 0.07, 45.1) - 0.5) * 22;
  return base + n1 + n2;
}

function topRightCreaseY(x) {
  // Diagonal crease from (685, 110) to (1020, 445)
  return 110 + (x - 685) * 1.0;
}

function seamSplitHalfGap(x) {
  // The crate's two horizontal boards meet around y = 490
  let n = noise(x * 0.025, 88.2);
  if (x < 380) return 5 + n * 14;
  if (x > 870) return 4 + n * 12;
  return 1.5 + n * 4.5;
}

// Determines whether a point (x, y) is on the intact glued paper label
function isInsideLabel(x, y) {
  let edgeJitterL = (noise(y * 0.03, 1.1) - 0.5) * 14;
  let edgeJitterR = (noise(y * 0.03, 2.2) - 0.5) * 14;
  let edgeJitterT = (noise(x * 0.03, 3.3) - 0.5) * 12;
  let edgeJitterB = (noise(x * 0.03, 4.4) - 0.5) * 14;

  if (x < 182 + edgeJitterL || x > 1018 + edgeJitterR) return false;
  if (y < 112 + edgeJitterT || y > 852 + edgeJitterB) return false;

  // Top-left weathered corner notch
  if (x - 180 + (y - 110) < 75 + (noise(x * 0.05, y * 0.05) - 0.5) * 25) return false;

  // Top-right peeled corner (above the diagonal crease)
  if (x > 685 && y < topRightCreaseY(x)) return false;

  // Bottom-left torn-away region exposing wood grain & knot
  if (y > bottomLeftTearY(x)) return false;

  // Horizontal board gap tear around y = 490
  let seamY = 490 + (noise(x * 0.015, 77.7) - 0.5) * 8;
  if (abs(y - seamY) < seamSplitHalfGap(x)) return false;

  return true;
}

// Clips a line segment to the intact label and draws the visible sub-segments
function drawLabelClippedLine(x1, y1, x2, y2, steps = 28) {
  let inSeg = false;
  let sx = 0, sy = 0;
  for (let i = 0; i <= steps; i++) {
    let t = i / steps;
    let px = lerp(x1, x2, t);
    let py = lerp(y1, y2, t);
    let inside = isInsideLabel(px, py);
    if (inside && !inSeg) {
      sx = px;
      sy = py;
      inSeg = true;
    } else if (!inside && inSeg) {
      let ex = lerp(x1, x2, (i - 1) / steps);
      let ey = lerp(y1, y2, (i - 1) / steps);
      if (dist(sx, sy, ex, ey) > 1.5) brush.line(sx, sy, ex, ey);
      inSeg = false;
    } else if (inside && i === steps && inSeg) {
      if (dist(sx, sy, px, py) > 1.5) brush.line(sx, sy, px, py);
    }
  }
}

// =============================================================================
// 1. WEATHERED PINE CRATE & TABLETOP
// =============================================================================

function drawCrateAndTable() {
  brush.noStroke();

  // Warm pastel parchment & bleached pine base washes
  brush.wash("#EFE4D2", 220);
  brush.rect(45, 40, 1110, 880, "corner");

  // Subtle pastel toning across upper and lower pine boards
  brush.fillBleed(0.22, "out");
  brush.fillTexture(0.55, 0.3);

  // Upper board warm pastel buff & rose-ochre undertone
  brush.fill("#E5D2B8", 110);
  brush.rect(55, 45, 1090, 442, "corner");

  // Lower board slightly deeper weathered honey-grey
  brush.fill("#DEC7AA", 125);
  brush.rect(55, 494, 1090, 426, "corner");

  // Left and right vertical crate end cleats (recessed shadow & thicker wood)
  brush.fill("#D2B99B", 130);
  brush.rect(45, 40, 78, 880, "corner");
  brush.rect(1077, 40, 78, 880, "corner");

  // Tabletop / Ledge (y = 920 to 1200) in soft pastel warm stone & dusty wood
  brush.wash("#E8DDD0", 240);
  brush.rect(0, 920, 1200, 280, "corner");

  brush.fill("#D4C3B3", 115);
  brush.rect(0, 920, 1200, 140, "corner");

  brush.fill("#C2B0A2", 95);
  brush.rect(0, 1040, 1200, 160, "corner");
  brush.noFill();
  brush.noWash();

  // Wood Knots in exposed pine zones:
  // Knot 1: Bottom-left exposed wood under torn label (x=315, y=735)
  // Knot 2: Top-right exposed wood under peeled label (x=905, y=225)
  // Knot 3: Left cleat (x=82, y=340)
  const knots = [
    { x: 315, y: 735, rx: 46, ry: 28, board: 2 },
    { x: 905, y: 225, rx: 38, ry: 24, board: 1 },
    { x: 540, y: 885, rx: 32, ry: 16, board: 2 }
  ];

  // Dry-brushed horizontal pine grain across both boards
  const grainColors = ["#C7AE91", "#B39678", "#9B7C5E", "#7D6045", "#D8C3A8", "#8C7057"];

  for (let board = 1; board <= 2; board++) {
    let yMin = board === 1 ? 48 : 496;
    let yMax = board === 1 ? 485 : 916;

    for (let y = yMin; y <= yMax; y += 3.2) {
      let col = grainColors[ floor(noise(y * 0.15, board * 10) * grainColors.length) ];
      let w = map(noise(y * 0.08, board), 0, 1, 0.55, 1.65);

      // Increase contrast and density of dry-brushed pencil grain in the exposed wood areas
      brush.set(random() < 0.65 ? "woodgrain" : (random() < 0.5 ? "2B" : "cpencil"), col, w);

      let pts = [];
      for (let x = 123; x <= 1077; x += 24) {
        let dy = (noise(x * 0.006, y * 0.03, board) - 0.5) * 14;

        // Displace grain lines organically around wood knots on the same board
        for (let k of knots) {
          if (k.board === board) {
            let dx = x - k.x;
            let distY = y - k.y;
            let nd = sqrt((dx * dx) / (k.rx * k.rx * 3.2) + (distY * distY) / (k.ry * k.ry * 3.2));
            if (nd < 2.2) {
              let push = pow(1 - nd / 2.2, 2) * k.ry * 1.45;
              dy += (distY >= 0 ? 1 : -1) * push;
            }
          }
        }
        let clampY = constrain(y + dy, yMin + 1, yMax - 1);
        let p = 0.4 + 0.8 * noise(x * 0.02, y * 0.05);
        pts.push([x, clampY, p]);
      }
      brush.spline(pts, 0.35);
    }
  }

  // Extra rich dry-brushed graphite & colored pencil grain specifically in the torn/exposed areas
  const extraZones = [
    { x1: 125, x2: 620, y1: 520, y2: 915 }, // Bottom-left tear zone
    { x1: 660, x2: 1075, y1: 50, y2: 465 }, // Top-right peel zone
    { x1: 125, x2: 1075, y1: 472, y2: 512 } // Center seam zone
  ];

  for (let z of extraZones) {
    for (let i = 0; i < 95; i++) {
      let y = random(z.y1, z.y2);
      if (abs(y - 490) < 5) continue;
      let xStart = random(z.x1, z.x2 - 60);
      let len = random(45, 190);
      let xEnd = min(z.x2, xStart + len);

      let dark = random() < 0.45;
      brush.set(
        dark ? "2B" : "cpencil",
        dark ? "#6B513A" : (random() < 0.5 ? "#9E8267" : "#F7EFE2"),
        random(0.5, 1.25)
      );

      let pts = [];
      let board = y < 490 ? 1 : 2;
      for (let x = xStart; x <= xEnd; x += 18) {
        let dy = (noise(x * 0.01, y * 0.04) - 0.5) * 6;
        for (let k of knots) {
          if (k.board === board) {
            let dx = x - k.x;
            let distY = y - k.y;
            let nd = sqrt((dx * dx) / (k.rx * k.rx * 2.8) + (distY * distY) / (k.ry * k.ry * 2.8));
            if (nd < 2.0) {
              dy += (distY >= 0 ? 1 : -1) * pow(1 - nd / 2.0, 2) * k.ry * 1.35;
            }
          }
        }
        pts.push([x, y + dy, random(0.4, 1.1)]);
      }
      if (pts.length >= 2) brush.spline(pts, 0.3);
    }
  }

  // Render the concentric wood knots in detail
  for (let k of knots) {
    brush.noStroke();
    brush.fill("#735339", 160);
    brush.fillBleed(0.15, "out");
    let kPts = [];
    for (let a = 0; a < 360; a += 20) {
      let rMod = 0.85 + 0.3 * noise(cos(a) + 1, sin(a) + 1, k.x);
      kPts.push([k.x + cos(a) * k.rx * 0.65 * rMod, k.y + sin(a) * k.ry * 0.65 * rMod]);
    }
    drawShapePoly(kPts, 0.3);
    brush.noFill();

    for (let ring = 0.2; ring <= 1.35; ring += 0.14) {
      brush.set("2B", ring < 0.7 ? "#4A321F" : "#7E5E44", map(ring, 0.2, 1.35, 1.2, 0.6));
      let rPts = [];
      for (let a = 0; a <= 360; a += 18) {
        let rad = a;
        let n = 0.9 + 0.2 * noise(cos(rad) * 2, sin(rad) * 2, ring * 5);
        rPts.push([k.x + cos(rad) * k.rx * ring * n, k.y + sin(rad) * k.ry * ring * n]);
      }
      drawShapePoly(rPts, 0.4, true);
    }
    // Radial crack inside knot core
    brush.set("rotring", "#2E1C10", 0.8);
    brush.line(k.x - k.rx * 0.3, k.y - 2, k.x + k.rx * 0.3, k.y + 3);
    brush.line(k.x - 3, k.y - k.ry * 0.35, k.x + 2, k.y + k.ry * 0.35);
  }

  // Vertical grain on left and right crate cleats
  for (let side of [ { x1: 46, x2: 122 }, { x1: 1078, x2: 1154 } ]) {
    for (let x = side.x1; x <= side.x2; x += 3.5) {
      let c = grainColors[floor(noise(x * 0.2) * grainColors.length)];
      brush.set("woodgrain", c, random(0.5, 1.2));
      let pts = [];
      for (let y = 42; y <= 918; y += 45) {
        pts.push([x + (noise(x * 0.05, y * 0.01) - 0.5) * 5, y]);
      }
      brush.spline(pts, 0.25);
    }
    // Inner shadow edge of cleat
    let edgeX = side.x1 < 500 ? side.x2 : side.x1;
    brush.set("charcoal", "#594330", 1.4);
    brush.line(edgeX, 42, edgeX, 918);
    brush.set("airbrush", "#4A3728", 0.9);
    brush.line(edgeX + (side.x1 < 500 ? 4 : -4), 45, edgeX + (side.x1 < 500 ? 4 : -4), 915);
  }

  // Weathered nail heads on the side cleats
  const nails = [ [84, 130], [84, 415], [84, 575], [84, 835], [1116, 135], [1116, 420], [1116, 570], [1116, 840] ];
  for (let [nx, ny] of nails) {
    brush.set("airbrush", "#8C583A", 0.7);
    brush.circle(nx, ny + 4, 10, 0.2);
    brush.noStroke();
    brush.wash("#3D2B22", 230);
    brush.circle(nx, ny, 7, 0.15);
    brush.noWash();
    brush.set("2B", "#1F140E", 1.1);
    brush.circle(nx, ny, 7, 0.15);
    brush.set("pen", "#B8A390", 0.7);
    brush.arc(nx, ny, 4.5, 200, 320);
  }

  // Deep shadow gap between the upper and lower pine boards (y = 486..495)
  brush.noStroke();
  brush.wash("#2B1D13", 235);
  brush.rect(122, 486, 956, 9, "corner");
  brush.noWash();
  brush.set("charcoal", "#1A100A", 1.8);
  brush.line(122, 490, 1078, 490);
  brush.set("HB", "#F5E9D6", 0.9);
  brush.line(122, 496, 1078, 496); // Bottom board top-lip highlight

  // Crate bottom edge resting on the tabletop (y = 918)
  brush.set("charcoal", "#2E2018", 2.2);
  brush.line(44, 918, 1156, 918);
  brush.set("airbrush", "#423229", 1.4);
  brush.line(40, 924, 1160, 924);

  // Subtle horizontal wood & stone texture on the foreground tabletop
  for (let y = 928; y <= 1195; y += 5.5) {
    let t = map(y, 928, 1195, 0, 1);
    let col = lerpColor(color("#B8A593"), color("#8F7D6E"), t);
    brush.set(random() < 0.5 ? "woodgrain" : "HB", col, map(t, 0, 1, 0.6, 1.3));
    let yOff = (noise(y * 0.05) - 0.5) * 6;
    brush.line(0, y + yOff, 1200, y - yOff * 0.5);
  }
}

// =============================================================================
// 2. FLAT SATURATED LITHOGRAPHIC LABEL (SUNBURST IN CADMIUM ORANGE & COBALT)
// =============================================================================

function drawLithoLabel() {
  // Build outer intact label boundary points for the paper base wash
  // Top-left -> Top-right crease -> Right edge -> Bottom-right -> Bottom-left tear -> Left edge
  let upperLabelPoly = [];
  for (let x = 250; x <= 685; x += 20) upperLabelPoly.push([x, 112 + (noise(x * 0.03, 3.3) - 0.5) * 10]);
  for (let x = 685; x <= 1018; x += 20) upperLabelPoly.push([x, topRightCreaseY(x)]);
  for (let y = 445; y <= 484; y += 15) upperLabelPoly.push([1018 + (noise(y * 0.03, 2.2) - 0.5) * 10, y]);
  for (let x = 1018; x >= 182; x -= 25) upperLabelPoly.push([x, 490 - seamSplitHalfGap(x)]);
  for (let y = 480; y >= 185; y -= 20) upperLabelPoly.push([182 + (noise(y * 0.03, 1.1) - 0.5) * 10, y]);
  upperLabelPoly.push([250, 112]);

  let lowerLabelPoly = [];
  for (let x = 182; x <= 1018; x += 25) lowerLabelPoly.push([x, 490 + seamSplitHalfGap(x)]);
  for (let y = 500; y <= 852; y += 20) lowerLabelPoly.push([1018 + (noise(y * 0.03, 2.2) - 0.5) * 10, y]);
  for (let x = 1018; x >= 555; x -= 20) lowerLabelPoly.push([x, 852 + (noise(x * 0.03, 4.4) - 0.5) * 10]);
  for (let x = 555; x >= 182; x -= 15) lowerLabelPoly.push([x, min(852, bottomLeftTearY(x))]);
  for (let y = 535; y >= 500; y -= 15) lowerLabelPoly.push([182 + (noise(y * 0.03, 1.1) - 0.5) * 10, y]);

  // Vintage warm cream litho paper base wash
  brush.noStroke();
  brush.wash("#FAF1DF", 242);
  drawShapePoly(upperLabelPoly, 0.05);
  drawShapePoly(lowerLabelPoly, 0.05);
  brush.noWash();

  // Inner graphic frame bounds: x in [224, 976], y in [152, 812]
  const fx1 = 224, fx2 = 976, fy1 = 152, fy2 = 812;
  const sunX = 590, sunY = 485;

  // Clip helper for BOTH the inner litho frame AND the intact torn label
  function isInsideGraphic(x, y) {
    if (x < fx1 || x > fx2 || y < fy1 || y > fy2) return false;
    return isInsideLabel(x, y);
  }

  function drawGraphicClippedLine(x1, y1, x2, y2, steps = 32) {
    let inSeg = false;
    let sx = 0, sy = 0;
    for (let i = 0; i <= steps; i++) {
      let t = i / steps;
      let px = lerp(x1, x2, t);
      let py = lerp(y1, y2, t);
      let inside = isInsideGraphic(px, py);
      if (inside && !inSeg) {
        sx = px;
        sy = py;
        inSeg = true;
      } else if (!inside && inSeg) {
        let ex = lerp(x1, x2, (i - 1) / steps);
        let ey = lerp(y1, y2, (i - 1) / steps);
        if (dist(sx, sy, ex, ey) > 1.5) brush.line(sx, sy, ex, ey);
        inSeg = false;
      } else if (inside && i === steps && inSeg) {
        if (dist(sx, sy, px, py) > 1.5) brush.line(sx, sy, px, py);
      }
    }
  }

  // --- STYLIZED SUNBURST IN CADMIUM ORANGE & COBALT BLUE ---
  // 24 rays (each 15 degrees) radiating from (sunX, sunY)
  const numRays = 24;
  const raySpan = 360 / numRays;

  for (let r = 0; r < numRays; r++) {
    let a1 = r * raySpan - 7.5;
    let a2 = (r + 1) * raySpan - 7.5;
    let isCobalt = r % 2 === 0;

    // Saturated lithographic inks tempered with luminous vintage warmth
    let baseCol = isCobalt ? "#214894" : "#F25C22";
    let glowCol = isCobalt ? "#4E7AC7" : "#FA9442";
    let pastelCol = isCobalt ? "#8FB3E8" : "#FCD088";

    // Sample radial scanlines inside this wedge to render flat litho ink clipped to label & frame
    for (let a = a1 + 0.4; a <= a2 - 0.4; a += 0.55) {
      let dx = cos(a);
      let dy = sin(a);
      // Ray from r=95 out to r=560
      let rStart = 92;
      let rEnd = 560;

      // Inner pastel-gold / periwinkle glow transition (r = 92..210)
      brush.set("marker", pastelCol, 1.35);
      drawGraphicClippedLine(
        sunX + dx * rStart, sunY + dy * rStart,
        sunX + dx * 205, sunY + dy * 205,
        14
      );

      // Mid vibrant cadmium / cobalt zone (r = 185..340)
      brush.set("marker", glowCol, 1.55);
      drawGraphicClippedLine(
        sunX + dx * 185, sunY + dy * 185,
        sunX + dx * 340, sunY + dy * 340,
        16
      );

      // Outer deep saturated lithographic cadmium orange & cobalt blue (r = 310..560)
      brush.set("marker", baseCol, 1.85);
      drawGraphicClippedLine(
        sunX + dx * 310, sunY + dy * 310,
        sunX + dx * rEnd, sunY + dy * rEnd,
        22
      );
    }

    // Crisp vintage cream & gold litho keyline separating each sunburst ray
    brush.set("pen", "#FFF6E3", 1.1);
    drawGraphicClippedLine(sunX + cos(a1) * 94, sunY + sin(a1) * 94, sunX + cos(a1) * 550, sunY + sin(a1) * 550, 30);
    brush.set("rotring", "#172D5E", 0.65);
    drawGraphicClippedLine(sunX + cos(a1 + 0.3) * 98, sunY + sin(a1 + 0.3) * 98, sunX + cos(a1 + 0.3) * 550, sunY + sin(a1 + 0.3) * 550, 30);
  }

  // --- PERIOD AIRBRUSH GLOW (SPRAY-SOFT GRADIENTS) ---
  // Concentric airbrush halos radiating from the sun center and horizon
  const airbrushPasses = [
    { rMin: 75, rMax: 175, col: "#FFF2C9", count: 160, brushName: "airbrush", w: 1.3 },
    { rMin: 130, rMax: 245, col: "#FCA856", count: 190, brushName: "airbrush", w: 1.2 },
    { rMin: 190, rMax: 330, col: "#F26427", count: 170, brushName: "fineSpray", w: 1.1 },
    { rMin: 260, rMax: 430, col: "#85ACE6", count: 160, brushName: "airbrush", w: 1.15 },
    { rMin: 320, rMax: 490, col: "#254B96", count: 150, brushName: "fineSpray", w: 1.1 }
  ];

  for (let pass of airbrushPasses) {
    brush.set(pass.brushName, pass.col, pass.w);
    for (let i = 0; i < pass.count; i++) {
      let ang = random(360);
      let rad = random(pass.rMin, pass.rMax);
      let px = sunX + cos(ang) * rad;
      let py = sunY + sin(ang) * rad;
      if (isInsideGraphic(px, py) && isInsideGraphic(px + cos(ang + 90) * 18, py + sin(ang + 90) * 18)) {
        brush.line(px, py, px + cos(ang + 90) * 18, py + sin(ang + 90) * 18);
      }
    }
  }

  // --- STYLIZED LITHOGRAPHIC HILLS AT BOTTOM OF LABEL ---
  // Rolling cobalt, teal-jade, and cadmium gold orchard hills (y = 635..812)
  for (let y = 635; y <= fy2; y += 2.6) {
    for (let x = fx1; x <= fx2; x += 14) {
      if (!isInsideGraphic(x, y) || !isInsideGraphic(x + 12, y)) continue;
      let hill1 = 665 + sin((x - 220) * 0.42) * 32;
      let hill2 = 715 + cos((x - 300) * 0.38) * 36;
      let hill3 = 762 + sin((x - 180) * 0.5) * 24;

      let col = null;
      if (y > hill3) col = "#193573";       // Deep cobalt foreground hill
      else if (y > hill2) col = "#2B6E68";  // Vintage jade-teal orchard stripe
      else if (y > hill1) col = "#3862AD";  // Soft cobalt-periwinkle mid hill

      if (col) {
        brush.set("marker", col, 1.45);
        brush.line(x, y, x + 13, y);
      }
    }
  }

  // Crisp pastel gold & cream contour lines along the stylized hills
  for (let h = 1; h <= 3; h++) {
    brush.set("pen", h === 2 ? "#FCE5A2" : "#F5823B", 1.3);
    for (let x = fx1; x <= fx2 - 8; x += 8) {
      let y1 = h === 1 ? 665 + sin((x - 220) * 0.42) * 32 : (h === 2 ? 715 + cos((x - 300) * 0.38) * 36 : 762 + sin((x - 180) * 0.5) * 24);
      let x2 = x + 8;
      let y2 = h === 1 ? 665 + sin((x2 - 220) * 0.42) * 32 : (h === 2 ? 715 + cos((x2 - 300) * 0.38) * 36 : 762 + sin((x2 - 180) * 0.5) * 24);
      drawGraphicClippedLine(x, y1, x2, y2, 4);
    }
  }

  // --- CENTRAL IDEALISED COMMERCIAL EMBLEM (SUN-DISC & GRAPHIC ORANGE) ---
  // Flat commercial idealization at (sunX = 590, sunY = 485), radius = 104
  const emblemR = 104;
  for (let y = sunY - emblemR; y <= sunY + emblemR; y += 2.4) {
    let dy = y - sunY;
    let halfW = sqrt(max(0, emblemR * emblemR - dy * dy));
    let xStart = sunX - halfW;
    let xEnd = sunX + halfW;

    // Flat cadmium orange graphic disc with period vertical gradient
    let t = map(y, sunY - emblemR, sunY + emblemR, 0, 1);
    let c = t < 0.35 ? "#FDB750" : (t < 0.72 ? "#F56A25" : "#D9381E");
    brush.set("marker", c, 1.55);
    drawGraphicClippedLine(xStart, y, xEnd, y, 24);
  }

  // Airbrushed pastel highlight on the upper-left of the commercial graphic orange
  brush.set("airbrush", "#FFF3C4", 1.2);
  for (let i = 0; i < 65; i++) {
    let a = random(190, 320);
    let r = random(15, 78);
    let px = sunX + cos(a) * r;
    let py = sunY + sin(a) * r;
    if (isInsideGraphic(px, py)) brush.line(px, py, px + 8, py - 4);
  }

  // Graphic cobalt & cream double ring around the central sun-orange emblem
  for (let ring of [ { r: 108, c: "#FFF7E5", w: 2.2 }, { r: 114, c: "#1B3B7A", w: 2.0 }, { r: 120, c: "#F26427", w: 1.2 } ]) {
    brush.set("pen", ring.c, ring.w);
    for (let a = 0; a < 360; a += 5) {
      let x1 = sunX + cos(a) * ring.r;
      let y1 = sunY + sin(a) * ring.r;
      let x2 = sunX + cos(a + 5) * ring.r;
      let y2 = sunY + sin(a + 5) * ring.r;
      drawGraphicClippedLine(x1, y1, x2, y2, 3);
    }
  }

  // Stylized symmetrical emerald-jade leaves flanking top of the emblem
  for (let dir of [-1, 1]) {
    for (let s = 0; s <= 1; s += 0.04) {
      let lx = sunX + dir * (18 + s * 95);
      let ly = sunY - 96 - sin(s * 180) * 28 + s * 18;
      let halfH = sin(s * 180) * 22;
      brush.set("marker", s < 0.5 ? "#3E967E" : "#1F6657", 1.5);
      drawGraphicClippedLine(lx, ly - halfH, lx, ly + halfH, 6);
    }
    // Leaf vein in cream
    brush.set("pen", "#FFF4D9", 1.1);
    drawGraphicClippedLine(sunX + dir * 18, sunY - 96, sunX + dir * 110, sunY - 78, 12);
  }

  // --- VINTAGE ARCHED BANNER RIBBON AT TOP OF LABEL ---
  // Arched cobalt & cream ribbon from x = 280 to 900 around (590, 560) radius 330..385
  const archCX = 590, archCY = 585;
  for (let r = 328; r <= 388; r += 2.5) {
    let isBorder = r < 334 || r > 382;
    brush.set("marker", isBorder ? "#F26427" : "#183675", 1.6);
    for (let a = 232; a <= 308; a += 1.5) {
      let x1 = archCX + cos(a) * r;
      let y1 = archCY + sin(a) * r;
      let x2 = archCX + cos(a + 1.5) * r;
      let y2 = archCY + sin(a + 1.5) * r;
      drawGraphicClippedLine(x1, y1, x2, y2, 3);
    }
  }

  // Stylized geometric block lettering inside the banner ("SOL D'ORO")
  // Drawn with crisp pastel-gold litho strokes along the arch
  const letterAngles = [-28, -20, -12, -2, 5, 13, 21, 29];
  for (let idx = 0; idx < letterAngles.length; idx++) {
    let ang = 270 + letterAngles[idx];
    let rMid = 358;
    let lx = archCX + cos(ang) * rMid;
    let ly = archCY + sin(ang) * rMid;
    if (!isInsideGraphic(lx, ly)) continue;

    brush.set("marker", "#FDE6A8", 1.5);
    // Block letter glyphs oriented radially
    let ux = cos(ang + 90), uy = sin(ang + 90);
    let vx = cos(ang), vy = sin(ang);

    if (idx === 0 || idx === 5) { // S or R
      drawGraphicClippedLine(lx - ux * 11 - vx * 14, ly - uy * 11 - vy * 14, lx + ux * 11 - vx * 14, ly + uy * 11 - vy * 14, 4);
      drawGraphicClippedLine(lx - ux * 11, ly - uy * 11, lx + ux * 11, ly + uy * 11, 4);
      drawGraphicClippedLine(lx - ux * 11 + vx * 14, ly - uy * 11 + vy * 14, lx + ux * 11 + vx * 14, ly + uy * 11 + vy * 14, 4);
      drawGraphicClippedLine(lx - ux * 11 + vx * 14, ly - uy * 11 + vy * 14, lx - ux * 11, ly - uy * 11, 4);
      drawGraphicClippedLine(lx + ux * 11, ly + uy * 11, lx + ux * 11 - vx * 14, ly + uy * 11 - vy * 14, 4);
    } else if (idx === 1 || idx === 4 || idx === 7) { // O
      for (let s = -10; s <= 10; s += 20) {
        drawGraphicClippedLine(lx + ux * s - vx * 14, ly + uy * s - vy * 14, lx + ux * s + vx * 14, ly + uy * s + vy * 14, 4);
      }
      for (let s = -14; s <= 14; s += 28) {
        drawGraphicClippedLine(lx - ux * 10 + vx * s, ly - uy * 10 + vy * s, lx + ux * 10 + vx * s, ly + uy * 10 + vy * s, 4);
      }
    } else if (idx === 2) { // L
      drawGraphicClippedLine(lx - ux * 10 - vx * 14, ly - uy * 10 - vy * 14, lx - ux * 10 + vx * 14, ly - uy * 10 + vy * 14, 4);
      drawGraphicClippedLine(lx - ux * 10 - vx * 14, ly - uy * 10 - vy * 14, lx + ux * 10 - vx * 14, ly + uy * 10 - vy * 14, 4);
    } else if (idx === 3) { // Apostrophe / Star
      drawGraphicClippedLine(lx, ly + vy * 6, lx, ly + vy * 16, 3);
    } else if (idx === 6) { // R leg
      drawGraphicClippedLine(lx - ux * 10 - vx * 14, ly - uy * 10 - vy * 14, lx - ux * 10 + vx * 14, ly - uy * 10 + vy * 14, 4);
      drawGraphicClippedLine(lx - ux * 10 + vx * 14, ly - uy * 10 + vy * 14, lx + ux * 10 + vx * 6, ly + uy * 10 + vy * 6, 4);
      drawGraphicClippedLine(lx - ux * 10, ly - uy * 10, lx + ux * 10 - vx * 14, ly + uy * 10 - vy * 14, 4);
    }
  }

  // --- OUTER LITHOGRAPHIC BORDER FRAME (COBALT BLUE & CADMIUM ORANGE RULES) ---
  // Thick Cobalt Outer Band (208..224 and 976..992, 136..152 and 812..828)
  for (let offset = 0; offset <= 14; offset += 2.5) {
    let bx1 = 210 + offset, bx2 = 990 - offset;
    let by1 = 138 + offset, by2 = 826 - offset;
    let col = offset < 9 ? "#1D3F8A" : (offset < 12 ? "#FAF1DF" : "#F25C22");
    brush.set("marker", col, 1.5);
    drawLabelClippedLine(bx1, by1, bx2, by1, 45);
    drawLabelClippedLine(bx2, by1, bx2, by2, 45);
    drawLabelClippedLine(bx2, by2, bx1, by2, 45);
    drawLabelClippedLine(bx1, by2, bx1, by1, 45);
  }

  // Subtle vintage paper aging & stain washes over the intact label
  brush.set("airbrush", "#D9C3A0", 1.1);
  for (let i = 0; i < 85; i++) {
    let px = random(190, 1000);
    let py = random(120, 840);
    if (isInsideLabel(px, py)) {
      brush.line(px, py, px + random(-25, 25), py + random(-15, 15));
    }
  }
}

// =============================================================================
// 3. TORN PAPER DECKLE EDGES & 3D PEELING TOP-RIGHT CORNER FLAP
// =============================================================================

function drawTornPaperAndCurl() {
  // --- A. FIBROUS WHITE TORN DECKLE EDGE ALONG BOTTOM-LEFT TEAR ---
  // Where the lithographic layer ripped away, a 6-14px band of fuzzy white paper pulp remains stuck to the pine wood
  for (let x = 182; x <= 558; x += 2.2) {
    let ty = bottomLeftTearY(x);
    if (ty > 852) continue;

    // Cast shadow of torn paper lip onto wood below
    brush.set("HB", "#5E4735", 0.9);
    brush.line(x, ty + 2, x + 3, ty + 6);

    // Fibrous white/cream paper backing deckle
    let deckleW = 6 + noise(x * 0.08, 9.1) * 12;
    brush.set("cpencil", "#FFFDF7", random(0.9, 1.6));
    brush.line(x, ty - 2, x - random(2, 6), ty + deckleW);

    if (random() < 0.6) {
      brush.set("2H", "#E8DEC8", 0.8);
      brush.line(x, ty, x - random(4, 10), ty + deckleW + random(2, 6));
    }
  }

  // --- B. RAGGED PAPER FIBRES ALONG THE CENTER PLANK SEAM (y = 490) ---
  for (let x = 182; x <= 1018; x += 3.5) {
    if (x < 330 && bottomLeftTearY(x) < 495) continue;
    let seamY = 490 + (noise(x * 0.015, 77.7) - 0.5) * 8;
    let gap = seamSplitHalfGap(x);

    // Upper torn lip & lower torn lip
    brush.set("cpencil", "#FBF4E6", random(0.7, 1.3));
    brush.line(x, seamY - gap - 3, x + random(-3, 3), seamY - gap + 2);
    brush.line(x, seamY + gap + 3, x + random(-3, 3), seamY + gap - 2);

    brush.set("2B", "#4A3525", 0.7);
    brush.line(x, seamY - gap + 1, x + 2, seamY - gap + 3);
  }

  // --- C. WEATHERED OUTER EDGES OF THE LABEL ---
  // Left, Top, Right, Bottom outer edges with slight lifting shadow and frayed paper
  for (let y = 185; y <= 535; y += 4) {
    let lx = 182 + (noise(y * 0.03, 1.1) - 0.5) * 14;
    brush.set("2B", "#5C4532", 0.9);
    brush.line(lx - 2, y, lx - 1, y + 4);
    brush.set("cpencil", "#FBF3E4", 1.1);
    brush.line(lx, y, lx + 3, y + 2);
  }
  for (let x = 250; x <= 685; x += 4) {
    let ty = 112 + (noise(x * 0.03, 3.3) - 0.5) * 12;
    brush.set("2B", "#5C4532", 0.85);
    brush.line(x, ty - 2, x + 4, ty - 1);
    brush.set("cpencil", "#FBF3E4", 1.1);
    brush.line(x, ty, x + 2, ty + 3);
  }
  for (let y = 445; y <= 852; y += 4) {
    let rx = 1018 + (noise(y * 0.03, 2.2) - 0.5) * 14;
    brush.set("2B", "#4F3A28", 1.0);
    brush.line(rx + 2, y, rx + 2, y + 4);
    brush.set("cpencil", "#FBF3E4", 1.1);
    brush.line(rx, y, rx - 3, y + 2);
  }

  // --- D. DRAMATIC 3D PEELING TOP-RIGHT CORNER FLAP ---
  // The corner from (685, 110) to (1020, 445) has detached from the dry pine board
  // and curls forward and downward, with its tip drooping to (705, 438).
  const foldTop = [685, 112];
  const foldBot = [1018, 445];
  const curlTip = [702, 438];

  // 1. Cast shadow of the curled paper flap onto the intact label & exposed wood
  let shadowPoly = [];
  for (let t = 0; t <= 1; t += 0.08) {
    let px = bezierPoint(foldTop[0], 675, 670, curlTip[0] - 18, t);
    let py = bezierPoint(foldTop[1], 240, 360, curlTip[1] + 34, t);
    shadowPoly.push([px, py]);
  }
  for (let t = 0; t <= 1; t += 0.08) {
    let px = bezierPoint(curlTip[0] - 18, 820, 935, foldBot[0], t);
    let py = bezierPoint(curlTip[1] + 34, 472, 468, foldBot[1], t);
    shadowPoly.push([px, py]);
  }
  for (let t = 1; t >= 0; t -= 0.1) {
    shadowPoly.push([lerp(foldTop[0], foldBot[0], t), lerp(foldTop[1], foldBot[1], t)]);
  }

  brush.noStroke();
  brush.fill("#1E1610", 115);
  brush.fillBleed(0.28, "out");
  drawShapePoly(shadowPoly, 0.1);
  brush.noFill();

  // Soft airbrushed penumbra along the curl's cast shadow
  brush.set("airbrush", "#1A120C", 1.5);
  for (let t = 0.05; t <= 0.95; t += 0.03) {
    let sx = bezierPoint(foldTop[0], 675, 670, curlTip[0] - 14, t);
    let sy = bezierPoint(foldTop[1], 240, 360, curlTip[1] + 28, t);
    brush.line(sx, sy, sx + 12, sy + 10);
  }
  for (let t = 0.05; t <= 0.95; t += 0.03) {
    let sx = bezierPoint(curlTip[0] - 14, 820, 935, foldBot[0], t);
    let sy = bezierPoint(curlTip[1] + 28, 468, 462, foldBot[1], t);
    brush.line(sx, sy, sx + 12, sy - 6);
  }

  // 2. Build the 3D curled paper flap polygon
  let flapPoly = [];
  // Crease edge (lightly curved inward as the paper rolls in 3D)
  for (let t = 0; t <= 1; t += 0.06) {
    let cx = bezierPoint(foldTop[0], 790, 905, foldBot[0], t);
    let cy = bezierPoint(foldTop[1], 205, 320, foldBot[1], t);
    flapPoly.push([cx, cy]);
  }
  // Bottom curled edge from foldBot to curlTip
  for (let t = 0; t <= 1; t += 0.06) {
    let bx = bezierPoint(foldBot[0], 915, 810, curlTip[0], t);
    let by = bezierPoint(foldBot[1], 448, 452, curlTip[1], t);
    flapPoly.push([bx, by]);
  }
  // Left curled edge from curlTip back up to foldTop
  for (let t = 0; t <= 1; t += 0.06) {
    let lx = bezierPoint(curlTip[0], 688, 682, foldTop[0], t);
    let ly = bezierPoint(curlTip[1], 335, 225, foldTop[1], t);
    flapPoly.push([lx, ly]);
  }

  // Opaque warm cream-buff paper backing wash
  brush.noStroke();
  brush.wash("#F3E8D2", 248);
  drawShapePoly(flapPoly, 0.08);
  brush.noWash();

  // Cylindrical 3D shading across the curled paper flap (parallel to the diagonal crease)
  for (let u = 0.02; u <= 0.98; u += 0.018) {
    // u = 0 is at the crease, u = 1 is at the curlTip
    // Connect point on left edge to point on bottom edge
    let x1 = bezierPoint(foldTop[0], 682, 688, curlTip[0], u);
    let y1 = bezierPoint(foldTop[1], 225, 335, curlTip[1], u);
    let x2 = bezierPoint(foldBot[0], 915, 810, curlTip[0], u);
    let y2 = bezierPoint(foldBot[1], 448, 452, curlTip[1], u);

    // Cylindrical light falloff: bright highlight near u=0.28, warm shadow near crease (u<0.15) and tip (u>0.7)
    let shadeCol;
    if (u < 0.16) shadeCol = "#D4C2A5";
    else if (u < 0.42) shadeCol = "#FFFDF7";
    else if (u < 0.72) shadeCol = "#E8D9BE";
    else shadeCol = "#C9B495";

    brush.set("cpencil", shadeCol, 1.4);
    brush.line(x1, y1, x2, y2);

    // Faint ghosted bleed-through of the cobalt blue & cadmium orange litho print on the reverse side
    if (u > 0.2 && u < 0.85 && int(u * 100) % 2 === 0) {
      let bleedCol = int(u * 25) % 2 === 0 ? "#B8C7DE" : "#F2C6A7";
      brush.set("HB", bleedCol, 0.9);
      brush.line(lerp(x1, x2, 0.15), lerp(y1, y2, 0.15), lerp(x1, x2, 0.85), lerp(y1, y2, 0.85));
    }
  }

  // Crisp paper thickness & fibrous deckle along the curled edges
  brush.set("2B", "#8C775E", 1.1);
  let curlOutline = [];
  for (let t = 0; t <= 1; t += 0.06) {
    curlOutline.push([
      bezierPoint(foldTop[0], 682, 688, curlTip[0], t),
      bezierPoint(foldTop[1], 225, 335, curlTip[1], t)
    ]);
  }
  for (let t = 0; t <= 1; t += 0.06) {
    curlOutline.push([
      bezierPoint(curlTip[0], 810, 915, foldBot[0], t),
      bezierPoint(curlTip[1], 452, 448, foldBot[1], t)
    ]);
  }
  brush.spline(curlOutline, 0.25);

  brush.set("gloss", "#FFFDF9", 1.0);
  let highlightOutline = [];
  for (let t = 0.05; t <= 0.95; t += 0.08) {
    highlightOutline.push([
      bezierPoint(foldTop[0], 682, 688, curlTip[0], t) + 2,
      bezierPoint(foldTop[1], 225, 335, curlTip[1], t) - 1
    ]);
  }
  brush.spline(highlightOutline, 0.25);
}

// =============================================================================
// 4. WHOLE TILTED BLOOD ORANGE (RESTING AGAINST CRATE BEHIND CUT HALF)
// =============================================================================

function drawBackOrange(cx, cy, r) {
  // Cast shadow on tabletop & against crate
  brush.noStroke();
  brush.fill("#2B1A14", 150);
  brush.fillBleed(0.25, "out");
  let shPts = [];
  for (let a = 0; a < 360; a += 18) {
    shPts.push([cx - 25 + cos(a) * r * 0.95, cy + r * 0.88 + sin(a) * 32]);
  }
  drawShapePoly(shPts, 0.3);
  brush.noFill();

  // Warm subsurface scattering orange-red glow in the shadow
  brush.set("airbrush", "#9E2A1B", 1.4);
  for (let i = 0; i < 35; i++) {
    brush.line(cx - 80 + random(140), cy + r * 0.82 + random(-8, 12), cx - 40 + random(120), cy + r * 0.88 + random(-5, 15));
  }

  // Base silhouette of the whole blood orange (slightly oblate spheroid)
  let orangePts = [];
  for (let a = 0; a < 360; a += 10) {
    let radMod = 1.0 + 0.025 * sin(a * 3) + 0.015 * noise(cos(a) * 2, sin(a) * 2);
    orangePts.push([cx + cos(a) * r * 1.03 * radMod, cy + sin(a) * r * 0.97 * radMod]);
  }

  brush.noStroke();
  brush.wash("#E85C25", 248);
  drawShapePoly(orangePts, 0.3);
  brush.noWash();

  // Layered spherical shading: pastel apricot top-left light -> cadmium orange -> deep crimson anthocyanin blush
  for (let ring = 0.98; ring >= 0.08; ring -= 0.032) {
    // Shift center toward top-left highlight (cx - 52, cy - 58)
    let lx = lerp(cx, cx - 52, 1 - ring);
    let ly = lerp(cy, cy - 58, 1 - ring);
    let col;
    if (ring > 0.82) col = "#8C1822";        // Deep crimson-maroon lower/outer blush
    else if (ring > 0.62) col = "#C42926";   // Blood-orange crimson blush
    else if (ring > 0.38) col = "#EC6324";   // Rich cadmium orange
    else if (ring > 0.18) col = "#FA9C4B";   // Luminous apricot
    else col = "#FDE09B";                    // Pastel peach-gold highlight

    brush.set("cpencil", col, 1.8);
    let cPts = [];
    for (let a = 0; a <= 360; a += 12) {
      let rx = r * 1.02 * ring;
      let ry = r * 0.96 * ring;
      let px = lx + cos(a) * rx;
      let py = ly + sin(a) * ry;
      if (dist(px, py, cx, cy) < r * 0.99) {
        cPts.push([px, py]);
      }
    }
    if (cPts.length > 3) brush.spline(cPts, 0.35);
  }

  // Characteristic blood-orange irregular crimson-violet mottling patch on the rind
  brush.set("airbrush", "#6E0E1D", 1.35);
  for (let i = 0; i < 110; i++) {
    let a = random(-35, 155);
    let d = random(r * 0.25, r * 0.92);
    let px = cx + cos(a) * d;
    let py = cy + sin(a) * d * 0.95;
    brush.line(px, py, px + random(-14, 14), py + random(-14, 14));
  }

  // Hyperreal Citrus Rind Pores (Oil Glands): hundreds of tiny dimples with dark pore & lit rim
  for (let i = 0; i < 420; i++) {
    let a = random(360);
    let d = sqrt(random()) * r * 0.94;
    let px = cx + cos(a) * d * 1.02;
    let py = cy + sin(a) * d * 0.96;

    let distToLight = dist(px, py, cx - 55, cy - 60);
    let poreCol = distToLight < r * 0.6 ? "#B5381A" : "#4A0812";
    brush.set("rotring", poreCol, random(0.65, 1.15));
    brush.line(px, py, px + 1.5, py + 1.2);

    // Specular micro-rim on pores in the lit upper-left zone
    if (distToLight < r * 0.65 && random() < 0.6) {
      brush.set("pen", "#FFF3C7", 0.7);
      brush.line(px + 1.5, py + 1.5, px + 3, py + 2.2);
    }
  }

  // Stem Calyx (Greenish-ochre woody button on upper-left shoulder at (cx - 68, cy - 72))
  let sx = cx - 68, sy = cy - 72;
  // Radial creases around calyx
  brush.set("2B", "#942916", 0.85);
  for (let a = 0; a < 360; a += 28) {
    brush.line(sx + cos(a) * 8, sy + sin(a) * 7, sx + cos(a) * 26, sy + sin(a) * 22);
  }
  brush.noStroke();
  brush.wash("#6B7042", 240);
  brush.circle(sx, sy, 13, 0.25);
  brush.noWash();
  brush.set("2B", "#3B3E20", 1.1);
  brush.circle(sx, sy, 13, 0.25);
  brush.set("cpencil", "#B8B07A", 1.0);
  brush.circle(sx - 2, sy - 2, 6, 0.2);
}

// =============================================================================
// 5. HERO CUT BLOOD ORANGE HALF (HYPERREAL SEGMENTS, PITH, WET GLISTEN & JUICE DROP)
// =============================================================================

function drawCutBloodOrange(cx, cy, rx, ry) {
  // --- A. CAST SHADOW & SUBSURFACE SCATTERING ON TABLETOP ---
  brush.noStroke();
  brush.fill("#1C0E0B", 175);
  brush.fillBleed(0.25, "out");
  let shPoly = [];
  for (let a = 0; a < 360; a += 15) {
    shPoly.push([cx + 10 + cos(a) * rx * 1.02, cy + ry * 0.96 + sin(a) * 38]);
  }
  drawShapePoly(shPoly, 0.3);
  brush.noFill();

  // Ambient crimson-amber bounce light on the table in front of the cut face
  brush.set("airbrush", "#B82520", 1.5);
  for (let i = 0; i < 55; i++) {
    let sx = cx + random(-rx * 0.75, rx * 0.75);
    let sy = cy + ry * 0.92 + random(-6, 26);
    brush.line(sx, sy, sx + random(-25, 25), sy + random(-4, 6));
  }

  // --- B. LOWER-RIGHT OUTER RIND CRESCENT (3D RIM OF THE HEMISPHERE) ---
  // Because the cut face is tilted slightly upward toward the viewer, we see a crescent of outer peel
  let rimPts = [];
  for (let a = -25; a <= 205; a += 8) {
    let thick = map(sin(a), -0.4, 1, 4, 24);
    rimPts.push([cx + cos(a) * (rx + thick * 0.55), cy + sin(a) * (ry + thick)]);
  }
  for (let a = 205; a >= -25; a -= 8) {
    rimPts.push([cx + cos(a) * rx * 0.98, cy + sin(a) * ry * 0.98]);
  }

  brush.noStroke();
  brush.wash("#C7321D", 248);
  drawShapePoly(rimPts, 0.25);
  brush.noWash();

  // Texture and crimson shading on the visible outer rind rim
  for (let a = -20; a <= 200; a += 2.2) {
    let thick = map(sin(a), -0.4, 1, 4, 24);
    let x1 = cx + cos(a) * (rx - 2);
    let y1 = cy + sin(a) * (ry - 2);
    let x2 = cx + cos(a) * (rx + thick * 0.55);
    let y2 = cy + sin(a) * (ry + thick);
    let col = a > 35 && a < 145 ? "#6E0F1B" : "#E35322";
    brush.set("cpencil", col, 1.3);
    brush.line(x1, y1, x2, y2);

    if (random() < 0.5) {
      brush.set("rotring", "#3D060D", 0.8);
      brush.line(lerp(x1, x2, 0.6), lerp(y1, y2, 0.6), lerp(x1, x2, 0.6) + 1.5, lerp(y1, y2, 0.6) + 1.5);
    }
  }

  // --- C. CUT FACE: OUTER RIND ZEST LINE & WHITE PITH (ALBEDO) ---
  // Subtle organic lobing corresponding to the 10 internal carpels
  const numSegs = 10;
  const segAngles = [0, 35, 72, 109, 144, 181, 217, 253, 289, 325, 360];

  function outerFaceRadius(ang) {
    let lobe = sin(ang * numSegs) * 2.5 + (noise(cos(ang) * 2 + 5, sin(ang) * 2 + 5) - 0.5) * 6;
    return 1.0 + lobe / 220;
  }

  let cutFacePoly = [];
  let zestPoly = [];
  for (let a = 0; a < 360; a += 6) {
    let m = outerFaceRadius(a);
    zestPoly.push([cx + cos(a) * rx * m, cy + sin(a) * ry * m]);
    cutFacePoly.push([cx + cos(a) * (rx - 4.5) * m, cy + sin(a) * (ry - 4.5) * m]);
  }

  // Thin bright cadmium zest rim around the cut face
  brush.noStroke();
  brush.wash("#F26822", 245);
  drawShapePoly(zestPoly, 0.25);

  // Creamy spongy white pith (albedo) base across the entire cut face
  brush.wash("#FCF5E8", 252);
  drawShapePoly(cutFacePoly, 0.25);
  brush.noWash();

  // Radial fibrous pith texture & crimson-magenta juice staining along the inner pith ring
  for (let a = 0; a < 360; a += 1.2) {
    let m = outerFaceRadius(a);
    let rOuter = 0.975 * m;
    let rInner = 0.845 * m;

    let xOut = cx + cos(a) * rx * rOuter;
    let yOut = cy + sin(a) * ry * rOuter;
    let xMid = cx + cos(a) * rx * ((rOuter + rInner) * 0.5);
    let yMid = cy + sin(a) * ry * ((rOuter + rInner) * 0.5);
    let xIn = cx + cos(a) * rx * rInner;
    let yIn = cy + sin(a) * ry * rInner;

    // Fine spongy cream/warm-grey pith fibres
    brush.set(random() < 0.6 ? "2H" : "cpencil", random() < 0.5 ? "#E6D8C3" : "#FFFDF9", random(0.6, 1.1));
    brush.line(xOut, yOut, xIn, yIn);

    // Anthocyanin magenta-crimson stain bleeding from the blood-orange segments into the white pith
    if (noise(a * 0.08, 19.4) > 0.32) {
      let stainCol = random() < 0.5 ? "#D95F76" : "#B82843";
      brush.set("cpencil", stainCol, random(0.7, 1.25));
      brush.line(xMid, yMid, xIn, yIn);
    }
  }

  // --- D. 10 GLISTENING CRIMSON-AND-AMBER SEGMENTS (CARPELS) ---
  for (let s = 0; s < numSegs; s++) {
    let aStart = segAngles[s] + 2.1;
    let aEnd = segAngles[s + 1] - 2.1;
    let aMid = (aStart + aEnd) * 0.5;
    let span = aEnd - aStart;

    // Build curved wedge polygon for this carpel with rounded outer corners and tapered inner tip
    let segPts = [];
    let rTip = 22 + (noise(s * 3.1) - 0.5) * 6;

    // Inner tip rounded curve
    segPts.push([cx + cos(aStart + 3) * (rTip + 8), cy + sin(aStart + 3) * (rTip + 8)]);
    segPts.push([cx + cos(aMid) * rTip, cy + sin(aMid) * rTip]);
    segPts.push([cx + cos(aEnd - 3) * (rTip + 8), cy + sin(aEnd - 3) * (rTip + 8)]);

    // Right radial septum wall out to outer arc
    for (let r = rTip + 18; r <= 168; r += 25) {
      let bow = sin(map(r, rTip, 175, 0, 180)) * 1.2;
      segPts.push([cx + cos(aEnd + bow) * (r / 220) * rx, cy + sin(aEnd + bow) * (r / 220) * ry]);
    }

    // Outer rounded carpel back (tangential curve from aEnd to aStart)
    for (let a = aEnd; a >= aStart; a -= 3.5) {
      // Round off the corners near aStart and aEnd
      let cornerDist = min(abs(a - aStart), abs(aEnd - a));
      let cornerPull = cornerDist < 8 ? pow((8 - cornerDist) / 8, 2) * 16 : 0;
      let rOuter = (186 - cornerPull + (noise(a * 0.1, s) - 0.5) * 4) / 220;
      segPts.push([cx + cos(a) * rx * rOuter, cy + sin(a) * ry * rOuter]);
    }

    // Left radial septum wall back to inner tip
    for (let r = 168; r >= rTip + 18; r -= 25) {
      let bow = -sin(map(r, rTip, 175, 0, 180)) * 1.2;
      segPts.push([cx + cos(aStart + bow) * (r / 220) * rx, cy + sin(aStart + bow) * (r / 220) * ry]);
    }

    // 1. Deep ruby-crimson base wash for the segment
    brush.noStroke();
    brush.wash("#590816", 248);
    drawShapePoly(segPts, 0.18);
    brush.noWash();

    // 2. Variegated watercolor & airbrush glow inside the segment (crimson + fiery amber streaks)
    // Blood oranges have dramatic amber-gold sectors beside deep oxblood-ruby sectors
    let amberAngle = aStart + span * (0.25 + 0.5 * noise(s * 7.7));
    for (let rNorm = 0.16; rNorm <= 0.81; rNorm += 0.045) {
      let cornerRound = rNorm > 0.74 ? map(rNorm, 0.74, 0.82, 0, 4.5) : 0;
      for (let a = aStart + 1.5 + cornerRound; a <= aEnd - 1.5 - cornerRound; a += 2.2) {
        let px = cx + cos(a) * rx * rNorm;
        let py = cy + sin(a) * ry * rNorm;

        // Determine color of this pulp vesicle:
        // Outer perimeter & septum edges are darker oxblood/ruby; mid & inner zones have glowing crimson, coral, and amber!
        let distFromAmber = abs(a - amberAngle);
        let nVal = noise(a * 0.15, rNorm * 8, s * 10);

        let vCol;
        if (rNorm > 0.75 || a < aStart + 3.2 || a > aEnd - 3.2) {
          vCol = nVal < 0.5 ? "#3D040E" : "#6E0B1C"; // Deep oxblood-ruby shadow crevices
        } else if (distFromAmber < span * 0.24 && rNorm < 0.68 && nVal > 0.32) {
          vCol = nVal > 0.62 ? "#F7B940" : "#EB7823"; // Luminous amber-gold vesicles!
        } else if (rNorm < 0.36 && nVal > 0.4) {
          vCol = "#F05633"; // Bright fiery blood-coral near center
        } else if (nVal > 0.58) {
          vCol = "#D41E30"; // Vivid glistening crimson
        } else {
          vCol = "#8F0E22"; // Rich ruby-garnet
        }

        // Orient each teardrop juice vesicle radially (curving slightly along the carpel wall)
        let vLen = map(rNorm, 0.15, 0.82, 7, 14);
        let vAng = a + (a - aMid) * 0.12 + (noise(px * 0.05, py * 0.05) - 0.5) * 8;
        let x2 = px + cos(vAng) * vLen;
        let y2 = py + sin(vAng) * vLen;

        brush.set("vesicle", vCol, map(rNorm, 0.15, 0.82, 0.75, 1.25));
        brush.line(px, py, x2, y2);

        // Dark micro-crevice between adjacent juice vesicles for startling 3D cellular depth
        if (random() < 0.45) {
          brush.set("pen", "#2B0209", 0.55);
          brush.line(px + cos(vAng + 90) * 1.8, py + sin(vAng + 90) * 1.8, x2 + cos(vAng + 90) * 1.8, y2 + sin(vAng + 90) * 1.8);
        }
      }
    }

    // 3. Second layer of translucent glowing vesicles & fine pulp hairs
    for (let i = 0; i < 42; i++) {
      let rNorm = random(0.18, 0.76);
      let a = random(aStart + 3, aEnd - 3);
      let px = cx + cos(a) * rx * rNorm;
      let py = cy + sin(a) * ry * rNorm;
      let isAmber = abs(a - amberAngle) < span * 0.22 && rNorm < 0.65;
      let col = isAmber ? (random() < 0.5 ? "#FCE07E" : "#F59633") : (random() < 0.5 ? "#E6353B" : "#B31228");
      brush.set("cpencil", col, random(0.8, 1.35));
      let len = random(6, 13);
      brush.line(px, py, px + cos(a) * len, py + sin(a) * len);
    }
  }

  // --- E. RADIAL SEPTUM MEMBRANES & FIBROUS CENTRAL COLUMELLA (CORE) ---
  // Draw the 10 fibrous white/cream pith membranes dividing the segments
  for (let s = 0; s < numSegs; s++) {
    let a = segAngles[s];
    // Pink/crimson juice bleed along the edges of each septum membrane
    for (let side of [-1.2, 1.2]) {
      brush.set("cpencil", "#C94058", 0.95);
      let pts = [];
      for (let r = 18; r <= 188; r += 18) {
        let bow = sin(map(r, 18, 188, 0, 180)) * 1.1;
        let ang = a + side + bow;
        pts.push([cx + cos(ang) * (r / 220) * rx, cy + sin(ang) * (r / 220) * ry]);
      }
      brush.spline(pts, 0.3);
    }

    // Creamy-white fibrous septum line
    for (let pass = 0; pass < 3; pass++) {
      brush.set(pass === 2 ? "pen" : "cpencil", pass === 0 ? "#E8D7C0" : "#FFFDF9", pass === 0 ? 1.35 : 0.85);
      let pts = [];
      for (let r = 14; r <= 190; r += 14) {
        let jitter = (noise(r * 0.08, s * 5, pass) - 0.5) * 2.2;
        let ang = a + jitter;
        pts.push([cx + cos(ang) * (r / 220) * rx, cy + sin(ang) * (r / 220) * ry, random(0.6, 1.2)]);
      }
      brush.spline(pts, 0.3);
    }

    // Tiny frayed pith fibrils branching off the septum into the juicy flesh
    brush.set("2H", "#FCEEE2", 0.65);
    for (let r = 28; r <= 178; r += 7) {
      let bx = cx + cos(a) * (r / 220) * rx;
      let by = cy + sin(a) * (r / 220) * ry;
      let dir = random() < 0.5 ? 1 : -1;
      let fAng = a + dir * random(25, 65);
      brush.line(bx, by, bx + cos(fAng) * random(3, 6.5), by + sin(fAng) * random(3, 6.5));
    }
  }

  // Central irregular fibrous white pith core (columella)
  let corePts = [];
  for (let a = 0; a < 360; a += 12) {
    // Star-like spikes pointing into the 10 septum walls
    let spike = pow(max(0, cos((a - 2) * numSegs)), 2) * 11;
    let rCore = 15 + spike + (noise(cos(a) * 2, sin(a) * 2) - 0.5) * 5;
    corePts.push([cx + cos(a) * rCore, cy + sin(a) * rCore]);
  }
  brush.noStroke();
  brush.wash("#FCF6EA", 250);
  drawShapePoly(corePts, 0.25);
  brush.noWash();

  // Spongy shading & crimson staining around the central core
  for (let i = 0; i < 65; i++) {
    let a = random(360);
    let r1 = random(4, 14);
    let r2 = r1 + random(5, 11);
    let col = r1 < 7 ? "#C4AF97" : (random() < 0.45 ? "#E06C7E" : "#FFFDF9");
    brush.set("cpencil", col, random(0.7, 1.1));
    brush.line(cx + cos(a) * r1, cy + sin(a) * r1, cx + cos(a) * r2, cy + sin(a) * r2);
  }
  // Tiny hollow natural cleft at the exact center of the pith core
  brush.set("2B", "#6B423B", 1.1);
  brush.line(cx - 5, cy - 2, cx + 4, cy + 3);
  brush.line(cx - 2, cy + 4, cx + 3, cy - 4);

  // --- F. STARTLING HYPERREAL JUICINESS: WET SPECULAR HIGHLIGHTS ---
  // 1. Crisp, dazzling white & pale-lemon specular reflections on individual swollen vesicles
  for (let s = 0; s < numSegs; s++) {
    let aStart = segAngles[s] + 3.5;
    let aEnd = segAngles[s + 1] - 3.5;

    // Liquid meniscus highlights pooling right alongside the septum membranes and outer carpel wall
    for (let rNorm = 0.22; rNorm <= 0.76; rNorm += 0.085) {
      if (random() < 0.75) {
        let sideA = random() < 0.5 ? aStart + random(1.2, 3.5) : aEnd - random(1.2, 3.5);
        let hx = cx + cos(sideA) * rx * rNorm;
        let hy = cy + sin(sideA) * ry * rNorm;
        brush.set("gloss", "#FFFFFF", random(0.85, 1.45));
        brush.line(hx, hy, hx + cos(sideA) * random(5, 11), hy + sin(sideA) * random(5, 11));
      }
    }

    // Wet curved bead & crescent glints across the plump vesicles (denser on upper & mid-left lit side)
    let glintCount = (s >= 4 && s <= 9) ? 28 : 19;
    for (let i = 0; i < glintCount; i++) {
      let rNorm = random(0.2, 0.77);
      let a = random(aStart + 2, aEnd - 2);
      let gx = cx + cos(a) * rx * rNorm;
      let gy = cy + sin(a) * ry * rNorm;

      // Soft pink-amber halo under the brightest glints
      if (random() < 0.5) {
        brush.set("cpencil", "#FFCFD2", 1.2);
        brush.line(gx - 1, gy - 1, gx + cos(a) * 5, gy + sin(a) * 5);
      }

      // Razor-sharp wet white specular highlight
      brush.set("gloss", random() < 0.8 ? "#FFFFFF" : "#FFFCE6", random(0.7, 1.4));
      let len = random(2.5, 7.5);
      let curveA = a + random(-15, 15);
      brush.line(gx, gy, gx + cos(curveA) * len, gy + sin(curveA) * len);

      // Pinpoint sparkle dot next to elongated highlight
      if (random() < 0.45) {
        brush.set("gloss", "#FFFFFF", 1.1);
        brush.line(gx + cos(curveA) * (len + 3), gy + sin(curveA) * (len + 3), gx + cos(curveA) * (len + 4.2), gy + sin(curveA) * (len + 4.2));
      }
    }
  }

  // --- G. RUNNING JUICE DROP & GLOSSY CRIMSON PUDDLE ---
  // Located at the bottom of the lowest segment (around angle 86 degrees, x = cx + 14)
  let dropX = cx + 14;
  let streamTopY = cy + ry * 0.76;   // Starts inside bottom segment
  let streamMidY = cy + ry * 0.98;   // Crosses white pith & zest rim
  let hangDropY = cy + ry + 20;      // Bulging hanging drop at bottom of rind

  // 1. Translucent crimson-amber juice rivulet running down across the white pith
  for (let y = streamTopY; y <= hangDropY - 8; y += 2.2) {
    let w = map(y, streamTopY, hangDropY - 8, 3.5, 7.5);
    let curveX = dropX + sin((y - streamTopY) * 3.5) * 1.8;

    // Warm ruby-amber refractive trail
    brush.set("vesicle", y < streamMidY ? "#C91E2E" : "#E33B29", 1.1);
    brush.line(curveX - w * 0.5, y, curveX + w * 0.5, y);

    // Dark ruby left shadow edge of rivulet
    brush.set("pen", "#5E0714", 0.7);
    brush.line(curveX - w * 0.55, y, curveX - w * 0.55, y + 2);

    // Glowing golden-coral caustic right edge
    brush.set("pen", "#FA9D3E", 0.75);
    brush.line(curveX + w * 0.45, y, curveX + w * 0.45, y + 2);
  }

  // Wet specular line running down the center of the juice stream
  brush.set("gloss", "#FFFFFF", 1.05);
  brush.line(dropX - 1, streamTopY + 5, dropX, hangDropY - 12);

  // 2. Plump 3D Hanging Juice Drop at (dropX, hangDropY)
  let dropPts = [];
  for (let a = 0; a < 360; a += 15) {
    // Teardrop profile: tapered at top, round and heavy at bottom
    let radX = 11.5 * (1 + 0.18 * sin(a));
    let radY = 14.5;
    dropPts.push([dropX + cos(a) * radX, hangDropY + sin(a) * radY]);
  }
  brush.noStroke();
  brush.wash("#8F0D1E", 242);
  drawShapePoly(dropPts, 0.3);
  brush.noWash();

  // Internal caustic amber-coral glow at the lower-right of the hanging drop
  brush.set("vesicle", "#EB4728", 1.3);
  brush.circle(dropX + 2, hangDropY + 3, 6.5, 0.1);
  brush.set("cpencil", "#FCD05B", 1.2);
  brush.line(dropX + 1, hangDropY + 6, dropX + 6, hangDropY + 4);

  // Dark oxblood upper-left refraction inside drop
  brush.set("pen", "#3B030B", 1.1);
  brush.arc(dropX, hangDropY, 9.5, 175, 340);

  // Dazzling white primary specular highlight & bottom secondary reflection on the hanging drop
  brush.set("gloss", "#FFFFFF", 1.55);
  brush.arc(dropX - 1, hangDropY - 1, 7.5, 195, 265);
  brush.set("gloss", "#FFFFFF", 1.2);
  brush.line(dropX - 4, hangDropY - 7, dropX - 2, hangDropY - 8);
  brush.set("gloss", "#FFE8B8", 0.85);
  brush.arc(dropX, hangDropY + 1, 9.5, 25, 85);

  // 3. Glossy Fallen Juice Puddle & Stray Pulp Vesicles on the Tabletop Below (y = cy + ry + 48)
  let pudX = dropX + 4;
  let pudY = cy + ry + 50;

  // Dark shadow rim under the meniscus of the puddle
  brush.set("pen", "#38040C", 1.1);
  let pudPts = [];
  for (let a = 0; a < 360; a += 12) {
    let prx = 46 + (noise(cos(a) * 2, sin(a) * 2) - 0.5) * 12;
    let pry = 12.5 + (noise(sin(a) * 2, cos(a) * 2) - 0.5) * 3.5;
    pudPts.push([pudX + cos(a) * prx, pudY + sin(a) * pry]);
  }
  brush.noStroke();
  brush.wash("#7A0B1B", 225);
  drawShapePoly(pudPts, 0.3);
  brush.noWash();

  // Translucent ruby & glowing amber caustic core inside the puddle
  for (let r = 0.85; r >= 0.2; r -= 0.18) {
    brush.set("vesicle", r > 0.5 ? "#B81929" : "#EB5E28", 1.25);
    let innerPts = [];
    for (let a = 0; a <= 360; a += 18) {
      innerPts.push([pudX + 4 * (1 - r) + cos(a) * 42 * r, pudY + 1.5 * (1 - r) + sin(a) * 10.5 * r]);
    }
    brush.spline(innerPts, 0.35);
  }
  brush.set("cpencil", "#FAD161", 1.15);
  brush.line(pudX + 2, pudY + 2, pudX + 18, pudY + 2);

  // Crisp white liquid meniscus highlight along the puddle rim
  brush.set("gloss", "#FFFFFF", 1.35);
  brush.line(pudX - 28, pudY - 6, pudX + 12, pudY - 8);
  brush.line(pudX + 18, pudY - 6, pudX + 26, pudY - 4);
  brush.set("gloss", "#FFF7D6", 0.95);
  brush.line(pudX - 18, pudY + 8, pudX + 22, pudY + 7);

  // Two tiny glistening fallen juice vesicles resting on the wood beside the orange
  for (let v of [ { x: cx - 105, y: cy + ry + 32, ang: 14, col: "#D4202F" }, { x: pudX + 64, y: pudY - 4, ang: -18, col: "#EB6A24" } ]) {
    brush.set("pen", "#2E080E", 0.9);
    brush.line(v.x - 5, v.y + 3, v.x + 8, v.y + 3);
    brush.set("vesicle", v.col, 1.4);
    brush.line(v.x - 6, v.y, v.x + 7, v.y + sin(v.ang) * 3);
    brush.set("gloss", "#FFFFFF", 1.0);
    brush.line(v.x - 3, v.y - 1.5, v.x + 3, v.y - 1);
  }
}

// Hyperrealistic study: Rusted barbed wire on a weathered fence post,
// encrusted on the windward side with feathery, wind-aligned rime ice crystals.

const WIND_ANGLE = -34; // Windward growth direction (degrees, pointing upper-right)
const WIRE_STAPLE_X = 284;
const WIRE_STAPLE_Y = 538;
const BARB_POSITIONS = [118, 438, 756, 1052];

async function setup() {
  createCanvas(1200, 1200, WEBGL);
  angleMode(DEGREES);
  randomSeed(8472);
  noiseSeed(8472);

  // Scale built-in brushes for 1200x1200 canvas
  brush.scaleBrushes(3);

  // Custom feather-fine etching needle for crystal spines and barb facets
  brush.add("needle", {
    type: "default",
    weight: 0.22,
    scatter: 0.04,
    sharpness: 0.94,
    grain: 0.18,
    opacity: 215,
    spacing: 0.12,
    pressure: [1.0, 0.75, 0.08],
    rotate: "natural",
    noise: 0.15
  });

  // Custom razor-sharp white highlight pen for brittle ice edges
  brush.add("ice_edge", {
    type: "default",
    weight: 0.30,
    scatter: 0.03,
    sharpness: 0.96,
    grain: 0.22,
    opacity: 250,
    spacing: 0.1,
    pressure: [0.35, 1.0, 0.05],
    rotate: "natural",
    noise: 0.1
  });

  // Custom micro-stipple for crystalline hoarfrost dust and rust flecks
  brush.add("frost_dust", {
    type: "spray",
    weight: 0.35,
    scatter: 1.4,
    opacity: 150,
    spacing: 0.65,
    pressure: [0.8, 1.0, 0.4],
    rotate: "random"
  });
}

function draw() {
  translate(-width / 2, -height / 2);

  // Toned pearl-slate grey paper ground
  background("#abb4c2");

  // 1. Flat soft charcoal fog background & directional atmospheric rhythm
  drawFogAtmosphere();

  // 2. Distant ghostly fence post & wire receding in the winter fog
  drawDistantGhostFence();

  // 3. Foreground weathered wooden fence post (left anchor)
  drawFencePost();

  // 4. Windward rime ice comb along the right edge & top of the fence post
  drawPostRimeComb();

  // 5. Windward rime ice on the wire (Pass 1 & 2: translucent blue-violet mass & lattice)
  const wirePlumes = generateWireRimePlumes();
  drawRimeUnderlayer(wirePlumes);
  drawRimeMidLattice(wirePlumes);

  // 6. Rusted double-strand barbed wire, U-staple, and 4-point barbs
  drawBarbedWireStrand();
  drawFenceStaple(WIRE_STAPLE_X, WIRE_STAPLE_Y);
  for (let bx of BARB_POSITIONS) {
    drawBarbCluster(bx);
  }

  // 7. Windward rime ice (Pass 3: razor-sharp white crystal spines & foreground needles)
  drawRimeHighSpines(wirePlumes);

  // 8. Fine airborne ice crystals & subtle directional wind grain
  drawFinalBrittleAccents(wirePlumes);

  noLoop();
}

// =============================================================================
// GEOMETRY HELPERS
// =============================================================================

function getWireY(x) {
  if (x <= WIRE_STAPLE_X) {
    let u = (x + 40) / (WIRE_STAPLE_X + 40);
    let linear = lerp(472, WIRE_STAPLE_Y, u);
    let sag = 10 * sin(u * 180);
    return linear + sag;
  } else {
    let u = (x - WIRE_STAPLE_X) / (1240 - WIRE_STAPLE_X);
    let linear = lerp(WIRE_STAPLE_Y, 742, u);
    let sag = 34 * sin(u * 180);
    return linear + sag;
  }
}

function getWireAngle(x) {
  let dx = 2;
  let dy = getWireY(x + dx) - getWireY(x - dx);
  return atan2(dy, 2 * dx);
}

function getPostRightEdgeX(y) {
  let base = map(y, 130, 1200, 294, 316);
  let wobble = 3.5 * noise(y * 0.012, 1.7) - 1.75;
  if (y > 490 && y < 580) {
    // Subtle notch where staple is hammered in
    wobble -= 2.2 * sin(map(y, 490, 580, 0, 180));
  }
  return base + wobble;
}

// =============================================================================
// 1. BACKGROUND FOG (FLAT SOFT CHARCOAL HAZE)
// =============================================================================

function drawFogAtmosphere() {
  brush.noStroke();

  // Broad flat toned washes for dense freezing fog
  const fogBands = [
    { y: -40, h: 420, col: "#9ea7b7", op: 55 },
    { y: 240, h: 480, col: "#b4bcc9", op: 45 },
    { y: 580, h: 420, col: "#949eae", op: 50 },
    { y: 860, h: 380, col: "#858f9f", op: 65 }
  ];

  for (let b of fogBands) {
    brush.wash(b.col, b.op);
    brush.rect(-40, b.y, 1280, b.h);
  }
  brush.noWash();

  // Subtle watercolor mist blooms for depth behind the hero wire
  brush.fillBleed(0.35, "out");
  brush.fillTexture(0.25, 0.1);
  brush.fill("#8c96a8", 38);
  brush.rect(260, 220, 960, 440);
  brush.fill("#c5cdd9", 34);
  brush.rect(340, 310, 780, 290);
  brush.fill("#7d8799", 42);
  brush.rect(-20, 740, 1240, 480);
  brush.noFill();

  // Flat soft charcoal haze: broad low-opacity horizontal and wind-aligned passes
  for (let i = 0; i < 95; i++) {
    let y = map(i, 0, 94, 10, 1190) + random(-12, 12);
    let col = i % 3 === 0 ? "#8a94a6" : (i % 3 === 1 ? "#a2abb9" : "#b8c0cd");
    brush.set("charcoal", col, random(1.8, 3.8));
    let x1 = random(-60, 120);
    let x2 = random(1080, 1260);
    brush.line(x1, y, x2, y + random(-18, 18));
  }

  // Directional wind-aligned whisper lines across the fog (WIND_ANGLE = -34)
  for (let i = 0; i < 110; i++) {
    let sx = random(-50, 1200);
    let sy = random(0, 1200);
    let len = random(90, 280);
    let ang = WIND_ANGLE + random(-1.5, 1.5);
    let col = random() < 0.55 ? "#9ba4b4" : "#bec6d3";
    brush.set("2B", col, random(0.25, 0.65));
    brush.line(sx, sy, sx + cos(ang) * len, sy + sin(ang) * len);
  }
}

// =============================================================================
// 2. DISTANT GHOST FENCE IN FOG
// =============================================================================

function drawDistantGhostFence() {
  // Barely visible second post far back in the freezing mist
  let gx = 910;
  let gyTop = 365;
  brush.noStroke();
  brush.wash("#939cad", 55);
  brush.beginShape(0);
  brush.vertex(gx - 28, 1200);
  brush.vertex(gx - 22, gyTop + 18);
  brush.vertex(gx + 14, gyTop);
  brush.vertex(gx + 22, 1200);
  brush.endShape(true);
  brush.noWash();

  // Faint rime silhouette on distant post's windward edge
  brush.set("2H", "#c0c8d6", 0.35);
  for (let y = gyTop + 4; y < 1150; y += 9) {
    let len = random(8, 22) * noise(y * 0.03);
    brush.line(gx + 16, y, gx + 16 + cos(WIND_ANGLE) * len, y + sin(WIND_ANGLE) * len);
  }

  // Faint receding wire line connecting foreground post to distant post
  brush.set("2H", "#8f98a8", 0.3);
  for (let t = 0; t < 1; t += 0.04) {
    let x1 = lerp(298, gx + 8, t);
    let y1 = lerp(535, gyTop + 135, t) + 28 * sin(t * 180);
    let x2 = lerp(298, gx + 8, t + 0.035);
    let y2 = lerp(535, gyTop + 135, t + 0.035) + 28 * sin((t + 0.035) * 180);
    brush.line(x1, y1, x2, y2);
  }
}

// =============================================================================
// 3. FOREGROUND WEATHERED WOODEN FENCE POST
// =============================================================================

function drawFencePost() {
  // Post silhouette points
  let topY = 142;
  let leftXTop = 58;
  let leftXBot = 74;

  // Base tonal body of weathered split cedar post
  brush.noStroke();
  brush.wash("#6e7787", 170);
  brush.beginShape(0);
  brush.vertex(leftXBot, 1220);
  brush.vertex(leftXTop, topY + 34);
  brush.vertex(135, topY + 8);
  brush.vertex(235, topY - 4);
  brush.vertex(getPostRightEdgeX(topY + 12), topY + 12);
  for (let y = 200; y <= 1200; y += 100) {
    brush.vertex(getPostRightEdgeX(y), y);
  }
  brush.vertex(getPostRightEdgeX(1220), 1220);
  brush.endShape(true);
  brush.noWash();

  // Darker core plane near the windward chamfer (gives 3D turn of form)
  brush.fillBleed(0.18, "in");
  brush.fillTexture(0.45, 0.25);
  brush.fill("#4b5363", 115);
  brush.beginShape(0);
  brush.vertex(185, 1220);
  brush.vertex(172, topY + 6);
  brush.vertex(258, topY + 2);
  for (let y = 200; y <= 1220; y += 120) {
    brush.vertex(getPostRightEdgeX(y) - 18, y);
  }
  brush.endShape(true);
  brush.noFill();

  // Left edge dissolving softly into the fog
  for (let i = 0; i < 45; i++) {
    let x = random(42, 125);
    let y1 = random(140, 1100);
    let y2 = y1 + random(80, 260);
    brush.set("charcoal", "#9aa3b3", random(0.9, 2.2));
    brush.line(x, y1, x + random(-6, 6), min(1220, y2));
  }

  // Fine vertical silvered wood grain & weathered fibers
  for (let x = 78; x < 306; x += 2.6) {
    let xRatio = (x - 78) / (306 - 78);
    let segs = int(random(5, 10));
    for (let s = 0; s < segs; s++) {
      let yStart = random(topY + 15, 1140);
      let yEnd = min(1210, yStart + random(45, 170));
      let curX1 = x + map(yStart, 140, 1200, 0, 20) + 3 * (noise(x * 0.05, yStart * 0.01) - 0.5);
      let curX2 = x + map(yEnd, 140, 1200, 0, 20) + 3 * (noise(x * 0.05, yEnd * 0.01) - 0.5);

      let maxR = getPostRightEdgeX((yStart + yEnd) * 0.5) - 2;
      if (curX1 > maxR || curX2 > maxR) continue;

      // Knot distortion around staple
      let distStaple = dist(curX1, (yStart + yEnd) * 0.5, WIRE_STAPLE_X - 18, WIRE_STAPLE_Y);
      if (distStaple < 55) {
        let push = (1 - distStaple / 55) * 10 * (curX1 < WIRE_STAPLE_X - 18 ? -1 : 1);
        curX1 += push;
        curX2 += push * 0.5;
      }

      // Color selection: dark crevices, silver cedar, or pale blue-violet frost in grain
      let n = noise(x * 0.12, yStart * 0.02);
      if (n < 0.32) {
        brush.set("rotring", "#333a4a", random(0.25, 0.55));
      } else if (n < 0.65) {
        brush.set("2H", xRatio > 0.7 ? "#8a96ab" : "#596275", random(0.35, 0.7));
      } else {
        brush.set("needle", xRatio > 0.78 ? "#dde5f2" : "#aeb8c9", random(0.3, 0.65));
      }
      brush.line(curX1, yStart, curX2, yEnd);
    }
  }

  // Deep vertical split checks in the post + frost trapped inside splits
  const splits = [
    { xBase: 148, y1: 150, y2: 690, w: 1.2 },
    { xBase: 218, y1: 142, y2: 980, w: 1.6 },
    { xBase: 256, y1: 310, y2: 1180, w: 1.3 },
    { xBase: 175, y1: 620, y2: 1190, w: 1.1 }
  ];

  for (let sp of splits) {
    let prevX = sp.xBase + map(sp.y1, 140, 1200, 0, 18);
    let prevY = sp.y1;
    for (let y = sp.y1 + 24; y <= sp.y2; y += 24) {
      let nx = sp.xBase + map(y, 140, 1200, 0, 18) + (noise(sp.xBase, y * 0.02) - 0.5) * 9;
      // Dark split shadow
      brush.set("rotring", "#1f2533", sp.w * random(0.5, 1.0));
      brush.line(prevX, prevY, nx, y);
      // Crisp white frost rim on the windward lip of the split
      if (random() < 0.8) {
        brush.set("needle", "#e8effa", 0.45);
        brush.line(prevX + 1.8, prevY, nx + 1.8, y);
      }
      prevX = nx;
      prevY = y;
    }
  }

  // Subtle rust stain weeping down from the iron U-staple into the frosted wood
  for (let i = 0; i < 28; i++) {
    let rx = WIRE_STAPLE_X - random(4, 24);
    let ry1 = WIRE_STAPLE_Y + random(4, 22);
    let ry2 = ry1 + random(12, 48);
    let col = random() < 0.45 ? "#8c3d20" : "#613122";
    brush.set("needle", col, random(0.25, 0.5));
    brush.line(rx, ry1, rx + random(-1.5, 2.5), ry2);
  }
}

// =============================================================================
// 4. RIME ICE COMB ON FENCE POST'S WINDWARD EDGE & TOP
// =============================================================================

function drawPostRimeComb() {
  // 1. Frost cap along the splintered top of the post (y ≈ 142)
  for (let x = 95; x <= 296; x += 3.2) {
    let ratio = (x - 95) / 201;
    let yBase = lerp(168, 148, pow(ratio, 0.7)) + (noise(x * 0.06) - 0.5) * 8;
    let len = lerp(14, 78, pow(ratio, 1.5)) * (0.65 + 0.6 * noise(x * 0.08));
    let ang = WIND_ANGLE + random(-4, 4);
    drawSingleRimeFeather(x, yBase, len, ang, ratio * 0.85, false);
  }

  // 2. Continuous wind-aligned rime shelf along the right (windward) edge of the post
  // First lay down a translucent pale blue-violet & pearl ice crust along the post edge
  brush.noStroke();
  brush.fillBleed(0.12, "out");
  brush.fillTexture(0.3, 0.2);
  brush.fill("#8c9bb8", 95);
  brush.beginShape(0.2);
  for (let y = 148; y <= 1200; y += 35) {
    let rx = getPostRightEdgeX(y) - 6;
    brush.vertex(rx, y);
  }
  for (let y = 1200; y >= 148; y -= 35) {
    let rx = getPostRightEdgeX(y);
    let shelfW = (28 + 38 * noise(y * 0.018, 9.2)) * (y > 505 && y < 565 ? 1.35 : 1.0);
    brush.vertex(rx + cos(WIND_ANGLE) * shelfW, y + sin(WIND_ANGLE) * shelfW);
  }
  brush.endShape(true);
  brush.noFill();

  // Now build individual feathery crystal spines along the post's windward face
  for (let y = 150; y < 1205; y += 4.2) {
    let rx = getPostRightEdgeX(y) - random(0, 6);
    let n = noise(y * 0.022, 3.4);
    let nFine = noise(y * 0.11, 7.1);
    let baseLen = 28 + 68 * pow(n, 1.3) + 22 * nFine;

    // Extra crystal surge around where the wire staple meets the post edge
    let dWire = abs(y - WIRE_STAPLE_Y);
    if (dWire < 42) {
      baseLen += (1 - dWire / 42) * 38;
    }

    let ang = WIND_ANGLE + (noise(y * 0.05) - 0.5) * 5;
    drawSingleRimeFeather(rx, y, baseLen, ang, 0.75 + 0.25 * nFine, true);
  }
}

// =============================================================================
// 5. GENERATE & RENDER FEATHERY RIME ICE ALONG THE BARBED WIRE
// =============================================================================

function generateWireRimePlumes() {
  let plumes = [];

  // Step along the entire barbed wire from left to right
  for (let x = -25; x <= 1225; x += 2.6) {
    let wy = getWireY(x);
    let wAng = getWireAngle(x);
    let normAng = wAng - 90; // Upper-right (windward) normal

    // Helical twist modulation of the two strands creates natural scalloped packets
    let twistWave = 0.5 + 0.5 * sin(x * 1.95 - 25);
    let packetEnv = 0.35 + 0.65 * pow(twistWave, 0.85);
    let gustEnv = 0.55 + 0.65 * noise(x * 0.012, 14.2);

    // Occasional narrow brittle gaps where rime plates separate
    let gapCheck = noise(x * 0.09, 88.1);
    if (gapCheck < 0.16 && abs(x - WIRE_STAPLE_X) > 25) {
      continue;
    }

    let len = (36 + 98 * packetEnv * gustEnv) * random(0.82, 1.16);

    // Dramatic crystal plume amplification on the 4-point barbs!
    let isBarbPlume = false;
    for (let bx of BARB_POSITIONS) {
      let d = abs(x - bx);
      if (d < 36) {
        let boost = pow(1 - d / 36, 1.2);
        len += boost * random(75, 135);
        isBarbPlume = true;
      }
    }

    // Slight suppression directly behind the post's left shadow, surge at staple
    if (x > 255 && x < 312) {
      len *= 0.85;
    }

    // Nucleation point on the windward (upper-right) side of the wire
    let startOffset = random(1.5, 4.8);
    let sx = x + cos(normAng) * startOffset;
    let sy = wy + sin(normAng) * startOffset;

    let spineAngle = WIND_ANGLE + (noise(x * 0.04, 21.0) - 0.5) * 5.2 + random(-1.2, 1.2);

    plumes.push({
      x: sx,
      y: sy,
      wireX: x,
      len: len,
      angle: spineAngle,
      density: isBarbPlume ? 1.15 : (0.65 + 0.45 * packetEnv),
      isBarbPlume: isBarbPlume,
      seed: random(1000)
    });
  }

  // Add specialized secondary king-spines radiating from the windward barb spikes
  for (let bx of BARB_POSITIONS) {
    let by = getWireY(bx);
    const spikeAngles = [-42, -26, -54, -18];
    for (let s = 0; s < spikeAngles.length; s++) {
      let spAng = spikeAngles[s];
      let spDist = random(10, 28);
      let sx = bx + cos(spAng) * spDist;
      let sy = by + sin(spAng) * spDist;
      plumes.push({
        x: sx,
        y: sy,
        wireX: bx,
        len: random(135, 225),
        angle: WIND_ANGLE + random(-3.2, 3.2),
        density: 1.25,
        isBarbPlume: true,
        seed: random(1000)
      });
    }
  }

  return plumes;
}

// Pass 1: Translucent pale blue-violet & pearl grey internal shadow mass
function drawRimeUnderlayer(plumes) {
  brush.noStroke();
  brush.fillBleed(0.14, "out");
  brush.fillTexture(0.35, 0.22);

  // Batch 1: Pale blue-violet shadow silhouette along the lower-mid body of the rime
  brush.fill("#7d8dad", 82);
  for (let idx = 0; idx < plumes.length; idx += 7) {
    let p = plumes[idx];
    let nextP = plumes[min(plumes.length - 1, idx + 7)];
    let tip1X = p.x + cos(p.angle) * (p.len * 0.78);
    let tip1Y = p.y + sin(p.angle) * (p.len * 0.78);
    let tip2X = nextP.x + cos(nextP.angle) * (nextP.len * 0.78);
    let tip2Y = nextP.y + sin(nextP.angle) * (nextP.len * 0.78);

    brush.beginShape(0.15);
    brush.vertex(p.x, p.y);
    brush.vertex(tip1X, tip1Y);
    brush.vertex(tip2X, tip2Y);
    brush.vertex(nextP.x, nextP.y);
    brush.endShape(true);
  }

  // Batch 2: Lighter pearl-grey sintered ice apron near the wire core
  brush.fill("#d5deeb", 110);
  for (let idx = 0; idx < plumes.length; idx += 6) {
    let p = plumes[idx];
    let nextP = plumes[min(plumes.length - 1, idx + 6)];
    let mid1X = p.x + cos(p.angle) * (p.len * 0.42);
    let mid1Y = p.y + sin(p.angle) * (p.len * 0.42);
    let mid2X = nextP.x + cos(nextP.angle) * (nextP.len * 0.42);
    let mid2Y = nextP.y + sin(nextP.angle) * (nextP.len * 0.42);

    brush.beginShape(0.1);
    brush.vertex(p.x, p.y);
    brush.vertex(mid1X, mid1Y);
    brush.vertex(mid2X, mid2Y);
    brush.vertex(nextP.x, nextP.y);
    brush.endShape(true);
  }
  brush.noFill();
}

// Pass 2: Pale blue-violet, slate, and pearl-grey crystalline lattice & shadow undersides
function drawRimeMidLattice(plumes) {
  for (let p of plumes) {
    let ex = p.x + cos(p.angle) * p.len;
    let ey = p.y + sin(p.angle) * p.len;

    // 1. Deep blue-violet shadow line immediately underneath the primary crystal spine
    let perpAng = p.angle + 90;
    let shOff = 1.6;
    brush.set("needle", "#5c6b8c", random(0.45, 0.85));
    brush.line(
      p.x + cos(perpAng) * shOff,
      p.y + sin(perpAng) * shOff,
      ex + cos(perpAng) * (shOff * 0.4),
      ey + sin(perpAng) * (shOff * 0.4)
    );

    // 2. Pale blue-violet & pearl-grey secondary feather pinnae (internal crystalline ribs)
    let steps = int(map(p.len, 30, 230, 6, 22) * p.density);
    for (let i = 1; i < steps; i++) {
      let t = i / steps;
      let cx = lerp(p.x, ex, t);
      let cy = lerp(p.y, ey, t);

      // Taper profile: widest around t = 0.35, needle-sharp at tip t = 1.0
      let env = sin(pow(t, 0.75) * 180);
      let barbLenUp = (8 + p.len * 0.21) * env * random(0.65, 1.25);
      let barbLenDown = (5 + p.len * 0.14) * env * random(0.55, 1.1);

      // Upper feather pinna (angled sharply into the wind)
      let upAng = p.angle - random(19, 31);
      let colUp = t < 0.55 ? "#8b9ab9" : "#b9c5d9";
      brush.set("needle", colUp, random(0.35, 0.7));
      brush.line(cx, cy, cx + cos(upAng) * barbLenUp, cy + sin(upAng) * barbLenUp);

      // Lower feather pinna (sawtooth shadow facet)
      if (i % 2 === 0) {
        let dnAng = p.angle + random(16, 26);
        let colDn = t < 0.5 ? "#677699" : "#95a3bf";
        brush.set("needle", colDn, random(0.3, 0.6));
        brush.line(cx, cy, cx + cos(dnAng) * barbLenDown, cy + sin(dnAng) * barbLenDown);
      }
    }

    // 3. Dark slate micro-crevices at the base of the rime collar to separate overlapping plates
    if (random() < 0.42) {
      let crLen = random(10, 28);
      brush.set("rotring", "#3d485e", random(0.22, 0.42));
      brush.line(p.x, p.y, p.x + cos(p.angle + 8) * crLen, p.y + sin(p.angle + 8) * crLen);
    }
  }
}

// Pass 3: Razor-sharp pure white & luminous pearl crystal spines + dendritic tips
function drawRimeHighSpines(plumes) {
  for (let p of plumes) {
    let ex = p.x + cos(p.angle) * p.len;
    let ey = p.y + sin(p.angle) * p.len;

    // 1. Primary crystal spine (rachis) in crisp white
    brush.set("ice_edge", "#f0f5fc", random(0.55, 0.95));
    brush.line(p.x, p.y, ex, ey);

    // Extra razor-white highlight along the outer 75% of the spine against the toned grey paper
    let mX = lerp(p.x, ex, 0.22);
    let mY = lerp(p.y, ey, 0.22);
    brush.set("ice_edge", "#ffffff", random(0.45, 0.85));
    brush.line(mX, mY, ex, ey);

    // 2. Feathery white secondary barbs and tertiary hexagonal crystal teeth
    let steps = int(map(p.len, 30, 230, 7, 25) * p.density);
    for (let i = 1; i <= steps; i++) {
      let t = i / steps;
      let cx = lerp(p.x, ex, t);
      let cy = lerp(p.y, ey, t);
      let env = sin(pow(t, 0.72) * 180);

      // Windward (upper) feathery barb in sharp white
      let bLen = (6 + p.len * 0.18) * env * random(0.6, 1.28);
      let bAng = p.angle - random(18, 28);
      let bx = cx + cos(bAng) * bLen;
      let by = cy + sin(bAng) * bLen;

      brush.set("needle", t > 0.35 ? "#ffffff" : "#e3ebf7", random(0.35, 0.75));
      brush.line(cx, cy, bx, by);

      // Tertiary wind-locked tooth at the end of longer barbs (characteristic of rime dendrites!)
      if (bLen > 12 && random() < 0.72) {
        let toothLen = bLen * random(0.45, 0.85);
        let tAng = WIND_ANGLE + random(-2.5, 2.5);
        brush.set("ice_edge", "#ffffff", random(0.3, 0.6));
        brush.line(bx, by, bx + cos(tAng) * toothLen, by + sin(tAng) * toothLen);
      }

      // Lower crystalline step-facet
      if (i % 2 === 1 && t > 0.2) {
        let lLen = (4 + p.len * 0.11) * env * random(0.5, 1.05);
        let lAng = p.angle + random(14, 24);
        brush.set("needle", "#dce5f4", random(0.28, 0.55));
        brush.line(cx, cy, cx + cos(lAng) * lLen, cy + sin(lAng) * lLen);
      }
    }
  }
}

// Helper for drawing individual rime feathers on the fence post
function drawSingleRimeFeather(x, y, len, angle, clarity, includeShadow) {
  let ex = x + cos(angle) * len;
  let ey = y + sin(angle) * len;

  if (includeShadow) {
    brush.set("needle", "#637294", random(0.4, 0.75));
    brush.line(x, y + 1.4, ex, ey + 1.0);
  }

  let steps = int(map(len, 15, 120, 4, 14));
  for (let i = 1; i <= steps; i++) {
    let t = i / steps;
    let cx = lerp(x, ex, t);
    let cy = lerp(y, ey, t);
    let env = sin(t * 180);
    let bLen = (4 + len * 0.19) * env * random(0.6, 1.2);
    let bAng = angle - random(18, 29);

    brush.set("needle", t > 0.4 ? "#ffffff" : "#cdd7e8", random(0.3, 0.65) * clarity);
    brush.line(cx, cy, cx + cos(bAng) * bLen, cy + sin(bAng) * bLen);
  }

  brush.set("ice_edge", "#ffffff", random(0.4, 0.8) * clarity);
  brush.line(x, y, ex, ey);
}

// =============================================================================
// 6. RUSTED DOUBLE-STRAND BARBED WIRE, U-STAPLE, AND 4-POINT BARBS
// =============================================================================

function drawBarbedWireStrand() {
  let step = 3.0;
  let twistFreq = 1.95; // Degrees per pixel
  let strandRadius = 3.8;

  for (let x = -30; x < 1230; x += step) {
    let xNext = x + step;
    let y1 = getWireY(x);
    let y2 = getWireY(xNext);
    let ang = getWireAngle(x);
    let normX = cos(ang + 90); // Points down-left (leeward side)
    let normY = sin(ang + 90);

    // Two twisted wire strands oscillating around the centerline
    let phase1 = x * twistFreq;
    let phase2 = (x + step) * twistFreq;

    for (let strand = 0; strand < 2; strand++) {
      let pA = phase1 + strand * 180;
      let pB = phase2 + strand * 180;
      let offA = sin(pA) * 3.4;
      let offB = sin(pB) * 3.4;

      let sx1 = x + normX * offA;
      let sy1 = y1 + normY * offA;
      let sx2 = xNext + normX * offB;
      let sy2 = y2 + normY * offB;

      // Determine how much of the upper strand is buried under the windward rime apron
      let isUpper = offA < -0.5;
      let rustNoise = noise(x * 0.035, strand * 12.7);
      // Extra rust near barbs and staple
      for (let bx of BARB_POSITIONS) {
        if (abs(x - bx) < 28) rustNoise += 0.24;
      }
      if (abs(x - WIRE_STAPLE_X) < 24) rustNoise += 0.25;

      // 1. Leeward dark iron shadow edge (always sharp and exposed on the bottom!)
      brush.set("rotring", "#1d222e", random(0.45, 0.8));
      brush.line(
        sx1 + normX * strandRadius,
        sy1 + normY * strandRadius,
        sx2 + normX * strandRadius,
        sy2 + normY * strandRadius
      );

      // 2. Dark oxidized steel core of the cylinder
      brush.set("rotring", "#323a4b", random(0.5, 0.9));
      brush.line(
        sx1 + normX * (strandRadius * 0.5),
        sy1 + normY * (strandRadius * 0.5),
        sx2 + normX * (strandRadius * 0.5),
        sy2 + normY * (strandRadius * 0.5)
      );

      // 3. Cold metallic / frost-dusted mid-cylinder
      let midCol = isUpper ? "#9aa7bd" : "#5a657a";
      brush.set("needle", midCol, random(0.4, 0.75));
      brush.line(sx1, sy1, sx2, sy2);

      // 4. Tiny flecks of rust orange where the bare wire shows through!
      if (rustNoise > 0.52) {
        // Dark burnt sienna oxidation bed
        brush.set("needle", "#5e2716", random(0.45, 0.85));
        brush.line(
          sx1 + normX * 1.2,
          sy1 + normY * 1.2,
          sx2 + normX * 1.2,
          sy2 + normY * 1.2
        );

        // Vivid rust orange fleck
        if (random() < 0.78) {
          let rustCol = random() < 0.45 ? "#d95f26" : (random() < 0.6 ? "#b8491e" : "#eb7a38");
          brush.set("needle", rustCol, random(0.35, 0.75));
          let fx = sx1 + normX * random(-0.5, 2.2);
          let fy = sy1 + normY * random(-0.5, 2.2);
          brush.line(fx, fy, fx + cos(ang) * random(2.5, 5.5), fy + sin(ang) * random(2.5, 5.5));
        }
      }

      // 5. Sintered white rime crust gripping the upper (windward) side of the wire twist
      let crustCol = (x % 9 < 4.5) ? "#ffffff" : "#dce5f2";
      brush.set("ice_edge", crustCol, random(0.5, 0.95));
      brush.line(
        sx1 - normX * (strandRadius * 0.75),
        sy1 - normY * (strandRadius * 0.75),
        sx2 - normX * (strandRadius * 0.75),
        sy2 - normY * (strandRadius * 0.75)
      );
    }

    // Tiny hanging frost granules along the leeward bottom edge of the wire
    if (random() < 0.28) {
      let gx = x + normX * (strandRadius + 2.8);
      let gy = y1 + normY * (strandRadius + 2.8);
      brush.set("needle", "#dce4f2", random(0.3, 0.55));
      brush.line(gx, gy, gx + cos(WIND_ANGLE) * random(3, 8), gy + sin(WIND_ANGLE) * random(3, 8));
    }
  }
}

// Heavy rusted iron U-staple clamping the wire to the fence post
function drawFenceStaple(cx, cy) {
  // Cast shadow of the staple onto the frosted wood
  brush.set("charcoal", "#232938", 0.9);
  brush.arc(cx - 4, cy + 4, 15, -115, 85);

  // Arch of the iron U-staple (driven into the wood to the left, looping over the wire)
  for (let r = 11.5; r <= 17.5; r += 1.0) {
    let col = r < 13.5 ? "#1e222d" : (r < 15.5 ? "#4a2a1e" : "#78859c");
    brush.set("rotring", col, 0.55);
    brush.arc(cx - 5, cy, r, -118, 78);
  }

  // Intense rust orange flecks on the staple bend
  const stapleRustPts = [
    { a: -65, r: 14.5, c: "#d95d24" },
    { a: -25, r: 15.0, c: "#eb7836" },
    { a: 15, r: 14.0, c: "#bd4a1e" },
    { a: 48, r: 13.5, c: "#d95d24" },
    { a: -92, r: 14.2, c: "#a83f18" }
  ];
  for (let pt of stapleRustPts) {
    let rx = (cx - 5) + cos(pt.a) * pt.r;
    let ry = cy + sin(pt.a) * pt.r;
    brush.set("needle", pt.c, random(0.5, 0.85));
    brush.line(rx, ry, rx + cos(pt.a + 80) * 5.5, ry + sin(pt.a + 80) * 5.5);
  }

  // Crisp white rime frost rim & feathers growing off the upper windward edge of the staple
  for (let a = -105; a <= 15; a += 8) {
    let sx = (cx - 5) + cos(a) * 17.5;
    let sy = cy + sin(a) * 17.5;
    let len = random(18, 52);
    drawSingleRimeFeather(sx, sy, len, WIND_ANGLE + random(-3, 3), 0.95, true);
  }
}

// 4-point rusted wire barb cluster wrapped around the main strand
function drawBarbCluster(bx) {
  let by = getWireY(bx);
  let wAng = getWireAngle(bx);
  let normX = cos(wAng + 90);
  let normY = sin(wAng + 90);
  let tangX = cos(wAng);
  let tangY = sin(wAng);

  // 1. Four tightly wound wire coils around the main strand
  for (let c = -1.5; c <= 1.5; c += 1.0) {
    let coilX = bx + tangX * (c * 5.2);
    let coilY = by + tangY * (c * 5.2);

    // Dark iron coil body
    for (let t = -1.0; t <= 1.0; t += 0.35) {
      let px1 = coilX - normX * 7.5 + tangX * (t * 2.0);
      let py1 = coilY - normY * 7.5 + tangY * (t * 2.0);
      let px2 = coilX + normX * 8.5 + tangX * (t * 2.0 + 1.5);
      let py2 = coilY + normY * 8.5 + tangY * (t * 2.0 + 1.5);

      let col = t < -0.2 ? "#1b202b" : (t < 0.4 ? "#592818" : "#7e8ba3");
      brush.set("rotring", col, 0.55);
      brush.line(px1, py1, px2, py2);
    }

    // Rust orange flecks wedged between the barb coils
    brush.set("needle", "#e0662b", 0.65);
    brush.line(
      coilX + normX * 2.5,
      coilY + normY * 2.5,
      coilX + normX * 6.5 + tangX * 2.0,
      coilY + normY * 6.5 + tangY * 2.0
    );
    brush.set("needle", "#b3441b", 0.55);
    brush.line(
      coilX - normX * 1.5,
      coilY - normY * 1.5,
      coilX + normX * 3.0 - tangX * 2.0,
      coilY + normY * 3.0 - tangY * 2.0
    );

    // Thick white frost cap on the top of each coil loop
    brush.set("ice_edge", "#ffffff", 0.75);
    brush.line(
      coilX - normX * 8.2 - tangX * 1.8,
      coilY - normY * 8.2 - tangY * 1.8,
      coilX - normX * 5.0 + tangX * 2.2,
      coilY - normY * 5.0 + tangY * 2.2
    );
  }

  // 2. Four sharp cut-wire spikes radiating from the barb knot
  const spikes = [
    // Two leeward spikes (pointing downward/left into the cold shadow, bare & rusted)
    { ang: wAng + 126, len: 36, leeward: true },
    { ang: wAng + 54, len: 31, leeward: true },
    // Two windward spikes (pointing upward/right, acting as armatures for rime plumes)
    { ang: wAng - 132, len: 33, leeward: false },
    { ang: wAng - 44, len: 40, leeward: false }
  ];

  for (let sp of spikes) {
    let tipX = bx + cos(sp.ang) * sp.len;
    let tipY = by + sin(sp.ang) * sp.len;
    let pAng = sp.ang + 90;

    // Beveled cut tip geometry
    let bevX = tipX + cos(sp.ang - 28) * 4.5;
    let bevY = tipY + sin(sp.ang - 28) * 4.5;

    // Dark iron shadow side of spike
    brush.set("rotring", "#1b202c", 0.65);
    brush.line(bx + cos(pAng) * 2.4, by + sin(pAng) * 2.4, tipX + cos(pAng) * 1.2, tipY + sin(pAng) * 1.2);
    brush.line(tipX + cos(pAng) * 1.2, tipY + sin(pAng) * 1.2, bevX, bevY);

    // Oxidized core & vivid rust orange flecks along the spike shaft
    brush.set("rotring", "#472519", 0.6);
    brush.line(bx, by, tipX, tipY);

    for (let f = 0.22; f < 0.88; f += 0.24) {
      let fx = lerp(bx, tipX, f);
      let fy = lerp(by, tipY, f);
      let rCol = f > 0.5 ? "#e36b2d" : "#bd4b1e";
      brush.set("needle", rCol, 0.55);
      brush.line(fx, fy, fx + cos(sp.ang) * 4.8, fy + sin(sp.ang) * 4.8);
    }

    // Cold steel / frost highlight along the upper edge of the spike
    brush.set("ice_edge", sp.leeward ? "#ced8e8" : "#ffffff", 0.65);
    brush.line(
      bx - cos(pAng) * 2.2,
      by - sin(pAng) * 2.2,
      bevX,
      bevY
    );

    // If windward spike, sprout extra feathery rime crystals directly along its shaft
    if (!sp.leeward) {
      for (let t = 0.25; t <= 1.0; t += 0.18) {
        let sx = lerp(bx, bevX, t);
        let sy = lerp(by, bevY, t);
        drawSingleRimeFeather(sx, sy, random(42, 95) * t, WIND_ANGLE + random(-3, 3), 1.0, true);
      }
    } else {
      // On leeward spikes, add a tiny frozen ice bead / short rime tooth at the sharp bevel tip
      drawSingleRimeFeather(bevX, bevY, random(10, 22), WIND_ANGLE + random(-2, 2), 0.9, false);
    }
  }
}

