function drawFinalBrittleAccents(plumes) {
  // 1. Delicate crystalline dust & detached ice spicules drifting along the wind vector
  for (let i = 0; i < 160; i++) {
    let p = random(plumes);
    let distAlong = random(0.3, 1.18) * p.len;
    let jitterPerp = random(-14, 14);
    let sx = p.x + cos(p.angle) * distAlong + cos(p.angle + 90) * jitterPerp;
    let sy = p.y + sin(p.angle) * distAlong + sin(p.angle + 90) * jitterPerp;

    let spiculeLen = random(4, 15);
    let col = random() < 0.72 ? "#ffffff" : "#cfd9ea";
    brush.set("ice_edge", col, random(0.28, 0.55));
    brush.line(
      sx,
      sy,
      sx + cos(WIND_ANGLE) * spiculeLen,
      sy + sin(WIND_ANGLE) * spiculeLen
    );
  }

  // 2. Micro-flecks of rust orange & dark iron stipple along the bare leeward underside
  for (let x = 10; x < 1190; x += random(14, 32)) {
    let wy = getWireY(x);
    let wAng = getWireAngle(x);
    let lx = x + cos(wAng + 90) * random(1.5, 5.2);
    let ly = wy + sin(wAng + 90) * random(1.5, 5.2);

    if (noise(x * 0.04, 99.1) > 0.44) {
      let c = random() < 0.5 ? "#d95f25" : "#8f3717";
      brush.set("needle", c, random(0.35, 0.65));
      brush.line(lx, ly, lx + cos(wAng) * 3.5, ly + sin(wAng) * 3.5);
    }
  }

  // 3. Subtle frost dust spray along the heaviest rime clusters for crystalline shimmer
  brush.set("frost_dust", "#ffffff", 0.55);
  for (let bx of BARB_POSITIONS) {
    let by = getWireY(bx);
    brush.line(
      bx + cos(WIND_ANGLE) * 15,
      by + sin(WIND_ANGLE) * 15,
      bx + cos(WIND_ANGLE) * 145,
      by + sin(WIND_ANGLE) * 145
    );
  }
}

