// ===========================================================================
// HELPER: Trace a polygon array into brush.beginShape / vertex / endShape
// ===========================================================================
function traceShape(pts, curvature = 0.25, closed = true) {
  brush.beginShape(curvature);
  for (let i = 0; i < pts.length; i++) {
    brush.vertex(pts[i][0], pts[i][1]);
  }
  brush.endShape(closed);
}

// ===========================================================================
//Helper: Generate a ribbon polygon from a spine of [x, y, halfWidth]
// ===========================================================================
function buildRibbonPoints(spine) {
  let leftSide = [];
  let rightSide = [];
  for (let i = 0; i < spine.length; i++) {
    let p = spine[i];
    let dx = 0, dy = 0;
    if (i < spine.length - 1) {
      dx += spine[i + 1][0] - p[0];
      dy += spine[i + 1][1] - p[1];
    }
    if (i > 0) {
      dx += p[0] - spine[i - 1][0];
      dy += p[1] - spine[i - 1][1];
    }
    let len = Math.hypot(dx, dy) || 1;
    let nx = -dy / len;
    let ny = dx / len;
    let w = p[2];
    leftSide.push([p[0] + nx * w, p[1] + ny * w]);
    rightSide.push([p[0] - nx * w, p[1] - ny * w]);
  }
  rightSide.reverse();
  return leftSide.concat(rightSide);
}

// ===========================================================================
// 1. EMERALD FIELD & POLISH PAPER-CUT SCALLOPED BLACK BORDER
// ===========================================================================
function drawEmeraldFieldAndScallopedBorder(cx, cy) {
  brush.noField();

  // Base saturated emerald field inside the frame
  brush.noStroke();
  brush.wash("#006b44", 255);
  brush.rect(55, 55, 1090, 1090, "corner");

  // Rich emerald watercolor glaze in the central field for luminous depth
  brush.fill("#008756", 145);
  brush.fillBleed(0.18, "in");
  brush.fillTexture(0.55, 0.35);
  brush.circle(cx, cy, 520, 0.04);
  brush.noFill();

  // Subtle vertical paper-weave grain in the emerald ground
  brush.hatchStyle("2H", "#005435", 0.55);
  brush.hatch(11, 90, { rand: 0.03 });
  brush.noStroke();
  brush.rect(70, 70, 1060, 1060, "corner");
  brush.noHatch();

  // Construct the crisp scalloped inner boundary of the cut-paper black border
  // 9 scallops per side (36 around the perimeter) creating a folk Wycinanki frame
  const margin = 86;
  const innerMin = margin;
  const innerMax = 1200 - margin;
  const span = innerMax - innerMin;
  const numScallops = 9;
  const step = span / numScallops;
  const scallopDepth = 28;

  let innerScallopPts = [];

  // Top edge (left to right)
  for (let i = 0; i < numScallops; i++) {
    let x0 = innerMin + i * step;
    let xm = x0 + step * 0.5;
    for (let k = 0; k <= 6; k++) {
      let t = k / 6;
      let a = t * 180;
      let px = x0 + t * step;
      let py = innerMin + sin(a) * scallopDepth;
      innerScallopPts.push([px, py]);
    }
  }
  // Right edge (top to bottom)
  for (let i = 0; i < numScallops; i++) {
    let y0 = innerMin + i * step;
    for (let k = 0; k <= 6; k++) {
      let t = k / 6;
      let a = t * 180;
      let px = innerMax - sin(a) * scallopDepth;
      let py = y0 + t * step;
      innerScallopPts.push([px, py]);
    }
  }
  // Bottom edge (right to left)
  for (let i = 0; i < numScallops; i++) {
    let x0 = innerMax - i * step;
    for (let k = 0; k <= 6; k++) {
      let t = k / 6;
      let a = t * 180;
      let px = x0 - t * step;
      let py = innerMax - sin(a) * scallopDepth;
      innerScallopPts.push([px, py]);
    }
  }
  // Left edge (bottom to top)
  for (let i = 0; i < numScallops; i++) {
    let y0 = innerMax - i * step;
    for (let k = 0; k <= 6; k++) {
      let t = k / 6;
      let a = t * 180;
      let px = innerMin + sin(a) * scallopDepth;
      let py = y0 - t * step;
      innerScallopPts.push([px, py]);
    }
  }

  // Draw the cast drop-shadow of the cut-paper scalloped black border onto the emerald field
  brush.noStroke();
  brush.set("charcoal", "#002918", 2.8);
  let shadowPts = innerScallopPts.map(p => [p[0] + 4, p[1] + 5]);
  traceShape(shadowPts, 0.15, true);

  // Fill the four outer border strips in deep cut-paper black + scalloped lobes
  brush.noStroke();
  brush.wash("#0d0a10", 255);
  brush.rect(0, 0, 1200, innerMin + 2, "corner");
  brush.rect(0, innerMax - 2, 1200, 1200 - innerMax + 2, "corner");
  brush.rect(0, 0, innerMin + 2, 1200, "corner");
  brush.rect(innerMax - 2, 0, 1200 - innerMax + 2, 1200, "corner");

  // Fill every scallop lobe in cut-paper black
  for (let side = 0; side < 4; side++) {
    for (let i = 0; i < numScallops; i++) {
      let lobePts = [];
      for (let k = 0; k <= 8; k++) {
        let t = k / 8;
        let a = t * 180;
        let d = sin(a) * scallopDepth;
        if (side === 0) lobePts.push([innerMin + (i + t) * step, innerMin - 4 + d]);
        if (side === 1) lobePts.push([innerMax + 4 - d, innerMin + (i + t) * step]);
        if (side === 2) lobePts.push([innerMax - (i + t) * step, innerMax + 4 - d]);
        if (side === 3) lobePts.push([innerMin - 4 + d, innerMax - (i + t) * step]);
      }
      brush.noStroke();
      brush.wash("#0d0a10", 255);
      traceShape(lobePts, 0.2, true);
    }
  }

  // Crisp cut-paper edge highlight and folk punched geometric cutouts along the black scallop border
  brush.set("rotring", "#2b2333", 1.1);
  traceShape(innerScallopPts, 0.12, true);

  // Folk Wycinanki punched diamond & teardrop apertures along the scalloped black frame
  // revealing the saturated emerald paper underneath
  for (let side = 0; side < 4; side++) {
    for (let i = 0; i < numScallops; i++) {
      let u = innerMin + (i + 0.5) * step;
      let v = 52;
      let px = side === 0 ? u : side === 1 ? 1200 - v : side === 2 ? 1200 - u : v;
      let py = side === 0 ? v : side === 1 ? u : side === 2 ? 1200 - v : 1200 - u;

      // Emerald diamond cutout inside each scallop crown
      let dPts = [
        [px, py - 11],
        [px + 8, py],
        [px, py + 11],
        [px - 8, py]
      ];
      brush.noStroke();
      brush.wash("#007a4e", 255);
      traceShape(dPts, 0.05, true);
      brush.set("scalpel", "#2e2538", 0.9);
      traceShape(dPts, 0.05, true);

      // Pair of tiny folk notch cutouts between scallops
      if (i < numScallops) {
        let u2 = innerMin + i * step;
        let nx = side === 0 ? u2 : side === 1 ? 1200 - 34 : side === 2 ? 1200 - u2 : 34;
        let ny = side === 0 ? 34 : side === 1 ? u2 : side === 2 ? 1200 - 34 : 1200 - u2;
        brush.noStroke();
        brush.wash("#007a4e", 245);
        brush.circle(nx, ny, 4.5, 0.05);
      }
    }
  }

  // Corner Wycinanki folk star cutouts in the 4 corners of the emerald field
  const corners = [
    [148, 148, 1, 1],
    [1052, 148, -1, 1],
    [148, 1052, 1, -1],
    [1052, 1052, -1, -1]
  ];
  for (let [kx, ky, sx, sy] of corners) {
    // Cut-paper black folk corner flourish
    let flourish = [
      [kx - sx * 24, ky - sy * 24],
      [kx + sx * 38, ky - sy * 18],
      [kx + sx * 14, ky + sy * 14],
      [kx - sx * 18, ky + sy * 38]
    ];
    brush.noStroke();
    brush.wash("#0d0a10", 255);
    traceShape(flourish, 0.15, true);
    brush.set("scalpel", "#2c2336", 0.8);
    traceShape(flourish, 0.15, true);

    // Tiny emerald eye inside corner flourish
    brush.noStroke();
    brush.wash("#008053", 255);
    brush.circle(kx - sx * 2, ky - sy * 2, 6, 0.05);
  }

  // Deep ambient shadow cast by the cabbage head onto the emerald background
  brush.noStroke();
  brush.fill("#002617", 170);
  brush.fillBleed(0.35, "out");
  brush.fillTexture(0.6, 0.3);
  brush.circle(cx, cy + 14, 468, 0.08);
  brush.noFill();
}

// ===========================================================================
// 2. OUTER UNCUT LEAVES WITH WAXY EPICUTICULAR BLOOM
// ===========================================================================
function drawOuterLeavesWithBloom(cx, cy) {
  // 5 symmetrical pairs of ruffled outer wrapper leaves + 1 top crown leaf
  // These curve in 3D behind the flat knife-cut plane and carry the powdery bluish-white bloom
  const leafConfigs = [
    { aStart: -96, aEnd: -60, rInner: 380, rOuter: 482, col: "#1b0b29", bloom: 0.85 },
    { aStart: -64, aEnd: -22, rInner: 390, rOuter: 488, col: "#220e33", bloom: 0.95 },
    { aStart: -26, aEnd: 18,  rInner: 395, rOuter: 492, col: "#190926", bloom: 0.90 },
    { aStart: 14,  aEnd: 54,  rInner: 385, rOuter: 480, col: "#240f36", bloom: 0.85 },
    { aStart: 48,  aEnd: 82,  rInner: 360, rOuter: 454, col: "#170724", bloom: 0.75 }
  ];

  for (let cfg of leafConfigs) {
    for (let side of [-1, 1]) {
      let pts = [];
      let rimPts = [];
      let steps = 22;

      // Inner base arc
      pts.push([
        cx + side * cos(cfg.aStart) * cfg.rInner * 0.85,
        cy + sin(cfg.aStart) * cfg.rInner * 0.85
      ]);

      for (let i = 0; i <= steps; i++) {
        let t = i / steps;
        let a = lerp(cfg.aStart, cfg.aEnd, t);
        let env = sin(t * 180);
        // Ruffled organic margin with gentle asymmetry
        let ruffle = sin(t * 540 + side * 15) * 9 + cos(t * 900) * 4;
        let r = lerp(cfg.rInner, cfg.rOuter, Math.pow(env, 0.65)) + ruffle * env;
        // Slight aspect ratio stretch
        let px = cx + side * cos(a) * r * 1.03;
        let py = cy + sin(a) * r * 0.97;
        pts.push([px, py]);
        rimPts.push([px, py]);
      }

      pts.push([
        cx + side * cos(cfg.aEnd) * cfg.rInner * 0.85,
        cy + sin(cfg.aEnd) * cfg.rInner * 0.85
      ]);

      // Base dark aubergine wash for the outer leaf
      brush.noStroke();
      brush.wash(cfg.col, 250);
      traceShape(pts, 0.25, true);

      // Deep indigo-violet watercolor glaze on the outer leaf
      brush.fill("#2e1344", 120);
      brush.fillBleed(0.15, "in");
      brush.fillTexture(0.6, 0.4);
      traceShape(pts, 0.25, true);
      brush.noFill();

      // Waxy epicuticular bloom: powdery slate-blue & pale lavender-white frosting
      let midAngle = (cfg.aStart + cfg.aEnd) * 0.5;
      let hatchAngle = side === 1 ? midAngle + 90 : 180 - midAngle - 90;
      brush.hatchStyle("cpencil", "#95a8cc", 0.9);
      brush.hatch(5.5, hatchAngle, { rand: 0.12, gradient: 0.35 });
      brush.noStroke();
      traceShape(pts, 0.2, true);
      brush.noHatch();

      // Concentrated bloom spray on the convex bulge of the outer leaf
      let bulgeR = (cfg.rInner + cfg.rOuter) * 0.51;
      for (let k = 0; k < 18; k++) {
        let tk = map(k, 0, 17, 0.18, 0.82);
        let ak = lerp(cfg.aStart, cfg.aEnd, tk);
        let rk = bulgeR + random(-14, 10);
        let bx = cx + side * cos(ak) * rk * 1.03;
        let by = cy + sin(ak) * rk * 0.97;
        brush.set("wax_bloom", k % 2 === 0 ? "#c6d4ee" : "#9fb2d6", random(0.8, 1.45));
        brush.line(bx - 6, by - 4, bx + 6, by + 4);
      }

      // Subtle outer leaf branching veins in pale dusty lavender
      for (let v = 1; v <= 3; v++) {
        let tv = v / 4;
        let av = lerp(cfg.aStart, cfg.aEnd, tv);
        let vPts = [];
        for (let s = 0; s <= 5; s++) {
          let ts = s / 5;
          let rv = lerp(cfg.rInner + 5, cfg.rOuter - 12, ts);
          let aCurv = av + sin(ts * 180) * 4;
          vPts.push([
            cx + side * cos(aCurv) * rv * 1.03,
            cy + sin(aCurv) * rv * 0.97,
            lerp(1.4, 0.3, ts)
          ]);
        }
        brush.set("cpencil", "#b8add1", 0.75);
        brush.spline(vPts, 0.4);
      }

      // Crisp dark folded outer contour + pale waxy rim highlight
      brush.set("vein_pen", "#0d0314", 1.1);
      brush.spline(rimPts, 0.3);
      brush.set("cpencil", "#d4dff5", 0.55);
      brush.spline(rimPts.slice(3, rimPts.length - 3), 0.3);
    }
  }
}

// ===========================================================================
// 3. KNIFE-SLICED CABBAGE HEAD: WATERCOLOUR GLAZES & DEEP VIOLET BASE
// ===========================================================================
function getCutHeadOutline(cx, cy, scaleOffset = 0) {
  let pts = [];
  let steps = 90;
  for (let i = 0; i < steps; i++) {
    let a = (i / steps) * 360 - 90; // Start at top (-90 deg)
    // Symmetrical angle distance from top (-90) to bottom (+90)
    let symA = Math.abs(((a + 90 + 180) % 360) - 180); // 0 at top, 180 at bottom
    // Slight oblate-heart cabbage head shape
    let rx = 424 + scaleOffset;
    let ry = 398 + scaleOffset;
    // Subtle multi-layered leaf lobe undulations around the cut perimeter
    let lobe = sin(symA * 7) * 5.5 + cos(symA * 13) * 3.0;
    // Basal stem indentation near bottom (symA > 152)
    let stemIndent = symA > 150 ? -Math.pow((symA - 150) / 30, 1.8) * 26 : 0;
    // Slight broadening across the upper-mid shoulders (symA ~ 55-100)
    let shoulder = sin( constrain(map(symA, 15, 135, 0, 180), 0, 180) ) * 14;

    let rBaseX = rx + lobe + shoulder + stemIndent * 0.4;
    let rBaseY = ry + lobe + shoulder * 0.6 + stemIndent;

    let px = cx + cos(a) * rBaseX;
    let py = cy + sin(a) * rBaseY;
    pts.push([px, py]);
  }
  return pts;
}

function drawSlicedHeadWatercolourBase(cx, cy) {
  // Outer bevel shadow where the cut plane meets the uncut outer leaves
  let outerBevelPts = getCutHeadOutline(cx, cy, 8);
  brush.noStroke();
  brush.wash("#12031c", 255);
  traceShape(outerBevelPts, 0.2, true);

  // Main cut face base wash in deep abyssal purple-black
  let mainCutPts = getCutHeadOutline(cx, cy, 0);
  brush.noStroke();
  brush.wash("#1c0529", 255);
  traceShape(mainCutPts, 0.2, true);

  // Watercolour Glaze 1: Rich imperial violet across the cut dome
  let glaze1Pts = getCutHeadOutline(cx, cy, -10);
  brush.noStroke();
  brush.fill("#3d094f", 155);
  brush.fillBleed(0.28, "in");
  brush.fillTexture(0.7, 0.55);
  traceShape(glaze1Pts, 0.25, true);
  brush.noFill();

  // Watercolour Glaze 2: Saturated magenta-plum glow in the left, right, and upper chambers
  const glazeZones = [
    { x: cx - 185, y: cy - 35, r: 215, col: "#69116d", op: 135 },
    { x: cx + 185, y: cy - 35, r: 215, col: "#69116d", op: 135 },
    { x: cx,       y: cy - 190, r: 195, col: "#7c1778", op: 130 },
    { x: cx - 135, y: cy + 145, r: 165, col: "#4f0c5c", op: 140 },
    { x: cx + 135, y: cy + 145, r: 165, col: "#4f0c5c", op: 140 }
  ];
  for (let gz of glazeZones) {
    brush.noStroke();
    brush.fill(gz.col, gz.op);
    brush.fillBleed(0.32, "out");
    brush.fillTexture(0.65, 0.45);
    brush.circle(gz.x, gz.y, gz.r, 0.12);
    brush.noFill();
  }
}

// ===========================================================================
// 4. CONVOLUTED LABYRINTH OF MAGENTA-VIOLET FOLDS & PAPER-CUT CHAMBERS
// ===========================================================================
// Helper to evaluate a primary rib path at parameter t in [0..1]
function evalRibPoint(cx, cy, side, ribIdx, t, asymSeed = 0) {
  // 9 ribs from bottom (ribIdx = 0) to inner-top (ribIdx = 8)
  let u = ribIdx / 8; // 0 = lowest outer rib, 1 = highest inner rib

  // Starting point along the side of the central core
  let startY = lerp(cy + 345, cy - 55, Math.pow(u, 0.88));
  let startX = cx + side * lerp(58, 16, Math.pow(u, 0.75));

  // Peak outer excursion and final incurving crown destination
  let maxReachX = lerp(395, 155, Math.pow(u, 0.95));
  let midY = lerp(cy + 150, cy - 195, u);
  let endAngle = lerp(-76, -86, u); // Radiates up into the crown
  let endR = lerp(395, 195, u);
  let endX = cx + side * cos(endAngle) * endR * 1.04;
  let endY = cy + sin(endAngle) * endR * 0.96;

  // Parametric C-curve / S-wave with botanical convolutions
  let p0x = startX, p0y = startY;
  let p1x = cx + side * (maxReachX * 0.72), p1y = startY + lerp(28, -25, u);
  let p2x = cx + side * (maxReachX * 1.06), p2y = midY;
  let p3x = endX, p3y = endY;

  // Cubic Bezier evaluation
  let mt = 1 - t;
  let bx = mt * mt * mt * p0x + 3 * mt * mt * t * p1x + 3 * mt * t * t * p2x + t * t * t * p3x;
  let by = mt * mt * mt * p0y + 3 * mt * mt * t * p1y + 3 * mt * t * t * p2y + t * t * t * p3y;

  // Add characteristic cabbage midrib undulations (nearly mirror-symmetrical with micro-organic nuance)
  let waveFreq = 3.5 + ribIdx * 0.4;
  let waveAmp = lerp(11, 6, u) * sin(t * 180);
  let phase = ribIdx * 42 + asymSeed * 8;
  let wx = sin(t * 360 * waveFreq + phase) * waveAmp * 0.55;
  let wy = cos(t * 360 * waveFreq + phase) * waveAmp;

  // Thickness profile of the white rib: thick at the core junction, tapering toward the tip
  let baseThick = lerp(16.5, 7.5, u);
  let thick = baseThick * Math.pow(1 - t * 0.82, 1.15) + sin(t * 540 + phase) * 1.4 * (1 - t);

  return {
    x: bx + side * wx,
    y: by + wy,
    w: Math.max(1.6, thick)
  };
}

function drawConvolutedChambersAndFolds(cx, cy) {
  // Between adjacent primary ribs (0..7), draw stacked Wycinanki-like folded leaf chambers
  // Each chamber has:
  //   1) Deep abyssal purple-black gap
  //   2) Royal violet & crimson-magenta folded leaf ribbons
  //   3) Convoluted S-folded and brain-coral secondary white/pink veins
  for (let rIdx = 0; rIdx < 8; rIdx++) {
    for (let side of [-1, 1]) {
      let asym = side === 1 ? 1.0 : -1.0;
      let steps = 26;
      let lowerSpine = [];
      let upperSpine = [];

      for (let i = 0; i <= steps; i++) {
        let t = i / steps;
        let pLow = evalRibPoint(cx, cy, side, rIdx, t, asym * 0.35);
        let pHigh = evalRibPoint(cx, cy, side, rIdx + 1, t, asym * 0.35);
        lowerSpine.push(pLow);
        upperSpine.push(pHigh);
      }

      // Build chamber polygon bounded by the two ribs
      let chamberPts = [];
      for (let i = 2; i < steps - 1; i++) {
        chamberPts.push([
          lerp(lowerSpine[i].x, upperSpine[i].x, 0.12),
          lerp(lowerSpine[i].y, upperSpine[i].y, 0.12)
        ]);
      }
      for (let i = steps - 2; i >= 2; i--) {
        chamberPts.push([
          lerp(lowerSpine[i].x, upperSpine[i].x, 0.88),
          lerp(lowerSpine[i].y, upperSpine[i].y, 0.88)
        ]);
      }

      // Layer 1: Deep cut-paper shadow recess inside the chamber
      brush.noStroke();
      brush.wash("#11021a", 235);
      traceShape(chamberPts, 0.25, true);

      // Layer 2: Convoluted meanders (folded purple leaf tissue + secondary white veins)
      // Subdivide each chamber into 4 to 6 tightly folded S-loops / brain-like gyri
      let numLoops = 6 - Math.floor(rIdx * 0.35);
      for (let l = 0; l < numLoops; l++) {
        let t0 = map(l, 0, numLoops, 0.08, 0.84);
        let t1 = map(l + 0.88, 0, numLoops, 0.08, 0.84);
        let tMid = (t0 + t1) * 0.5;

        let i0 = Math.floor(t0 * steps);
        let iMid = Math.floor(tMid * steps);
        let i1 = Math.min(steps, Math.floor(t1 * steps));

        let pA0 = lowerSpine[i0], pB0 = upperSpine[i0];
        let pAM = lowerSpine[iMid], pBM = upperSpine[iMid];
        let pA1 = lowerSpine[i1], pB1 = upperSpine[i1];

        // Construct a folded horseshoe / S-curve pocket inside the chamber
        let foldDir = (l + rIdx) % 2 === 0 ? 1 : -1;
        let foldLoopPts = [
          [lerp(pA0.x, pB0.x, 0.22), lerp(pA0.y, pB0.y, 0.22)],
          [lerp(pAM.x, pBM.x, 0.18), lerp(pAM.y, pBM.y, 0.18)],
          [lerp(pA1.x, pB1.x, 0.28), lerp(pA1.y, pB1.y, 0.28)],
          [lerp(pA1.x, pB1.x, 0.78), lerp(pA1.y, pB1.y, 0.78)],
          [lerp(pAM.x, pBM.x, 0.84), lerp(pAM.y, pBM.y, 0.84)],
          [lerp(pA0.x, pB0.x, 0.72), lerp(pA0.y, pB0.y, 0.72)]
        ];

        // Outer magenta-violet fold layer
        let foldCol = (l + rIdx) % 2 === 0 ? "#4d0b59" : "#63106b";
        brush.noStroke();
        brush.wash(foldCol, 230);
        traceShape(foldLoopPts, 0.35, true);

        // Inner brighter crimson-magenta cut layer
        let innerLoopPts = foldLoopPts.map(pt => {
          let cxL = (pAM.x + pBM.x) * 0.5;
          let cyL = (pAM.y + pBM.y) * 0.5;
          return [lerp(pt[0], cxL, 0.26), lerp(pt[1], cyL, 0.26)];
        });
        brush.noStroke();
        brush.wash((l % 2 === 0) ? "#8c1b82" : "#a32692", 220);
        traceShape(innerLoopPts, 0.35, true);

        // Convoluted secondary white-and-pink vein ribbon folded inside the loop (S-curve or U-fold)
        let sCurveSpine = [];
        for (let k = 0; k <= 10; k++) {
          let u = k / 10;
          let tx = lerp(t0 + 0.01, t1 - 0.01, u);
          let pL = evalRibPoint(cx, cy, side, rIdx, tx, asym * 0.35);
          let pU = evalRibPoint(cx, cy, side, rIdx + 1, tx, asym * 0.35);
          // S-wave across the chamber width
          let vCross = 0.5 + 0.32 * sin(u * 360 * 1.2 + foldDir * 65);
          let sx = lerp(pL.x, pU.x, vCross);
          let sy = lerp(pL.y, pU.y, vCross);
          let sw = lerp(4.2, 2.2, rIdx / 8) * (0.65 + 0.5 * sin(u * 180));
          sCurveSpine.push([sx, sy, sw]);
        }

        // Osmotic pink halo around secondary vein
        let haloRibbon = buildRibbonPoints(sCurveSpine.map(s => [s[0], s[1], s[2] * 1.55]));
        brush.noStroke();
        brush.wash("#cc4da3", 215);
        traceShape(haloRibbon, 0.3, true);

        // Crisp white secondary vein cut layer
        let whiteRibbon = buildRibbonPoints(sCurveSpine);
        brush.noStroke();
        brush.wash("#f7effa", 248);
        traceShape(whiteRibbon, 0.3, true);

        // Fine pen ink outline tracing the convoluted secondary vein
        brush.set("vein_pen", "#2b0538", 0.72);
        traceShape(whiteRibbon, 0.3, true);
      }

      // Add long undulating interstitial leaf blade ribbons running parallel between the major ribs
      let midBladeSpine = [];
      for (let i = 1; i <= steps - 1; i++) {
        let u = i / steps;
        let pL = lowerSpine[i];
        let pU = upperSpine[i];
        let wave = 0.5 + 0.22 * sin(u * 360 * 3.5 + rIdx * 45);
        midBladeSpine.push([
          lerp(pL.x, pU.x, wave),
          lerp(pL.y, pU.y, wave),
          lerp(3.4, 1.5, u)
        ]);
      }
      let bladeHalo = buildRibbonPoints(midBladeSpine.map(s => [s[0], s[1], s[2] * 1.6]));
      brush.noStroke();
      brush.wash("#b53491", 210);
      traceShape(bladeHalo, 0.28, true);

      let bladeCore = buildRibbonPoints(midBladeSpine);
      brush.noStroke();
      brush.wash("#faeefc", 245);
      traceShape(bladeCore, 0.28, true);

      brush.set("scalpel", "#380747", 0.65);
      traceShape(bladeCore, 0.28, true);
    }
  }
}

// ===========================================================================
// 5. APICAL CROWN ARCHES & NESTED DOME VEINS (ABOVE THE CORE APEX)
// ===========================================================================
function drawApicalCrownLayers(cx, cy) {
  // In the upper dome (between -155 deg and -25 deg from center), leaves arch continuously
  // over the top of the core in stacked, ruffled Wycinanki omega-arches
  const numArches = 9;
  for (let aIdx = 0; aIdx < numArches; aIdx++) {
    let u = aIdx / (numArches - 1); // 0 = outermost top arch, 1 = innermost arch above heart
    let baseR = lerp(378, 138, u);
    let archCenterY = lerp(cy + 10, cy - 55, u);
    let angleSpan = lerp(52, 68, u);

    // 1. Deep shadow trough beneath the arch
    let troughSpine = [];
    let veinSpine = [];
    let steps = 36;

    for (let i = 0; i <= steps; i++) {
      let t = (i / steps) * 2 - 1; // -1 (left) to +1 (right)
      let symT = Math.abs(t);
      let angle = -90 + t * angleSpan;

      // Symmetrical crenellated / folk-scalloped undulations in the cabbage dome
      let freq = 7 + (aIdx % 3) * 2;
      let undul = cos(symT * 180 * freq) * lerp(9.5, 5.5, u) * (1 - symT * 0.35);
      let secondUndul = sin(symT * 180 * (freq * 2)) * 3.2;

      let r = baseR + undul + secondUndul;
      let px = cx + cos(angle) * r * 1.06;
      let py = archCenterY + sin(angle) * r * 0.92;

      let w = lerp(7.2, 3.8, u) * (1 - symT * 0.45) + (undul > 0 ? 1.4 : -0.6);
      veinSpine.push([px, py, Math.max(1.8, w)]);
      troughSpine.push([px, py + w * 2.1, Math.max(3.0, w * 1.9)]);
    }

    // Draw dark purple-black cavity trough under each arch
    let troughPoly = buildRibbonPoints(troughSpine);
    brush.noStroke();
    brush.wash("#14031f", 240);
    traceShape(troughPoly, 0.25, true);

    // Draw rich magenta-violet leaf fold bordering the arch
    let magentaPoly = buildRibbonPoints(veinSpine.map(s => [s[0], s[1] + 2.5, s[2] * 2.15]));
    brush.noStroke();
    brush.wash(aIdx % 2 === 0 ? "#7a1677" : "#99218c", 225);
    traceShape(magentaPoly, 0.25, true);

    // Draw translucent rose-pink osmotic bleed zone
    let pinkPoly = buildRibbonPoints(veinSpine.map(s => [s[0], s[1], s[2] * 1.48]));
    brush.noStroke();
    brush.wash("#d95cb0", 230);
    traceShape(pinkPoly, 0.25, true);

    // Draw crisp white cut vein arch
    let whitePoly = buildRibbonPoints(veinSpine);
    brush.noStroke();
    brush.wash("#fbf7fc", 252);
    traceShape(whitePoly, 0.25, true);

    // Fine pen tracing of the convoluted arch
    brush.set("vein_pen", "#280536", 0.78);
    traceShape(whitePoly, 0.25, true);
  }
}

// ===========================================================================
// 6. CENTRAL CORE (STALK / PITH) & GRAND SYMMETRICAL WHITE MIDRIBS
// ===========================================================================
function drawCoreAndPrimaryVeins(cx, cy) {
  // First draw the 9 pairs of Grand Symmetrical Primary White Midribs (from bottom 0 to inner 8)
  for (let rIdx = 0; rIdx < 9; rIdx++) {
    for (let side of [-1, 1]) {
      let asym = side === 1 ? 1.0 : -1.0;
      let steps = 34;
      let spine = [];

      for (let i = 0; i <= steps; i++) {
        let t = i / steps;
        let pt = evalRibPoint(cx, cy, side, rIdx, t, asym * 0.35);
        spine.push([pt.x, pt.y, pt.w]);
      }

      // 1. Deep shadow bevel along the underside of the major rib
      let shadowSpine = spine.map(s => [s[0] + side * 2.5, s[1] + 4.5, s[2] * 1.45]);
      let shadowPoly = buildRibbonPoints(shadowSpine);
      brush.noStroke();
      brush.wash("#160321", 230);
      traceShape(shadowPoly, 0.25, true);

      // 2. Outer magenta-rose osmotic bleed border
      let bleedSpine = spine.map(s => [s[0], s[1], s[2] * 1.38]);
      let bleedPoly = buildRibbonPoints(bleedSpine);
      brush.noStroke();
      brush.wash("#c9439b", 235);
      traceShape(bleedPoly, 0.25, true);

      // 3. Soft lilac-pink sub-cortex layer
      let lilacSpine = spine.map(s => [s[0], s[1], s[2] * 1.16]);
      let lilacPoly = buildRibbonPoints(lilacSpine);
      brush.noStroke();
      brush.wash("#e8bfe0", 245);
      traceShape(lilacPoly, 0.25, true);

      // 4. Crisp ivory-white medullary vein core
      let corePoly = buildRibbonPoints(spine);
      brush.noStroke();
      brush.wash("#fcf9fd", 255);
      traceShape(corePoly, 0.25, true);

      // 5. Internal vascular bundle striations along the center of the thick rib
      let midLinePts = spine.slice(0, 24).map(s => [s[0], s[1], s[2] * 0.12]);
      brush.set("scalpel", "#d49bc8", 0.65);
      brush.spline(midLinePts, 0.35);

      // 6. Crisp pen contour tracing every curve of the white rib
      brush.set("vein_pen", "#230430", 0.9);
      traceShape(corePoly, 0.25, true);

      // 7. Bifurcating secondary branch off the midrib (echoing paper-cut symmetry)
      if (rIdx < 7) {
        let branchStartIdx = 11 + (rIdx % 3) * 3;
        let branchSpine = [];
        for (let b = 0; b <= 10; b++) {
          let tb = b / 10;
          let tMain = (branchStartIdx / steps) + tb * 0.28;
          let pMain = evalRibPoint(cx, cy, side, rIdx, Math.min(0.96, tMain), asym * 0.35);
          let pUpper = evalRibPoint(cx, cy, side, rIdx + 1, Math.min(0.96, tMain), asym * 0.35);
          let pull = Math.pow(tb, 0.75) * 0.65;
          let bx = lerp(pMain.x, pUpper.x, pull);
          let by = lerp(pMain.y, pUpper.y, pull) + sin(tb * 360) * 6;
          let bw = pMain.w * lerp(0.65, 0.18, tb);
          branchSpine.push([bx, by, Math.max(1.4, bw)]);
        }
        let branchHalo = buildRibbonPoints(branchSpine.map(s => [s[0], s[1], s[2] * 1.4]));
        brush.noStroke();
        brush.wash("#d152a5", 220);
        traceShape(branchHalo, 0.25, true);

        let branchWhite = buildRibbonPoints(branchSpine);
        brush.noStroke();
        brush.wash("#fbf7fc", 252);
        traceShape(branchWhite, 0.25, true);

        brush.set("scalpel", "#2c063b", 0.75);
        traceShape(branchWhite, 0.25, true);
      }
    }
  }

  // =========================================================================
  // NOW DRAW THE CENTRAL CORE (STALK / PITH) FUSING ALL RIBS AT THE AXIS
  // =========================================================================
  // Build the symmetrical gothic-chalice core outline from bottom stem (cy+395) to apex (cy-75)
  function getCorePolygon(scaleX = 1.0, offsetY = 0) {
    let leftPts = [];
    let rightPts = [];
    let steps = 32;
    for (let i = 0; i <= steps; i++) {
      let u = i / steps; // 0 = bottom cut stem, 1 = upper core apex
      let y = lerp(cy + 392, cy - 72, u) + offsetY;
      // Width profile: broad at base, flares at rib attachment nodes, tapers to a point at apex
      let baseW = lerp(74, 4, Math.pow(u, 0.82));
      // Node bulges where the 9 pairs of ribs join the stalk
      let nodeBulge = sin(u * 180 * 8) * 5.5 * (1 - u * 0.6);
      // Basal root neck flare near u = 0.15
      let neckFlare = sin(constrain(map(u, 0, 0.35, 0, 180), 0, 180)) * 14;
      let w = (baseW + nodeBulge + neckFlare) * scaleX;
      leftPts.push([cx - w, y]);
      rightPts.push([cx + w, y]);
    }
    rightPts.reverse();
    return leftPts.concat(rightPts);
  }

  // Layer 1: Deep violet-magenta outer vascular cortex of the stalk
  let coreOuter = getCorePolygon(1.26, 0);
  brush.noStroke();
  brush.wash("#8a1c80", 240);
  traceShape(coreOuter, 0.2, true);

  // Layer 2: Luminous rose-magenta osmotic ring around the core
  let coreRose = getCorePolygon(1.14, 0);
  brush.noStroke();
  brush.wash("#cf51a3", 245);
  traceShape(coreRose, 0.2, true);

  // Layer 3: Pale orchid cambium layer
  let coreOrchid = getCorePolygon(1.04, 0);
  brush.noStroke();
  brush.wash("#edd0e7", 250);
  traceShape(coreOrchid, 0.2, true);

  // Layer 4: Crisp ivory-white central pith
  let coreWhite = getCorePolygon(0.92, 0);
  brush.noStroke();
  brush.wash("#fbf8fc", 255);
  traceShape(coreWhite, 0.2, true);

  // Layer 5: Subtle inner heart-pith fibrous core (pale warm cream-lilac)
  let coreInnerPith = getCorePolygon(0.54, 12);
  brush.noStroke();
  brush.wash("#f2e6f5", 220);
  traceShape(coreInnerPith, 0.2, true);

  // Vascular cambium dotted lines & horizontal growth nodes inside the core pith
  brush.set("scalpel", "#b874a8", 0.75);
  traceShape(coreInnerPith, 0.25, true);

  for (let n = 1; n <= 14; n++) {
    let u = n / 15;
    let ny = lerp(cy + 375, cy - 45, u);
    let halfW = lerp(52, 6, Math.pow(u, 0.85));
    // Horizontal arched growth node lines inside the stalk pith
    let nodePts = [
      [cx - halfW, ny + 4],
      [cx - halfW * 0.5, ny - 2],
      [cx, ny - 4],
      [cx + halfW * 0.5, ny - 2],
      [cx + halfW, ny + 4]
    ];
    brush.set("2H", "#cfa4c8", 0.65);
    brush.spline(nodePts, 0.4);
  }

  // Crisp bottom knife-cut base of the stalk stub
  let stubBottom = [
    [cx - 72, cy + 390],
    [cx, cy + 395],
    [cx + 72, cy + 390]
  ];
  brush.set("vein_pen", "#240430", 1.3);
  brush.spline(stubBottom, 0.2);
}

// ===========================================================================
// 7. INNER HEART ROSETTE (EMBRYONIC SPIRAL FOLDS AROUND CORE APEX)
// ===========================================================================
function drawInnerHeartRosette(cx, cy) {
  // Directly flanking and crowning the tip of the core (cx, cy - 72) are the tightly
  // curled embryonic leaves—like a symmetrical Polish paper-cut floral centerpiece
  const heartY = cy - 88;

  for (let side of [-1, 1]) {
    // 3 nested embryonic paisley / spiral curls per side
    for (let curl = 0; curl < 3; curl++) {
      let u = curl / 2;
      let radX = lerp(66, 24, u);
      let radY = lerp(58, 22, u);
      let cX = cx + side * lerp(48, 18, u);
      let cY = heartY - lerp(8, 24, u);

      let spiralSpine = [];
      let steps = 22;
      for (let i = 0; i <= steps; i++) {
        let t = i / steps;
        let a = lerp(90, -220, t);
        let r = lerp(1.0, 0.25, t);
        let sx = cX + side * cos(a) * radX * r;
        let sy = cY + sin(a) * radY * r;
        let sw = lerp(5.2, 1.8, t) * lerp(1.0, 0.65, u);
        spiralSpine.push([sx, sy, sw]);
      }

      // Deep violet cavity behind curl
      let cavPoly = buildRibbonPoints(spiralSpine.map(s => [s[0], s[1], s[2] * 1.9]));
      brush.noStroke();
      brush.wash("#1a0326", 235);
      traceShape(cavPoly, 0.3, true);

      // Luminous magenta-pink sheath
      let pinkPoly = buildRibbonPoints(spiralSpine.map(s => [s[0], s[1], s[2] * 1.4]));
      brush.noStroke();
      brush.wash("#d44ea6", 235);
      traceShape(pinkPoly, 0.3, true);

      // Crisp white embryonic leaf vein
      let whitePoly = buildRibbonPoints(spiralSpine);
      brush.noStroke();
      brush.wash("#fcf9fd", 255);
      traceShape(whitePoly, 0.3, true);

      // Fine ink contour
      brush.set("scalpel", "#290538", 0.78);
      traceShape(whitePoly, 0.3, true);
    }
  }

  // Central apical bud jewel right above the tip of the stalk
  let budPts = [
    [cx, heartY - 56],
    [cx + 15, heartY - 26],
    [cx, heartY + 8],
    [cx - 15, heartY - 26]
  ];
  brush.noStroke();
  brush.wash("#b82d8f", 240);
  traceShape(budPts, 0.35, true);

  let innerBudPts = [
    [cx, heartY - 46],
    [cx + 8, heartY - 25],
    [cx, heartY - 2],
    [cx - 8, heartY - 25]
  ];
  brush.noStroke();
  brush.wash("#ffffff", 255);
  traceShape(innerBudPts, 0.35, true);
  brush.set("scalpel", "#2a0538", 0.8);
  traceShape(innerBudPts, 0.35, true);
}

// ===========================================================================
// 8. KNIFE-SCORED EDGE & PARALLEL BLADE MICRO-STRIATIONS
// ===========================================================================
function drawKnifeScoredSurfaceAndEdge(cx, cy) {
  // 1. Crisp knife-cut perimeter rim around the entire sliced cabbage face
  let cutEdgePts = getCutHeadOutline(cx, cy, 1);
  brush.set("vein_pen", "#0c0112", 1.35);
  traceShape(cutEdgePts, 0.2, true);

  // Razor-sharp white/pink outer cuticle line where the blade sheared the epidermis
  let innerRimPts = getCutHeadOutline(cx, cy, -2);
  // Top half catches bright specular edge light
  let topArc = innerRimPts.slice(0, 32).concat(innerRimPts.slice(60));
  brush.set("scalpel", "#f2d5ea", 0.85);
  for (let i = 0; i < innerRimPts.length - 1; i += 2) {
    let p1 = innerRimPts[i];
    let p2 = innerRimPts[i + 1];
    brush.set("scalpel", i < 45 ? "#f5dcf0" : "#9c3b8c", 0.8);
    brush.line(p1[0], p1[1], p2[0], p2[1]);
  }

  // 2. Parallel chef's-knife micro-striations across the flat cut face (angle ~ 88.5 deg)
  // A large sharp blade leaves subtle straight parallel score lines and faint anthocyanin juice trails
  const numScores = 105;
  for (let i = 0; i < numScores; i++) {
    let xBase = map(i, 0, numScores - 1, cx - 395, cx + 395) + random(-2, 2);
    let dx = (xBase - cx) / 415;
    if (Math.abs(dx) >= 0.97) continue;

    let maxHalfH = Math.sqrt(1 - dx * dx) * 380;
    let yTop = cy - maxHalfH + random(8, 35);
    let yBot = cy + maxHalfH - random(12, 35);

    // Slight blade tilt (1.5 degrees from vertical)
    let tilt = (yBot - yTop) * 0.024;

    // Draw broken segments along the blade score path
    let segs = 5;
    for (let s = 0; s < segs; s++) {
      if (random() < 0.28) continue;
      let t0 = (s + random(0.05, 0.2)) / segs;
      let t1 = (s + random(0.65, 0.92)) / segs;
      let x0 = xBase + tilt * t0;
      let y0 = lerp(yTop, yBot, t0);
      let x1 = xBase + tilt * t1;
      let y1 = lerp(yTop, yBot, t1);

      // Near center (over the white core), knife drags faint pink-lilac pigment downward
      let distFromAxis = Math.abs(x0 - cx);
      if (distFromAxis < 65 && y0 > cy - 50) {
        brush.set("scalpel", i % 2 === 0 ? "#d99ec9" : "#ffffff", 0.42);
      } else {
        // Across the violet-magenta folds and white veins: alternating fine sheen and micro-groove
        brush.set("scalpel", i % 3 === 0 ? "#f7e1f3" : "#4a0b57", 0.36);
      }
      brush.line(x0, y0, x1, y1);
    }
  }
}

// ===========================================================================
// 9. HYPERREAL MOISTURE BEADS ON THE CUT FACE
// ===========================================================================
function drawSingleMoistureBead(x, y, r, onWhiteVein = true) {
  // 1. Cast shadow below and slightly right of the water droplet
  brush.noStroke();
  brush.wash(onWhiteVein ? "#7a246f" : "#0c0112", 185);
  brush.circle(x + r * 0.28, y + r * 0.48, r * 0.95, 0.08);

  // 2. Droplet main body (subtle lensing of underlying magenta/white tissue)
  brush.noStroke();
  brush.wash(onWhiteVein ? "#f2d5ea" : "#611168", 210);
  brush.circle(x, y, r, 0.06);

  // 3. Upper-left dark refractive rim (where light enters the convex meniscus)
  brush.set("scalpel", onWhiteVein ? "#6e1c66" : "#160221", 0.85);
  brush.arc(x, y, r * 0.92, 195, 330);

  // 4. Lower-right internal caustic reflection (focusing bright rose/white light)
  brush.noStroke();
  brush.wash(onWhiteVein ? "#ffffff" : "#f58cd4", 235);
  brush.circle(x + r * 0.24, y + r * 0.28, r * 0.52, 0.05);

  // 5. Crisp upper-left primary specular highlight (pure opaque white glint)
  let hx = x - r * 0.32;
  let hy = y - r * 0.32;
  let hr = Math.max(1.3, r * 0.28);
  brush.noStroke();
  brush.wash("#ffffff", 255);
  brush.circle(hx, hy, hr, 0.02);

  brush.set("specular", "#ffffff", Math.max(0.45, r * 0.12));
  brush.line(hx - hr * 0.3, hy - hr * 0.2, hx + hr * 0.3, hy + hr * 0.2);

  // 6. Tiny secondary pinpoint sparkle on larger beads
  if (r > 5.5) {
    brush.set("specular", "#ffffff", 0.45);
    brush.line(x + r * 0.28, y + r * 0.32, x + r * 0.34, y + r * 0.32);
  }
}

function drawMoistureBeads(cx, cy) {
  let beads = [];

  // A. Moisture beads clinging to the freshly sliced primary white ribs (symmetric pairs + organic offset)
  for (let rIdx = 0; rIdx < 9; rIdx++) {
    let countOnRib = 3;
    for (let k = 0; k < countOnRib; k++) {
      let tBase = 0.16 + k * 0.28 + random(-0.05, 0.05);
      for (let side of [-1, 1]) {
        let t = constrain(tBase + random(-0.03, 0.03), 0.1, 0.88);
        let pt = evalRibPoint(cx, cy, side, rIdx, t, side * 0.35);
        let offsetAngle = random(360);
        let offsetDist = random(0, pt.w * 0.65);
        let bx = pt.x + cos(offsetAngle) * offsetDist;
        let by = pt.y + sin(offsetAngle) * offsetDist;
        let br = random(3.2, 8.2) * lerp(1.15, 0.75, t);
        beads.push({ x: bx, y: by, r: br, onWhite: true });
      }
    }
  }

  // B. Moisture beads exuding from the vascular cambium of the central stalk/core
  for (let i = 0; i < 14; i++) {
    let by = lerp(cy + 350, cy - 50, i / 13) + random(-10, 10);
    let u = map(by, cy + 390, cy - 70, 0, 1);
    let maxW = lerp(55, 8, u);
    let bx = cx + random(-maxW, maxW);
    let br = random(3.5, 9.0);
    beads.push({ x: bx, y: by, r: br, onWhite: true });
  }

  // C. Dewdrops nestled on the deep magenta-violet folds and upper crown arches
  for (let i = 0; i < 24; i++) {
    let angle = random(-165, -15);
    let rad = random(135, 365);
    let bx = cx + cos(angle) * rad * 1.02;
    let by = cy + sin(angle) * rad * 0.94;
    let br = random(3.0, 7.5);
    beads.push({ x: bx, y: by, r: br, onWhite: i % 2 === 0 });
  }

  // Render all moisture beads
  for (let b of beads) {
    drawSingleMoistureBead(b.x, b.y, b.r, b.onWhite);
  }
}

