// Helper for crisp polygon washes
function washPoly(pts, col, alpha) {
  let p = new brush.Polygon(pts);
  p.wash(col, alpha);
  return p;
}

// Helper for watercolor polygon fills
function watercolorPoly(pts, col, alpha, bleed = 0.18, tex = 0.45) {
  let p = new brush.Polygon(pts);
  p.fill(col, alpha, bleed, tex);
  return p;
}

// Helper to generate circle polygon points
function circlePts(cx, cy, r, n = 72, wobble = 0) {
  let pts = [];
  for (let i = 0; i < n; i++) {
    let a = (i / n) * 360;
    let rad = r + (wobble ? (noise(cx * 0.01 + cos(a) * 1.5, cy * 0.01 + sin(a) * 1.5) - 0.5) * wobble : 0);
    pts.push([cx + cos(a) * rad, cy + sin(a) * rad]);
  }
  return pts;
}

function draw() {
  translate(-width / 2, -height / 2);
  brush.noField();

  // =========================================================================
  // 1. ARCHIVAL OFF-WHITE GROUND
  // =========================================================================
  background("#F3EFE4");

  // Subtle paper fiber & warm tone modulation
  brush.noStroke();
  watercolorPoly(
    [[40, 40], [1160, 40], [1160, 1160], [40, 1160]],
    "#ECE5D5",
    32,
    0.05,
    0.35
  );

  // Very fine paper tooth
  brush.set("2H", "#DED6C4", 0.3);
  for (let i = 0; i < 160; i++) {
    let x = random(60, 1140);
    let y = random(60, 1140);
    let len = random(18, 65);
    let ang = random(-8, 8);
    brush.line(x, y, x + cos(ang) * len, y + sin(ang) * len);
  }

  // =========================================================================
  // 2. BAUHAUS CONSTRUCTIVIST GEOMETRY (Hard-edged Marker + Rotring Order)
  // =========================================================================

  // --- A. Thin Yellow Rule anchoring the corners ---
  // Top-left primary L-rule + bottom-right counter-rule in vivid Bauhaus cadmium yellow
  const yellowCol = "#F7B500";
  const yellowDeep = "#E09F00";

  // Top-left horizontal bar (x: 84 -> 620, y: 84 -> 93)
  let tlHoriz = [[84, 84], [620, 84], [620, 93], [84, 93]];
  washPoly(tlHoriz, yellowCol, 250);
  // Top-left vertical bar (x: 84 -> 93, y: 84 -> 640)
  let tlVert = [[84, 84], [93, 84], [93, 640], [84, 640]];
  washPoly(tlVert, yellowCol, 250);

  // Bottom-right corner anchor rule (x: 780 -> 1116, y: 1107 -> 1116 & vertical 870 -> 1116)
  let brHoriz = [[780, 1107], [1116, 1107], [1116, 1116], [780, 1116]];
  let brVert = [[1107, 870], [1116, 870], [1116, 1116], [1107, 1116]];
  washPoly(brHoriz, yellowCol, 250);
  washPoly(brVert, yellowCol, 250);

  // Reinforce yellow rules with hard-edged marker strokes
  brush.set("marker", yellowCol, 0.9);
  brush.line(86, 88.5, 618, 88.5);
  brush.line(88.5, 86, 88.5, 638);
  brush.line(782, 1111.5, 1114, 1111.5);
  brush.line(1111.5, 872, 1111.5, 1114);

  // Crisp yellow datum block in top-left corner
  let tlBlock = [[104, 104], [134, 104], [134, 114], [104, 114]];
  washPoly(tlBlock, yellowDeep, 245);
  brush.set("marker", yellowCol, 0.7);
  brush.line(106, 109, 132, 109);

  // --- B. Flat Vermilion Disc sitting behind the flame ---
  const discX = 720;
  const discY = 472;
  const discR = 216;
  const vermilion = "#E32417";
  const vermilionRich = "#D11B0F";

  let discPoly = circlePts(discX, discY, discR, 96, 0);
  let discObj = washPoly(discPoly, vermilion, 252);

  // Dense hard-edged marker hatch across the vermilion disc for authentic flat poster pigment
  brush.hatchStyle("marker", vermilionRich, 1.35);
  discObj.hatch(5.5, -36, { rand: 0.01 });
  brush.noHatch();

  // Second pass of marker wash to unify the flat vermilion plane
  washPoly(discPoly, vermilion, 165);

  // Crisp marker + rotring perimeter on the vermilion disc
  brush.set("marker", vermilionRich, 0.75);
  for (let i = 0; i < discPoly.length; i++) {
    let p1 = discPoly[i];
    let p2 = discPoly[(i + 1) % discPoly.length];
    brush.line(p1[0], p1[1], p2[0], p2[1]);
  }

  // --- C. Black Bar cutting the lower third ---
  const barTop = 812;
  const barBot = 934;
  const barLeft = 84;
  const barRight = 1116;
  const bauhausBlack = "#151413";

  let blackBarPts = [
    [barLeft, barTop],
    [barRight, barTop],
    [barRight, barBot],
    [barLeft, barBot]
  ];
  let barObj = washPoly(blackBarPts, bauhausBlack, 254);

  // Dense marker fill inside the black bar
  brush.hatchStyle("marker", "#0E0E0D", 1.5);
  barObj.hatch(5, 0, { rand: 0.008 });
  brush.noHatch();
  washPoly(blackBarPts, bauhausBlack, 210);

  // Secondary thin constructivist black rule just below the bar on the right
  let subBarPts = [[720, 950], [1116, 950], [1116, 957], [720, 957]];
  washPoly(subBarPts, bauhausBlack, 250);

  // --- D. Economical Mechanical Constructivist Registration Marks (Rotring) ---
  brush.set("rotring", "#2A2826", 0.35);
  // Top-left measurement ticks along yellow rule
  for (let x = 140; x <= 600; x += 40) {
    let h = (x % 120 === 20) ? 10 : 5;
    brush.line(x, 93, x, 93 + h);
  }
  for (let y = 140; y <= 600; y += 40) {
    let w = (y % 120 === 20) ? 10 : 5;
    brush.line(93, y, 93 + w, y);
  }

  // Subtle mechanical datum crosshair & circle in upper-left negative space
  brush.set("rotring", "#3A3632", 0.3);
  brush.line(185, 220, 235, 220);
  brush.line(210, 195, 210, 245);
  brush.circle(210, 220, 12, 0.02);

  // Constructivist axis projection hairline extending beyond the match base and tip
  // Match axis vector: from (280, 1070) to (736, 456) -> angle = -53.4 deg
  const mX0 = 280, mY0 = 1070;
  const mX1 = 736, mY1 = 456;
  const mDX = mX1 - mX0;
  const mDY = mY1 - mY0;
  const mLen = sqrt(mDX * mDX + mDY * mDY); // ~765.2 px
  const uX = mDX / mLen; //  0.5959
  const uY = mDY / mLen; // -0.8030
  const nX = -uY;        //  0.8030 (perpendicular down-right)
  const nY = uX;         //  0.5959

  // Helper to convert match coordinates (s along stick, d perpendicular) to canvas (x, y)
  function mPt(s, d) {
    return [mX0 + uX * s + nX * d, mY0 + uY * s + nY * d];
  }

  // Fine mechanical extension line below match base & caliper ticks
  brush.set("rotring", "#2A2826", 0.32);
  let extA = mPt(-75, 0);
  let extB = mPt(-18, 0);
  brush.line(extA[0], extA[1], extB[0], extB[1]);
  let tick1 = mPt(-55, -12), tick2 = mPt(-55, 12);
  brush.line(tick1[0], tick1[1], tick2[0], tick2[1]);

  // Mechanical horizontal datum through disc center (left side only, stopping before disc)
  brush.line(84, discY, discX - discR - 16, discY);
  brush.line(discX - discR - 16, discY - 8, discX - discR - 16, discY + 8);

  // Small yellow mechanical square accent sitting on the black bar's left edge
  washPoly([[84, barTop], [104, barTop], [104, barTop + 20], [84, barTop + 20]], yellowCol, 255);

  // =========================================================================
  // 3. CURL OF GREY SMOKE (Upper Negative Space & Top of Disc)
  // =========================================================================
  // The smoke rises from the flame tip around (718, 198), curving in a tense,
  // silky laminar-to-turbulent ribbon up to (790, 48).

  // Define centerline of primary smoke ribbon
  function smokeCenter(t) {
    // t in [0, 1], y goes from 208 down to 44
    let y = lerp(208, 44, t);
    let x = 718
      - sin(t * 195) * 44 * pow(t, 0.65)
      + sin(t * 370 - 35) * 26 * pow(t, 1.3)
      + pow(t, 2.4) * 68;
    return [x, y];
  }

  // Build layered watercolor smoke envelopes in the off-white space above the disc
  let smokeLeftOuter = [];
  let smokeRightOuter = [];
  let smokeLeftCore = [];
  let smokeRightCore = [];

  for (let i = 0; i <= 28; i++) {
    let t = i / 28;
    let c = smokeCenter(t);
    let wOuter = lerp(5, 38, pow(t, 0.85)) + sin(t * 540) * 6 * t;
    let wCore = lerp(2.5, 16, pow(t, 0.9)) + cos(t * 420) * 4 * t;
    smokeLeftOuter.push([c[0] - wOuter, c[1] + sin(t * 300) * 4]);
    smokeRightOuter.unshift([c[0] + wOuter * 0.85, c[1] - cos(t * 300) * 4]);
    smokeLeftCore.push([c[0] - wCore * 0.6, c[1]]);
    smokeRightCore.unshift([c[0] + wCore, c[1]]);
  }

  let smokeOuterPoly = smokeLeftOuter.concat(smokeRightOuter);
  let smokeCorePoly = smokeLeftCore.concat(smokeRightCore);

  // Translucent watercolor washes for smoke
  brush.noStroke();
  watercolorPoly(smokeOuterPoly, "#B8C0C8", 48, 0.38, 0.55);
  watercolorPoly(smokeCorePoly, "#7E8791", 58, 0.32, 0.65);

  // Secondary curled vortex lobe near the top turn (around t = 0.62..0.92)
  let vortexPts = [];
  for (let i = 0; i < 24; i++) {
    let a = (i / 24) * 360;
    let rx = 28 + sin(a * 2) * 6;
    let ry = 19 + cos(a * 3) * 4;
    vortexPts.push([696 + cos(a) * rx, 96 + sin(a) * ry]);
  }
  watercolorPoly(vortexPts, "#8F969E", 45, 0.42, 0.5);

  // Silky soft_plume & fine graphite filaments showing folded veil edges of smoke
  for (let strand = 0; strand < 18; strand++) {
    let phase = map(strand, 0, 17, -1, 1);
    let sPts = [];
    for (let i = 0; i <= 22; i++) {
      let t = i / 22;
      let c = smokeCenter(t);
      let spread = lerp(1.5, 28, pow(t, 0.85));
      let twist = sin(t * 320 + strand * 28) * spread * 0.75 + phase * spread * 0.45;
      let yOff = cos(t * 280 + strand * 22) * 6 * t;
      let press = sin(t * 180) * 0.8 + 0.2;
      sPts.push([c[0] + twist, c[1] + yOff, press]);
    }
    if (strand % 3 === 0) {
      brush.set("soft_plume", "#6E7680", random(0.45, 0.85));
      brush.spline(sPts, 0.6);
    }
    // Crisp veil edge in 2H / HB graphite
    let col = (strand % 2 === 0) ? "#596068" : "#8A929A";
    brush.set(strand % 4 === 0 ? "HB" : "2H", col, random(0.22, 0.42));
    brush.spline(sPts, 0.65);
  }

  // Delicate curled smoke loop filaments at the top vortex
  for (let k = 0; k < 9; k++) {
    let loopPts = [];
    let rBase = 10 + k * 2.8;
    for (let i = 0; i <= 16; i++) {
      let a = -60 + (i / 16) * 290;
      let r = rBase * (0.65 + 0.45 * (i / 16));
      loopPts.push([
        702 + cos(a) * r * 1.25 + k * 1.2,
        102 + sin(a) * r * 0.85 - k * 1.5,
        0.3 + 0.6 * sin((i / 16) * 180)
      ]);
    }
    brush.set("2H", "#666E78", 0.28);
    brush.spline(loopPts, 0.65);
  }

  // =========================================================================
  // 4. CAST SHADOW OF THE MATCHSTICK (Grounding Trompe-l'oeil Realism)
  // =========================================================================
  // Light comes from upper-left + the flame itself. The stick casts a subtle,
  // crisp shadow shifted (+20, +15) across the off-white ground and vermilion disc.
  let shOffX = 20, shOffY = 15;
  // Shadow segments on off-white paper (below black bar & between black bar and disc)
  let shSeg1 = [
    [mPt(0, -13)[0] + shOffX, mPt(0, -13)[1] + shOffY],
    [mPt(190, -13)[0] + shOffX, mPt(190, -13)[1] + shOffY],
    [mPt(190, 12)[0] + shOffX, mPt(190, 12)[1] + shOffY],
    [mPt(0, 12)[0] + shOffX, mPt(0, 12)[1] + shOffY]
  ];
  watercolorPoly(shSeg1, "#C4B9A5", 72, 0.15, 0.3);

  let shSeg2 = [
    [mPt(340, -13)[0] + shOffX, mPt(340, -13)[1] + shOffY],
    [mPt(535, -13)[0] + shOffX, mPt(535, -13)[1] + shOffY],
    [mPt(535, 12)[0] + shOffX, mPt(535, 12)[1] + shOffY],
    [mPt(340, 12)[0] + shOffX, mPt(340, 12)[1] + shOffY]
  ];
  watercolorPoly(shSeg2, "#C2B6A0", 70, 0.15, 0.3);

  // Shadow segment falling across the vermilion disc (up to the match neck where flame light cancels shadow)
  let shSeg3 = [
    [mPt(535, -11)[0] + shOffX, mPt(535, -11)[1] + shOffY],
    [mPt(665, -8)[0] + shOffX, mPt(665, -8)[1] + shOffY],
    [mPt(665, 10)[0] + shOffX, mPt(665, 10)[1] + shOffY],
    [mPt(535, 11)[0] + shOffX, mPt(535, 11)[1] + shOffY]
  ];
  washPoly(shSeg3, "#9E140B", 95);

  // =========================================================================
  // 5. TRANSLUCENT BLUE BASE OF FLAME & LUMINOUS FLAME BODY (Under-layer)
  // =========================================================================
  // The flame wraps around the match neck/head (s = 685..775) and rises from
  // (742, 448) up to (718, 198), crossing out of the vermilion disc at y = 256.

  // Helper for flame envelope shape
  // t = 0 at base (around match neck s = 685, i.e. (688, 520))
  // t = 1 at upper flame tip (718, 196)
  function flameEnvelope(t, side) {
    // Center spine starts aligned with match head and curves vertically upward
    let startX = 696, startY = 508;
    let midX = 752, midY = 395;
    let topX = 718, topY = 196;

    // Quadratic bezier spine
    let u = 1 - t;
    let cx = u * u * startX + 2 * u * t * midX + t * t * topX;
    let cy = u * u * startY + 2 * u * t * midY + t * t * topY;

    // Add subtle buoyant S-wave
    cx += sin(t * 240 - 20) * 8 * pow(t, 1.2);

    // Width profile: bulbous blue base at bottom, broad luminous belly in middle, sharp tip at top
    let w;
    if (t < 0.25) {
      w = sin((t / 0.25) * 90) * 52;
    } else {
      let tb = (t - 0.25) / 0.75;
      w = 52 * pow(1 - tb, 0.82) * (1 + 0.18 * sin(tb * 220));
    }

    // Asymmetry: right side bulges slightly more around the angled match head
    let asym = (side > 0) ? (1.12 - 0.2 * t) : (0.95 + 0.08 * sin(t * 180));
    // Normal direction roughly horizontal as flame rises, tilted at base
    let tiltAng = lerp(-36, 0, pow(t, 0.55));
    let nx = cos(tiltAng) * side * w * asym;
    let ny = sin(tiltAng) * side * w * asym;

    return [cx + nx, cy + ny];
  }

  // --- A. Outer Amber-Orange Thermal Halo ---
  let outerFlamePts = [];
  for (let i = 0; i <= 40; i++) outerFlamePts.push(flameEnvelope(i / 40, -1.12));
  for (let i = 40; i >= 0; i--) outerFlamePts.push(flameEnvelope(i / 40, 1.12));
  washPoly(outerFlamePts, "#FF5400", 85);

  // --- B. Translucent Blue Base (Chemiluminescent Gas Cup at Bottom of Flame) ---
  // Wraps s = 670 to s = 765 around the match neck and lower head
  let blueCupOuter = [];
  let blueCupInner = [];
  let blueRimCyan = [];

  for (let i = 0; i <= 28; i++) {
    let t = (i / 28) * 0.46; // lower 46% of flame height
    let taper = (t < 0.30) ? 1.0 : map(t, 0.30, 0.46, 1.0, 0.0);
    blueCupOuter.push(flameEnvelope(t, -1.06 * taper - 0.12 * (1 - taper)));
  }
  for (let i = 28; i >= 0; i--) {
    let t = (i / 28) * 0.46;
    let taper = (t < 0.30) ? 1.0 : map(t, 0.30, 0.46, 1.0, 0.0);
    blueCupOuter.push(flameEnvelope(t, 1.06 * taper + 0.12 * (1 - taper)));
  }

  for (let i = 0; i <= 24; i++) {
    let t = 0.015 + (i / 24) * 0.38;
    let taper = (t < 0.25) ? 0.92 : map(t, 0.25, 0.395, 0.92, 0.0);
    blueCupInner.push(flameEnvelope(t, -0.88 * taper));
  }
  for (let i = 24; i >= 0; i--) {
    let t = 0.015 + (i / 24) * 0.38;
    let taper = (t < 0.25) ? 0.92 : map(t, 0.25, 0.395, 0.92, 0.0);
    blueCupInner.push(flameEnvelope(t, 0.88 * taper));
  }

  // Cushion the blue base against the vermilion disc so it glows with electric clarity
  washPoly(blueCupOuter, "#0A2268", 215);
  washPoly(blueCupOuter, "#1245E8", 210);
  washPoly(blueCupInner, "#2A85FF", 215);

  // Inner dark/translucent pyrolysis pocket (the "dead space" around the neck where gas is cool)
  let darkPocket = [];
  for (let i = 0; i <= 20; i++) {
    let t = 0.03 + (i / 20) * 0.25;
    let taper = sin(((t - 0.03) / 0.25) * 180);
    darkPocket.push(flameEnvelope(t, -0.58 * taper));
  }
  for (let i = 20; i >= 0; i--) {
    let t = 0.03 + (i / 20) * 0.25;
    let taper = sin(((t - 0.03) / 0.25) * 180);
    darkPocket.push(flameEnvelope(t, 0.58 * taper));
  }
  washPoly(darkPocket, "#13296B", 195);

  // Luminous cyan-cobalt rim strokes around the translucent blue base
  for (let side of [-1, 1]) {
    let rimPts = [];
    let innerRimPts = [];
    for (let i = 0; i <= 24; i++) {
      let t = (i / 24) * 0.44;
      let taper = (t < 0.28) ? 1.0 : map(t, 0.28, 0.44, 1.0, 0.15);
      let p = flameEnvelope(t, side * 1.02 * taper);
      let pIn = flameEnvelope(t, side * 0.82 * taper);
      let press = sin((i / 24) * 180) * 0.95 + 0.15;
      rimPts.push([p[0], p[1], press]);
      innerRimPts.push([pIn[0], pIn[1], press]);
    }
    brush.set("soft_plume", "#1B68FF", 0.55);
    brush.spline(rimPts, 0.55);
    brush.set("cpencil", "#64E9FF", 1.15);
    brush.spline(rimPts, 0.55);
    brush.set("cpencil", "#A8F9FF", 0.75);
    brush.spline(innerRimPts, 0.55);
  }

  // Bottom arc of the blue flame cup wrapping under the match neck
  let cupArcPts = [];
  for (let i = -10; i <= 10; i++) {
    let u = i / 10;
    let p = flameEnvelope(0.01 + abs(u) * 0.08, u * 0.98);
    cupArcPts.push([p[0], p[1], 1.1 - abs(u) * 0.5]);
  }
  brush.set("cpencil", "#5CE1FF", 1.25);
  brush.spline(cupArcPts, 0.5);
  brush.set("2H", "#D4FCFF", 0.55);
  brush.spline(cupArcPts, 0.5);

  // --- C. Luminous Yellow-Orange-White Upper Flame Tongue ---
  // Transition zone from blue base (t = 0.22) up to the flickering tip (t = 1.0)
  function upperFlameLayer(tStart, tEnd, widthScale, col, alpha) {
    let pts = [];
    for (let i = 0; i <= 32; i++) {
      let u = i / 32;
      let t = lerp(tStart, tEnd, u);
      let pinch = (u < 0.18) ? sin((u / 0.18) * 90) : 1.0;
      pts.push(flameEnvelope(t, -widthScale * pinch));
    }
    for (let i = 32; i >= 0; i--) {
      let u = i / 32;
      let t = lerp(tStart, tEnd, u);
      let pinch = (u < 0.18) ? sin((u / 0.18) * 90) : 1.0;
      pts.push(flameEnvelope(t, widthScale * pinch));
    }
    return washPoly(pts, col, alpha);
  }

  // Layered thermal gradients from deep tangerine-amber to blinding incandescent white
  upperFlameLayer(0.18, 1.00, 0.96, "#FF5E00", 225);
  upperFlameLayer(0.20, 0.97, 0.84, "#FF8C00", 235);
  upperFlameLayer(0.22, 0.93, 0.72, "#FFB700", 245);
  upperFlameLayer(0.24, 0.88, 0.58, "#FFE135", 250);
  upperFlameLayer(0.26, 0.80, 0.44, "#FFF699", 252);
  upperFlameLayer(0.28, 0.70, 0.28, "#FFFFFF", 255);

  // Secondary flickering flame tongue licking off the right flank (around (770, 325) -> (776, 255))
  let rightLickPts = [
    [762, 375],
    [776, 342],
    [782, 298],
    [773, 254],
    [766, 295],
    [756, 338]
  ];
  washPoly(rightLickPts, "#FF7700", 220);
  let rightLickCore = [
    [764, 365],
    [773, 335],
    [776, 298],
    [772, 272],
    [766, 305],
    [759, 342]
  ];
  washPoly(rightLickCore, "#FFD629", 240);

  // Left micro-flicker wisp near the top of the vermilion disc
  let leftLickPts = [
    [694, 345],
    [684, 310],
    [687, 274],
    [695, 306],
    [701, 335]
  ];
  washPoly(leftLickPts, "#FF8800", 210);

  // Fine silky directional flame filaments in colored pencil & soft_plume
  for (let f = 0; f < 22; f++) {
    let sNorm = map(f, 0, 21, -0.82, 0.82);
    let fPts = [];
    let tMin = 0.20 + abs(sNorm) * 0.08;
    let tMax = 0.96 - abs(sNorm) * 0.18;
    for (let i = 0; i <= 18; i++) {
      let u = i / 18;
      let t = lerp(tMin, tMax, u);
      let pinch = (u < 0.2) ? sin((u / 0.2) * 90) : 1.0;
      let p = flameEnvelope(t, sNorm * pinch);
      fPts.push([p[0], p[1], sin(u * 180) * 0.9 + 0.2]);
    }
    let fCol = (abs(sNorm) < 0.3) ? "#FFFFFF" : (abs(sNorm) < 0.6 ? "#FFE94D" : "#FF8800");
    brush.set("cpencil", fCol, 0.75);
    brush.spline(fPts, 0.5);
  }

  // =========================================================================
  // 6. HYPERREAL SPLINTERED PINE MATCHSTICK (3D Square-Section Prism)
  // =========================================================================
  // The matchstick spans s = 0 (bottom cut end at (280, 1070)) to s = 720 (inside head).
  // Cross-section geometry:
  //   Top-left edge:   d = -15.5
  //   Central arris:   d = +1.5   (ridge between lit top-left face and shaded bottom-right face)
  //   Bottom-right:    d = +14.0
  //   End-grain face at s = 0..10 showing the raw 3D square cut end!

  const sStickEnd = 712;

  // Build slightly organic wood edge profiles with tiny splinter indentations
  let topEdge = [];
  let arrisEdge = [];
  let botEdge = [];

  const nSteps = 90;
  for (let i = 0; i <= nSteps; i++) {
    let u = i / nSteps;
    let s = u * sStickEnd;
    // Slight narrowing/char shrinkage right below the head (s > 630)
    let charPinch = (s > 630) ? map(s, 630, sStickEnd, 1.0, 0.82) : 1.0;
    let n1 = (noise(s * 0.025, 1.2) - 0.5) * 1.1;
    let n2 = (noise(s * 0.03, 5.4) - 0.5) * 0.9;
    let n3 = (noise(s * 0.025, 9.7) - 0.5) * 1.1;

    topEdge.push(mPt(s, (-15.5 + n1) * charPinch));
    arrisEdge.push(mPt(s, (1.5 + n2) * charPinch));
    botEdge.push(mPt(s, (14.0 + n3) * charPinch));
  }

  // --- A. Opaque Base Washes for the Two Long Wood Planes ---
  // Lit Top-Left Plane (from topEdge to arrisEdge)
  let litFacePts = topEdge.concat(arrisEdge.slice().reverse());
  washPoly(litFacePts, "#F2DFC1", 255);

  // Shaded Bottom-Right Plane (from arrisEdge to botEdge)
  let shadeFacePts = arrisEdge.concat(botEdge.slice().reverse());
  washPoly(shadeFacePts, "#C99F6B", 255);

  // 3D Cut End-Grain Face at the bottom base (s = -9..0)
  let endP1 = mPt(0, -15.5);
  let endP2 = mPt(0, 1.5);
  let endP3 = mPt(0, 14.0);
  let endP4 = mPt(-11, 11.5);
  let endP5 = mPt(-13, -2.0);
  let endP6 = mPt(-9, -16.5);
  let endGrainPts = [endP1, endP2, endP3, endP4, endP5, endP6];
  washPoly(endGrainPts, "#B3834C", 255);

  // --- B. Zonal Color & Pyrolysis Scorch Gradient along the Stick ---
  // Segment the stick from s = 540 to s = 712 to build a hyperreal transition:
  // raw pine -> warm amber -> toasted sienna -> charred umber -> carbon black
  const scorchBands = [
    { s0: 0,   s1: 550, colLit: "#EED6B1", colShade: "#BD905A", alpha: 110 },
    { s0: 530, s1: 605, colLit: "#E0AE6C", colShade: "#9C6934", alpha: 175 },
    { s0: 590, s1: 645, colLit: "#C27329", colShade: "#753E14", alpha: 215 },
    { s0: 632, s1: 675, colLit: "#78320D", colShade: "#421A07", alpha: 235 },
    { s0: 662, s1: 695, colLit: "#331509", colShade: "#1C0B05", alpha: 248 },
    { s0: 685, s1: 714, colLit: "#170F0C", colShade: "#0D0908", alpha: 255 }
  ];

  for (let b of scorchBands) {
    let pLit = [
      mPt(b.s0, -15.2),
      mPt(b.s1, -14.2),
      mPt(b.s1, 1.5),
      mPt(b.s0, 1.5)
    ];
    let pShade = [
      mPt(b.s0, 1.5),
      mPt(b.s1, 1.5),
      mPt(b.s1, 13.0),
      mPt(b.s0, 13.8)
    ];
    washPoly(pLit, b.colLit, b.alpha);
    washPoly(pShade, b.colShade, b.alpha);
  }

  // Subtle watercolor wood stain modulation on the unburnt pine shaft
  watercolorPoly(
    [mPt(40, -15), mPt(520, -15), mPt(520, 1.5), mPt(40, 1.5)],
    "#D9B382",
    42,
    0.2,
    0.5
  );
  watercolorPoly(
    [mPt(40, 1.5), mPt(520, 1.5), mPt(520, 13.8), mPt(40, 13.8)],
    "#9E703B",
    55,
    0.2,
    0.55
  );

  // --- C. Fine Longitudinal Pine Grain, Tracheid Pores & Growth Rings ---
  // Lit top-left face grain lines
  for (let g = 0; g < 34; g++) {
    let dBase = map(g, 0, 33, -14.8, 1.0);
    let gPts = [];
    let sStart = random(0, 35);
    let sEnd = random(580, 685);
    let steps = 28;
    for (let i = 0; i <= steps; i++) {
      let u = i / steps;
      let s = lerp(sStart, sEnd, u);
      let charPinch = (s > 630) ? map(s, 630, sStickEnd, 1.0, 0.82) : 1.0;
      let wave = sin(s * 0.035 + g * 0.7) * 0.65 + (noise(s * 0.02, g * 2.1) - 0.5) * 0.9;
      let d = constrain((dBase + wave) * charPinch, -15.2, 1.3);
      let p = mPt(s, d);
      gPts.push([p[0], p[1], 0.35 + 0.6 * sin(u * 180)]);
    }
    // Alternate between warm ochre cpencil and sharp 2H/HB graphite
    if (g % 5 === 0) {
      brush.set("cpencil", "#B88449", random(0.28, 0.48));
    } else if (g % 3 === 0) {
      brush.set("HB", "#9C713E", random(0.20, 0.36));
    } else {
      brush.set("2H", "#C9A16B", random(0.18, 0.32));
    }
    brush.spline(gPts, 0.45);
  }

  // Shaded bottom-right face grain lines (richer umber & dark graphite)
  for (let g = 0; g < 26; g++) {
    let dBase = map(g, 0, 25, 2.0, 13.4);
    let gPts = [];
    let sStart = random(0, 30);
    let sEnd = random(580, 685);
    let steps = 26;
    for (let i = 0; i <= steps; i++) {
      let u = i / steps;
      let s = lerp(sStart, sEnd, u);
      let charPinch = (s > 630) ? map(s, 630, sStickEnd, 1.0, 0.82) : 1.0;
      let wave = cos(s * 0.04 + g * 0.9) * 0.55 + (noise(s * 0.025, g * 3.3 + 20) - 0.5) * 0.8;
      let d = constrain((dBase + wave) * charPinch, 1.7, 13.6);
      let p = mPt(s, d);
      gPts.push([p[0], p[1], 0.4 + 0.55 * sin(u * 180)]);
    }
    if (g % 4 === 0) {
      brush.set("2B", "#5E3C1B", random(0.25, 0.42));
    } else {
      brush.set("HB", "#7A5229", random(0.22, 0.38));
    }
    brush.spline(gPts, 0.45);
  }

  // Microscopic wood pores / resin ducts along the pine faces
  for (let p = 0; p < 95; p++) {
    let s = random(8, 630);
    let d = random(-14.2, 12.8);
    let len = random(4, 14);
    let p1 = mPt(s, d);
    let p2 = mPt(s + len, d);
    let col = (d < 1.5) ? "#8F6332" : "#4F3114";
    brush.set("2H", col, random(0.18, 0.32));
    brush.line(p1[0], p1[1], p2[0], p2[1]);
  }

  // --- D. Central Arris Highlight & Crisp Structural Edges ---
  // The central ridge (d = 1.5) catches a razor-sharp pale cream highlight from the light
  // and turns golden-orange near the flame neck!
  for (let i = 0; i < nSteps - 4; i++) {
    let s0 = (i / nSteps) * sStickEnd;
    let p1 = arrisEdge[i];
    let p2 = arrisEdge[i + 1];
    let col = (s0 < 540) ? "#FFF7E6" : (s0 < 635 ? "#FFB85C" : "#FF6200");
    let wt = (s0 < 660) ? 0.55 : 0.35;
    brush.set("cpencil", col, wt);
    brush.line(p1[0], p1[1], p2[0], p2[1]);
  }

  // Dark core shadow line immediately below the central arris (d = +2.3)
  brush.set("HB", "#5C3B1C", 0.32);
  for (let i = 0; i < nSteps - 3; i += 2) {
    let s0 = (i / nSteps) * sStickEnd;
    let s1 = ((i + 2) / nSteps) * sStickEnd;
    let p1 = mPt(s0, 2.4);
    let p2 = mPt(s1, 2.4);
    brush.line(p1[0], p1[1], p2[0], p2[1]);
  }

  // Crisp graphite contour along top-left and bottom-right edges of the matchstick
  brush.set("HB", "#6B4B2A", 0.38);
  for (let i = 0; i < nSteps; i++) {
    let p1 = topEdge[i];
    let p2 = topEdge[min(i + 1, nSteps)];
    brush.line(p1[0], p1[1], p2[0], p2[1]);

    let b1 = botEdge[i];
    let b2 = botEdge[min(i + 1, nSteps)];
    brush.set("2B", "#3B2410", 0.42);
    brush.line(b1[0], b1[1], b2[0], b2[1]);
  }

  // --- E. Splintered Pine Base & Lifted Wood Fibers ---
  // End-grain texture at the cut bottom (s = -12..4)
  brush.set("2B", "#4A2E14", 0.35);
  for (let k = 0; k < 18; k++) {
    let d = map(k, 0, 17, -15, 13.5);
    let pA = mPt(random(-11, -5), d + random(-1, 1));
    let pB = mPt(random(2, 14), d);
    brush.line(pA[0], pA[1], pB[0], pB[1]);
  }

  // Sharp individual wood splinters peeling off the cut base and along the stick edges
  const splinters = [
    // Base splinters jutting out from s = 0
    { s0: 12, d0: -15.2, s1: -26, d1: -19.5, dMid: -17.0, col: "#EED5B0", shCol: "#593818", w: 2.2 },
    { s0: 8,  d0: -9.5,  s1: -34, d1: -11.8, dMid: -10.5, col: "#F5E2C4", shCol: "#63401D", w: 2.6 },
    { s0: 10, d0: 1.5,   s1: -28, d1: 2.8,   dMid: 2.0,   col: "#E6C495", shCol: "#4A2C11", w: 2.4 },
    { s0: 6,  d0: 8.5,   s1: -22, d1: 11.2,  dMid: 9.8,   col: "#C2945E", shCol: "#3B220C", w: 1.8 },
    { s0: 14, d0: 13.8,  s1: -19, d1: 17.5,  dMid: 15.2,  col: "#B5854D", shCol: "#2E1908", w: 1.9 },
    // Lifted splinters along the shaft (especially dramatic where stick crosses the black bar!)
    { s0: 145, d0: -15.2, s1: 192, d1: -21.5, dMid: -17.5, col: "#F7E6CA", shCol: "#5C3C1E", w: 2.1 },
    { s0: 255, d0: -15.0, s1: 298, d1: -20.8, dMid: -17.2, col: "#F7E6CA", shCol: "#0A0A0A", w: 2.3 },
    { s0: 270, d0: 13.8,  s1: 232, d1: 18.6,  dMid: 15.8,  col: "#D4A872", shCol: "#0A0A0A", w: 1.8 },
    { s0: 425, d0: -15.2, s1: 468, d1: -20.2, dMid: -17.0, col: "#F4DFBE", shCol: "#6B4926", w: 2.0 },
    { s0: 515, d0: 1.6,   s1: 552, d1: -2.8,  dMid: -0.5,  col: "#FFE8C2", shCol: "#5E3B18", w: 1.6 },
    { s0: 615, d0: -14.8, s1: 644, d1: -19.5, dMid: -16.8, col: "#D9822B", shCol: "#3D1806", w: 1.7 }
  ];

  for (let sp of splinters) {
    let pBase1 = mPt(sp.s0, sp.d0);
    let pBase2 = mPt(sp.s0, sp.d0 + (sp.d0 < 0 ? sp.w : -sp.w));
    let pMid = mPt((sp.s0 + sp.s1) * 0.5, sp.dMid);
    let pTip = mPt(sp.s1, sp.d1);

    // Tiny shadow under the lifted splinter
    brush.set("HB", sp.shCol, 0.35);
    let pShTip = mPt(sp.s1, sp.d0 + (sp.d1 - sp.d0) * 0.35);
    brush.line(pBase1[0], pBase1[1], pShTip[0], pShTip[1]);

    // Opaque wood splinter wedge
    washPoly([pBase1, pMid, pTip, pBase2], sp.col, 252);

    // Crisp needle-sharp edge & highlight on splinter
    brush.set("splinter_needle", sp.col, 0.85);
    brush.spline([[pBase1[0], pBase1[1], 0.9], [pMid[0], pMid[1], 0.6], [pTip[0], pTip[1], 0.1]], 0.35);
    brush.set("2H", sp.shCol, 0.26);
    brush.spline([[pBase2[0], pBase2[1], 0.8], [pMid[0], pMid[1], 0.5], [pTip[0], pTip[1], 0.1]], 0.35);
  }

  // Charred wood cracks & glowing ember fissures in the pyrolysis neck (s = 655..708)
  for (let c = 0; c < 14; c++) {
    let sA = random(650, 695);
    let sB = sA + random(8, 22);
    let d = random(-12.5, 11.5);
    let p1 = mPt(sA, d);
    let p2 = mPt(sB, d + random(-1.5, 1.5));
    brush.set("rotring", "#FF6D00", 0.38);
    brush.line(p1[0], p1[1], p2[0], p2[1]);
    if (c % 2 === 0) {
      brush.set("rotring", "#FFF099", 0.22);
      brush.line(p1[0], p1[1], lerp(p1[0], p2[0], 0.6), lerp(p1[1], p2[1], 0.6));
    }
  }

  // =========================================================================
  // 7. THE BUBBLING SULPHUR / POTASSIUM CHLORATE HEAD (Instant of Ignition)
  // =========================================================================
  // The match head wraps s = 702 to s = 784 (centered around s = 744, i.e., (723, 473) -> (772, 407)).
  // Lower-right side still shows the granular unburnt/melting sulfur-crimson chemical crust;
  // Upper-left and tip are erupting into swollen carbonized bubbles with incandescent magma fissures!

  const sHeadCenter = 744;
  const headLenHalf = 42; // spans s = 702..786
  const headWidHalf = 24; // spans d = -25..+23

  // Base bulbous match-head silhouette with erupting blisters on the upper-left side
  let headPts = [];
  const headN = 64;
  for (let i = 0; i < headN; i++) {
    let a = (i / headN) * 360;
    // Tear-drop distortion: tapered at neck (cos(a) < 0), bulbous at tip (cos(a) > 0)
    let sOff = cos(a) * headLenHalf * (cos(a) < 0 ? 1.08 : 0.95);
    let taper = map(cos(a), -1, 1, 0.68, 1.06);
    let dOff = sin(a) * headWidHalf * taper;

    // Erupting bubble protrusions on the igniting side (sin(a) < 0.25 and cos(a) > -0.4)
    let blister = 0;
    if (sin(a) < 0.35 && cos(a) > -0.55) {
      blister = pow(max(0, sin(a * 5 + 40)), 2) * 7.5
              + pow(max(0, cos(a * 7 - 20)), 2) * 5.0;
    } else {
      // Subtle granular roughness on unburnt side
      blister = (noise(cos(a) * 2 + 4, sin(a) * 2 + 4) - 0.5) * 2.5;
    }

    let radScale = 1 + blister / 28;
    headPts.push(mPt(sHeadCenter + sOff * radScale, dOff * radScale - 1.0));
  }

  // 1. Dark charred & crimson-sulfur base mass of the match head
  washPoly(headPts, "#26120E", 255);

  // 2. Unburnt / melting chemical crust on the lower-right side (d > -2, s = 705..775)
  let unburntPts = [];
  for (let i = 0; i <= 32; i++) {
    let a = map(i, 0, 32, -25, 175); // positive sin(a) -> bottom-right side
    let sOff = cos(a) * (headLenHalf * 0.92);
    let dOff = sin(a) * (headWidHalf * 0.94);
    unburntPts.push(mPt(sHeadCenter + sOff, dOff));
