// Hyperreal Overhead Tortoise Carapace in the Pardhan Gond Manner
// Built with p5.js v2 (WEBGL) and p5.brush

const CX = 600;
const CY = 636;
const RX = 374;
const RY = 442;

// Global light vector (upper-left directional sunlight + dome elevation)
const LIGHT = normalize3([-0.48, -0.52, 0.707]);
const HALF_VEC = normalize3([LIGHT[0], LIGHT[1], LIGHT[2] + 1.0]);

function normalize3(v) {
  let m = Math.hypot(v[0], v[1], v[2]) || 1;
  return [v[0] / m, v[1] / m, v[2] / m];
}

// Color ramps: each family maps 3D illumination [0..1] from deep umber-tinted shadow
// through soft pastel gouache midtones to luminous chalky highlights.
const COLOR_RAMPS = {
  umber: [
    [28, 16, 11],
    [54, 33, 22],
    [82, 52, 36],
    [114, 76, 54],
    [148, 104, 76]
  ],
  vermilion: [
    [76, 30, 22],
    [138, 56, 42],
    [206, 98, 76],
    [238, 138, 114],
    [252, 192, 174]
  ],
  turmeric: [
    [82, 56, 22],
    [148, 104, 38],
    [214, 164, 68],
    [244, 204, 108],
    [254, 236, 168]
  ],
  green: [
    [34, 52, 34],
    [66, 98, 64],
    [110, 158, 106],
    [152, 198, 146],
    [206, 236, 198]
  ],
  white: [
    [88, 74, 62],
    [146, 132, 114],
    [204, 194, 174],
    [238, 232, 216],
    [255, 252, 244]
  ],
  horn: [
    [62, 44, 28],
    [116, 88, 58],
    [174, 142, 102],
    [220, 196, 156],
    [250, 240, 218]
  ]
};

function sampleRamp(family, lightVal, warmthShift = 0) {
  let ramp = COLOR_RAMPS[family] || COLOR_RAMPS.umber;
  let t = constrain(lightVal + warmthShift, 0, 1) * (ramp.length - 1);
  let idx = Math.floor(t);
  let frac = t - idx;
  let c0 = ramp[Math.min(idx, ramp.length - 1)];
  let c1 = ramp[Math.min(idx + 1, ramp.length - 1)];
  let r = Math.round(c0[0] + (c1[0] - c0[0]) * frac);
  let g = Math.round(c0[1] + (c1[1] - c0[1]) * frac);
  let b = Math.round(c0[2] + (c1[2] - c0[2]) * frac);
  return (
    "#" +
    r.toString(16).padStart(2, "0") +
    g.toString(16).padStart(2, "0") +
    b.toString(16).padStart(2, "0")
  );
}

