function draw() {
  translate(-width / 2, -height / 2);
  brush.noField();

  // 1. Rich warm umber ground + devotional earth texture + ambient cast shadows
  drawUmberGround();

  // 2. Emerging anatomy beneath carapace rim: head, neck, 4 scaly limbs & claws, tail
  drawEmergingAnatomy();

  // 3. Build watertight anatomical carapace mesh (5 Vertebrals, 8 Costals, 24 Marginals)
  let scutes = buildCarapaceScutes();

  // 4. Carapace base dome & deep keratin suture foundation
  drawCarapaceFoundation(scutes);

  // 5. Render each scute: 3D bevels, concentric keratin growth ridges, and Gond patterns
  // Draw marginals first, then costals, then central vertebrals so the crown sits highest
  for (let s of scutes) {
    if (s.kind === "marginal") renderScute(s);
  }
  for (let s of scutes) {
    if (s.kind === "costal") renderScute(s);
  }
  for (let s of scutes) {
    if (s.kind === "vertebral") renderScute(s);
  }

  // 6. Final suture ambient occlusion & specular dome catchlights
  drawCarapaceFinishing(scutes);

  noLoop();
}

// ============================================================================
// SHAPE & SPLINE HELPERS
// ============================================================================

function drawShapePoly(pts, curvature = 0.18) {
  if (!pts || pts.length < 3) return;
  brush.beginShape(curvature);
  for (let i = 0; i < pts.length; i++) {
    brush.vertex(pts[i][0], pts[i][1]);
  }
  brush.endShape(true);
}

function safeLine(x1, y1, x2, y2) {
  if (Math.hypot(x2 - x1, y2 - y1) > 0.6) {
    brush.line(x1, y1, x2, y2);
  }
}

function safeSpline(pts, curvature = 0.4) {
  if (!pts || pts.length < 3) return;
  let clean = [pts[0]];
  for (let i = 1; i < pts.length; i++) {
    if (Math.hypot(pts[i][0] - clean[clean.length - 1][0], pts[i][1] - clean[clean.length - 1][1]) > 0.8) {
      clean.push(pts[i]);
    }
  }
  if (clean.length >= 3) {
    brush.spline(clean, curvature);
  } else if (clean.length === 2) {
    safeLine(clean[0][0], clean[0][1], clean[1][0], clean[1][1]);
  }
}

function makeEllipsePoly(cx, cy, rx, ry, rotDeg = 0, n = 36, wobble = 0) {
  let pts = [];
  let c = Math.cos((rotDeg * Math.PI) / 180);
  let s = Math.sin((rotDeg * Math.PI) / 180);
  for (let i = 0; i < n; i++) {
    let a = (i / n) * Math.PI * 2;
    let w = wobble > 0 ? 1 + (noise(cx * 0.01 + Math.cos(a), cy * 0.01 + Math.sin(a)) - 0.5) * wobble : 1;
    let lx = Math.cos(a) * rx * w;
    let ly = Math.sin(a) * ry * w;
    pts.push([cx + lx * c - ly * s, cy + lx * s + ly * c]);
  }
  return pts;
}

