function drawUmberGround() {
  background("#382318");

  // Layered warm earth washes
  brush.noStroke();
  brush.wash("#4A3021", 160);
  brush.rect(0, 0, width, height, "corner");

  // Warm clay halo around the tortoise
  brush.fillBleed(0.35, "out");
  brush.fillTexture(0.55, 0.25);
  brush.fill("#61402C", 95);
  drawShapePoly(makeEllipsePoly(590, 620, 540, 560, 0, 40, 0.08), 0.3);

  brush.fill("#744E36", 65);
  drawShapePoly(makeEllipsePoly(530, 540, 440, 470, -15, 36, 0.08), 0.3);

  // Darker vignette at canvas corners
  brush.noFill();
  brush.wash("#24150E", 95);
  const corners = [
    [[0, 0], [380, 0], [180, 180], [0, 380]],
    [[1200, 0], [1200, 380], [1020, 180], [820, 0]],
    [[0, 1200], [0, 820], [180, 1020], [380, 1200]],
    [[1200, 1200], [820, 1200], [1020, 1020], [1200, 820]]
  ];
  for (let c of corners) drawShapePoly(c, 0.1);
  brush.noWash();

  // Tactile woven earth grain and subtle devotional radial ground ripples
  brush.hatchStyle("2B", "#2A1810", 0.45);
  brush.hatch(14, 28, { rand: 0.12 });
  brush.noStroke();
  brush.rect(20, 20, 1160, 1160, "corner");
  brush.noHatch();

  // Subtle concentric devotional earth rings in raw umber around the outer ground
  for (let r = 490; r <= 575; r += 22) {
    let n = 90;
    for (let i = 0; i < n; i++) {
      let a1 = (i / n) * 360;
      let a2 = ((i + 0.55) / n) * 360;
      let rx = r * 0.92;
      let ry = r * 1.03;
      let x1 = CX + rx * cos(a1);
      let y1 = CY - 10 + ry * sin(a1);
      let x2 = CX + rx * cos(a2);
      let y2 = CY - 10 + ry * sin(a2);
      if (x1 > 25 && x1 < 1175 && y1 > 25 && y1 < 1175) {
        let col = i % 2 === 0 ? "#6D4B35" : "#4E3323";
        brush.set("gond_hair", col, 0.25);
        safeLine(x1, y1, x2, y2);
      }
    }
  }

  // Deep ambient cast shadow beneath the tortoise shell and limbs (shifted lower-right)
  brush.noStroke();
  for (let i = 0; i < 4; i++) {
    let expand = (3 - i) * 18;
    let sx = CX + 28 - i * 4;
    let sy = CY + 32 - i * 4;
    brush.wash("#190E09", 55 + i * 28);
    drawShapePoly(makeEllipsePoly(sx, sy, RX + 22 + expand, RY + 20 + expand, 4, 48, 0.03), 0.25);
  }

  // Cast shadows under head and four limbs
  const limbShadows = [
    [605, 132, 68, 88, -2],   // head shadow
    [195, 232, 95, 62, 32],   // left foreleg shadow
    [1025, 252, 95, 62, -30], // right foreleg shadow
    [225, 995, 88, 56, -34],  // left hindleg shadow
    [1000, 985, 88, 56, 34],  // right hindleg shadow
    [622, 1105, 28, 42, 18]   // tail shadow
  ];
  for (let ls of limbShadows) {
    brush.wash("#170C07", 115);
    drawShapePoly(makeEllipsePoly(ls[0] + 14, ls[1] + 16, ls[2], ls[3], ls[4], 28, 0.04), 0.25);
    brush.wash("#24140D", 75);
    drawShapePoly(makeEllipsePoly(ls[0] + 22, ls[1] + 24, ls[2] * 1.22, ls[3] * 1.22, ls[4], 28, 0.04), 0.25);
  }
  brush.noWash();
}

