function drawSmallGondScale(cx, cy, rx, ry, rotDeg, family, baseLight, rings = 3) {
  // Base scale wash
  let poly = makeEllipsePoly(cx, cy, rx, ry, rotDeg, 20, 0.06);
  brush.noStroke();
  brush.wash(sampleRamp("umber", baseLight * 0.55), 210);
  drawShapePoly(poly, 0.2);

  brush.wash(sampleRamp(family, baseLight * 0.85), 145);
  drawShapePoly(makeEllipsePoly(cx - rx * 0.12, cy - ry * 0.12, rx * 0.82, ry * 0.82, rotDeg, 18, 0.04), 0.2);
  brush.noWash();

  // Dark scale crevice outline
  brush.set("gond_hair", sampleRamp("umber", baseLight * 0.3), 0.34);
  safeSpline([...poly, poly[0]], 0.35);

  // Concentric Gond hairline rings + radial micro-dashes
  let c = cos(rotDeg);
  let s = sin(rotDeg);
  const ringFamilies = [family, "turmeric", "white", "vermilion"];

  for (let k = 1; k <= rings; k++) {
    let t = k / (rings + 0.8);
    let rkx = rx * (1 - t * 0.78);
    let rky = ry * (1 - t * 0.78);
    let fam = ringFamilies[(k - 1) % ringFamilies.length];

    // Split ring into lit upper-left half and shaded lower-right half
    let litPts = [];
    let shdPts = [];
    let steps = 18;
    for (let i = 0; i <= steps; i++) {
      let a = -180 + (i / steps) * 360;
      let lx = cos(a) * rkx;
      let ly = sin(a) * rky;
      let px = cx + lx * c - ly * s;
      let py = cy + lx * s + ly * c;
      if (a >= -165 && a <= 25) litPts.push([px, py]);
      if (a >= 15 || a <= -155) shdPts.push([px, py]);
    }
    brush.set("gond_hair", sampleRamp(fam, Math.min(1, baseLight + 0.22)), 0.26);
    safeSpline(litPts, 0.35);
    brush.set("gond_hair", sampleRamp(fam, Math.max(0.08, baseLight - 0.18)), 0.22);
    safeSpline(shdPts, 0.35);

    // Radial micro-dashes on outer band
    if (k === 1 && rx > 9) {
      let nDashes = Math.floor(constrain((rx + ry) * 0.75, 8, 22));
      for (let d = 0; d < nDashes; d++) {
        let a = (d / nDashes) * 360;
        let dirL = cos(a - 135) * 0.18;
        let r0x = rx * 0.9, r0y = ry * 0.9;
        let r1x = rx * 0.62, r1y = ry * 0.62;
        let x0 = cx + (cos(a) * r0x * c - sin(a) * r0y * s);
        let y0 = cy + (cos(a) * r0x * s + sin(a) * r0y * c);
        let x1 = cx + (cos(a) * r1x * c - sin(a) * r1y * s);
        let y1 = cy + (cos(a) * r1x * s + sin(a) * r1y * c);
        brush.set("gond_hair", sampleRamp(fam, constrain(baseLight + dirL, 0.1, 0.98)), 0.24);
        safeLine(x0, y0, x1, y1);
      }
    }
  }

  // Central seed dot highlight at scale crown
  brush.set("gond_dot", sampleRamp("white", Math.min(1, baseLight + 0.3)), 0.32);
  safeLine(cx - 1.5, cy - 1.5, cx + 1.0, cy + 1.0);
}

function drawClaw(bx, by, angleDeg, len, baseW, lightBias) {
  let rad = (angleDeg * Math.PI) / 180;
  let dirX = Math.cos(rad);
  let dirY = Math.sin(rad);
  let perpX = -dirY;
  let perpY = dirX;

  // Curve the claw gently downward/inward
  let curveSign = dirX < 0 ? -1 : 1;
  let curveAmt = len * 0.14 * curveSign;

  let leftEdge = [];
  let rightEdge = [];
  let centerLine = [];
  let steps = 10;

  for (let i = 0; i <= steps; i++) {
    let t = i / steps;
    let w = baseW * 0.5 * Math.pow(1 - t, 0.68);
    let bend = Math.sin(t * Math.PI) * curveAmt;
    let mx = bx + dirX * len * t + perpX * bend;
    let my = by + dirY * len * t + perpY * bend;
    centerLine.push([mx, my]);
    leftEdge.push([mx - perpX * w, my - perpY * w]);
    rightEdge.push([mx + perpX * w, my + perpY * w]);
  }

  let clawPoly = [...leftEdge, ...rightEdge.slice().reverse()];

  // Base shadow and keratin body
  brush.noStroke();
  brush.wash(sampleRamp("umber", 0.18), 235);
  drawShapePoly(clawPoly, 0.2);

  // Lit side of the claw
  let litHalf = [...leftEdge, ...centerLine.slice().reverse()];
  brush.wash(sampleRamp("horn", constrain(0.62 + lightBias, 0.3, 0.95)), 210);
  drawShapePoly(litHalf, 0.2);

  // Shaded side of the claw
  let shdHalf = [...centerLine, ...rightEdge.slice().reverse()];
  brush.wash(sampleRamp("horn", constrain(0.34 + lightBias, 0.15, 0.75)), 210);
  drawShapePoly(shdHalf, 0.2);
  brush.noWash();

  // Longitudinal keratin growth striations & Gond ring ticks at base
  for (let f = -0.35; f <= 0.35; f += 0.23) {
    let streak = [];
    for (let i = 0; i <= steps; i++) {
      let t = i / steps;
      let w = baseW * f * Math.pow(1 - t, 0.68);
      let bend = Math.sin(t * Math.PI) * curveAmt;
      streak.push([
        bx + dirX * len * t + perpX * (bend + w),
        by + dirY * len * t + perpY * (bend + w)
      ]);
    }
    let lVal = constrain(0.55 - f * 0.7 + lightBias, 0.15, 0.98);
    brush.set("gond_hair", sampleRamp("horn", lVal), 0.26);
    safeSpline(streak, 0.3);
  }

  // Transverse Gond growth arcs near the claw base collar
  for (let r = 0.12; r <= 0.42; r += 0.1) {
    let w = baseW * 0.46 * Math.pow(1 - r, 0.68);
    let bend = Math.sin(r * Math.PI) * curveAmt;
    let mx = bx + dirX * len * r + perpX * bend;
    let my = by + dirY * len * r + perpY * bend;
    brush.set("gond_hair", sampleRamp("umber", 0.22), 0.25);
    safeLine(mx - perpX * w, my - perpY * w, mx + perpX * w, my + perpY * w);
  }

  // Crisp ivory ridge highlight along dorsal crest
  brush.set("gond_hair", sampleRamp("white", constrain(0.85 + lightBias, 0.5, 1.0)), 0.3);
  safeSpline(centerLine.slice(1, steps), 0.35);

  // Dark outline around claw
  brush.set("gond_hair", "#1C100A", 0.36);
  safeSpline(leftEdge, 0.3);
  safeSpline(rightEdge, 0.3);
}

function drawLimb(cfg) {
  let { side, isFront, baseX, baseY, tipX, tipY, widthBase, widthTip, numClaws, clawAngles } = cfg;
  let dx = tipX - baseX;
  let dy = tipY - baseY;
  let limbLen = Math.hypot(dx, dy);
  let ux = dx / limbLen;
  let uy = dy / limbLen;
  let px = -uy;
  let py = ux;

  // Illumination based on global light (left limbs are brighter than right limbs)
  let limbLight = side < 0 ? (isFront ? 0.68 : 0.52) : (isFront ? 0.48 : 0.34);

  // Build limb contour
  let outline = [];
  let steps = 16;
  for (let i = 0; i <= steps; i++) {
    let t = i / steps;
    let w = lerp(widthBase * 0.5, widthTip * 0.5, t) * (1 + 0.15 * Math.sin(t * Math.PI));
    outline.push([baseX + dx * t + px * w, baseY + dy * t + py * w]);
  }
  for (let i = steps; i >= 0; i--) {
    let t = i / steps;
    let w = lerp(widthBase * 0.5, widthTip * 0.5, t) * (1 + 0.12 * Math.sin(t * Math.PI));
    outline.push([baseX + dx * t - px * w, baseY + dy * t - py * w]);
  }

  // Claws drawn first at distal foot edge so foot scales overlap their bases
  for (let c = 0; c < numClaws; c++) {
    let frac = numClaws > 1 ? c / (numClaws - 1) - 0.5 : 0;
    let cbx = tipX + px * frac * widthTip * 0.84 - ux * (Math.abs(frac) * 14);
    let cby = tipY + py * frac * widthTip * 0.84 - uy * (Math.abs(frac) * 14);
    let cLen = (isFront ? 42 : 34) * (1 - Math.abs(frac) * 0.22);
    let cW = (isFront ? 15 : 13.5) * (1 - Math.abs(frac) * 0.15);
    drawClaw(cbx, cby, clawAngles[c], cLen, cW, limbLight - 0.45);
  }

  // Leathery limb base wash
  brush.noStroke();
  brush.wash(sampleRamp("umber", limbLight * 0.45), 240);
  drawShapePoly(outline, 0.25);
  brush.noWash();

  // Overlapping osteoderm keratin scales from distal wrist back toward carapace
  const scaleFamilies = ["turmeric", "vermilion", "green", "white"];
  let rows = isFront ? 6 : 5;
  for (let r = rows - 1; r >= 0; r--) {
    let t = (r + 0.35) / (rows + 0.2);
    // Darker under carapace rim overhang (t near 0)
    let rowShadow = t < 0.35 ? map(t, 0, 0.35, 0.35, 1.0) : 1.0;
    let rowW = lerp(widthBase * 0.46, widthTip * 0.44, t);
    let cols = r % 2 === 0 ? 4 : 3;
    for (let c = 0; c < cols; c++) {
      let cf = cols > 1 ? (c / (cols - 1) - 0.5) * 1.65 : 0;
      let scx = baseX + dx * t + px * cf * rowW * 0.55;
      let scy = baseY + dy * t + py * cf * rowW * 0.55;
      let srx = (isFront ? 15 : 13) * (1 - 0.12 * Math.abs(cf));
      let sry = (isFront ? 11 : 10) * (1 - 0.1 * Math.abs(cf));
      let rot = atan2(dy, dx) + cf * 18;
      let localL = constrain((limbLight - cf * side * 0.12) * rowShadow, 0.12, 0.92);
      let fam = scaleFamilies[(r + c) % scaleFamilies.length];
      drawSmallGondScale(scx, scy, srx, sry, rot, fam, localL, 3);
    }
  }
}

function drawTail() {
  let tx0 = 602, ty0 = 1068;
  let tx1 = 624, ty1 = 1134;
  let steps = 7;
  for (let i = steps; i >= 0; i--) {
    let t = i / steps;
    let x = lerp(tx0, tx1, t) + Math.sin(t * Math.PI) * 5;
    let y = lerp(ty0, ty1, t);
    let r = lerp(18, 5, t);
    let lVal = lerp(0.18, 0.42, t);
    drawSmallGondScale(x, y, r, r * 0.75, 18, i % 2 === 0 ? "turmeric" : "vermilion", lVal, 2);
  }
}

