}

// ============================================================================
// 3. WATER-TIGHT CARAPACE ANATOMICAL TESSELLATION
// ============================================================================

function shellPt(u, v) {
  let r2 = u * u + v * v;
  // Slight posterior broadening + subtle anterior cervical indentation
  let postFlare = 1.0 + 0.058 * Math.sin((v * Math.PI) / 2) - 0.025 * v * v;
  let nuchalIndent = v < -0.75 ? -0.022 * Math.exp(-Math.pow(u / 0.22, 2)) * Math.pow((-v - 0.75) / 0.25, 2) : 0;
  let x = CX + u * RX * postFlare;
  let y = CY + (v - nuchalIndent) * RY;

  // Smooth biological asymmetry so shared vertices stay 100% locked together
  let wx = (noise(u * 1.35 + 12.3, v * 1.35 + 45.6) - 0.5) * 13 * Math.min(1, r2 + 0.2);
  let wy = (noise(u * 1.35 + 78.9, v * 1.35 + 23.4) - 0.5) * 13 * Math.min(1, r2 + 0.2);
  return [x + wx, y + wy];
}

function rimUv(rNorm, thetaDeg, scallop = 0) {
  let r = rNorm + scallop;
  return [r * cos(thetaDeg), r * sin(thetaDeg)];
}

function arcRimPts(rNorm, degStart, degEnd, steps = 8, isOuter = false, marginalIndex = 0) {
  let pts = [];
  for (let i = 0; i <= steps; i++) {
    let t = i / steps;
    let deg = lerp(degStart, degEnd, t);
    let scallop = 0;
    if (isOuter) {
      // Gentle scalloped flare on each marginal plate
      let flareStrength = 0.012 + 0.01 * Math.pow(Math.sin((deg * Math.PI) / 180), 2);
      scallop = Math.sin(t * Math.PI) * flareStrength;
    }
    let uv = rimUv(rNorm, deg, scallop);
    pts.push(shellPt(uv[0], uv[1]));
  }
  return pts;
}

function interpUvPts(uvA, uvB, steps = 5) {
  let pts = [];
  for (let i = 0; i <= steps; i++) {
    let t = i / steps;
    let u = lerp(uvA[0], uvB[0], t);
    let v = lerp(uvA[1], uvB[1], t);
    pts.push(shellPt(u, v));
  }
  return pts;
}

function concatEdges(edgeArrays) {
  let out = [];
  for (let e of edgeArrays) {
    for (let i = 0; i < e.length - 1; i++) {
      out.push(e[i]);
    }
  }
  return out;
}

function buildCarapaceScutes() {
  const R_IN = 0.858;
  const R_OUT = 1.0;

  // Exact shared interior seam vertices in (u, v)
  const P0_L = rimUv(R_IN, -111), P0_R = rimUv(R_IN, -69);
  const P1_L = [-0.255, -0.525], M1 = [0.0, -0.515], P1_R = [0.255, -0.525];
  const P2_L = [-0.395, -0.305], P2_R = [0.395, -0.305];
  const P3_L = [-0.285, -0.115], M2 = [0.0, -0.105], P3_R = [0.285, -0.115];
  const P4_L = [-0.415, 0.095], P4_R = [0.415, 0.095];
  const P5_L = [-0.275, 0.285], M3 = [0.0, 0.295], P5_R = [0.275, 0.285];
  const P6_L = [-0.365, 0.465], P6_R = [0.365, 0.465];
  const P7_L = [-0.205, 0.605], M4 = [0.0, 0.615], P7_R = [0.205, 0.605];
  const P8_L = rimUv(R_IN, 114), P8_R = rimUv(R_IN, 66);

  // Costal-to-Marginal junction points on R_IN
  const CM1_R = rimUv(R_IN, -30), CM1_L = rimUv(R_IN, -150);
  const CM2_R = rimUv(R_IN, 6), CM2_L = rimUv(R_IN, -186);
  const CM3_R = rimUv(R_IN, 39), CM3_L = rimUv(R_IN, 141);

  let scutes = [];

  // ---- 5 VERTEBRAL SCUTES (V1..V5) ----
  scutes.push(createScuteObj("V1", "vertebral", 0, concatEdges([
    arcRimPts(R_IN, -111, -69, 8, false),
    interpUvPts(P0_R, P1_R, 5),
    interpUvPts(P1_R, M1, 4),
    interpUvPts(M1, P1_L, 4),
    interpUvPts(P1_L, P0_L, 5)
  ]), [0, 0.04], 11, ["white", "turmeric", "vermilion", "green"]));

  scutes.push(createScuteObj("V2", "vertebral", 1, concatEdges([
    interpUvPts(P1_L, M1, 4),
    interpUvPts(M1, P1_R, 4),
    interpUvPts(P1_R, P2_R, 5),
    interpUvPts(P2_R, P3_R, 5),
    interpUvPts(P3_R, M2, 4),
    interpUvPts(M2, P3_L, 4),
    interpUvPts(P3_L, P2_L, 5),
    interpUvPts(P2_L, P1_L, 5)
  ]), [0, 0.02], 12, ["turmeric", "vermilion", "white", "green"]));

  scutes.push(createScuteObj("V3", "vertebral", 2, concatEdges([
    interpUvPts(P3_L, M2, 4),
    interpUvPts(M2, P3_R, 4),
    interpUvPts(P3_R, P4_R, 5),
    interpUvPts(P4_R, P5_R, 5),
    interpUvPts(P5_R, M3, 4),
    interpUvPts(M3, P5_L, 4),
    interpUvPts(P5_L, P4_L, 5),
    interpUvPts(P4_L, P3_L, 5)
  ]), [0, 0.0], 13, ["white", "vermilion", "turmeric", "green"]));

  scutes.push(createScuteObj("V4", "vertebral", 3, concatEdges([
    interpUvPts(P5_L, M3, 4),
    interpUvPts(M3, P5_R, 4),
    interpUvPts(P5_R, P6_R, 5),
    interpUvPts(P6_R, P7_R, 5),
    interpUvPts(P7_R, M4, 4),
    interpUvPts(M4, P7_L, 4),
    interpUvPts(P7_L, P6_L, 5),
    interpUvPts(P6_L, P5_L, 5)
  ]), [0, -0.02], 11, ["turmeric", "green", "vermilion", "white"]));

  scutes.push(createScuteObj("V5", "vertebral", 4, concatEdges([
    interpUvPts(P7_L, M4, 4),
    interpUvPts(M4, P7_R, 4),
    interpUvPts(P7_R, P8_R, 5),
    arcRimPts(R_IN, 66, 114, 8, false),
    interpUvPts(P8_L, P7_L, 5)
  ]), [0, -0.05], 10, ["white", "vermilion", "turmeric", "green"]));

  // ---- 4 RIGHT COSTAL SCUTES (C1R..C4R) ----
  scutes.push(createScuteObj("C1R", "costal", 0, concatEdges([
    arcRimPts(R_IN, -69, -30, 7, false),
    interpUvPts(CM1_R, P2_R, 6),
    interpUvPts(P2_R, P1_R, 5),
    interpUvPts(P1_R, P0_R, 5)
  ]), [-0.08, 0.04], 11, ["green", "turmeric", "vermilion", "white"]));

  scutes.push(createScuteObj("C2R", "costal", 1, concatEdges([
    interpUvPts(P2_R, CM1_R, 6),
    arcRimPts(R_IN, -30, 6, 7, false),
    interpUvPts(CM2_R, P4_R, 6),
    interpUvPts(P4_R, P3_R, 5),
    interpUvPts(P3_R, P2_R, 5)
  ]), [-0.10, 0.0], 12, ["vermilion", "white", "green", "turmeric"]));

  scutes.push(createScuteObj("C3R", "costal", 2, concatEdges([
    interpUvPts(P4_R, CM2_R, 6),
    arcRimPts(R_IN, 6, 39, 7, false),
    interpUvPts(CM3_R, P6_R, 6),
    interpUvPts(P6_R, P5_R, 5),
    interpUvPts(P5_R, P4_R, 5)
  ]), [-0.10, -0.02], 11, ["turmeric", "green", "white", "vermilion"]));

  scutes.push(createScuteObj("C4R", "costal", 3, concatEdges([
    interpUvPts(P6_R, CM3_R, 6),
    arcRimPts(R_IN, 39, 66, 6, false),
    interpUvPts(P8_R, P7_R, 5),
    interpUvPts(P7_R, P6_R, 5)
  ]), [-0.08, -0.04], 10, ["green", "vermilion", "turmeric", "white"]));

  // ---- 4 LEFT COSTAL SCUTES (C1L..C4L) ----
  scutes.push(createScuteObj("C1L", "costal", 4, concatEdges([
    interpUvPts(P0_L, P1_L, 5),
    interpUvPts(P1_L, P2_L, 5),
    interpUvPts(P2_L, CM1_L, 6),
    arcRimPts(R_IN, -150, -111, 7, false)
  ]), [0.08, 0.04], 11, ["green", "turmeric", "vermilion", "white"]));

  scutes.push(createScuteObj("C2L", "costal", 5, concatEdges([
    interpUvPts(P2_L, P3_L, 5),
    interpUvPts(P3_L, P4_L, 5),
    interpUvPts(P4_L, CM2_L, 6),
    arcRimPts(R_IN, -186, -150, 7, false),
    interpUvPts(CM1_L, P2_L, 6)
  ]), [0.10, 0.0], 12, ["vermilion", "white", "green", "turmeric"]));

  scutes.push(createScuteObj("C3L", "costal", 6, concatEdges([
    interpUvPts(P4_L, P5_L, 5),
    interpUvPts(P5_L, P6_L, 5),
    interpUvPts(P6_L, CM3_L, 6),
    arcRimPts(R_IN, 141, 174, 7, false),
    interpUvPts(CM2_L, P4_L, 6)
  ]), [0.10, -0.02], 11, ["turmeric", "green", "white", "vermilion"]));

  scutes.push(createScuteObj("C4L", "costal", 7, concatEdges([
    interpUvPts(P6_L, P7_L, 5),
    interpUvPts(P7_L, P8_L, 5),
    arcRimPts(R_IN, 114, 141, 6, false),
    interpUvPts(CM3_L, P6_L, 6)
  ]), [0.08, -0.04], 10, ["green", "vermilion", "turmeric", "white"]));

  // ---- 24 MARGINAL SCUTES AROUND PERIMETER ----
  let mAngles = [-95.5, -84.5]; // Nuchal
  for (let i = 1; i <= 11; i++) mAngles.push(-84.5 + (i / 11) * (83.5 - -84.5)); // 11 Right
  mAngles.push(96.5); // Supracaudal
  for (let i = 1; i <= 11; i++) mAngles.push(96.5 + (i / 11) * (264.5 - 96.5)); // 11 Left

  const mCycles = [
    ["turmeric", "vermilion", "white", "green"],
    ["white", "green", "turmeric", "vermilion"],
    ["vermilion", "turmeric", "green", "white"]
  ];

  for (let m = 0; m < 24; m++) {
    let a0 = mAngles[m];
    let a1 = mAngles[m + 1];
    let midA = (a0 + a1) * 0.5;
    let mPoly = concatEdges([
      arcRimPts(R_IN, a0, a1, 5, false, m),
      interpUvPts(rimUv(R_IN, a1), rimUv(R_OUT, a1), 4),
      arcRimPts(R_OUT, a1, a0, 5, true, m),
      interpUvPts(rimUv(R_OUT, a0), rimUv(R_IN, a0), 4)
    ]);
    // Shift marginal areola slightly toward the outer-posterior corner
    let bias = [-cos(midA) * 0.06, -sin(midA) * 0.06];
    scutes.push(createScuteObj("M" + m, "marginal", m, mPoly, bias, 5, mCycles[m % 3]));
  }

  return scutes;
}

// Construct a scute object with curve-shortening concentric growth rings
function createScuteObj(id, kind, idx, poly, areolaBias, numRings, paletteCycle) {
  // Compute centroid & bounding scale
  let cx = 0, cy = 0;
  for (let p of poly) {
    cx += p[0];
    cy += p[1];
  }
  cx /= poly.length;
  cy /= poly.length;

  let maxR = 0;
  for (let p of poly) {
    maxR = Math.max(maxR, Math.hypot(p[0] - cx, p[1] - cy));
  }

  // Areola center (slightly offset from centroid)
  let ax = cx + areolaBias[0] * maxR;
  let ay = cy + areolaBias[1] * maxR;

  // Sample radial distances from (ax, ay) to the polygon boundary at N_DIRS angles
  const N_DIRS = 64;
  let rOuter = new Array(N_DIRS);

  for (let i = 0; i < N_DIRS; i++) {
    let theta = (i / N_DIRS) * Math.PI * 2;
    let dx = Math.cos(theta);
    let dy = Math.sin(theta);
    let bestT = maxR * 0.7;

    for (let j = 0; j < poly.length; j++) {
      let p1 = poly[j];
      let p2 = poly[(j + 1) % poly.length];
      let ex = p2[0] - p1[0];
      let ey = p2[1] - p1[1];
      let det = dx * ey - dy * ex;
      if (Math.abs(det) > 1e-6) {
        let rx = p1[0] - ax;
        let ry = p1[1] - ay;
        let tRay = (rx * ey - ry * ex) / det;
        let uSeg = (rx * dy - ry * dx) / det;
        if (tRay > 0 && uSeg >= -0.001 && uSeg <= 1.001) {
          bestT = tRay;
          break;
        }
      }
    }
    rOuter[i] = bestT;
  }

  // Detect radial corner rays (polygon vertices) so we can subtly emphasize corner ridges
  let rSmoothRef = smoothCircular(rOuter, 10);
  let cornerWeight = new Array(N_DIRS);
  for (let i = 0; i < N_DIRS; i++) {
    cornerWeight[i] = constrain((rOuter[i] / (rSmoothRef[i] || 1) - 0.96) * 6.0, 0, 1);
  }

  // Inset slightly from raw suture line and apply 2 passes of corner rounding for Ring 0
  let sutureShrink = kind === "marginal" ? 0.935 : 0.962;
  let r0 = smoothCircular(rOuter, 2).map((v) => v * sutureShrink);

  // Generate strictly nested concentric growth rings via iterative curve-shortening flow
  let rings = [];
  let rCurr = r0.slice();
  let endScale = kind === "marginal" ? 0.24 : 0.19;
  let stepRatio = Math.pow(endScale, 1 / numRings);

  for (let k = 0; k <= numRings; k++) {
    let sNorm = k / numRings;
    let ringPts = [];
    for (let i = 0; i < N_DIRS; i++) {
      let theta = (i / N_DIRS) * Math.PI * 2;
      ringPts.push([
        ax + rCurr[i] * Math.cos(theta),
        ay + rCurr[i] * Math.sin(theta)
      ]);
    }
    rings.push({
      k,
      sNorm,
      radii: rCurr.slice(),
      pts: ringPts
    });

    // Advance inward by smoothing corners and contracting radially
    let smoothed = smoothCircular(rCurr, kind === "marginal" ? 2 : 3);
    let rNext = new Array(N_DIRS);
    for (let i = 0; i < N_DIRS; i++) {
      let blend = lerp(rCurr[i], smoothed[i], 0.65);
      rNext[i] = Math.min(rCurr[i] * 0.935, blend * stepRatio);
    }
    rCurr = rNext;
  }

  return {
    id,
    kind,
    idx,
    poly,
    cx,
    cy,
    ax,
    ay,
    maxR,
    numRings,
    rings,
    cornerWeight,
    paletteCycle
  };
}

function smoothCircular(arr, passes = 1) {
  let curr = arr.slice();
  let n = curr.length;
  for (let p = 0; p < passes; p++) {
    let next = new Array(n);
    for (let i = 0; i < n; i++) {
      let prev = curr[(i - 1 + n) % n];
      let nextVal = curr[(i + 1) % n];
      next[i] = 0.25 * prev + 0.5 * curr[i] + 0.25 * nextVal;
    }
    curr = next;
  }
  return curr;
}

// ============================================================================
// 4. 3D VOLUMETRIC LIGHTING MODEL (GLOBAL DOME + SCUTE PYRAMID + GROWTH RIDGE)
// ============================================================================

function compute3DLight(x, y, scute, sNorm = 0.5, ridgeSlope = 0.0) {
  // 1. Global carapace dome gradient
  let u = (x - CX) / RX;
  let v = (y - CY) / RY;
  let r2 = u * u + v * v;
  let domeSteepness = 0.64 + 0.44 * r2;
  let gx = u * domeSteepness;
  let gy = v * domeSteepness;

  // Marginal rim flare catchlight at outer flange
  if (scute && scute.kind === "marginal" && sNorm < 0.35) {
    gx *= 0.82;
    gy *= 0.82;
  }

  // 2. Local scute pyramidal dome gradient relative to areola center (ax, ay)
  let sx = 0, sy = 0;
  let distA = 1;
  if (scute) {
    let dx = x - scute.ax;
    let dy = y - scute.ay;
    distA = Math.hypot(dx, dy) || 1;
    let ndx = dx / (scute.maxR * 0.78);
    let ndy = dy / (scute.maxR * 0.78);

    // Scutes have a pronounced pyramidal bevel, steeper near sutures & growth rings
    let pyramidStrength = scute.kind === "vertebral" ? 0.54 : scute.kind === "costal" ? 0.48 : 0.38;
    if (sNorm < 0.12) pyramidStrength *= 1.45; // steep bevel into suture sulcus
    sx = ndx * pyramidStrength;
    sy = ndy * pyramidStrength;

    // 3. Concentric keratin growth ridge undulation
    let rx = (dx / distA) * ridgeSlope * 0.32;
    let ry = (dy / distA) * ridgeSlope * 0.32;
    sx += rx;
    sy += ry;
  }

  // Total surface normal
  let nx = -(gx * 0.72 + sx * 0.62);
  let ny = -(gy * 0.72 + sy * 0.62);
  let nzSq = Math.max(0.06, 1.0 - Math.min(0.94, nx * nx + ny * ny));
  let nz = Math.sqrt(nzSq);
  let nNorm = normalize3([nx, ny, nz]);

  // Diffuse Lambertian + warm sky ambient + keratin specular sheen
  let ndotl = Math.max(0, nNorm[0] * LIGHT[0] + nNorm[1] * LIGHT[1] + nNorm[2] * LIGHT[2]);
  let ndoth = Math.max(0, nNorm[0] * HALF_VEC[0] + nNorm[1] * HALF_VEC[1] + nNorm[2] * HALF_VEC[2]);
  let spec = Math.pow(ndoth, 13) * 0.36;

  // Soft reflected bounce light from the warm earth on the shaded lower-right rim
  let bounce = Math.max(0, u * 0.5 + v * 0.5) * r2 * 0.12;

  // Suture groove ambient occlusion
  let ao = sNorm < 0.06 ? map(sNorm, 0, 0.06, 0.42, 1.0) : 1.0;

  let val = (0.11 + 0.78 * ndotl + spec + bounce) * ao;
  return constrain(val, 0.03, 1.0);
}

// ============================================================================
// 5. CARAPACE FOUNDATION & SUTURE GROOVES
// ============================================================================

function drawCarapaceFoundation(scutes) {
  // Outer carapace silhouette built from outer marginal arcs
  let outerHull = arcRimPts(1.005, -90, 270, 96, true, 0);

  // Deep espresso-umber keratin shell foundation (forms the dark sutures between all scutes)
  brush.noStroke();
  brush.wash("#1A0E09", 250);
  drawShapePoly(outerHull, 0.2);

  // Broad 3D dome under-wash across the carapace
  brush.wash("#352015", 160);
  drawShapePoly(arcRimPts(0.95, -90, 270, 64, false, 0), 0.25);

  // Warm illuminated upper-left dome under-wash
  brush.fillBleed(0.28, "in");
  brush.fillTexture(0.45, 0.2);
  brush.fill("#68432C", 85);
  drawShapePoly(makeEllipsePoly(CX - 75, CY - 85, RX * 0.68, RY * 0.68, -25, 36, 0.04), 0.3);
  brush.noFill();
  brush.noWash();

  // Individual scute 3D tonal base washes
  for (let s of scutes) {
    let baseL = compute3DLight(s.ax, s.ay, s, 0.5, 0);
    // Outer scute body wash (slightly inset from raw polygon so dark suture groove shows)
    brush.noStroke();
    brush.wash(sampleRamp("umber", baseL * 0.72), 215);
    drawShapePoly(s.rings[0].pts, 0.2);

    // Mid-dome warm undertone
    let midIdx = Math.floor(s.numRings * 0.45);
    let midL = compute3DLight(s.ax - s.maxR * 0.12, s.ay - s.maxR * 0.12, s, 0.5, 0.3);
    brush.wash(sampleRamp("umber", midL * 0.92), 155);
    drawShapePoly(s.rings[midIdx].pts, 0.25);

    // Crown warmth at areola
    let crownIdx = Math.floor(s.numRings * 0.82);
    let crownL = compute3DLight(s.ax - s.maxR * 0.08, s.ay - s.maxR * 0.08, s, 0.85, 0.5);
    brush.wash(sampleRamp(s.paletteCycle[0], crownL * 0.65), 95);
    drawShapePoly(s.rings[crownIdx].pts, 0.3);
  }
  brush.noWash();
}

// ============================================================================
// 6. SCUTE RENDERER: CONCENTRIC GROWTH RIDGES + GOND RHYTHMIC PATTERNS
// ============================================================================

function renderScute(scute) {
  const N_DIRS = scute.rings[0].pts.length; // 64
  const numRings = scute.numRings;

  // A. Deep suture groove outline & lit bevel lip on the outermost ring
  drawSutureBevel(scute);

  // B. Concentric bands from outer suture (k = 0) inward to areola (k = numRings - 1)
  for (let k = 0; k < numRings; k++) {
    let ringOut = scute.rings[k];
    let ringIn = scute.rings[k + 1];
    let sMid = (ringOut.sNorm + ringIn.sNorm) * 0.5;
    let fam = scute.paletteCycle[k % scute.paletteCycle.length];
    let nextFam = scute.paletteCycle[(k + 1) % scute.paletteCycle.length];

    // 1. Physical 3D growth-ridge under-shading (soft bevel highlight & groove shadow)
    drawGrowthRidgeRelief(scute, ringOut, ringIn, fam);

    // 2. Crisp Gond hairline contour ring ("fingerprint ridge") split into 3D-lit sectors
    drawSectorContourRing(scute, ringOut, fam, k === 0 ? 0.34 : 0.27);

    // 3. Dense rhythmic Gond pattern filling the band between ringOut and ringIn
    drawGondBandFill(scute, k, ringOut, ringIn, sMid, fam, nextFam);
  }

  // C. Innermost areola contour & sacred embryonic crown stipple
  drawScuteAreola(scute);
}

function drawSutureBevel(scute) {
  let outerPts = scute.rings[0].pts;
  let n = outerPts.length;
  let closed = [...outerPts, outerPts[0], outerPts[1]];

  // Deep espresso sulcus groove
  brush.set("gond_hair", "#160B06", scute.kind === "marginal" ? 0.42 : 0.52);
  safeSpline(closed, 0.3);

  // Warm rim highlight where the scute's outer lip faces the upper-left light
  let SECTORS = 8;
  let ptsPerSec = n / SECTORS;
  for (let sec = 0; sec < SECTORS; sec++) {
    let i0 = Math.floor(sec * ptsPerSec);
    let i1 = Math.floor((sec + 1) * ptsPerSec) + 1;
    let sub = [];
    for (let i = i0; i <= i1; i++) sub.push(outerPts[i % n]);
    let midPt = sub[Math.floor(sub.length / 2)];
    let lVal = compute3DLight(midPt[0], midPt[1], scute, 0.03, 0.85);
    if (lVal > 0.48) {
      brush.set("gond_hair", sampleRamp("turmeric", lVal), 0.25);
      safeSpline(sub, 0.35);
    }
  }
}

function drawGrowthRidgeRelief(scute, ringOut, ringIn, fam) {
  // Subtle physical ridge modeling every 2nd ring on main scutes
  if (scute.kind === "marginal" && ringOut.k % 2 === 1) return;

  let n = ringOut.pts.length;
  let SECTORS = 8;
  let step = n / SECTORS;

  for (let sec = 0; sec < SECTORS; sec++) {
    let i0 = Math.floor(sec * step);
    let i1 = Math.floor((sec + 1) * step) + 1;
    let crestPts = [];
    let groovePts = [];
    for (let i = i0; i <= i1; i++) {
      let idx = i % n;
      let pOut = ringOut.pts[idx];
      let pIn = ringIn.pts[idx];
      crestPts.push([lerp(pOut[0], pIn[0], 0.28), lerp(pOut[1], pIn[1], 0.28)]);
      groovePts.push([lerp(pOut[0], pIn[0], 0.88), lerp(pOut[1], pIn[1], 0.88)]);
    }
    let mid = crestPts[Math.floor(crestPts.length / 2)];
    let lCrest = compute3DLight(mid[0], mid[1], scute, ringOut.sNorm, 0.95);
    let lGroove = compute3DLight(mid[0], mid[1], scute, ringIn.sNorm, -0.95);

    // Soft dry-pastel ridge highlight on lit sectors
    if (lCrest > 0.42) {
      brush.set("gond_shade", sampleRamp(fam, lCrest), 0.45 + 0.35 * lCrest);
      safeSpline(crestPts, 0.35);
    }
    // Soft umber crease shadow in the growth-ring trough
    brush.set("gond_shade", sampleRamp("umber", lGroove * 0.55), 0.38);
    safeSpline(groovePts, 0.35);
  }
}

function drawSectorContourRing(scute, ring, fam, baseWeight) {
  let pts = ring.pts;
  let n = pts.length;
  let SECTORS = scute.kind === "marginal" ? 6 : 8;
  let step = n / SECTORS;

  for (let sec = 0; sec < SECTORS; sec++) {
    let i0 = Math.floor(sec * step);
    let i1 = Math.floor((sec + 1) * step) + 1;
    let sub = [];
    let grooveSub = [];

    for (let i = i0; i <= i1; i++) {
      let idx = i % n;
      let p = pts[idx];
      sub.push(p);
      // Slight inward offset for the dark keratin groove shadow line
      grooveSub.push([lerp(p[0], scute.ax, 0.018), lerp(p[1], scute.ay, 0.018)]);
    }

    let mid = sub[Math.floor(sub.length / 2)];
    let lRidge = compute3DLight(mid[0], mid[1], scute, ring.sNorm, 0.85);
    let lGroove = compute3DLight(mid[0], mid[1], scute, ring.sNorm, -0.85);

    // Dark hairline groove directly adjacent to the ridge
    brush.set("gond_hair", sampleRamp("umber", lGroove * 0.42), baseWeight * 0.78);
    safeSpline(grooveSub, 0.35);

    // Luminous 3D-shaded pastel hairline contour along the ridge crest
    let w = baseWeight * (0.78 + 0.42 * lRidge);
    brush.set("gond_hair", sampleRamp(fam, lRidge), w);
    safeSpline(sub, 0.35);
  }
}

function drawGondBandFill(scute, k, ringOut, ringIn, sMid, fam, nextFam) {
  let ptsOut = ringOut.pts;
  let ptsIn = ringIn.pts;
  let n = ptsOut.length;

  // Estimate circumference of this band to space Gond marks rhythmically
  let circum = 0;
  for (let i = 0; i < n; i++) {
    let p0 = ptsOut[i];
    let p1 = ptsOut[(i + 1) % n];
    circum += Math.hypot(p1[0] - p0[0], p1[1] - p0[1]);
  }

  let spacingPx = scute.kind === "marginal" ? 6.2 : 5.2;
  let numMarks = Math.max(12, Math.floor(circum / spacingPx));

  // Pattern vocabulary cycles across bands so form and Gond ornament become one:
  // 0: Radial comb dashes ("Digna")
  // 1: Sesame seed-dots ("Chana / Bindu") + inner fingerprint hairline
  // 2: Oblique herringbone / feather dashes ("Lehariya")
  // 3: Alternating long-short radial dashes + corner ray accents
  let mode = (k + scute.idx) % 4;

  // For mode 1 or 3 on large scutes, add an extra mid-band fingerprint hairline contour
  if ((mode === 1 || mode === 3) && circum > 110) {
    let midRingPts = [];
    for (let i = 0; i < n; i++) {
      midRingPts.push([
        lerp(ptsOut[i][0], ptsIn[i][0], 0.52),
        lerp(ptsOut[i][1], ptsIn[i][1], 0.52)
      ]);
    }
    drawSectorContourRing(scute, { pts: midRingPts, sNorm: sMid }, nextFam, 0.21);
  }

  for (let m = 0; m < numMarks; m++) {
    let u = (m / numMarks) * n;
    let i0 = Math.floor(u) % n;
    let i1 = (i0 + 1) % n;
    let frac = u - Math.floor(u);

    let ox = lerp(ptsOut[i0][0], ptsOut[i1][0], frac);
    let oy = lerp(ptsOut[i0][1], ptsOut[i1][1], frac);
    let ix = lerp(ptsIn[i0][0], ptsIn[i1][0], frac);
    let iy = lerp(ptsIn[i0][1], ptsIn[i1][1], frac);

    // Tangent vector along the contour ring
    let tx = ptsOut[i1][0] - ptsOut[i0][0];
    let ty = ptsOut[i1][1] - ptsOut[i0][1];
    let tLen = Math.hypot(tx, ty) || 1;
    tx /= tLen;
    ty /= tLen;

    let bandW = Math.hypot(ix - ox, iy - oy);
    if (bandW < 1.4) continue;

    // Corner ray boost: polygon vertex rays catch extra light like tortoise radial flutes
    let cornerBoost = scute.cornerWeight[i0] * 0.16;
    let mx = (ox + ix) * 0.5;
    let my = (oy + iy) * 0.5;
    let lVal = constrain(compute3DLight(mx, my, scute, sMid, 0.35) + cornerBoost, 0.04, 1.0);

    // Choose color: corner rays occasionally gleam with white/turmeric
    let markFam = cornerBoost > 0.09 && m % 2 === 0 ? "white" : fam;

    if (mode === 0) {
      // Rhythm 0: Crisp radial Gond dashes bridging across the growth band
      let x0 = lerp(ox, ix, 0.16);
      let y0 = lerp(oy, iy, 0.16);
      let x1 = lerp(ox, ix, 0.84);
      let y1 = lerp(oy, iy, 0.84);
      brush.set("gond_hair", sampleRamp(markFam, lVal), 0.24 + 0.14 * lVal);
      safeLine(x0, y0, x1, y1);
    } else if (mode === 1) {
      // Rhythm 1: Plump sesame seed-dots nestled along the band
      let dotFam = m % 3 === 0 ? nextFam : markFam;
      let x0 = lerp(ox, ix, 0.26);
      let y0 = lerp(oy, iy, 0.26);
      let x1 = lerp(ox, ix, 0.72);
      let y1 = lerp(oy, iy, 0.72);
      brush.set("gond_dot", sampleRamp(dotFam, lVal), 0.27 + 0.14 * lVal);
      safeLine(x0, y0, x1, y1);
    } else if (mode === 2) {
      // Rhythm 2: Oblique feather / chevron dashes leaning along the contour
      let slant = (k % 2 === 0 ? 1 : -1) * Math.min(3.5, bandW * 0.42);
      let x0 = lerp(ox, ix, 0.18) - tx * slant * 0.5;
      let y0 = lerp(oy, iy, 0.18) - ty * slant * 0.5;
      let x1 = lerp(ox, ix, 0.84) + tx * slant * 0.5;
      let y1 = lerp(oy, iy, 0.84) + ty * slant * 0.5;
      brush.set("gond_hair", sampleRamp(markFam, lVal), 0.23 + 0.13 * lVal);
      safeLine(x0, y0, x1, y1);
    } else {
      // Rhythm 3: Alternating radial dash + sacred white/turmeric seed tick
      let isEven = m % 2 === 0;
      let x0 = lerp(ox, ix, 0.15);
      let y0 = lerp(oy, iy, 0.15);
      let x1 = lerp(ox, ix, isEven ? 0.86 : 0.52);
      let y1 = lerp(oy, iy, isEven ? 0.86 : 0.52);
      let useFam = isEven ? markFam : nextFam;
      brush.set(isEven ? "gond_hair" : "gond_dot", sampleRamp(useFam, lVal), 0.24 + 0.13 * lVal);
      safeLine(x0, y0, x1, y1);
    }
  }
}

function drawScuteAreola(scute) {
  let innerRing = scute.rings[scute.numRings];
  let fam = scute.paletteCycle[0];

  // Crisp contour around the central areola shield
  drawSectorContourRing(scute, innerRing, "white", 0.28);

  // Concentric stippled seed-dots and radial micro-ticks inside the rough embryonic areola
  let subRings = scute.kind === "marginal" ? 2 : 3;
  const areolaFams = ["turmeric", "vermilion", "white", "green"];

  for (let r = 1; r <= subRings; r++) {
    let frac = r / (subRings + 0.6);
    let n = innerRing.pts.length;
    let step = scute.kind === "marginal" ? 4 : 3;

    for (let i = 0; i < n; i += step) {
      let p = innerRing.pts[i];
      let x0 = lerp(p[0], scute.ax, frac * 0.72);
      let y0 = lerp(p[1], scute.ay, frac * 0.72);
      let x1 = lerp(p[0], scute.ax, Math.min(0.96, frac * 0.72 + 0.22));
      let y1 = lerp(p[1], scute.ay, Math.min(0.96, frac * 0.72 + 0.22));

      let lVal = compute3DLight(x0, y0, scute, 0.82 + frac * 0.15, 0.65);
      let dotFam = areolaFams[(r + i) % areolaFams.length];
      brush.set("gond_dot", sampleRamp(dotFam, lVal), 0.26 + 0.15 * lVal);
      safeLine(x0, y0, x1, y1);
    }
  }

  // Sacred central bindu cluster & specular dome highlight on upper-left of areola
  let hx = scute.ax - scute.maxR * 0.045;
  let hy = scute.ay - scute.maxR * 0.045;
  let apexL = compute3DLight(hx, hy, scute, 0.95, 1.0);
  brush.set("gond_dot", sampleRamp("white", Math.min(1, apexL + 0.18)), 0.36);
  safeLine(hx - 1.5, hy - 1.5, hx + 1.5, hy + 1.5);
  brush.set("gond_dot", sampleRamp(fam, apexL), 0.32);
  safeLine(scute.ax - 1.2, scute.ay + 1.2, scute.ax + 1.5, scute.ay - 1.0);
}

// ============================================================================
// 7. FINISHING PASS: SUTURE DEPTH & SPECULAR DOME CATCHLIGHTS
// ============================================================================

function drawCarapaceFinishing(scutes) {
  // Reinforce deep keratin sutures between plates & luminous ridge catchlights on upper-left dome
  for (let s of scutes) {
    if (s.kind === "marginal") continue;

    // Emphasize the lit upper-left radial ridge rays where polygon corners travel to the areola
    let n = s.rings[0].pts.length;
    for (let i = 0; i < n; i++) {
      if (s.cornerWeight[i] > 0.38) {
        let pMid = s.rings[Math.floor(s.numRings * 0.5)].pts[i];
        let lVal = compute3DLight(pMid[0], pMid[1], s, 0.5, 0.9);
        if (lVal > 0.62) {
          for (let k = 1; k < s.numRings - 1; k += 2) {
            let pA = s.rings[k].pts[i];
            let pB = s.rings[k + 1].pts[i];
            brush.set("gond_dot", sampleRamp("white", Math.min(1, lVal + 0.15)), 0.26);
            safeLine(
              lerp(pA[0], pB[0], 0.25),
              lerp(pA[1], pB[1], 0.25),
              lerp(pA[0], pB[0], 0.72),
              lerp(pA[1], pB[1], 0.72)
            );
          }
        }
      }
    }
  }
}

