function draw() {
  translate(-width / 2, -height / 2);
  background("#f6f2e8");

  // -------------------------------------------------------------------------
  // 1. SUNLIT WHITEWASHED PLASTER WALL (Bright Late-Morning Light from Top-Left)
  // -------------------------------------------------------------------------
  drawWhitewashedWall();

  // -------------------------------------------------------------------------
  // 2. KALOCSA-STYLE FOLK MOTIF PAINTED ON THE WALL (Vivid Marker + Satin Hatch)
  // -------------------------------------------------------------------------
  const kalocsaLayout = buildKalocsaLayout();
  drawKalocsaWallPainting(kalocsaLayout);

  // Subtle lime-wash wall aging over the painted motif so it lives IN the wall
  drawWallLimeOverglaze();

  // -------------------------------------------------------------------------
  // 3. PEPPER CLUSTER GEOMETRY & SOFT REAL CAST SHADOWS ON THE WALL
  // -------------------------------------------------------------------------
  const pods = buildPepperCluster();
  drawWallCastShadows(pods);

  // -------------------------------------------------------------------------
  // 4. FORGED IRON NAIL & UPPER HEMP TWINE
  // -------------------------------------------------------------------------
  drawIronNailAndTwineBack(596, 86, 598, 960);

  // -------------------------------------------------------------------------
  // 5. HYPERREAL DRYING PAPRIKA PEPPERS (Back-to-Front Layering)
  // -------------------------------------------------------------------------
  for (let i = 0; i < pods.length; i++) {
    const pod = pods[i];
    if (pod.layer === 0) {
      drawHyperrealPepper(pod);
    }
  }

  // Intertwined middle hemp twine strand passing between back and front pods
  drawTwineMidStrand(596, 130, 598, 860);

  for (let i = 0; i < pods.length; i++) {
    const pod = pods[i];
    if (pod.layer === 1) {
      drawHyperrealPepper(pod);
    }
  }

  // Foreground hero pods (including the prominent split pods showing seeds)
  for (let i = 0; i < pods.length; i++) {
    const pod = pods[i];
    if (pod.layer === 2) {
      drawHyperrealPepper(pod);
    }
  }

  // Top knot loops & stray hemp fibers over the upper stems
  drawTwineTopKnot(596, 86);

  noLoop();
}

// =============================================================================
// LAYER 1: WHITEWASHED PLASTER WALL
// =============================================================================
function drawWhitewashedWall() {
  brush.noStroke();
  brush.noHatch();
  brush.noMass();

  // Subtle architectural lime-wash tonal modulation (bright top-left, slightly cooler bottom-right)
  const washes = [
    { x: 260, y: 220, w: 620, h: 520, col: "#fcfaf4", op: 32 },
    { x: 920, y: 880, w: 680, h: 640, col: "#e7e2d5", op: 26 },
    { x: 880, y: 300, w: 540, h: 480, col: "#ede9dd", op: 22 },
    { x: 300, y: 920, w: 580, h: 500, col: "#eae5d9", op: 24 },
    { x: 600, y: 600, w: 960, h: 960, col: "#f4efe2", op: 18 }
  ];

  brush.fillBleed(0.45, "out");
  brush.fillTexture(0.55, 0.25);
  for (let w of washes) {
    brush.fill(w.col, w.op);
    brush.rect(w.x, w.y, w.w, w.h, "center");
  }
  brush.noFill();

  // Sweeping plaster trowel marks & lime brush striations
  for (let i = 0; i < 160; i++) {
    let x = random(20, 1180);
    let y = random(20, 1180);
    let len = random(70, 260);
    let ang = random(-18, 22) + (noise(x * 0.003, y * 0.003) - 0.5) * 35;
    let col = random(["#ebe5d8", "#e4decb", "#fcfbf7", "#f0eadc", "#dfd9c8"]);
    brush.set("charcoal", col, random(0.4, 1.3));
    let x2 = x + cos(ang) * len;
    let y2 = y + sin(ang) * len;
    let xm = (x + x2) * 0.5 + random(-14, 14);
    let ym = (y + y2) * 0.5 + random(-14, 14);
    brush.spline([[x, y, 0.2], [xm, ym, 0.7], [x2, y2, 0.2]], 0.4);
  }

  // Fine mineral grain & tiny plaster pits
  for (let i = 0; i < 110; i++) {
    let x = random(30, 1170);
    let y = random(30, 1170);
    brush.set("2H", random(["#d6cfc0", "#ffffff", "#e3ddd0"]), random(0.3, 0.7));
    brush.line(x, y, x + random(-35, 35), y + random(-12, 12));
  }
}

