function drawKalocsaLeaf(x, y, ang, len, w, pal) {
  push();
  translate(x, y);
  rotate(ang);

  // Upper half of leaf (darker leaf green with angled satin-stitch hatching)
  brush.noStroke();
  brush.wash(pal.greenDark, 225);
  brush.hatchStyle("satinMarker", pal.greenLeaf, 0.85);
  brush.hatch(3.2, 38, { rand: 0.02 });
  brush.beginShape(0.35);
  brush.vertex(0, 0);
  brush.vertex(len * 0.28, -w * 0.82);
  brush.vertex(len * 0.68, -w * 0.72);
  brush.vertex(len, 0);
  brush.vertex(len * 0.5, 0);
  brush.endShape(true);

  // Lower half of leaf (bright yellow-green with opposing satin-stitch hatching)
  brush.wash(pal.greenBright, 225);
  brush.hatchStyle("satinMarker", pal.greenLeaf, 0.85);
  brush.hatch(3.2, -38, { rand: 0.02 });
