function evalPodSpine(pod, t) {
  let mt = 1 - t;
  let x = mt * mt * pod.x0 + 2 * mt * t * pod.x1 + t * t * pod.x2;
  let y = mt * mt * pod.y0 + 2 * mt * t * pod.y1 + t * t * pod.y2;

  // Add subtle organic shrinkage wave along spine
  let wave = sin(t * 540 + pod.seed * 17) * (3.5 * t * (1 - t * 0.5));
  let dx = 2 * mt * (pod.x1 - pod.x0) + 2 * t * (pod.x2 - pod.x1);
  let dy = 2 * mt * (pod.y1 - pod.y0) + 2 * t * (pod.y2 - pod.y1);
  let len = sqrt(dx * dx + dy * dy) || 1;
  let tx = dx / len;
  let ty = dy / len;
  let nx = -ty;
  let ny = tx;

  return {
    x: x + nx * wave,
    y: y + ny * wave,
    tx: tx,
    ty: ty,
    nx: nx,
    ny: ny
  };
}

function evalPodWidth(pod, t, sideSign) {
  // Organic paprika profile: rounded shoulder, undulating pinched body, pointed tip
  let shoulder = t < 0.12 ? sin((t / 0.12) * 90) : 1.0;
  let taper = pow(max(0, 1 - t), 0.72);
  let baseW = lerp(pod.w0, pod.wMid, sin(min(1, t * 1.6) * 90)) * shoulder * taper;

  // Shrinkage buckles along the pod contour
  let ph = pod.seed * 31 + (sideSign > 0 ? 110 : 0);
  let buckle = 1.0
    + 0.13 * sin(t * 620 + ph)
    + 0.08 * cos(t * 1080 + ph * 1.7)
    - 0.09 * sin(t * 320 + ph * 0.5);

  return max(1.8, baseW * buckle);
}

function drawWallCastShadows(pods) {
  brush.noStroke();
  brush.noHatch();
  brush.noMass();

  // 1. Soft outer penumbra cast on the whitewashed wall & Kalocsa painting (shifted +42, +50)
  brush.fillBleed(0.38, "out");
  brush.fillTexture(0.45, 0.2);

  for (let pod of pods) {
    let offX = pod.layer === 0 ? 30 : pod.layer === 1 ? 42 : 52;
    let offY = pod.layer === 0 ? 36 : pod.layer === 1 ? 50 : 62;

    // Cool luminous late-morning shadow wash
    brush.fill("#848fa6", 44);
    drawPodSilhouetteShape(pod, offX, offY, 1.08);

    // Warm translucent ruby subsurface glow inside the cast shadow of red paprika skin
    brush.fill("#b5635c", 24);
    drawPodSilhouetteShape(pod, offX + 5, offY + 5, 0.92);
  }

  // 2. Darker umbra / contact shadow closer to the wall-touching pods (+22, +26)
  brush.fillBleed(0.22, "out");
  for (let pod of pods) {
    let offX = pod.layer === 0 ? 18 : pod.layer === 1 ? 26 : 34;
    let offY = pod.layer === 0 ? 22 : pod.layer === 1 ? 32 : 40;
    brush.fill("#4d5569", 52);
    drawPodSilhouetteShape(pod, offX, offY, 0.88);
  }

  // Shadow of the hanging twine and iron nail
  brush.fill("#565e73", 65);
  brush.rect(624, 340, 22, 480, "center");
  brush.circle(618, 108, 18, 0.2);

  brush.noFill();
}

function drawPodSilhouetteShape(pod, dx, dy, widthScale) {
  let steps = 16;
  brush.beginShape(0.35);
  for (let i = 0; i <= steps; i++) {
    let t = i / steps;
    let sp = evalPodSpine(pod, t);
    let w = evalPodWidth(pod, t, -1) * widthScale;
    brush.vertex(sp.x + dx - sp.nx * w, sp.y + dy - sp.ny * w);
  }
  for (let i = steps; i >= 0; i--) {
    let t = i / steps;
    let sp = evalPodSpine(pod, t);
    let w = evalPodWidth(pod, t, 1) * widthScale;
    brush.vertex(sp.x + dx + sp.nx * w, sp.y + dy + sp.ny * w);
  }
  brush.endShape(true);
}

