function drawIronNailAndTwineBack(xTop, yTop, xBot, yBot) {
  // Small plaster hole & crack around the forged nail
  brush.set("pen", "#5c5549", 0.8);
  brush.line(xTop, yTop, xTop - 18, yTop - 12);
  brush.line(xTop, yTop, xTop + 14, yTop + 16);

  // Twine main column running down the spine of the cluster
  for (let strand = -1; strand <= 1; strand++) {
    let pts = [];
    for (let y = yTop; y <= yBot; y += 28) {
      let twist = sin((y - yTop) * 4.5 + strand * 120) * 4.5;
      pts.push([xTop + twist, y, 1.0]);
    }
    brush.set("satinMarker", strand === -1 ? "#c7ae83" : strand === 0 ? "#9e8156" : "#6e5436", 1.8);
    brush.spline(pts, 0.45);
  }

  // Diagonal hemp ply twists
  for (let y = yTop + 6; y < yBot; y += 9) {
    let x = xTop + sin((y - yTop) * 4.5) * 2.5;
    brush.set("pen", "#523d24", 0.75);
    brush.line(x - 4.5, y - 3, x + 4.5, y + 3);
    brush.set("cpencil", "#e6d6b5", 0.7);
    brush.line(x - 3.5, y - 1, x + 2.5, y + 3);
  }
}

function drawTwineMidStrand(xTop, yTop, xBot, yBot) {
  for (let y = yTop; y < yBot; y += 14) {
    let x = xTop + sin(y * 3.2) * 3.5;
    brush.set("cpencil", "#8c6f47", 1.1);
    brush.line(x - 4, y - 5, x + 4, y + 5);
    brush.set("pen", "#dfd0b0", 0.65);
