  brush.arc(nx, ny, 9, 20, 190);
  brush.set("lacquerGlint", "#d8e0eb", 0.9);
  brush.arc(nx - 2, ny - 2, 9, 200, 330);

  // Hemp loop & knot wrapped around the nail
  const loopPts = [
    [[nx - 8, ny + 4, 0.9], [nx - 18, ny - 18, 1.0], [nx, ny - 28, 1.0], [nx + 18, ny - 16, 1.0], [nx + 8, ny + 6, 0.9]],
