  // Frayed sisal fibers sticking out at the knot
  for (let i = 0; i < 18; i++) {
    let a = random(-160, 40);
    let r1 = random(6, 14);
    let r2 = r1 + random(14, 34);
    brush.set("pen", random(["#cbb48c", "#8f724a", "#ede1c7"]), 0.45);
    brush.line(nx + cos(a) * r1, ny + 14 + sin(a) * r1, nx + cos(a) * r2, ny + 14 + sin(a) * r2);
  }
}

// =============================================================================
// LAYER 5: HYPERREAL DRYING PAPRIKA PEPPERS
// =============================================================================
function drawHyperrealPepper(pod) {
  randomSeed(pod.seed * 997);

  // 1. Contact shadow under this pod onto underlying pods
  if (pod.layer > 0) {
    brush.noStroke();
    brush.fillBleed(0.18, "out");
    brush.fill("#240305", 85);
    drawPodSilhouetteShape(pod, 10, 14, 0.96);
    brush.noFill();
  }

  // Color palette per pod based on drying maturity & light exposure
  const pal = getPodPalette(pod.hue);

  // 2. Opaque base wash silhouette
  brush.noStroke();
  brush.wash(pal.coreShadow, 252);
  drawPodSilhouetteShape(pod, 0, 0, 1.0);
  brush.noWash();

  // 3. Sculptural 3D Lobe & Cylindrical Shading Bands (Sun from Top-Left: s < 0 is sunlit, s > 0 is shadow)
  const bands = [
    { s0: -0.96, s1: -0.68, col: pal.midRed, op: 235 },
    { s0: -0.75, s1: -0.18, col: pal.sunScarlet, op: 245 },
    { s0: -0.52, s1: -0.22, col: pal.hotVermilion, op: 220 },
    { s0: -0.22, s1: 0.28, col: pal.lacquerRed, op: 235 },
    { s0: 0.22, s1: 0.72, col: pal.deepCarmine, op: 240 },
    { s0: 0.48, s1: 0.84, col: pal.oxblood, op: 245 },
    { s0: 0.78, s1: 0.98, col: pal.reflectedWall, op: 210 } // Warm limestone bounce light on shadow rim!
  ];

  let steps = 22;
  brush.noStroke();
  for (let b of bands) {
    brush.wash(b.col, b.op);
    brush.beginShape(0.32);
    for (let i = 0; i <= steps; i++) {
      let t = i / steps;
      let pt = evalPodSurfacePoint(pod, t, b.s0);
      brush.vertex(pt.x, pt.y);
    }
    for (let i = steps; i >= 0; i--) {
      let t = i / steps;
      let pt = evalPodSurfacePoint(pod, t, b.s1);
      brush.vertex(pt.x, pt.y);
    }
    brush.endShape(true);
  }
  brush.noWash();

  // 4. Longitudinal Shrinkage Wrinkles, Valleys & Swollen Ridges
  const numRidges = 7;
  for (let r = 0; r < numRidges; r++) {
    let sBase = map(r, 0, numRidges - 1, -0.82, 0.82);

    // Draw the sunken wrinkle valley
    let valleyPts = [];
    let ridgeSunPts = [];
    let ridgeGlintPts = [];

    for (let i = 1; i < steps; i++) {
      let t = i / steps;
      // Wrinkle wave pinches at shoulder and tip,buckles in mid-body
      let wrinkleWave = 0.09 * sin(t * 780 + r * 85 + pod.seed * 19)
                      + 0.05 * cos(t * 1320 - r * 50);
      let sVal = constrain(sBase + wrinkleWave, -0.94, 0.94);

      let pVal = evalPodSurfacePoint(pod, t, sVal);
      let pressure = sin(t * 180) * (0.65 + 0.55 * abs(sin(t * 900 + r * 40)));
      valleyPts.push([pVal.x, pVal.y, pressure]);

      // Adjacent raised ridge crest on sunward side of valley
      let sCrest = constrain(sVal - 0.09, -0.96, 0.92);
      let pCrest = evalPodSurfacePoint(pod, t, sCrest);
      ridgeSunPts.push([pCrest.x, pCrest.y, pressure * 1.1]);

      if (sCrest > -0.78 && sCrest < 0.25 && i >= 2 && i <= steps - 2) {
        ridgeGlintPts.push([pCrest.x, pCrest.y, pressure]);
      }
    }

    // Sunken dark crease
    brush.set("satinMarker", sBase < 0 ? pal.deepCarmine : pal.oxblood, 0.95);
    brush.spline(valleyPts, 0.45);
    brush.set("pen", "#210103", 0.65);
    brush.spline(valleyPts, 0.45);

    // Swollen ridge flank catching light
    let ridgeCol = sBase < -0.1 ? pal.hotVermilion : sBase < 0.35 ? pal.sunScarlet : pal.midRed;
    brush.set("satinMarker", ridgeCol, 1.15);
    brush.spline(ridgeSunPts, 0.45);

    // Broken lacquer specular ribbon along sunlit ridges
    if (ridgeGlintPts.length > 4) {
      // Split into broken segments so highlights skip across knuckles of the wrinkled skin
      for (let k = 0; k < ridgeGlintPts.length - 3; k += 3) {
        let seg = ridgeGlintPts.slice(k, k + 4);
        if (seg.length >= 3) {
          brush.set("cpencil", "#ff9e88", 1.15);
          brush.spline(seg, 0.4);
          if (sBase > -0.68 && sBase < 0.05) {
            brush.set("lacquerGlint", "#fff6f0", 0.85);
            brush.spline(seg, 0.4);
          }
        }
      }
    }
  }

  // 5. Transverse & Diagonal Dehydration Crinkles (Buckled Skin Facets)
  const numBuckles = 26;
  for (let b = 0; b < numBuckles; b++) {
    let t = random(0.08, 0.9);
    let sCenter = random(-0.78, 0.75);
    let span = random(0.16, 0.34);
    let tTilt = random(-0.045, 0.045);

    let p1 = evalPodSurfacePoint(pod, constrain(t - tTilt, 0.03, 0.96), constrain(sCenter - span, -0.95, 0.95));
    let pMid = evalPodSurfacePoint(pod, constrain(t + abs(tTilt) * 0.7, 0.03, 0.96), sCenter);
    let p2 = evalPodSurfacePoint(pod, constrain(t + tTilt, 0.03, 0.96), constrain(sCenter + span, -0.95, 0.95));

    // Dark V-shaped dehydration pinch
    brush.set("pen", sCenter < 0 ? pal.oxblood : "#1c0102", random(0.55, 0.95));
    brush.spline([[p1.x, p1.y, 0.3], [pMid.x, pMid.y, 1.1], [p2.x, p2.y, 0.3]], 0.45);

    // Sunlit lower lip of the transverse wrinkle
    let pLip1 = evalPodSurfacePoint(pod, constrain(t - tTilt + 0.014, 0.03, 0.97), constrain(sCenter - span * 0.85, -0.95, 0.95));
    let pLipM = evalPodSurfacePoint(pod, constrain(t + abs(tTilt) * 0.7 + 0.016, 0.03, 0.97), sCenter);
    let pLip2 = evalPodSurfacePoint(pod, constrain(t + tTilt + 0.014, 0.03, 0.97), constrain(sCenter + span * 0.85, -0.95, 0.95));

    if (sCenter < 0.25) {
      brush.set("cpencil", sCenter < -0.15 ? "#ff7e66" : pal.sunScarlet, 0.85);
      brush.spline([[pLip1.x, pLip1.y, 0.2], [pLipM.x, pLipM.y, 1.0], [pLip2.x, pLip2.y, 0.2]], 0.45);

      // Sharp white-pink lacquer glint on knuckle crest
      if (sCenter > -0.65 && sCenter < 0.08 && random() < 0.7) {
        brush.set("lacquerGlint", "#ffffff", random(0.55, 0.95));
        brush.line(pLipM.x - 3, pLipM.y - 1, pLipM.x + 3, pLipM.y + 2);
      }
    }
  }

  // 6. Crisp Razor-Sharp Lacquer Specular Highlights & Cool Window Reflection Sheen
  for (let i = 0; i < 18; i++) {
    let t1 = random(0.09, 0.82);
    let t2 = constrain(t1 + random(0.04, 0.11), 0.1, 0.9);
    let s = random(-0.58, -0.12);
    let pa = evalPodSurfacePoint(pod, t1, s);
    let pm = evalPodSurfacePoint(pod, (t1 + t2) * 0.5, s + random(-0.04, 0.04));
    let pb = evalPodSurfacePoint(pod, t2, s);

    // Cool sky sheen on glossy cuticle
    brush.set("cpencil", "#dce9fa", 0.95);
    brush.spline([[pa.x, pa.y, 0.3], [pm.x, pm.y, 1.1], [pb.x, pb.y, 0.3]], 0.4);

    // Pure white specular core
    brush.set("lacquerGlint", "#ffffff", random(0.65, 1.05));
    brush.spline([[pa.x, pa.y, 0.2], [pm.x, pm.y, 1.2], [pb.x, pb.y, 0.2]], 0.4);
  }

  // 7. DUSTY SHOULDERS (Mineral Bloom, Pollen & Chalk Dust in Upper Crevices)
  drawDustyShoulders(pod);

  // 8. SPLIT SHOWING SEEDS (on Hero Split Pods!)
  if (pod.split) {
    drawPodSplitAndSeeds(pod);
  }

  // 9. Crisp Outer Contour Definition & Dried Tip Hook
  drawPodContourAndTip(pod, pal);

  // 10. CURLED GREEN CALYX CROWN & WOODY TWISTED STEM
  drawPodCalyxAndCurledStem(pod);
}

function getPodPalette(hueType) {
  if (hueType === "deep") {
    return {
      coreShadow: "#240204",
      oxblood: "#3d0408",
      deepCarmine: "#63080e",
      midRed: "#8c0f16",
      lacquerRed: "#ab151c",
      sunScarlet: "#cc2222",
      hotVermilion: "#e33928",
      reflectedWall: "#8f3b32"
    };
  } else if (hueType === "crimson") {
    return {
      coreShadow: "#2b0305",
      oxblood: "#4a060a",
      deepCarmine: "#780a12",
      midRed: "#a1121a",
      lacquerRed: "#bf1920",
      sunScarlet: "#de2824",
      hotVermilion: "#f04329",
      reflectedWall: "#a3463c"
    };
  } else {
    // Bright sunlit lacquer scarlet
    return {
      coreShadow: "#330406",
      oxblood: "#54070c",
      deepCarmine: "#870c14",
      midRed: "#b3141c",
      lacquerRed: "#cf1d22",
      sunScarlet: "#eb2f24",
      hotVermilion: "#ff4d2e",
      reflectedWall: "#b35044"
    };
  }
}

function evalPodSurfacePoint(pod, t, s) {
  // s in [-1, 1] across the width of the pod
  let sp = evalPodSpine(pod, t);
  let w = evalPodWidth(pod, t, s >= 0 ? 1 : -1);
  // Add 3D foreshortened bulge near shoulder
  let axialLift = (1 - s * s) * sin(t * 180) * 4.5;
  return {
    x: sp.x + sp.nx * (s * w) - sp.tx * axialLift,
    y: sp.y + sp.ny * (s * w) - sp.ty * axialLift
  };
}

function drawDustyShoulders(pod) {
  // Dusty pale mineral bloom & dried field dust settled on the upper shoulder (t in 0.02..0.28)
  for (let i = 0; i < 28; i++) {
    let t = random(0.02, 0.25);
    let s = random(-0.85, 0.75);
    let pt = evalPodSurfacePoint(pod, t, s);
    let dustCol = random(["#e8dfd0", "#d9cdb8", "#f2ece1", "#c7baa2"]);
    brush.set("dustBloom", dustCol, random(0.55, 1.1));
    brush.line(pt.x - 4, pt.y - 2, pt.x + 4, pt.y + 2);
  }

  // Chalky dust gathered inside the upper shoulder wrinkle valleys
  for (let r = 0; r < 9; r++) {
    let s = map(r, 0, 8, -0.78, 0.68) + random(-0.04, 0.04);
    let p0 = evalPodSurfacePoint(pod, 0.03, s);
    let p1 = evalPodSurfacePoint(pod, 0.12, s + random(-0.05, 0.05));
    let p2 = evalPodSurfacePoint(pod, 0.24, s + random(-0.05, 0.05));
    brush.set("charcoal", "#e3d8c4", random(0.45, 0.85));
    brush.spline([[p0.x, p0.y, 0.9], [p1.x, p1.y, 0.7], [p2.x, p2.y, 0.2]], 0.4);
  }
}

function drawPodSplitAndSeeds(pod) {
  // Longitudinal split from t = 0.22 to t = 0.80 revealing cavity, pith placenta, and golden seeds!
  let tStart = 0.21;
  let tEnd = 0.81;
  let sCenter = -0.06;
  let halfGap = pod.splitOpen * 0.45;
  let splitSteps = 16;

  let leftRim = [];
  let rightRim = [];
  let pithLine = [];

  for (let i = 0; i <= splitSteps; i++) {
    let u = i / splitSteps;
    let t = lerp(tStart, tEnd, u);
    // Spindle opening profile (pinched at ends, gaping in middle)
    let openEnv = sin(u * 180) * (0.85 + 0.15 * sin(u * 540));
    let sL = sCenter - halfGap * openEnv;
    let sR = sCenter + halfGap * openEnv;

    leftRim.push(evalPodSurfacePoint(pod, t, sL));
    rightRim.push(evalPodSurfacePoint(pod, t, sR));
    pithLine.push(evalPodSurfacePoint(pod, t, sCenter + 0.03 * openEnv));
  }

  // 1. Deep dark interior cavity of the split pod
  brush.noStroke();
  brush.wash("#1a0203", 252);
  brush.beginShape(0.3);
  for (let p of leftRim) brush.vertex(p.x, p.y);
  for (let i = rightRim.length - 1; i >= 0; i--) brush.vertex(rightRim[i].x, rightRim[i].y);
  brush.endShape(true);

  // Inner reddish-brown pericarp wall visible on shadow side of cavity
  brush.wash("#4a0909", 230);
  brush.beginShape(0.3);
  for (let p of pithLine) brush.vertex(p.x, p.y);
  for (let i = rightRim.length - 1; i >= 0; i--) brush.vertex(rightRim[i].x, rightRim[i].y);
  brush.endShape(true);
  brush.noWash();

  // 2. Pale orange-cream spongy placenta / pith rib down the center of the cavity
  let pithPts = pithLine.map((p, idx) => [
    p.x + sin(idx * 45) * 1.5,
    p.y,
    sin((idx / splitSteps) * 180) * 1.2
  ]);
  brush.set("satinMarker", "#d97b38", 1.8);
  brush.spline(pithPts, 0.45);
  brush.set("cpencil", "#f5c487", 1.1);
  brush.spline(pithPts, 0.45);

  // 3. Individual Hyperreal Paprika Seeds nestled inside the split!
  const numSeeds = pod.layer === 2 ? 42 : 26;
  for (let i = 0; i < numSeeds; i++) {
    let u = map(i, 0, numSeeds - 1, 0.08, 0.92) + random(-0.025, 0.025);
    u = constrain(u, 0.07, 0.93);
    let t = lerp(tStart, tEnd, u);
    let openEnv = sin(u * 180);
    let sOff = sCenter + random(-halfGap * 0.72, halfGap * 0.68) * openEnv;
    let sp = evalPodSurfacePoint(pod, t, sOff);

    let seedAng = random(0, 360);
    let seedR = random(3.8, 5.6) * (0.75 + 0.35 * openEnv);
    let inDeepShadow = sOff > sCenter + halfGap * 0.25 * openEnv;

    drawSinglePaprikaSeed(sp.x, sp.y, seedR, seedAng, inDeepShadow);
  }

  // 4. Curled, translucent red & amber split skin edges overlapping the outer seeds
  let leftSpline = leftRim.map((p, idx) => [p.x, p.y, 0.7 + 0.5 * sin((idx / splitSteps) * 180)]);
  let rightSpline = rightRim.map((p, idx) => [p.x, p.y, 0.7 + 0.5 * sin((idx / splitSteps) * 180)]);

  // Inner golden-orange cut flesh edge of the split pericarp
  brush.set("cpencil", "#f07c3a", 1.15);
  brush.spline(leftSpline, 0.4);
  brush.set("cpencil", "#b8431f", 1.0);
  brush.spline(rightSpline, 0.4);

  // Crisp dark dried split lip & bright lacquer highlight on the curled left rim
  brush.set("pen", "#2e0204", 0.85);
  brush.spline(leftSpline, 0.4);
  brush.spline(rightSpline, 0.4);

  let leftHighlight = leftSpline.slice(2, leftSpline.length - 2).map(p => [p[0] - 1.8, p[1] - 0.8, p[2]]);
  brush.set("lacquerGlint", "#ffdbd1", 0.85);
  brush.spline(leftHighlight, 0.4);
}

function drawSinglePaprikaSeed(x, y, r, ang, inShadow) {
  push();
  translate(x, y);
  rotate(ang);

  // Tiny cast shadow under the seed
  brush.noStroke();
  brush.wash("#170102", 235);
  brush.circle(1.2, 1.5, r * 1.05, 0.12);

  // Flat kidney / teardrop seed body
  let bodyCol = inShadow ? "#c48b37" : random(["#e8b858", "#f2ca6d", "#f7d983", "#dba444"]);
  brush.wash(bodyCol, 248);
  brush.beginShape(0.38);
  brush.vertex(-r * 1.1, 0);
  brush.vertex(-r * 0.4, -r * 0.78);
  brush.vertex(r * 0.65, -r * 0.72);
  brush.vertex(r * 1.05, 0);
  brush.vertex(r * 0.65, r * 0.78);
  brush.vertex(-r * 0.35, r * 0.68);
  brush.endShape(true);
  brush.noWash();

  // Darker amber embryo dimple in seed center
  brush.set("pen", inShadow ? "#6e4310" : "#9c631a", 0.55);
  brush.arc(0, 0, r * 0.48, 20, 250);

  // Thickened golden seed rim & tiny specular catchlight
  if (!inShadow) {
    brush.set("lacquerGlint", "#fff9e6", 0.55);
    brush.arc(0, -r * 0.1, r * 0.72, 200, 340);
  }

  pop();
}

function drawPodContourAndTip(pod, pal) {
  let steps = 20;
  let leftEdge = [];
  let rightEdge = [];

  for (let i = 0; i <= steps; i++) {
    let t = i / steps;
    let pL = evalPodSurfacePoint(pod, t, -0.98);
    let pR = evalPodSurfacePoint(pod, t, 0.98);
    leftEdge.push([pL.x, pL.y, 0.6 + 0.5 * sin(t * 180)]);
    rightEdge.push([pR.x, pR.y, 0.6 + 0.5 * sin(t * 180)]);
  }

  // Sunlit left contour in glowing scarlet
  brush.set("pen", pal.sunScarlet, 0.9);
  brush.spline(leftEdge, 0.4);

  // Shadow right contour in deep oxblood
  brush.set("pen", pal.coreShadow, 1.0);
  brush.spline(rightEdge, 0.4);

  // Shrunken, dark, slightly curled dried tip at t = 1
  let pTip = evalPodSpine(pod, 1.0);
  let pHook = {
    x: pTip.x + pTip.tx * 9 + pTip.nx * 5,
    y: pTip.y + pTip.ty * 9 + pTip.ny * 5
  };
  brush.set("satinMarker", "#2e0305", 1.3);
  brush.line(pTip.x, pTip.y, pHook.x, pHook.y);
  brush.set("lacquerGlint", "#ff9478", 0.65);
  brush.line(pTip.x - 1, pTip.y - 1, pHook.x - 1, pHook.y - 1);
}

function drawPodCalyxAndCurledStem(pod) {
  let sp0 = evalPodSpine(pod, 0.02);
  let w0 = pod.w0 * 0.92;

  // 1. Sharp contact shadow of the calyx teeth gripping the dusty red shoulder
  const numTeeth = 5;
  brush.noStroke();
  brush.wash("#240304", 210);
  brush.beginShape(0.35);
  for (let i = 0; i <= numTeeth; i++) {
    let s = map(i, 0, numTeeth, -0.88, 0.88);
    let pTooth = evalPodSurfacePoint(pod, 0.08 + 0.03 * (i % 2), s);
    brush.vertex(pTooth.x + 2, pTooth.y + 4);
  }
  for (let i = numTeeth; i >= 0; i--) {
    let s = map(i, 0, numTeeth, -0.78, 0.78);
    let pTop = evalPodSurfacePoint(pod, 0.0, s);
    brush.vertex(pTop.x, pTop.y - 4);
  }
  brush.endShape(true);

  // 2. Dried Olive-Green & Khaki-Sage Calyx Crown (5 pointed curled sepals)
  let calyxPts = [];
  for (let i = 0; i < numTeeth; i++) {
    let sL = map(i, 0, numTeeth, -0.86, 0.86);
    let sM = map(i + 0.5, 0, numTeeth, -0.86, 0.86);
    let sR = map(i + 1, 0, numTeeth, -0.86, 0.86);

    let pBaseL = evalPodSurfacePoint(pod, 0.01, sL * 0.75);
    let pTip = evalPodSurfacePoint(pod, 0.085 + (i % 2) * 0.025, sM);
    let pBaseR = evalPodSurfacePoint(pod, 0.01, sR * 0.75);

    let sepalCol = i < 2 ? "#697d44" : i === 2 ? "#556935" : "#3d4d24";
    brush.wash(sepalCol, 248);
    brush.beginShape(0.32);
    brush.vertex(sp0.x - sp0.tx * 7, sp0.y - sp0.ty * 7);
    brush.vertex(pBaseL.x, pBaseL.y);
    brush.vertex(pTip.x, pTip.y);
    brush.vertex(pBaseR.x, pBaseR.y);
    brush.endShape(true);

    calyxPts.push([pBaseL.x, pBaseL.y, pTip.x, pTip.y, pBaseR.x, pBaseR.y]);
  }
  brush.noWash();

  // Fibrous ridges & dry straw edges on the calyx sepals
  for (let cp of calyxPts) {
    brush.set("pen", "#263314", 0.8);
    brush.spline([[cp[0], cp[1], 0.6], [cp[2], cp[3], 1.0], [cp[4], cp[5], 0.6]], 0.4);
    brush.set("cpencil", "#c7be8f", 0.75);
    brush.line(sp0.x - sp0.tx * 4, sp0.y - sp0.ty * 4, cp[2], cp[3]);
  }

  // 3. Curled Woody Green Stem (Pedicel) twisting up to the hemp twine
  let st = pod.stem;
  let pA = st[0]; // Attachment near twine
  let pB = st[1]; // Mid-curl control
  let pC = [sp0.x - sp0.tx * 4, sp0.y - sp0.ty * 4]; // Calyx crown center

  // Build curled 3D stem path
  let stemCenter = [
    [pC[0], pC[1], 1.3],
    [pB[0], pB[1], 1.1],
    [pA[0], pA[1], 0.95]
  ];

  // Dark forest-olive shadow side of stem
  brush.set("satinMarker", "#2b3818", 2.6);
  brush.spline(stemCenter.map(p => [p[0] + 2.2, p[1] + 2.2, p[2]]), 0.55);

  // Mid olive-green woody stem body
  brush.set("satinMarker", "#566b34", 2.3);
  brush.spline(stemCenter, 0.55);

  // Sunlit sage-ochre longitudinal woody striations along stem
  brush.set("cpencil", "#98a865", 1.25);
  brush.spline(stemCenter.map(p => [p[0] - 1.5, p[1] - 1.5, p[2]]), 0.55);

  brush.set("pen", "#d9d1a3", 0.75);
  brush.spline(stemCenter.map(p => [p[0] - 2.2, p[1] - 2.0, p[2] * 0.8]), 0.55);

  // Tiny pale woody cut face at the stem tip near the twine
  brush.noStroke();
  brush.wash("#cfc293", 245);
  brush.circle(pA[0], pA[1], 4.5, 0.15);
  brush.noWash();
  brush.set("pen", "#4a3e22", 0.7);
  brush.circle(pA[0], pA[1], 4.5, 0.15);
}

// Imperial Mughal Miniature: Shah Jahan Jade Horse-Head Dagger Hilt (Khanjar)
// Rendered with p5.brush in layered watercolour, one-hair brush stippling (pardakht),
// and kundan gold & ruby inlays within a gold-flecked muraqqa album border.

async function setup() {
  createCanvas(1200, 1200, WEBGL);
  brush.scaleBrushes(3);
  angleMode(DEGREES);
  randomSeed(1648);
  noiseSeed(1648);

  // Register custom brushes for Mughal miniature technique
  // 1. One-hair squirrel brush (yak-baal qalam) for micro-stippling & hair-thin contours
  brush.add("one_hair", {
    type: "default",
    weight: 0.16,
    scatter: 0.03,
    sharpness: 0.9,
    grain: 0.25,
    opacity: 165,
    spacing: 0.12,
    pressure: [0.25, 1.0, 0.2],
    rotate: "natural",
    noise: 0.25
  });

  // 2. Soft watercolour glazing brush for translucent nephrite jade modelling
  brush.add("jade_glaze", {
    type: "default",
    weight: 0.95,
    scatter: 0.35,
    sharpness: 0.18,
    grain: 0.22,
    opacity: 42,
    spacing: 0.18,
    pressure: [0.15, 1.0, 0.15],
    rotate: "natural",
    noise: 0.2
  });

  // 3. Burnished gold wire & pinpoint highlight brush
  brush.add("gold_pin", {
    type: "default",
    weight: 0.22,
    scatter: 0.01,
    sharpness: 0.96,
    grain: 0.08,
    opacity: 235,
    spacing: 0.08,
    pressure: [0.6, 1.0, 0.5],
    rotate: "natural",
    noise: 0.1
  });

  // 4. Mineral dust & zar-afshan gold fleck spray
  brush.add("mineral_dust", {
    type: "spray",
    weight: 0.55,
    scatter: 1.6,
    opacity: 130,
    spacing: 0.7,
    pressure: [0.7, 1.0, 0.7],
    rotate: "random",
    noise: 0.4
  });

  background("#2b1e26");
}

function draw() {
  translate(-width / 2, -height / 2);
  brush.noField();

  // 1. MANUSCRIPT PAGE OUTER BORDER (Dusky Twilight Hashiya with Gold Flecks)
  drawOuterHashiya();

  // 2. SCROLLING ARABESQUE MARGIN (Islimi Band) & LAPIS LAZULI INNER BAND
  drawMuraqqaBorders();

  // 3. FLAT SAFFRON FIELD (Dusky Twilight Inflected Mineral Ground)
  drawSaffronField();

  // 4. UPPER DAMASCUS WATERED STEEL BLADE & GOLD KOFTGARI RICASSO
  drawDamascusBlade();

  // 5. NEPHRITE JADE HORSE-HEAD HILT (Translucent Watercolour & One-Hair Pardakht)
  drawJadeHorseHilt();

  // 6. KUNDAN GOLD WIRE BRIDLES, FLORAL INLAYS, RUBIES & EMERALDS
  drawKundanJewelsAndBridle();

  noLoop();
}

// ============================================================================
// GEOMETRY & WATERCOLOUR HELPERS
// ============================================================================

function drawPoly(pts, curv = 0.25, closed = true) {
  brush.beginShape(curv);
  for (let i = 0; i < pts.length; i++) {
    brush.vertex(pts[i][0], pts[i][1]);
  }
  brush.endShape(closed);
}

function fillZone(pts, col, alpha, bleed = 0.12, tex = 0.3, border = 0.18, curv = 0.3) {
  brush.noStroke();
  brush. noWash();
  brush.fill(col, alpha);
  brush.fillBleed(bleed, "out");
  brush.fillTexture(tex, border);
  drawPoly(pts, curv, true);
  brush.noFill();
}

function washZone(pts, col, alpha, curv = 0.25) {
  brush.noStroke();
  brush.noFill();
  brush.wash(col, alpha);
  drawPoly(pts, curv, true);
  brush.noWash();
}

function lerpPt(p1, p2, t) {
  return [lerp(p1[0], p2[0], t), lerp(p1[1], p2[1], t)];
}

function quadPt(p0, p1, p2, t) {
  let u = 1 - t;
  return [
    u * u * p0[0] + 2 * u * t * p1[0] + t * t * p2[0],
    u * u * p0[1] + 2 * u * t * p1[1] + t * t * p2[1]
  ];
}

