// 1. OUTER BORDER (HASHIYA) - DUSKY TWILIGHT ANTIQUE PAPER & ZAR-AFSHAN GOLD
// ============================================================================

function drawOuterHashiya() {
  // Base dusky twilight plum-slate wash across entire folio
  brush.noStroke();
  brush.wash("#2f212a", 255);
  brush.rect(0, 0, 1200, 1200, "corner");
  brush.noWash();

  // Atmospheric twilight watercolour washes on the outer margins
  let marginBands = [
    [[0, 0], [1200, 0], [1200, 95], [0, 95]],
    [[0, 1105], [1200, 1105], [1200, 1200], [0, 1200]],
    [[0, 80], [150, 80], [150, 1120], [0, 1120]],
    [[1050, 80], [1200, 80], [1200, 1120], [1050, 1120]]
  ];

  for (let b of marginBands) {
    fillZone(b, "#3d2a35", 85, 0.25, 0.45, 0.2, 0.05);
  }

  // Subtle twilight indigo & rose-umber mottling in the outer margin
  for (let i = 0; i < 24; i++) {
    let side = i % 4;
    let cx, cy, rx, ry;
    if (side === 0) { cx = random(60, 1140); cy = random(20, 70); rx = random(60, 130); ry = random(20, 35); }
    else if (side === 1) { cx = random(60, 1140); cy = random(1130, 1180); rx = random(60, 130); ry = random(20, 35); }
    else if (side === 2) { cx = random(25, 120); cy = random(100, 1100); rx = random(30, 55); ry = random(60, 140); }
    else { cx = random(1080, 1175); cy = random(100, 1100); rx = random(30, 55); ry = random(60, 140); }

    let pts = [];
    for (let a = 0; a < 360; a += 45) {
      pts.push([cx + cos(a) * rx, cy + sin(a) * ry]);
    }
    let col = i % 2 === 0 ? "#231c2e" : "#4a323b";
    fillZone(pts, col, 45, 0.3, 0.4, 0.15, 0.4);
  }

  // Antique paper deckle & woven grain lines around outer margin
  brush.set("one_hair", "#4d3843", 0.35);
  for (let i = 0; i < 280; i++) {
    let x, y;
    if (random() < 0.5) {
      x = random() < 0.5 ? random(8, 132) : random(1068, 1192);
      y = random(8, 1192);
    } else {
      x = random(8, 1192);
      y = random() < 0.5 ? random(8, 72) : random(1128, 1192);
    }
    let len = random(10, 32);
    let ang = random() < 0.7 ? random(-4, 4) : random(86, 94);
    brush.line(x, y, x + cos(ang) * len, y + sin(ang) * len);
  }

  // Zar-afshan (sprinkled gold leaf flecks & dust) across the outer margin
  let goldPalette = ["#a67926", "#cfa03c", "#ebd55b", "#ffea9f", "#8a5e18"];
  for (let c = 0; c < goldPalette.length; c++) {
    brush.set("mineral_dust", goldPalette[c], 0.55);
    for (let i = 0; i < 95; i++) {
      let x, y;
      if (random() < 0.58) {
        x = random() < 0.5 ? random(10, 132) : random(1068, 1190);
        y = random(10, 1190);
      } else {
        x = random(10, 1190);
        y = random() < 0.5 ? random(10, 72) : random(1128, 1190);
      }
      brush.line(x, y, x + random(-12, 12), y + random(-12, 12));
    }
  }

  // Distinct tiny beaten gold leaf flakes (squares & diamonds)
  for (let c = 0; c < 3; c++) {
    let col = c === 0 ? "#c79430" : (c === 1 ? "#f0c85b" : "#fff0a8");
    brush.set("gold_pin", col, 0.55);
    for (let i = 0; i < 160; i++) {
      let x, y;
      if (random() < 0.55) {
        x = random() < 0.5 ? random(12, 130) : random(1070, 1188);
        y = random(12, 1188);
      } else {
        x = random(12, 1188);
        y = random() < 0.5 ? random(12, 70) : random(1130, 1188);
      }
      let s = random(1.2, 3.8);
      brush.line(x, y, x + s, y + random(-1.5, 1.5));
      if (random() < 0.45) {
        brush.line(x, y + 0.8, x + s * 0.8, y + 0.8);
      }
    }
  }
}

