function drawJadwalFrame(x, y, w, h, goldCol, redCol) {
  // Gold leaf rule band (4px thick)
  brush.set("gold_pin", "#9e6e18", 1.1);
  brush.noFill();
  brush.rect(x, y, w, h, "corner");

  brush.set("gold_pin", goldCol, 1.3);
  brush.rect(x + 1.5, y + 1.5, w - 3, h - 3, "corner");

  brush.set("gold_pin", "#fff0a6", 0.55);
  brush.rect(x + 2, y + 2, w - 4, h - 4, "corner");

  // Cinnabar red hairline rule
  brush.set("one_hair", redCol, 0.55);
  brush.rect(x - 2, y - 2, w + 4, h + 4, "corner");

  // Crisp black ink framing lines
  brush.set("one_hair", "#120c10", 0.65);
  brush.rect(x, y, w, h, "corner");
  brush.rect(x + 4, y + 4, w - 8, h - 8, "corner");
}

function drawHorizontalIslimi(xStart, xEnd, yCenter, count) {
  let step = (xEnd - xStart) / count;
  let vinePts = [];
  let subVinePts = [];

  for (let i = 0; i <= count * 4; i++) {
    let t = i / (count * 4);
    let x = lerp(xStart, xEnd, t);
    let wave = sin(t * count * 180) * 14;
    let wave2 = cos(t * count * 180) * 10;
    vinePts.push([x, yCenter + wave]);
    subVinePts.push([x, yCenter - wave2]);
  }

  // Secondary pale celadon-gold counter-vine
  brush.set("one_hair", "#7a8f7d", 0.55);
  brush.spline(subVinePts, 0.5);

  // Main burnished gold spiral vine
  brush.set("gold_pin", "#b88628", 0.85);
  brush.spline(vinePts, 0.5);
  brush.set("gold_pin", "#f5d06c", 0.45);
  brush.spline(vinePts, 0.5);

  // Floral palmettes & buds at each wave crest
  for (let i = 0; i < count; i++) {
    let cx = xStart + (i + 0.5) * step;
    let dir = i % 2 === 0 ? 1 : -1;
    let cy = yCenter + dir * 11;

    // Coiling tendril
    let tendril = [
      [cx - step * 0.22, yCenter],
      [cx, cy],
      [cx + step * 0.14, yCenter - dir * 5],
      [cx + step * 0.04, yCenter - dir * 9]
    ];
    brush.set("gold_pin", "#e0b145", 0.55);
    brush.spline(tendril, 0.6);

    // Lotus palmette petals (gold + ruby center)
    drawMiniFlower(cx, cy - dir * 4, 6.5);
    // Tiny celadon leaf bud
    drawMiniLeaf(cx - step * 0.18, yCenter - dir * 7, dir * 35);
    drawMiniLeaf(cx + step * 0.18, yCenter + dir * 6, -dir * 35);
  }
}

function drawVerticalIslimi(xCenter, yStart, yEnd, count) {
  let step = (yEnd - yStart) / count;
  let vinePts = [];
  let subVinePts = [];

  for (let i = 0; i <= count * 4; i++) {
    let t = i / (count * 4);
    let y = lerp(yStart, yEnd, t);
    let wave = sin(t * count * 180) * 14;
    let wave2 = cos(t * count * 180) * 10;
    vinePts.push([xCenter + wave, y]);
    subVinePts.push([xCenter - wave2, y]);
  }

  brush.set("one_hair", "#7a8f7d", 0.55);
  brush.spline(subVinePts, 0.5);

  brush.set("gold_pin", "#b88628", 0.85);
  brush.spline(vinePts, 0.5);
  brush.set("gold_pin", "#f5d06c", 0.45);
  brush.spline(vinePts, 0.5);

  for (let i = 0; i < count; i++) {
    let cy = yStart + (i + 0.5) * step;
    let dir = i % 2 === 0 ? 1 : -1;
    let cx = xCenter + dir * 11;

    let tendril = [
      [xCenter, cy - step * 0.22],
      [cx, cy],
      [xCenter - dir * 5, cy + step * 0.14],
      [xCenter - dir * 9, cy + step * 0.04]
    ];
    brush.set("gold_pin", "#e0b145", 0.55);
    brush.spline(tendril, 0.6);

    drawMiniFlower(cx - dir * 4, cy, 6.5);
    drawMiniLeaf(xCenter - dir * 7, cy - step * 0.18, 90 + dir * 35);
    drawMiniLeaf(xCenter + dir * 6, cy + step * 0.18, 90 - dir * 35);
  }
}

function drawMiniFlower(x, y, r) {
  // Five-petal gold & cinnabar rosette
  brush.set("gold_pin", "#d9a53b", 0.65);
  for (let a = 0; a < 360; a += 72) {
    let px = x + cos(a) * r;
    let py = y + sin(a) * r;
    brush.line(x, y, px, py);
    brush.line(x + cos(a - 18) * (r * 0.6), y + sin(a - 18) * (r * 0.6), px, py);
  }
  // Ruby heart
  brush.set("gold_pin", "#c92434", 0.9);
  brush.line(x - 1.5, y, x + 1.5, y);
  brush.line(x, y - 1.5, x, y + 1.5);
  // Pinpoint pearl dot
  brush.set("gold_pin", "#fff5de", 0.55);
  brush.line(x - 0.4, y - 0.4, x + 0.4, y - 0.4);
}

function drawMiniLeaf(x, y, ang) {
  let x2 = x + cos(ang) * 7;
  let y2 = y + sin(ang) * 7;
  brush.set("gold_pin", "#7da38c", 0.65);
  brush.line(x, y, x2, y2);
  brush.set("gold_pin", "#e6c365", 0.4);
  brush.line(x, y, x + cos(ang + 15) * 5, y + sin(ang + 15) * 5);
}

function drawCornerMedallion(cx, cy, r) {
  brush.set("gold_pin", "#d9a63c", 0.75);
  brush.noFill();
  brush.circle(cx, cy, r, 0.08);
  brush.circle(cx, cy, r * 0.55, 0.05);
  for (let a = 0; a < 360; a += 45) {
    brush.line(cx + cos(a) * (r * 0.3), cy + sin(a) * (r * 0.3), cx + cos(a) * r, cy + sin(a) * r);
  }
  brush.set("gold_pin", "#cf2334", 1.1);
  brush.line(cx - 2, cy, cx + 2, cy);
  brush.line(cx, cy - 2, cx, cy + 2);
  brush.set("gold_pin", "#fff7e0", 0.6);
  brush.line(cx - 0.5, cy - 0.5, cx + 0.5, cy - 0.5);
}

function drawHorizontalLapisMotifs(xStart, xEnd, y, count) {
  let step = (xEnd - xStart) / count;
  for (let i = 0; i < count; i++) {
    let cx = xStart + (i + 0.5) * step;
    // Elongated gold cartouche
    let hw = step * 0.28;
    let hh = 7;
    let pts = [
      [cx - hw, y], [cx - hw * 0.6, y - hh], [cx + hw * 0.6, y - hh],
      [cx + hw, y], [cx + hw * 0.6, y + hh], [cx - hw * 0.6, y + hh]
    ];
    brush.set("gold_pin", "#e3b448", 0.6);
    drawPoly(pts, 0.2, true);
    brush.set("gold_pin", "#fff0a6", 0.35);
    brush.line(cx - hw * 0.5, y, cx + hw * 0.5, y);

    // Ruby & pearl dot inside cartouche
    brush.set("gold_pin", "#d92538", 0.85);
    brush.line(cx - 1.5, y, cx + 1.5, y);
    brush.set("gold_pin", "#ffffff", 0.5);
    brush.line(cx - 0.4, y - 0.4, cx + 0.4, y - 0.4);

    // Four-petal gold star between cartouches
    if (i < count - 1) {
      let sx = cx + step * 0.5;
      brush.set("gold_pin", "#f0c965", 0.55);
      brush.line(sx - 5, y, sx + 5, y);
      brush.line(sx, y - 5, sx, y + 5);
      brush.set("gold_pin", "#fff8e6", 0.45);
      brush.line(sx - 1, y - 1, sx + 1, y + 1);
    }
  }
}

function drawVerticalLapisMotifs(x, yStart, yEnd, count) {
  let step = (yEnd - yStart) / count;
  for (let i = 0; i < count; i++) {
    let cy = yStart + (i + 0.5) * step;
    let hh = step * 0.28;
    let hw = 7;
    let pts = [
      [x, cy - hh], [x + hw, cy - hh * 0.6], [x + hw, cy + hh * 0.6],
      [x, cy + hh], [x - hw, cy + hh * 0.6], [x - hw, cy - hh * 0.6]
    ];
    brush.set("gold_pin", "#e3b448", 0.6);
    drawPoly(pts, 0.2, true);
    brush.set("gold_pin", "#fff0a6", 0.35);
    brush.line(x, cy - hh * 0.5, x, cy + hh * 0.5);

    brush.set("gold_pin", "#d92538", 0.85);
    brush.line(x, cy - 1.5, x, cy + 1.5);
    brush.set("gold_pin", "#ffffff", 0.5);
    brush.line(x - 0.4, cy - 0.4, x + 0.4, cy - 0.4);

    if (i < count - 1) {
      let sy = cy + step * 0.5;
      brush.set("gold_pin", "#f0c965", 0.55);
      brush.line(x - 5, sy, x + 5, sy);
      brush.line(x, sy - 5, x, sy + 5);
      brush.set("gold_pin", "#fff8e6", 0.45);
      brush.line(x - 1, sy - 1, x + 1, sy + 1);
    }
  }
}

