}

function drawCornerSpandrel(cx, cy, dx, dy) {
  let s = 54;
  let pts = [
    [cx, cy],
    [cx + dx * s, cy],
    [cx + dx * s * 0.72, cy + dy * s * 0.32],
    [cx + dx * s * 0.48, cy + dy * s * 0.48],
    [cx + dx * s * 0.32, cy + dy * s * 0.72],
    [cx, cy + dy * s]
  ];
  washZone(pts, "#162c63", 250, 0.25);
  fillZone(pts, "#0e1d42", 120, 0.08, 0.35, 0.2, 0.25);

  // Gold filigree border & arabesque inside spandrel
  brush.set("gold_pin", "#e8b84b", 0.7);
  drawPoly(pts, 0.25, true);

  brush.set("gold_pin", "#ffe285", 0.45);
  brush.line(cx + dx * 6, cy + dy * 6, cx + dx * 28, cy + dy * 28);
  brush.line(cx + dx * 8, cy + dy * 22, cx + dx * 24, cy + dy * 14);
  brush.line(cx + dx * 22, cy + dy * 8, cx + dx * 14, cy + dy * 24);

  drawMiniFlower(cx + dx * 17, cy + dy * 17, 5.5);
}

