// 4. DAMASCUS WATERED STEEL BLADE (FAULAD-I-JAWHARDAR) & GOLD KOFTGARI
// ============================================================================

function drawDamascusBlade() {
  // Upper section of the curved double-edged khanjar blade emerging below collar (y = 838..982)
  // Left (cutting curve) & Right (spine curve) + central raised ridge (fuller/rib)
  let leftBlade = [
    [548, 838], [545, 875], [547, 915], [554, 952], [566, 984],
    [588, 945], [599, 905], [606, 868], [610, 838]
  ];
  let rightBlade = [
    [610, 838], [606, 868], [599, 905], [588, 945], [566, 984],
    [606, 955], [636, 920], [658, 880], [672, 838]
  ];

  // Opaque steel base washes
  washZone(leftBlade, "#3a4556", 255, 0.2);
  washZone(rightBlade, "#1e2430", 255, 0.2);

  // Twilight metallic watercolour modelling
  fillZone(leftBlade, "#4f5e75", 130, 0.08, 0.35, 0.2, 0.2);
  fillZone(rightBlade, "#141821", 150, 0.08, 0.4, 0.25, 0.2);

  // Subtle saffron-twilight reflection near the blade tip
  let tipGlow = [[550, 920], [566, 984], [592, 935], [575, 915]];
  fillZone(tipGlow, "#6e5c52", 65, 0.15, 0.3, 0.1, 0.2);

  // Wootz Damascus watering patterns (Jawhar swirling micro-lines)
  for (let i = 0; i < 48; i++) {
    let t = i / 48;
    let y = lerp(842, 976, t);
    let xL = lerp(548, 566, t * t) - sin(t * 90) * 3;
    let xM = lerp(610, 566, pow(t, 1.15));
    let xR = lerp(671, 566, pow(t, 0.92));

    // Left bevel watering (silvery blue-grey)
    let ptsL = [];
    for (let s = 0; s <= 6; s++) {
      let u = s / 6;
      let px = lerp(xL + 2, xM - 1, u);
      let py = y + sin(u * 360 + i * 35) * 2.4 + cos(i * 50) * 1.2;
      ptsL.push([px, py]);
    }
    brush.set("one_hair", i % 2 === 0 ? "#7a8da6" : "#252d3b", 0.3);
    brush.spline(ptsL, 0.5);

    // Right bevel watering (deep charcoal & dusky steel)
    let ptsR = [];
    for (let s = 0; s <= 6; s++) {
      let u = s / 6;
      let px = lerp(xM + 1, xR - 2, u);
      let py = y + cos(u * 360 + i * 40) * 2.4;
      ptsR.push([px, py]);
    }
    brush.set("one_hair", i % 2 === 0 ? "#435066" : "#0e1218", 0.3);
    brush.spline(ptsR, 0.5);
  }

  // Crisp central ridge highlight & bevel edges
  let ridgeLine = [[610, 838], [606, 868], [599, 905], [588, 945], [566, 984]];
  brush.set("one_hair", "#c4d4eb", 0.65);
  brush.spline(ridgeLine, 0.3);
  brush.set("gold_pin", "#eef5ff", 0.35);
  brush.spline([[609, 842], [604, 875], [596, 912]], 0.3);

  // Outer blade edges
  brush.set("one_hair", "#8fa2bd", 0.55);
  brush.spline([[548, 838], [545, 875], [547, 915], [554, 952], [566, 984]], 0.3);
  brush.set("one_hair", "#11151d", 0.65);
  brush.spline([[672, 838], [658, 880], [636, 920], [606, 955], [566, 984]], 0.3);

  // Gold Koftgari (Damascened gold arabesque) at the ricasso (y = 844..908)
  let koftgariCartouche = [
    [572, 842], [646, 842], [632, 872], [612, 892],
    [597, 914], [589, 890], [575, 868]
  ];
  brush.set("gold_pin", "#d4a035", 0.65);
  drawPoly(koftgariCartouche, 0.35, true);

  // Intricate gold scrollwork inside ricasso
  for (let side of [-1, 1]) {
    let scroll = [
      [608, 848],
      [608 + side * 18, 856],
      [604 + side * 22, 870],
      [602 + side * 10, 882],
      [599, 898]
    ];
    brush.set("gold_pin", "#f2c85b", 0.55);
    brush.spline(scroll, 0.5);

    let innerCurl = [
      [606 + side * 6, 854],
      [605 + side * 14, 864],
      [603 + side * 6, 872]
    ];
    brush.set("gold_pin", "#ffe89e", 0.4);
    brush.spline(innerCurl, 0.5);
  }
  drawMiniFlower(603, 868, 5);
}

