      [lerp(558, 578, u), lerp(345, 352, u)],
      [lerp(534, 548, u), lerp(352, 366, u)],
      [lerp(510, 526, u), lerp(372, 378, u)]
    ];
    brush.set("one_hair", s % 2 === 0 ? "#3f5c49" : "#f0faef", 0.5);
    brush.spline(fp, 0.45);
  }

  // 12 Sculpted Scalloped Mane Locks along the right arch of the neck
  let numLocks = 12;
  for (let i = 0; i < numLocks; i++) {
    let t0 = i / numLocks;
    let t1 = (i + 1) / numLocks;

    // Crest origin along right edge of neck
    let crest0 = quadPt([614, 355], [728, 495], [682, 725], t0);
    let crest1 = quadPt([614, 355], [728, 495], [682, 725], t1);
    let crestMid = [
      (crest0[0] + crest1[0]) * 0.5 + 7,
      (crest0[1] + crest1[1]) * 0.5
    ];

    // Forward-sweeping tip of each carved lock onto the neck plane
    let tip = quadPt([588, 398], [658, 535], [634, 728], t0 + 0.055);
    let baseIn = quadPt([582, 382], [648, 520], [626, 712], t0);

    let lockPoly = [
      crest0,
      crestMid,
      crest1,
      [lerp(crest1[0], tip[0], 0.55), lerp(crest1[1], tip[1], 0.65) + 6],
      tip,
      [lerp(tip[0], baseIn[0], 0.45) - 4, lerp(tip[1], baseIn[1], 0.5) - 2],
      baseIn
    ];

    // Cast shadow in the jade beneath each overlapping lock
    let shadowPoly = lockPoly.map(p => [p[0] - 3.5, p[1] + 4.5]);
    fillZone(shadowPoly, "#334d3c", 170, 0.08, 0.3, 0.2, 0.3);

    // Opaque & translucent celadon lock body
    washZone(lockPoly, "#98b59d", 250, 0.3);
    fillZone(lockPoly, "#cbe0ca", 165, 0.1, 0.25, 0.12, 0.3);

    // Translucent glow on the outer scalloped crest of the mane
    let crestGlow = [crest0, crestMid, crest1, lerpPt(crest1, tip, 0.35), lerpPt(crest0, tip, 0.35)];
    fillZone(crestGlow, "#e6f2dc", 175, 0.12, 0.2, 0.08, 0.3);

    // 8 incised hair striations per lock with one-hair brush
    for (let h = 0; h <= 7; h++) {
      let u = h / 7;
      let startP = lerpPt(crest0, crest1, u);
      let ctrlP = [
        lerp(crestMid[0], (crest0[0] + tip[0]) * 0.5, u) + (1 - u) * 5,
        lerp(crest0[1], tip[1], 0.48 + u * 0.18)
      ];
      let endP = [
        tip[0] + (u - 0.5) * 8,
        tip[1] + (u - 0.5) * 6
      ];
      // Dark incised groove
      brush.set("one_hair", "#3e5c48", 0.5);
      brush.spline([startP, ctrlP, endP], 0.45);
      // Adjacent polished jade ridge highlight
      brush.set("one_hair", h < 3 ? "#f4fcf2" : "#cfe3ce", 0.45);
      brush.spline([
        [startP[0], startP[1] - 1.1],
        [ctrlP[0], ctrlP[1] - 1.1],
        [endP[0], endP[1] - 1.1]
      ], 0.45);
    }

    // Curled volute tip at the end of each lock
    brush.set("one_hair", "#35523f", 0.55);
    brush.arc(tip[0] + 3, tip[1] - 2, 4.5, 40, 260);
    brush.set("one_hair", "#f2faef", 0.5);
    brush.arc(tip[0] + 3, tip[1] - 2, 3.2, 60, 230);
  }

  // --- I. RAZOR-SHARP SPECULAR JADE HIGHLIGHTS & MASTER CONTOUR ---
  // Continuous luminous edge along brow, nasal bridge & muzzle
  brush.set("gold_pin", "#f7fcf6", 0.8);
  brush.spline([
    [522, 368], [504, 385], [486, 405], [462, 428],
    [435, 452], [408, 474], [396, 492], [394, 510]
  ], 0.35);

  // Specular glint along the upper edge of the cheekbone (zygomatic crest)
  brush.set("gold_pin", "#f7fcf6", 0.75);
  brush.spline([[456, 492], [496, 472], [536, 448], [562, 439]], 0.35);

  // Crisp shadow line directly under the cheekbone crest
  brush.set("one_hair", "#3a5744", 0.65);
  brush.spline([[456, 496], [496, 476], [536, 452], [562, 443]], 0.35);

  // Vertical waxy lustre lines down the neck cylinder
  brush.set("one_hair", "#f2faf0", 0.55);
  brush.spline([[598, 465], [608, 540], [612, 625], [608, 715]], 0.4);
  brush.spline([[608, 475], [618, 550], [622, 635], [616, 718]], 0.4);

  // Master outer contour of the jade horse head in delicate olive-jade ink
  brush.set("one_hair", "#2f4737", 0.65);
  brush.spline([
    [536, 354], [504, 384], [486, 405], [462, 428], [435, 452],
    [408, 474], [395, 492], [393, 512], [401, 529]
  ], 0.3);
  brush.spline([
    [412, 538], [410, 549], [428, 560], [456, 558], [478, 552],
    [506, 560], [538, 560], [562, 546]
  ], 0.3);
  brush.spline([
    [562, 546], [550, 578], [546, 618], [548, 662], [544, 704], [538, 738]
  ], 0.3);

  // --- J. CARVED LOTUS QUILLON BLOCK & COLLAR (y = 732..848) ---
  drawJadeLotusCollar();
}

function drawJadeLotusCollar() {
  // 1. Upper Torus Molding Ring (x: 530..690, y: 732..754)
  let torusRing = [
    [530, 735], [610, 739], [690, 735],
    [694, 745], [690, 755], [610, 759], [530, 755], [526, 745]
  ];
