  brush.set("one_hair", "#385442", 0.65);
  drawPoly(torusRing, 0.25, true);

  // 2. Main Flared Quillon Guard Block with Scrolling Lotus-Bud Volutes (y: 754..822)
  let quillonBody = [
    [530, 755], [610, 759], [690, 755],
    [712, 772], [734, 784], [738, 798], [724, 812], [696, 816],
    [682, 822], [610, 826], [538, 822],
    [524, 816], [496, 812], [482, 798], [486, 784], [508, 772]
  ];
  washZone(quillonBody, "#8eab93", 255, 0.25);
  fillZone(quillonBody, "#608069", 150, 0.12, 0.3, 0.18, 0.25);

  // 9 Carved Upward-Pointing Acanthus / Lotus Petals across the Quillon Block
  let numUpperPetals = 9;
  for (let i = 0; i < numUpperPetals; i++) {
    let t = (i + 0.5) / numUpperPetals;
    let px = lerp(500, 720, t);
    let pw = 12.5;
    let pyBase = 820 - abs(t - 0.5) * 12;
    let pyTip = 758 + abs(t - 0.5) * 18;

    let petal = [
      [px - pw, pyBase],
      [px - pw * 0.85, lerp(pyBase, pyTip, 0.55)],
      [px, pyTip],
      [px + pw * 0.85, lerp(pyBase, pyTip, 0.55)],
      [px + pw, pyBase]
    ];
    fillZone(petal, "#cbe0ca", 175, 0.08, 0.25, 0.12, 0.3);

    // Raised midrib & translucent rim on each carved jade petal
    brush.set("one_hair", "#eef7ec", 0.6);
    brush.line(px, pyBase - 2, px, pyTip + 2);
    brush.spline([[px - pw * 0.8, lerp(pyBase, pyTip, 0.5)], [px, pyTip], [px + pw * 0.8, lerp(pyBase, pyTip, 0.5)]], 0.35);

    // Deep carved groove between petals
    brush.set("one_hair", "#35523f", 0.6);
    drawPoly(petal, 0.3, true);
  }

  // Scrolling jade volute spirals at left (494, 796) and right (726, 796) quillon tips
  for (let side of [-1, 1]) {
    let vx = 610 + side * 116;
    let vy = 796;
    brush.set("one_hair", "#324d3b", 0.65);
    brush.circle(vx, vy, 11, 0.08);
    brush.set("one_hair", "#eff8ee", 0.65);
    brush.arc(vx, vy, 8, side > 0 ? -60 : 120, side > 0 ? 140 : 320);
  }

  // 3. Lower Inverted Lotus Petal Collar Clasping the Blade Root (y: 822..848)
  let lowerCollar = [
    [538, 822], [610, 826], [682, 822],
    [674, 845], [610, 850], [546, 845]
  ];
  washZone(lowerCollar, "#85a38b", 255, 0.2);

  let numLowerPetals = 7;
  for (let i = 0; i < numLowerPetals; i++) {
    let t = (i + 0.5) / numLowerPetals;
    let px = lerp(548, 672, t);
    let pw = 9.5;
    let pyTop = 823;
    let pyBot = 847 - abs(t - 0.5) * 5;

    let petal = [
      [px - pw, pyTop],
      [px - pw * 0.75, lerp(pyTop, pyBot, 0.6)],
      [px, pyBot],
      [px + pw * 0.75, lerp(pyTop, pyBot, 0.6)],
      [px + pw, pyTop]
    ];
    fillZone(petal, "#bdd4bd", 175, 0.08, 0.25, 0.12, 0.25);
    brush.set("one_hair", "#e8f4e6", 0.55);
    brush.line(px, pyTop + 2, px, pyBot - 2);
    brush.set("one_hair", "#324d3b", 0.6);
    drawPoly(petal, 0.25, true);
  }
}

