function drawCabochonRubyEye(cx, cy) {
  // 1. Sculpted Kundan Gold Bezel Rim set into the jade orbital socket
  let bezelOuter = [
    [cx - 21, cy + 3], [cx - 10, cy - 11], [cx + 8, cy - 11],
    [cx + 22, cy - 1], [cx + 10, cy + 11], [cx - 8, cy + 11]
  ];
  washZone(bezelOuter, "#b88420", 255, 0.35);
  fillZone(bezelOuter, "#f0c456", 190, 0.06, 0.2, 0.15, 0.35);

  // Gold bezel rim shadow & highlight
  brush.set("one_hair", "#5e3e08", 0.65);
  drawPoly(bezelOuter, 0.35, true);
  brush.set("gold_pin", "#fff3b8", 0.7);
  brush.spline([[cx - 19, cy + 1], [cx - 9, cy - 10], [cx + 7, cy - 10], [cx + 19, cy - 1]], 0.35);

  // 2. Almond-shaped Cabochon Pigeon-Blood Ruby Eyeball
  let rubyOutline = [
    [cx - 16, cy + 2], [cx - 8, cy - 8], [cx + 6, cy - 8],
    [cx + 16, cy - 1], [cx + 8, cy + 8], [cx - 6, cy + 8]
  ];
  washZone(rubyOutline, "#7a091c", 255, 0.38);
  fillZone(rubyOutline, "#b8112b", 190, 0.08, 0.25, 0.15, 0.38);

  // Lower-right internal fiery ruby subsurface scattering
  let fieryGlow = [
    [cx - 4, cy + 1], [cx + 6, cy - 2], [cx + 13, cy],
    [cx + 7, cy + 6], [cx - 3, cy + 6]
  ];
  fillZone(fieryGlow, "#ff3856", 180, 0.1, 0.2, 0.08, 0.35);

  // Deep dark-ruby pupil core (gazing serenely left)
  let pupilPts = [];
  for (let a = 0; a < 360; a += 45) {
    pupilPts.push([cx - 2 + cos(a) * 5.2, cy + sin(a) * 5.2]);
  }
  washZone(pupilPts, "#260208", 250, 0.4);

  // Fine radial iris striations in glowing crimson & gold-pin
  brush.set("one_hair", "#ff5972", 0.45);
  for (let a = -60; a <= 140; a += 25) {
    brush.line(cx - 2 + cos(a) * 5.5, cy + sin(a) * 4.5, cx - 2 + cos(a) * 10, cy + sin(a) * 6.5);
  }

  // Crisp pinpoint white-gold specular window reflection on upper-left dome
  let glint1 = [[cx - 8, cy - 4], [cx - 3, cy - 5], [cx - 3, cy - 2], [cx - 8, cy - 1]];
  washZone(glint1, "#ffffff", 255, 0.15);
  brush.set("gold_pin", "#ffffff", 0.9);
  brush.line(cx - 7, cy - 3.5, cx - 3.5, cy - 4.2);
  // Secondary pinpoint catchlight
  brush.line(cx + 5, cy + 3, cx + 6.5, cy + 3);
}

function drawGoldStrap(pts, w) {
  let steps = 24;
  let upperEdge = [];
  let lowerEdge = [];
  let centerLine = [];

  for (let i = 0; i <= steps; i++) {
    let t = i / steps;
    let p = quadPt(pts[0], pts[1], pts[2], t);
    let pNext = quadPt(pts[0], pts[1], pts[2], min(1, t + 0.02));
    let ang = atan2(pNext[1] - p[1], pNext[0] - p[0]) + 90;
    let hw = w * 0.5;
    upperEdge.push([p[0] + cos(ang) * hw, p[1] + sin(ang) * hw]);
    lowerEdge.push([p[0] - cos(ang) * hw, p[1] - sin(ang) * hw]);
    centerLine.push(p);
  }

  let strapPoly = upperEdge.concat(lowerEdge.slice().reverse());

  // Cast shadow in the jade channel
  let shadowPoly = strapPoly.map(p => [p[0] + 1.2, p[1] + 1.8]);
  fillZone(shadowPoly, "#2b4233", 150, 0.06, 0.25, 0.15, 0.2);

  // Opaque burnished 24k gold base
  washZone(strapPoly, "#cfa032", 255, 0.2);
  fillZone(strapPoly, "#ecc050", 170, 0.06, 0.2, 0.1, 0.2);

  // Dark gold shadow border & bright gold wire edges
  brush.set("one_hair", "#6b470a", 0.65);
  brush.spline(upperEdge, 0.35);
  brush.spline(lowerEdge, 0.35);

  brush.set("gold_pin", "#fff2a8", 0.65);
  brush.spline(lowerEdge.map(p => [p[0] + 0.6, p[1] + 0.6]), 0.35);

  // Beaded gold wire granulation along both borders of the strap
  brush.set("gold_pin", "#fff7cc", 0.45);
  for (let i = 0; i <= steps; i++) {
    let u = upperEdge[i];
    let l = lowerEdge[i];
    brush.line(u[0] - 0.4, u[1], u[0] + 0.4, u[1]);
    brush.line(l[0] - 0.4, l[1], l[0] + 0.4, l[1]);
  }
}

function drawKundanGem(cx, cy, rx, ry, ang, type) {
  let isRuby = type.toLowerCase() === "ruby";
  let bezelPts = [];
  let gemPts = [];
  let glowPts = [];

  for (let a = 0; a < 360; a += 45) {
    let lx = cos(a) * (rx + 1.8);
    let ly = sin(a) * (ry + 1.8);
    let gx = cos(a) * rx;
    let gy = sin(a) * ry;
    let glx = cos(a) * (rx * 0.55) + rx * 0.18;
    let gly = sin(a) * (ry * 0.55) + ry * 0.18;

    bezelPts.push([
      cx + lx * cos(ang) - ly * sin(ang),
      cy + lx * sin(ang) + ly * cos(ang)
    ]);
    gemPts.push([
      cx + gx * cos(ang) - gy * sin(ang),
      cy + gx * sin(ang) + gy * cos(ang)
    ]);
    glowPts.push([
      cx + glx * cos(ang) - gly * sin(ang),
      cy + glx * sin(ang) + gly * cos(ang)
    ]);
  }

  // 1. Gold Kundan Bezel
  washZone(bezelPts, "#d9a536", 255, 0.35);
  brush.set("one_hair", "#6b4708", 0.5);
  drawPoly(bezelPts, 0.35, true);
  brush.set("gold_pin", "#fff2b2", 0.5);
  brush.line(bezelPts[4][0], bezelPts[4][1], bezelPts[6][0], bezelPts[6][1]);

  // 2. Cabochon Gem Body
  let baseCol = isRuby ? "#6e0819" : "#084528";
  let midCol = isRuby ? "#bf132e" : "#15804d";
  let glowCol = isRuby ? "#ff4766" : "#52e096";

  washZone(gemPts, baseCol, 255, 0.38);
  fillZone(gemPts, midCol, 195, 0.05, 0.2, 0.1, 0.38);
  washZone(glowPts, glowCol, 210, 0.35);

  // 3. Pinpoint White-Gold Specular Highlight on upper-left of cabochon
  let hx = cx - rx * 0.32;
  let hy = cy - ry * 0.32;
  brush.set("gold_pin", "#ffffff", 0.85);
  brush.line(hx - 0.8, hy, hx + 0.8, hy);
  brush.line(hx, hy - 0.6, hx, hy + 0.6);
}

function drawRoyalRosette(cx, cy, r) {
  // Gold scalloped base plate
  let platePts = [];
  for (let a = 0; a < 360; a += 30) {
    let rad = r + (a % 60 === 0 ? 1.5 : -0.5);
    platePts.push([cx + cos(a) * rad, cy + sin(a) * rad]);
  }
  washZone(platePts, "#c9962c", 255, 0.3);
  brush.set("one_hair", "#5e3d06", 0.55);
  drawPoly(platePts, 0.3, true);

  // 8 Teardrop Ruby Petals radiating around center
  for (let a = 0; a < 360; a += 45) {
    let px = cx + cos(a) * (r * 0.62);
    let py = cy + sin(a) * (r * 0.62);
    drawKundanGem(px, py, r * 0.28, r * 0.19, a, "ruby");
  }

  // Central Emerald or Ruby Cabochon Boss
  drawKundanGem(cx, cy, r * 0.32, r * 0.32, 0, "emerald");
}

function drawRubyPendant(x, y, s) {
  // Gold suspension ring
  brush.set("gold_pin", "#ffe282", 0.55);
  brush.line(x, y - 3, x, y + 1);
  // Teardrop ruby
  drawKundanGem(x, y + s, s * 0.65, s * 0.9, 0, "ruby");
  // Tiny seed pearl at bottom tip
  let py = y + s * 2.1;
  brush.set("gold_pin", "#f5efe0", 0.9);
  brush.line(x - 1, py, x + 1, py);
  brush.set("gold_pin", "#ffffff", 0.65);
  brush.line(x - 0.4, py - 0.4, x + 0.3, py - 0.4);
}

function drawNeckFloralInlay(cx, cy) {
  // Hair-thin inlaid gold wire stems on the jade neck
  let mainStem = [[cx, cy + 48], [cx - 4, cy + 16], [cx + 2, cy - 18]];
  let leftStem = [[cx - 2, cy + 22], [cx - 22, cy + 6], [cx - 28, cy - 12]];
  let rightStem = [[cx - 2, cy + 18], [cx + 20, cy + 4], [cx + 26, cy - 10]];

  for (let st of [mainStem, leftStem, rightStem]) {
    brush.set("one_hair", "#6e490a", 0.7);
    brush.spline(st.map(p => [p[0] + 0.8, p[1] + 0.8]), 0.45);
    brush.set("gold_pin", "#e3b23c", 0.8);
    brush.spline(st, 0.45);
    brush.set("gold_pin", "#fff2a8", 0.45);
    brush.spline(st.map(p => [p[0] - 0.4, p[1] - 0.4]), 0.45);
  }

  // Emerald leaves along the gold stems
  drawKundanGem(cx - 12, cy + 32, 4.2, 2.2, -35, "emerald");
  drawKundanGem(cx + 12, cy + 30, 4.2, 2.2, 35, "emerald");
  drawKundanGem(cx - 14, cy + 8, 3.8, 2.0, -45, "emerald");
  drawKundanGem(cx + 14, cy + 6, 3.8, 2.0, 45, "emerald");

  // Central 3-petalled Mughal Ruby Poppy Blossom at (cx + 2, cy - 22)
  drawKundanGem(cx + 2, cy - 26, 5.2, 3.6, -90, "ruby");
  drawKundanGem(cx - 6, cy - 22, 4.6, 3.1, -135, "ruby");
  drawKundanGem(cx + 10, cy - 22, 4.6, 3.1, -45, "ruby");
  drawKundanGem(cx + 2, cy - 18, 2.8, 2.8, 0, "emerald");

  // Flanking Ruby Buds
  drawKundanGem(cx - 28, cy - 14, 4.4, 2.8, -115, "ruby");
  drawKundanGem(cx + 26, cy - 12, 4.4, 2.8, -65, "ruby");

  // Gold lotus bract at base of floral spray
  drawKundanGem(cx, cy + 48, 3.6, 2.6, 0, "ruby");
}

function drawCheekTrefoilInlay(cx, cy) {
  let stem = [[cx + 14, cy + 12], [cx + 4, cy + 4], [cx - 6, cy - 4]];
  brush.set("gold_pin", "#d9a536", 0.7);
  brush.spline(stem, 0.4);
  brush.set("gold_pin", "#fff0a6", 0.4);
  brush.spline(stem, 0.4);

  drawKundanGem(cx - 8, cy - 6, 3.6, 2.4, -140, "ruby");
  drawKundanGem(cx - 2, cy - 11, 3.2, 2.1, -95, "emerald");
  drawKundanGem(cx - 11, cy + 1, 3.2, 2.1, 175, "emerald");
}

// 1950s Technicolor Melodrama — Extreme Close-Up Profile
// Rendered with p5.js v2 & p5.brush

const PROFILE_PTS = [
  { y: -20, x: 502 },
  { y: 0,   x: 495 },
  { y: 95,  x: 458 }, // Frontal eminence
  { y: 165, x: 452 }, // Supraorbital brow ridge
  { y: 225, x: 468 }, // Nasion (root of nose)
  { y: 360, x: 372 }, // Upper nasal dorsum
  { y: 500, x: 272 }, // Mid nasal bridge
  { y: 580, x: 212 }, // Supratip break
  { y: 628, x: 188 }, // Pronasale (nose tip)
  { y: 662, x: 198 }, // Infratip lobule
  { y: 692, x: 248 }, // Columella underside
  { y: 704, x: 315 }, // Subnasale
  { y: 770, x: 294 }, // Philtrum concavity
  { y: 835, x: 266 }, // Cupid's bow peak (labrale superius)
  { y: 888, x: 240 }, // Upper cherry-red lip prominence
  { y: 938, x: 274 }, // Upper lip inward curve
  { y: 954, x: 304 }, // Stomion (parted lip cleft)
  { y: 972, x: 282 }, // Lower lip upper rim
  { y: 1025, x: 254 }, // Lower cherry-red lip prominence
  { y: 1092, x: 298 }, // Lower vermilion border
  { y: 1138, x: 332 }, // Mentolabial sulcus (chin cleft dip)
  { y: 1200, x: 310 }, // Pogonion (chin curve)
  { y: 1220, x: 305 }
];

// Smooth piecewise Hermite/cosine interpolation for exact profile silhouette
function getProfileX(y) {
  if (y <= PROFILE_PTS[0].y) return PROFILE_PTS[0].x;
  if (y >= PROFILE_PTS[PROFILE_PTS.length - 1].y) return PROFILE_PTS[PROFILE_PTS.length - 1].x;
  for (let i = 0; i < PROFILE_PTS.length - 1; i++) {
    let p0 = PROFILE_PTS[i];
    let p1 = PROFILE_PTS[i + 1];
    if (y >= p0.y && y <= p1.y) {
      let t = (y - p0.y) / (p1.y - p0.y);
      // Smoothstep blend with slight sharpness at subnasale & stomion
      let isSharp = (p0.y === 692 || p0.y === 938 || p0.y === 954 || p0.y === 835);
      let s = isSharp ? (t * t * (3 - 2 * t)) : (0.5 - 0.5 * Math.cos(t * Math.PI));
      return p0.x + (p1.x - p0.x) * s;
    }
  }
  return 350;
}

// Helper for tear central spine X coordinate from y = 364 to y = 805
function getTearCenterX(y) {
  let t = constrain((y - 364) / (800 - 364), 0, 1);
  // Subtle organic curve over the malar prominence and down into the hollow
  return 574 + Math.sin(t * Math.PI * 1.65) * 11 - t * 14 + Math.sin(t * 9.0) * 1.8;
}

// Helper for tear half-width at any y along the track and terminal drop
function getTearHalfWidth(y) {
  if (y < 362 || y > 806) return 0;
  if (y < 395) {
    // Upper meniscus funneling from lower eyelid
    return map(y, 362, 395, 16, 5.5);
  } else if (y < 695) {
    // Narrow glistening rivulet down the cheek with slight beading modulation
    let base = map(y, 395, 695, 5.5, 7.5);
    let wave = Math.sin((y - 395) * 0.055) * 1.4;
    return base + wave;
  } else {
    // Swollen pendant teardrop (y: 695 to 806)
    let u = (y - 695) / (806 - 695); // 0 to 1
    // Teardrop profile: widens smoothly to a heavy belly at u = 0.68, then rounds at bottom
    if (u < 0.72) {
      let k = u / 0.72;
      return 7.5 + 21.5 * Math.pow(Math.sin(k * Math.PI * 0.5), 1.35);
    } else {
      let k = (u - 0.72) / 0.28;
      return 29.0 * Math.sqrt(Math.max(0, 1 - k * k));
    }
  }
}

async function setup() {
  createCanvas(1200, 1200, WEBGL);
  brush.scaleBrushes(3);
  angleMode(DEGREES);
  randomSeed(1955);
  noiseSeed(1955);

  // Custom brush for translucent dermal glazing & velvet transitions
  brush.add("dermal_glaze", {
    type: "default",
    weight: 16,
    scatter: 0.45,
    sharpness: 0.08,
    grain: 0.35,
    opacity: 16,
    spacing: 0.35,
    pressure: [0.3, 1.0, 0.3],
    noise: 0.3
  });

  // Custom brush for hyper-fine individual eyelashes, brow hairs & capillaries
  brush.add("lash_silk", {
    type: "default",
    weight: 1.35,
    scatter: 0.02,
    sharpness: 0.88,
    grain: 0.12,
    opacity: 210,
    spacing: 0.12,
    pressure: [1.35, 0.75, 0.04],
    noise: 0.18
  });

  // Custom brush for microscopic skin pores and translucent powder dust
  brush.add("powder_micro", {
    type: "spray",
    weight: 5.5,
    scatter: 2.2,
    opacity: 28,
    spacing: 0.65,
    pressure: [0.6, 1.0, 0.6],
    noise: 0.5
  });

  // Custom brush for wet specular reflections on tear and cherry lip
  brush.add("wet_gloss", {
    type: "default",
    weight: 2.6,
    scatter: 0.03,
    sharpness: 0.92,
    grain: 0.08,
    opacity: 235,
    spacing: 0.15,
    pressure: [0.2, 1.2, 0.2],
    noise: 0.1
  });
}

function draw() {
  translate(-width / 2, -height / 2);
  background("#031017");

  // 1. Deep Peacock Blue Heavy Velvet Background
  drawPeacockVelvetBackground();

  // 2. Watercolor & Wash Undertones of the Profile (Key Light, Rose Bloom, Teal Shadow)
  drawSkinWatercolorBase();

  // 3. Volumetric Coloured Pencil Modeling & Osteology Planes
  drawVolumetricSkinPlanes();

  // 4. Sculpted Nose, Nostril Wing & Alar Crease
  drawNoseAndNostril();

  // 5. Sliver of Glossy Cherry-Red Lip (The Piercing Monochrome Accent)
  drawGlossyCherryLips();

  // 6. Microscopic Skin Realism: Pores, Langer's Lines & Face Powder Grain
  drawMicroscopicPoresAndPowder();

  // 7. 1950s Glamour Eye in Profile, Iris Refraction, Wet Lashes & High Brow
  drawTechnicolorEyeAndBrow();

  // 8. Single Tear Tracing Mascara Down Cheek with Optical Lensing & Caustics
  drawMascaraTearAndLensing();

  // 9. Profile Rim Illumination, Vellus Peach Fuzz & Final Atmospheric Polish
  drawProfileRimAndFinalGlazes();

  noLoop();
}

// =============================================================================
// 1. DEEP PEACOCK BLUE VELVET BACKGROUND
// =============================================================================
function drawPeacockVelvetBackground() {
  brush.noStroke();

  // Deep hanging velvet folds in the left negative space
  const foldConfigs = [
    { x0: -20, x1: 110, col: "#041620", op: 180 },
    { x0: 75,  x1: 215, col: "#072636", op: 155 },
    { x0: 170, x1: 335, col: "#0b394e", op: 145 },
    { x0: 270, x1: 485, col: "#114f68", op: 135 },
    { x0: 350, x1: 540, col: "#186480", op: 115 }
  ];

  for (let f of foldConfigs) {
    brush.fill(f.col, f.op);
    brush.fillBleed(0.32, "out");
    brush.fillTexture(0.55, 0.25);
    brush.beginShape(0.35);
    for (let y = -20; y <= 1220; y += 80) {
      let sway = Math.sin(y * 0.0045 + f.x0 * 0.02) * 28;
      brush.vertex(f.x0 + sway, y);
    }
    for (let y = 1220; y >= -20; y -= 80) {
      let sway = Math.cos(y * 0.004 + f.x1 * 0.015) * 32;
      let limX = Math.min(f.x1 + sway, getProfileX(y) + 18);
      brush.vertex(limX, y);
    }
    brush.endShape(CLOSE);
  }
  brush.noFill();

  // Theatrical peacock-cyan glow halo just behind the profile silhouette
  for (let pass = 0; pass < 4; pass++) {
    let spread = 35 + pass * 38;
    let col = pass < 2 ? "#1e7794" : "#0e465c";
    brush.set("dermal_glaze", col, 2.2 + pass * 0.6);
    for (let y = 10; y < 1190; y += 14) {
      let px = getProfileX(y);
      let xStart = px - random(6, spread);
      let xEnd = px + random(-4, 6);
      if (xStart < xEnd) {
        brush.line(xStart, y + random(-6, 6), xEnd, y + random(-4, 4));
      }
    }
  }

  // Dense directional velvet nap & vertical drapery texture
  const velvetTones = ["#020b10", "#051924", "#092b3c", "#0f4257", "#175a73", "#227591"];
  for (let i = 0; i < 1100; i++) {
    let y = random(-10, 1210);
    let px = getProfileX(y);
    let x = random(-10, px + 4);
    let distToFace = px - x;

    // Brighter peacock sheen along fold ridges and near the profile rim
    let foldWave = Math.sin(x * 0.032 + Math.sin(y * 0.003) * 1.8);
    let idx = floor(map(foldWave + map(constrain(distToFace, 0, 260), 0, 260, 1.1, -0.6), -1.6, 2.1, 0, velvetTones.length));
    idx = constrain(idx, 0, velvetTones.length - 1);

    let len = random(28, 78);
    let ang = 88 + Math.sin(y * 0.005 + x * 0.01) * 7 + random(-4, 4);
    brush.set(random() < 0.65 ? "cpencil" : "charcoal", velvetTones[idx], random(0.45, 1.15));
    let x2 = x + cos(ang) * len;
    let y2 = y + sin(ang) * len;
    if (x2 < getProfileX(y2) + 4) {
      brush.line(x, y, x2, y2);
    }
  }

  // Subtle cross-woven velvet pile shimmer in the peacock highlights
  brush.set("2H", "#2e8ca8", 0.35);
  for (let i = 0; i < 320; i++) {
    let y = random(20, 1180);
    let px = getProfileX(y);
    let x = px - random(8, 120);
    if (x > 0) {
      brush.line(x, y, x - random(10, 26), y + random(-5, 5));
    }
  }
}

