  brush.beginShape(0.15);
  for (let y = -10; y <= 1210; y += 20) {
    brush.vertex(getProfileX(y), y);
  }
  brush.vertex(1220, 1210);
  brush.vertex(1220, -10);
  brush.endShape(CLOSE);
