// =============================================================================
// 3. VOLUMETRIC COLOURED PENCIL MODELING & FACIAL PLANES
// =============================================================================
function drawVolumetricSkinPlanes() {
  // Smooth dermal glazing passes to unify the watercolor layers before fine pencil work
  const glazeRegions = [
    // Warm sunlit malar highlight
    { xMin: 360, xMax: 610, yMin: 380, yMax: 680, col: "#fae0cc", count: 95, ang: -18 },
    // Rose blush transition across mid-cheek
    { xMin: 470, xMax: 790, yMin: 410, yMax: 810, col: "#cf7e88", count: 110, ang: -25 },
    // Cool celadon-teal halftone transition
    { xMin: 640, xMax: 960, yMin: 180, yMax: 1050, col: "#4c7d85", count: 120, ang: -35 },
    // Deep peacock-teal shadow side on right
    { xMin: 820, xMax: 1190, yMin: 20, yMax: 1190, col: "#173f4d", count: 130, ang: -48 },
    // Forehead warm key light to temple teal
    { xMin: 460, xMax: 720, yMin: 10, yMax: 190, col: "#f2cbb4", count: 70, ang: -8 },
    // Nasolabial & perioral warm-rose halftone
    { xMin: 310, xMax: 570, yMin: 690, yMax: 1180, col: "#d1938c", count: 85, ang: 28 }
  ];

  for (let reg of glazeRegions) {
    brush.set("dermal_glaze", reg.col, random(1.3, 2.1));
    for (let i = 0; i < reg.count; i++) {
      let y = random(reg.yMin, reg.yMax);
      let x = random(reg.xMin, reg.xMax);
      let px = getProfileX(y);
      if (x > px + 6) {
        let len = random(45, 110);
        let a = reg.ang + random(-14, 14);
        let x2 = x + cos(a) * len;
        let y2 = y + sin(a) * len;
        if (x2 > getProfileX(y2) + 6) {
          brush.line(x, y, x2, y2);
        }
      }
    }
  }

  // Dense, contoured coloured pencil hatching following the 3D surface topology of the face
  // We sample across the face and compute local surface illumination & curvature flow
  for (let i = 0; i < 3400; i++) {
    let y = random(5, 1195);
    let px = getProfileX(y);
    let x = random(px + 2, 1195);

    // Skip interior of eye aperture and cherry lips (rendered in dedicated layers)
    let inEye = (x > 495 && x < 735 && y > 285 && y < 368);
    let inLips = (x < 495 && y > 832 && y < 1098 && x < px + map(y, 832, 1098, 220, 185));
    if (inEye || inLips) continue;

    // Normalized horizontal distance from profile edge
    let dProfile = x - px;

    // Compute volumetric lighting fields:
    // 1. Key light intensity (strongest near profile edge, nose bridge, upper cheekbone, forehead, chin)
    let cheekDist = dist(x, y, 495, 515);
    let foreheadDist = dist(x, y, 535, 95);
    let chinDist = dist(x, y, 395, 1175);
    let noseBridgeFactor = (y > 225 && y < 650 && dProfile < 115) ? map(dProfile, 0, 115, 0.95, 0) : 0;

    let keyLight =
       noseBridgeFactor +
      constrain(map(cheekDist, 0, 240, 0.85, 0), 0, 0.85) +
      constrain(map(foreheadDist, 0, 210, 0.75, 0), 0, 0.75) +
      constrain(map(chinDist, 0, 150, 0.65, 0), 0, 0.65) +
      constrain(map(dProfile, 0, 95, 0.55, 0), 0, 0.55);

    // 2. Rose bloom field (concentrated on malar arch, cheek apple, nose tip, upper orbit)
    let roseDist = dist(x, y, 615, 575);
    let noseTipDist = dist(x, y, 255, 635);
    let roseFactor =
      constrain(map(roseDist, 0, 255, 0.9, 0), 0, 0.9) +
      constrain(map(noseTipDist, 0, 110, 0.7, 0), 0, 0.7);

    // 3. Teal shadow field (increases toward right side of canvas, under-eye hollow, subnasale, jaw)
    let tealFactor =
      constrain(map(x, 620, 1150, 0.0, 1.0), 0, 1.0) +
      constrain(map(dist(x, y, 610, 395), 0, 95, 0.35, 0), 0, 0.35) +
      constrain(map(dist(x, y, 560, 1040), 0, 220, 0.45, 0), 0, 0.45);

    // Choose coloured pencil pigment based on local light/rose/teal balance
    let col;
    if (tealFactor > 0.72) {
      const darkTeals = ["#0b222c", "#12313f", "#1b4352", "#265564"];
      col = random(darkTeals);
    } else if (tealFactor > 0.42 && keyLight < 0.48) {
      const midTeals = ["#2f5f6b", "#3f727d", "#55878f", "#6e9ba0", "#5f6e78"];
      col = random(midTeals);
    } else if (roseFactor > 0.48 && keyLight < 0.92) {
      const roseTones = ["#9e5562", "#b56773", "#c97a83", "#db8f95", "#e6a6a8"];
      col = random(roseTones);
    } else if (keyLight > 0.75) {
      const highKeyTones = ["#f2cbb4", "#f7d9c4", "#fce6d4", "#fff2e6", "#ebd1c2"];
      col = random(highKeyTones);
    } else {
      const warmMidTones = ["#c79286", "#d6a394", "#e3b5a4", "#b8827a", "#9c7878"];
      col = random(warmMidTones);
    }

    // Determine anatomical contour stroke angle so strokes wrap around the 3D form
    let strokeAngle = 0;
    if (y < 225) {
      // Forehead wraps gently across frontal bone into temple
      strokeAngle = map(x, px, 1150, -12, 22);
    } else if (y < 680 && dProfile < 145) {
      // Nasal dorsum and sidewall contour lines follow bridge angle (~54 deg) or cross-wrap (~-28 deg)
      strokeAngle = random() < 0.65 ? 124 : -26;
    } else if (y > 380 && y < 880 && x > 380 && x < 880) {
      // Malar cheekbone: curved concentric arcs wrapping around the apple of the cheek
      let dx = x - 535;
      let dy = y - 515;
      strokeAngle = atan2(dy, dx) + 90 + random(-18, 18);
    } else {
      // Lateral cheek & jaw sweep downward toward neck/chin
      strokeAngle = 62 + random(-20, 20);
    }

    let segLen = random(14, 34);
    let x1 = x - cos(strokeAngle) * segLen * 0.5;
    let y1 = y - sin(strokeAngle) * segLen * 0.5;
    let x2 = x + cos(strokeAngle) * segLen * 0.5;
    let y2 = y + sin(strokeAngle) * segLen * 0.5;

    if (x1 > getProfileX(y1) + 2 && x2 > getProfileX(y2) + 2) {
      let bName = random() < 0.78 ? "cpencil" : "2H";
      brush.set(bName, col, random(0.32, 0.72));
      // Slight curved spline for organic hand-drawn pencil feel
      let xm = (x1 + x2) * 0.5 + cos(strokeAngle + 90) * random(-3.5, 3.5);
      let ym = (y1 + y2) * 0.5 + sin(strokeAngle + 90) * random(-3.5, 3.5);
      brush.spline([[x1, y1, 0.4], [xm, ym, 0.95], [x2, y2, 0.4]], 0.35);
    }
  }

  // Subtle nasolabial fold & perioral muscle modeling (from nostril wing 415,682 toward 535,950)
  for (let i = 0; i < 160; i++) {
    let t = random(0, 1);
    let fx = lerp(412, 535, t) + Math.sin(t * Math.PI) * 18 + random(-18, 18);
    let fy = lerp(680, 955, t) + random(-12, 12);
    let col = fx < lerp(412, 535, t) + 12 ? "#8c5660" : "#f2cab6";
    brush.set("cpencil", col, random(0.35, 0.65));
    brush.line(fx, fy, fx + random(6, 16), fy + random(14, 28));
  }
}

// =============================================================================
// 4. SCULPTED NOSE, NOSTRIL WING & ALAR CREASE
// =============================================================================
function drawNoseAndNostril() {
  brush.noStroke();

  // Nostril aperture (deep velvet shadow inside the nostril)
  brush.fill("#0c090d", 230);
  brush.fillBleed(0.08, "in");
  brush.beginShape(0.35);
  brush.vertex(238, 678);
  brush.vertex(275, 662);
  brush.vertex(332, 668);
  brush.vertex(356, 682);
  brush.vertex(318, 692);
  brush.vertex(258, 688);
  brush.endShape(CLOSE);

  // Warm subsurface red-umber glow at the anterior rim of the nostril
  brush.fill("#4a1520", 160);
  brush.fillBleed(0.15, "out");
  brush.beginShape(0.3);
  brush.vertex(228, 672);
  brush.vertex(278, 656);
  brush.vertex(345, 665);
  brush.vertex(368, 685);
  brush.vertex(340, 674);
  brush.vertex(265, 672);
  brush.endShape(CLOSE);
  brush.noFill();

  // Alar crease (curved shadow tucking behind the nostril wing around x: 375..418, y: 635..695)
  const alarPts = [
    [355, 618, 0.3],
    [396, 642, 0.9],
    [414, 672, 1.1],
    [398, 696, 0.8],
    [362, 702, 0.3]
  ];
  brush.set("2B", "#3b232b", 0.95);
  brush.spline(alarPts, 0.45);
  brush.set("cpencil", "#6e424c", 1.35);
  brush.spline(alarPts, 0.45);

  // Teal reflected shadow under the nostril wing and columella
  for (let i = 0; i < 95; i++) {
    let t = random(0, 1);
    let x = lerp(240, 405, t) + random(-8, 8);
    let y = lerp(682, 698, t) + random(-6, 10);
    if (x > getProfileX(y) + 1) {
      let col = random(["#1f3e4a", "#385c66", "#5c3b44", "#24161c"]);
      brush.set("cpencil", col, random(0.35, 0.65));
      brush.line(x, y, x + random(8, 18), y + random(-3, 5));
    }
  }

  // Luminous golden-ivory highlight strip down the nasal dorsum and rounded pronasale tip
  for (let i = 0; i < 180; i++) {
    let y = random(235, 648);
    let px = getProfileX(y);
    let d = random(2, 28);
    let x = px + d;
    let col = d < 12 ? "#fff5eb" : (d < 20 ? "#fae2ce" : "#e8bda8");
    brush.set("cpencil", col, random(0.35, 0.68));
    // Follow the angle of the nasal bridge
    brush.line(x, y, x - random(5, 13), y + random(8, 18));
  }

  // Soft spherical highlight on the ball of the nose tip (208, 622) and nostril wing (345, 648)
  for (let i = 0; i < 90; i++) {
    let a = random(0, 360);
    let r = random(2, 24);
    let tx = 216 + cos(a) * r;
    let ty = 624 + sin(a) * r * 0.85;
    if (tx > getProfileX(ty) + 2) {
      brush.set("2H", r < 11 ? "#fff8f0" : "#f7d5c0", random(0.3, 0.55));
      brush.line(tx, ty, tx + cos(a + 90) * 8, ty + sin(a + 90) * 8);
    }

    let wx = 342 + cos(a) * r * 1.1;
    let wy = 648 + sin(a) * r * 0.75;
    brush.set("2H", r < 10 ? "#fae0cc" : "#d99898", random(0.3, 0.55));
    brush.line(wx, wy, wx + cos(a + 90) * 9, wy + sin(a + 90) * 7);
  }
}

// =============================================================================
// 5. SLIVER OF GLOSSY CHERRY-RED LIP (THE MONOCHROME ACCENT)
// =============================================================================
function drawGlossyCherryLips() {
  brush.noStroke();

  // Define exact anatomical boundaries for Upper Lip and Lower Lip in profile
  // Upper Lip: Cupid's bow peak (266, 835) -> front bulge (240, 888) -> stomion (304, 954) -> mouth corner (488, 974)
  const upperLipPoly = [
    [266, 835], [248, 860], [240, 888], [249, 916], [274, 938],
    [304, 954], [365, 962], [430, 969], [488, 974],
    [435, 922], [372, 878], [312, 848]
  ];

  // Lower Lip: Stomion (304, 954) -> upper rim (282, 972) -> plump bulge (254, 1025) -> lower border (298, 1092) -> corner (488, 974)
  const lowerLipPoly = [
    [282, 972], [262, 996], [254, 1025], [264, 1058], [298, 1092],
    [358, 1078], [418, 1042], [462, 1004], [488, 974],
    [422, 973], [355, 968], [304, 954]
  ];

  // 1. Base opaque cherry-red wash so the lips glow with pure Technicolor saturation
  brush.wash("#9e081c", 230);
  brush.beginShape(0.22);
  for (let p of upperLipPoly) brush.vertex(Math.max(p[0], getProfileX(p[1])), p[1]);
  brush.endShape(CLOSE);

  brush.wash("#bf0d25", 230);
  brush.beginShape(0.22);
  for (let p of lowerLipPoly) brush.vertex(Math.max(p[0], getProfileX(p[1])), p[1]);
  brush.endShape(CLOSE);
  brush.noWash();

  // 2. Watercolor bleed layers for velvety depth and subsurface crimson bloom
  brush.fill("#e61530", 150);
  brush.fillBleed(0.16, "out");
  brush.fillTexture(0.45, 0.3);
  brush.beginShape(0.25);
  for (let p of lowerLipPoly) brush.vertex(Math.max(p[0], getProfileX(p[1])), p[1]);
  brush.endShape(CLOSE);

  brush.fill("#730412", 165);
  brush.fillBleed(0.14, "in");
  brush.beginShape(0.25);
  for (let p of upperLipPoly) brush.vertex(Math.max(p[0], getProfileX(p[1])), p[1]);
  brush.endShape(CLOSE);
  brush.noFill();

  // 3. Cylindrical contoured coloured pencil strokes following the lip pillows (sulci)
  // Upper Lip contour strokes
  for (let i = 0; i < 360; i++) {
    let t = random(0, 1); // along mouth from front (0) to corner (1)
    let xTop = lerp(266, 485, t);
    let yTop = lerp(835, 972, Math.pow(t, 0.88));
    let xBot = lerp(290, 488, t);
    let yBot = lerp(950, 974, Math.pow(t, 0.92));

    // Bulge out to the left near the front profile
    let bulge = (1 - t) * 32;
    let xm = (xTop + xBot) * 0.5 - bulge;
    let ym = (yTop + yBot) * 0.5;

    // Color gradation: bright scarlet at front upper rim, deep ruby-black toward inner cleft & corner
    let col;
    if (t < 0.28) {
      col = random(["#ff2e47", "#eb142e", "#c70a21", "#ff596c"]);
    } else if (t < 0.65) {
      col = random(["#a8071b", "#820414", "#cc0e26", "#5c020d"]);
    } else {
      col = random(["#47020a", "#2b0106", "#660410"]);
    }

    brush.set("cpencil", col, random(0.38, 0.78));
    let sx1 = Math.max(xTop, getProfileX(yTop) + 1);
    let sxm = Math.max(xm, getProfileX(ym) + 1);
    let sx2 = Math.max(xBot, getProfileX(yBot) + 1);
    brush.spline([[sx1, yTop, 0.4], [sxm, ym, 1.0], [sx2, yBot, 0.5]], 0.4);
  }

  // Lower Lip contour strokes (plump, luscious, catching intense key light)
  for (let i = 0; i < 420; i++) {
    let t = random(0, 1);
    let xTop = lerp(285, 486, t);
    let yTop = lerp(962, 974, t);
    let xBot = lerp(298, 486, t);
    let yBot = lerp(1092, 976, Math.pow(t, 0.82));

    let bulge = (1 - t) * 38;
    let xm = (xTop + xBot) * 0.5 - bulge;
    let ym = (yTop + yBot) * 0.5;

    let col;
    if (t < 0.35) {
      col = random(["#ff3850", "#ff1f3a", "#e01029", "#ff6b7d", "#b8081e"]);
    } else if (t < 0.72) {
      col = random(["#c40c22", "#960618", "#700311", "#eb1730"]);
    } else {
      col = random(["#4f020b", "#300107", "#750513"]);
    }

    brush.set("cpencil", col, random(0.4, 0.82));
    let sx1 = Math.max(xTop, getProfileX(yTop) + 1);
    let sxm = Math.max(xm, getProfileX(ym) + 1);
    let sx2 = Math.max(xBot, getProfileX(yBot) + 1);
    brush.spline([[sx1, yTop, 0.5], [sxm, ym, 1.1], [sx2, yBot, 0.4]], 0.45);
  }

  // 4. Deep velvet shadow in the parted mouth cleft (stomion) & hint of wet pearl tooth
  brush.noStroke();
  brush.wash("#140104", 240);
  brush.beginShape(0.25);
  brush.vertex(284, 945);
  brush.vertex(345, 950);
  brush.vertex(430, 964);
  brush.vertex(492, 975);
  brush.vertex(425, 974);
  brush.vertex(340, 968);
  brush.vertex(292, 966);
  brush.endShape(CLOSE);

  // Subtle glint of a wet upper incisor edge inside the parted lips
  brush.wash("#d9d0cb", 165);
  brush.beginShape(0.2);
  brush.vertex(312, 952);
  brush.vertex(348, 954);
  brush.vertex(344, 962);
  brush.vertex(310, 960);
  brush.endShape(CLOSE);
  brush.noWash();

  // Dark contour line along stomion & mouth corner (cheilion dimple)
  brush.set("2B", "#1a0105", 1.1);
  brush.spline([
    [282, 946, 0.6],
    [340, 956, 1.1],
    [418, 968, 1.0],
    [492, 975, 0.8],
    [508, 982, 0.2]
  ], 0.35);

  // 5. Crisp Cupid's bow white-gold ridge highlight (milk-line above upper vermilion border)
  for (let i = 0; i < 45; i++) {
    let t = random(0, 0.85);
    let x1 = lerp(267, 455, t);
    let y1 = lerp(833, 945, Math.pow(t, 0.88)) - random(1, 5);
    let x2 = lerp(267, 455, t + 0.12);
    let y2 = lerp(833, 945, Math.pow(t + 0.12, 0.88)) - random(1, 5);
    brush.set("2H", t < 0.4 ? "#fff7ed" : "#f5cdb8", random(0.4, 0.75));
    brush.line(x1, y1, x2, y2);
  }

  // 6. High-gloss 1950s wet lacquer specular highlights across both lips
  // Lower lip main specular ribbon (broken by vertical lip creases for hyperrealism)
  for (let i = 0; i < 85; i++) {
    let t = random(0.02, 0.58);
    let cx = lerp(262, 415, t);
    let cy = lerp(1012, 1018, t) + Math.sin(t * Math.PI) * 14 + random(-8, 8);
    let hLen = random(8, 22);
    let isCore = (t < 0.38 && abs(cy - (lerp(1012, 1018, t) + Math.sin(t * Math.PI) * 14)) < 5);
    let col = isCore ? "#ffffff" : (random() < 0.5 ? "#ffd9e0" : "#ff8da1");
    brush.set("wet_gloss", col, isCore ? random(0.55, 1.05) : random(0.35, 0.65));
    // Vertical/curved micro-facets following lip creases
    brush.line(cx, cy - hLen * 0.45, cx - random(2, 7), cy + hLen * 0.55);
  }

  // Upper lip glossy specular highlight along its anterior curve (x: 245..335, y: 868..918)
  for (let i = 0; i < 55; i++) {
    let t = random(0.02, 0.45);
    let cx = lerp(246, 345, t);
    let cy = lerp(878, 918, t) + random(-6, 6);
    let col = t < 0.25 ? "#ffffff" : "#ffc7d1";
    brush.set("wet_gloss", col, random(0.35, 0.8));
    brush.line(cx, cy - random(4, 10), cx - random(2, 6), cy + random(4, 10));
  }

  // Pin-prick wet diamond glints on the cherry lip gloss
  const lipGlints = [
    [264, 1014], [276, 1022], [292, 1026], [312, 1028], [334, 1025],
    [250, 884], [262, 892], [278, 902], [298, 956], [322, 964]
  ];
  for (let g of lipGlints) {
    brush.set("rotring", "#ffffff", 0.9);
    brush.line(g[0] - 3, g[1], g[0] + 3, g[1]);
    brush.line(g[0], g[1] - 3, g[0], g[1] + 3);
  }
}

// =============================================================================
// 6. MICROSCOPIC SKIN REALISM: PORES, LANGER'S LINES & POWDER GRAIN
// =============================================================================
function drawMicroscopicPoresAndPowder() {
  // 1. Loose 1950s Velvet Face Powder Spray Pass (warm ivory in key light, cool celadon in shadow)
  for (let i = 0; i < 160; i++) {
    let y = random(30, 1170);
    let px = getProfileX(y);
    let x = random(px + 12, 1150);
    if (x > 490 && x < 750 && y > 260 && y < 375) continue; // skip eye
    if (x < 500 && y > 830 && y < 1100) continue; // skip lips

    let col = x < 620 ? "#fce3cf" : (x < 820 ? "#d99ea2" : "#4b7b85");
    brush.set("powder_micro", col, random(0.7, 1.4));
    brush.line(x, y, x + random(15, 45), y + random(-15, 15));
  }

  // 2. Microscopic Dermal Pores & Rhomboid Skin Micro-Relief (Langer's lines)
  // Concentrated on nose tip/wing, malar cheek prominence, forehead, and chin
  for (let i = 0; i < 2600; i++) {
    // Bias distribution toward high-focus cheek, nose, and brow zones
    let zone = random();
    let x, y;
    if (zone < 0.58) {
      // Cheek & malar zone
      x = random(355, 860);
      y = random(385, 920);
    } else if (zone < 0.78) {
      // Nose bridge, tip & wing
      y = random(340, 695);
      let px = getProfileX(y);
      x = px + random(4, 155);
    } else if (zone < 0.90) {
      // Forehead & glabella
      y = random(20, 220);
      let px = getProfileX(y);
      x = px + random(4, 340);
    } else {
      // Philtrum & chin
      y = random(705, 1190);
      let px = getProfileX(y);
      x = px + random(4, 240);
    }

    let px = getProfileX(y);
    if (x <= px + 3) continue;
    if (x < 505 && y > 830 && y < 1105) continue; // skip lips
    if (x > 485 && x < 765 && y > 245 && y < 380) continue; // skip eye

    // Also skip interior of the tear track so the liquid lens remains smooth over the pores
    let tearCX = getTearCenterX(y);
    let tearHW = getTearHalfWidth(y);
    if (tearHW > 0 && abs(x - tearCX) < tearHW * 0.7) continue;

    // Pore orientation stretches slightly along cheek contour
    let poreAng = 25 + (x - 450) * 0.06 + random(-15, 15);
    let poreSize = random(1.4, 3.2);

    // Upper-left micro-shadow pit of the pore
    let shadowCol;
    if (x > 740) {
      shadowCol = random(["#0f2d38", "#1c4352", "#2b5663"]);
    } else if (x > 530 && y > 430 && y < 780) {
      shadowCol = random(["#7d3e49", "#944f5a", "#66404a"]);
    } else {
      shadowCol = random(["#9e685e", "#b37b70", "#875750"]);
    }

    brush.set("2H", shadowCol, random(0.22, 0.42));
    brush.line(
      x, y,
      x + cos(poreAng) * poreSize,
      y + sin(poreAng) * poreSize
    );

    // Lower-right micro-rim highlight of the pore (catching raking key light + powder grain)
    if (x < 820 && random() < 0.78) {
      let hiCol = x < 580 ? "#fff5e8" : (x < 710 ? "#f5cbd0" : "#78a6b0");
      brush.set("2H", hiCol, random(0.2, 0.36));
      let hx = x + cos(poreAng + 65) * 1.6;
      let hy = y + sin(poreAng + 65) * 1.6;
      brush.line(hx, hy, hx + cos(poreAng) * (poreSize * 0.85), hy + sin(poreAng) * (poreSize * 0.85));
    }

    // Faint rhomboid micro-sulcus connecting adjacent pores (skin triangle network)
    if (random() < 0.28) {
      brush.set("2H", shadowCol, 0.16);
      let diagAng = poreAng + (random() < 0.5 ? 52 : -52);
      brush.line(x, y, x + cos(diagAng) * random(4, 8), y + sin(diagAng) * random(4, 8));
    }
  }

  // 3. Individual Microscopic Face Powder Granules clinging to skin surface
  for (let i = 0; i < 1400; i++) {
    let y = random(35, 1185);
    let px = getProfileX(y);
    let x = px + random(2, 680 * Math.pow(random(), 1.4));
    if (x > 1190) continue;
    if (x < 505 && y > 830 && y < 1105) continue;
    if (x > 485 && x < 765 && y > 245 && y < 380) continue;

    let col;
    if (x - px < 45) {
      col = random(["#fffaf2", "#ffeedb", "#fae0c8"]);
    } else if (x < 640) {
      col = random(["#fce6d4", "#f5cebe", "#ebd2c5"]);
    } else {
      col = random(["#8bb3bd", "#6a95a0", "#d49ca2"]);
    }

    brush.set("rotring", col, random(0.22, 0.45));
    brush.line(x, y, x + random(-1.5, 1.5), y + random(-1.5, 1.5));
  }
}

// =============================================================================
// 7. 1950s GLAMOUR EYE IN PROFILE, IRIS, WET LASHES & ARCHED BROW
// =============================================================================
function drawTechnicolorEyeAndBrow() {
  // ---------------------------------------------------------------------------
  // A. Iridescent Peacock-Turquoise 1950s Eyeshadow & Supratarsal Crease
  // ---------------------------------------------------------------------------
  brush.noStroke();

  // Frosted peacock-teal eyeshadow wash over the mobile upper eyelid
  brush.fill("#164c5e", 145);
  brush.fillBleed(0.22, "out");
  brush.fillTexture(0.5, 0.25);
  brush.beginShape(0.3);
  brush.vertex(492, 290);
  brush.vertex(545, 242);
  brush.vertex(635, 240);
  brush.vertex(735, 285);
  brush.vertex(770, 328);
  brush.vertex(715, 344);
  brush.vertex(595, 305);
  brush.endShape(CLOSE);

  // Shimmering seafoam-turquoise highlight on the center of the upper eyelid ball
  brush.fill("#3d92a6", 110);
  brush.fillBleed(0.25, "out");
  brush.beginShape(0.3);
  brush.vertex(505, 285);
  brush.vertex(555, 252);
  brush.vertex(625, 260);
  brush.vertex(645, 308);
  brush.vertex(545, 296);
  brush.endShape(CLOSE);
  brush.noFill();

  // Coloured pencil modeling of the upper eyelid fold (supratarsal crease) & lower tear trough
  for (let i = 0; i < 240; i++) {
    let t = random(0, 1);
    // Upper eyelid crease curve: (490, 232) -> (615, 224) -> (775, 322)
    let cx = lerp(490, 775, t);
    let cy = lerp(232, 322, t) - Math.sin(t * Math.PI) * 34 + random(-18, 28);
    let dCrease = cy - (lerp(232, 322, t) - Math.sin(t * Math.PI) * 34);

    let col;
    if (abs(dCrease) < 5) {
      col = random(["#1c1118", "#0d2936", "#361c26"]); // deep socket fold
    } else if (dCrease > 0) {
      // Mobile eyelid below crease: shimmering peacock turquoise & silver-teal
      col = random(["#1a5669", "#2c758a", "#4ca0b5", "#76c2d4", "#123a47"]);
    } else {
      // Brow bone above crease: warm rose-champagne & alabaster highlight
      col = random(["#cfa098", "#ebC5B5", "#fae2d2", "#9e6770"]);
    }

    brush.set("cpencil", col, random(0.35, 0.72));
    let ang = map(t, 0, 1, -12, 32) + random(-8, 8);
    brush.line(cx, cy, cx + cos(ang) * random(10, 22), cy + sin(ang) * random(10, 22));
  }

  // Emphasize the sharp supratarsal crease line
  brush.set("2B", "#1d141b", 0.95);
  brush.spline([
    [488, 238, 0.3],
    [555, 220, 1.0],
    [645, 236, 1.1],
    [725, 282, 0.8],
    [782, 324, 0.2]
  ], 0.4);

  // ---------------------------------------------------------------------------
  // B. Eyeball in Profile: Corneal Bulge, Foreshortened Iris, Pupil & Sclera
  // ---------------------------------------------------------------------------
  brush.noStroke();

  // 1. Sclera & Corneal Dome base shape
  // Front of cornea bulges out at (502, 326); outer corner tapers to (715, 344)
  const eyeAperture = [
    [504, 296], [538, 292], [595, 298], [658, 316], [715, 344],
    [655, 355], [588, 362], [532, 362], [506, 354], [500, 326]
  ];

  brush.wash("#9ab6bf", 240);
  brush.beginShape(0.28);
  for (let p of eyeAperture) brush.vertex(p[0], p[1]);
  brush.endShape(CLOSE);

  // Shaded sclera (cool blue-teal shadow under upper lashes, warm pink-ivory near lower rim)
  brush.fill("#4d6e7a", 150);
  brush.fillBleed(0.12, "in");
  brush.beginShape(0.25);
  brush.vertex(565, 296);
  brush.vertex(658, 316);
  brush.vertex(715, 344);
  brush.vertex(645, 342);
  brush.vertex(568, 325);
  brush.endShape(CLOSE);

  brush.fill("#dcebed", 170);
  brush.fillBleed(0.10, "in");
  brush.beginShape(0.25);
  brush.vertex(565, 322);
  brush.vertex(648, 330);
  brush.vertex(690, 346);
  brush.vertex(640, 356);
  brush.vertex(568, 358);
  brush.endShape(CLOSE);
  brush.noFill();

  // Scleral spherical shading & delicate red episcleral blood capillaries
  for (let i = 0; i < 85; i++) {
    let sx = random(568, 705);
    let sy = random(304, 356);
    let col = sy < 328 ? "#527480" : (sx > 665 ? "#9c6d75" : "#e3f0f2");
    brush.set("2H", col, random(0.3, 0.55));
    brush.line(sx, sy, sx + random(6, 14), sy + random(-2, 4));
  }

  // Fine branching blood vessels in the outer sclera (redness from crying)
  const vessels = [
    [[702, 343, 0.7], [676, 340, 0.5], [652, 344, 0.3], [634, 341, 0.1]],
    [[692, 346, 0.6], [668, 350, 0.4], [642, 348, 0.15]],
    [[680, 332, 0.5], [655, 328, 0.3], [632, 331, 0.1]]
  ];
  for (let v of vessels) {
    brush.set("lash_silk", "#b84656", 0.32);
    brush.spline(v, 0.4);
  }

  // 2. Aqueous Corneal Bulge (protruding transparent dome on the left: x: 500..532, y: 296..358)
  brush.noStroke();
  brush.wash("#b5d8e0", 185);
  brush.beginShape(0.35);
  brush.vertex(518, 294);
  brush.vertex(503, 308);
  brush.vertex(499, 326);
  brush.vertex(504, 346);
  brush.vertex(518, 359);
  brush.vertex(532, 345);
  brush.vertex(532, 310);
  brush.endShape(CLOSE);

  // 3. Foreshortened Iris Ellipse (center: 544, 327; rx: 28, ry: 32)
  const irisCX = 544;
  const irisCY = 327;
  const irisRX = 27;
  const irisRY = 32;

  // Dark limbal ring of iris
  brush.wash("#071e26", 245);
  brush.beginShape(0.35);
  for (let a = 0; a < 360; a += 20) {
    brush.vertex(irisCX + cos(a) * irisRX, irisCY + sin(a) * irisRY);
  }
  brush.endShape(CLOSE);
  brush.noWash();

  // Radial iris stroma fibers (peacock blue-green, slate cyan, and warm gold collarette)
  for (let i = 0; i < 240; i++) {
    let a = random(0, 360);
    let rIn = random(0.24, 0.45);
    let rOut = random(0.68, 0.96);
    let x1 = irisCX + cos(a) * irisRX * rIn;
    let y1 = irisCY + sin(a) * irisRY * rIn;
    let x2 = irisCX + cos(a + random(-6, 6)) * irisRX * rOut;
    let y2 = irisCY + sin(a + random(-6, 6)) * irisRY * rOut;

    // Lower-left side of iris catches warm golden-cyan internal caustic refraction!
    let isLitSide = (a > 60 && a < 230);
    let col;
    if (rIn < 0.35 && random() < 0.45) {
      col = random(["#d49b52", "#e8b86d", "#8ca878"]); // warm amber pupillary ring
    } else if (isLitSide) {
      col = random(["#3ea2b5", "#5ec2d4", "#26788a", "#8ce0ed"]);
    } else {
      col = random(["#0c2d38", "#164657", "#1f5c70", "#081c24"]);
    }

    brush.set("2H", col, random(0.28, 0.55));
    brush.line(x1, y1, x2, y2);
  }

  // 4. Deep Velvet-Black Pupil (shifted forward toward corneal dome: center 533, 327)
  brush.noStroke();
  brush.wash("#030608", 255);
  brush.beginShape(0.35);
  for (let a = 0; a < 360; a += 24) {
    brush.vertex(533 + cos(a) * 11.5, 327 + sin(a) * 17.5);
  }
  brush.endShape(CLOSE);
  brush.noWash();

  // ---------------------------------------------------------------------------
  // C. Wet Lower Waterline, Pooled Tear Meniscus & Corneal Catchlights
  // ---------------------------------------------------------------------------
  // Glistening pink-coral lower waterline rim from (506, 356) to (715, 344)
  for (let i = 0; i < 75; i++) {
    let t = random(0, 1);
    let wx = lerp(506, 712, t);
    let wy = lerp(356, 344, t) + Math.sin(t * Math.PI) * 8 + random(-2.5, 2.5);
    let col = random(["#d97580", "#f09aa2", "#b04e59", "#fae0e2"]);
    brush.set("cpencil", col, random(0.35, 0.65));
    brush.line(wx, wy, wx + random(6, 14), wy + random(-2, 2));
  }

  // Pooled tear fluid meniscus along the lower eyelid margin (catching brilliant white light)
  brush.set("wet_gloss", "#ffffff", 0.95);
  brush.spline([
    [508, 355, 0.5],
    [555, 362, 1.3],
    [605, 361, 1.2],
    [658, 354, 0.8],
    [705, 345, 0.3]
  ], 0.35);

  brush.set("wet_gloss", "#bfeef5", 0.65);
  brush.spline([
    [512, 358, 0.4],
    [565, 365, 1.1],
    [618, 363, 1.0],
    [672, 355, 0.5]
  ], 0.35);

  // Studio Window Specular Reflection on the curved Corneal Dome!
  // Main curved windowpane highlight on upper-left cornea (x: 503..532, y: 303..325)
  brush.noStroke();
  brush.wash("#ffffff", 245);
  brush.beginShape(0.2);
  brush.vertex(504, 314);
  brush.vertex(513, 303);
  brush.vertex(529, 305);
  brush.vertex(525, 319);
  brush.vertex(508, 323);
  brush.endShape(CLOSE);

  // Secondary windowpane reflection just below window mullion
  brush.wash("#fff9f0", 220);
  brush.beginShape(0.2);
  brush.vertex(503, 327);
  brush.vertex(522, 324);
  brush.vertex(520, 333);
  brush.vertex(504, 335);
  brush.endShape(CLOSE);
  brush.noWash();

  // Extra crisp white catchlight glints on the cornea and tear meniscus
  brush.set("wet_gloss", "#ffffff", 1.15);
  brush.line(507, 308, 526, 307);
  brush.line(505, 315, 523, 315);
  brush.line(568, 362, 588, 363);

  // ---------------------------------------------------------------------------
  // D. Bold 1950s Winged Liquid Eyeliner & Mascara-Clumped Eyelashes
  // ---------------------------------------------------------------------------
  // Jet-black winged eyeliner along the upper lash line: (496, 294) -> (715, 344) -> flick (768, 325)
  brush.noStroke();
  brush.wash("#05080c", 250);
  brush.beginShape(0.25);
  brush.vertex(495, 294);
  brush.vertex(548, 282);
  brush.vertex(615, 290);
  brush.vertex(685, 316);
  brush.vertex(732, 332);
  brush.vertex(770, 324); // winged cat-eye tip
  brush.vertex(742, 344);
  brush.vertex(712, 346);
  brush.vertex(648, 318);
  brush.vertex(578, 299);
  brush.vertex(512, 296);
  brush.endShape(CLOSE);
  brush.noWash();

  // Cast shadow of the thick upper eyelashes across the top of the cornea and sclera
  brush.set("2B", "#0a1c24", 1.2);
  brush.spline([
    [502, 298, 0.8],
    [555, 296, 1.2],
    [625, 306, 1.1],
    [695, 332, 0.7]
  ], 0.35);

  // UPPER EYELASHES:
  // In profile, front lashes sweep dramatically out to the left toward the nose bridge,
  // curving slightly down and then curling fiercely upward!
  const numUpperClusters = 26;
  for (let c = 0; c < numUpperClusters; c++) {
    let t = c / (numUpperClusters - 1); // 0 (front of eye) to 1 (outer corner)
    let rootX = lerp(496, 732, t);
    let rootY = lerp(292, 338, Math.pow(t, 1.15)) - Math.sin(t * Math.PI) * 14;

    // Clumped wet mascara tip target
    let lashLen = map( sin(t * 165) + 0.5, 0, 1.5, 42, 74) * (t < 0.15 ? 0.82 : 1.0);
    // Angle fans from 195 deg (sweeping forward-left) to 245 deg (sweeping up-left) to 305 deg (outer wing)
    let baseAng = map(t, 0, 1, 192, 285);

    let tipX = rootX + cos(baseAng + 18) * lashLen;
    let tipY = rootY + sin(baseAng + 18) * lashLen;

    // Draw 4-6 individual hairs per mascara bundle that converge toward the wet clumped tip
    let hairsInBundle = floor(random(4, 7));
    for (let h = 0; h < hairsInBundle; h++) {
      let rx = rootX + random(-4.5, 4.5);
      let ry = rootY + random(-2, 2);
      // Midpoint dips down before curling up
      let midX = lerp(rx, tipX, 0.48) + cos(baseAng - 38) * (lashLen * 0.22) + random(-2, 2);
      let midY = lerp(ry, tipY, 0.48) + sin(baseAng - 38) * (lashLen * 0.22) + random(2, 6);
      let tx = tipX + random(-2.5, 2.5);
      let ty = tipY + random(-2.5, 2.5);

      let lashCol = h === 0 ? "#182836" : "#04070a";
      brush.set("lash_silk", lashCol, random(0.75, 1.35));
      brush.spline([
        [rx, ry, 1.35],
        [midX, midY, 0.95],
        [tx, ty, 0.08]
      ], 0.45);
    }

    // Mascara bead/thickening along the lash shaft
    if (random() < 0.7) {
      let bx = lerp(rootX, tipX, random(0.3, 0.65));
      let by = lerp(rootY, tipY, random(0.3, 0.65)) + 2;
      brush.set("rotring", "#030508", random(0.9, 1.5));
      brush.line(bx, by, bx + random(-2, 2), by + random(-2, 2));
    }
  }

  // LOWER EYELASHES:
  // Heavily mascaraed, wet, clumped into starry V-bundles along the lower lid (especially near tear spill at x=574)
  const numLowerClusters = 19;
  for (let c = 0; c < numLowerClusters; c++) {
    let t = c / (numLowerClusters - 1);
    let rootX = lerp(514, 712, t);
    let rootY = lerp(360, 347, t) + Math.sin(t * Math.PI) * 9;

    // Longer, wetter clumps right around the tear origin (x: 555..605)
    let nearTear = abs(rootX - 575) < 34;
    let lashLen = (nearTear ? random(26, 38) : random(16, 28)) * Math.sin(t * Math.PI * 0.85 + 0.2);
    let baseAng = map(t, 0, 1, 132, 68);

    let tipX = rootX + cos(baseAng) * lashLen;
    let tipY = rootY + sin(baseAng) * lashLen;

    let hairs = nearTear ? 5 : 3;
    for (let h = 0; h < hairs; h++) {
      let rx = rootX + random(-4, 4);
      let ry = rootY + random(-1.5, 1.5);
      let mx = lerp(rx, tipX, 0.5) + random(-2, 2);
      let my = lerp(ry, tipY, 0.5) + random(2, 5);
      let tx = tipX + random(-1.8, 1.8);
      let ty = tipY + random(-1.8, 1.8);

      brush.set("lash_silk", "#05090e", random(0.55, 0.98));
      brush.spline([[rx, ry, 1.1], [mx, my, 0.75], [tx, ty, 0.08]], 0.4);
    }

    // Wet specular glint on the mascara-clumped lower lashes near the tear
    if (nearTear) {
      brush.set("wet_gloss", "#ffffff", 0.55);
      brush.line(rootX, rootY + 3, lerp(rootX, tipX, 0.45), lerp(rootY, tipY, 0.45));
    }
  }

  // ---------------------------------------------------------------------------
  // E. High-Arched 1950s Sculpted Hollywood Eyebrow
  // ---------------------------------------------------------------------------
  // Helper for brow spine: starts at (476, 168), peaks at (665, 118), tapers to (910, 202)
  function getBrowPt(t) {
    let x = lerp(476, 910, t);
    let y;
    if (t < 0.44) {
      let u = t / 0.44;
      y = lerp(168, 118, Math.sin(u * Math.PI * 0.5));
    } else {
      let u = (t - 0.44) / 0.56;
      y = lerp(118, 202, Math.pow(u, 1.35));
    }
    let thickness = map(t, 0, 0.35, 22, 16);
    if (t >= 0.35) thickness = map(t, 0.35, 1.0, 16, 2.5);
    return { x, y, thickness };
  }

  // Soft dark taupe-umber pencil base under the eyebrow hairs
  for (let i = 0; i < 140; i++) {
    let t = random(0.02, 0.96);
    let b = getBrowPt(t);
    let oy = random(-b.thickness * 0.45, b.thickness * 0.45);
    brush.set("cpencil", random(["#241a18", "#362724", "#171212"]), random(0.45, 0.85));
    brush.line(b.x, b.y + oy, b.x + random(10, 22), b.y + oy + random(-4, 6));
  }

  // 320 individual crisp eyebrow hairs following natural anatomical growth pattern
  for (let i = 0; i < 320; i++) {
    let t = random(0, 0.99);
    let b = getBrowPt(t);
    let startOffset = random(-b.thickness * 0.55, b.thickness * 0.55);
    let rx = b.x + random(-4, 4);
    let ry = b.y + startOffset;

    // Hair angle: steep upward at the medial head (t < 0.15), sweeping horizontally over the arch, downward at tail
    let hairAng;
    if (t < 0.16) {
      hairAng = map(t, 0, 0.16, -68, -24) + random(-8, 8);
    } else if (t < 0.48) {
      hairAng = map(t, 0.16, 0.48, -24, 12) + random(-6, 6);
    } else {
      hairAng = map(t, 0.48, 1.0, 12, 34) + random(-5, 5);
    }

    let hLen = map(t, 0, 1, 26, 18) * random(0.75, 1.2);
    let mx = rx + cos(hairAng - 6) * (hLen * 0.5);
    let my = ry + sin(hairAng - 6) * (hLen * 0.5);
    let tx = rx + cos(hairAng + 8) * hLen;
    let ty = ry + sin(hairAng + 8) * hLen;

    let col = random(["#0c090a", "#1a1312", "#2b201e", "#3d2f2b"]);
    if (t < 0.3 && random() < 0.18) col = "#6e5852"; // specular sheen on front brow hairs
    brush.set("lash_silk", col, random(0.42, 0.82));
    brush.spline([[rx, ry, 0.9], [mx, my, 0.75], [tx, ty, 0.1]], 0.35);
  }
}

// =============================================================================
// 8. SINGLE TEAR TRACING MASCARA DOWN CHEEK (OPTICAL LENSING & CAUSTICS)
// =============================================================================
function drawMascaraTearAndLensing() {
  // ---------------------------------------------------------------------------
  // A. Disturbed Face Powder Margin & Cast Shadow to the Right of the Tear
  // ---------------------------------------------------------------------------
  brush.noStroke();

  // Translucent teal-rose cast shadow on the right (shadow-ward) side of the raised liquid tear
  brush.fill("#223842", 115);
  brush.fillBleed(0.14, "out");
  brush.beginShape(0.3);
  for (let y = 370; y <= 804; y += 14) {
    let cx = getTearCenterX(y);
    let hw = getTearHalfWidth(y);
    brush.vertex(cx + hw * 0.65, y);
  }
  for (let y = 804; y >= 370; y -= 14) {
    let cx = getTearCenterX(y);
    let hw = getTearHalfWidth(y);
    let shadowWidth = map(hw, 5, 29, 7, 22);
    brush.vertex(cx + hw + shadowWidth, y + 4);
  }
  brush.endShape(CLOSE);
  brush.noFill();

  // Fine pencil shading inside the cast shadow and dampened powder border
  for (let y = 368; y <= 806; y += 2.5) {
    let cx = getTearCenterX(y);
    let hw = getTearHalfWidth(y);
    let sw = map(hw, 5, 29, 6, 19);

    // Right-side cast shadow lines
    brush.set("cpencil", y > 690 ? "#1d313b" : "#4f323b", random(0.35, 0.65));
    brush.line(cx + hw - 1, y, cx + hw + sw * random(0.6, 1.1), y + random(1, 4));

    // Dampened rose-umber skin rim where tear wet the matte face powder on the left edge
    brush.set("2H", "#8f4e59", 0.38);
    brush.line(cx - hw - random(2, 5), y, cx - hw + 1, y + 2);
  }

  // ---------------------------------------------------------------------------
  // B. Optical Lensing: Focused Caustic Glow Inside the Right Half of the Tear
  // ---------------------------------------------------------------------------
  // Because the key light comes from the upper-left, the convex tear acts as a cylindrical/spherical lens,
  // focusing warm golden-rose light onto the right interior of the stream and terminal drop!
  brush.noStroke();
  brush.wash("#ffe5d1", 185);
  brush.beginShape(0.32);
  for (let y = 372; y <= 802; y += 12) {
    let cx = getTearCenterX(y);
    let hw = getTearHalfWidth(y);
    brush.vertex(cx - hw * 0.15, y);
  }
  for (let y = 802; y >= 372; y -= 12) {
    let cx = getTearCenterX(y);
    let hw = getTearHalfWidth(y);
    brush.vertex(cx + hw * 0.92, y);
  }
  brush.endShape(CLOSE);
  brush.noWash();

  // Radiant caustic pencil modeling inside the swollen pendant teardrop (y: 700..802)
  for (let i = 0; i < 160; i++) {
    let y = random(375, 800);
    let cx = getTearCenterX(y);
    let hw = getTearHalfWidth(y);
    let x = cx + random(-hw * 0.25, hw * 0.88);
    let isDrop = y > 700;
    let col = isDrop
      ? random(["#fff6eb", "#ffe2cc", "#f7bfa8", "#f29ca2"])
      : random(["#fae0cc", "#f2c2b0", "#e69da0"]);
    brush.set("cpencil", col, random(0.35, 0.68));
    brush.line(x, y, x + random(-3, 4), y + random(5, 12));
  }

  // ---------------------------------------------------------------------------
  // C. Left-Side Refractive Shadow & Dissolved Black Mascara Stream
  // ---------------------------------------------------------------------------
  // 1. Dark refractive shadow along the left interior of the tear lens
  for (let y = 368; y <= 800; y += 2.2) {
    let cx = getTearCenterX(y);
    let hw = getTearHalfWidth(y);
    let col = y > 700 ? "#182832" : "#38222a";
    brush.set("2H", col, random(0.38, 0.72));
    brush.line(cx - hw, y, cx - hw * 0.22, y + 2);
  }

  // 2. Dissolved Mascara Pigment Channel:
  // Flows from the lower lash line (574, 364), winds in dark dendritic threads down the tear track,
  // and pools heavily in an ink-black crescent at the bottom bowl of the pendant teardrop!
  brush.noStroke();
  // Heavy pooled mascara crescent at the bottom of the pendant teardrop (y: 762..804)
  brush.wash("#070d12", 235);
  brush.beginShape(0.35);
  brush.vertex(539, 768);
  brush.vertex(555, 782);
  brush.vertex(572, 780);
  brush.vertex(585, 765);
  brush.vertex(581, 792);
  brush.vertex(562, 804);
  brush.vertex(543, 792);
  brush.endShape(CLOSE);

  // Upper mascara bleed funnel at the lower eyelid margin (y: 362..415)
  brush.wash("#091118", 215);
  brush.beginShape(0.3);
  brush.vertex(564, 362);
  brush.vertex(586, 364);
  brush.vertex(581, 405);
  brush.vertex(572, 415);
  brush.vertex(569, 392);
  brush.endShape(CLOSE);
  brush.noWash();

  // Sinuous suspended mascara threads & pigment eddies along the entire tear track
  for (let s = 0; s < 7; s++) {
    let pts = [];
    let offsetPhase = s * 1.4;
    for (let y = 364; y <= 796; y += 22) {
      let cx = getTearCenterX(y);
      let hw = getTearHalfWidth(y);
      let ox = Math.sin(y * 0.045 + offsetPhase) * (hw * 0.42) - hw * 0.12;
      let pWeight = y > 720 ? 1.25 : (y < 430 ? 1.15 : 0.65);
      pts.push([cx + ox, y, pWeight]);
    }
    let mCol = s < 3 ? "#060b10" : (s < 5 ? "#142430" : "#243b4a");
    brush.set("lash_silk", mCol, random(0.45, 0.85));
    brush.spline(pts, 0.45);
  }

  // Microscopic flaked mascara grains suspended inside the tear and clinging to its edges
  for (let i = 0; i < 210; i++) {
    let y = random(366, 804);
    let cx = getTearCenterX(y);
    let hw = getTearHalfWidth(y);
    // Concentrate more mascara specks near top meniscus and bottom drop bowl
    let x = cx + random(-hw * 0.95, hw * 0.75);
    let isDense = (y < 435 || y > 745 || random() < 0.45);
    if (isDense) {
      let col = random(["#04080c", "#0f1c26", "#1d3140"]);
      brush.set("rotring", col, random(0.3, 0.75));
      brush.line(x, y, x + random(-2, 2), y + random(1, 4));
    }
  }

  // ---------------------------------------------------------------------------
  // D. Secondary Small Bead Droplet Below the Main Pendant Tear (555, 838)
  // ---------------------------------------------------------------------------
  const beadX = 555;
  const beadY = 838;
  // Cast shadow of small bead
  brush.noStroke();
  brush.wash("#243942", 145);
  brush.circle(beadX + 4, beadY + 3, 7.5, 0.15);
  // Caustic interior of small bead
  brush.wash("#ffe6d4", 200);
  brush.circle(beadX + 1.5, beadY, 6.5, 0.15);
  // Dark mascara speck at bottom of small bead
  brush.wash("#081017", 230);
  brush.circle(beadX - 1, beadY + 3.5, 3.8, 0.15);
  brush.noWash();

  // ---------------------------------------------------------------------------
  // E. Razor-Sharp Wet Specular Highlights on the Tear Track & Pendant Drop
  // ---------------------------------------------------------------------------
  // 1. Continuous wet highlight ribbon just inside the left (light-facing) edge of the rivulet
  let leftRibbonPts = [];
  for (let y = 368; y <= 715; y += 20) {
    let cx = getTearCenterX(y);
    let hw = getTearHalfWidth(y);
    leftRibbonPts.push([cx - hw * 0.58, y, map(hw, 5, 14, 0.55, 1.1)]);
  }
  brush.set("wet_gloss", "#ffffff", 0.75);
  brush.spline(leftRibbonPts, 0.4);

  // 2. Curved studio-light specular reflection on the upper-left dome of the swollen pendant teardrop!
  const dropHighlightOuter = [
    [551, 712, 0.3],
    [541, 734, 1.25],
    [538, 758, 1.45],
    [542, 780, 1.1],
    [552, 795, 0.4]
  ];
  brush.set("wet_gloss", "#ffffff", 1.25);
  brush.spline(dropHighlightOuter, 0.45);

  const dropHighlightInner = [
    [555, 720, 0.2],
    [546, 740, 1.0],
    [544, 762, 1.1],
    [548, 780, 0.6]
  ];
  brush.set("wet_gloss", "#fff8ed", 0.9);
  brush.spline(dropHighlightInner, 0.45);

  // 3. Secondary internal reflection arc along the bottom-right meniscus of the teardrop
  brush.set("wet_gloss", "#ffffff", 0.8);
  brush.spline([
    [564, 801, 0.4],
    [577, 794, 1.0],
    [586, 778, 0.9],
    [588, 758, 0.3]
  ], 0.4);

  // Specular glint on the lower small bead (555, 838)
  brush.set("wet_gloss", "#ffffff", 0.85);
  brush.line(beadX - 3.5, beadY - 3, beadX - 2.5, beadY + 2);
}

// =============================================================================
// 9. PROFILE RIM ILLUMINATION, VELLUS PEACH FUZZ & FINAL POLISH
// =============================================================================
function drawProfileRimAndFinalGlazes() {
  // 1. Crisp Technicolor Golden-Ivory Rim Highlight along the entire skin profile contour
  for (let y = 0; y < 1200; y += 3) {
    // Skip cherry-red lip vermilion (which has its own crimson-scarlet edge)
    if (y > 835 && y < 1094) continue;

    let px = getProfileX(y);
    let pxNext = getProfileX(y + 4);
    let tang = atan2(4, pxNext - px);

    let rimCol = (y > 575 && y < 670) ? "#fff7ed" : "#ffeedb";
    brush.set("2H", rimCol, random(0.45, 0.85));
    brush.line(px + 0.5, y, pxNext + 0.5, y + 4);

    // Secondary soft warm glow 3-7px inside the profile edge
    if (random() < 0.65) {
      brush.set("cpencil", "#f7d5be", random(0.35, 0.6));
      brush.line(px + random(2, 7), y, pxNext + random(2, 7), y + 4);
    }

    // 2. Microscopic Vellus Hair (Peach Fuzz) catching the theatrical backlight along the profile edge!
    // Visible especially on forehead, philtrum, chin, and lower nasal bridge against the dark peacock velvet
    let fuzzProb = (y > 706 && y < 832) ? 0.65 : ((y > 1096 || y < 210) ? 0.45 : 0.18);
    if (random() < fuzzProb) {
      let fuzzLen = (y > 706 && y < 832) ? random(4, 9.5) : random(3.5, 7.5);
      // Hairs project outward-left and slightly downward into the dark peacock background
      let fuzzAng = tang + 98 + random(-18, 18);
      brush.set("lash_silk", "#fff6e8", random(0.18, 0.34));
      brush.line(
        px + 1, y,
        px + cos(fuzzAng) * fuzzLen,
        y + sin(fuzzAng) * fuzzLen
      );
    }
  }

  // 3. Crisp Scarlet Rim along the profile edge of the Cherry-Red Lips
  for (let y = 836; y <= 1092; y += 2.5) {
    if (y > 944 && y < 966) continue; // parted mouth cleft
    let px = getProfileX(y);
    let pxNext = getProfileX(y + 3);
    let col = (y < 915 || (y > 975 && y < 1055)) ? "#ff475e" : "#b8081e";
    brush.set("2H", col, 0.65);
    brush.line(px, y, pxNext, y + 3);
  }

  // 4. Final Subtle Atmospheric Technicolor Teal & Rose Glaze Accents
  // Deepen the far-right temple/cheek vignette so the eye, tear, and cherry lip command total focus
  brush.set("dermal_glaze", "#071d26", 2.4);
  for (let i = 0; i < 65; i++) {
    let x = random(980, 1200);
    let y = random(0, 1200);
    brush.line(x, y, x + random(-35, 35), y + random(50, 120));
  }
}

async function setup() {
  createCanvas(1200, 1200, WEBGL);
  angleMode(DEGREES);

  randomSeed(4079);
  noiseSeed(4079);

  // Custom brushes tailored for cord impressions, iron-oxide chalk, soot blooms, and bone filaments
  brush.add("cord_fibre", {
