  });

  background("#151210");
}

function draw() {
  translate(-width / 2, -height / 2);
  brush.noField();

  // =========================================================================
  // 1. SURROUNDING ROOM: SOFT CHARCOAL-GREY GRADIENT WITH WARM UNDERTONE
  // =========================================================================
  const roomRings = [
    { r: 860, col: "#141210", op: 95 },
    { r: 740, col: "#1a1715", op: 85 },
    { r: 640, col: "#211d1a", op: 80 },
    { r: 550, col: "#2a2420", op: 75 },
    { r: 475, col: "#352d27", op: 75 },
    { r: 410, col: "#43382f", op: 75 },
    { r: 355, col: "#544538", op: 80 },
    { r: 315, col: "#6b5542", op: 85 },
    { r: 285, col: "#87694d", op: 90 },
    { r: 264, col: "#a88058", op: 95 },
    { r: 250, col: "#c99b66", op: 105 }
  ];

  brush.noStroke();
  for (let ring of roomRings) {
    let pts = [];
    for (let a = 0; a < 360; a += 8) {
      let jitter = 14 * (noise(cos(a) * 2 + ring.r * 0.01, sin(a) * 2) - 0.5);
      let rx = BULB_X + cos(a) * (ring.r + jitter);
      let ry = BULB_Y + sin(a) * (ring.r + jitter);
      pts.push([rx, ry]);
    }
    let poly = new brush.Polygon(pts);
    poly.wash(ring.col, ring.op);
  }

  // Soft charcoal grain strokes across the room to build seamless velvety tone
  const roomCharcoalTones = [
    { rMin: 560, rMax: 880, col: "#141110", count: 110, w: 1.5 },
    { rMin: 430, rMax: 640, col: "#221d1a", count: 100, w: 1.35 },
    { rMin: 340, rMax: 490, col: "#332b25", count: 95, w: 1.2 },
    { rMin: 275, rMax: 380, col: "#4a3d32", count: 90, w: 1.05 }
  ];

  for (let band of roomCharcoalTones) {
    brush.set("velvet_charcoal", band.col, band.w);
    for (let i = 0; i < band.count; i++) {
      let a = random(360);
      let r = random(band.rMin, band.rMax);
      let span = random(18, 42);
      brush.arc(BULB_X, BULB_Y, r, a - span / 2, a + span / 2);
    }
  }

  // Subtle fine diagonal charcoal tooth in the dark corners
  brush.set("fine_charcoal", "#181513", 0.9);
  for (let i = 0; i < 140; i++) {
    let a = random(360);
    let r = random(420, 840);
    let x = BULB_X + cos(a) * r;
    let y = BULB_Y + sin(a) * r;
    let tang = a + 90 + random(-25, 25);
    let len = random(45, 110);
    brush.line(
      x - cos(tang) * len * 0.5,
      y - sin(tang) * len * 0.5,
      x + cos(tang) * len * 0.5,
      y + sin(tang) * len * 0.5
    );
  }

  // =========================================================================
  // 2. ATMOSPHERIC TUNGSTEN CORONA (CHROME YELLOW TO CORONAL ROSE AT LIMB)
  // =========================================================================
  const coronaBands = [
    { rMin: 265, rMax: 380, col: "#9e7a50", count: 85, w: 1.15 },
    { rMin: 245, rMax: 325, col: "#cfa360", count: 95, w: 1.0 },
    { rMin: 235, rMax: 290, col: "#ebca78", count: 105, w: 0.85 },
    { rMin: 230, rMax: 268, col: "#fae29b", count: 110, w: 0.72 },
    // Coronal rose right at the grazing limb
    { rMin: 226, rMax: 254, col: "#d96552", count: 115, w: 0.65 },
    { rMin: 228, rMax: 248, col: "#e8836f", count: 110, w: 0.55 },
    { rMin: 230, rMax: 244, col: "#f5a991", count: 95, w: 0.45 }
  ];

  for (let cb of coronaBands) {
    brush.set("coronal_glow", cb.col, cb.w);
    for (let i = 0; i < cb.count; i++) {
      let a = random(360);
      // Slightly stronger coronal intensity around upper crown & temples
      let topBoost = map(sin(a), -1, 1, 1.08, 0.88);
      let r = getHeadRadius(a) + ( random(cb.rMin, cb.rMax) - 232 ) * topBoost;
      let span = random(10, 26);
      brush.arc(CX, CY, r, a - span / 2, a + span / 2);
    }
  }

  // Soft background radial pencil-glow rays streaming outward before the scalp mass
  const bgRayColors = ["#7d6245", "#a68256", "#cfa465", "#e8c478", "#dca080"];
  for (let cIdx = 0; cIdx < bgRayColors.length; cIdx++) {
    brush.set("cpencil", bgRayColors[cIdx], 0.55);
    let rayCount = 75;
    for (let i = 0; i < rayCount; i++) {
      let a = random(360);
      let rStart = getHeadRadius(a) - 4;
      let rEnd = rStart + random(45, 240 - cIdx * 30);
      let drift = random(-8, 8);
      let p1 = [CX + cos(a) * rStart, CY + sin(a) * rStart, 0.8];
      let p2 = [
        CX + cos(a + drift * 0.5) * ((rStart + rEnd) * 0.5),
        CY + sin(a + drift * 0.5) * ((rStart + rEnd) * 0.5),
        0.5
      ];
      let p3 = [CX + cos(a + drift) * rEnd, CY + sin(a + drift) * rEnd, 0.1];
      brush.spline([p1, p2, p3], 0.35);
    }
  }

  // =========================================================================
  // 3. THE ECLIPSED SCALP: BLACK DISC OF DENSE, VELVETY CHARCOAL MASS
  // =========================================================================
  let headPts = [];
  let innerPts = [];
  for (let a = 0; a < 360; a += 3) {
    headPts.push(getHeadPoint(a, 0));
    innerPts.push(getHeadPoint(a, -10));
  }

  // Solid dark under-wash so the eclipsed core is completely opaque
  let headPoly = new brush.Polygon(headPts);
  headPoly.wash("#120e0d", 255);

  let innerPoly = new brush.Polygon(innerPts);
  innerPoly.wash("#0a0807", 255);

  // Dense dry-media charcoal mass passes over the cranium
  brush.noStroke();
  brush. noFill();
  brush.noWash();

  brush.mass("charcoal", "#13100e", {
    precision: 0.72,
    strength: 0.95,
    gradient: 0.22,
    outline: true
  });
  brush.beginShape(0.3);
  for (let i = 0; i < headPts.length; i += 2) {
    brush.vertex(headPts[i][0], headPts[i][1]);
  }
  brush.endShape(true);

  brush.mass("charcoal", "#0a0807", {
    precision: 0.8,
    strength: 1.0,
    gradient: 0.15,
    outline: false
  });
  brush.beginShape(0.3);
  for (let i = 0; i < innerPts.length; i += 2) {
    brush.vertex(innerPts[i][0], innerPts[i][1]);
  }
  brush.endShape(true);
  brush.noMass();

  // Velvety spherical charcoal strokes modeling the 3D volume of the bald crown
  const scalpLayers = [
    { rFracMin: 0.0, rFracMax: 0.78, col: "#070605", brushName: "velvet_charcoal", w: 1.15, count: 130 },
    { rFracMin: 0.55, rFracMax: 0.93, col: "#0e0b0a", brushName: "velvet_charcoal", w: 0.9, count: 120 },
    { rFracMin: 0.80, rFracMax: 0.98, col: "#171210", brushName: "fine_charcoal", w: 0.85, count: 140 },
    { rFracMin: 0.91, rFracMax: 1.00, col: "#261b17", brushName: "fine_charcoal", w: 0.65, count: 130 }
  ];

  for (let sl of scalpLayers) {
    brush.set(sl.brushName, sl.col, sl.w);
    for (let i = 0; i < sl.count; i++) {
      let a = random(360);
      let maxR = getHeadRadius(a);
      let r = maxR * random(sl.rFracMin, sl.rFracMax);
      if (r < 18) continue;
      let span = random(16, 44);
      brush.arc(CX, CY, r, a - span / 2, a + span / 2);
    }
  }

  // Cross-contour graphite/charcoal shading across the central occiput
  brush.set("2B", "#090707", 0.85);
  for (let i = 0; i < 160; i++) {
    let a = random(360);
    let r = random(15, 205);
    let x = CX + cos(a) * r;
    let y = CY + sin(a) * r;
    let ang = a + 90 + random(-35, 35);
    let len = random(28, 70);
    brush.line(
      x - cos(ang) * len * 0.5,
      y - sin(ang) * len * 0.5,
      x + cos(ang) * len * 0.5,
      y + sin(ang) * len * 0.5
    );
  }

  // =========================================================================
  // 4. GRAZING CHROMOSPHERE AT THE LIMB (CORONAL ROSE & SUBSURFACE SCATTER)
  // =========================================================================
  // Along the very limb of the scalp, tungsten light grazes skin & hair follicles
  const limbRoseTones = [
    { offsetMin: -5, offsetMax: 2, col: "#6e2920", w: 0.55, count: 130 },
    { offsetMin: -3, offsetMax: 4, col: "#a83e31", w: 0.5, count: 140 },
    { offsetMin: -1.5, offsetMax: 6.5, col: "#d95f4c", w: 0.45, count: 150 },
    { offsetMin: 0, offsetMax: 9, col: "#eb856e", w: 0.4, count: 140 },
    { offsetMin: 2, offsetMax: 13, col: "#f5b882", w: 0.36, count: 120 },
    { offsetMin: 4, offsetMax: 18, col: "#fae098", w: 0.32, count: 110 }
  ];

  for (let lr of limbRoseTones) {
    brush.set("cpencil", lr.col, lr.w);
    for (let i = 0; i < lr.count; i++) {
      let a = random(360);
      let r = getHeadRadius(a) + random(lr.offsetMin, lr.offsetMax);
      let span = random(4, 13);
      brush.arc(CX, CY, r, a - span / 2, a + span / 2);
    }
  }

  // Subtle highlight on the upper ear helixes tucked at ~162 deg and ~18 deg
  const earAngles = [162, 18];
  for (let ea of earAngles) {
    brush.set("cpencil", "#d96552", 0.45);
    for (let i = 0; i < 18; i++) {
      let a = ea + random(-11, 11);
      let r = getHeadRadius(a) + random(-2, 2.5);
      brush.arc(CX, CY, r, a - 3, a + 3);
    }
    brush.set("vellus_hair", "#f7d58c", 0.65);
    for (let i = 0; i < 22; i++) {
      let a = ea + random(-12, 12);
      let p0 = getHeadPoint(a, random(-2, 1));
      let len = random(6, 16);
      let outAng = a + random(-18, 18);
      brush.line(p0[0], p0[1], p0[0] + cos(outAng) * len, p0[1] + sin(outAng) * len);
    }
  }

  // =========================================================================
  // 5. DRIFTING DUST STREAMS & ILLUMINATED CONVECTION FILAMENTS
  // =========================================================================
  let dustBeads = [];

  // Long, curving pencil-filament dust trails in the thermal updraft
  const dustStreamColors = ["#8c6e4d", "#b8925c", "#dec078", "#f5de96", "#e69f84"];
  for (let c = 0; c < dustStreamColors.length; c++) {
    brush.set("vellus_hair", dustStreamColors[c], 0.55);
    let streamCount = 48;
    for (let i = 0; i < streamCount; i++) {
      let a = random(360);
      let baseR = getHeadRadius(a);
      let rDist = random(18, 290);
      let r = baseR + rDist;
      let sx = CX + cos(a) * r;
      let sy = CY + sin(a) * r;

      // Thermal upward & radial drift angle
      let flowAng = a + sin(a * 2) * 14 - cos(a) * 18 + random(-15, 15);
      let segLen = random(7, 22);
      let pts = [[sx, sy, 0.2]];
      let curX = sx;
      let curY = sy;
      let steps = int(random(2, 5));
      for (let s = 1; s <= steps; s++) {
        flowAng += random(-14, 14);
        curX += cos(flowAng) * segLen;
        curY += sin(flowAng) * segLen;
        let p = s === steps ? 0.1 : 0.75;
        pts.push([curX, curY, p]);
      }
      brush.spline(pts, 0.45);

      if (random() < 0.55) {
        dustBeads.push({
          x: pts[1][0] + random(-2, 2),
          y: pts[1][1] + random(-2, 2),
          dist: rDist,
          size: random(0.35, 0.95)
        });
      }
    }
  }

  // Additional floating dust motes following coronal arcs
  for (let i = 0; i < 240; i++) {
    let a = random(360);
    let rDist = pow(random(1), 1.6) * 310 + 6;
    let r = getHeadRadius(a) + rDist;
    dustBeads.push({
      x: CX + cos(a) * r,
      y: CY + sin(a) * r,
      dist: rDist,
      size: random(0.28, 1.05)
    });
  }

  // =========================================================================
  // 6. CORONA OF FINE WHITE HAIRS (WIRY, SLIGHTLY KINKED PENCIL FILAMENTS)
  // =========================================================================
  let hairList = [];

  // Helper to generate anatomically & astronomically accurate hair parameters
  function buildHairPath(startAngle, rootDepth, totalLen, curveBias, kinkiness, isVellus) {
    let pStart = getHeadPoint(startAngle, rootDepth);
    let pts = [[pStart[0], pStart[1]]];
    let curX = pStart[0];
    let curY = pStart[1];
    let curAng = startAngle + random(-14, 14);

    let numSteps = isVellus ? int(random(3, 6)) : int(constrain(totalLen / 14, 6, 18));
    let stepLen = totalLen / numSteps;
    let prevKink = 0;
    let kinks = [];

    for (let s = 1; s <= numSteps; s++) {
      let t = s / numSteps;
      // Smooth coronal streamer curvature + thermal lift toward top
      let thermalLift = -cos(curAng) * 1.4;
      let drift = curveBias * (0.6 + 0.8 * t) + thermalLift;

      // Wiry kink characteristic of coarse, unpigmented elderly hair
      let kink = 0;
      if (!isVellus && random() < 0.42) {
        kink = random([-1, 1]) * random(5, 16) * kinkiness;
      } else {
        kink = -prevKink * random(0.45, 0.85) + random(-3.5, 3.5) * kinkiness;
      }
      prevKink = kink;

      curAng += drift + kink;
      curX += cos(curAng) * stepLen;
      curY += sin(curAng) * stepLen;
      pts.push([curX, curY]);

      // Record sharp kinks or limb crossings where light refracts into bright beads
      let distFromLimb = s * stepLen + rootDepth;
      if (
        (abs(kink) > 6.5 && t > 0.08 && t < 0.82) ||
        (s === 1 && distFromLimb > 0 && random() < 0.48) ||
        (s === 2 && random() < 0.35)
      ) {
        kinks.push({
          x: curX,
          y: curY,
          t: t,
          dist: max(1, distFromLimb),
          intensity: map(abs(kink), 0, 16, 0.55, 1.15)
        });
      }
    }

    return { pts, kinks, totalLen, isVellus, startAngle };
  }

  // A. Top Bald Crown (242° to 298°): Grazing vellus down + sparse long stray filaments
  for (let i = 0; i < 150; i++) {
    let a = random(238, 302);
    let len = random(9, 34);
    let curve = random(-3.5, 3.5);
    hairList.push(buildHairPath(a, random(-2.5, 1.0), len, curve, 0.55, true));
  }
  // Sparse, long stray crown hairs floating upward into the eclipse glare
  for (let i = 0; i < 52; i++) {
    let a = random(232, 308);
    let len = random(65, 225);
    let side = a < 270 ? -1 : 1;
    let curve = side * random(0.6, 3.2) + random(-1.8, 1.8);
    hairList.push(buildHairPath(a, random(-5, 0.5), len, curve, 0.95, false));
  }

  // B. Left & Right Parietal / Temporal Fringe (The main coronal streamers!)
  // Left fringe: 138° to 242°, Right fringe: 298° to 422° (62°)
  const fringeZones = [
    { aMin: 142, aMax: 242, side: -1, count: 165 },
    { aMin: 298, aMax: 398, side: 1, count: 165 }
  ];

  for (let z of fringeZones) {
    for (let i = 0; i < z.count; i++) {
      let a = random(z.aMin, z.aMax);
      // Hairs near the parietal ridge (190-235 and 305-350) stream furthest outward
      let distFromRidge = min(abs(angleDiff(a, 212)), abs(angleDiff(a, 328)));
      let ridgeFactor = map(constrain(distFromRidge, 0, 65), 0, 65, 1.35, 0.68);
      let len = random(55, 245) * ridgeFactor;

      // Occasional extra-long coronal streamer filaments
      if (random() < 0.16) len *= random(1.25, 1.55);

      // Coronal magnetic-like arch bias (some sweep up, some arch outward/downward)
      let archMode = random();
      let curve = 0;
      if (archMode < 0.45) {
        curve = -z.side * random(0.8, 2.8); // Sweeping upward toward crown
      } else if (archMode < 0.82) {
        curve = z.side * random(0.5, 2.5);  // Sweeping outward & gently down
      } else {
        curve = random(-3.2, 3.2);          // Unruly crossing filament
      }

      hairList.push(buildHairPath(a, random(-7, 0.5), len, curve, random(0.8, 1.25), false));
    }
  }

  // C. Lower Occipital / Nape Fringe (42° to 138°)
  for (let i = 0; i < 95; i++) {
    let a = random(42, 138);
    let len = random(38, 155);
    let side = a > 90 ? -1 : 1;
    let curve = side * random(0.4, 2.4) + random(-1.5, 1.5);
    hairList.push(buildHairPath(a, random(-6, 0.5), len, curve, 0.9, false));
  }

  // Collect all kinks for light bead rendering
  let hairBeads = [];
  for (let h of hairList) {
    for (let k of h.kinks) {
      hairBeads.push(k);
    }
  }

  // =========================================================================
  // RENDER HAIRS IN 3 TONAL PASSES (CORONAL ROSE -> CHROME YELLOW -> PEARL WHITE)
  // =========================================================================

  // PASS 1: Faint Coronal Rose at the very limb (root segments of every hair)
  const roseRootColors = ["#d45d4a", "#e67c67", "#f29c85"];
  for (let cIdx = 0; cIdx < roseRootColors.length; cIdx++) {
    brush.set("wiry_hair", roseRootColors[cIdx], 0.85);
    for (let i = cIdx; i < hairList.length; i += roseRootColors.length) {
      let h = hairList[i];
      let endIdx = min(h.pts.length, h.isVellus ? 3 : 4);
      if (endIdx < 2) continue;
      let subPts = [];
      for (let j = 0; j < endIdx; j++) {
        let p = j === 0 ? 0.35 : j === endIdx - 1 ? 0.15 : 0.85;
        subPts.push([h.pts[j][0], h.pts[j][1], p]);
      }
      if (subPts.length >= 2) {
        brush.spline(subPts, 0.25);
      }
    }
  }

  // PASS 2: Pale Chrome Yellow along the full length & thinning outer pencil filaments
  const chromeColors = ["#e3b259", "#f2cb72", "#f8dc8d", "#fce9ad"];
  for (let cIdx = 0; cIdx < chromeColors.length; cIdx++) {
    for (let i = cIdx; i < hairList.length; i += chromeColors.length) {
      let h = hairList[i];
      brush.set(h.isVellus ? "vellus_hair" : "wiry_hair", chromeColors[cIdx], h.isVellus ? 0.72 : 0.82);

      // From just off the root to the very tip
      let startIdx = h.pts.length > 4 ? 1 : 0;
      let subPts = [];
      let count = h.pts.length - startIdx;
      for (let j = startIdx; j < h.pts.length; j++) {
        let norm = (j - startIdx) / max(1, count - 1);
        let p = norm < 0.2 ? 0.65 : norm > 0.8 ? 0.08 : 0.85 * (1 - norm * 0.55);
        subPts.push([h.pts[j][0], h.pts[j][1], p]);
      }
      if (subPts.length >= 2) {
        brush.spline(subPts, 0.22);
      }
    }
  }

  // PASS 3: Pearly Titanium White along the inner-to-mid hair shafts
  const pearlColors = ["#f7f1e1", "#fcf8ec", "#fffdf7", "#ffffff"];
  for (let cIdx = 0; cIdx < pearlColors.length; cIdx++) {
    for (let i = cIdx; i < hairList.length; i += pearlColors.length) {
      let h = hairList[i];
      if (h.isVellus && random() < 0.35) continue;

      brush.set(h.isVellus ? "vellus_hair" : "wiry_hair", pearlColors[cIdx], h.isVellus ? 0.65 : 0.76);

      // Pearly white is strongest in the inner-to-mid corona, thinning out before the chrome-yellow tip
      let maxIdx = h.isVellus
        ? h.pts.length
        : max(3, int(h.pts.length * random(0.62, 0.86)));
      let subPts = [];
      for (let j = 0; j < maxIdx; j++) {
        let norm = j / max(1, maxIdx - 1);
        let p = j === 0 ? 0.2 : norm > 0.75 ? 0.1 : 0.95 * (1 - norm * 0.45);
        subPts.push([h.pts[j][0], h.pts[j][1], p]);
      }
      if (subPts.length >= 2) {
        brush.spline(subPts, 0.2);
      }
    }
  }

  // =========================================================================
  // 7. RE-ANCHOR SCALP HORIZON (DARK VELVET CHARCOAL TUCK AT HAIR ROOTS)
  // =========================================================================
  // Subtle dark charcoal strokes just inside the limb so some hairs emerge from behind the horizon
  brush.set("fine_charcoal", "#120e0d", 0.55);
  for (let i = 0; i < 160; i++) {
    let a = random(360);
    let r = getHeadRadius(a) - random(2.5, 9);
    let span = random(4, 11);
    brush.arc(CX, CY, r, a - span / 2, a + span / 2);
  }

  // =========================================================================
  // 8. TINY BRIGHT BEADS OF REFRACTED LIGHT (ON HAIR KINKS, LIMB & DUST)
  // =========================================================================
  // Add concentrated limb refraction beads ("Baily's beads" through hair follicles)
  for (let i = 0; i < 145; i++) {
    let a = random(360);
    // Denser along the upper crown and parietal fringes
    if (a > 55 && a < 125 && random() < 0.45) continue;
    let rOffset = random(-1.0, 5.5);
    let pt = getHeadPoint(a, rOffset);
    hairBeads.push({
      x: pt[0],
      y: pt[1],
      t: 0.05,
      dist: max(0.5, rOffset + 2),
      intensity: random(0.75, 1.35)
    });
  }

  // First pass on beads: tiny warm chrome-yellow / coronal-rose micro-halos
  brush.set("coronal_glow", "#f7cc74", 0.12);
  for (let i = 0; i < hairBeads.length; i += 2) {
    let b = hairBeads[i];
    if (b.dist < 160) {
      brush.circle(b.x, b.y, random(1.8, 3.8), 0.2);
    }
  }

  // Second pass on beads: crisp pale chrome yellow & coronal rose pinpoint glints
  brush.set("light_bead", "#f59d7e", 0.65);
  for (let b of hairBeads) {
    if (b.dist < 14) {
      let ang = random(360);
      let d = random(1.0, 2.2) * b.intensity;
      brush.line(b.x - cos(ang) * d, b.y - sin(ang) * d, b.x + cos(ang) * d, b.y + sin(ang) * d);
    }
  }

  brush.set("light_bead", "#fae296", 0.62);
  for (let b of hairBeads) {
    if (b.dist >= 8 && b.dist < 220) {
      let ang = random(360);
      let d = random(0.8, 2.0) * b.intensity;
      brush.line(b.x - cos(ang) * d, b.y - sin(ang) * d, b.x + cos(ang) * d, b.y + sin(ang) * d);
    }
  }

  // Third pass on beads: brilliant pearly titanium white pinpoint cores on hair kinks
  brush.set("light_bead", "#ffffff", 0.58);
  for (let b of hairBeads) {
    if (b.dist < 150) {
      let ang = random(360);
      let d = random(0.6, 1.5) * b.intensity;
      brush.line(b.x - cos(ang) * d, b.y - sin(ang) * d, b.x + cos(ang) * d, b.y + sin(ang) * d);
    }
  }

  // Render drifting dust motes (pearly near limb, pale chrome yellow in mid-corona, warm buff outside)
  for (let db of dustBeads) {
    if (db.dist < 85) {
      brush.set("light_bead", "#fffdf7", 0.45 * db.size);
    } else if (db.dist < 195) {
      brush.set("light_bead", "#f7de92", 0.42 * db.size);
    } else {
      brush.set("cpencil", "#c7a16b", 0.48 * db.size);
    }
    let ang = random(360);
    let d = random(0.6, 1.6) * db.size;
    brush.line(db.x - cos(ang) * d, db.y - sin(ang) * d, db.x + cos(ang) * d, db.y + sin(ang) * d);
  }

  noLoop();
}

