function buildMousepadPolygon(cx, cy, w, h, cornerR, angleDeg) {
  let pts = [];
  let hw = w / 2, hh = h / 2;
  let corners = [
    [hw - cornerR, -hh + cornerR, -90, 0],
    [hw - cornerR, hh - cornerR, 0, 90],
    [-hw + cornerR, hh - cornerR, 90, 180],
    [-hw + cornerR, -hh + cornerR, 180, 270]
  ];
  let rad = angleDeg * Math.PI / 180;
  let ca = Math.cos(rad), sa = Math.sin(rad);

  for (let c = 0; c < corners.length; c++) {
    let [ox, oy, a0, a1] = corners[c];
    let segs = 5;
    for (let s = 0; s <= segs; s++) {
      let a = (a0 + (a1 - a0) * (s / segs)) * Math.PI / 180;
      let lx = ox + Math.cos(a) * cornerR;
      let ly = oy + Math.sin(a) * cornerR;
      let wx = cx + lx * ca - ly * sa;
      let wy = cy + lx * sa + ly * ca;
      pts.push([wx, wy]);
    }
  }
  return pts;
}

