// ===========================================================================
// 4. COILED GREY PS/2 CORD & STEPPED SHADOWS
// ===========================================================================

function evalCatmullRom(p0, p1, p2, p3, t) {
  let t2 = t * t, t3 = t2 * t;
  let x = 0.5 * (
    (2 * p1[0]) +
    (-p0[0] + p2[0]) * t +
    (2 * p0[0] - 5 * p1[0] + 4 * p2[0] - p3[0]) * t2 +
    (-p0[0] + 3 * p1[0] - 3 * p2[0] + p3[0]) * t3
  );
  let y = 0.5 * (
    (2 * p1[1]) +
    (-p0[1] + p2[1]) * t +
    (2 * p0[1] - 5 * p1[1] + 4 * p2[1] - p3[1]) * t2 +
    (-p0[1] + 3 * p1[1] - 3 * p2[1] + p3[1]) * t3
  );
  return [x, y];
}

function sampleSpline(ctrlPts, samplesPerSeg = 14) {
  let out = [];
  let n = ctrlPts.length;
  for (let i = 0; i < n - 1; i++) {
    let p0 = ctrlPts[Math.max(0, i - 1)];
    let p1 = ctrlPts[i];
    let p2 = ctrlPts[i + 1];
    let p3 = ctrlPts[Math.min(n - 1, i + 2)];
    let limit = (i === n - 2) ? samplesPerSeg : samplesPerSeg - 1;
    for (let s = 0; s <= limit; s++) {
      let t = s / samplesPerSeg;
      out.push(evalCatmullRom(p0, p1, p2, p3, t));
    }
  }
  return out;
}

function buildTubePolygon(spinePts, r0, r1) {
  let leftSide = [];
  let rightSide = [];
  let n = spinePts.length;
  for (let i = 0; i < n; i++) {
    let pPrev = spinePts[Math.max(0, i - 1)];
    let pNext = spinePts[Math.min(n - 1, i + 1)];
    let dx = pNext[0] - pPrev[0], dy = pNext[1] - pPrev[1];
    let len = Math.hypot(dx, dy) || 1;
    let nx = -dy / len, ny = dx / len;
    leftSide.push([spinePts[i][0] + nx * r0, spinePts[i][1] + ny * r0]);
    rightSide.push([spinePts[i][0] + nx * r1, spinePts[i][1] + ny * r1]);
  }
  return leftSide.concat(rightSide.reverse());
}

function drawCordPass(spinePts, radius) {
  // 1. Base marker grey cylinder fill
  let fullTube = buildTubePolygon(spinePts, -radius, radius);
  fillMarkerPoly(fullTube, "#90989c", 250, "#858d91", 5, 30, 0.42);

  // 2. Stepped longitudinal bevel bands along the cylindrical cord
  let n = spinePts.length;
  let chunk = 5;
  for (let i = 0; i < n - 1; i += chunk) {
    let sub = spinePts.slice(i, Math.min(n, i + chunk + 1));
    if (sub.length < 2) continue;

    let pA = sub[0], pB = sub[sub.length - 1];
    let dx = pB[0] - pA[0], dy = pB[1] - pA[1];
    let len = Math.hypot(dx, dy) || 1;
    let nx = -dy / len, ny = dx / len;
    // Ensure (nx, ny) points toward Top-Left (-0.707, -0.707)
    let dotTL = nx * (-0.7071) + ny * (-0.7071);
    let sgn = dotTL >= 0 ? 1 : -1;

    // Lit top-left cylinder strip
    let litStrip = buildTubePolygon(sub, sgn * radius * 0.2, sgn * radius * 0.92);
    fillMarkerPoly(litStrip, "#bcc4c8", 242, "#cfd6da", 4.5, 0, 0.35);

    // Core dark bottom-right cylinder strip
    let darkStrip = buildTubePolygon(sub, -sgn * radius * 0.25, -sgn * radius * 0.95);
    fillMarkerPoly(darkStrip, "#5e666a", 245, "#4c5357", 4.5, 0, 0.35);

    // Subtle yellowed rubber aging smudge along mid-cord
    if (i % 2 === 0) {
      let ageStrip = buildTubePolygon(sub, -sgn * radius * 0.2, sgn * radius * 0.3);
      fillMarkerPoly(ageStrip, "#a8a393", 140, "#999382", 5, 45, 0.32);
    }
  }

  // 3. Cross-contour ring ticks & rubber mold parting seam
  for (let i = 2; i < n - 2; i += 3) {
    let pPrev = spinePts[i - 1], pNext = spinePts[i + 1];
    let p = spinePts[i];
    let dx = pNext[0] - pPrev[0], dy = pNext[1] - pPrev[1];
    let len = Math.hypot(dx, dy) || 1;
    let nx = -dy / len, ny = dx / len;
    brush.set("2H", i % 6 === 0 ? "#484f52" : "#d8e0e4", 0.3);
    brush.line(p[0] - nx * radius * 0.85, p[1] - ny * radius * 0.85, p[0] + nx * radius * 0.85, p[1] + ny * radius * 0.85);
  }

  // 4. Strict 1990s OS Bevel along both outer edges of the cord
  bevelPolygon(fullTube, {
    lightOuter: "#ffffff",
    lightInner: "#dce2e6",
    darkInner: "#495054",
    darkOuter: "#161a1d",
    outerWeight: 0.78,
    innerWeight: 0.46,
    insetDist: 2.5
  });
}

function drawCoiledCord() {
  let cordR = 14.5;

  // We divide the coiled cord into 3 overlapping segments so upper coils cast
  // hard stepped shadows over lower coils!
  // Segment 1 (Lower Loop): from upper-left desk port down through big lower-left loop and across to right
  let seg1Ctrl = [
    [225, 134],
    [215, 225],
    [195, 360],
    [215, 505],
    [325, 575],
    [515, 510],
    [715, 395],
    [825, 315],
    [810, 225],
    [685, 185],
    [520, 215]
  ];

  // Segment 2 (Middle Coil): sweeps from (520, 215) down-left OVER Segment 1, looping around
  let seg2Ctrl = [
    [520, 215],
    [365, 265],
    [265, 365],
    [275, 465],
    [390, 485],
    [555, 395],
    [645, 290],
    [590, 200],
    [445, 195],
    [325, 275]
  ];

  // Segment 3 (Front Lead into Mouse Snout): sweeps from (325, 275) down-right into the mouse strain-relief boot
  let seg3Ctrl = [
    [325, 275],
    [290, 365],
    [340, 445],
    [438, 492],
    [485, 525]
  ];

  let spine1 = sampleSpline(seg1Ctrl, 12);
  let spine2 = sampleSpline(seg2Ctrl, 12);
  let spine3 = sampleSpline(seg3Ctrl, 12);

  let tube1 = buildTubePolygon(spine1, -cordR, cordR);
  let tube2 = buildTubePolygon(spine2, -cordR, cordR);
  let tube3 = buildTubePolygon(spine3, -cordR, cordR);

  // A. Hard Stepped Cast Shadows of all cord loops onto the mousepad/desk
  let allTubes = [tube1, tube2, tube3];
  for (let tPoly of allTubes) {
    let shOuter = makeSteppedPolygon(tPoly, 24, 28, 8);
    fillMarkerPoly(shOuter, "#004e52", 220, "#004044", 5, -45, 0.4);
  }
  for (let tPoly of allTubes) {
    let shInner = makeSteppedPolygon(tPoly, 13, 16, 7);
    fillMarkerPoly(shInner, "#082224", 242, "#041517", 4.5, -45, 0.4);
  }

  // B. Draw PS/2 Desk Port Bulkhead Clip at (225, 134)
  drawBevelBox(196, 133, 58, 28, {
    fillCol: "#8a9296",
    hatchCol: "#7d8589",
    hatchDist: 5,
    outerWeight: 0.7,
    innerWeight: 0.45
  });

  // C. Draw Segment 1 (bottom-most coil)
  drawCordPass(spine1, cordR);

  // D. Hard Stepped Shadow of Segment 2 cast onto Segment 1
  let sh2On1 = makeSteppedPolygon(tube2, 9, 11, 6);
  fillMarkerPoly(sh2On1, "#122022", 185, "#091214", 4, -45, 0.38);

  // E. Draw Segment 2 (middle coil)
  drawCordPass(spine2, cordR);

  // F. Hard Stepped Shadow of Segment 3 cast onto Segment 2 & 1
  let sh3On2 = makeSteppedPolygon(tube3, 8, 10, 6);
  fillMarkerPoly(sh3On2, "#122022", 190, "#091214", 4, -45, 0.38);

  // G. Draw Segment 3 (lead into mouse snout)
  drawCordPass(spine3, cordR);
}

// ===========================================================================
// 5. HYPERREAL YELLOWED BEIGE BALL MOUSE (3D AXONOMETRIC & BEVEL ENGINE)
// ===========================================================================

function drawBeigeBallMouse(cx, cy, angleDeg) {
  let rad = angleDeg * Math.PI / 180;
  let ca = Math.cos(rad), sa = Math.sin(rad);

  // 3D Axonometric projection from local mouse coordinates (u, v, z) to canvas (x, y)
  // u: width (-135..+135), v: length (-225 front nose .. +230 rear tail), z: height (0..70)
  function proj(u, v, z = 0) {
    let rx = u * ca - v * sa;
    let ry = u * sa + v * ca;
    return [
      cx + rx - z * 0.42,
      cy + ry - z * 0.56
    ];
  }

  // Half-width silhouette of the classic 1990s sculpted mouse
  function halfWidth(v) {
    if (v < -195) {
      // Chamfered front nose rounding
      let t = (v + 225) / 30;
      return 92 + 22 * Math.sin(Math.max(0, Math.min(1, t)) * Math.PI * 0.5);
    } else if (v < -35) {
      // Button deck gentle taper
      let t = (v + 195) / 160;
      return 114 + 17 * t;
    } else if (v < 70) {
      // Mid-body palm swell
      let t = (v + 35) / 105;
      return 131 + 3 * Math.sin(t * Math.PI);
    } else {
      // Rounded ergonomic rear tail
      let t = Math.min(1, (v - 70) / 160);
      return 131 * Math.cos(t * Math.PI * 0.47);
    }
  }

  // Longitudinal ridge elevation z(v)
  function spineZ(v) {
    if (v < -35) {
      // Sloping front button deck
      let t = Math.max(0, (v + 225) / 190);
      return 20 + 38 * Math.pow(t, 0.84);
    } else if (v < 48) {
      // Rising to palm crown
      let t = (v + 35) / 83;
      return 58 + 12 * Math.sin(t * Math.PI * 0.5);
    } else {
      // Sloping down to rear tail skirt
      let t = Math.min(1, (v - 48) / 182);
      return 70 - 52 * Math.pow(t, 1.35);
    }
  }

  // Full 3D surface elevation domeZ(u, v)
  function domeZ(u, v) {
    let hw = Math.max(10, halfWidth(v));
    let normU = Math.min(1.1, Math.abs(u) / hw);
    let z = spineZ(v) - 15 * Math.pow(normU, 1.85);

    // Subtle concave ergonomic finger scoops on Left and Right buttons
    if (v > -195 && v < -55) {
      let scoopV = Math.sin(((v + 195) / 140) * Math.PI);
      let leftDist = Math.abs(u - (-58)) / 42;
      let rightDist = Math.abs(u - 58) / 42;
      if (leftDist < 1) {
        z -= 4.5 * scoopV * Math.cos(leftDist * Math.PI * 0.5);
      }
      if (rightDist < 1) {
        z -= 4.5 * scoopV * Math.cos(rightDist * Math.PI * 0.5);
      }
    }
    return Math.max(8, z);
  }

  // Lower chassis split line height
  function skirtZ(v) {
    if (v < -35) return 10;
    let t = Math.max(0, (v + 35) / 265);
    return 10 + 4 * Math.sin(t * Math.PI);
  }

  // Build base footprint polygon at z = 0 for shadows
  let footprintPts = [];
  for (let v = -225; v <= 228; v += 14) {
    footprintPts.push(proj(halfWidth(v), v, 0));
  }
  for (let v = 228; v >= -225; v -= 14) {
    footprintPts.push(proj(-halfWidth(v), v, 0));
  }

  // -------------------------------------------------------------------------
  // A. HARD STEPPED CAST SHADOWS OF MOUSE ON TEAL MOUSEPAD (3 TIERS)
  // -------------------------------------------------------------------------
  let mShad3 = makeSteppedPolygon(footprintPts, 54, 62, 12);
  fillMarkerPoly(mShad3, "#004e52", 238, "#004044", 6, -45, 0.45);
  bevelPolygon(mShad3, {
    invert: true,
    lightOuter: "#1caeb3",
    darkOuter: "#00292b",
    doubleBevel: false,
    outerWeight: 0.48
  });

  let mShad2 = makeSteppedPolygon(footprintPts, 34, 40, 10);
  fillMarkerPoly(mShad2, "#002f32", 246, "#002326", 5.5, -45, 0.45);
  bevelPolygon(mShad2, {
    invert: true,
    lightOuter: "#006b70",
    darkOuter: "#031314",
    doubleBevel: false,
    outerWeight: 0.5
  });

  let mShad1 = makeSteppedPolygon(footprintPts, 16, 20, 8);
  fillMarkerPoly(mShad1, "#051416", 252, "#020b0c", 5, -45, 0.45);

  // -------------------------------------------------------------------------
  // B. FRONT SEGMENTED RUBBER STRAIN-RELIEF BOOT (5 BEVELLED RINGS)
  // -------------------------------------------------------------------------
  for (let rIdx = 4; rIdx >= 0; rIdx--) {
    let v0 = -225 - rIdx * 13;
    let v1 = v0 - 10.5;
    let w0 = 26 - rIdx * 2.1;
    let w1 = 26 - (rIdx + 0.8) * 2.1;
    let zBot = 4, zTop = 19 - rIdx * 0.9;

    let ringPoly = [
      proj(-w0, v0, zTop),
      proj(-w1, v1, zTop),
      proj(w1 * 0.2, v1, zTop + 2),
      proj(w1, v1, zBot + 4),
      proj(w1, v1, zBot),
      proj(w0, v0, zBot),
      proj(w0 * 0.2, v0, zTop + 2)
    ];

    // Slightly yellowed warm grey rubber on the strain relief
    let col = rIdx % 2 === 0 ? "#8e928c" : "#7c807a";
    fillMarkerPoly(ringPoly, col, 250, "#6e726c", 4, angleDeg, 0.38);

    // Grime in the slot between strain-relief rings
    let grooveA = proj(-w0 * 0.9, v0, zTop);
    let grooveB = proj(w0 * 0.9, v0, zBot + 3);
    brush.set("charcoal", "#2b251c", 0.55);
    brush.line(grooveA[0], grooveA[1], grooveB[0], grooveB[1]);

    bevelPolygon(ringPoly, {
      lightOuter: "#ffffff",
      lightInner: "#cfd4d0",
      darkInner: "#464a47",
      darkOuter: "#151816",
      outerWeight: 0.62,
      innerWeight: 0.38,
      insetDist: 1.8
    });
  }

  // -------------------------------------------------------------------------
  // C. LOWER CHASSIS SKIRT (COOLER AGED PUTTY-BEIGE ABS PLASTIC)
  // -------------------------------------------------------------------------
  // Visible along the right wall (u > 0) and wrapping around the rear tail
  let vStepsSkirt = [];
  for (let v = -222; v <= 228; v += 15) vStepsSkirt.push(v);

  for (let i = 0; i < vStepsSkirt.length - 1; i++) {
    let v0 = vStepsSkirt[i], v1 = vStepsSkirt[i + 1];
    let hw0 = halfWidth(v0), hw1 = halfWidth(v1);
    let sz0 = skirtZ(v0), sz1 = skirtZ(v1);

    let quadR = [
      proj(hw0, v0, sz0),
      proj(hw1, v1, sz1),
      proj(hw1, v1, 0),
      proj(hw0, v0, 0)
    ];
    let shade = v0 > 90 ? "#8a8170" : "#9e9583";
    fillMarkerPoly(quadR, shade, 250, "#7d7464", 4.5, angleDeg + 90, 0.38);
    bevelPolygon(quadR, {
      lightOuter: "#d6ceb8",
      darkOuter: "#1a1712",
      doubleBevel: false,
      outerWeight: 0.52
    });
  }

  // Rear left-to-right tail skirt wrap
  let tailWrap = [];
  for (let a = -80; a <= 80; a += 16) {
    let t = a / 90;
    let v = 228 - 28 * (t * t);
    let u = t * halfWidth(200);
    tailWrap.push([u, v]);
  }
  for (let i = 0; i < tailWrap.length - 1; i++) {
    let [u0, v0] = tailWrap[i], [u1, v1] = tailWrap[i + 1];
    let q = [
      proj(u0, v0, skirtZ(v0)),
      proj(u1, v1, skirtZ(v1)),
      proj(u1, v1, 0),
      proj(u0, v0, 0)
    ];
    fillMarkerPoly(q, "#827968", 250, "#6e6656", 4, angleDeg, 0.38);
    bevelPolygon(q, {
      lightOuter: "#c4bca8",
      darkOuter: "#171410",
      doubleBevel: false,
      outerWeight: 0.5
    });
  }

  // -------------------------------------------------------------------------
  // D. UPPER SIDE WALL OF MOUSE BODY (WARM YELLOWED OCHRE-BEIGE FACETS)
  // -------------------------------------------------------------------------
  for (let i = 0; i < vStepsSkirt.length - 1; i++) {
    let v0 = vStepsSkirt[i], v1 = vStepsSkirt[i + 1];
    if (v0 < -36) continue; // Front button side wall is drawn with the Right Button
    let hw0 = halfWidth(v0), hw1 = halfWidth(v1);
    let sz0 = skirtZ(v0), sz1 = skirtZ(v1);
    let tz0 = domeZ(hw0, v0), tz1 = domeZ(hw1, v1);

    let sideWallQuad = [
      proj(hw0 * 0.96, v0, tz0),
      proj(hw1 * 0.96, v1, tz1),
      proj(hw1, v1, sz1 + 1.5),
      proj(hw0, v0, sz0 + 1.5)
    ];

    let wallCol = v0 < 60 ? "#bf9e5e" : (v0 < 150 ? "#ab8b4c" : "#94763e");
    let hatchCol = v0 < 60 ? "#b08e4f" : "#826632";
    fillMarkerPoly(sideWallQuad, wallCol, 250, hatchCol, 5, angleDeg + 45, 0.4);
    bevelPolygon(sideWallQuad, {
      lightOuter: "#f5e5be",
      lightInner: "#d9bc80",
      darkInner: "#6e562a",
      darkOuter: "#1c1812",
      outerWeight: 0.58,
      innerWeight: 0.36,
      insetDist: 2
    });

    // Grimy housing split seam between upper shell and lower skirt
    let s1 = proj(hw0, v0, sz0 + 0.8);
    let s2 = proj(hw1, v1, sz1 + 0.8);
    brush.set("rotring", "#1a1510", 0.78);
    brush.line(s1[0], s1[1], s2[0], s2[1]);
    brush.set("charcoal", "#594728", 0.48);
    brush.line(s1[0] - 1, s1[1] - 1, s2[0] - 1, s2[1] - 1);
  }

  // -------------------------------------------------------------------------
  // E. MAIN PALM SHELL (HYPERREAL YELLOWED ABS PLASTIC + STEPPED FACETS)
  // -------------------------------------------------------------------------
  // Outer top deck contour of the main palm shell (v from -33 to +225)
  let palmDeckPts = [];
  for (let v = -33; v <= 222; v += 12) {
    let hw = halfWidth(v) * 0.96;
    palmDeckPts.push(proj(-hw, v, domeZ(-hw, v)));
  }
  for (let v = 222; v >= -33; v -= 12) {
    let hw = halfWidth(v) * 0.96;
    palmDeckPts.push(proj(hw, v, domeZ(hw, v)));
  }

  // Base yellowed beige marker wash across the palm shell
  fillMarkerPoly(palmDeckPts, "#e0c68c", 250, "#d6b97c", 6, angleDeg, 0.48);

  // Build stepped, bevelled tonal zones across the ergonomic dome to capture
  // uneven brominated-ABS UV yellowing (cream-ivory on top-left -> butterscotch -> deep ochre on bottom-right)
  let uBands = [-0.95, -0.52, -0.08, 0.42, 0.95];
  let vBands = [-33, 25, 95, 162, 218];
  let paletteGrid = [
    ["#f2e5c2", "#e8d4a2", "#d9bd7e", "#c2a05c"],
    ["#ede0b8", "#e2c990", "#cfb06c", "#b89450"],
    ["#e6d4a6", "#d6b878", "#c4a058", "#ab8642"],
    ["#d9c492", "#c7a766", "#b28e48", "#997736"]
  ];

  for (let r = 0; r < vBands.length - 1; r++) {
    let v0 = vBands[r], v1 = vBands[r + 1];
    for (let c = 0; c < uBands.length - 1; c++) {
      let uf0 = uBands[c], uf1 = uBands[c + 1];
      let hw0 = halfWidth(v0) * 0.94;
      let hw1 = halfWidth(v1) * 0.94;
      let u00 = uf0 * hw0, u01 = uf1 * hw0;
      let u10 = uf0 * hw1, u11 = uf1 * hw1;

      let patch = [
        proj(u00, v0, domeZ(u00, v0)),
        proj(u01, v0, domeZ(u01, v0)),
        proj(u11, v1, domeZ(u11, v1)),
        proj(u10, v1, domeZ(u10, v1))
      ];

      let baseCol = paletteGrid[r][c];
      fillMarkerPoly(patch, baseCol, 225, baseCol, 5.5, angleDeg + (c - 1.5) * 18, 0.4);

      // Subtle internal facet bevels following 1990s OS bevel logic
      bevelPolygon(patch, {
        lightOuter: "#fff8e6",
        darkOuter: "#8c703c",
        doubleBevel: false,
        outerWeight: 0.35
      });
    }
  }

  // Intense UV-oxidized butterscotch/amber yellowing patch on the central palm crest
  let uvPatch = [];
  for (let a = 0; a < 16; a++) {
    let ang = (a / 16) * Math.PI * 2;
    let u = 18 + Math.cos(ang) * 68;
    let v = 72 + Math.sin(ang) * 64;
    uvPatch.push(proj(u, v, domeZ(u, v)));
  }
  let uvStepped = makeSteppedPolygon(uvPatch, 0, 0, 8);
  fillMarkerPoly(uvStepped, "#cfa658", 165, "#bf9342", 5, angleDeg - 25, 0.38);
  bevelPolygon(uvStepped, {
    lightOuter: "#f5e3b8",
    darkOuter: "#7d5e26",
    doubleBevel: false,
    outerWeight: 0.38
  });

  // Bright top-left specular bevel zone on the upper-left palm shoulder
  let specPatch = [];
  for (let a = 0; a < 14; a++) {
    let ang = (a / 14) * Math.PI * 2;
    let u = -52 + Math.cos(ang) * 42;
    let v = 25 + Math.sin(ang) * 46;
    specPatch.push(proj(u, v, domeZ(u, v)));
  }
  let specStepped = makeSteppedPolygon(specPatch, 0, 0, 7);
  fillMarkerPoly(specStepped, "#f9f0d8", 210, "#fff8e8", 4.5, angleDeg, 0.35);
  bevelPolygon(specStepped, {
    lightOuter: "#ffffff",
    darkOuter: "#b89c64",
    doubleBevel: false,
    outerWeight: 0.45
  });

  // Fine ABS plastic stipple & palm-wear micro-scratches across the shell
  for (let i = 0; i < 95; i++) {
    let v = random(-25, 205);
    let hw = halfWidth(v) * 0.85;
    let u = random(-hw, hw);
    let p = proj(u, v, domeZ(u, v));
    let scLen = random(4, 18);
    let scAng = random(0, Math.PI * 2);
    brush.set(i % 3 === 0 ? "rotring" : "2H", i % 2 === 0 ? "#fff9e8" : "#876b38", 0.28);
    brush.line(p[0], p[1], p[0] + Math.cos(scAng) * scLen, p[1] + Math.sin(scAng) * scLen);
  }

  // Recessed Clerical Brand / Serial Badge on the lower-left palm rest
  let badgePts = [
    proj(-78, 122, domeZ(-78, 122)),
    proj(-18, 122, domeZ(-18, 122)),
    proj(-18, 152, domeZ(-18, 152)),
    proj(-78, 152, domeZ(-78, 152))
  ];
  fillMarkerPoly(badgePts, "#cbb27c", 245, "#bfa46c", 4, angleDeg, 0.35);
  bevelPolygon(badgePts, {
    invert: true,
    lightOuter: "#ffffff",
    lightInner: "#f5e6c4",
    darkInner: "#6e5830",
    darkOuter: "#1c1710",
    outerWeight: 0.6,
    innerWeight: 0.38,
    insetDist: 2.2
  });
  // Crusty grime tucked into the recessed badge corners
  brush.set("charcoal", "#4a3b20", 0.45);
  brush.line(badgePts[0][0] + 2, badgePts[0][1] + 2, badgePts[1][0] - 2, badgePts[1][1] + 2);
  // Crisp geometric block bars inside the badge ("MS-2.0")
  for (let b = 0; b < 4; b++) {
    let bu = -68 + b * 12;
    let bp1 = proj(bu, 134, domeZ(bu, 134));
    let bp2 = proj(bu + 7, 134, domeZ(bu + 7, 134));
    brush.set("rotring", "#544324", 0.52);
    brush.line(bp1[0], bp1[1], bp2[0], bp2[1]);
    brush.set("rotring", "#fff8e4", 0.35);
    brush.line(bp1[0], bp1[1] + 1.5, bp2[0], bp2[1] + 1.5);
  }

  // Strict 1990s OS Bevel around the entire Main Palm Shell perimeter
  bevelPolygon(palmDeckPts, {
    lightOuter: "#ffffff",
    lightInner: "#f7ebd0",
    darkInner: "#785e2e",
    darkOuter: "#1a1610",
    outerWeight: 0.85,
    innerWeight: 0.52,
    insetDist: 3.0
  });

  // -------------------------------------------------------------------------
  // F. DEEP TRANSVERSE & CENTER SEAM TRENCH (BEFORE & AFTER BUTTONS)
  // -------------------------------------------------------------------------
  let seamTrenchTrans = [];
  for (let u = -halfWidth(-35); u <= halfWidth(-35); u += 16) {
    seamTrenchTrans.push(proj(u, -40, domeZ(u, -40) - 4));
  }
  for (let u = halfWidth(-33); u >= -halfWidth(-33); u -= 16) {
    seamTrenchTrans.push(proj(u, -31, domeZ(u, -31) - 4));
  }
  fillMarkerPoly(seamTrenchTrans, "#181410", 255, "#0f0c09", 3, angleDeg, 0.45);

  let seamTrenchCenter = [
    proj(-5.5, -224, 14),
    proj(5.5, -224, 14),
    proj(5.5, -33, 52),
    proj(-5.5, -33, 52)
  ];
  fillMarkerPoly(seamTrenchCenter, "#16120e", 255, "#0d0b08", 3, angleDeg + 90, 0.45);

  // -------------------------------------------------------------------------
  // G. LEFT & RIGHT SCUFFED MOUSE BUTTONS
  // -------------------------------------------------------------------------
  // 1. Right Button Outer Side Wall (u = +halfWidth(v), v from -222 to -36)
  for (let v = -220; v < -38; v += 15) {
    let vNext = Math.min(-38, v + 15);
    let hw0 = halfWidth(v), hw1 = halfWidth(vNext);
    let rWall = [
      proj(hw0 * 0.96, v, domeZ(hw0, v)),
      proj(hw1 * 0.96, vNext, domeZ(hw1, vNext)),
      proj(hw1, vNext, skirtZ(vNext) + 1.5),
      proj(hw0, v, skirtZ(v) + 1.5)
    ];
    fillMarkerPoly(rWall, "#b89656", 250, "#a38244", 4.5, angleDeg + 45, 0.38);
    bevelPolygon(rWall, {
      lightOuter: "#f0dfb6",
      darkOuter: "#1c1710",
      doubleBevel: false,
      outerWeight: 0.52
    });
  }

  // 2. Front Nose Chamfer Wall for Left & Right Buttons (v = -224)
  for (let btnSide of [-1, 1]) {
    let uStart = btnSide === -1 ? -halfWidth(-220) * 0.92 : 4.5;
    let uEnd = btnSide === -1 ? -4.5 : halfWidth(-220) * 0.92;
    let frontWall = [
      proj(uStart, -220, domeZ(uStart, -220)),
      proj(uEnd, -220, domeZ(uEnd, -220)),
      proj(uEnd, -224, 10),
      proj(uStart, -224, 10)
    ];
    fillMarkerPoly(frontWall, btnSide === -1 ? "#e6d2a0" : "#cfb47a", 250, "#bfa46a", 4, angleDeg, 0.38);
    bevelPolygon(frontWall, {
      lightOuter: "#ffffff",
      darkOuter: "#1c1812",
      doubleBevel: false,
      outerWeight: 0.58
    });
  }

  // 3. Left Button Top Deck (u in [-halfWidth(v)*0.96, -4.2], v in [-220, -39])
  let leftBtnPts = [];
  for (let v = -220; v <= -39; v += 14) {
    let u = -halfWidth(v) * 0.96;
    leftBtnPts.push(proj(u, v, domeZ(u, v)));
  }
  for (let u = -halfWidth(-39) * 0.96; u <= -4.2; u += 18) {
    leftBtnPts.push(proj(u, -39, domeZ(u, -39)));
  }
  for (let v = -39; v >= -220; v -= 14) {
    leftBtnPts.push(proj(-4.2, v, domeZ(-4.2, v)));
  }
  for (let u = -4.2; u >= -halfWidth(-220) * 0.96; u -= 18) {
    leftBtnPts.push(proj(u, -220, domeZ(u, -220)));
  }

  fillMarkerPoly(leftBtnPts, "#e8d39e", 250, "#dec68c", 5.5, angleDeg - 10, 0.45);

  // Left button concave finger scoop bevelled well
  let leftWellPts = [];
  for (let a = 0; a < 18; a++) {
    let ang = (a / 18) * Math.PI * 2;
    let u = -58 + Math.cos(ang) * 38;
    let v = -132 + Math.sin(ang) * 62;
    leftWellPts.push(proj(u, v, domeZ(u, v)));
  }
  fillMarkerPoly(leftWellPts, "#d9bf82", 220, "#cca660", 5, angleDeg + 35, 0.38);
  bevelPolygon(leftWellPts, {
    invert: true,
    lightOuter: "#fff9e6",
    darkOuter: "#947840",
    doubleBevel: false,
    outerWeight: 0.42
  });

  // HYPERREAL SCUFFED WEAR PATCH ON LEFT BUTTON (polished shiny spot + finger-oil rim + scratches)
  let leftOilRim = [];
  let leftScuffCore = [];
  let leftGlossSpot = [];
  for (let a = 0; a < 16; a++) {
    let ang = (a / 16) * Math.PI * 2;
    let u1 = -56 + Math.cos(ang) * 31, v1 = -135 + Math.sin(ang) * 48;
    let u2 = -56 + Math.cos(ang) * 23, v2 = -135 + Math.sin(ang) * 37;
    let u3 = -58 + Math.cos(ang) * 13, v3 = -138 + Math.sin(ang) * 22;
    leftOilRim.push(proj(u1, v1, domeZ(u1, v1)));
    leftScuffCore.push(proj(u2, v2, domeZ(u2, v2)));
    leftGlossSpot.push(proj(u3, v3, domeZ(u3, v3)));
  }
  // Yellowish-brown skin-oil patina halo around the worn area
  fillMarkerPoly(makeSteppedPolygon(leftOilRim, 0, 0, 6), "#c29c52", 180, "#b0893e", 4.5, angleDeg, 0.36);
  // Polished lighter ivory-cream worn plastic center
  fillMarkerPoly(makeSteppedPolygon(leftScuffCore, 0, 0, 6), "#f3e7c6", 235, "#faefd2", 4, angleDeg - 20, 0.36);
  // Bright rubbed specular highlight core
  fillMarkerPoly(makeSteppedPolygon(leftGlossSpot, 0, 0, 5), "#fffbf0", 245, "#ffffff", 3.5, angleDeg, 0.32);
  bevelPolygon(makeSteppedPolygon(leftScuffCore, 0, 0, 6), {
    lightOuter: "#ffffff",
    darkOuter: "#997b42",
    doubleBevel: false,
    outerWeight: 0.4
  });

  // Criss-cross micro-scratches, fingernail arcs & scuffs on Left Button
  for (let s = 0; s < 58; s++) {
    let su = -56 + random(-36, 36);
    let sv = -132 + random(-58, 58);
    let sp1 = proj(su, sv, domeZ(su, sv));
    let sa = random(0, Math.PI * 2);
    let sl = random(5, 22);
    let sp2 = [sp1[0] + Math.cos(sa) * sl, sp1[1] + Math.sin(sa) * sl];
    let col = s % 3 === 0 ? "#ffffff" : (s % 3 === 1 ? "#7a6132" : "#a88c54");
    brush.set(s % 4 === 0 ? "rotring" : "2H", col, random(0.26, 0.42));
    brush.line(sp1[0], sp1[1], sp2[0], sp2[1]);
  }

  // Strict 1990s OS Bevel around the Left Button
  bevelPolygon(leftBtnPts, {
    lightOuter: "#ffffff",
    lightInner: "#f9eed2",
    darkInner: "#755c2e",
    darkOuter: "#17140f",
    outerWeight: 0.85,
    innerWeight: 0.5,
    insetDist: 2.8
  });

  // 4. Right Button Top Deck (u in [+4.2, +halfWidth(v)*0.96], v in [-220, -39])
  let rightBtnPts = [];
  for (let v = -220; v <= -39; v += 14) {
    rightBtnPts.push(proj(4.2, v, domeZ(4.2, v)));
  }
  for (let u = 4.2; u <= halfWidth(-39) * 0.96; u += 18) {
    rightBtnPts.push(proj(u, -39, domeZ(u, -39)));
  }
  for (let v = -39; v >= -220; v -= 14) {
    let u = halfWidth(v) * 0.96;
    rightBtnPts.push(proj(u, v, domeZ(u, v)));
  }
  for (let u = halfWidth(-220) * 0.96; u >= 4.2; u -= 18) {
    rightBtnPts.push(proj(u, -220, domeZ(u, -220)));
  }

  fillMarkerPoly(rightBtnPts, "#dbc082", 250, "#cfa65c", 5.5, angleDeg + 12, 0.45);

  // Right button concave finger scoop & secondary scuff spot
  let rightWellPts = [];
  let rightScuffPts = [];
  for (let a = 0; a < 16; a++) {
    let ang = (a / 16) * Math.PI * 2;
    let u1 = 56 + Math.cos(ang) * 35, v1 = -130 + Math.sin(ang) * 58;
    let u2 = 52 + Math.cos(ang) * 18, v2 = -132 + Math.sin(ang) * 30;
    rightWellPts.push(proj(u1, v1, domeZ(u1, v1)));
    rightScuffPts.push(proj(u2, v2, domeZ(u2, v2)));
  }
  fillMarkerPoly(rightWellPts, "#c9a864", 220, "#b8934c", 5, angleDeg - 25, 0.38);
  bevelPolygon(rightWellPts, {
    invert: true,
    lightOuter: "#f7e8c2",
    darkOuter: "#7d6230",
    doubleBevel: false,
    outerWeight: 0.4
  });

  // Secondary worn shiny patch on Right Button
  fillMarkerPoly(makeSteppedPolygon(rightScuffPts, 0, 0, 6), "#ede0ba", 225, "#f7ebd0", 4, angleDeg, 0.35);
  bevelPolygon(makeSteppedPolygon(rightScuffPts, 0, 0, 6), {
    lightOuter: "#ffffff",
    darkOuter: "#8f723b",
    doubleBevel: false,
    outerWeight: 0.38
  });

  // Scuff scratches on Right Button
  for (let s = 0; s < 38; s++) {
    let su = 54 + random(-32, 32);
    let sv = -130 + random(-52, 52);
    let sp1 = proj(su, sv, domeZ(su, sv));
    let sa = random(0, Math.PI * 2);
    let sl = random(4, 18);
    let col = s % 2 === 0 ? "#fff6de" : "#6e5528";
    brush.set("2H", col, random(0.25, 0.4));
    brush.line(sp1[0], sp1[1], sp1[0] + Math.cos(sa) * sl, sp1[1] + Math.sin(sa) * sl);
  }

  // Strict 1990s OS Bevel around the Right Button
  bevelPolygon(rightBtnPts, {
    lightOuter: "#ffffff",
    lightInner: "#f2e2ba",
    darkInner: "#6b5226",
    darkOuter: "#17140f",
    outerWeight: 0.85,
    innerWeight: 0.5,
    insetDist: 2.8
  });

  // -------------------------------------------------------------------------
  // H. HYPERREAL GRIME IN THE SEAMS (T-JUNCTION, BUTTON SPLIT & TRANSVERSE GAP)
  // -------------------------------------------------------------------------
  // 1. Transverse seam grime (v ≈ -36 across full width)
  for (let u = -halfWidth(-36) * 0.94; u <= halfWidth(-36) * 0.94; u += 4.5) {
    let pSeam = proj(u, -36, domeZ(u, -36) - 1.5);
    let pRearLip = proj(u, -32.5, domeZ(u, -32.5) + 0.5);
    let pFrontLip = proj(u, -39, domeZ(u, -39));

    // Deep pitch-dark seam crevice
    brush.set("rotring", "#14100c", 0.72);
    brush.line(pSeam[0] - 2, pSeam[1] - 1, pSeam[0] + 2, pSeam[1] + 1);

    // Crusty oxidized hand-gunk / skin-oil / dust clusters clinging to seam walls
    let gunkCol = (Math.abs(u) < 28 || random() < 0.55) ? "#4a391e" : "#6e562e";
    brush.set("charcoal", gunkCol, random(0.38, 0.68));
    brush.line(
      pFrontLip[0] + random(-2.5, 2.5),
      pFrontLip[1] + random(-2.5, 2.5),
      pSeam[0] + random(-2.5, 2.5),
      pSeam[1] + random(-2.5, 2.5)
    );

    // Tiny pale lint/dead-skin specks trapped in the dark seam
    if (random() < 0.28) {
      brush.set("rotring", "#d4cab2", 0.35);
      brush.line(pSeam[0], pSeam[1], pSeam[0] + random(-2, 2), pSeam[1] + random(-2, 2));
    }

    // Crisp white OS bevel catch-light on the opposing rear palm-shell lip!
    if (u < halfWidth(-36) * 0.65) {
      brush.set("rotring", "#ffffff", 0.58);
      brush.line(pRearLip[0] - 2, pRearLip[1] - 1, pRearLip[0] + 2, pRearLip[1] + 1);
    }
  }

  // 2. Longitudinal center seam grime between Left and Right buttons (u = 0, v in [-220, -36])
  for (let v = -218; v <= -36; v += 4.5) {
    let pCenter = proj(0, v, domeZ(0, v) - 2);
    let pRightLip = proj(4.2, v, domeZ(4.2, v) + 0.5);
    let pLeftLip = proj(-4.2, v, domeZ(-4.2, v));

    // Dark core trench
    brush.set("rotring", "#120e0a", 0.75);
    brush.line(pCenter[0] - 1, pCenter[1] - 2, pCenter[0] + 1, pCenter[1] + 2);

    // Compacted brown/olive-ochre grime along the button gap
    let cCol = (v > -85 || v < -185 || random() < 0.5) ? "#45351b" : "#695129";
    brush.set("charcoal", cCol, random(0.4, 0.7));
    brush.line(
      pLeftLip[0] + random(-2, 2),
      pLeftLip[1] + random(-2, 2),
      pCenter[0] + random(-2, 2),
      pCenter[1] + random(-2, 2)
    );

    if (random() < 0.25) {
      brush.set("rotring", "#cfc4aa", 0.34);
      brush.line(pCenter[0], pCenter[1], pCenter[0] + random(-2, 2), pCenter[1] + random(-2, 2));
    }

    // Crisp white OS bevel highlight along the opposing Right-Button inner edge
    brush.set("rotring", "#ffffff", 0.62);
    brush.line(pRightLip[0] - 1, pRightLip[1] - 2, pRightLip[0] + 1, pRightLip[1] + 2);
  }

  // Extra heavy grime buildup right at the T-junction (u = 0, v = -36)
  let tJunc = proj(0, -36, domeZ(0, -36) - 1);
  for (let k = 0; k < 18; k++) {
    let gx = tJunc[0] + random(-11, 11);
    let gy = tJunc[1] + random(-11, 11);
    brush.set("charcoal", k % 2 === 0 ? "#2e2312" : "#5e4925", random(0.42, 0.72));
    brush.line(gx, gy, gx + random(-4, 4), gy + random(-4, 4));
  }

  // Tiny edge nicks along the front chamfer of the mouse (each bevelled!)
  let nicks = [[-72, -219], [-28, -220], [34, -220]];
  for (let [nu, nv] of nicks) {
    let np = proj(nu, nv, domeZ(nu, nv));
    brush.set("rotring", "#2b2316", 0.55);
    brush.line(np[0] - 4, np[1] - 2, np[0] + 3, np[1] + 1);
    brush.set("rotring", "#ffffff", 0.5);
    brush.line(np[0] - 3, np[1] + 1, np[0] + 4, np[1] + 3);
  }
}

