function drawTitleBarAndFrame() {
  // 1. Outer 3D Raised OS Window Border around entire 1200x1200 canvas
  let outerFrame = [[6, 6], [1194, 6], [1194, 1194], [6, 1194]];
  bevelPolygon(outerFrame, {
    lightOuter: "#ffffff",
    lightInner: "#e6ecef",
    darkInner: "#687075",
    darkOuter: "#121619",
    outerWeight: 1.15,
    innerWeight: 0.78,
    insetDist: 4.5
  });

  // 2. Navy-to-Azure Title-Bar Strip across the top edge (x: 20..1180, y: 20..82)
  let tbX = 20, tbY = 20, tbW = 1160, tbH = 62;
  let slices = 36;
  let sliceW = tbW / slices;

  // Vivid & Saturated Navy (#00007a) -> Royal Cobalt (#0042c4) -> Vivid Azure (#00a6ff)
  let gradientStops = [
    [0, 4, 122],
    [0, 32, 168],
    [0, 76, 212],
    [6, 128, 240],
    [18, 174, 255]
  ];

  function sampleGradHex(t) {
    let pos = t * (gradientStops.length - 1);
    let idx = Math.min(gradientStops.length - 2, Math.floor(pos));
    let f = pos - idx;
    let c0 = gradientStops[idx], c1 = gradientStops[idx + 1];
    let r = Math.round(c0[0] + (c1[0] - c0[0]) * f);
    let g = Math.round(c0[1] + (c1[1] - c0[1]) * f);
    let b = Math.round(c0[2] + (c1[2] - c0[2]) * f);
    return "#" + [r, g, b].map(v => v.toString(16).padStart(2, "0")).join("");
  }

  for (let i = 0; i < slices; i++) {
    let t = i / (slices - 1);
    let col = sampleGradHex(t);
    let nextCol = sampleGradHex(Math.min(1, (i + 1) / (slices - 1)));
    let sx = tbX + i * sliceW;
    let sPts = [
      [sx, tbY],
      [sx + sliceW + 1.5, tbY],
      [sx + sliceW + 1.5, tbY + tbH],
      [sx, tbY + tbH]
    ];
    fillMarkerPoly(sPts, col, 252, nextCol, 5.5, 90, 0.48);

    // Classic 1990s OS pixel-dither cross-ticks between gradient bands
    if (i > 0 && i < slices - 1) {
      brush.set("rotring", nextCol, 0.42);
      for (let dy = 6; dy < tbH - 4; dy += 8) {
        let ox = (dy % 16 === 0) ? -2 : 2;
        brush.line(sx + ox, tbY + dy, sx + ox, tbY + dy + 4);
      }
    }
  }

  // Bevel around the Title-Bar Strip
  let tbPts = [[tbX, tbY], [tbX + tbW, tbY], [tbX + tbW, tbY + tbH], [tbX, tbY + tbH]];
  bevelPolygon(tbPts, {
    invert: true,
    lightOuter: "#ffffff",
    lightInner: "#b8d8eb",
    darkInner: "#00104a",
    darkOuter: "#12161a",
    outerWeight: 0.78,
    innerWeight: 0.48,
    insetDist: 2.5
  });

  // 3. Miniature Pixel-Bevel Mouse Icon on Left of Title Bar (x: 32, y: 29, w: 42, h: 44)
  drawBevelBox(32, 29, 42, 44, {
    fillCol: "#00868a",
    hatchCol: "#00989c",
    hatchDist: 4,
    outerWeight: 0.58,
    innerWeight: 0.35,
    insetDist: 2
  });
  // Mini beige mouse inside icon box
  drawBevelBox(41, 37, 24, 30, {
    fillCol: "#e6d29e",
    hatchCol: "#d4ba7c",
    hatchDist: 3.5,
    outerWeight: 0.52,
    doubleBevel: false
  });
  brush.set("rotring", "#1a1814", 0.5);
  brush.line(41, 48, 65, 48);
  brush.line(53, 37, 53, 48);

  // 4. Crisp Pixel-Block Title Text: "MOUSE.DRV - [PS/2 BALL]"
  drawPixelTitleText(92, 38);

  // 5. Tiny Square Minimize, Maximize & Close Buttons (drawn as stiff little boxes on right)
  let btnSize = 44;
  let btnY = tbY + 9;
  let btnX_Min = 1018;
  let btnX_Max = 1068;
  let btnX_Close = 1124;

  let btns = [
    { x: btnX_Min, type: "min" },
    { x: btnX_Max, type: "max" },
    { x: btnX_Close, type: "close" }
  ];

  for (let b of btns) {
    // Hard stepped shadow of the stiff little box onto the azure title bar
    let bShad = [
      [b.x + 5, btnY + 5],
      [b.x + btnSize + 5, btnY + 5],
      [b.x + btnSize + 5, btnY + btnSize + 5],
      [b.x + 5, btnY + btnSize + 5]
    ];
    fillMarkerPoly(bShad, "#002654", 245, "#001838", 4, 0, 0.4);

    // Stiff little square box with flat marker grey & strict double 90s bevel
    drawBevelBox(b.x, btnY, btnSize, btnSize, {
      fillCol: "#c3cacd",
      hatchCol: "#b6bec2",
      hatchDist: 5,
      hatchAngle: 0,
      lightOuter: "#ffffff",
      lightInner: "#e8eef0",
      darkInner: "#6e767a",
      darkOuter: "#14181b",
      outerWeight: 0.88,
      innerWeight: 0.58,
      insetDist: 3.2
    });

    // Crisp stiff geometric symbols inside each button
    let cx = b.x + btnSize / 2;
    let cy = btnY + btnSize / 2;
    if (b.type === "min") {
      // Thick bottom bar
      drawBevelBox(cx - 10, cy + 6, 20, 6, {
        fillCol: "#1a1e22",
        lightOuter: "#1a1e22",
        darkOuter: "#ffffff",
        doubleBevel: false,
        outerWeight: 0.45
      });
    } else if (b.type === "max") {
      // Stiff little window square with thick top bar
      drawBevelBox(cx - 11, cy - 11, 22, 22, {
        invert: true,
        fillCol: "#c3cacd",
        lightOuter: "#ffffff",
        darkOuter: "#1a1e22",
        doubleBevel: false,
        outerWeight: 0.65
      });
      brush.set("rotring", "#1a1e22", 1.1);
      brush.line(cx - 10, cy - 8, cx + 10, cy - 8);
      brush.line(cx - 10, cy - 5, cx + 10, cy - 5);
    } else if (b.type === "close") {
      // Stiff pixel-stepped 'X' with white bevel drop-highlight
      brush.set("rotring", "#ffffff", 0.85);
      brush.line(cx - 8, cy - 9, cx + 10, cy + 9);
      brush.line(cx + 10, cy - 9, cx - 8, cy + 9);

      brush.set("rotring", "#14181b", 1.05);
      brush.line(cx - 9, cy - 9, cx + 9, cy + 9);
      brush.line(cx + 9, cy - 9, cx - 9, cy + 9);
      brush.line(cx - 8, cy - 9, cx + 10, cy + 9);
      brush.line(cx + 8, cy - 9, cx - 10, cy + 9);
    }
  }

  // 6. Clerical Sub-Header / Status Strip (x: 20..1180, y: 88..126)
  drawBevelBox(20, 88, 1160, 38, {
    fillCol: "#bfc6c9",
    hatchCol: "#b4bcc0",
    hatchDist: 6,
    outerWeight: 0.72,
    innerWeight: 0.45,
    insetDist: 2.5
  });

  // Left clerical menu button bevel boxes ("FILE", "OPTIONS", "CALIBRATE")
  let menuWidths = [86, 112, 128];
  let mx = 30;
  for (let mw of menuWidths) {
    drawBevelBox(mx, 94, mw, 26, {
      fillCol: "#c6cdd0",
      hatchCol: "#bac2c6",
      hatchDist: 5,
      outerWeight: 0.55,
      doubleBevel: false
    });
    // Crisp dark/white bevelled text bar inside menu button
    brush.set("rotring", "#ffffff", 0.55);
    brush.line(mx + 13, 108, mx + mw - 13, 108);
    brush.set("rotring", "#22282c", 0.75);
    brush.line(mx + 12, 106, mx + mw - 14, 106);
    mx += mw + 10;
  }

  // Right sunken status wells in the sub-header strip
  let wellWidths = [165, 185, 220];
  let wx = 1170;
  for (let ww of wellWidths) {
    wx -= ww;
    drawBevelBox(wx, 94, ww, 26, {
