      hatchCol: "#aab2b6",
      hatchDist: 5,
      outerWeight: 0.58,
      innerWeight: 0.35,
      insetDist: 2
    });
    // Status indicator LED box + crisp bar
    drawBevelBox(wx + 8, 100, 14, 14, {
      fillCol: "#00989c",
      hatchCol: "#00b4b8",
      hatchDist: 3,
