    brush.line(wx + 30, 107, wx + ww - 14, 107);
    brush.set("rotring", "#ffffff", 0.45);
    brush.line(wx + 31, 109, wx + ww - 13, 109);
    wx -= 10;
  }
}

// Crisp 1990s bitmap/vector block glyphs for the Title Bar
function drawPixelTitleText(startX, startY) {
  let glyphs = {
    M: [[0,24,0,0],[0,0,9,12],[9,12,18,0],[18,0,18,24]],
    O: [[0,0,16,0],[16,0,16,24],[16,24,0,24],[0,24,0,0]],
    U: [[0,0,0,24],[0,24,16,24],[16,24,16,0]],
    S: [[16,0,0,0],[0,0,0,12],[0,12,16,12],[16,12,16,24],[16,24,0,24]],
    E: [[15,0,0,0],[0,0,0,24],[0,12,12,12],[0,24,15,24]],
    ".": [[2,20,6,20],[6,20,6,24],[6,24,2,24],[2,24,2,20]],
    D: [[0,0,0,24],[0,0,12,0],[12,0,16,5],[16,5,16,19],[16,19,12,24],[12,24,0,24]],
    R: [[0,24,0,0],[0,0,15,0],[15,0,15,12],[15,12,0,12],[8,12,16,24]],
    V: [[0,0,8,24],[8,24,16,0]],
    "-": [[2,12,14,12]],
    "[": [[10,0,2,0],[2,0,2,24],[2,24,10,24]],
    P: [[0,24,0,0],[0,0,15,0],[15,0,15,12],[15,12,0,12]],
    "2": [[0,0,15,0],[15,0,15,12],[15,12,0,12],[0,12,0,24],[0,24,15,24]],
    B: [[0,0,0,24],[0,0,14,0],[14,0,14,12],[0,12,15,12],[15,12,15,24],[15,24,0,24]],
    A: [[0,24,0,6],[0,6,8,0],[8,0,16,6],[16,6,16,24],[0,14,16,14]],
    L: [[0,0,0,24],[0,24,14,24]],
    "]": [[2,0,10,0],[10,0,10,24],[10,24,2,24]]
  };

  let text = "MOUSE.DRV - [PS2 BALL]";
  let cx = startX;
  for (let i = 0; i < text.length; i++) {
    let ch = text[i];
    if (ch === " ") {
      cx += 16;
      continue;
    }
    let segs = glyphs[ch];
    if (segs) {
      // Hard stepped shadow in deep navy-charcoal
      brush.set("rotring", "#00062e", 0.95);
      for (let s of segs) {
        brush.line(cx + s[0] + 2.5, startY + s[1] + 2.5, cx + s[2] + 2.5, startY + s[3] + 2.5);
      }
      // Crisp white pen glyph
      brush.set("rotring", "#ffffff", 0.95);
      for (let s of segs) {
        brush.line(cx + s[0], startY + s[1], cx + s[2], startY + s[3]);
      }
    }
    cx += (ch === "." || ch === "[" || ch === "]") ? 14 : 24;
  }
}

