// State management wrappers to guarantee valid p5.brush state
function useStroke(name, col, weight = 1) {
  brush.noFill();
  brush.noWash();
  brush.noHatch();
  brush.set(name, col, weight);
}

function useWash(col, opacity = 255) {
  brush.noStroke();
  brush.noFill();
  brush.noHatch();
  brush.wash(col, opacity);
}

function useWatercolor(col, opacity = 150, bleed = 0.15, tex = 0.5, border = 0.35) {
  brush.noStroke();
  brush.noWash();
  brush.noHatch();
  brush.fill(col, opacity);
  brush.fillBleed(bleed, "out");
  brush.fillTexture(tex, border);
}

function drawPolyShape(pts, curvature = 0.1, closed = true) {
  brush.beginShape(curvature);
  for (let i = 0; i < pts.length; i++) {
    brush.vertex(pts[i][0], pts[i][1]);
  }
  brush.endShape(closed);
}

// ============================================================================
// CARTOUCHE & GEOMETRY HELPERS
// ============================================================================

// Compute point on the scalloped Ottoman Şemse / Mihrab Cartouche
function getCartouchePt(deg, inset = 0) {
  let cx = 600;
  let cy = 558;
  let rx = 472 - inset;
  let ry = 468 - inset;

  // Base superellipse / ogee curve
  let rad = deg * Math.PI / 180;
  let cosA = Math.cos(rad);
  let sinA = Math.sin(rad);

  // Pointed ogee crown at top (-90 deg) and bottom (+90 deg)
  let crownPinch = Math.pow(Math.abs(sinA), 3.2) * 26;
  // 20 scalloped lobes around the perimeter
  let lobe = Math.cos(20 * rad) * (9.5 - inset * 0.08);
  // Subtle waist indentation at 0 and 180 deg, plus medallions
  let medallion = Math.pow(Math.abs(cosA), 12) * 16;

  let rMod = 1.0 + (lobe + crownPinch + medallion) / 470;
  let x = cx + cosA * rx * rMod;
  let y = cy + sinA * ry * rMod;
  return [x, y];
}

function getCartouchePolygon(inset = 0, steps = 240) {
  let pts = [];
  for (let i = 0; i < steps; i++) {
    let deg = (i / steps) * 360;
    pts.push(getCartouchePt(deg, inset));
  }
  return pts;
}

function getEllipsePolygon(cx, cy, rx, ry, steps = 90, rotDeg = 0) {
  let pts = [];
  let rotRad = rotDeg * Math.PI / 180;
  let cR = Math.cos(rotRad);
  let sR = Math.sin(rotRad);
  for (let i = 0; i < steps; i++) {
    let a = (i / steps) * Math.PI * 2;
    let ex = Math.cos(a) * rx;
    let ey = Math.sin(a) * ry;
    pts.push([
      cx + ex * cR - ey * sR,
      cy + ex * sR + ey * cR
    ]);
  }
  return pts;
}

