async function setup() {
  createCanvas(1200, 1200, WEBGL);
  brush.scaleBrushes(3);
  angleMode(DEGREES);
  randomSeed(7819);
  noiseSeed(7819);

  // Custom ultra-fine liner & dry texture brushes for hyperreal rendering
  brush.add("tahrir", {
    type: "default",
    weight: 0.32,
    scatter: 0.02,
    sharpness: 0.92,
    grain: 0.1,
    opacity: 230,
    spacing: 0.12,
    pressure: [0.7, 1.0, 0.7],
    noise: 0.15
  });

  brush.add("gild", {
    type: "default",
    weight: 0.55,
    scatter: 0.08,
    sharpness: 0.8,
    grain: 0.35,
    opacity: 200,
    spacing: 0.15,
    pressure: [0.4, 1.15, 0.3],
    noise: 0.25
  });

  brush.add("glaze", {
    type: "marker",
    weight: 2.2,
    scatter: 0.15,
    opacity: 32,
    spacing: 0.25,
    pressure: [0.7, 1.0, 0.7],
    markerTip: false,
    noise: 0.1
  });

  brush.add("burnish", {
    type: "default",
    weight: 0.8,
    scatter: 0.12,
    sharpness: 0.65,
    grain: 0.45,
    opacity: 140,
    spacing: 0.18,
    pressure: [0.3, 1.0, 0.3],
    noise: 0.3
  });
}

function draw() {
  translate(-width / 2, -height / 2);
  background(PAL.abyss);
  brush.noField();

  // 1. Outer Twilight Margin, Corner Spandrels & Lapis Lazuli Cartouche Ground
  renderOuterMarginAndSpandrels();
  renderLapisCartoucheGround();

  // 2. Tezhip Illumination: Helezon Spirals, Rumi & Hatayi Scrollwork + Cetvel Rules
  renderTezhipScrollwork();
  renderCartoucheCetvelFrame();

  // 3. The Scratched Walnut Tray
  renderWalnutTray();

  // 4. The Dented Hammered Brass Cezve & Turned Handle
  renderBrassCezve();

  // 5. The Porcelain Fincan, Saucer, Bubbling Crema & Clinging Grounds
  renderPorcelainFincanAndCoffee();

  // 6. Fragrant Meditative Steam & Final Specular Jewels
  renderFragrantSteamAndFinalGlints();

  noLoop();
}

// ============================================================================
// 1. OUTER MARGIN, SPANDRELS & LAPIS LAZULI WATERCOLOR GROUND
// ============================================================================

function renderOuterMarginAndSpandrels() {
  // Deep twilight wash over the whole manuscript page
  useWash(PAL.marginGround, 220);
  brush.rect(0, 0, 1200, 1200, "corner");

  // Spandrel ground inside the rectangular cetvel box (64..1136)
  useWatercolor(PAL.spandrelDark, 210, 0.12, 0.55, 0.35);
  brush.rect(64, 64, 1072, 1072, "corner");

  useWatercolor(PAL.spandrelPlum, 130, 0.2, 0.6, 0.4);
  brush.rect(76, 76, 1048, 1048, "corner");

  // Subtle twilight paper texture across outer margins
  useStroke("2B", "#1c2642", 0.35);
  for (let i = 0; i < 240; i++) {
    let side = i % 4;
    let x1, y1, len = random(30, 90);
    if (side === 0) { x1 = random(20, 1180); y1 = random(10, 58); }
    else if (side === 1) { x1 = random(20, 1180); y1 = random(1142, 1190); }
    else if (side === 2) { x1 = random(10, 58); y1 = random(20, 1180); }
    else { x1 = random(1142, 1190); y1 = random(20, 1180); }
    brush.line(x1, y1, x1 + random(-len, len) * 0.4, y1 + random(-len, len) * 0.4);
  }

  // Corner spandrel (Köşebent) arabesque scrollwork in the 4 corners
  const corners = [
    { cx: 165, cy: 165, sx: 1, sy: 1 },
    { cx: 1035, cy: 165, sx: -1, sy: 1 },
    { cx: 165, cy: 1035, sx: 1, sy: -1 },
    { cx: 1035, cy: 1035, sx: -1, sy: -1 }
  ];

  for (let c of corners) {
    drawCornerSpandrelOrnament(c.cx, c.cy, c.sx, c.sy);
  }
}

function drawCornerSpandrelOrnament(cx, cy, sx, sy) {
  // Spiral cloud-band & rumi vines filling the corner triangle
  let sPts1 = [];
  let sPts2 = [];
  for (let t = 0; t <= 55; t++) {
    let a = (t / 55) * Math.PI * 2.6;
    let r = 85 * (1 - t / 68);
    sPts1.push([
      cx + sx * (Math.cos(a) * r + 15),
      cy + sy * (Math.sin(a) * r + 15),
      0.5 + 0.5 * Math.sin((t / 55) * Math.PI)
    ]);
    let r2 = 52 * (1 - t / 65);
    sPts2.push([
      cx + sx * (95 + Math.cos(a + 1.2) * r2),
      cy + sy * (-10 + Math.sin(a + 1.2) * r2),
      0.4 + 0.5 * Math.sin((t / 55) * Math.PI)
    ]);
  }
  useStroke("gild", PAL.ochreMid, 0.9);
  brush.spline(sPts1, 0.5);
  brush.spline(sPts2, 0.5);

  useStroke("tahrir", PAL.goldBright, 0.7);
  brush.spline(sPts1, 0.5);

  // Corner hatayi rosette at center of spiral
  drawHatayiBlossom(cx + sx * 15, cy + sy * 15, 22, 45 * sx * sy, PAL.cinnabar, PAL.goldBright);
  drawHatayiBlossom(cx + sx * 95, cy - sy * 10, 15, 20 * sx * sy, PAL.lapisBright, PAL.goldAntique);
  drawHatayiBlossom(cx - sx * 10, cy + sy * 95, 15, 70 * sx * sy, PAL.lapisBright, PAL.goldAntique);

  // Rumi leaves along corner diagonal
  for (let k = 0; k < 5; k++) {
    let ang = (k * 72 + 25) * (Math.PI / 180);
    let rx = cx + sx * (15 + Math.cos(ang) * 48);
    let ry = cy + sy * (15 + Math.sin(ang) * 48);
    drawRumiLeaf(rx, ry, 14, k * 72 + 60, sx);
  }
}

function renderLapisCartoucheGround() {
  // Multi-layered deep lapis lazuli watercolor washes inside the cartouche
  let polyOuter = getCartouchePolygon(0, 180);
  let polyMid = getCartouchePolygon(18, 160);
  let polyInner = getCartouchePolygon(45, 140);

  // Solid base wash so spandrels don't bleed through
  useWash(PAL.twilightDark, 250);
  drawPolyShape(polyOuter, 0.05, true);

  // Deep lapis watercolor pass 1
  useWatercolor(PAL.lapisDeep, 210, 0.18, 0.65, 0.45);
  drawPolyShape(polyMid, 0.08, true);

  // Rich ultramarine/lapis pass 2
  useWatercolor(PAL.lapisMid, 155, 0.24, 0.7, 0.5);
  drawPolyShape(polyInner, 0.1, true);

  // Upper luminous twilight lapis glow behind the scrollwork
  let upperGlowPts = getEllipsePolygon(600, 420, 340, 250, 70);
  useWatercolor(PAL.lapisBright, 95, 0.3, 0.6, 0.3);
  drawPolyShape(upperGlowPts, 0.2, true);

  // Deep abyssal vignette in lower cartouche to ground the walnut tray
  let lowerVignettePts = getEllipsePolygon(600, 770, 390, 210, 70);
  useWatercolor(PAL.abyss, 140, 0.28, 0.5, 0.3);
  drawPolyShape(lowerVignettePts, 0.2, true);

  // Lapis mineral lazurite granulation & cross-hatched mineral sheen
  useStroke("2B", PAL.lapisBright, 0.35);
  for (let i = 0; i < 420; i++) {
    let a = random(360) * Math.PI / 180;
    let r = Math.sqrt(random()) * 410;
    let x = 600 + Math.cos(a) * r * 0.95;
    let y = 540 + Math.sin(a) * r * 0.95;
    let ang = random(-30, 30) * Math.PI / 180;
    let len = random(6, 22);
    brush.line(x, y, x + Math.cos(ang) * len, y + Math.sin(ang) * len);
  }

  // Zer-efşan (traditional Ottoman gold leaf dust sprinkled on lapis ground)
  useStroke("spray", PAL.goldAntique, 0.45);
  for (let i = 0; i < 90; i++) {
    let a = random(360) * Math.PI / 180;
    let r = random(60, 420);
    let x = 600 + Math.cos(a) * r * 0.94;
    let y = 470 + Math.sin(a) * r * 0.85;
    brush.line(x, y, x + random(-8, 8), y + random(-8, 8));
  }

  useStroke("tahrir", PAL.goldPale, 0.55);
  for (let i = 0; i < 220; i++) {
    let a = random(360) * Math.PI / 180;
    let r = random(30, 425);
    let x = 600 + Math.cos(a) * r * 0.93;
    let y = 480 + Math.sin(a) * r * 0.88;
    brush.circle(x, y, random(0.4, 1.3), 0.1);
  }
}

// ============================================================================
// 2. TEZHIP ILLUMINATION: RUMI & HATAYI SCROLLWORK + CETVEL RULES
// ============================================================================

function renderTezhipScrollwork() {
  // Symmetrical Helezon (spiral scroll) definitions in the upper & side cartouche field
  // Each spiral has (cx, cy, rStart, rEnd, turns, startDeg, dir)
  const spirals = [
    // Primary Grand Crown Spirals (Upper center-left & right)
    { cx: 470, cy: 315, r0: 138, r1: 12, turns: 2.35, a0: -75, dir: 1, primary: true },
    { cx: 730, cy: 315, r0: 138, r1: 12, turns: 2.35, a0: 255, dir: -1, primary: true },

    // Upper Apex Finial Spirals
    { cx: 538, cy: 185, r0: 66, r1: 8, turns: 1.85, a0: 110, dir: -1, primary: false },
    { cx: 662, cy: 185, r0: 66, r1: 8, turns: 1.85, a0: 70, dir: 1, primary: false },

    // Mid-Flank Spirals (framing the cezve and coffee cup)
    { cx: 295, cy: 465, r0: 112, r1: 10, turns: 2.15, a0: -25, dir: -1, primary: true },
    { cx: 905, cy: 465, r0: 112, r1: 10, turns: 2.15, a0: 205, dir: 1, primary: true },

    // Inner Medallion Spirals (directly above the tray horizon)
    { cx: 495, cy: 525, r0: 84, r1: 9, turns: 1.9, a0: -110, dir: 1, primary: false },
    { cx: 705, cy: 525, r0: 84, r1: 9, turns: 1.9, a0: 290, dir: -1, primary: false },

    // Lower Wing Spirals (flanking the walnut tray left & right)
    { cx: 245, cy: 675, r0: 82, r1: 9, turns: 1.85, a0: -45, dir: 1, primary: false },
    { cx: 955, cy: 675, r0: 82, r1: 9, turns: 1.85, a0: 225, dir: -1, primary: false }
  ];

  // Pass 1: Draw the layered ochre and burnished gold spiral vines (Helezon)
  for (let sp of spirals) {
    let steps = 95;
    let ptsMain = [];
    let ptsEcho = [];
    for (let i = 0; i <= steps; i++) {
      let t = i / steps;
      let ang = (sp.a0 + sp.dir * t * sp.turns * 360) * Math.PI / 180;
      let r = lerp(sp.r0, sp.r1, Math.pow(t, 0.88));
      let x = sp.cx + Math.cos(ang) * r;
      let y = sp.cy + Math.sin(ang) * r;
      let p = 0.4 + 0.8 * Math.sin(t * Math.PI);
      ptsMain.push([x, y, p]);
      ptsEcho.push([
        sp.cx + Math.cos(ang) * (r + 3.2),
        sp.cy + Math.sin(ang) * (r + 3.2),
        p * 0.7
      ]);
    }

    // Ochre under-drawing
    useStroke("gild", PAL.ochreDark, sp.primary ? 1.5 : 1.15);
    brush.spline(ptsMain, 0.5);

    // Rich gold mid-layer
    useStroke("gild", PAL.goldAntique, sp.primary ? 1.05 : 0.85);
    brush.spline(ptsMain, 0.5);

    // Secondary delicate parallel gold vine
    useStroke("tahrir", PAL.ochreLight, 0.65);
    brush.spline(ptsEcho, 0.5);

    // Bright gold-yellow highlight along the spine
    useStroke("tahrir", PAL.goldBright, 0.6);
    brush.spline(ptsMain, 0.5);

    // Hair-fine cinnabar tahrir accent along outer curve of primary spirals
    if (sp.primary) {
      useStroke("tahrir", PAL.cinnabar, 0.42);
      brush.spline(ptsEcho, 0.5);
    }

    // Populate Rumi split-leaves & Hatayi blossoms along the spiral
    let numNodes = sp.primary ? 9 : 6;
    for (let k = 1; k <= numNodes; k++) {
      let t = k / (numNodes + 0.6);
      let angDeg = sp.a0 + sp.dir * t * sp.turns * 360;
      let ang = angDeg * Math.PI / 180;
      let r = lerp(sp.r0, sp.r1, Math.pow(t, 0.88));
      let nx = sp.cx + Math.cos(ang) * r;
      let ny = sp.cy + Math.sin(ang) * r;
      let tangentDeg = angDeg + sp.dir * 90;

      // Alternate Rumi split-leaf and Hatayi / Penç buds along the scroll
      let scale = map(t, 0, 1, sp.primary ? 22 : 16, 9);
      if (k % 2 === 1) {
        drawRumiLeaf(nx, ny, scale, tangentDeg + sp.dir * 28, sp.dir);
        // Small opposing leaf-bud (hurde rumi)
        drawRumiLeaf(nx, ny, scale * 0.62, tangentDeg - sp.dir * 38, -sp.dir);
      } else {
        let accentCol = (k % 4 === 0) ? PAL.cinnabar : PAL.turquoise;
        drawHatayiBlossom(nx, ny, scale * 0.95, tangentDeg, accentCol, PAL.goldBright);
      }
    }

    // Center terminal Hatayi blossom at the eye of each spiral
    drawHatayiBlossom(
      sp.cx,
      sp.cy,
      sp.primary ? 24 : 18,
      sp.dir * 15,
      sp.primary ? PAL.cinnabarBright : PAL.turquoise,
      PAL.goldPale
    );
  }

  // Central Axis Symmetry Medallions (Crown Tepelik at top, Bridge Medallion in center)
  drawCentralShimseCrown(600, 148, 36);
  drawCentralShimseCrown(600, 275, 44);
  drawCentralShimseCrown(600, 425, 34);

  // Delicate three-dot Çintemani pearl & cinnabar clusters in the lapis intervals
  const cintemaniPts = [
    [600, 212], [535, 245], [665, 245], [415, 220], [785, 220],
    [355, 365], [845, 365], [600, 355], [415, 425], [785, 425],
    [225, 565], [975, 565], [345, 575], [855, 575], [600, 490]
  ];
  for (let pt of cintemaniPts) {
    drawCintemaniCluster(pt[0], pt[1], 4.2);
  }
}

// Draw an authentic Ottoman Rumi split-leaf (almond wing motif with internal hurde lines)
function drawRumiLeaf(x, y, size, deg, flip = 1) {
  let rad = deg * Math.PI / 180;
  let c = Math.cos(rad);
  let s = Math.sin(rad);

  const tf = (lx, ly) => [
    x + lx * c - (ly * flip) * s,
    y + lx * s + (ly * flip) * c
  ];

  // Outer wing contour
  let wingPts = [
    tf(0, 0),
    tf(size * 0.35, -size * 0.42),
    tf(size * 0.85, -size * 0.32),
    tf(size * 1.25, size * 0.08),
    tf(size * 0.95, size * 0.38),
    tf(size * 0.45, size * 0.22),
    tf(0, 0)
  ];

  // Ochre & gold wash fill
  useWash(PAL.ochreMid, 185);
  drawPolyShape(wingPts, 0.25, true);

  // Inner swollen almond (ortabağ / hurde core)
  let corePts = [
    tf(size * 0.2, -size * 0.05),
    tf(size * 0.55, -size * 0.2),
    tf(size * 0.85, 0),
    tf(size * 0.55, size * 0.14)
  ];
  useWash(PAL.goldBright, 210);
  drawPolyShape(corePts, 0.2, true);

  // Fine gold pen shading veins
  useStroke("gild", PAL.goldPale, 0.6);
  brush.spline([tf(size * 0.15, 0), tf(size * 0.65, -size * 0.14), tf(size * 1.15, size * 0.06)], 0.4);

  // Hair-fine cinnabar & pearl tahrir contour
  useStroke("tahrir", PAL.cinnabar, 0.45);
  drawPolyShape(wingPts, 0.25, true);

  useStroke("tahrir", PAL.pearlWhite, 0.35);
  brush.spline([tf(size * 0.2, -size * 0.32), tf(size * 0.75, -size * 0.28), tf(size * 1.18, size * 0.05)], 0.4);

  // Tiny curled cleft tip
  let tip = tf(size * 1.25, size * 0.08);
  useStroke("tahrir", PAL.goldPale, 0.55);
  brush.circle(tip[0], tip[1], 1.4, 0.1);
}

// Draw an Ottoman Hatayi / Penç multi-layered floral blossom
function drawHatayiBlossom(cx, cy, radius, rotDeg, centerCol, rimCol) {
  let petals = 6;

  // Outer scalloped gold halo petals
  for (let i = 0; i < petals; i++) {
    let a = (rotDeg + i * (360 / petals)) * Math.PI / 180;
    let aL = a - 0.38;
    let aR = a + 0.38;
    let rOut = radius;
    let rMid = radius * 0.72;

    let pPts = [
      [cx + Math.cos(a) * (radius * 0.2), cy + Math.sin(a) * (radius * 0.2)],
      [cx + Math.cos(aL) * rMid, cy + Math.sin(aL) * rMid],
      [cx + Math.cos(a) * rOut, cy + Math.sin(a) * rOut],
      [cx + Math.cos(aR) * rMid, cy + Math.sin(aR) * rMid]
    ];

    useWash(PAL.ochreMid, 200);
    drawPolyShape(pPts, 0.3, true);

    // Gold inner petal wash
    let pInner = [
      [cx + Math.cos(a) * (radius * 0.22), cy + Math.sin(a) * (radius * 0.22)],
      [cx + Math.cos(a - 0.22) * (radius * 0.55), cy + Math.sin(a - 0.22) * (radius * 0.55)],
      [cx + Math.cos(a) * (radius * 0.82), cy + Math.sin(a) * (radius * 0.82)],
      [cx + Math.cos(a + 0.22) * (radius * 0.55), cy + Math.sin(a + 0.22) * (radius * 0.55)]
    ];
    useWash(PAL.goldAntique, 220);
    drawPolyShape(pInner, 0.25, true);

    // Radial gold-yellow pen veins inside petal
    useStroke("tahrir", rimCol, 0.5);
    brush.line(
      cx + Math.cos(a) * (radius * 0.28),
      cy + Math.sin(a) * (radius * 0.28),
      cx + Math.cos(a) * (radius * 0.88),
      cy + Math.sin(a) * (radius * 0.88)
    );

    // Hair-fine cinnabar & white contour rule around each petal
    useStroke("tahrir", PAL.cinnabarDark, 0.45);
    drawPolyShape(pPts, 0.3, true);

    useStroke("tahrir", PAL.pearlWhite, 0.32);
    brush.arc(
      cx + Math.cos(a) * (radius * 0.55),
      cy + Math.sin(a) * (radius * 0.55),
      radius * 0.36,
      rotDeg + i * (360 / petals) - 45,
      rotDeg + i * (360 / petals) + 45
    );
  }

  // Jewel-like center ovary (cinnabar or turquoise with gold & pearl anthers)
  let cRing = getEllipsePolygon(cx, cy, radius * 0.34, radius * 0.34, 24);
  useWash(centerCol, 240);
  drawPolyShape(cRing, 0.15, true);

  useStroke("tahrir", PAL.goldPale, 0.65);
  brush.circle(cx, cy, radius * 0.35, 0.08);

  useStroke("tahrir", PAL.pearlWhite, 0.55);
  brush.circle(cx, cy, radius * 0.14, 0.05);
}

// Draw a symmetrical Ottoman Tepelik / Crown medallion on the vertical axis
function drawCentralShimseCrown(cx, cy, r) {
  // Lobed diamond-almond medallion
  let pts = [];
  for (let i = 0; i < 36; i++) {
    let a = (i / 36) * Math.PI * 2;
    let lobe = 1 + 0.18 * Math.cos(8 * a);
    let rx = r * 1.15 * lobe;
    let ry = r * 0.85 * lobe;
    pts.push([cx + Math.cos(a) * rx, cy + Math.sin(a) * ry]);
  }
  useWash(PAL.ochreDark, 215);
  drawPolyShape(pts, 0.2, true);

  useStroke("gild", PAL.goldBright, 0.9);
  drawPolyShape(pts, 0.2, true);

  useStroke("tahrir", PAL.cinnabarBright, 0.5);
  drawPolyShape(pts, 0.2, true);

  // Flanked by twin symmetrical Rumi wings
  drawRumiLeaf(cx - r * 0.2, cy, r * 0.85, -145, -1);
  drawRumiLeaf(cx + r * 0.2, cy, r * 0.85, -35, 1);

  drawHatayiBlossom(cx, cy, r * 0.68, 0, PAL.cinnabar, PAL.goldPale);
}

function drawCintemaniCluster(cx, cy, r) {
  const offsets = [
    [0, -r * 1.15],
    [-r * 1.05, r * 0.75],
    [r * 1.05, r * 0.75]
  ];
  for (let off of offsets) {
    let px = cx + off[0];
    let py = cy + off[1];
    let pPoly = getEllipsePolygon(px, py, r, r, 14);
    useWash(PAL.goldBright, 230);
    drawPolyShape(pPoly, 0.1, true);
    useStroke("tahrir", PAL.cinnabarBright, 0.45);
    brush.circle(px, py, r, 0.05);
    useStroke("tahrir", PAL.pearlWhite, 0.45);
    brush.circle(px - r * 0.25, py - r * 0.25, r * 0.35, 0.05);
  }
}

// Render the jeweller-tight Cetvel (ruling lines) & Zencirek braided cartouche frame
function renderCartoucheCetvelFrame() {
  // 1. Outer rectangular manuscript Cetvel frame (x: 56..1144, y: 56..1144)
  // Gold band fill between 58 and 68
  useStroke("gild", PAL.goldAntique, 2.2);
  brush.rect(63, 63, 1074, 1074, "corner");

  useStroke("tahrir", PAL.goldBright, 1.1);
  brush.rect(63, 63, 1074, 1074, "corner");

  // Hair-fine black tahrir, cinnabar, and white contour rules
  useStroke("tahrir", PAL.tahrirInk, 0.75);
  brush.rect(58, 58, 1084, 1084, "corner");
  brush.rect(68, 68, 1064, 1064, "corner");

  useStroke("tahrir", PAL.cinnabarBright, 0.65);
  brush.rect(53, 53, 1094, 1094, "corner");
  brush.rect(73, 73, 1054, 1054, "corner");

  useStroke("tahrir", PAL.pearlWhite, 0.55);
  brush.rect(49, 49, 1102, 1102, "corner");
  brush.rect(77, 77, 1046, 1046, "corner");

  // Delicate Tığ (spear-finials) radiating into the outer margin
  for (let i = 0; i <= 16; i++) {
    let pos = 120 + i * 60;
    let len = (i % 2 === 0) ? 28 : 16;
    let col = (i % 2 === 0) ? PAL.goldBright : PAL.lapisBright;
    useStroke("tahrir", col, 0.55);
    // Top & bottom
    brush.line(pos, 47, pos, 47 - len);
    brush.line(pos, 1153, pos, 1153 + len);
    // Left & right
    brush.line(47, pos, 47 - len, pos);
    brush.line(1153, pos, 1153 + len, pos);

    useStroke("tahrir", PAL.cinnabarBright, 0.5);
    brush.circle(pos, 47 - len * 0.55, 1.8, 0.05);
    brush.circle(pos, 1153 + len * 0.55, 1.8, 0.05);
    brush.circle(47 - len * 0.55, pos, 1.8, 0.05);
    brush.circle(1153 + len * 0.55, pos, 1.8, 0.05);
  }

  // 2. Scalloped Cartouche Multi-Rule Border (Cetvel & Zencirek)
  let ringOuterWhite = getCartouchePolygon(-9, 240);
  let ringOuterCin = getCartouchePolygon(-5, 240);
  let ringGoldOut = getCartouchePolygon(0, 240);
  let ringGoldMid = getCartouchePolygon(7, 240);
  let ringGoldIn = getCartouchePolygon(14, 240);
  let ringInnerCin = getCartouchePolygon(19, 240);
  let ringInnerWhite = getCartouchePolygon(23, 240);

  // Gold ribbon body along the cartouche perimeter
  useStroke("gild", PAL.ochreMid, 2.8);
  drawPolyShape(ringGoldMid, 0.15, true);

  useStroke("gild", PAL.goldAntique, 1.9);
  drawPolyShape(ringGoldMid, 0.15, true);

  useStroke("tahrir", PAL.goldBright, 1.0);
  drawPolyShape(ringGoldOut, 0.15, true);
  drawPolyShape(ringGoldIn, 0.15, true);

  // Dark ink tahrir edges of gold ribbon
  useStroke("tahrir", PAL.tahrirInk, 0.7);
  drawPolyShape(ringGoldOut, 0.15, true);
  drawPolyShape(ringGoldIn, 0.15, true);

  // Hair-fine Cinnabar contour rules
  useStroke("tahrir", PAL.cinnabarBright, 0.72);
  drawPolyShape(ringOuterCin, 0.15, true);
  drawPolyShape(ringInnerCin, 0.15, true);

  // Hair-fine Pearl White contour rules
  useStroke("tahrir", PAL.pearlWhite, 0.58);
  drawPolyShape(ringOuterWhite, 0.15, true);
  drawPolyShape(ringInnerWhite, 0.15, true);

  // Zencirek (braided gold chain & jewel dots) along the cartouche ribbon
  for (let i = 0; i < 160; i++) {
    let deg = (i / 160) * 360;
    let pt = getCartouchePt(deg, 7);
    if (i % 2 === 0) {
      useStroke("tahrir", PAL.goldPale, 0.65);
      brush.circle(pt[0], pt[1], 2.4, 0.05);
    } else {
      useStroke("tahrir", PAL.cinnabarBright, 0.6);
      brush.circle(pt[0], pt[1], 1.6, 0.05);
    }
  }

  // Jewel studs on the 20 scallop cusps
  for (let i = 0; i < 20; i++) {
    let deg = i * 18;
    let pOut = getCartouchePt(deg, -15);
    drawCintemaniCluster(pOut[0], pOut[1], 2.8);
  }
}

