function renderWalnutTray() {
  const tCx = 600;
  const tCy = 865;
  const outerRx = 456;
  const outerRy = 148;
  const innerRx = 414;
  const innerRy = 124;

  // 1. Deep cast shadow of the tray over the lower cartouche & lapis field
  for (let k = 4; k >= 0; k--) {
    let sPoly = getEllipsePolygon(tCx + 8, tCy + 20 + k * 5, outerRx + k * 7, outerRy + k * 4, 90);
    useWash(PAL.abyss, 65);
    drawPolyShape(sPoly, 0.15, true);
  }

  // 2. Outer molded walnut tray rim & bevel
  let rimUnderPoly = getEllipsePolygon(tCx, tCy + 12, outerRx, outerRy, 100);
  useWash(PAL.walnutVoid, 250);
  drawPolyShape(rimUnderPoly, 0.15, true);

  let rimTopPoly = getEllipsePolygon(tCx, tCy, outerRx, outerRy, 100);
  useWash(PAL.walnutDark, 245);
  drawPolyShape(rimTopPoly, 0.15, true);

  // Warm walnut watercolor richness on the tray bed
  let bedPoly = getEllipsePolygon(tCx, tCy + 5, innerRx, innerRy, 100);
  useWatercolor(PAL.walnutMid, 210, 0.12, 0.65, 0.4);
  drawPolyShape(bedPoly, 0.15, true);

  // 3. Inner molded wall of the tray rim (lit on back/right, shadowed on front/left)
  for (let i = 0; i < 180; i++) {
    let deg = i * 2;
    let rad = deg * Math.PI / 180;
    let x1 = tCx + Math.cos(rad) * outerRx;
    let y1 = tCy + Math.sin(rad) * outerRy;
    let x2 = tCx + Math.cos(rad) * innerRx;
    let y2 = (tCy + 6) + Math.sin(rad) * innerRy;

    // Grazing light hits the back-right inner wall (deg in 220..350)
    let lightFactor = Math.sin((deg - 200) * Math.PI / 180);
    let col = PAL.walnutDeep;
    if (lightFactor > 0.5) col = PAL.walnutAmber;
    else if (lightFactor > 0.1) col = PAL.walnutWarm;
    else if (lightFactor > -0.3) col = PAL.walnutMid;

    useStroke("2B", col, 1.3);
    brush.line(x1, y1, x2, y2);
  }

  // 4. Hyperreal Walnut Cathedral Wood Grain across the sunken tray surface
  for (let row = -118; row <= 118; row += 1.6) {
    let yNorm = row / innerRy;
    if (Math.abs(yNorm) >= 0.99) continue;
    let halfW = innerRx * Math.sqrt(1 - yNorm * yNorm);
    let yBase = tCy + 6 + row;

    // Create segmented grain lines with cathedral arches & heartwood knots
    let pts = [];
    let steps = 28;
    for (let s = 0; s <= steps; s++) {
      let xFrac = (s / steps) * 2 - 1;
      let px = tCx + xFrac * (halfW - 4);
      // Cathedral arch distortion around two wood knots at (-140, +15) and (+170, -20)
      let d1 = Math.hypot((px - 450) * 0.35, (yBase - 880) * 1.2);
      let d2 = Math.hypot((px - 770) * 0.35, (yBase - 845) * 1.2);
      let arch = Math.sin(d1 * 0.09) * 4.5 * Math.exp(-d1 * 0.008)
               + Math.cos(d2 * 0.08) * 3.8 * Math.exp(-d2 * 0.008);
      let py = yBase + arch + (noise(px * 0.008, yBase * 0.03) - 0.5) * 5;
      pts.push([px, py, 0.5 + 0.5 * (1 - Math.abs(xFrac))]);
    }

    // Alternate dark walnut pores and warm amber heartwood bands
    let bandVal = Math.sin(row * 0.28 + noise(row * 0.1) * 4);
    let grainCol = PAL.walnutDark;
    let w = 0.65;
    if (bandVal > 0.55) { grainCol = PAL.walnutAmber; w = 0.55; }
    else if (bandVal > 0.1) { grainCol = PAL.walnutWarm; w = 0.6; }
    else if (bandVal < -0.45) { grainCol = PAL.walnutVoid; w = 0.75; }

    useStroke("HB", grainCol, w);
    brush.spline(pts, 0.35);
  }

  // Dark walnut pores (vessel flecks) across the wood
  useStroke("rotring", PAL.walnutVoid, 0.45);
  for (let i = 0; i < 550; i++) {
    let a = random(360) * Math.PI / 180;
    let r = Math.sqrt(random()) * 0.95;
    let px = tCx + Math.cos(a) * innerRx * r;
    let py = tCy + 6 + Math.sin(a) * innerRy * r;
    let len = random(4, 16);
    brush.line(px, py, px + len, py + random(-0.8, 0.8));
  }

  // 5. Specular Reflections on the Polished Walnut Tray
  // Warm golden reflection pool beneath and around the brass cezve (x ~ 465, y ~ 860)
  for (let r = 135; r > 15; r -= 14) {
    let refPoly = getEllipsePolygon(465, 868, r * 1.15, r * 0.42, 40);
    useWash(PAL.brassOchre, 26);
    drawPolyShape(refPoly, 0.2, true);
  }
  useStroke("burnish", PAL.brassWarm, 0.55);
  for (let i = 0; i < 65; i++) {
    let rx = random(355, 575);
    let ry = random(830, 915);
    let len = random(12, 38);
    brush.line(rx - len / 2, ry, rx + len / 2, ry + random(-1, 1));
  }

  // Cool ivory-porcelain reflection beneath the fincan saucer (x ~ 745, y ~ 885)
  for (let r = 120; r > 20; r -= 16) {
    let refPoly = getEllipsePolygon(745, 885, r * 1.1, r * 0.36, 36);
    useWash(PAL.porcelainWarm, 22);
    drawPolyShape(refPoly, 0.2, true);
  }

  // 6. Cast Shadows of Cezve and Cup onto the Walnut Tray
  // Cezve cast shadow (extending to right-front)
  for (let k = 6; k >= 0; k--) {
    let cShad = getEllipsePolygon(498 + k * 7, 856 + k * 2.5, 114 + k * 9, 36 + k * 3, 50, 6);
    useWash(PAL.walnutVoid, 42);
    drawPolyShape(cShad, 0.15, true);
  }
  // Saucer & Cup cast shadow
  for (let k = 6; k >= 0; k--) {
    let fShad = getEllipsePolygon(768 + k * 6, 876 + k * 2.5, 128 + k * 8, 41 + k * 2.5, 50, 5);
    useWash(PAL.walnutVoid, 40);
    drawPolyShape(fShad, 0.15, true);
  }

  // 7. Hyperreal Surface Scratches, Wear Marks & Spilled Coffee Grounds on Tray
  // Years of circular & arcuate serving scratches catching the twilight & brass light
  for (let i = 0; i < 165; i++) {
    let a = random(360) * Math.PI / 180;
    let rad = Math.sqrt(random()) * 0.88;
    let sx = tCx + Math.cos(a) * innerRx * rad;
    let sy = tCy + 6 + Math.sin(a) * innerRy * rad;
    let sAng = random(-35, 35) * Math.PI / 180;
    let sLen = random(14, 68);
    let mx = (sx + sx + Math.cos(sAng) * sLen) / 2 + random(-4, 4);
    let my = (sy + sy + Math.sin(sAng) * sLen * 0.45) / 2 + random(-4, 4);
    let ex = sx + Math.cos(sAng) * sLen;
    let ey = sy + Math.sin(sAng) * sLen * 0.45;

    // Dark recessed groove of scratch
    useStroke("tahrir", PAL.walnutVoid, random(0.3, 0.55));
    brush.spline([[sx, sy, 0.2], [mx, my, 0.8], [ex, ey, 0.2]], 0.4);

    // Adjacent razor-sharp bright edge catching light
    let hiCol = (sx < 580) ? PAL.walnutScratchHi : PAL.walnutScratch;
    if (random() < 0.28) hiCol = PAL.brassGlow;
    useStroke("tahrir", hiCol, random(0.25, 0.5));
    brush.spline([[sx, sy + 0.9, 0.2], [mx, my + 0.9, 0.9], [ex, ey + 0.9, 0.2]], 0.4);
  }

  // Brass inlay wire and specular ridge along the top bevel of the walnut tray rim
  let rimInlay1 = getEllipsePolygon(tCx, tCy - 1, outerRx - 14, outerRy - 7, 120);
  let rimInlay2 = getEllipsePolygon(tCx, tCy - 1, outerRx - 24, outerRy - 11, 120);
  useStroke("tahrir", PAL.brassMid, 0.65);
  drawPolyShape(rimInlay1, 0.15, true);
  useStroke("tahrir", PAL.brassGold, 0.45);
  drawPolyShape(rimInlay2, 0.15, true);

  // Specular wood highlights on front-left and back-right rim bevel
  useStroke("gild", PAL.walnutScratchHi, 0.95);
  brush.arc(tCx, tCy - 2, outerRx - 6, 200, 330);
  useStroke("tahrir", PAL.brassGlow, 0.6);
  brush.arc(tCx, tCy + 2, innerRx + 3, 25, 155);

  // Tiny spilled coffee droplets & scattered dry grounds on the tray between cezve & cup
  for (let i = 0; i < 85; i++) {
    let gx = random(530, 810) + random(-35, 35);
    let gy = random(835, 925);
    useStroke("tahrir", PAL.groundsDark, random(0.4, 0.9));
    brush.circle(gx, gy, random(0.5, 1.8), 0.2);
  }
  // Two small glossy spilled coffee drops near (605, 882) and (622, 892)
  const drops = [[604, 882, 5.5, 2.4], [619, 891, 3.6, 1.7], [588, 875, 2.8, 1.3]];
  for (let d of drops) {
    let dPoly = getEllipsePolygon(d[0], d[1], d[2], d[3], 18);
    useWash(PAL.coffeeBlack, 240);
    drawPolyShape(dPoly, 0.15, true);
    useStroke("tahrir", PAL.cremaCaramel, 0.45);
    brush.arc(d[0], d[1], d[2] * 0.85, 15, 165);
    useStroke("tahrir", PAL.pureWhite, 0.55);
    brush.circle(d[0] - d[2] * 0.35, d[1] - d[3] * 0.25, 0.9, 0.05);
  }
}

// ============================================================================
// 4. THE DENTED HAMMERED BRASS CEZVE & LONG HANDLE
// ============================================================================

// Cezve 3D profile & dent displacement helpers
function getCezveProfile(v) {
  // v in [0, 1]: 0 = bottom base (y = 842), 1 = top rim (y = 496)
  let y = lerp(842, 496, v);
  let r;
  if (v < 0.06) {
    // Rounded bottom bevel
    r = lerp(94, 108, v / 0.06);
  } else if (v < 0.24) {
    // Swollen lower belly
    let t = (v - 0.06) / 0.18;
    r = 108 + Math.sin(t * Math.PI * 0.65) * 8;
  } else if (v < 0.72) {
    // Graceful conical taper to waist
    let t = (v - 0.24) / 0.48;
    r = lerp(114, 75, Math.sin(t * Math.PI * 0.5));
  } else {
    // Flaring upper collar & rim
    let t = (v - 0.72) / 0.28;
    r = lerp(75, 93, Math.pow(t, 1.25));
  }
  return { y, r };
}

// Compute 3D point and perturbed normal on the cezve with realistic dents
function evalCezveSurface(v, thetaDeg) {
  let prof = getCezveProfile(v);
  let rad = thetaDeg * Math.PI / 180;
  let r = prof.r;
  let y = prof.y;

  // Pouring spout (Ibrik/Gaga) on the right side (theta around 15 deg, v > 0.70)
  let spoutAngDiff = Math.abs(((thetaDeg - 16 + 540) % 360) - 180);
  let spoutFactor = 0;
  if (v > 0.68 && spoutAngDiff < 42) {
    let sv = (v - 0.68) / 0.32;
    let sa = Math.cos((spoutAngDiff / 42) * Math.PI * 0.5);
    spoutFactor = Math.pow(sv, 1.5) * Math.pow(sa, 1.6);
    r += spoutFactor * 31;
    y -= spoutFactor * 14;
  }

  // Three realistic dents (concave deformations on the brass body)
  const dents = [
    { vc: 0.31, tc: 118, rv: 0.13, rt: 24, depth: 9.5 }, // Prominent front-left belly dent
    { vc: 0.54, tc: 56,  rv: 0.11, rt: 21, depth: 7.8 }, // Mid-right shoulder dent
    { vc: 0.19, tc: 74,  rv: 0.09, rt: 18, depth: 6.2 }, // Lower front dent
    { vc: 0.66, tc: 142, rv: 0.08, rt: 16, depth: 5.0 }  // Upper left waist dent
  ];

  let dentDisp = 0;
  let dDv = 0;
  let dDt = 0;

  for (let d of dents) {
    let dv = (v - d.vc) / d.rv;
    let dt = (((thetaDeg - d.tc + 540) % 360) - 180) / d.rt;
    let distSq = dv * dv + dt * dt;
    if (distSq < 1.0) {
      let falloff = Math.pow(1 - distSq, 2);
      dentDisp -= d.depth * falloff;
      // Analytical gradient for normal perturbation
      dDv += d.depth * 4 * (1 - distSq) * dv / d.rv;
      dDt += d.depth * 4 * (1 - distSq) * dt / d.rt;
    }
  }

  r += dentDisp;

  let cx = 465;
  let x = cx + Math.cos(rad) * r;
  // Perspective foreshortening of circular cross-sections
  let z = Math.sin(rad) * r;
  let screenY = y + Math.sin(rad) * r * 0.31;

  // Approximate surface normal (nx, ny, nz)
  let nx = Math.cos(rad) + dDt * 0.045 * Math.sin(rad);
  let nz = Math.sin(rad);
  let ny = (v < 0.72 ? -0.18 : 0.22) + dDv * 0.022;
  let nLen = Math.hypot(nx, ny, nz) || 1;

  return {
    x,
    y: screenY,
    z,
    r,
    nx: nx / nLen,
    ny: ny / nLen,
    nz: nz / nLen,
    dentDisp,
    spoutFactor
  };
}

// Compute hammered brass color from surface normal
function shadeBrassNormal(nx, ny, nz, v, thetaDeg, isDentEdge = false) {
  // Primary warm light from upper-left-front
  let lx = -0.52, ly = -0.55, lz = 0.65;
  let ndotl = Math.max(0, nx * lx + ny * ly + nz * lz);

  // Reflection vector R = 2(N.V)N - V for view V = (0, 0, 1)
  let rx = 2 * nz * nx;
  let ry = 2 * nz * ny;
  let rz = 2 * nz * nz - 1;

  // Specular highlight
  let spec = Math.pow(Math.max(0, rx * (-0.48) + ry * (-0.42) + rz * 0.77), 16);

  // Environment reflection bands:
  // Upward-facing normals reflect twilight lapis sky
  if (ry < -0.38 && spec < 0.45) {
    return (ry < -0.62) ? PAL.brassSkyLight : PAL.brassSkyDark;
  }
  // Right-facing normals reflect the bright porcelain cup & crema
  if (nx > 0.62 && v < 0.65) {
    return (ny < 0) ? PAL.brassGlow : PAL.brassWarm;
  }
  // Downward-facing normals reflect the dark walnut tray
  if (ry > 0.42 && spec < 0.3) {
    return (ry > 0.68) ? PAL.brassShadow : PAL.brassUmber;
  }

  if (spec > 0.72 || isDentEdge) return PAL.brassSpec;
  if (spec > 0.45) return PAL.brassGlow;
  if (ndotl > 0.72) return PAL.brassGold;
  if (ndotl > 0.52) return PAL.brassWarm;
  if (ndotl > 0.34) return PAL.brassMid;
  if (ndotl > 0.18) return PAL.brassOchre;
  if (ndotl > 0.06) return PAL.brassBronze;
  return PAL.brassUmber;
}

function renderBrassCezve() {
  // 1. Render the long turned wooden & brass handle first (attaches at left upper shoulder)
  renderCezveHandle();

  // 2. Build Cezve Silhouette Polygon for base washes
  let leftEdge = [];
  let rightEdge = [];
  let bottomCurve = [];
  let topFrontCurve = [];

  for (let i = 0; i <= 40; i++) {
    let v = i / 40;
    let pL = evalCezveSurface(v, 180);
    let pR = evalCezveSurface(v, 0);
    leftEdge.push([pL.x, pL.y]);
    rightEdge.push([pR.x, pR.y]);
  }
  for (let i = 0; i <= 36; i++) {
    let th = 180 - (i / 36) * 180;
    let pBot = evalCezveSurface(0, th);
    bottomCurve.push([pBot.x, pBot.y]);
  }
  for (let i = 0; i <= 36; i++) {
    let th = (i / 36) * 180;
    let pTop = evalCezveSurface(1, th);
    topFrontCurve.push([pTop.x, pTop.y]);
  }

  let bodyPoly = [...bottomCurve, ...rightEdge, ...topFrontCurve, ...leftEdge.slice().reverse()];

  // Solid base wash so background doesn't show through
  useWash(PAL.brassUmber, 250);
  drawPolyShape(bodyPoly, 0.08, true);

  // Warm antique brass watercolor under-glow
  useWatercolor(PAL.brassMid, 195, 0.1, 0.55, 0.35);
  drawPolyShape(bodyPoly, 0.08, true);

  // Vertical cylindrical reflection zones (Left bright ridge, Center-right dark core, Right bounce)
  let highlightBand = [];
  let coreShadowBand = [];
  for (let i = 0; i <= 30; i++) {
    let v = i / 30;
    let p1 = evalCezveSurface(v, 145);
    let p2 = evalCezveSurface(v, 112);
    highlightBand.push([p1.x, p1.y]);
    coreShadowBand.unshift([p2.x, p2.y]);
  }
  useWash(PAL.brassGold, 150);
  drawPolyShape([...highlightBand, ...coreShadowBand], 0.1, true);

  let darkCore1 = [];
  let darkCore2 = [];
  for (let i = 0; i <= 30; i++) {
    let v = i / 30;
    let p1 = evalCezveSurface(v, 82);
    let p2 = evalCezveSurface(v, 42);
    darkCore1.push([p1.x, p1.y]);
    darkCore2.unshift([p2.x, p2.y]);
  }
  useWash(PAL.brassShadow, 165);
  drawPolyShape([...darkCore1, ...darkCore2], 0.1, true);

  // 3. Hyperreal Hammered Facets (Dövme Bakır/Pirinç) across the 3D body
  // Staggered rows of concave hammer dimples
  const vRows = 16;
  const tCols = 17;

  for (let row = 0; row < vRows; row++) {
    let v0 = 0.05 + (row / vRows) * 0.86;
    let v1 = 0.05 + ((row + 1) / vRows) * 0.86;
    let vc = (v0 + v1) * 0.5;
    let stagger = (row % 2) * (180 / tCols) * 0.5;

    for (let col = 0; col < tCols; col++) {
      let tc = 8 + col * ((164) / (tCols - 1)) + stagger;
      if (tc > 174) continue;

      let centerPt = evalCezveSurface(vc, tc);
      // Facet size scales with local radius and foreshortening
      let foreshorten = Math.sin(tc * Math.PI / 180);
      let fw = centerPt.r * 0.105 * (0.35 + 0.65 * foreshorten);
      let fh = 9.8;

      // Concave dimple: upper half of facet tilts downward (catches dark/sky),
      // lower half tilts upward (catches bright golden specular rim)
      let nUp = shadeBrassNormal(
        centerPt.nx - 0.12,
        centerPt.ny + 0.36,
        centerPt.nz,
        vc,
        tc
      );
      let nMid = shadeBrassNormal(
        centerPt.nx,
        centerPt.ny,
        centerPt.nz,
        vc,
        tc
      );
      let nLow = shadeBrassNormal(
        centerPt.nx + 0.1,
        centerPt.ny - 0.38,
        centerPt.nz + 0.15,
        vc,
        tc,
        centerPt.dentDisp < -2.5
      );

      // Facet cushion fill
      let fPoly = getEllipsePolygon(centerPt.x, centerPt.y, fw, fh * 0.54, 12);
      useWash(nMid, 195);
      drawPolyShape(fPoly, 0.2, true);

      // Upper concave shadow crescent inside dimple
      useStroke("burnish", nUp, 1.15);
      brush.arc(centerPt.x, centerPt.y + 0.5, fw * 0.78, 195, 345);

      // Dark bronze hammer ridge along top edge of dimple
      useStroke("2B", PAL.brassUmber, 0.55);
      brush.arc(centerPt.x, centerPt.y, fw * 0.92, 190, 350);

      // Lower bright golden/specular crescent catching the light
      useStroke("gild", nLow, 0.85);
      brush.arc(centerPt.x, centerPt.y - 0.5, fw * 0.82, 15, 165);

      // Extra razor-sharp specular glint on facets along the lit ridge or dent rims
      if ((tc > 105 && tc < 152) || centerPt.dentDisp < -1.8) {
        useStroke("tahrir", PAL.brassSpec, 0.55);
        brush.arc(centerPt.x - fw * 0.12, centerPt.y - 0.5, fw * 0.72, 25, 140);
      }
    }
  }

  // 4. Emphasize the 3 Macro-Dents (warped reflections & deep tarnished creases)
  const dentHighlights = [
    { vc: 0.31, tc: 118, rx: 28, ry: 18 },
    { vc: 0.54, tc: 56,  rx: 24, ry: 15 },
    { vc: 0.19, tc: 74,  rx: 19, ry: 12 },
    { vc: 0.66, tc: 142, rx: 16, ry: 11 }
  ];

  for (let dh of dentHighlights) {
    let dp = evalCezveSurface(dh.vc, dh.tc);
    // Deep tarnished bronze hollow on the upper-left inside of the dent
    let dHollow = getEllipsePolygon(dp.x - 3, dp.y - 3, dh.rx * 0.75, dh.ry * 0.65, 20, -15);
    useWash(PAL.brassShadow, 150);
    drawPolyShape(dHollow, 0.25, true);

    // Bright warped golden crescent on the lower-right lip of the dent
    useStroke("gild", PAL.brassGlow, 1.2);
    brush.arc(dp.x, dp.y, dh.rx * 0.88, -10, 145);

    useStroke("tahrir", PAL.brassSpec, 0.75);
    brush.arc(dp.x + 1, dp.y + 1, dh.rx * 0.82, 10, 125);

    // Cool twilight sky reflection trapped in the upper ridge of the dent
    useStroke("burnish", PAL.brassSkyLight, 0.9);
    brush.arc(dp.x, dp.y - 2, dh.rx * 0.9, 195, 325);
  }

  // 5. Fine horizontal lathe lines, micro-scratches & aged patina on the brass
  for (let i = 0; i < 140; i++) {
    let v = random(0.02, 0.96);
    let t1 = random(12, 155);
    let t2 = t1 + random(8, 26);
    let p1 = evalCezveSurface(v, t1);
    let p2 = evalCezveSurface(v, (t1 + t2) * 0.5);
    let p3 = evalCezveSurface(v, t2);
    let col = (t1 > 105 && t1 < 150) ? PAL.brassSpec : (random() < 0.5 ? PAL.brassGlow : PAL.brassShadow);
    useStroke("tahrir", col, random(0.28, 0.52));
    brush.spline([[p1.x, p1.y, 0.3], [p2.x, p2.y, 0.9], [p3.x, p3.y, 0.3]], 0.4);
  }

  // Base foot ring & ambient occlusion contact line on the walnut tray
  useStroke("gild", PAL.brassShadow, 1.6);
  drawPolyShape(bottomCurve, 0.15, false);

  let baseBevel = [];
  for (let i = 0; i <= 36; i++) {
    let p = evalCezveSurface(0.035, 180 - (i / 36) * 180);
    baseBevel.push([p.x, p.y]);
  }
  useStroke("tahrir", PAL.brassGlow, 0.75);
  drawPolyShape(baseBevel, 0.15, false);

  // 6. Cezve Top Opening, Tin-Lined Interior (Kalay), Rolled Brass Lip & Pouring Spout
  let rimBackCurve = [];
  let rimFullPoly = [];
  for (let i = 0; i <= 72; i++) {
    let th = (i / 72) * 360;
    let p = evalCezveSurface(1.0, th);
    rimFullPoly.push([p.x, p.y]);
    if (th >= 180) rimBackCurve.push([p.x, p.y]);
  }

  // Inner tin-lined & coffee-stained wall visible at the top opening
  useWash(PAL.tinDark, 245);
  drawPolyShape(rimFullPoly, 0.12, true);

  // Vertical metallic shading on the back inner wall of the cezve mouth
  for (let i = 0; i < 60; i++) {
    let th = 185 + (i / 60) * 170;
    let pTop = evalCezveSurface(1.0, th);
    let depth = 36 * Math.sin((th - 180) * Math.PI / 180);
    // Right-back inner wall catches bright twilight/tin highlight
    let col = PAL.tinDark;
    if (th > 280 && th < 345) col = PAL.porcelainLit;
    else if (th > 245) col = PAL.tinInterior;
    else if (th < 220) col = PAL.brassShadow;

    useStroke("HB", col, 1.3);
    brush.line(pTop.x, pTop.y, pTop.x, pTop.y + depth);
  }

  // Dark residual simmered Turkish coffee & foam inside the bottom of the visible mouth
  let innerCoffeePts = [];
  for (let i = 0; i <= 48; i++) {
    let th = (i / 48) * 360;
    let p = evalCezveSurface(0.95, th);
    innerCoffeePts.push([p.x, p.y + 11]);
  }
  useWash(PAL.coffeeDark, 235);
  drawPolyShape(innerCoffeePts, 0.15, true);

  // Frothy bronze crema ring clinging inside the cezve neck and pouring spout
  useStroke("burnish", PAL.cremaRoasted, 1.4);
  drawPolyShape(innerCoffeePts, 0.15, true);

  // Gritty coffee grounds clinging inside the pouring spout (right side of rim)
  useStroke("spray", PAL.groundsDark, 0.65);
  for (let i = 0; i < 45; i++) {
    let th = random(-28, 45);
    let p = evalCezveSurface(random(0.92, 1.0), th);
    brush.line(p.x - 4, p.y + 2, p.x + 4, p.y + 6);
  }
  useStroke("tahrir", PAL.groundsDark, 0.55);
  for (let i = 0; i < 65; i++) {
    let th = random(-32, 48);
    let p = evalCezveSurface(random(0.93, 1.0), th);
    brush.circle(p.x + random(-4, 4), p.y + random(0, 8), random(0.4, 1.4), 0.2);
  }

  // Rolled brass rim & razor-sharp specular highlights around the mouth and spout
  useStroke("gild", PAL.brassUmber, 2.2);
  drawPolyShape(rimFullPoly, 0.12, true);

  useStroke("gild", PAL.brassGold, 1.3);
  drawPolyShape(rimFullPoly, 0.12, true);

  useStroke("tahrir", PAL.brassSpec, 0.85);
  drawPolyShape(topFrontCurve, 0.12, false);

  // Crisp silhouette contour of the cezve body
  useStroke("tahrir", PAL.brassShadow, 0.65);
  drawPolyShape(leftEdge, 0.1, false);
  drawPolyShape(rightEdge, 0.1, false);
}

// Render the long brass & turned walnut handle of the cezve (extending upper-left)
function renderCezveHandle() {
  // Handle axis from attachment on cezve upper-left (386, 558) out to (128, 322)
  const ax0 = 392, ay0 = 564;
  const ax1 = 128, ay1 = 322;
  const dx = ax1 - ax0;
  const dy = ay1 - ay0;
  const len = Math.hypot(dx, dy);
  const ux = dx / len;
  const uy = dy / len;
  const nx = -uy; // Perpendicular normal pointing upper-right
  const ny = ux;

  const hPt = (t, offset) => [
    ax0 + ux * (t * len) + nx * offset,
    ay0 + uy * (t * len) + ny * offset
  ];

  // 1. Flanged Brass Socket & Rivet Plate on the Cezve Shoulder
  let flangePts = [
    [396, 526],
    [378, 545],
    [372, 578],
    [398, 602],
    [418, 586],
    [414, 542]
  ];
  useWash(PAL.brassBronze, 245);
  drawPolyShape(flangePts, 0.2, true);

  useStroke("gild", PAL.brassGold, 1.1);
  drawPolyShape(flangePts, 0.2, true);

  useStroke("tahrir", PAL.brassShadow, 0.7);
  drawPolyShape(flangePts, 0.2, true);

  // Three raised copper rivets securing the handle plate
  const rivets = [[398, 544], [392, 566], [402, 585]];
  for (let rv of rivets) {
    let rPoly = getEllipsePolygon(rv[0], rv[1], 4.8, 4.8, 14);
    useWash(PAL.copperRivet, 245);
    drawPolyShape(rPoly, 0.1, true);
    useStroke("tahrir", PAL.brassShadow, 0.65);
    brush.circle(rv[0], rv[1], 5.0, 0.08);
    useStroke("tahrir", PAL.copperHi, 0.65);
    brush.arc(rv[0], rv[1], 3.5, 190, 340);
    useStroke("tahrir", PAL.brassSpec, 0.55);
    brush.circle(rv[0] - 1.4, rv[1] - 1.4, 1.0, 0.05);
  }

  // 2. Brass Stem (t in 0.05 .. 0.36) & Turned Walnut Grip (t in 0.36 .. 0.94)
  const steps = 48;
  const getHandleRadius = (t) => {
    if (t < 0.36) {
      // Tapered hexagonal/round brass shank with decorative collar at t=0.34
      let ring = Math.exp(-Math.pow((t - 0.34) / 0.025, 2)) * 5.5;
      return lerp(11.5, 8.2, t / 0.36) + ring;
    } else if (t < 0.94) {
      // Lathe-turned walnut handle with baluster swell and double rings
      let wt = (t - 0.36) / 0.58;
      let swell = Math.sin(wt * Math.PI) * 7.5;
      let pommel = Math.exp(-Math.pow((wt - 0.92) / 0.08, 2)) * 5.2;
      let groove = -Math.exp(-Math.pow((wt - 0.18) / 0.03, 2)) * 2.8
                   -Math.exp(-Math.pow((wt - 0.80) / 0.03, 2)) * 2.8;
      return 9.5 + swell + pommel + groove;
    } else {
      // Brass finial cap at tip
      return lerp(9.0, 4.0, (t - 0.94) / 0.06);
    }
  };

  // Build polygons for brass stem and wooden grip
  let brassStemTop = [], brassStemBot = [];
  let woodGripTop = [], woodGripBot = [];

  for (let i = 0; i <= steps; i++) {
    let t = i / steps;
    let r = getHandleRadius(t);
    let pTop = hPt(t, r);
    let pBot = hPt(t, -r);
    if (t <= 0.37) {
      brassStemTop.push(pTop);
      brassStemBot.unshift(pBot);
    }
    if (t >= 0.35) {
      woodGripTop.push(pTop);
      woodGripBot.unshift(pBot);
    }
  }

  // Wash brass stem
  useWash(PAL.brassMid, 245);
  drawPolyShape([...brassStemTop, ...brassStemBot], 0.1, true);

  // Wash turned walnut grip
  useWash(PAL.walnutDark, 250);
  drawPolyShape([...woodGripTop, ...woodGripBot], 0.1, true);

  // Cylindrical shading along the handle
  for (let s = -1.0; s <= 1.0; s += 0.12) {
    // s = 1 is upper-right edge (lit), s = -1 is lower-left edge (shadowed)
    let ptsBrass = [];
    let ptsWood = [];
    for (let i = 0; i <= steps; i++) {
      let t = i / steps;
      let r = getHandleRadius(t);
      let pt = hPt(t, s * r);
      if (t <= 0.36) ptsBrass.push([pt[0], pt[1], 0.7]);
      if (t >= 0.36) ptsWood.push([pt[0], pt[1], 0.7]);
    }

    // Brass stem shading
    let bCol = PAL.brassMid;
    if (s > 0.65) bCol = PAL.brassSkyLight;
    else if (s > 0.25) bCol = PAL.brassSpec;
    else if (s > -0.1) bCol = PAL.brassGold;
    else if (s < -0.55) bCol = PAL.brassShadow;
    else if (s < -0.2) bCol = PAL.brassUmber;

    useStroke("gild", bCol, 0.85);
    brush.spline(ptsBrass, 0.3);

    // Turned walnut grip shading
    let wCol = PAL.walnutMid;
    if (s > 0.45 && s < 0.75) wCol = PAL.walnutScratchHi;
    else if (s > 0.15) wCol = PAL.walnutAmber;
    else if (s < -0.5) wCol = PAL.walnutVoid;
    else if (s < -0.15) wCol = PAL.walnutDeep;

    useStroke("HB", wCol, 0.9);
    brush.spline(ptsWood, 0.3);
  }

  // Turned lathe rings on the collar and wooden handle
  const ringPositions = [0.33, 0.35, 0.37, 0.46, 0.82, 0.94];
  for (let rt of ringPositions) {
    let r = getHandleRadius(rt);
    let p1 = hPt(rt, r);
    let p2 = hPt(rt, -r);
    useStroke("tahrir", PAL.brassShadow, 0.75);
    brush.line(p1[0], p1[1], p2[0], p2[1]);
    let p1Hi = hPt(rt + 0.006, r * 0.85);
    let p2Hi = hPt(rt + 0.006, -r * 0.4);
    useStroke("tahrir", PAL.brassGlow, 0.55);
    brush.line(p1Hi[0], p1Hi[1], p2Hi[0], p2Hi[1]);
  }

  // Brass finial eyelet & hanging ring at tip (128, 322)
  useStroke("gild", PAL.brassGold, 1.3);
  brush.circle(ax1 - 6, ay1 - 6, 8, 0.1);
  useStroke("gild", PAL.brassBronze, 1.4);
  brush.circle(ax1 - 14, ay1 - 2, 16, 0.12);
  useStroke("tahrir", PAL.brassSpec, 0.75);
  brush.arc(ax1 - 14, ay1 - 2, 16, 180, 330);
}

// ============================================================================
// 5. PORCELAIN FINCAN, SAUCER, BUBBLING CREMA & CLINGING GROUNDS
// ============================================================================

function renderPorcelainFincanAndCoffee() {
  const fCx = 746;
  const sCy = 868; // Saucer center Y
  const rimCy = 716; // Cup top rim Y
  const baseCy = 854; // Cup foot base Y

  // --------------------------------------------------------------------------
  // A. THE PORCELAIN SAUCER
  // --------------------------------------------------------------------------
  const sRx = 132;
  const sRy = 43;

  // Saucer underside & foot shadow
  let sFootPoly = getEllipsePolygon(fCx, sCy + 9, sRx * 0.68, sRy * 0.68, 60);
  useWash(PAL.walnutVoid, 235);
  drawPolyShape(sFootPoly, 0.15, true);

  // Saucer lower belly reflecting warm walnut tray
  let sBellyPoly = getEllipsePolygon(fCx, sCy + 4, sRx * 0.96, sRy * 0.98, 80);
  useWash(PAL.porcelainAmber, 235);
  drawPolyShape(sBellyPoly, 0.15, true);

  // Saucer upper glazed dish surface
  let sTopPoly = getEllipsePolygon(fCx, sCy, sRx, sRy, 90);
  useWash(PAL.porcelainCool, 245);
  drawPolyShape(sTopPoly, 0.15, true);

  // Left half of saucer catches bright twilight & warm brass bounce
  let sLitPoly = getEllipsePolygon(fCx - 24, sCy - 2, sRx * 0.72, sRy * 0.78, 60);
  useWatercolor(PAL.porcelainLit, 195, 0.15, 0.35, 0.2);
  drawPolyShape(sLitPoly, 0.15, true);

  // Right half of saucer in cool twilight shadow
  let sShadPoly = getEllipsePolygon(fCx + 32, sCy + 2, sRx * 0.65, sRy * 0.75, 60);
  useWatercolor(PAL.porcelainShadow, 165, 0.15, 0.4, 0.25);
  drawPolyShape(sShadPoly, 0.15, true);

  // Saucer Ottoman cobalt-lapis, cinnabar & gold rim ornament
  let sBandOut = getEllipsePolygon(fCx, sCy, sRx - 6, sRy - 2, 90);
  let sBandIn = getEllipsePolygon(fCx, sCy + 1, sRx - 22, sRy - 7, 90);
  useStroke("tahrir", PAL.goldAntique, 0.85);
  drawPolyShape(sBandOut, 0.15, true);
  drawPolyShape(sBandIn, 0.15, true);

  for (let i = 0; i < 28; i++) {
    let a = (i / 28) * Math.PI * 2;
    let px = fCx + Math.cos(a) * (sRx - 14);
    let py = sCy + Math.sin(a) * (sRy - 4.5);
    let col = (i % 2 === 0) ? PAL.lapisBright : PAL.cinnabar;
    useStroke("tahrir", col, 0.75);
    brush.circle(px, py, 2.6, 0.1);
    useStroke("tahrir", PAL.goldBright, 0.5);
    brush.circle(px, py, 1.1, 0.05);
  }

  // Recessed central saucer well & cast shadow of the cup
  let wellPoly = getEllipsePolygon(fCx, sCy + 3, 66, 21, 50);
  useWash(PAL.porcelainDeep, 215);
  drawPolyShape(wellPoly, 0.15, true);

  for (let k = 4; k >= 0; k--) {
    let cupShad = getEllipsePolygon(fCx + 14 + k * 4, sCy + 4 + k * 1.2, 56 + k * 5, 18 + k * 1.8, 40);
    useWash(PAL.abyss, 48);
    drawPolyShape(cupShad, 0.15, true);
  }

  // Specular porcelain highlights on saucer rim
  useStroke("gild", PAL.porcelainSpec, 1.1);
  brush.arc(fCx, sCy, sRx - 1, 165, 255);
  brush.arc(fCx, sCy, sRx - 1, 15, 75);

  // --------------------------------------------------------------------------
  // B. THE PORCELAIN CUP (FINCAN) EXTERIOR
  // --------------------------------------------------------------------------
  // Cup profile helper: v=0 at foot (y=854, r=50) to v=1 at rim (y=716, r=92)
  const getCupProfile = (v) => {
    let y = lerp(baseCy, rimCy, v);
    let r;
    if (v < 0.10) {
      // Foot ring
      r = lerp(49, 53, v / 0.10);
    } else {
      // Rounded tulip-bell belly flaring to rim
      let t = (v - 0.10) / 0.90;
      r = 53 + Math.sin(t * Math.PI * 0.58) * 37 + Math.pow(t, 2.4) * 4;
    }
    return { y, r };
  };

  const evalCupSurface = (v, thetaDeg) => {
    let prof = getCupProfile(v);
    let rad = thetaDeg * Math.PI / 180;
    let x = fCx + Math.cos(rad) * prof.r;
    let y = prof.y + Math.sin(rad) * prof.r * 0.31;
    return { x, y, r: prof.r };
  };

  // Build cup silhouette polygon
  let cupLeft = [], cupRight = [], cupBottom = [], cupTopFront = [];
  for (let i = 0; i <= 32; i++) {
    let v = i / 32;
    let pL = evalCupSurface(v, 180);
    let pR = evalCupSurface(v, 0);
    cupLeft.push([pL.x, pL.y]);
    cupRight.push([pR.x, pR.y]);
  }
  for (let i = 0; i <= 30; i++) {
    let th = 180 - (i / 30) * 180;
    let pB = evalCupSurface(0, th);
    cupBottom.push([pB.x, pB.y]);
  }
  for (let i = 0; i <= 30; i++) {
    let th = (i / 30) * 180;
    let pT = evalCupSurface(1, th);
    cupTopFront.push([pT.x, pT.y]);
  }

  let cupPoly = [...cupBottom, ...cupRight, ...cupTopFront, ...cupLeft.slice().reverse()];

  // Base porcelain wash
  useWash(PAL.porcelainCool, 252);
  drawPolyShape(cupPoly, 0.08, true);

  // Smooth 3D cylindrical & spherical shading across the porcelain cup
  const cCols = 52;
  for (let c = 0; c <= cCols; c++) {
    let th = (c / cCols) * 180; // Front hemisphere 0..180
    let pts = [];
    for (let rv = 0; rv <= 18; rv++) {
      let v = rv / 18;
      let pt = evalCupSurface(v, th);
      pts.push([pt.x, pt.y, 0.8]);
    }

    // Lighting across the porcelain cylinder:
    // th in 152..180: warm golden-amber bounce light reflected from the brass cezve!
    // th in 112..152: bright cool-white specular highlight & lit ivory porcelain
    // th in 72..112: soft cool midtone porcelain
    // th in 22..72: cool twilight shadow core
    // th in 0..22: faint cool rim bounce on far right
    let col = PAL.porcelainMid;
    if (th > 158) col = PAL.porcelainAmber;
    else if (th > 144) col = PAL.porcelainWarm;
    else if (th > 122 && th <= 140) col = PAL.porcelainSpec;
    else if (th > 102) col = PAL.porcelainLit;
    else if (th > 74) col = PAL.porcelainCool;
    else if (th > 32) col = PAL.porcelainShadow;
    else if (th > 14) col = PAL.porcelainDeep;
    else col = PAL.porcelainShadow;

    useStroke("glaze", col, 1.35);
    brush.spline(pts, 0.35);
  }

  // Warm walnut bounce light on the lower belly of the porcelain cup
  for (let i = 0; i < 28; i++) {
    let th = 35 + (i / 28) * 125;
    let p1 = evalCupSurface(0.08, th);
    let p2 = evalCupSurface(0.28, th);
    useStroke("burnish", PAL.porcelainAmber, 0.9);
    brush.line(p1.x, p1.y, p2.x, p2.y);
  }

  // Glazed Ottoman Porcelain Ornament (Cobalt-Lapis, Gold & Cinnabar bands + Medallions)
  const drawCupBand = (v, col, weight) => {
    let bPts = [];
    for (let i = 0; i <= 36; i++) {
      let th = (i / 36) * 180;
      let p = evalCupSurface(v, th);
      bPts.push([p.x, p.y, 0.8]);
    }
    useStroke("tahrir", col, weight);
    brush.spline(bPts, 0.35);
  };

  // Foot ring gold & cinnabar rules
  drawCupBand(0.04, PAL.goldAntique, 1.1);
  drawCupBand(0.09, PAL.goldBright, 0.75);
  drawCupBand(0.11, PAL.cinnabar, 0.5);

  // Upper exterior rim gold & cobalt frieze
  drawCupBand(0.92, PAL.goldAntique, 1.15);
  drawCupBand(0.87, PAL.lapisMid, 0.9);
  drawCupBand(0.84, PAL.goldBright, 0.65);
  drawCupBand(0.82, PAL.cinnabar, 0.45);

  // Three foreshortened Hatayi / Tulip medallions painted on the porcelain belly
  const cupMedallions = [42, 92, 142];
  for (let mTh of cupMedallions) {
    let pCenter = evalCupSurface(0.50, mTh);
    let pTop = evalCupSurface(0.72, mTh);
    let pBot = evalCupSurface(0.26, mTh);
    let pLeft = evalCupSurface(0.50, mTh + 16);
    let pRight = evalCupSurface(0.50, mTh - 16);

    // Cobalt-lapis ogival medallion on porcelain
    let mPoly = [
      [pTop.x, pTop.y],
      [pLeft.x, pLeft.y],
      [pBot.x, pBot.y],
      [pRight.x, pRight.y]
    ];
    useWash(PAL.lapisMid, 165);
    drawPolyShape(mPoly, 0.3, true);

    useStroke("tahrir", PAL.goldAntique, 0.75);
    drawPolyShape(mPoly, 0.3, true);

    useStroke("tahrir", PAL.cinnabar, 0.48);
    drawPolyShape(mPoly, 0.3, true);

    // Stylized gold & cinnabar blossom inside medallion
    useStroke("tahrir", PAL.goldBright, 0.7);
    brush.line(pBot.x, pBot.y, pTop.x, pTop.y);
    brush.line(pLeft.x, pLeft.y, pRight.x, pRight.y);
    useStroke("tahrir", PAL.cinnabarBright, 0.75);
    brush.circle(pCenter.x, pCenter.y, 4.2, 0.1);
    useStroke("tahrir", PAL.goldPale, 0.55);
    brush.circle(pCenter.x, pCenter.y, 1.8, 0.05);
  }

  // Crisp glossy specular window reflection on the front-left of the porcelain cup
  let specWin1 = [], specWin2 = [];
  for (let i = 0; i <= 16; i++) {
    let v = 0.22 + (i / 16) * 0.66;
    let p1 = evalCupSurface(v, 134);
    let p2 = evalCupSurface(v, 126);
    specWin1.push([p1.x, p1.y, 0.9]);
    specWin2.push([p2.x, p2.y, 0.7]);
  }
  useStroke("gild", PAL.porcelainSpec, 1.45);
  brush.spline(specWin1, 0.35);
  useStroke("tahrir", PAL.porcelainSpec, 0.9);
  brush.spline(specWin2, 0.35);

  // --------------------------------------------------------------------------
  // C. CUP RIM, INNER WALL, THICK BUBBLING CREMA & CLINGING GROUNDS
  // --------------------------------------------------------------------------
  const rimRx = 93;
  const rimRy = 29;
  const liqCy = rimCy + 8;
  const liqRx = 86;
  const liqRy = 25.5;

  // 1. Inner porcelain wall visible above the coffee line
  let rimEllipse = getEllipsePolygon(fCx, rimCy, rimRx, rimRy, 80);
  useWash(PAL.porcelainWarm, 250);
  drawPolyShape(rimEllipse, 0.12, true);

  // Shade the inner back wall of the porcelain rim (darker on left, brighter on right-back)
  for (let i = 0; i < 55; i++) {
    let deg = 180 + (i / 55) * 180;
    let rad = deg * Math.PI / 180;
    let x = fCx + Math.cos(rad) * (rimRx - 2);
    let yTop = rimCy + Math.sin(rad) * (rimRy - 1);
    let yBot = liqCy + Math.sin(rad) * (liqRy - 1) + 4;
    let col = PAL.porcelainCool;
    if (deg > 280 && deg < 345) col = PAL.porcelainLit;
    else if (deg < 235) col = PAL.porcelainShadow;

    useStroke("HB", col, 1.25);
    brush.line(x, yTop, x, yBot);
  }

  // 2. The Turkish Coffee & Thick Velvety Crema (Köpük)
  let liqPoly = getEllipsePolygon(fCx, liqCy, liqRx, liqRy, 80);
  useWash(PAL.cremaDeep, 252);
  drawPolyShape(liqPoly, 0.12, true);

  // Warm roasted hazelnut & caramel crema rings
  let cremaMidPoly = getEllipsePolygon(fCx - 3, liqCy, liqRx * 0.92, liqRy * 0.90, 70);
  useWatercolor(PAL.cremaHazelnut, 210, 0.15, 0.55, 0.35);
  drawPolyShape(cremaMidPoly, 0.15, true);

  let cremaLightPoly = getEllipsePolygon(fCx - 8, liqCy - 1, liqRx * 0.76, liqRy * 0.74, 60);
  useWatercolor(PAL.cremaCaramel, 185, 0.18, 0.5, 0.3);
  drawPolyShape(cremaLightPoly, 0.18, true);

  // Small dark glossy "eye" of black coffee peeking through the thick crema on center-right
  const eyeCx = fCx + 19;
  const eyeCy = liqCy + 2;
  const eyeRx = 26;
  const eyeRy = 8.5;
  let eyeOuter = getEllipsePolygon(eyeCx, eyeCy, eyeRx * 1.25, eyeRy * 1.25, 36, -6);
  useWash(PAL.cremaDeep, 240);
  drawPolyShape(eyeOuter, 0.2, true);

  let eyeInner = getEllipsePolygon(eyeCx, eyeCy, eyeRx, eyeRy, 36, -6);
  useWash(PAL.coffeeBlack, 252);
  drawPolyShape(eyeInner, 0.2, true);

  // Glossy twilight sky reflection arc on the black coffee eye
  useStroke("burnish", PAL.brassSkyDark, 0.85);
  brush.arc(eyeCx, eyeCy + 1, eyeRx * 0.72, 195, 325);
  useStroke("tahrir", PAL.porcelainLit, 0.55);
  brush.arc(eyeCx - 2, eyeCy - 1, eyeRx * 0.55, 210, 295);

  // Swirling velvety crema currents around the cup
  for (let i = 0; i < 95; i++) {
    let a0 = random(360) * Math.PI / 180;
    let rFrac = random(0.18, 0.95);
    let sPts = [];
    for (let s = 0; s < 5; s++) {
      let a = a0 + s * 0.22;
      let rf = lerp(rFrac, rFrac * 0.82, s / 4);
      let px = fCx + Math.cos(a) * liqRx * rf;
      let py = liqCy + Math.sin(a) * liqRy * rf;
      // Avoid crossing the center of the dark coffee eye
      if (Math.hypot((px - eyeCx) / eyeRx, (py - eyeCy) / eyeRy) < 0.85) break;
      sPts.push([px, py, 0.6]);
    }
    if (sPts.length >= 3) {
      let cCol = random([PAL.cremaRoasted, PAL.cremaHazelnut, PAL.cremaCaramel, PAL.cremaGold, PAL.cremaUmber]);
      useStroke("burnish", cCol, random(0.45, 0.95));
      brush.spline(sPts, 0.45);
    }
  }

  // 3. Hundreds of Hyperreal Micro-Bubbles in the Crema (Köpük)
  // Generate packed foam bubbles clustering around the meniscus rim, around the dark eye, and in frothy rafts
  let bubbles = [];
  for (let i = 0; i < 460; i++) {
    let bx, by, br;
    if (i < 95) {
      // Ring of medium-large bubbles hugging the boundary of the dark coffee eye
      let a = random(360) * Math.PI / 180;
      let dist = random(0.92, 1.48);
      bx = eyeCx + Math.cos(a) * eyeRx * dist;
      by = eyeCy + Math.sin(a) * eyeRy * dist;
      br = random(1.1, 3.4) * map(dist, 0.92, 1.48, 1.15, 0.65);
    } else if (i < 220) {
      // Frothy meniscus bubbles along the outer rim of the coffee
      let a = random(360) * Math.PI / 180;
      let dist = random(0.76, 0.97);
      bx = fCx + Math.cos(a) * liqRx * dist;
      by = liqCy + Math.sin(a) * liqRy * dist;
      br = random(0.9, 3.1);
    } else {
      // Dense micro-foam rafts across the main crema surface
      let a = random(360) * Math.PI / 180;
      let dist = Math.sqrt(random()) * 0.88;
      bx = fCx + Math.cos(a) * liqRx * dist;
      by = liqCy + Math.sin(a) * liqRy * dist;
      br = random(0.55, 2.3);
    }

    // Ensure bubble is inside the liquid ellipse and outside the dark eye core
    let inCup = Math.hypot((bx - fCx) / (liqRx - 2.5), (by - liqCy) / (liqRy - 1.5)) < 1.0;
    let inEye = Math.hypot((bx - eyeCx) / (eyeRx * 0.86), (by - eyeCy) / (eyeRy * 0.86)) < 1.0;
    if (inCup && !inEye) {
      bubbles.push({ x: bx, y: by, r: br });
    }
  }

  // Sort larger bubbles first, smaller micro-bubbles on top
  bubbles.sort((a, b) => b.r - a.r);

  for (let b of bubbles) {
    // Dark roasted coffee cell wall around bubble
    useStroke("tahrir", PAL.cremaDeep, 0.55);
    brush.circle(b.x, b.y, b.r, 0.08);

    if (b.r > 1.3) {
      // Warm golden-caramel dome of the bubble
      let bCol = (b.r > 2.2) ? PAL.cremaCaramel : PAL.cremaGold;
      useStroke("tahrir", bCol, 0.5);
      brush.arc(b.x, b.y, b.r * 0.72, 10, 175);
    }

    // Pinpoint specular highlight on upper-left of every bubble
    let hiCol = (b.r > 1.5 || random() < 0.45) ? PAL.cremaSpec : PAL.cremaFroth;
    useStroke("tahrir", hiCol, b.r > 2.0 ? 0.58 : 0.42);
    brush.circle(b.x - b.r * 0.28, b.y - b.r * 0.24, Math.max(0.35, b.r * 0.28), 0.02);
  }

  // 4. Coffee Grounds (Telve) Clinging to the Porcelain Rim & Lip
  // When poured from the cezve (on the left), fine dark grounds cling to the inner wall
  // just above the crema meniscus and smudge onto the left/front-left porcelain lip!
  useStroke("spray", PAL.groundsDark, 0.55);
  for (let i = 0; i < 65; i++) {
    let deg = random(165, 355);
    let rad = deg * Math.PI / 180;
    let gx = fCx + Math.cos(rad) * (liqRx - random(-2, 5));
    let gy = liqCy + Math.sin(rad) * (liqRy - random(-1, 3)) - random(1, 7);
    brush.line(gx - 3, gy, gx + 3, gy + random(-1.5, 1.5));
  }

  // Individual gritty coffee ground clusters clinging to the inner porcelain wall & top rim
  for (let i = 0; i < 210; i++) {
    // Heaviest concentration on the left pouring side (deg in 145..265) and back tide-line
    let deg = (i < 130) ? random(142, 265) : random(180, 360);
    let rad = deg * Math.PI / 180;
    let tide = random(0, 1);
    let gx = fCx + Math.cos(rad) * lerp(liqRx, rimRx, tide * 0.85) + random(-2, 2);
    let gy = lerp(
      liqCy + Math.sin(rad) * liqRy,
      rimCy + Math.sin(rad) * rimRy,
      tide * 0.88
    ) + random(-1.5, 1.5);

    let gCol = (random() < 0.65) ? PAL.groundsDark : PAL.groundsMid;
    useStroke("tahrir", gCol, random(0.38, 0.85));
    brush.circle(gx, gy, random(0.35, 1.35), 0.25);
  }

  // 5. Gilded Top Lip of the Porcelain Cup (with coffee ground smudges on the left lip)
  useStroke("gild", PAL.goldAntique, 1.35);
  drawPolyShape(rimEllipse, 0.12, true);

  useStroke("tahrir", PAL.goldBright, 0.75);
  drawPolyShape(rimEllipse, 0.12, true);

  // Specular highlights along the front-left and back-right gilded porcelain rim
  useStroke("tahrir", PAL.porcelainSpec, 0.85);
  brush.arc(fCx, rimCy, rimRx, 115, 175);
  brush.arc(fCx, rimCy, rimRx, 285, 345);

  // Wet coffee stain & clinging grounds right over the left rim edge (where poured from cezve)
  for (let i = 0; i < 38; i++) {
    let deg = random(158, 208);
    let rad = deg * Math.PI / 180;
    let rx = fCx + Math.cos(rad) * rimRx + random(-2.5, 2.5);
    let ry = rimCy + Math.sin(rad) * rimRy + random(-2, 2);
    useStroke("tahrir", PAL.groundsDark, random(0.45, 0.85));
    brush.circle(rx, ry, random(0.4, 1.4), 0.2);
  }
}

// ============================================================================
// 6. FRAGRANT MEDITATIVE STEAM & FINAL SPECULAR JEWELS
// ============================================================================

function renderFragrantSteamAndFinalGlints() {
  // Subtle, courtly wisps of fragrant vapour rising from the hot fincan and cezve spout,
  // gently echoing the S-curve geometry of the tezhip scrollwork above
  const steamColumns = [
    { x0: 735, y0: 702, amp: 24, h: 270, phase: 0.2 },
    { x0: 758, y0: 708, amp: -19, h: 235, phase: 1.4 },
    { x0: 562, y0: 488, amp: 18, h: 210, phase: 0.8 },
    { x0: 545, y0: 495, amp: -15, h: 175, phase: 2.1 }
  ];

  for (let sc of steamColumns) {
    for (let strand = -3; strand <= 3; strand++) {
      let pts = [];
      let steps = 28;
      for (let i = 0; i <= steps; i++) {
        let t = i / steps;
        let wave = Math.sin(t * Math.PI * 2.1 + sc.phase + strand * 0.22) * sc.amp * Math.pow(t, 0.75);
        let spread = strand * (2.5 + t * 11);
        let px = sc.x0 + wave + spread;
        let py = sc.y0 - t * sc.h;
        let press = Math.sin(t * Math.PI) * 0.55;
        pts.push([px, py, press]);
      }
      let col = (Math.abs(strand) <= 1) ? PAL.pearlWhite : PAL.lapisDust;
      useStroke("2H", col, 0.32);
      brush.spline(pts, 0.5);
    }
  }

  // Final razor-sharp jeweller glints on the cezve pouring lip, rivets, and crema
  const jewelGlints = [
    [578, 492, 2.2], // Cezve pouring spout tip
    [412, 514, 1.8], // Cezve left rim
    [422, 745, 2.0], // Cezve belly dent ridge
    [445, 635, 1.7], // Cezve waist highlight
    [688, 728, 1.9], // Fincan front-left rim
    [684, 768, 1.6], // Fincan belly specular
    [632, 868, 1.6]  // Saucer left rim
  ];

  for (let g of jewelGlints) {
    useStroke("tahrir", PAL.pureWhite, 0.75);
    brush.circle(g[0], g[1], g[2], 0.02);
    useStroke("tahrir", PAL.goldPale, 0.45);
    brush.line(g[0] - g[2] * 2.4, g[1], g[0] + g[2] * 2.4, g[1]);
    brush.line(g[0], g[1] - g[2] * 2.4, g[0], g[1] + g[2] * 2.4);
  }
}

