// ============================================================================
// GEOMETRY & TEXTILE APPLIQUÉ HELPERS
// ============================================================================

function drawPoly(pts, curvature = 0) {
  if (!pts || pts.length < 3) return;
  brush.beginShape(curvature);
  for (let i = 0; i < pts.length; i++) {
    brush.vertex(pts[i][0], pts[i][1]);
  }
  brush.endShape(true);
}

function insetPoly(pts, dist) {
  let cx = 0, cy = 0;
  for (let i = 0; i < pts.length; i++) {
    cx += pts[i][0];
    cy += pts[i][1];
  }
  cx /= pts.length;
  cy /= pts.length;
  let out = [];
  for (let i = 0; i < pts.length; i++) {
    let dx = pts[i][0] - cx;
    let dy = pts[i][1] - cy;
    let len = Math.hypot(dx, dy) || 1;
    let shrink = Math.min(dist, len * 0.35);
    out.push([pts[i][0] - (dx / len) * shrink, pts[i][1] - (dy / len) * shrink]);
  }
  return out;
}

function offsetPoly(pts, ox, oy) {
  return pts.map(p => [p[0] + ox, p[1] + oy]);
}

function lerpPt(a, b, t) {
  return [a[0] + (b[0] - a[0]) * t, a[1] + (b[1] - a[1]) * t];
}

function quadPts(x1, y1, x2, y2, x3, y3, x4, y4) {
  return [[x1, y1], [x2, y2], [x3, y3], [x4, y4]];
}

// Renders dashed running-stitch pen marks along a polyline or closed polygon
function drawRunningStitch(pts, closed, col, stitchLen = 8.5, gapLen = 5.5, weight = 0.55, jitter = 1.1) {
  brush.noFill();
  brush.noWash();
  brush.noHatch();
  brush.set("rotring", col, weight);

  let count = closed ? pts.length : pts.length - 1;
  for (let i = 0; i < count; i++) {
    let a = pts[i];
    let b = pts[(i + 1) % pts.length];
    let dx = b[0] - a[0];
    let dy = b[1] - a[1];
    let segLen = Math.hypot(dx, dy);
    if (segLen < 2) continue;

    let ux = dx / segLen;
    let uy = dy / segLen;
    let nx = -uy;
    let ny = ux;

    let d = 1.5;
    let step = stitchLen + gapLen;
    while (d < segLen - 1.5) {
      let dEnd = Math.min(d + stitchLen, segLen - 1.0);
      if (dEnd - d > 1.8) {
        let j1 = random(-jitter, jitter);
        let j2 = random(-jitter, jitter);
        let x1 = a[0] + ux * d + nx * j1;
        let y1 = a[1] + uy * d + ny * j1;
        let x2 = a[0] + ux * dEnd + nx * j2;
        let y2 = a[1] + uy * dEnd + ny * j2;
        brush.line(x1, y1, x2, y2);
      }
      d += step * random(0.88, 1.12);
    }

    // Corner tack stitch
    if (closed && segLen > 18) {
      let kx = a[0] + nx * 2.2;
      let ky = a[1] + ny * 2.2;
      let kx2 = a[0] - nx * 2.2;
      let ky2 = a[1] - ny * 2.2;
      brush.line(kx, ky, kx2, ky2);
    }
  }
}

// Core hyperreal fabric appliqué renderer:
// 1. Coarse crosshatched weave under-texture
// 2. Flat watercolor or wash patch
// 3. Optional corrugated iron ("calamina") ribs & rust weathering
// 4. Contrasting running-stitch seam outlines
function drawAppliquePatch(pts, fam, isLit = true, opts = {}) {
  let fillCol = isLit ? fam[0] : fam[2];
  let weaveCol1 = isLit ? fam[2] : fam[3];
  let weaveCol2 = isLit ? PALETTE.burlapMid : fam[1];
  let stitchCol = opts.stitchCol || (isLit ? fam[4] : fam[5]);

  // Subtle drop-edge shadow on burlap so the cut cloth has physical relief
  if (opts.reliefShadow !== false) {
    brush.noStroke();
    brush.noHatch();
    brush.wash(PALETTE.burlapShadow, isLit ? 55 : 85);
    drawPoly(offsetPoly(pts, 2.5, 3.0), 0);
    brush.noWash();
  }

  // 1. Coarse crosshatched fabric weave underneath the watercolor patch
  let wSpace = opts.weaveSpacing || 7.5;
  let wAngle = opts.weaveAngle !== undefined ? opts.weaveAngle : 3;
  brush.noFill();
  brush.noWash();
  brush.noStroke();
  brush.hatchStyle("2H", weaveCol1, opts.weaveWeight || 0.35);
  brush.hatch(wSpace, wAngle, { rand: 0.07 });
  drawPoly(pts, 0);
  brush.hatchStyle("cpencil", weaveCol2, (opts.weaveWeight || 0.35) * 0.9);
  brush.hatch(wSpace * 1.05, wAngle + 90, { rand: 0.07 });
  drawPoly(pts, 0);
  brush.noHatch();

  // 2. Flat watercolor patch or opaque wash
  brush.noStroke();
  if (opts.useWash) {
    brush.wash(fillCol, opts.opacity || 205);
    drawPoly(pts, 0.02);
    brush.noWash();
  } else {
    brush.fill(fillCol, opts.opacity || (isLit ? 185 : 210));
    brush.fillBleed(opts.bleed !== undefined ? opts.bleed : 0.05, "out");
    brush.fillTexture(0.85, 0.72);
    drawPoly(pts, 0.02);
    brush.noFill();
  }

  // 3. Optional corrugated metal ("calamina") ribs
  if (opts.corrugated) {
    let ribAngle = opts.ribAngle !== undefined ? opts.ribAngle : 90;
    let ribSpacing = opts.ribSpacing || 4.2;
    brush.noFill();
    brush.noWash();
    brush.noStroke();
    brush.hatchStyle("rotring", fam[3], opts.ribWeight || 0.28);
    brush.hatch(ribSpacing, ribAngle, { rand: 0.02 });
    drawPoly(pts, 0);
    if (isLit) {
      brush.hatchStyle("2H", PALETTE.threadCream, 0.22);
      brush.hatch(ribSpacing * 2, ribAngle, { rand: 0.02 });
      drawPoly(pts, 0);
    }
    brush.noHatch();
  }

  // 4. Optional rust / weathering stain at base or top edge
  if (opts.weathering && pts.length >= 4) {
    let wPts = [
      lerpPt(pts[0], pts[3], 0.68),
      lerpPt(pts[1], pts[2], 0.68),
      pts[2],
      pts[3]
    ];
    brush.noStroke();
    brush.wash(PALETTE.rust, isLit ? 65 : 95);
    drawPoly(wPts, 0.05);
    brush.noWash();
  }

  // 5. Frayed dark edge outline + Contrasting Running-Stitch Seam
  brush.set("2B", fam[3], 0.35);
  drawPoly(pts, 0);

  let sLen = opts.stitchLen || 8.0;
  let gLen = opts.gapLen || 5.0;
  let sWeight = opts.stitchWeight || 0.55;
  drawRunningStitch(pts, true, stitchCol, sLen, gLen, sWeight, 0.9);

  if (opts.doubleSeam) {
    let inner = insetPoly(pts, opts.insetDist || 4.5);
    drawRunningStitch(inner, true, opts.innerStitchCol || stitchCol, sLen * 0.85, gLen * 0.9, sWeight * 0.82, 0.7);
  }
}

// ============================================================================
// 1. PALE HESSIAN SKY & COARSE BURLAP WEAVE GROUND
// ============================================================================

function drawBurlapGroundAndSky() {
  // Subtle watercolor variation across the pale hessian sky & ground
  brush.noStroke();
  brush.fill(PALETTE.burlapMid, 85);
  brush.fillBleed(0.25, "out");
  brush.fillTexture(0.9, 0.5);
  drawPoly([[0, 0], [1200, 0], [1200, 380], [0, 380]], 0);
  drawPoly([[0, 380], [1200, 380], [1200, 1200], [0, 1200]], 0);
  brush.noFill();

  // Warm sunlit glow in the central sky canyon above the funicular
  brush.fill(PALETTE.warpLight, 120);
  brush.fillBleed(0.3, "out");
  drawPoly([[260, 0], [920, 0], [820, 340], [340, 340]], 0);
  brush.noFill();

  // Loose Hessian Warp (vertical) & Weft (horizontal) across the sky (y: 0..390)
  // Drawn with organic slack, slubs, and occasional loose weave gaps
  for (let x = 4; x < 1200; x += 6.5) {
    let isSlub = (Math.floor(x / 6.5) % 5 === 0);
    let col = isSlub ? PALETTE.warpDark : ((Math.floor(x / 6.5) % 2 === 0) ? PALETTE.warpMid : PALETTE.warpLight);
    let w = isSlub ? 0.52 : 0.34;
    brush.set("cpencil", col, w);

    let sway = sin(x * 1.7) * 2.2;
    let pts = [
      [x + random(-1, 1), 0],
      [x + sway + random(-1.5, 1.5), 110],
      [x - sway * 0.7 + random(-1.5, 1.5), 230],
      [x + sway * 0.5 + random(-1, 1), 390]
    ];
    brush.spline(pts, 0.35);
  }

  for (let y = 4; y < 390; y += 6.5) {
    let idx = Math.floor(y / 6.5);
    // Occasional loose open-weave gap in the hessian sky
    if (idx % 17 === 8) y += 3.5;
    let isSlub = (idx % 6 === 0);
    let col = isSlub ? PALETTE.warpDark : (idx % 2 === 0 ? PALETTE.warpMid : PALETTE.warpLight);
    let w = isSlub ? 0.55 : 0.34;
    brush.set("cpencil", col, w);

    let sag = sin(y * 2.3) * 2.5;
    let pts = [
      [0, y + random(-1, 1)],
      [300, y + sag + random(-1.5, 1.5)],
      [600, y + sag * 1.4 + random(-1.8, 1.8)],
      [900, y + sag * 0.6 + random(-1.5, 1.5)],
      [1200, y + random(-1, 1)]
    ];
    brush.spline(pts, 0.35);
  }

  // Coarser burlap grid extending down under the hillside (y: 380..1200)
  brush.noFill();
  brush.noStroke();
  brush.hatchStyle("2H", PALETTE.warpDark, 0.34);
  brush.hatch(10, 0, { rand: 0.04 });
  drawPoly([[0, 370], [1200, 370], [1200, 1200], [0, 1200]], 0);
  brush.hatchStyle("2H", PALETTE.warpMid, 0.34);
  brush.hatch(10, 90, { rand: 0.04 });
  drawPoly([[0, 370], [1200, 370], [1200, 1200], [0, 1200]], 0);
  brush.noHatch();

  // Stitched clouds / basting-thread lines in the pale hessian sky
  drawRunningStitch([[70, 75], [220, 68], [350, 82]], false, PALETTE.warpDark, 14, 9, 0.45, 0.8);
  drawRunningStitch([[780, 58], [960, 52], [1120, 66]], false, PALETTE.warpDark, 14, 9, 0.45, 0.8);
  drawRunningStitch([[430, 118], [590, 112], [720, 124]], false, PALETTE.burlapDeep, 12, 8, 0.4, 0.8);
}

// ============================================================================
// 2. HILLSIDE DARK BURLAP UNDERLAY (HIGH-CONTRAST FOUNDATION)
// ============================================================================

function drawHillsideUnderlay() {
  // Distant Valparaíso ridge stitched faintly in the central saddle
  let distRidge = [[340, 330], [430, 275], [530, 290], [670, 265], [790, 310], [790, 380], [340, 380]];
  brush.noStroke();
  brush.wash(PALETTE.burlapDark, 115);
  drawPoly(distRidge, 0.05);
  brush.noWash();
  drawRunningStitch(distRidge.slice(0, 5), false, PALETTE.burlapDeep, 7, 5, 0.45, 0.6);

  // Deep shadow burlap mass under the entire hillside so any gap between houses
  // reads as a high-contrast dark passage or shadowed retaining wall
  let hillMass = [
    [-10, 220], [190, 195], [370, 265], [490, 305], [585, 250],
    [740, 265], [960, 185], [1210, 210], [1210, 1210], [-10, 1210]
  ];
  brush.noStroke();
  brush.fill(PALETTE.burlapShadow, 210);
  brush.fillBleed(0.08, "out");
  brush.fillTexture(0.85, 0.7);
  drawPoly(hillMass, 0);
  brush.noFill();

  // Coarse dark crosshatch weave over the shadow underlay
  brush.noStroke();
  brush.hatchStyle("charcoal", "#1a1410", 0.38);
  brush.hatch(12, 2, { rand: 0.08 });
  drawPoly(hillMass, 0);
  brush.hatch(12, 92, { rand: 0.08 });
  drawPoly(hillMass, 0);
  brush.noHatch();
}

// ============================================================================
// ARCHITECTURAL ENGINE: 3D VALPARAÍSO HOUSE BUILDER
// ============================================================================

// Renders a multi-plane 3D Valparaíso house with:
// - Lit front wall + high-contrast shadowed side wall
// - Gabled, shed, or mansard corrugated roof with ridge stitching
// - Recessed dark windows with mullions, shutters & sill rust stains
// - Optional stilts, mending fabric patches, and overhanging balconies
function drawHouse(cfg) {
  let {
    x, y, w, h,
    sideW = 35,           // positive = side wall on right, negative = side wall on left
    skewFront = -6,       // vertical y-offset of right front corner for perspective
    skewSide = -14,       // vertical y-offset of back side corner
    fam = PALETTE.cobalt,
    roofFam = PALETTE.coral,
    roofType = "gable",   // "gable", "shed", "mansard", "hip", "turret"
    roofH = 38,
    corrugatedFront = true,
    corrugatedSide = true,
    frontRibAngle = 90,
    stories = 2,
    winCols = 2,
    hasShutters = true,
    shutterFam = PALETTE.mustard,
    hasBalcony = false,
    balconyFloor = 1,
    hasStilts = false,
    stiltH = 35,
    patchInfo = null      // { rx, ry, rw, rh, fam }
  } = cfg;

  let xL = x;
  let xR = x + w;
  let yTL = y;
  let yTR = y + skewFront;
  let yBL = y + h;
  let yBR = y + h + skewFront * 0.6;

  // 0. Drop shadow onto lower houses
  brush.noStroke();
  brush.wash(PALETTE.inkDark, 125);
  let shadowPoly = [
    [xL - 8, yBL + 6],
    [xR + (sideW > 0 ? sideW : 0) + 10, yBR + 14],
    [xR + (sideW > 0 ? sideW : 0) + 10, yBR + 34],
    [xL - 8, yBL + 24]
  ];
  drawPoly(shadowPoly, 0);
  brush.noWash();

  // 1. Optional timber stilts / retaining substructure underneath
  if (hasStilts) {
    let subPts = [[xL + 4, yBL], [xR - 4, yBR], [xR - 4, yBR + stiltH], [xL + 4, yBL + stiltH]];
    brush.noStroke();
    brush.wash("#1b1612", 215);
    drawPoly(subPts, 0);
    brush.noWash();

    brush.set("rotring", PALETTE.burlapMid, 0.65);
    let numStruts = Math.max(3, Math.floor(w / 28));
    for (let i = 0; i <= numStruts; i++) {
      let t = i / numStruts;
      let sx = lerp(xL + 6, xR - 6, t);
      let sy = lerp(yBL, yBR, t);
      brush.line(sx, sy, sx, sy + stiltH);
      if (i < numStruts) {
        let nx = lerp(xL + 6, xR - 6, (i + 1) / numStruts);
        let ny = lerp(yBL, yBR, (i + 1) / numStruts);
        brush.set("rotring", PALETTE.burlapDark, 0.45);
        brush.line(sx, sy, nx, ny + stiltH);
        brush.line(nx, ny, sx, sy + stiltH);
      }
    }
    drawRunningStitch(subPts, true, PALETTE.threadGold, 7, 5, 0.45);
  }

  // 2. Side Wall (in high-contrast deep shadow or secondary angle)
  let sidePts = null;
  let xSide = sideW >= 0 ? xR + sideW : xL + sideW;
  let ySideT = (sideW >= 0 ? yTR : yTL) + skewSide;
  let ySideB = (sideW >= 0 ? yBR : yBL) + skewSide * 0.7;

  if (Math.abs(sideW) > 4) {
    if (sideW > 0) {
      sidePts = [[xR, yTR], [xSide, ySideT], [xSide, ySideB], [xR, yBR]];
    } else {
      sidePts = [[xSide, ySideT], [xL, yTL], [xL, yBL], [xSide, ySideB]];
    }
    drawAppliquePatch(sidePts, fam, false, {
      corrugated: corrugatedSide,
      ribAngle: 90,
      ribSpacing: 4.0,
      weathering: true,
      doubleSeam: false,
      stitchLen: 7.5,
      gapLen: 4.8,
      stitchWeight: 0.5
    });
  }

  // 3. Front Wall (Lit vibrant fabric appliqué patch)
  let frontPts = [[xL, yTL], [xR, yTR], [xR, yBR], [xL, yBL]];
  drawAppliquePatch(frontPts, fam, true, {
    corrugated: corrugatedFront,
    ribAngle: frontRibAngle,
    ribSpacing: 4.2,
    weathering: true,
    doubleSeam: w > 70,
    insetDist: 5,
    stitchLen: 8.5,
    gapLen: 5.0,
    stitchWeight: 0.62
  });

  // Corrugated sheet horizontal overlap seam lines on front wall
  if (corrugatedFront && h > 55) {
    brush.set("rotring", fam[3], 0.35);
    for (let s = 1; s < stories + 1; s++) {
      let ty = s / (stories + 0.5);
      if (ty < 0.9) {
        let pA = lerpPt([xL, yTL], [xL, yBL], ty);
        let pB = lerpPt([xR, yTR], [xR, yBR], ty);
        brush.line(pA[0], pA[1], pB[0], pB[1]);
      }
    }
  }

  // 4. Optional Mending Appliqué Patch (a contrasting cloth square stitched onto a worn wall!)
  if (patchInfo) {
    let px = xL + w * patchInfo.rx;
    let py = yTL + h * patchInfo.ry;
    let pw = w * patchInfo.rw;
    let ph = h * patchInfo.rh;
    let mPts = [[px, py], [px + pw, py - 2], [px + pw, py + ph - 2], [px, py + ph]];
    drawAppliquePatch(mPts, patchInfo.fam, true, {
      useWash: true,
      corrugated: true,
      ribAngle: frontRibAngle === 90 ? 0 : 90,
      ribSpacing: 3.5,
      stitchLen: 5.5,
      gapLen: 3.5,
      stitchWeight: 0.55
    });
  }

  // 5. Roof Construction (Gable, Shed, Mansard, or Turret)
  if (roofType === "gable") {
    let apexX = (xL + xR) * 0.5;
    let apexY = (yTL + yTR) * 0.5 - roofH;
    // Front gable triangle (extension of front wall or distinct fabric patch)
    let gablePts = [[xL - 4, yTL + 2], [apexX, apexY], [xR + 4, yTR + 2]];
    drawAppliquePatch(gablePts, fam, true, {
      corrugated: true,
      ribAngle: 90,
      ribSpacing: 4.0,
      stitchLen: 7,
      gapLen: 4.5,
      stitchWeight: 0.55
    });

    // Circular attic vent in gable
    if (roofH > 26 && w > 60) {
      let vx = apexX;
      let vy = (yTL + yTR) * 0.5 - roofH * 0.42;
      brush.noStroke();
      brush.wash(PALETTE.inkDark, 220);
      brush.circle(vx, vy, 7.5, 0.1);
      brush.noWash();
      brush.set("rotring", fam[4], 0.5);
      brush.circle(vx, vy, 8.5, 0.1);
    }

    // Sloping roof plane over the side wall
    if (sideW > 0) {
      let rSlopePts = [
        [apexX, apexY - 2],
        [apexX + sideW + 6, apexY + skewSide - 2],
        [xSide + 5, ySideT + 3],
        [xR + 4, yTR + 2]
      ];
      drawAppliquePatch(rSlopePts, roofFam, true, {
        corrugated: true,
        ribAngle: 25,
        ribSpacing: 3.8,
        stitchLen: 7.5,
        gapLen: 4.5,
        stitchWeight: 0.58
      });
    } else if (sideW < 0) {
      let rSlopePts = [
        [apexX + sideW - 6, apexY + skewSide - 2],
        [apexX, apexY - 2],
        [xL - 4, yTL + 2],
        [xSide - 5, ySideT + 3]
      ];
      drawAppliquePatch(rSlopePts, roofFam, false, {
        corrugated: true,
        ribAngle: -25,
        ribSpacing: 3.8,
        stitchLen: 7.5,
        gapLen: 4.5,
        stitchWeight: 0.58
      });
    }
    // Roof overhang eave shadow line
    brush.set("rotring", PALETTE.inkDark, 0.9);
    brush.line(xL - 5, yTL + 2, apexX, apexY);
    brush.line(apexX, apexY, xR + 5, yTR + 2);
  } else if (roofType === "mansard" || roofType === "hip") {
    let inset = w * 0.16;
    let rTopL = [xL + inset, yTL - roofH];
    let rTopR = [xR - inset, yTR - roofH];
    let frontRoofPts = [[xL - 5, yTL + 2], rTopL, rTopR, [xR + 5, yTR + 2]];
    drawAppliquePatch(frontRoofPts, roofFam, true, {
      corrugated: true,
      ribAngle: 82,
      ribSpacing: 3.8,
      doubleSeam: true,
      stitchLen: 7.5,
      gapLen: 4.5,
      stitchWeight: 0.58
    });

    if (Math.abs(sideW) > 4) {
      let sideRoofPts = sideW > 0
        ? [rTopR, [rTopR[0] + sideW * 0.85, rTopR[1] + skewSide], [xSide + 4, ySideT + 2], [xR + 5, yTR + 2]]
        : [[rTopL[0] + sideW * 0.85, rTopL[1] + skewSide], rTopL, [xL - 5, yTL + 2], [xSide - 4, ySideT + 2]];
      drawAppliquePatch(sideRoofPts, roofFam, false, {
        corrugated: true,
        ribAngle: 95,
        ribSpacing: 3.8,
        stitchLen: 7,
        gapLen: 4.5,
        stitchWeight: 0.5
      });
    }

    // Small dormer window on mansard roof
    if (roofType === "mansard" && w > 75) {
      let dx = (xL + xR) * 0.5 - 11;
      let dy = (yTL + yTR) * 0.5 - roofH * 0.78;
      let dPts = [[dx, dy], [dx + 22, dy - 1], [dx + 22, dy + roofH * 0.65], [dx, dy + roofH * 0.65]];
      drawAppliquePatch(dPts, PALETTE.cream, true, { useWash: true, stitchLen: 4.5, gapLen: 3, stitchWeight: 0.45 });
      brush.noStroke();
      brush.wash(PALETTE.inkDark, 230);
      drawPoly([[dx + 4, dy + 4], [dx + 18, dy + 3], [dx + 18, dy + roofH * 0.55], [dx + 4, dy + roofH * 0.55]], 0);
      brush.noWash();
    }
  } else {
    // Shed / lean-to corrugated roof
    let rPts = [
      [xL - 5, yTL - roofH * 0.35],
      [xR + (sideW > 0 ? sideW * 0.7 : 5), yTR - roofH + (sideW > 0 ? skewSide * 0.5 : 0)],
      [xR + (sideW > 0 ? sideW + 4 : 5), (sideW > 0 ? ySideT : yTR) + 3],
      [xL - 5, yTL + 3]
    ];
    drawAppliquePatch(rPts, roofFam, true, {
      corrugated: true,
      ribAngle: 75,
      ribSpacing: 3.8,
      stitchLen: 7.5,
      gapLen: 4.5,
      stitchWeight: 0.55
    });
  }

  // 6. Windows & Doors on Front Wall
  let floorH = h / stories;
  for (let st = 0; st < stories; st++) {
    let wyTopRatio = (st + 0.22) / stories;
    let wyBotRatio = (st + 0.74) / stories;

    for (let c = 0; c < winCols; c++) {
      let wxLeftRatio = (c + 0.28) / (winCols + 0.15);
      let wxRightRatio = (c + 0.72) / (winCols + 0.15);

      // Ground floor door option on rightmost or leftmost bay
      let isDoor = (st === stories - 1 && c === 0 && cfg.hasDoor);
      let bRatio = isDoor ? 0.98 : wyBotRatio;

      let pTL = lerpPt(lerpPt([xL, yTL], [xR, yTR], wxLeftRatio), lerpPt([xL, yBL], [xR, yBR], wxLeftRatio), wyTopRatio);
      let pTR = lerpPt(lerpPt([xL, yTL], [xR, yTR], wxRightRatio), lerpPt([xL, yBL], [xR, yBR], wxRightRatio), wyTopRatio);
      let pBR = lerpPt(lerpPt([xL, yTL], [xR, yTR], wxRightRatio), lerpPt([xL, yBL], [xR, yBR], wxRightRatio), bRatio);
      let pBL = lerpPt(lerpPt([xL, yTL], [xR, yTR], wxLeftRatio), lerpPt([xL, yBL], [xR, yBR], wxLeftRatio), bRatio);

      let winW = pTR[0] - pTL[0];
      let winH = pBL[1] - pTL[1];

      // Rust drip below sill
      if (!isDoor) {
        brush.noStroke();
        brush.wash(PALETTE.rust, 75);
        drawPoly([pBL, pBR, [pBR[0] - 1, pBR[1] + 9], [pBL[0] + 1, pBL[1] + 11]], 0);
        brush.noWash();
      }

      // Deep dark recessed interior (High Contrast!)
      brush.noStroke();
      brush.wash(PALETTE.inkDark, 238);
      drawPoly([pTL, pTR, pBR, pBL], 0);
      brush.noWash();

      // Colored stained-glass transom or glass glint
      if (!isDoor && winH > 16) {
        let transCol = (c + st) % 2 === 0 ? PALETTE.mustard[0] : PALETTE.coralBright[0];
        let pMidL = lerpPt(pTL, pBL, 0.28);
        let pMidR = lerpPt(pTR, pBR, 0.28);
        brush.noStroke();
        brush.wash(transCol, 155);
        drawPoly([pTL, pTR, pMidR, pMidL], 0);
        brush.noWash();

        // Diagonal sky reflection in lower pane
        brush.set("2H", PALETTE.warpLight, 0.35);
        brush.line(pMidL[0] + 2, pMidL[1] + 4, pBR[0] - 3, pBR[1] - 4);
      }

      // Louvered Shutters (small fabric strips flanking window)
      if (hasShutters && !isDoor && winW > 11) {
        let shW = Math.min(8, winW * 0.42);
        let shL = [[pTL[0] - shW, pTL[1]], pTL, pBL, [pBL[0] - shW, pBL[1]]];
        let shR = [pTR, [pTR[0] + shW, pTR[1]], [pBR[0] + shW, pBR[1]], pBR];
        brush.noStroke();
        brush.wash(shutterFam[0], 215);
        drawPoly(shL, 0);
        drawPoly(shR, 0);
        brush.noWash();

        // Louver slats & stitch outline
        brush.set("rotring", shutterFam[3], 0.32);
        drawPoly(shL, 0);
        drawPoly(shR, 0);
        for (let sy = pTL[1] + 3; sy < pBL[1] - 2; sy += 3.5) {
          brush.line(pTL[0] - shW + 1, sy, pTL[0] - 1, sy);
          brush.line(pTR[0] + 1, sy, pTR[0] + shW - 1, sy);
        }
      }

      // Crisp cream/thread window frame & muntin bars
      let frameCol = fam === PALETTE.cream ? PALETTE.cobalt[0] : PALETTE.threadCream;
      brush.set("rotring", frameCol, 0.55);
      drawPoly([pTL, pTR, pBR, pBL], 0);
      let midTop = lerpPt(pTL, pTR, 0.5);
      let midBot = lerpPt(pBL, pBR, 0.5);
      brush.line(midTop[0], midTop[1], midBot[0], midBot[1]);
      let midL = lerpPt(pTL, pBL, 0.45);
      let midR = lerpPt(pTR, pBR, 0.45);
      brush.line(midL[0], midL[1], midR[0], midR[1]);

      // Sill ledge
      brush.set("rotring", frameCol, 0.8);
      brush.line(pBL[0] - 3, pBL[1] + 1, pBR[0] + 3, pBR[1] + 1);
    }
  }

  // Side wall narrow windows
  if (sidePts && Math.abs(sideW) > 22) {
    for (let st = 0; st < stories; st++) {
      let wy1 = (st + 0.26) / stories;
      let wy2 = (st + 0.68) / stories;
      let sTL = lerpPt(lerpPt(sidePts[0], sidePts[1], 0.35), lerpPt(sidePts[3], sidePts[2], 0.35), wy1);
      let sTR = lerpPt(lerpPt(sidePts[0], sidePts[1], 0.68), lerpPt(sidePts[3], sidePts[2], 0.35), wy1);
      let sBR = lerpPt(lerpPt(sidePts[0], sidePts[1], 0.68), lerpPt(sidePts[3], sidePts[2], 0.68), wy2);
      let sBL = lerpPt(lerpPt(sidePts[0], sidePts[1], 0.35), lerpPt(sidePts[3], sidePts[2], 0.35), wy2);
      brush.noStroke();
      brush.wash(PALETTE.inkDark, 235);
      drawPoly([sTL, sTR, sBR, sBL], 0);
      brush.noWash();
      brush.set("rotring", PALETTE.burlapMid, 0.4);
      drawPoly([sTL, sTR, sBR, sBL], 0);
    }
  }

  // 7. Overhanging Balcony with Wrought-Iron Railing & Laundry
  if (hasBalcony) {
    let bYRatio = balconyFloor / stories;
    let bL = lerpPt([xL, yTL], [xL, yBL], bYRatio);
    let bR = lerpPt([xR, yTR], [xR, yBR], bYRatio);
    let bOut = 10;
    let railH = 20;

    // Balcony floor slab & shadow
    let slabPts = [
      [bL[0] - 4, bL[1]],
      [bR[0] + 4, bR[1]],
      [bR[0] + 4, bR[1] + bOut],
      [bL[0] - 4, bL[1] + bOut]
    ];
    brush.noStroke();
    brush.wash(PALETTE.inkDark, 200);
    drawPoly(slabPts, 0);
    brush.noWash();

    // Iron brackets underneath
    brush.set("rotring", PALETTE.inkDark, 0.6);
    for (let k = 0.15; k <= 0.86; k += 0.35) {
      let bx = lerp(bL[0], bR[0], k);
      let by = lerp(bL[1], bR[1], k);
      brush.line(bx, by + bOut, bx, by + bOut + 12);
      brush.line(bx - 5, by + bOut, bx, by + bOut + 12);
    }

    // Iron railing balusters
    brush.set("rotring", PALETTE.inkDark, 0.55);
    brush.line(bL[0] - 4, bL[1] - railH, bR[0] + 4, bR[1] - railH);
    brush.line(bL[0] - 4, bL[1], bR[0] + 4, bR[1]);
    let numBars = Math.max(6, Math.floor(w / 9));
    for (let b = 0; b <= numBars; b++) {
      let t = b / numBars;
      let rx = lerp(bL[0] - 4, bR[0] + 4, t);
      let ry = lerp(bL[1], bR[1], t);
      brush.line(rx, ry, rx, ry - railH);
    }
    // Contrast stitch along balcony top rail
    drawRunningStitch([[bL[0] - 4, bL[1] - railH], [bR[0] + 4, bR[1] - railH]], false, fam[4], 6, 4, 0.48);

    // Balcony laundry items draped over the rail or hanging from balcony line
    if (cfg.balconyLaundry) {
      drawLaundryLineBetween([bL[0] - 2, bL[1] - railH + 2], [bR[0] + 2, bR[1] - railH + 2], cfg.balconyLaundry, 0.78);
    }
  }
}

// ============================================================================
// 3. TIERED VALPARAÍSO HILLSIDE HOUSES (BACK TO FRONT)
// ============================================================================

function drawTier1CrestHouses() {
  // Left Ridge Summit Houses (y ~ 180..320)
  drawHouse({
    x: -10, y: 205, w: 115, h: 115, sideW: 32, skewFront: -5, skewSide: -10,
    fam: PALETTE.cobaltDeep, roofFam: PALETTE.coral, roofType: "gable", roofH: 36,
    stories: 2, winCols: 2, shutterFam: PALETTE.mustard
  });

  // Tall Victorian Mirador / Turret on Left Crest
  drawHouse({
    x: 115, y: 172, w: 92, h: 135, sideW: 28, skewFront: -4, skewSide: -12,
    fam: PALETTE.mustard, roofFam: PALETTE.cobalt, roofType: "mansard", roofH: 38,
    stories: 3, winCols: 2, shutterFam: PALETTE.coral, hasBalcony: true, balconyFloor: 2
  });

  drawHouse({
    x: 220, y: 215, w: 105, h: 115, sideW: 26, skewFront: 4, skewSide: -8,
    fam: PALETTE.coral, roofFam: PALETTE.lime, roofType: "gable", roofH: 32,
    stories: 2, winCols: 2, shutterFam: PALETTE.cream
  });

  drawHouse({
    x: 332, y: 255, w: 96, h: 105, sideW: 24, skewFront: 6, skewSide: -8,
    fam: PALETTE.lime, roofFam: PALETTE.cobaltDeep, roofType: "shed", roofH: 24,
    stories: 2, winCols: 2, shutterFam: PALETTE.coral
  });

  // Upper Stair Summit House
  drawHouse({
    x: 430, y: 280, w: 85, h: 95, sideW: 20, skewFront: 4, skewSide: -8,
    fam: PALETTE.cream, roofFam: PALETTE.coralBright, roofType: "gable", roofH: 28,
    stories: 2, winCols: 2, shutterFam: PALETTE.cobalt
  });

