// ============================================================================
// FUNICULAR VIADUCT & STAIRCASE SUB-STRUCTURES
// ============================================================================

function drawFunicularViaductAndTrack() {
  // Funicular corridor climbs from bottom-right-center (x: 790, y: 1200)
  // to the Upper Station at (x: 585, y: 315)
  let topL = [558, 315], topR = [622, 315];
  let botL = [730, 1200], botR = [848, 1200];

  // Viaduct retaining wall on the left side of the track (gives 3D height)
  let wallPts = [
    topL,
    botL,
    [botL[0] - 34, 1200],
    [topL[0] - 18, 325]
  ];
  drawAppliquePatch(wallPts, PALETTE.slate, false, {
    corrugated: false,
    weaveSpacing: 6.5,
    weathering: true,
    stitchCol: PALETTE.threadGold,
    stitchLen: 8,
    gapLen: 5
  });

  // Iron truss cross-bracing along the viaduct side wall
  brush.set("rotring", PALETTE.burlapMid, 0.5);
  let numBays = 14;
  for (let i = 0; i < numBays; i++) {
    let t1 = i / numBays;
    let t2 = (i + 1) / numBays;
    let a1 = lerpPt(topL, botL, t1);
    let a2 = lerpPt(topL, botL, t2);
    let b1 = lerpPt([topL[0] - 18, 325], [botL[0] - 34, 1200], t1);
    let b2 = lerpPt([topL[0] - 18, 325], [botL[0] - 34, 1200], t2);
    brush.line(a1[0], a1[1], b1[0], b1[1]);
    brush.line(a1[0], a1[1], b2[0], b2[1]);
    brush.line(a2[0], a2[1], b1[0], b1[1]);
  }

  // Track bed surface (dark weathered ballast + coarse burlap weave)
  let bedPts = [topL, topR, botR, botL];
  drawAppliquePatch(bedPts, PALETTE.slate, true, {
    corrugated: false,
    weaveSpacing: 6.0,
    stitchCol: PALETTE.threadCoral,
    stitchLen: 9,
    gapLen: 5.5
  });

  // Foreshortened wooden railway sleepers (cross-ties) climbing the incline
  let numSleepers = 58;
  for (let i = 0; i <= numSleepers; i++) {
    let t = Math.pow(i / numSleepers, 1.12);
    let pL = lerpPt(topL, botL, t);
    let pR = lerpPt(topR, botR, t);
    let sL = lerpPt(pL, pR, 0.06);
    let sR = lerpPt(pL, pR, 0.94);
    brush.set("rotring", i % 2 === 0 ? PALETTE.burlapShadow : PALETTE.inkDark, lerp(0.45, 1.1, t));
    brush.line(sL[0], sL[1], sR[0], sR[1]);
  }

  // Dual Tracks (4 Steel Rails + 2 Central Traction Cables)
  let railOffsets = [0.14, 0.42, 0.58, 0.86];
  for (let r of railOffsets) {
    let rTop = lerpPt(topL, topR, r);
    let rBot = lerpPt(botL, botR, r);
    brush.set("rotring", PALETTE.inkDark, 0.95);
    brush.line(rTop[0] + 1.5, rTop[1], rBot[0] + 1.5, rBot[1]);
    brush.set("rotring", PALETTE.threadCream, 0.65);
    brush.line(rTop[0], rTop[1], rBot[0], rBot[1]);
  }

  // Central haulage cables with dashed stitch sheen
  for (let c of [0.28, 0.72]) {
    let cTop = lerpPt(topL, topR, c);
    let cBot = lerpPt(botL, botR, c);
    brush.set("rotring", PALETTE.inkDark, 0.55);
    brush.line(cTop[0], cTop[1], cBot[0], cBot[1]);
    drawRunningStitch([cTop, cBot], false, PALETTE.threadGold, 6, 8, 0.38, 0.3);
  }
}

function drawStaircaseStructure() {
  // Winding Valparaíso Staircase (Escalera) from upper saddle (x: 495, y: 345)
  // down through landings to bottom foreground (x: 310..565, y: 1200)
  let flights = [
    // Upper flight 1
    { topL: [472, 345], topR: [518, 345], botL: [445, 485], botR: [505, 485], steps: 14 },
    // Upper-mid flight 2
    { topL: [445, 485], topR: [508, 485], botL: [472, 655], botR: [548, 655], steps: 15 },
    // Mid-lower flight 3
    { topL: [465, 655], topR: [548, 655], botL: [390, 895], botR: [495, 895], steps: 18 },
    // Foreground grand flight 4
    { topL: [380, 895], topR: [502, 895], botL: [305, 1200], botR: [565, 1200], steps: 20 }
  ];

  let riserFams = [PALETTE.cobalt, PALETTE.mustard, PALETTE.coralBright, PALETTE.lime, PALETTE.cream];

  for (let fIdx = 0; fIdx < flights.length; fIdx++) {
    let fl = flights[fIdx];

    // Base cloth patch for flight
    let flPts = [fl.topL, fl.topR, fl.botR, fl.botL];
    drawAppliquePatch(flPts, PALETTE.cream, true, {
      corrugated: false,
      weaveSpacing: 6.5,
      stitchCol: PALETTE.inkDark,
      stitchLen: 8,
      gapLen: 5
    });

    // Individual steps: sunlit stone/burlap tread + brightly painted Valparaíso riser!
    for (let s = 0; s < fl.steps; s++) {
      let t1 = s / fl.steps;
      let tMid = (s + 0.48) / fl.steps;
      let t2 = (s + 1) / fl.steps;

      let pTL = lerpPt(fl.topL, fl.botL, t1);
      let pTR = lerpPt(fl.topR, fl.botR, t1);
      let pML = lerpPt(fl.topL, fl.botL, tMid);
      let pMR = lerpPt(fl.topR, fl.botR, tMid);
      let pBL = lerpPt(fl.topL, fl.botL, t2);
      let pBR = lerpPt(fl.topR, fl.botR, t2);

      // Sunlit horizontal tread
      brush.noStroke();
      brush.wash(s % 2 === 0 ? PALETTE.burlapLight : PALETTE.burlapMid, 210);
      drawPoly([pTL, pTR, pMR, pML], 0);
      brush.noWash();

      // Painted vertical riser (high contrast cheerful stripes!)
      let rFam = riserFams[(s + fIdx * 2) % riserFams.length];
      brush.noStroke();
      brush.wash(rFam[0], 215);
      drawPoly([pML, pMR, pBR, pBL], 0);
      brush.noWash();

      // Step nosing shadow line
      brush.set("rotring", PALETTE.inkDark, lerp(0.45, 0.85, fIdx / 3));
      brush.line(pML[0], pML[1], pMR[0], pMR[1]);
      brush.set("2H", rFam[3], 0.35);
      brush.line(pBL[0], pBL[1], pBR[0], pBR[1]);

      // Running stitch across foreground risers
      if (fIdx >= 2 && s % 2 === 0) {
        drawRunningStitch([lerpPt(pML, pBL, 0.5), lerpPt(pMR, pBR, 0.5)], false, rFam[4], 6, 4.5, 0.42, 0.4);
      }
    }

    // Stepped side parapet walls flanking the stairs
    let wallW = lerp(8, 18, fIdx / 3);
    let wallH = lerp(14, 28, fIdx / 3);
    let leftParapet = [
      [fl.topL[0] - wallW, fl.topL[1] - wallH],
      [fl.topL[0], fl.topL[1] - wallH * 0.4],
      fl.botL,
      [fl.botL[0] - wallW, fl.botL[1]]
    ];
    drawAppliquePatch(leftParapet, fIdx % 2 === 0 ? PALETTE.mustard : PALETTE.coral, false, {
      useWash: true,
      stitchCol: PALETTE.threadCream,
      stitchLen: 7,
      gapLen: 4.5
    });
  }
}

