function drawSingleFunicularCar(cx, cy, w, h, bodyFam, lowerFam, roofFam, sc) {
  let xL = cx - w * 0.5;
  let xR = cx + w * 0.5;
  let yT = cy - h * 0.5;
  let yB = cy + h * 0.5;
  let sideW = 24 * sc;
  let sideClimb = -28 * sc;

  // 1. Stepped triangular steel undercarriage chassis (adapts horizontal cabin to steep 50° slope!)
  let chassisPts = [
    [xL + 4, yB],
    [xR + sideW - 2, yB + sideClimb],
    [xR + sideW - 2, yB + 8 * sc],
    [xL + 6, yB + 38 * sc]
  ];
  brush.noStroke();
  brush.wash(PALETTE.inkDark, 235);
  drawPoly(chassisPts, 0);
  brush.noWash();

  // Steel wheels & truss struts under chassis
  brush.set("rotring", PALETTE.threadCream, 0.55 * sc);
  drawPoly(chassisPts, 0);
  brush.line(xL + 16 * sc, yB, xL + 16 * sc, yB + 30 * sc);
  brush.line(xR - 8 * sc, yB, xR - 8 * sc, yB + 16 * sc);
  brush.circle(xL + 14 * sc, yB + 34 * sc, 5 * sc, 0.08);
  brush.circle(xR + sideW - 10 * sc, yB + 6 * sc, 5 * sc, 0.08);

  // 2. Cabin Side Wall (climbing perspective)
  let sideUpper = [
    [xR, yT],
    [xR + sideW, yT + sideClimb],
    [xR + sideW, yB + sideClimb * 0.45],
    [xR, yB - h * 0.38]
  ];
  let sideLower = [
    [xR, yB - h * 0.38],
    [xR + sideW, yB + sideClimb * 0.45],
    [xR + sideW, yB + sideClimb],
    [xR, yB]
  ];
  drawAppliquePatch(sideUpper, bodyFam, false, { useWash: true, stitchLen: 5 * sc, gapLen: 3.5 * sc, stitchWeight: 0.45 });
  drawAppliquePatch(sideLower, lowerFam, false, { useWash: true, stitchLen: 5 * sc, gapLen: 3.5 * sc, stitchWeight: 0.45 });

  // 3. Cabin Front Face (Two-tone heritage Valparaíso livery!)
  let frontUpper = [[xL, yT], [xR, yT], [xR, yB - h * 0.38], [xL, yB - h * 0.38]];
  let frontLower = [[xL, yB - h * 0.38], [xR, yB - h * 0.38], [xR, yB], [xL, yB]];
  drawAppliquePatch(frontUpper, bodyFam, true, {
    useWash: false,
    corrugated: false,
    stitchCol: PALETTE.inkDark,
    stitchLen: 6 * sc,
    gapLen: 3.8 * sc,
    stitchWeight: 0.55
  });
  drawAppliquePatch(frontLower, lowerFam, true, {
    useWash: false,
    corrugated: true,
    ribAngle: 90,
    ribSpacing: 3.5,
    stitchCol: PALETTE.threadGold,
    stitchLen: 6 * sc,
    gapLen: 3.8 * sc,
    stitchWeight: 0.55
  });

  // 4. Arched Cabin Windows with warm interior & passenger silhouettes
  for (let i = 0; i < 3; i++) {
    let wx1 = lerp(xL + 6 * sc, xR - 6 * sc, i / 3) + 2 * sc;
    let wx2 = lerp(xL + 6 * sc, xR - 6 * sc, (i + 1) / 3) - 2 * sc;
    let wy1 = yT + 10 * sc;
    let wy2 = yB - h * 0.42;
    let wPts = [[wx1, wy1], [wx2, wy1], [wx2, wy2], [wx1, wy2]];
    brush.noStroke();
    brush.wash(PALETTE.inkDark, 235);
    drawPoly(wPts, 0);
    brush.noWash();

    // Passenger head/shoulder silhouette inside cabin
    if (i !== 1) {
      let px = (wx1 + wx2) * 0.5;
      let py = wy2 - 6 * sc;
      brush.noStroke();
      brush.wash(i === 0 ? PALETTE.coralBright[0] : PALETTE.limeBright[0], 210);
      brush.circle(px, py + 3 * sc, 5 * sc, 0.1);
      brush.wash(PALETTE.burlapMid, 220);
      brush.circle(px, py - 4 * sc, 3.2 * sc, 0.1);
      brush.noWash();
    }

    brush.set("rotring", PALETTE.threadCream, 0.5 * sc);
    drawPoly(wPts, 0);
  }

  // Side windows along climbing flank
  for (let j = 0; j < 2; j++) {
    let t1 = 0.15 + j * 0.42;
    let t2 = t1 + 0.30;
    let swPts = [
      lerpPt([xR, yT + 8 * sc], [xR + sideW, yT + sideClimb + 8 * sc], t1),
      lerpPt([xR, yT + 8 * sc], [xR + sideW, yT + sideClimb + 8 * sc], t2),
      lerpPt([xR, yB - h * 0.42], [xR + sideW, yB + sideClimb * 0.55], t2),
      lerpPt([xR, yB - h * 0.42], [xR + sideW, yB + sideClimb * 0.55], t1)
    ];
    brush.noStroke();
    brush.wash(PALETTE.inkDark, 230);
    drawPoly(swPts, 0);
    brush.noWash();
    brush.set("rotring", PALETTE.threadCream, 0.45 * sc);
    drawPoly(swPts, 0);
  }

  // 5. Clerestory Roof & Cable Hitch Wheel
  let roofPts = [
    [xL - 4 * sc, yT],
    [xR + 4 * sc, yT],
    [xR + sideW + 3 * sc, yT + sideClimb - 6 * sc],
    [xL + sideW * 0.6, yT + sideClimb * 0.65 - 8 * sc]
  ];
  drawAppliquePatch(roofPts, roofFam, true, {
    useWash: true,
    stitchCol: PALETTE.threadCream,
    stitchLen: 5.5 * sc,
    gapLen: 3.5 * sc,
    stitchWeight: 0.5
  });
}

