  // 5. Midground Climber with guitar/parcel on back
  drawClimbingFigure(468, 785, 0.72, PALETTE.mustardWarm, PALETTE.cobaltDeep, false, true);

  // 6. Mid-upper Landing Figures
  drawClimbingFigure(498, 638, 0.58, PALETTE.coralBright, PALETTE.cream, true, false);
  drawClimbingFigure(475, 565, 0.52, PALETTE.lime, PALETTE.slate, false, true);

