function drawClimbingFigure(x, y, sc, topFam, botFam, hasSkirt = false, hasBag = false) {
  let h = 74 * sc;
  let w = 24 * sc;

  // Cast shadow falling across stair treads
  brush.noStroke();
  brush.wash(PALETTE.inkDark, 150);
  drawPoly([
    [x - 8 * sc, y],
    [x + 22 * sc, y + 4 * sc],
    [x + 28 * sc, y + 12 * sc],
    [x - 4 * sc, y + 8 * sc]
  ], 0);
  brush.noWash();

  // Legs in climbing stride (left leg planted, right leg stepping up)
  brush.set("rotring", PALETTE.inkDark, 1.3 * sc);
  brush.line(x - 4 * sc, y - h * 0.36, x - 6 * sc, y);
  brush.line(x + 5 * sc, y - h * 0.38, x + 7 * sc, y - 9 * sc);

  // Lower garment appliqué patch (skirt or trousers)
  let botPts = hasSkirt
    ? [[x - 9 * sc, y - h * 0.52], [x + 9 * sc, y - h * 0.52], [x + 13 * sc, y - h * 0.22], [x - 12 * sc, y - h * 0.20]]
    : [[x - 8 * sc, y - h * 0.52], [x + 8 * sc, y - h * 0.52], [x + 9 * sc, y - h * 0.20], [x - 8 * sc, y - h * 0.18]];
  drawAppliquePatch(botPts, botFam, true, {
    useWash: true,
    stitchLen: 4.5 * sc,
    gapLen: 3 * sc,
    stitchWeight: 0.45 * sc
  });

  // Torso / Jacket / Shawl appliqué patch (leaning slightly forward into climb)
  let topPts = [
    [x - 9 * sc, y - h * 0.82],
    [x + 10 * sc, y - h * 0.80],
    [x + 11 * sc, y - h * 0.48],
    [x - 10 * sc, y - h * 0.50]
  ];
  drawAppliquePatch(topPts, topFam, true, {
    useWash: true,
    stitchLen: 4.5 * sc,
    gapLen: 3 * sc,
    stitchWeight: 0.48 * sc
  });

  // Market tote bag or backpack
  if (hasBag) {
    let bagPts = [
      [x - 17 * sc, y - h * 0.66],
      [x - 6 * sc, y - h * 0.68],
      [x - 5 * sc, y - h * 0.42],
      [x - 18 * sc, y - h * 0.40]
    ];
    drawAppliquePatch(bagPts, PALETTE.limeBright, true, {
      useWash: true,
      stitchLen: 3.5 * sc,
      gapLen: 2.5 * sc,
      stitchWeight: 0.4 * sc
    });
  }

  // Head & Sunhat / Hair
  brush.noStroke();
  brush.wash("#d99b72", 230);
  brush.circle(x + 1 * sc, y - h * 0.91, 6.5 * sc, 0.08);
  brush.noWash();

  // Dark hair & woven hat brim
  brush.noStroke();
  brush.wash(PALETTE.inkDark, 235);
  brush.circle(x, y - h * 0.93, 6.2 * sc, 0.1);
  brush.noWash();
  brush.set("rotring", PALETTE.mustard[0], 1.1 * sc);
  brush.line(x - 9 * sc, y - h * 0.94, x + 10 * sc, y - h * 0.92);
}

function drawStreetDog(x, y, sc) {
  // Cast shadow
  brush.noStroke();
