function drawLaundryLineBetween(pA, pB, fams, sc = 1.0) {
  let dist = Math.hypot(pB[0] - pA[0], pB[1] - pA[1]);
  let sag = Math.min(38 * sc, dist * 0.12);
  let mid = [(pA[0] + pB[0]) * 0.5, (pA[1] + pB[1]) * 0.5 + sag];

  // Clothesline cord
  brush.set("rotring", PALETTE.inkDark, 0.55 * sc);
  brush.spline([pA, mid, pB], 0.5);

  let count = fams.length;
  for (let i = 0; i < count; i++) {
    let t = (i + 0.65) / (count + 0.3);
    // Parabolic sag position along line
    let u = 1 - t;
    let lx = u * u * pA[0] + 2 * u * t * mid[0] + t * t * pB[0];
    let ly = u * u * pA[1] + 2 * u * t * mid[1] + t * t * pB[1] - sag * 0.12;

    let fam = fams[i];
    let type = (i % 4); // 0: bedsheet/towel, 1: T-shirt, 2: trousers, 3: dress/small items
    let breeze = 3.5 * sc;

    if (type === 0) {
      // Fluttering sheet or striped towel
      let gw = 18 * sc, gh = 28 * sc;
      let pts = [
        [lx - gw * 0.5, ly],
        [lx + gw * 0.5, ly + 1],
        [lx + gw * 0.5 + breeze, ly + gh],
        [lx - gw * 0.5 + breeze * 0.7, ly + gh - 2]
      ];
      drawAppliquePatch(pts, fam, true, { useWash: true, stitchLen: 4 * sc, gapLen: 2.8 * sc, stitchWeight: 0.42 });
    } else if (type === 1) {
      // T-shirt with sleeves
      let gw = 16 * sc, gh = 21 * sc;
      let pts = [
        [lx - gw * 0.7, ly + 3 * sc],
        [lx - gw * 0.4, ly],
        [lx + gw * 0.4, ly],
        [lx + gw * 0.75, ly + 4 * sc],
        [lx + gw * 0.45 + breeze, ly + 9 * sc],
        [lx + gw * 0.4 + breeze, ly + gh],
        [lx - gw * 0.4 + breeze, ly + gh],
        [lx - gw * 0.45 + breeze * 0.5, ly + 9 * sc]
      ];
      drawAppliquePatch(pts, fam, true, { useWash: true, stitchLen: 3.8 * sc, gapLen: 2.5 * sc, stitchWeight: 0.42 });
    } else if (type === 2) {
      // Trousers with two legs
      let gw = 14 * sc, gh = 25 * sc;
      let pts = [
        [lx - gw * 0.5, ly],
        [lx + gw * 0.5, ly],
        [lx + gw * 0.55 + breeze, ly + gh],
        [lx + gw * 0.12 + breeze, ly + gh],
        [lx + breeze * 0.5, ly + gh * 0.42],
        [lx - gw * 0.12 + breeze, ly + gh],
        [lx - gw * 0.5 + breeze, ly + gh]
      ];
      drawAppliquePatch(pts, fam, true, { useWash: true, stitchLen: 3.8 * sc, gapLen: 2.5 * sc, stitchWeight: 0.42 });
    } else {
      // Flared dress / apron
      let gw = 14 * sc, gh = 22 * sc;
      let pts = [
        [lx - gw * 0.35, ly],
        [lx + gw * 0.35, ly],
        [lx + gw * 0.7 + breeze, ly + gh],
        [lx - gw * 0.55 + breeze, ly + gh]
      ];
      drawAppliquePatch(pts, fam, true, { useWash: true, stitchLen: 3.8 * sc, gapLen: 2.5 * sc, stitchWeight: 0.42 });
    }

    // Two tiny wooden clothes-pegs pinning each item
    brush.set("rotring", PALETTE.mustard[0], 0.75 * sc);
    brush.line(lx - 4 * sc, ly - 3 * sc, lx - 4 * sc, ly + 2 * sc);
    brush.line(lx + 4 * sc, ly - 3 * sc, lx + 4 * sc, ly + 2 * sc);
  }
}

// ============================================================================
// 7. TANGLED POWER LINES, UTILITY POLES & SELVEDGE STITCHES
// ============================================================================

function drawUtilityPolesAndPowerLines() {
  // 5 Crooked Valparaíso Utility Poles with Cross-Arms, Transformers & Ceramic Insulators
  let poles = [
    { x: 112, yTop: 245, yBot: 1200, w: 9.5, tilt: 6, crossbars: [265, 305, 355], hasTransformer: true },
    { x: 358, yTop: 310, yBot: 890, w: 6.5, tilt: -5, crossbars: [325, 360], hasTransformer: false },
    { x: 668, yTop: 270, yBot: 880, w: 6.8, tilt: 4, crossbars: [285, 322], hasTransformer: true },
    { x: 1032, yTop: 225, yBot: 1200, w: 10.0, tilt: -8, crossbars: [248, 290, 342], hasTransformer: true },
    { x: 515, yTop: 185, yBot: 345, w: 4.5, tilt: 2, crossbars: [198, 222], hasTransformer: false }
  ];

  // Collect insulator anchor points for tangled catenary cables
  let anchors = [];

  for (let p of poles) {
    let xT = p.x + p.tilt;
    let xB = p.x;
    let polePts = [
      [xT - p.w * 0.4, p.yTop],
      [xT + p.w * 0.4, p.yTop],
      [xB + p.w * 0.65, p.yBot],
      [xB - p.w * 0.65, p.yBot]
    ];

    // Dark weathered pole body + stitch outline
    brush.noStroke();
    brush.wash(PALETTE.inkDark, 238);
    drawPoly(polePts, 0);
    brush.noWash();
    brush.set("rotring", PALETTE.burlapMid, 0.45);
    brush.line(xT - p.w * 0.25, p.yTop, xB - p.w * 0.4, p.yBot);
    drawRunningStitch([[xT, p.yTop], [xB, p.yBot]], false, PALETTE.threadGold, 9, 6, 0.42, 0.4);

    // Cylindrical pole-mounted transformer drum
    if (p.hasTransformer) {
      let ty = p.crossbars[p.crossbars.length - 1] + 22;
      let tx = lerp(xT, xB, (ty - p.yTop) / (p.yBot - p.yTop)) + p.w * 0.9;
      let trPts = [[tx, ty], [tx + p.w * 2.2, ty], [tx + p.w * 2.2, ty + p.w * 3.4], [tx, ty + p.w * 3.4]];
      drawAppliquePatch(trPts, PALETTE.slate, false, { useWash: true, stitchCol: PALETTE.threadCoral, stitchLen: 4.5, gapLen: 3 });
    }

    // Cross-arms & white ceramic pin insulators
    let poleAnchors = [];
    for (let cy of p.crossbars) {
      let cx = lerp(xT, xB, (cy - p.yTop) / (p.yBot - p.yTop));
      let armW = p.w * 4.8;
      brush.set("rotring", PALETTE.inkDark, p.w * 0.28);
      brush.line(cx - armW, cy - 2, cx + armW, cy + 2);
      // Diagonal metal V-brace
      brush.set("rotring", PALETTE.inkDark, 0.55);
      brush.line(cx - armW * 0.5, cy, cx, cy + armW * 0.45);
      brush.line(cx + armW * 0.5, cy, cx, cy + armW * 0.45);

      for (let k = -1; k <= 1; k += 0.5) {
        let ix = cx + armW * k * 0.88;
        let iy = cy + k * 1.8 - 4;
        brush.noStroke();
        brush.wash(PALETTE.threadCream, 235);
        brush.circle(ix, iy, 2.8, 0.05);
        brush.noWash();
        poleAnchors.push([ix, iy]);
      }
    }
    anchors.push(poleAnchors);

    // Tangled reserve wire coils looped around the pole under the crossbars
    let coilY = p.crossbars[p.crossbars.length - 1] + 10;
    let coilX = lerp(xT, xB, (coilY - p.yTop) / (p.yBot - p.yTop));
    brush.set("rotring", PALETTE.inkDark, 0.5);
    for (let c = 0; c < 4; c++) {
      brush.circle(coilX + random(-3, 3), coilY + c * 3, p.w * (1.2 + c * 0.2), 0.25);
    }
  }

  // Sweeping Catenary Power Lines crisscrossing the Pale Hessian Sky & House Canyons
  let wireConnections = [
    [0, 1], [1, 4], [4, 2], [2, 3], [0, 2], [1, 2], [0, 3]
  ];

  for (let conn of wireConnections) {
    let setA = anchors[conn[0]];
    let setB = anchors[conn[1]];
    let count = Math.min(setA.length, setB.length, 6);
    for (let i = 0; i < count; i++) {
      let pA = setA[i];
      let pB = setB[i];
      let span = Math.hypot(pB[0] - pA[0], pB[1] - pA[1]);
      let sag = span * random(0.06, 0.14);
      let mid = [(pA[0] + pB[0]) * 0.5, (pA[1] + pB[1]) * 0.5 + sag];

      let wWeight = (i % 3 === 0) ? 0.72 : 0.42;
      brush.set("rotring", PALETTE.inkDark, wWeight);
      brush.spline([pA, mid, pB], 0.45);

      // Running-stitch contrast thread on select main trunk cables
      if (i === 0) {
        let sCol = (conn[0] + conn[1]) % 2 === 0 ? PALETTE.threadCoral : PALETTE.threadGold;
        drawRunningStitch([pA, mid, pB], false, sCol, 9, 7, 0.42, 0.5);
      }
    }
  }

  // Off-canvas foreground catenary cables swooping across the upper sky corners
  let skyWires = [
    [[0, 95], [340, 195], [668, 282]],
    [[0, 145], [112, 265], [358, 325]],
    [[1200, 80], [1032, 248], [668, 285]],
    [[1200, 155], [1032, 290], [790, 385]],
    [[112, 305], [260, 480], [540, 515]],
    [[1032, 342], [865, 510], [665, 675]]
  ];
  for (let idx = 0; idx < skyWires.length; idx++) {
