function resetBrush() {
  brush.noStroke();
  brush.noFill();
  brush.noWash();
  brush.noHatch();
  brush.noMass();
  brush.noField();
}

// Watercolor fill polygon with organic bleed & texture
function wcPoly(pts, col, alpha = 85, bleed = 0.07, tex = 0.42, curv = 0.12) {
  if (!pts || pts.length < 3) return;
  resetBrush();
  brush.fill(col, alpha);
  brush.fillBleed(bleed, "out");
  brush.fillTexture(tex, 0.32);
  brush.beginShape(curv);
  for (let i = 0; i < pts.length; i++) {
    brush.vertex(pts[i][0], pts[i][1]);
  }
  brush.endShape(true);
  resetBrush();
}

// Fast translucent wash polygon for crisp glazed layers (PV cells, glass, sharp light planes)
function washPoly(pts, col, alpha = 90) {
  if (!pts || pts.length < 3) return;
  resetBrush();
  let p = new brush.Polygon(pts);
  p.wash(col, alpha);
  resetBrush();
}

// Fine hatched polygon for tonal modeling
function hatchPoly(pts, dist, angle, brushName, col, weight = 0.35, rand = 0.04) {
  if (!pts || pts.length < 3) return;
  resetBrush();
  let p = new brush.Polygon(pts);
  brush.hatchStyle(brushName, col, weight);
  p.hatch(dist, angle, { rand: rand, continuous: false });
  resetBrush();
}

// Crisp ink line
function inkLine(x1, y1, x2, y2, weight = 0.35, col = PAL.sepiaDark, bName = "rotring") {
  resetBrush();
  brush.set(bName, col, weight);
  brush.line(x1, y1, x2, y2);
  resetBrush();
}

// Smooth ink/pencil spline
function inkSpline(pts, curv = 0.5, weight = 0.35, col = PAL.sepiaDark, bName = "rotring") {
  if (!pts || pts.length < 2) return;
  resetBrush();
  brush.set(bName, col, weight);
  brush.spline(pts, curv);
  resetBrush();
}

// Polygon contour in ink
function inkPoly(pts, weight = 0.35, col = PAL.sepiaDark, close = true, curv = 0.08, bName = "rotring") {
  if (!pts || pts.length < 2) return;
  resetBrush();
  brush.set(bName, col, weight);
  brush.beginShape(curv);
  for (let i = 0; i < pts.length; i++) {
    brush.vertex(pts[i][0], pts[i][1]);
  }
  brush.endShape(close);
  resetBrush();
}

// Geometry helpers
function lerp2D(a, b, t) {
  return [a[0] + (b[0] - a[0]) * t, a[1] + (b[1] - a[1]) * t];
}

function quadPt(p00, p10, p11, p01, u, v) {
  let top = lerp2D(p00, p10, u);
  let bot = lerp2D(p01, p11, u);
  return lerp2D(top, bot, v);
}

function ellipsePt(cx, cy, rx, ry, tiltDeg, thetaDeg) {
  let th = (thetaDeg * Math.PI) / 180;
  let rot = (tiltDeg * Math.PI) / 180;
  let lx = rx * Math.cos(th);
  let ly = ry * Math.sin(th);
  return [
    cx + lx * Math.cos(rot) - ly * Math.sin(rot),
    cy + lx * Math.sin(rot) + ly * Math.cos(rot)
  ];
}

function ellipsePoly(cx, cy, rx, ry, tiltDeg, steps = 36, startDeg = 0, endDeg = 360) {
  let pts = [];
  for (let i = 0; i <= steps; i++) {
    let ang = startDeg + ((endDeg - startDeg) * i) / steps;
    pts.push(ellipsePt(cx, cy, rx, ry, tiltDeg, ang));
  }
  return pts;
}

async function setup() {
  createCanvas(1200, 1200, WEBGL);
  brush.scaleBrushes(3);
  angleMode(DEGREES);
