// ============================================================================
// 2. TERRACOTTA COURTYARD TILES & DAPPLED LIGHT PATCHES
// ============================================================================
function drawTerracottaGround() {
  // Base warm terracotta & twilight shadow ground plane (y: 800..1200)
  wcPoly(
    [[0, 810], [1200, 770], [1200, 1200], [0, 1200]],
    PAL.terraMid, 65, 0.12, 0.5, 0.05
  );

  // Perspective grid of terracotta pavers converging toward (260, 500)
  let vp = [260, 500];
  let rowYs = [805, 838, 878, 926, 984, 1055, 1140, 1230];

  for (let r = 0; r < rowYs.length - 1; r++) {
    let y1 = rowYs[r];
    let y2 = rowYs[r + 1];
    let t1 = (y1 - vp[1]) / (1200 - vp[1]);
    let t2 = (y2 - vp[1]) / (1200 - vp[1]);

    for (let c = -4; c < 11; c++) {
      let stagger = (r % 2) * 0.5;
      let bx1 = -350 + (c + stagger) * 195;
      let bx2 = bx1 + 188;

      let x1L = vp[0] + (bx1 - vp[0]) * t1;
      let x1R = vp[0] + (bx2 - vp[0]) * t1;
      let x2R = vp[0] + (bx2 - vp[0]) * t2;
      let x2L = vp[0] + (bx1 - vp[0]) * t2;

      if (x2R < -20 || x1L > 1220) continue;

      let tilePts = [
        [x1L + 2, y1 + 1.5],
        [x1R - 2, y1 + 1.5],
        [x2R - 2, y2 - 1.5],
        [x2L + 2, y2 - 1.5]
      ];

      let cx = (x1L + x1R + x2R + x2L) * 0.25;
      let cy = (y1 + y2) * 0.5;

      // Determine if tile falls in honeyed sun patch or dusky bike shadow
      let inBikeShadow =
        Math.hypot((cx - 560) * 0.7, cy - 975) < 250 ||
        Math.hypot((cx - 840) * 0.8, cy - 1090) < 155;
      let inSunPatch =
        !inBikeShadow &&
        ((cx > 310 && cx < 760 && cy > 960) || (cx > 920 && cy > 880));

      let col = PAL.terraMid;
      let alpha = 75;
      if (inBikeShadow) {
        col = (c + r) % 2 === 0 ? PAL.twilightSlate : PAL.terraDeep;
        alpha = 88;
      } else if (inSunPatch) {
        col = (c + r) % 2 === 0 ? PAL.sunflowerWarm : PAL.terraBright;
        alpha = 82;
      } else {
        col = (c + r) % 3 === 0 ? PAL.terraDark : PAL.terraMid;
        alpha = 72;
      }

      washPoly(tilePts, col, alpha);

      // Subtle diagonal tile texture hatching
      if (r >= 2 && (c + r) % 2 === 0) {
        hatchPoly(tilePts, 9, 25, "2B", inBikeShadow ? PAL.twilightDeep : PAL.terraDeep, 0.25, 0.05);
      }

      // Crisp sepia mortar contour
      inkPoly(tilePts, 0.24, PAL.sepiaWarm, true, 0.04);

      // Small sap-green moss tufts in select mortar corners
      if ((c * 7 + r * 3) % 5 === 0 && cy > 900) {
        wcPoly(
          [
            [x2L - 4, y2],
            [x2L + 18, y2 - 3],
            [x2L + 8, y2 + 5]
          ],
          PAL.sapMid, 95, 0.05, 0.3, 0.2
        );
      }
    }
  }

  // Honeyed dappled sunlight polygons directly on the terracotta tiles
  let sunPatches = [
    [[340, 1020], [540, 995], [610, 1095], [390, 1135]],
    [[580, 1055], [755, 1030], [790, 1150], [615, 1175]],
    [[965, 920], [1165, 895], [1190, 1035], [995, 1060]],
    [[65, 990], [215, 975], [240, 1085], [75, 1110]]
  ];
  for (let sp of sunPatches) {
    wcPoly(sp, PAL.sunflowerBright, 60, 0.14, 0.35, 0.18);
    inkPoly(sp, 0.18, PAL.copperGold, true, 0.15, "cpencil");
  }

  // Deep cast shadow under the cargo bike and front wheel
  wcPoly(
    [[140, 965], [480, 925], [925, 1065], [880, 1155], [380, 1065], [120, 1020]],
    PAL.twilightDeep, 82, 0.12, 0.45, 0.15
  );
}

// ============================================================================
// 3. OVERHEAD PERGOLA & PHOTOVOLTAIC TILES (LOW-ANGLE PERSPECTIVE)
// ============================================================================
function drawPhotovoltaicPergola() {
  // Define the overhead pergola plane as a perspective bilinear grid
  // Looking sharply up: rafters fan out from upper-left toward right/lower-right
  let pTL = [-80, -40];
  let pTR = [1260, -60];
  let pBR = [1280, 565];
  let pBL = [-60, 690];

  let numCols = 6; // Cross-battens
  let numRows = 5; // Main timber rafters

  // First: Render the translucent Photovoltaic (PV) Solar Tiles inside each grid bay
  for (let r = 0; r < numRows; r++) {
    let v0 = r / numRows;
    let v1 = (r + 1) / numRows;
    // Perspective foreshortening along v
    let pv0 = Math.pow(v0, 1.12);
    let pv1 = Math.pow(v1, 1.12);

    for (let c = 0; c < numCols; c++) {
      let u0 = c / numCols;
      let u1 = (c + 1) / numCols;

      // Inset slightly for timber frame clearance
      let padU = 0.012;
      let padV = 0.014;
      let q00 = quadPt(pTL, pTR, pBR, pBL, u0 + padU, pv0 + padV);
      let q10 = quadPt(pTL, pTR, pBR, pBL, u1 - padU, pv0 + padV);
      let q11 = quadPt(pTL, pTR, pBR, pBL, u1 - padU, pv1 - padV);
      let q01 = quadPt(pTL, pTR, pBR, pBL, u0 + padU, pv1 - padV);

      let bayPts = [q00, q10, q11, q01];

      // Determine how much midday sun hits this PV panel
      let center = quadPt(pTL, pTR, pBR, pBL, (u0 + u1) * 0.5, (pv0 + pv1) * 0.5);
      let sunFactor = constrain(1 - Math.hypot(center[0] - 820, center[1] - 190) / 680, 0, 1);

      // Base PV glass wash in copper-verdigris & twilight Prussian blue
      let baseCol = sunFactor > 0.45 ? PAL.verdMid : (r + c) % 2 === 0 ? PAL.verdDark : PAL.twilightBlue;
      wcPoly(bayPts, baseCol, 88, 0.06, 0.4, 0.03);

      // Translucent honey-gold backlight glow on sunlit panels
      if (sunFactor > 0.25) {
        let glowPts = [
          quadPt(q00, q10, q11, q01, 0.12, 0.12),
          quadPt(q00, q10, q11, q01, 0.88, 0.12),
          quadPt(q00, q10, q11, q01, 0.88, 0.88),
          quadPt(q00, q10, q11, q01, 0.12, 0.88)
        ];
        washPoly(glowPts, sunFactor > 0.6 ? PAL.sunflowerBright : PAL.verdBright, 55);
      }

      // Draw individual monocrystalline silicon sub-cells (3x4 grid per PV tile)
      let subU = 3;
      let subV = 4;
      for (let su = 0; su < subU; su++) {
        for (let sv = 0; sv < subV; sv++) {
          let su0 = (su + 0.08) / subU;
          let su1 = (su + 0.92) / subU;
          let sv0 = (sv + 0.08) / subV;
          let sv1 = (sv + 0.92) / subV;

          let c00 = quadPt(q00, q10, q11, q01, su0, sv0);
          let c10 = quadPt(q00, q10, q11, q01, su1, sv0);
          let c11 = quadPt(q00, q10, q11, q01, su1, sv1);
          let c01 = quadPt(q00, q10, q11, q01, su0, sv1);

          let cellCol = (su + sv + c) % 3 === 0 ? PAL.verdDeep : PAL.twilightIndigo;
          if (sunFactor > 0.55 && (su + sv) % 2 === 0) cellCol = PAL.verdMid;
          washPoly([c00, c10, c11, c01], cellCol, 72);

          // Copper busbar line down center of each solar cell column
          let busTop = lerp2D(c00, c10, 0.5);
          let busBot = lerp2D(c01, c11, 0.5);
          inkLine(busTop[0], busTop[1], busBot[0], busBot[1], 0.18, PAL.copperGold, "pen");
        }
      }

      // Crisp cell-matrix grid lines & silver-verdigris specular diagonal
      for (let su = 1; su < subU; su++) {
        let pA = quadPt(q00, q10, q11, q01, su / subU, 0);
        let pB = quadPt(q00, q10, q11, q01, su / subU, 1);
        inkLine(pA[0], pA[1], pB[0], pB[1], 0.22, PAL.verdPale, "rotring");
      }
      for (let sv = 1; sv < subV; sv++) {
        let pA = quadPt(q00, q10, q11, q01, 0, sv / subV);
        let pB = quadPt(q00, q10, q11, q01, 1, sv / subV);
        inkLine(pA[0], pA[1], pB[0], pB[1], 0.22, PAL.verdPale, "rotring");
      }

      // Diagonal glass sky reflection streak
      let refA = quadPt(q00, q10, q11, q01, 0.15, 0.05);
      let refB = quadPt(q00, q10, q11, q01, 0.32, 0.05);
      let refC = quadPt(q00, q10, q11, q01, 0.85, 0.95);
      let refD = quadPt(q00, q10, q11, q01, 0.68, 0.95);
      washPoly([refA, refB, refC, refD], sunFactor > 0.4 ? PAL.honeyPale : PAL.verdPale, 45);

      // PV tile frame contour in warm sepia + copper clips
      inkPoly(bayPts, 0.35, PAL.sepiaDark, true, 0.02);
    }
  }

  // Second: Cross-battens (running top-left to bottom-right)
  for (let c = 0; c <= numCols; c++) {
    let u = c / numCols;
    let wU = 0.011;
    let b00 = quadPt(pTL, pTR, pBR, pBL, u - wU, 0);
    let b10 = quadPt(pTL, pTR, pBR, pBL, u + wU, 0);
    let b11 = quadPt(pTL, pTR, pBR, pBL, u + wU, 1);
    let b01 = quadPt(pTL, pTR, pBR, pBL, u - wU, 1);

    // Side thickness of batten
    let s10 = [b10[0] + 9, b10[1] + 5];
    let s11 = [b11[0] + 9, b11[1] + 5];

    washPoly([b10, s10, s11, b11], PAL.woodLight, 95);
    washPoly([b00, b10, b11, b01], PAL.woodDark, 98);
    inkPoly([b00, b10, b11, b01], 0.32, PAL.sepiaDark, true, 0.02);
    inkPoly([b10, s10, s11, b11], 0.25, PAL.sepiaDark, true, 0.02);
  }

  // Third: Heavy 3D Timber Rafters (running left to right, seen from below with sunlit side face)
  for (let r = 0; r <= numRows; r++) {
    let v = Math.pow(r / numRows, 1.12);
    let wV = 0.016 * (0.8 + 0.4 * (r / numRows));

    let r00 = quadPt(pTL, pTR, pBR, pBL, 0, v - wV);
    let r10 = quadPt(pTL, pTR, pBR, pBL, 1, v - wV);
    let r11 = quadPt(pTL, pTR, pBR, pBL, 1, v + wV);
    let r01 = quadPt(pTL, pTR, pBR, pBL, 0, v + wV);

    // 3D depth face of the timber rafter (hanging down 18..28px)
    let depth = 16 + r * 4;
    let d00 = [r00[0], r00[1] - depth];
    let d10 = [r10[0], r10[1] - depth];

    // Sunlit side face of beam
    wcPoly([d00, d10, r10, r00], PAL.woodLight, 92, 0.05, 0.4, 0.02);
    hatchPoly([d00, d10, r10, r00], 6, -6, "2B", PAL.terraDark, 0.24, 0.03);

    // Shadowed underside face of beam
    wcPoly([r00, r10, r11, r01], PAL.woodDark, 95, 0.05, 0.45, 0.02);

    // Wood grain lines along the beam
    for (let g = 1; g <= 3; g++) {
      let gt = g / 4;
      let gL = lerp2D(d00, r00, gt);
      let gR = lerp2D(d10, r10, gt);
      let gMid = lerp2D(gL, gR, 0.5);
      inkSpline([gL, [gMid[0], gMid[1] + random(-3, 3)], gR], 0.4, 0.2, PAL.sepiaWarm, "pen");
    }

    // Crisp sepia architectural outlines
    inkPoly([d00, d10, r10, r00], 0.38, PAL.sepiaDark, true, 0.02);
    inkPoly([r00, r10, r11, r01], 0.42, PAL.sepiaDark, true, 0.02);

    // Oxidized copper joinery brackets & bolts at rafter intersections
    for (let c = 1; c < numCols; c++) {
      let u = c / numCols;
      let jPt = lerp2D(r00, r10, u);
      let brk = [
        [jPt[0] - 8, jPt[1] - depth * 0.7],
        [jPt[0] + 8, jPt[1] - depth * 0.7],
        [jPt[0] + 8, jPt[1] + 8],
        [jPt[0] - 8, jPt[1] + 8]
      ];
      washPoly(brk, PAL.verdMid, 95);
      inkPoly(brk, 0.3, PAL.sepiaDark, true, 0.02);
      // Two tiny bolt heads
      inkLine(jPt[0] - 3, jPt[1] - 4, jPt[0] + 3, jPt[1] - 4, 0.45, PAL.sepiaDark);
      inkLine(jPt[0] - 3, jPt[1] + 3, jPt[0] + 3, jPt[1] + 3, 0.45, PAL.sepiaDark);
    }
  }
}

// ============================================================================
// 4. CLIMBING RUNNER BEANS (BOTANICAL LEAVES, VINES, PODS, BLOSSOMS)
// ============================================================================

// Hyperreal single runner bean leaflet with complete hierarchical venation
function drawBeanLeaflet(bx, by, len, wid, angleDeg, colBase, isSunlit = false) {
  let rad = (angleDeg * Math.PI) / 180;
  let ca = Math.cos(rad);
  let sa = Math.sin(rad);

  function toWorld(lx, ly) {
    return [bx + lx * ca - ly * sa, by + lx * sa + ly * ca];
  }

  // Ovate-cordate (heart-shaped base, acuminate tip) runner bean leaflet contour
  let steps = 14;
  let leftSide = [];
  let rightSide = [];
  for (let i = 0; i <= steps; i++) {
    let t = i / steps;
    // Cordate base dip near t=0, widest at t=0.3, tapering to sharp tip at t=1
    let profile = Math.sin(Math.pow(t, 0.65) * Math.PI) * Math.pow(1 - t * 0.25, 0.6);
    if (t < 0.12) profile += Math.sin((t / 0.12) * Math.PI) * 0.18;
    let lx = t * len;
    let wy = profile * wid * 0.5;
    let wave = Math.sin(t * Math.PI * 5) * wid * 0.025;
    leftSide.push(toWorld(lx, -wy + wave));
    rightSide.push(toWorld(lx, wy + wave));
  }

  let poly = leftSide.concat(rightSide.reverse());

  // Watercolor fill
  wcPoly(poly, colBase, 88, 0.06, 0.4, 0.12);
  if (isSunlit) {
    let inner = [toWorld(len * 0.15, 0), toWorld(len * 0.5, -wid * 0.22), toWorld(len * 0.85, 0), toWorld(len * 0.5, wid * 0.22)];
    wcPoly(inner, PAL.sapChartreuse, 65, 0.08, 0.3, 0.18);
  } else {
    hatchPoly(poly, 5.5, angleDeg + 35, "2B", PAL.sapDeep, 0.22, 0.04);
  }

  // Primary midrib vein (base to apex)
  let midCurve = wid * 0.03;
  let midPts = [
    toWorld(0, 0),
    toWorld(len * 0.35, midCurve * 0.6),
    toWorld(len * 0.7, midCurve),
    toWorld(len, 0)
  ];
  inkSpline(midPts, 0.4, 0.36, PAL.sepiaDark, "rotring");
  if (isSunlit) {
    inkSpline(midPts, 0.4, 0.22, PAL.lettuceHeart, "cpencil");
  }

  // Secondary arcuate lateral veins + tertiary bifurcations
  let veinFracs = [0.14, 0.28, 0.44, 0.6, 0.75, 0.87];
  for (let vf of veinFracs) {
    let profile = Math.sin(Math.pow(vf, 0.65) * Math.PI) * Math.pow(1 - vf * 0.25, 0.6);
    let span = profile * wid * 0.46;
    let startX = vf * len;
    let startY = midCurve * Math.sin(vf * Math.PI);

    for (let side of [-1, 1]) {
      let p0 = toWorld(startX, startY);
      let p1 = toWorld(startX + len * 0.08, startY + side * span * 0.55);
      let p2 = toWorld(startX + len * 0.17, startY + side * span * 0.92);
      inkSpline([p0, p1, p2], 0.45, 0.22, PAL.sepiaWarm, "rotring");

      // Tertiary sub-vein fork
      let pFork = toWorld(startX + len * 0.13, startY + side * span * 0.78);
      inkLine(p1[0], p1[1], pFork[0], pFork[1], 0.15, PAL.sepiaLight, "rotring");
    }
  }

  // Crisp sepia margin contour
  inkPoly(poly, 0.32, PAL.sepiaDark, true, 0.1);
}

//Hanging textured runner bean pod
function drawRunnerBeanPod(x, y, length, curveAmt, col = PAL.sapBright) {
  let steps = 10;
  let leftEdge = [];
  let rightEdge = [];
  let halfW = 7.5;

  for (let i = 0; i <= steps; i++) {
    let t = i / steps;
    let cy = y + t * length;
    let cx = x + Math.sin(t * Math.PI) * curveAmt + Math.sin(t * Math.PI * 2) * 3;
    // Slight seed-bulge undulations along pod width
    let seedBulge = 1 + 0.16 * Math.sin(t * Math.PI * 6);
    let taper = Math.sin(Math.pow(t, 0.45) * Math.PI);
    let w = halfW * taper * seedBulge;
    leftEdge.push([cx - w, cy]);
    rightEdge.push([cx + w, cy]);
  }
  // Curved stylar beak tip at bottom
  let tip = [x + curveAmt * 0.2 + 5, y + length + 9];
  let poly = leftEdge.concat([tip], rightEdge.reverse());

  wcPoly(poly, col, 92, 0.05, 0.38, 0.12);
  // Honeyed highlight down left suture
  inkSpline(leftEdge, 0.4, 0.35, PAL.lettuceHeart, "cpencil");
  // Shaded right edge hatching
  hatchPoly(poly, 5, 20, "2B", PAL.sapDeep, 0.22, 0.04);

  // Subtle seed bulge contour arcs inside pod
  for (let s = 1; s <= 5; s++) {
    let st = s / 6;
    let sy = y + st * length;
    let sx = x + Math.sin(st * Math.PI) * curveAmt;
    inkSpline([[sx - 3, sy - 4], [sx + 3, sy], [sx - 2, sy + 5]], 0.5, 0.18, PAL.sapDeep, "rotring");
  }

  // Small calyx cap at top of pod
  let calPts = [[x - 6, y - 2], [x + 6, y - 2], [x + 3, y + 5], [x - 3, y + 5]];
  washPoly(calPts, PAL.sapDark, 95);
  inkPoly(calPts, 0.28, PAL.sepiaDark, true, 0.05);
  inkPoly(poly, 0.34, PAL.sepiaDark, true, 0.1);
}

// Scarlet-terracotta runner bean flower raceme
function drawBeanBlossomCluster(x, y, dir = 1) {
  // Peduncle stalk
  let stalkPts = [
    [x, y],
    [x + dir * 22, y + 18],
    [x + dir * 38, y + 48],
    [x + dir * 45, y + 78]
  ];
  inkSpline(stalkPts, 0.4, 0.35, PAL.terraDark, "rotring");

  // 5 papilionaceous blossoms along the raceme
  for (let i = 0; i < 5; i++) {
    let t = (i + 1) / 5.5;
    let bx = x + dir * (16 + i * 7) + (i % 2 === 0 ? -8 : 8);
    let by = y + 14 + i * 14;
    let sz = 11 - i * 1.1;

    // Banner petal (broad upper hood in scarlet-terracotta)
    let banner = ellipsePoly(bx, by - sz * 0.4, sz * 0.95, sz * 0.75, dir * 15, 12);
    wcPoly(banner, PAL.terraBlossom, 94, 0.05, 0.35, 0.15);
    inkPoly(banner, 0.26, PAL.sepiaDark, true, 0.12);

    // Wing petals (warm coral-terracotta lower lobes)
    let wing = ellipsePoly(bx + dir * 3, by + sz * 0.35, sz * 0.7, sz * 0.55, -dir * 10, 10);
    wcPoly(wing, PAL.terraBright, 92, 0.04, 0.3, 0.15);
    inkPoly(wing, 0.24, PAL.sepiaDark, true, 0.12);

    // Golden-yellow keel center dot
    let keel = ellipsePoly(bx, by, sz * 0.28, sz * 0.25, 0, 8);
    washPoly(keel, PAL.sunflowerBright, 95);
  }
}

