// Hyperreal single cupped lettuce leaf with ruffled margin and hierarchical veins
function drawLettuceLeaf(cx, cy, radius, angDeg, spanDeg, colBase, colVein, ruffleAmp = 0.09, isHeart = false) {
  let steps = 20;
  let outerPts = [];
  let startA = angDeg - spanDeg * 0.5;
  let endA = angDeg + spanDeg * 0.5;

  let basePt = ellipsePt(cx, cy, radius * 0.14, radius * 0.14, 0, angDeg + 180);

  for (let i = 0; i <= steps; i++) {
    let t = i / steps;
    let a = startA + (endA - startA) * t;
    let env = Math.sin(t * Math.PI);
    // Multi-frequency undulating butterhead leaf margin
    let ruffle =
      1 +
      ruffleAmp * Math.sin(t * Math.PI * 7) * env +
      ruffleAmp * 0.5 * Math.cos(t * Math.PI * 13) * env;
    let r = radius * (0.35 + 0.65 * Math.pow(env, 0.42)) * ruffle;
    outerPts.push(ellipsePt(cx, cy, r, r * 0.88, -8, a));
  }

  let leafPoly = [basePt].concat(outerPts);

  // Layered transparent watercolour fill
  wcPoly(leafPoly, colBase, 88, 0.07, 0.42, 0.14);

  // Sunlit chartreuse-yellow glow near leaf center/heart
  if (isHeart) {
    let innerGlow = [
      basePt,
      ellipsePt(cx, cy, radius * 0.62, radius * 0.55, -8, angDeg - spanDeg * 0.25),
      ellipsePt(cx, cy, radius * 0.72, radius * 0.64, -8, angDeg),
      ellipsePt(cx, cy, radius * 0.62, radius * 0.55, -8, angDeg + spanDeg * 0.25)
    ];
    wcPoly(innerGlow, PAL.sunflowerBright, 42, 0.1, 0.3, 0.18);
  } else {
    // Concave shadow hatching at base of leaf cup
    let cupShadow = [
      basePt,
      ellipsePt(cx, cy, radius * 0.5, radius * 0.44, -8, angDeg - spanDeg * 0.22),
      ellipsePt(cx, cy, radius * 0.55, radius * 0.48, -8, angDeg),
      ellipsePt(cx, cy, radius * 0.5, radius * 0.44, -8, angDeg + spanDeg * 0.22)
    ];
    hatchPoly(cupShadow, 5, angDeg + 45, "2B", PAL.sapDeep, 0.22, 0.04);
  }

  // --- HYPERREAL LEAF VENATION ---
  // 1. Succulent tapering primary midrib
  let midTip = ellipsePt(cx, cy, radius * 0.92, radius * 0.81, -8, angDeg);
  let mid1 = lerp2D(basePt, midTip, 0.33);
  let mid2 = lerp2D(basePt, midTip, 0.68);
  let perpRad = ((angDeg + 90) * Math.PI) / 180;
  let px = Math.cos(perpRad), py = Math.sin(perpRad);

  // Cream-chartreuse fleshy midrib fill
  let ribPoly = [
    [basePt[0] - px * 3.2, basePt[1] - py * 3.2],
    [mid1[0] - px * 2.1, mid1[1] - py * 2.1],
    [mid2[0] - px * 1.1, mid2[1] - py * 1.1],
    midTip,
    [mid2[0] + px * 1.1, mid2[1] + py * 1.1],
    [mid1[0] + px * 2.1, mid1[1] + py * 2.1],
    [basePt[0] + px * 3.2, basePt[1] + py * 3.2]
  ];
  washPoly(ribPoly, colVein, 90);
  inkSpline([[basePt[0] - px * 2.4, basePt[1] - py * 2.4], [mid1[0] - px * 1.4, mid1[1] - py * 1.4], midTip], 0.4, 0.24, PAL.sepiaWarm, "rotring");
  inkSpline([[basePt[0] + px * 2.4, basePt[1] + py * 2.4], [mid1[0] + px * 1.4, mid1[1] + py * 1.4], midTip], 0.4, 0.24, PAL.sepiaWarm, "rotring");

  // 2. Branching secondary & tertiary capillary veins
  let branchSteps = [0.22, 0.38, 0.54, 0.7, 0.83];
  for (let i = 0; i < branchSteps.length; i++) {
    let bt = branchSteps[i];
    let origin = lerp2D(basePt, midTip, bt);
    for (let side of [-1, 1]) {
      let targetIdx = Math.floor((0.5 + side * (0.15 + bt * 0.32)) * steps);
      targetIdx = constrain(targetIdx, 1, steps - 1);
      let edgePt = outerPts[targetIdx];
      let subTarget = lerp2D(origin, edgePt, 0.92);
      let ctrl = lerp2D(origin, subTarget, 0.52);
      ctrl[0] += px * side * radius * 0.06;
      ctrl[1] += py * side * radius * 0.06;

      // Secondary vein
      inkSpline([origin, ctrl, subTarget], 0.45, 0.2, PAL.sepiaWarm, "rotring");
      inkSpline([origin, ctrl, subTarget], 0.45, 0.16, colVein, "cpencil");

      // Tertiary bifurcating veinlets near margin
      let forkIdx = constrain(targetIdx + side * 2, 1, steps - 1);
      let forkPt = lerp2D(ctrl, outerPts[forkIdx], 0.85);
      inkLine(ctrl[0], ctrl[1], forkPt[0], forkPt[1], 0.15, PAL.sepiaLight, "rotring");

      // Capillary cross-bridge to adjacent secondary vein
      if (i > 0) {
        let prevOrigin = lerp2D(basePt, midTip, branchSteps[i - 1]);
        let bridgePt = lerp2D(prevOrigin, edgePt, 0.58);
        inkLine(ctrl[0], ctrl[1], bridgePt[0], bridgePt[1], 0.12, PAL.sepiaLight, "rotring");
      }
    }
  }

  // 3. Crisp warm-sepia ruffled margin contour
  inkSpline(outerPts, 0.45, 0.34, PAL.sepiaDark, "rotring");
}

// Complete rosette of a Butterhead Lettuce head
function drawButterheadRosette(cx, cy, maxR, rotOffset = 0) {
  // Outer ring: 7 broadsap-green & copper-verdigris wrapper leaves
  for (let i = 0; i < 7; i++) {
    let ang = rotOffset + (i * 360) / 7 + (i % 2) * 12;
    let col = i % 3 === 0 ? PAL.verdDark : i % 2 === 0 ? PAL.sapDark : PAL.sapMid;
    drawLettuceLeaf(cx, cy, maxR * (0.94 + (i % 2) * 0.08), ang, 78, col, PAL.sapChartreuse, 0.1, false);
  }
  // Mid ring: 6 cupped bright sap-green leaves
  for (let i = 0; i < 6; i++) {
    let ang = rotOffset + 25 + (i * 360) / 6;
    let col = i % 2 === 0 ? PAL.sapBright : PAL.sapMid;
    drawLettuceLeaf(cx, cy, maxR * 0.72, ang, 82, col, PAL.lettuceHeart, 0.09, false);
  }
  // Inner heart: 5 tender chartreuse & sunflower-yellow folded leaves
  for (let i = 0; i < 5; i++) {
    let ang = rotOffset + 48 + (i * 360) / 5;
    let col = i % 2 === 0 ? PAL.lettuceHeart : PAL.sapChartreuse;
    drawLettuceLeaf(cx, cy, maxR * 0.46, ang, 88, col, PAL.creamLight, 0.07, true);
  }
  // Central tight bud fold
  let heartFold = ellipsePoly(cx, cy - 3, maxR * 0.22, maxR * 0.18, -10, 14);
  wcPoly(heartFold, PAL.honeyPale, 92, 0.06, 0.3, 0.2);
  inkPoly(heartFold, 0.3, PAL.sepiaWarm, true, 0.15);
}

// Glass Bottle of Kombucha (tilted apothecary swing-top bottle nestled in crate)
function drawKombuchaBottle(cx, cy, tiltDeg = 14) {
  let rad = (tiltDeg * Math.PI) / 180;
  let ca = Math.cos(rad), sa = Math.sin(rad);

  // Local bottle coordinates: y=0 at shoulder center, y>0 downward into crate, y<0 upward to neck/stopper
  function bPt(lx, ly) {
    return [cx + lx * ca - ly * sa, cy + lx * sa + ly * ca];
  }

  // Bottle profile pairs (y, halfWidth) from base (+95) up to lip (-92)
  let prof = [
    [95, 42],
    [35, 43],
    [5, 42],
    [-12, 36],
    [-28, 22],
    [-48, 13],
    [-78, 11],
    [-86, 14],
    [-92, 12]
  ];

  let leftSide = prof.map(p => bPt(-p[1], p[0]));
  let rightSide = prof.map(p => bPt(p[1], p[0])).reverse();
  let bottlePoly = leftSide.concat(rightSide);

  // 1. Base Amber Glass Wash
  wcPoly(bottlePoly, PAL.amberGlass, 90, 0.05, 0.38, 0.1);

  // 2. Internal Kombucha Liquid & Golden Backlit Glow (from y=95 up to meniscus at y=-16)
  let liqPoly = [
    bPt(-39, 90), bPt(-39, 10), bPt(-32, -16),
    bPt(32, -16), bPt(39, 10), bPt(39, 90)
  ];
  wcPoly(liqPoly, PAL.amberGlow, 85, 0.06, 0.35, 0.1);

  // Sunlit honey-gold refraction column on right side of bottle
  let sunBand = [
    bPt(8, 88), bPt(10, -14), bPt(30, -14), bPt(34, 88)
  ];
  wcPoly(sunBand, PAL.sunflowerBright, 78, 0.06, 0.3, 0.1);

  // Shaded side & dusky twilight sky reflection on left side
  let shadeBand = [
    bPt(-41, 88), bPt(-41, 5), bPt(-33, -15), bPt(-18, -15), bPt(-22, 88)
  ];
  washPoly(shadeBand, PAL.amberDark, 75);
  let skyReflect = [
    bPt(-34, 80), bPt(-34, 6), bPt(-25, -18), bPt(-8, -72),
    bPt(-4, -72), bPt(-19, -16), bPt(-27, 8), bPt(-27, 80)
  ];
  washPoly(skyReflect, PAL.verdPale, 68);

  // 3. Liquid Meniscus Elliptical Ring & Effervescent Bubbles at Shoulder
  let meniscus = ellipsePoly(bPt(0, -16)[0], bPt(0, -16)[1], 33, 9, tiltDeg, 20);
  washPoly(meniscus, PAL.honeyPale, 82);
  inkPoly(meniscus, 0.28, PAL.sepiaDark, true, 0.08);
  // Tiny rising fermentation bubbles along meniscus
  for (let b = -24; b <= 24; b += 6) {
    let bp = bPt(b, -15 + (Math.abs(b) % 5));
    inkLine(bp[0] - 1, bp[1], bp[0] + 1, bp[1], 0.35, PAL.creamLight, "cpencil");
  }

  // 4. Curved Vintage Botanical Paper Label ("KOMBUCHA")
  let lblTopY = 12, lblBotY = 74;
  let lblPoly = [];
  for (let i = 0; i <= 10; i++) {
    let ang = 180 + (180 * i) / 10;
    let th = (ang * Math.PI) / 180;
    lblPoly.push(bPt(42.5 * Math.cos(th), lblTopY + 11 * Math.sin(th)));
  }
  for (let i = 10; i >= 0; i--) {
    let ang = 180 + (180 * i) / 10;
    let th = (ang * Math.PI) / 180;
    lblPoly.push(bPt(42.5 * Math.cos(th), lblBotY + 11 * Math.sin(th)));
  }
  washPoly(lblPoly, PAL.paper, 96);
  inkPoly(lblPoly, 0.35, PAL.sepiaDark, true, 0.06);

  // Terracotta inner decorative border on label
  let lblInner = [
    bPt(-36, lblTopY + 6), bPt(0, lblTopY + 13), bPt(36, lblTopY + 6),
    bPt(36, lblBotY - 6), bPt(0, lblBotY + 3), bPt(-36, lblBotY - 6)
  ];
  inkPoly(lblInner, 0.28, PAL.terraMid, true, 0.08);

  // Copper-verdigris botanical banner strip across label center
  let bannerStrip = [
    bPt(-34, 30), bPt(0, 37), bPt(34, 30),
    bPt(34, 44), bPt(0, 51), bPt(-34, 44)
  ];
  washPoly(bannerStrip, PAL.verdMid, 90);
  inkPoly(bannerStrip, 0.24, PAL.sepiaDark, true, 0.06);

  // Tiny botanical leaf emblem above banner on label
  let embL = [bPt(-2, 26), bPt(-12, 20), bPt(-4, 18)];
  let embR = [bPt(2, 26), bPt(12, 20), bPt(4, 18)];
  washPoly(embL, PAL.sapMid, 95);
  washPoly(embR, PAL.terraBright, 95);

  // Crisp hand-drawn micro-lettering strokes across the banner ("KOMBUCHA")
  for (let lx = -26; lx <= 26; lx += 6.5) {
    let ly = 34 + (1 - (lx * lx) / 900) * 5;
    let pTop = bPt(lx, ly - 3.5);
    let pBot = bPt(lx, ly + 3.5);
    let pMid = bPt(lx + 2.5, ly);
    inkLine(pTop[0], pTop[1], pBot[0], pBot[1], 0.32, PAL.creamLight, "rotring");
    inkLine(pTop[0], pTop[1], pMid[0], pMid[1], 0.24, PAL.creamLight, "rotring");
  }

  // Fine horizontal typography lines on lower label
  inkSpline([bPt(-22, 54), bPt(0, 59), bPt(22, 54)], 0.4, 0.22, PAL.sepiaWarm);
  inkSpline([bPt(-16, 61), bPt(0, 65), bPt(16, 61)], 0.4, 0.2, PAL.terraDark);

  // 5. Swing-Top Porcelain Stopper, Red Rubber Gasket & Wire Bail Mechanism
  // Terracotta-red rubber gasket ring at lip (-92)
  let gasket = ellipsePoly(bPt(0, -93)[0], bPt(0, -93)[1], 13, 4.5, tiltDeg, 16);
  washPoly(gasket, PAL.radishRed, 98);
  inkPoly(gasket, 0.28, PAL.sepiaDark, true, 0.08);

  // White conical porcelain stopper above gasket (-95 to -110)
  let stopper = [
    bPt(-11, -94), bPt(-14, -106), bPt(0, -111), bPt(14, -106), bPt(11, -94)
  ];
  washPoly(stopper, PAL.creamLight, 98);
  inkPoly(stopper, 0.34, PAL.sepiaDark, true, 0.08);

  // Galvanized steel wire bail clasp clamping from porcelain stopper to neck collar (-76)
  let neckCollar = ellipsePoly(bPt(0, -76)[0], bPt(0, -76)[1], 13, 4, tiltDeg, 14);
  inkPoly(neckCollar, 0.34, PAL.sepiaDark, true, 0.08);
  inkSpline([bPt(-12, -102), bPt(-18, -88), bPt(-13, -76)], 0.4, 0.38, PAL.twilightSlate, "rotring");
  inkSpline([bPt(12, -102), bPt(18, -88), bPt(13, -76)], 0.4, 0.38, PAL.twilightSlate, "rotring");
  // Wire lever loop on side of neck
  inkSpline([bPt(-13, -76), bPt(-21, -64), bPt(-15, -58), bPt(-12, -74)], 0.4, 0.34, PAL.sepiaDark, "rotring");

  // 6. Crisp Specular Glass Highlights & Outer Bottle Contour
  inkSpline([bPt(22, 5), bPt(26, -10), bPt(12, -26), bPt(7, -70)], 0.4, 0.55, PAL.creamLight, "cpencil");
  inkSpline([bPt(-30, 5), bPt(-27, -12), bPt(-10, -28)], 0.4, 0.4, PAL.honeyPale, "cpencil");
  inkPoly(bottlePoly, 0.42, PAL.sepiaDark, true, 0.08);
}

// Crisp Scarlet-Terracotta Radish with White Tip, Taproot & Leafy Crown
function drawRadish(x, y, rx, ry, angDeg, rootLen = 42) {
  let rad = (angDeg * Math.PI) / 180;
  let ca = Math.cos(rad), sa = Math.sin(rad);
  function rPt(lx, ly) {
    return [x + lx * ca - ly * sa, y + lx * sa + ly * ca];
  }

  let bulbPts = ellipsePoly(x, y, rx, ry, angDeg, 20);
  // Crimson-terracotta upper body
  wcPoly(bulbPts, PAL.radishRed, 92, 0.05, 0.38, 0.12);

  // Creamy-white lower root tip (bottom third of bulb)
  let tipPts = ellipsePoly(x, y, rx * 0.96, ry * 0.96, angDeg, 12, 35, 145);
  wcPoly(tipPts, PAL.creamLight, 92, 0.07, 0.3, 0.15);

  // Sunlit carmine-rose highlight & tonal hatching
  let hiPts = ellipsePoly(rPt(-rx * 0.28, -ry * 0.25)[0], rPt(-rx * 0.28, -ry * 0.25)[1], rx * 0.35, ry * 0.32, angDeg, 10);
  washPoly(hiPts, PAL.radishRose, 80);
  washPoly(ellipsePoly(rPt(-rx * 0.3, -ry * 0.3)[0], rPt(-rx * 0.3, -ry * 0.3)[1], rx * 0.16, ry * 0.14, angDeg, 8), PAL.creamLight, 85);

  // Fine horizontal root lenticel striations
  for (let s = -1; s <= 1; s++) {
    let pA = rPt(-rx * 0.45, s * ry * 0.28);
    let pB = rPt(rx * 0.25, s * ry * 0.28 + 2);
    inkLine(pA[0], pA[1], pB[0], pB[1], 0.18, PAL.terraDeep, "rotring");
  }

  // Crisp sepia contour around radish bulb
  inkPoly(bulbPts, 0.35, PAL.sepiaDark, true, 0.1);

  // Long delicate curling taproot hanging down over the wooden crate
  let tapStart = rPt(0, ry);
  let tapMid1 = rPt(4, ry + rootLen * 0.38);
  let tapMid2 = rPt(-5, ry + rootLen * 0.72);
  let tapEnd = rPt(3, ry + rootLen);
  // Cast shadow of taproot on the wooden crate plank
  inkSpline(
    [[tapStart[0] + 5, tapStart[1] + 4], [tapMid1[0] + 6, tapMid1[1] + 4], [tapEnd[0] + 6, tapEnd[1] + 4]],
    0.45, 0.28, PAL.sepiaWarm, "2B"
  );
  // Cream & sepia taproot
  inkSpline([tapStart, tapMid1, tapMid2, tapEnd], 0.45, 0.38, PAL.creamLight, "cpencil");
  inkSpline([tapStart, tapMid1, tapMid2, tapEnd], 0.45, 0.26, PAL.sepiaDark, "rotring");
}

function drawCargoCrateAndHarvest() {
  // Crate 3D Key Vertices (Low-angle looking up at left side wall & slanted front nose)
  let L_TL = [342, 535];
  let L_TR = [715, 482];
  let L_BR = [702, 795];
  let L_BL = [368, 768];

  let F_TR = [842, 520];
  let F_BR = [812, 772];

  // --- STEP 1: Dark Interior Cavity & Back Rim of Crate (behind produce) ---
  let backCorner = [485, 455];
  let cavityPts = [L_TL, backCorner, F_TR, L_TR];
  washPoly(cavityPts, PAL.sepiaDark, 92);

  // Back-layer foliage & rear butterhead lettuce head nestled deep in crate
  drawButterheadRosette(535, 425, 92, 15);

  // --- STEP 2: The Glass Bottle of Kombucha (emerging from center-right of crate) ---
  drawKombuchaBottle(612, 435, 13);

  // --- STEP 3: Left-Front & Right-Front Butterhead Lettuces (base layers inside crate) ---
  drawButterheadRosette(445, 480, 108, -12);
  drawButterheadRosette(748, 468, 96, 28);

  // Radish greens sprouting behind the radish bunch
  let radGreenPositions = [
    [555, 465, 52, -110],
    [582, 458, 58, -88],
    [615, 462, 54, -70],
    [648, 468, 50, -52],
    [675, 475, 46, -35]
  ];
  for (let rg of radGreenPositions) {
    drawLettuceLeaf(rg[0], rg[1], rg[2], rg[3], 48, PAL.sapMid, PAL.radishRose, 0.12, false);
  }

  // --- STEP 4: THE WOODEN CARGO CRATE (4 Planks on Left Side + 4 Planks on Front Nose) ---
  let numPlanks = 4;

  for (let p = 0; p < numPlanks; p++) {
    let t0 = p / numPlanks;
    let t1 = (p + 1) / numPlanks;

    // Left Side Plank
    let pTL = lerp2D(L_TL, L_BL, t0);
    let pTR = lerp2D(L_TR, L_BR, t0);
    let pBR = lerp2D(L_TR, L_BR, t1);
    let pBL = lerp2D(L_TL, L_BL, t1);
    let leftPlank = [pTL, pTR, pBR, pBL];

    // Base warm cedar/honey wood watercolour wash
    let woodCol = p % 2 === 0 ? PAL.woodLight : PAL.woodMid;
    wcPoly(leftPlank, woodCol, 94, 0.05, 0.42, 0.02);

    // Diagonal honeyed sunlight patch cutting across middle of crate side
    let sunL0 = lerp2D(pTL, pTR, 0.28 - p * 0.04);
    let sunL1 = lerp2D(pTL, pTR, 0.74 - p * 0.04);
    let sunL2 = lerp2D(pBL, pBR, 0.70 - p * 0.04);
    let sunL3 = lerp2D(pBL, pBR, 0.24 - p * 0.04);
    wcPoly([sunL0, sunL1, sunL2, sunL3], PAL.sunflowerBright, 48, 0.08, 0.3, 0.04);

    // Shaded rear corner of plank
    let shadeRear = [pTL, lerp2D(pTL, pTR, 0.24), lerp2D(pBL, pBR, 0.2), pBL];
    hatchPoly(shadeRear, 6, 12, "2B", PAL.woodDark, 0.24, 0.04);

    // Hyperreal Wood Grain & Cathedral Knots along each plank
    for (let g = 1; g <= 5; g++) {
      let gt = g / 6;
      let gStart = lerp2D(pTL, pBL, gt);
      let gEnd = lerp2D(pTR, pBR, gt);
      let g1 = lerp2D(gStart, gEnd, 0.28);
      let g2 = lerp2D(gStart, gEnd, 0.55);
      let g3 = lerp2D(gStart, gEnd, 0.82);
      // Cathedral grain wave around knot
      let knotWave = Math.sin(gt * Math.PI) * (g % 2 === 0 ? 5 : -5);
      g2[1] += knotWave;
      inkSpline([gStart, g1, g2, g3, gEnd], 0.45, 0.2, PAL.sepiaWarm, "rotring");
    }
    // Wood knot ellipse
    let knotPos = lerp2D(lerp2D(pTL, pBL, 0.5), lerp2D(pTR, pBR, 0.5), 0.35 + ((p * 29) % 45) * 0.01);
    let knotPts = ellipsePoly(knotPos[0], knotPos[1], 11, 4.5, -5, 12);
    washPoly(knotPts, PAL.woodDark, 85);
    inkPoly(knotPts, 0.24, PAL.sepiaDark, true, 0.1);

    // Plank seam shadow & sunlit upper bevel
    inkLine(pTL[0], pTL[1] + 2, pTR[0], pTR[1] + 2, 0.3, PAL.honeyPale, "cpencil");
    inkPoly(leftPlank, 0.4, PAL.sepiaDark, true, 0.02);

    // Front Slanted Nose Plank (in warm terracotta-umber shadow)
    let fTL = pTR;
    let fTR = lerp2D(F_TR, F_BR, t0);
    let fBR = lerp2D(F_TR, F_BR, t1);
    let fBL = pBR;
    let frontPlank = [fTL, fTR, fBR, fBL];

    wcPoly(frontPlank, p % 2 === 0 ? PAL.woodDark : PAL.terraDark, 95, 0.04, 0.45, 0.02);
    hatchPoly(frontPlank, 5.5, -22, "2B", PAL.sepiaDark, 0.25, 0.03);

    // Front plank wood grain
    for (let g = 1; g <= 3; g++) {
      let gt = g / 4;
      let gs = lerp2D(fTL, fBL, gt);
      let ge = lerp2D(fTR, fBR, gt);
      inkLine(gs[0], gs[1], ge[0], ge[1], 0.2, PAL.sepiaDark, "rotring");
    }
    inkPoly(frontPlank, 0.4, PAL.sepiaDark, true, 0.02);
  }

  // Underside baseboard thickness of the crate (visible because of low angle!)
  let baseBottomL = [L_BL[0] + 6, L_BL[1] + 18];
  let baseBottomMid = [L_BR[0] + 4, L_BR[1] + 20];
  let baseBottomR = [F_BR[0] - 4, F_BR[1] + 16];
  washPoly([L_BL, L_BR, baseBottomMid, baseBottomL], PAL.sepiaDark, 96);
  washPoly([L_BR, F_BR, baseBottomR, baseBottomMid], PAL.twilightDeep, 96);
  inkPoly([L_BL, L_BR, baseBottomMid, baseBottomL], 0.38, PAL.sepiaDark, true, 0.02);
  inkPoly([L_BR, F_BR, baseBottomR, baseBottomMid], 0.38, PAL.sepiaDark, true, 0.02);

  // Heavy Copper-Verdigris & Blackened Steel Corner Brackets with Hex Bolts
  for (let p = 0; p < numPlanks; p++) {
    let tMid = (p + 0.5) / numPlanks;
    // Center spine bracket at L_TR .. L_BR
    let cPt = lerp2D(L_TR, L_BR, tMid);
    let brkC = [
      [cPt[0] - 18, cPt[1] - 14],
      [cPt[0] + 15, cPt[1] - 10],
      [cPt[0] + 14, cPt[1] + 14],
      [cPt[0] - 19, cPt[1] + 10]
    ];
    washPoly(brkC, PAL.verdDeep, 96);
    inkPoly(brkC, 0.34, PAL.sepiaDark, true, 0.02);
    // Hex bolt heads
    for (let bx of [-10, 8]) {
      let bPoly = ellipsePoly(cPt[0] + bx, cPt[1], 3.5, 3.5, 0, 6);
      washPoly(bPoly, PAL.copperGold, 98);
      inkPoly(bPoly, 0.25, PAL.sepiaDark, true, 0.02);
    }

    // Rear corner bracket at L_TL .. L_BL
    let rPt = lerp2D(L_TL, L_BL, tMid);
    let brkR = [
      [rPt[0], rPt[1] - 12],
      [rPt[0] + 16, rPt[1] - 13],
      [rPt[0] + 16, rPt[1] + 11],
      [rPt[0], rPt[1] + 12]
    ];
    washPoly(brkR, PAL.verdDeep, 96);
    inkPoly(brkR, 0.32, PAL.sepiaDark, true, 0.02);
  }

  // Cast shadow of overhanging lettuce leaves & radishes onto the top wooden plank!
  let overhangShadow = [
    [355, 534], [465, 558], [535, 542], [615, 568],
    [695, 548], [765, 538], [820, 532], F_TR, L_TR, L_TL
  ];
  wcPoly(overhangShadow, PAL.twilightSlate, 62, 0.09, 0.4, 0.15);

  // --- STEP 5: OVERFLOWING FOREGROUND PRODUCE SPILLING OVER THE CRATE RIM ---
  // Foreground overarching butterhead lettuce leaves drooping over the left & right wooden rim
  drawLettuceLeaf(425, 495, 92, 95, 76, PAL.sapMid, PAL.lettuceHeart, 0.11, false);
  drawLettuceLeaf(485, 500, 86, 75, 72, PAL.sapBright, PAL.creamLight, 0.1, true);
  drawLettuceLeaf(378, 505, 78, 120, 68, PAL.verdDark, PAL.sapChartreuse, 0.1, false);

  drawLettuceLeaf(735, 482, 84, 65, 75, PAL.sapBright, PAL.lettuceHeart, 0.1, true);
  drawLettuceLeaf(788, 492, 76, 40, 70, PAL.sapMid, PAL.sapChartreuse, 0.11, false);

  // Bunch of 9 Crisp Scarlet-Terracotta Radishes tumbling over the front-center rim!
  let radishes = [
    [552, 498, 20, 24, -18, 46],
    [588, 512, 22, 26, 8, 52],
    [624, 504, 21, 25, -12, 48],
    [658, 516, 19, 24, 16, 45],
    [688, 498, 20, 23, 25, 38],
    [570, 480, 18, 21, -8, 30],
    [608, 482, 21, 22, 5, 32],
    [642, 486, 19, 21, -14, 34],
    [672, 478, 17, 20, 12, 28]
  ];
  // Raffia twine tying the radish bunch together
