  // Axle 3D extrusion vector (perpendicular to wheel plane)
  let axX = -24, axY = -6;

  // --- 7A. Copper-Verdigris Front Mudguard / Fender (wrapping upper-left arc of wheel) ---
  let fendBack = ellipsePoly(wCx + axX * 1.1, wCy + axY * 1.1, tireRx + 14, tireRy + 16, wTilt, 28, 125, 315);
