  // Honey-gold pinstripe along fender edge
  inkSpline(fendFront, 0.4, 0.45, PAL.honeyGold, "cpencil");
  inkPoly(fendPoly, 0.42, PAL.sepiaDark, true, 0.06);

  // --- 7B. Tire Casing & 56 Molded 3D Rubber Tread Blocks ---
  // Back tire cylinder wall
  let tireBack = ellipsePoly(wCx + axX, wCy + axY, tireRx, tireRy, wTilt, 48);
  let tireFront = ellipsePoly(wCx, wCy, tireRx, tireRy, wTilt, 48);
  let rimOpen = ellipsePoly(wCx, wCy, rimOuterRx, rimOuterRy, wTilt, 48);

  washPoly(tireBack, PAL.twilightDeep, 96);
  washPoly(tireFront, PAL.tireDark, 96);

  // Terracotta-tan gumwall stripe around tire sidewall
  let gumOuter = ellipsePoly(wCx, wCy, rimOuterRx + 12, rimOuterRy + 16, wTilt, 44);
  washPoly(gumOuter, PAL.woodMid, 88);

  // Cut out inner wheel opening and restore ground/shadow behind spokes
