  wcPoly(rimOpen, PAL.terraMid, 62, 0.08, 0.4, 0.08);
  // Dappled honeyed light patch visible *through* the lower spokes
  let wheelSun = ellipsePoly(wCx - 15, wCy + 45, 78, 95, wTilt, 18);
  wcPoly(wheelSun, PAL.sunflowerBright, 55, 0.12, 0.35, 0.15);

  // 56 Individual Molded Rubber Tread Lugs around the Tire Circumference
  let numLugs = 56;
  for (let i = 0; i < numLugs; i++) {
    let a1 = (i * 360) / numLugs;
    let a2 = ((i + 0.65) * 360) / numLugs;
    let p1 = ellipsePt(wCx, wCy, tireRx - 1, tireRy - 1, wTilt, a1);
    let p2 = ellipsePt(wCx, wCy, tireRx - 1, tireRy - 1, wTilt, a2);
    let p3 = ellipsePt(wCx + axX * 0.45, wCy + axY * 0.45, tireRx + 5, tireRy + 6, wTilt, a2);
    let p4 = ellipsePt(wCx + axX * 0.45, wCy + axY * 0.45, tireRx + 5, tireRy + 6, wTilt, a1);
    washPoly([p1, p2, p3, p4], i % 2 === 0 ? PAL.sepiaDark : PAL.twilightDeep, 95);
    inkPoly([p1, p2, p3, p4], 0.24, PAL.sepiaDark, true, 0.02);
  }

  // --- 7C. Double-Wall Alloy/Bronze Rim & Brass Valve Stem ---
  let rimWall = ellipsePoly(wCx + axX * 0.4, wCy + axY * 0.4, rimInnerRx, rimInnerRy, wTilt, 48);
