  let vBase = ellipsePt(wCx, wCy, rimInnerRx, rimInnerRy, wTilt, 125);
  let vTip = ellipsePt(wCx, wCy, rimInnerRx - 22, rimInnerRy - 28, wTilt, 125);
  inkLine(vBase[0], vBase[1], vTip[0], vTip[1], 0.65, PAL.honeyGold, "rotring");
  inkLine(vBase[0], vBase[1], vTip[0], vTip[1], 0.3, PAL.sepiaDark, "rotring");

  // --- 7D. Rear (Inner) Hub Flange, Disc Brake Rotor & 32 Tangential 3-Cross Spokes ---
  let hubBack = [wCx + axX * 0.75, wCy + axY * 0.75];
