  inkPoly(rotorOuter, 0.38, PAL.sepiaDark, true, 0.05);
  inkPoly(rotorInner, 0.3, PAL.sepiaDark, true, 0.05);
  // Rotor carrier arms & ventilation holes
  for (let r = 0; r < 12; r++) {
    let ra = r * 30;
    let holePt = ellipsePt(wCx + axX * 0.2, wCy + axY * 0.2, rotorRx * 0.8, rotorRy * 0.8, wTilt, ra);
