    // Tangential 3-cross phase shift (+62 or -62 deg)
    let crossDir = i % 4 < 2 ? 1 : -1;
    let hubAng = rimAng + crossDir * 64;

    let hp = ellipsePt(flCenter[0], flCenter[1], flRx * 0.88, flRy * 0.88, wTilt, hubAng);
