  // Outer (left) fork blade descending in foreground to front dropout (hubFront)
  let forkL = [
    [forkCrown[0] - 14, forkCrown[1] + 4],
    [forkCrown[0] + 6, forkCrown[1] + 6],
    [hubFront[0] + 8, hubFront[1] + 4],
    [hubFront[0] - 7, hubFront[1] + 2]
