  inkPoly(forkL, 0.42, PAL.sepiaDark, true, 0.04);

  // Disc Brake Caliper mounted to lower fork leg
  let calPts = [
    [hubFront[0] - 24, hubFront[1] - 44],
    [hubFront[0] - 4, hubFront[1] - 48],
    [hubFront[0] - 2, hubFront[1] - 22],
