  washPoly(calPts, PAL.terraDark, 96);
  inkPoly(calPts, 0.36, PAL.sepiaDark, true, 0.04);

  // Twin Stainless/Brass Fender Stays bolted to dropout
  let stay1 = ellipsePt(wCx - 6, wCy - 2, tireRx + 11, tireRy + 13, wTilt, 210);
  let stay2 = ellipsePt(wCx - 6, wCy - 2, tireRx + 11, tireRy + 13, wTilt, 255);
