  inkLine(hubFront[0], hubFront[1], stay2[0], stay2[1], 0.24, PAL.sepiaDark, "rotring");

  // Brass Axle Nut
  let nutPts = ellipsePoly(hubFront[0], hubFront[1], 7, 9, wTilt, 8);
  washPoly(nutPts, PAL.honeyGold, 98);
  inkPoly(nutPts, 0.38, PAL.sepiaDark, true, 0.05);
}

