// =============================================================================
// GEOMETRY & TEXTURE HELPERS
// =============================================================================

function lerpPt(p1, p2, t) {
  return [lerp(p1[0], p2[0], t), lerp(p1[1], p2[1], t)];
}

function distPt(p1, p2) {
  return dist(p1[0], p1[1], p2[0], p2[1]);
}

function polyWashAndMarker(pts, washCol, washAlpha, markerCols, angle, spacing, grainCol) {
  let poly = new brush.Polygon(pts);

  // Subtle base wash
  brush.noStroke();
  brush.noHatch();
  poly.wash(washCol, washAlpha);

  // Layered kraft-brown marker fills
  for (let i = 0; i < markerCols.length; i++) {
    let mCol = markerCols[i];
    let sp = spacing * (0.85 + i * 0.22);
    let ang = angle + (i % 2 === 0 ? 0 : 1.8);
    brush.hatchStyle("kraft_marker", mCol, 0.95 - i * 0.12);
    poly.hatch(sp, ang, { rand: 0.03, continuous: true });
  }

  // Fine directional paper-mill grain in pencil
  if (grainCol) {
    brush.hatchStyle("2H", grainCol, 0.25);
    poly.hatch(spacing * 0.42, angle, { rand: 0.08, continuous: false });
  }
  brush.noHatch();
}

function sprinkleWoodPulpFlecks(pts, count, minX, maxX, minY, maxY) {
  for (let i = 0; i < count; i++) {
    let x = random(minX, maxX);
    let y = random(minY, maxY);
    if (pointInPoly(x, y, pts)) {
      let col = random() < 0.65 ? PAL.umber : (random() < 0.5 ? PAL.buffLight : PAL.kraftDeep);
      brush.set("2H", col, random(0.18, 0.35));
      let ang = random(360);
      let len = random(1.5, 4.5);
      brush.line(x, y, x + cos(ang) * len, y + sin(ang) * len);
    }
  }
}

function pointInPoly(x, y, vs) {
  let inside = false;
  for (let i = 0, j = vs.length - 1; i < vs.length; j = i++) {
    let xi = vs[i][0], yi = vs[i][1];
    let xj = vs[j][0], yj = vs[j][1];
    let intersect = ((yi > y) !== (yj > y)) &&
      (x < (xj - xi) * (y - yi) / ((yj - yi) || 0.0001) + xi);
    if (intersect) inside = !inside;
  }
  return inside;
}

// Renders a hyperreal band of exposed corrugated inner fluting between two ragged curves
function drawExposedFluteBand(upperChain, lowerChain, numFlutes, rippleLinesCount, isHero) {
  // 1. Base recessed flute bed polygon
  let bandPolyPts = [...upperChain, ...lowerChain.slice().reverse()];
  let bandPoly = new brush.Polygon(bandPolyPts);
  brush.noStroke();
  bandPoly.wash(PAL.kraftMid, 210);
  brush.hatchStyle("marker", PAL.kraftDeep, 0.55);
  bandPoly.hatch(10, 35, { rand: 0.04, continuous: true });
  brush.noHatch();

  let sampleOnChain = (chain, u) => {
    let idx = constrain(u * (chain.length - 1), 0, chain.length - 1.0001);
    let i0 = floor(idx);
    let f = idx - i0;
    return lerpPt(chain[i0], chain[i0 + 1], f);
  };

  // 2. Individual 3D flute channels (valleys, lit ridges, glue lines, and cast shadows at tips)
  for (let k = 0; k < numFlutes; k++) {
    let uMid = (k + 0.5) / numFlutes;
    let uValleyL = k / numFlutes;
    let uCrest = (k + 0.42) / numFlutes;
    let uSlope = (k + 0.72) / numFlutes;

    let pTopV = sampleOnChain(upperChain, uValleyL);
    let pBotV = sampleOnChain(lowerChain, uValleyL);

    let pTopC = sampleOnChain(upperChain, uCrest);
    let pBotC = sampleOnChain(lowerChain, uCrest);

    let pTopS = sampleOnChain(upperChain, uSlope);
    let pBotS = sampleOnChain(lowerChain, uSlope);

    // Recessed dark groove (valley)
    brush.set("marker", PAL.umber, isHero ? 0.36 : 0.28);
    brush.line(pTopV[0], pTopV[1], pBotV[0], pBotV[1]);

    brush.set("2B", PAL.umberDeep, isHero ? 0.32 : 0.24);
    brush.line(
      lerp(pTopV[0], pBotV[0], 0.04),
      lerp(pTopV[1], pBotV[1], 0.04),
      lerp(pTopV[0], pBotV[0], 0.96),
      lerp(pTopV[1], pBotV[1], 0.96)
    );

    // Mid-tone kraft slope
    brush.set("cpencil", PAL.kraft, isHero ? 0.42 : 0.32);
    brush.line(pTopS[0], pTopS[1], pBotS[0], pBotS[1]);

    // Lit flute crest catching diffuse warehouse light
    brush.set("marker", PAL.buffWarm, isHero ? 0.34 : 0.25);
    brush.line(
      lerp(pTopC[0], pBotC[0], 0.06),
      lerp(pTopC[1], pBotC[1], 0.06),
      lerp(pTopC[0], pBotC[0], 0.92),
      lerp(pTopC[1], pBotC[1], 0.92)
    );

    brush.set("2H", PAL.buffLight, isHero ? 0.28 : 0.22);
    brush.line(
      lerp(pTopC[0], pBotC[0], 0.1),
      lerp(pTopC[1], pBotC[1], 0.1),
      lerp(pTopC[0], pBotC[0], 0.88),
      lerp(pTopC[1], pBotC[1], 0.88)
    );

    // Short directional pencil shading across the flute cylinder
    let stepsAlongFlute = isHero ? 7 : 5;
    for (let s = 1; s < stepsAlongFlute; s++) {
      let vt = s / stepsAlongFlute + random(-0.03, 0.03);
      let cPt = lerpPt(pTopC, pBotC, vt);
      let vPt = lerpPt(pTopV, pBotV, vt);
      brush.set("2H", PAL.umberLight, 0.2);
      brush.line(vPt[0], vPt[1], lerp(vPt[0], cPt[0], 0.65), lerp(vPt[1], cPt[1], 0.65));
    }

    // At the lower edge, each flute arch projects a tiny semi-circular 3D lip and dark pocket shadow
    if (isHero && k < numFlutes - 1) {
      let pBotNextV = sampleOnChain(lowerChain, (k + 1) / numFlutes);
      let archMid = [
        (pBotV[0] + pBotNextV[0]) * 0.5 + (pBotC[0] - pTopC[0]) * 0.06,
        (pBotV[1] + pBotNextV[1]) * 0.5 + (pBotC[1] - pTopC[1]) * 0.06
      ];
      // Hollow shadow under flute arch
      brush.set("2B", PAL.umberBlack, 0.38);
      brush.spline([pBotV, [archMid[0] + 2, archMid[1] + 5], pBotNextV], 0.5);
      // Lit flute arch rim
      brush.set("2H", PAL.buff, 0.28);
      brush.spline([pBotV, archMid, pBotNextV], 0.5);
    }
  }

  // 3. PRECISE RIPPLING PENCIL LINES running across all flutes (the signature undulating contour lines)
  let sampleCols = [PAL.umberDeep, PAL.umber, PAL.warmGreyDeep, PAL.umberLight, PAL.buffLight];
  for (let r = 0; r < rippleLinesCount; r++) {
    let vFrac = map(r, 0, rippleLinesCount - 1, 0.06, 0.94);
    let wavePts = [];
    let totalSamples = numFlutes * 4;

    for (let s = 0; s <= totalSamples; s++) {
      let u = s / totalSamples;
      let pTop = sampleOnChain(upperChain, u);
      let pBot = sampleOnChain(lowerChain, u);

      // Flute vector (from upper tear lip to lower tear lip)
      let dx = pBot[0] - pTop[0];
      let dy = pBot[1] - pTop[1];
      let fluteLen = sqrt(dx * dx + dy * dy) || 1;
      let nx = dx / fluteLen;
      let ny = dy / fluteLen;

      // Sinusoidal ripple rising over each crest and dipping into each valley
      let phase = u * numFlutes * 360;
      let waveAmp = (isHero ? 4.2 : 3.1) * sin(vFrac * 180);
      let rippleOffset = -cos(phase) * waveAmp + (noise(u * 8, r * 0.3) - 0.5) * 1.4;

      let basePt = lerpPt(pTop, pBot, vFrac);
      wavePts.push([
        basePt[0] + nx * rippleOffset,
        basePt[1] + ny * rippleOffset
      ]);
    }

    // Draw the rippling pencil line in segments so we can vary pressure & highlight crests
    let isHighlightLine = (r % 5 === 2);
    let isDarkLine = (r % 4 === 0);
    let bName = isHighlightLine ? "2H" : (isDarkLine ? "2B" : "HB");
    let col = isHighlightLine ? PAL.buffLight : sampleCols[r % 4];
    let wt = isHighlightLine ? 0.22 : (isDarkLine ? 0.32 : 0.24);

    brush.set(bName, col, wt);
    brush.spline(wavePts, 0.45);
  }

  // 4. Faint white/buff starch glue lines running across the flute crests
  for (let g = 0; g < (isHero ? 5 : 3); g++) {
    let vGlue = map(g, 0, isHero ? 4 : 2, 0.22, 0.78);
    for (let k = 0; k < numFlutes; k++) {
      let uC = (k + 0.42) / numFlutes;
      let pTop = sampleOnChain(upperChain, uC);
      let pBot = sampleOnChain(lowerChain, uC);
      let gp = lerpPt(pTop, pBot, vGlue + random(-0.02, 0.02));
      brush.set("2H", PAL.buffBright, 0.22);
      brush.line(gp[0] - 2.5, gp[1] + 1.2, gp[0] + 2.5, gp[1] - 1.2);
    }
  }

  // 5. Ragged fibrous torn paper lips along both upperChain and lowerChain
  drawRaggedPaperTearLip(upperChain, 1, isHero ? 11 : 8);
  drawRaggedPaperTearLip(lowerChain, -1, isHero ? 9 : 6);
}

// Draws the raw deckle edge of torn kraft linerboard (pale inner fibers + cast shadow + pencil contour)
function drawRaggedPaperTearLip(chain, sideSign, lipWidth) {
  let offsetChain = [];
  for (let i = 0; i < chain.length; i++) {
    let p = chain[i];
    let pNext = chain[min(i + 1, chain.length - 1)];
    let pPrev = chain[max(i - 1, 0)];
    let tx = pNext[0] - pPrev[0];
    let ty = pNext[1] - pPrev[1];
    let len = sqrt(tx * tx + ty * ty) || 1;
    let nx = -ty / len * sideSign;
    let ny = tx / len * sideSign;
    let w = lipWidth * (0.65 + 0.7 * noise(i * 0.45, sideSign * 10));
    offsetChain.push([p[0] + nx * w, p[1] + ny * w]);
  }

  // Fibrous buff paper bevel polygon
  let lipPolyPts = [...chain, ...offsetChain.slice().reverse()];
  let lipPoly = new brush.Polygon(lipPolyPts);
  brush.noStroke();
  lipPoly.wash(PAL.buffLight, 215);

  // Tiny pulled paper fibers along the tear
  for (let i = 0; i < chain.length - 1; i++) {
    let pA = chain[i];
    let pB = chain[i + 1];
    let oA = offsetChain[i];
    let oB = offsetChain[i + 1];
    let steps = 6;
    for (let s = 0; s < steps; s++) {
      let t = (s + random()) / steps;
      let p1 = lerpPt(pA, pB, t);
      let p2 = lerpPt(oA, oB, t);
      brush.set("2H", s % 2 === 0 ? PAL.buffBright : PAL.buffWarm, random(0.16, 0.28));
      brush.line(p1[0], p1[1], p2[0] + random(-2, 2), p2[1] + random(-2, 2));
    }
  }

  // Crisp irregular shadow line under the torn lip
  brush.set("2B", PAL.umberDeep, 0.34);
  brush.spline(chain, 0.25);

  // Outer edge where kraft surface breaks into raw buff pulp
  brush.set("HB", PAL.kraftDeep, 0.28);
  brush.spline(offsetChain, 0.25);
}

// Draws the cut cross-section edge of corrugated cardboard (two flat liners + S-wave flute inside)
function drawCorrugatedCutEdge(pStart, pEnd, thickness, waveCount) {
  let dx = pEnd[0] - pStart[0];
  let dy = pEnd[1] - pStart[1];
  let len = sqrt(dx * dx + dy * dy) || 1;
  let ux = dx / len;
  let uy = dy / len;
  let nx = -uy;
  let ny = ux;

  let pStart2 = [pStart[0] + nx * thickness, pStart[1] + ny * thickness];
  let pEnd2 = [pEnd[0] + nx * thickness, pEnd[1] + ny * thickness];

  // Recessed dark interior of the cut edge
  let edgePoly = new brush.Polygon([pStart, pEnd, pEnd2, pStart2]);
  brush.noStroke();
  edgePoly.wash(PAL.umber, 210);

  // Sinusoidal flute wave sandwiched between the two liners
  let wavePts = [];
  let totalSteps = waveCount * 4;
  for (let i = 0; i <= totalSteps; i++) {
    let t = i / totalSteps;
    let bx = lerp(pStart[0], pEnd[0], t);
    let by = lerp(pStart[1], pEnd[1], t);
    let sWave = (sin(t * waveCount * 360) * 0.42 + 0.5) * thickness;

    // Dark shadow dot inside each wave hollow
    if (i % 2 === 1 && i < totalSteps) {
      let hOff = (sin(t * waveCount * 360) > 0 ? 0.76 : 0.24) * thickness;
      brush.set("2B", PAL.umberBlack, 0.36);
      brush.line(
        bx + nx * hOff - ux * 2,
        by + ny * hOff - uy * 2,
        bx + nx * hOff + ux * 2,
        by + ny * hOff + uy * 2
      );
    }

    wavePts.push([bx + nx * sWave, by + ny * sWave]);
  }

  // Draw the sinusoidal flute ribbon
  brush.set("HB", PAL.tanLight, 0.35);
  brush.spline(wavePts, 0.5);
  brush.set("2H", PAL.buffLight, 0.22);
  brush.spline(wavePts, 0.5);

  // Top and bottom kraft liner edges
  brush.set("HB", PAL.buffWarm, 0.38);
  brush.line(pStart[0], pStart[1], pEnd[0], pEnd[1]);
  brush.set("2B", PAL.umberDeep, 0.38);
  brush.line(pStart2[0], pStart2[1], pEnd2[0], pEnd2[1]);
}

