// =============================================================================
// 3. THE SLEEPING TABBY KITTEN (CRAMMED AGAINST THE CORNER OF THE FRAME)
// =============================================================================

function drawSleepingKitten() {
  // Deep cozy contact shadow beneath the curled kitten on the box floor and walls
  let contactShadowPts = [
    [605, 985], [690, 745], [960, 575], [1185, 675],
    [1195, 1165], [710, 1165], [605, 1085]
  ];
  let cshPoly = new brush.Polygon(contactShadowPts);
  brush.noStroke();
  cshPoly.wash(PAL.umberBlack, 175);

  // ---------------------------------------------------------------------------
  // A. KITTEN TORSO, BACK, SHOULDER & HAUNCH (Crammed into right/bottom-right corner)
  // ---------------------------------------------------------------------------
  let torsoPts = [
    [765, 650], [875, 588], [1005, 582], [1115, 635],
    [1172, 740], [1182, 885], [1162, 1020], [1075, 1105],
    [925, 1110], [785, 1045], [725, 925], [730, 765]
  ];
  let torsoPoly = new brush.Polygon(torsoPts);
  brush.noStroke();
  torsoPoly.wash(PAL.warmGrey, 225);
  brush.hatchStyle("kraft_marker", PAL.amber, 0.65);
  torsoPoly.hatch(16, -35, { rand: 0.08, continuous: true });
  brush.noHatch();

  // Helper to evaluate tabby pattern on the curled body:
  // Spine center curves around (890, 845) from angle -65 deg to +115 deg
  let getTorsoTabbyCol = (x, y) => {
    let dx = x - 885;
    let dy = y - 845;
    let r = sqrt(dx * dx + dy * dy);
    let theta = atan2(dy, dx); // degrees in [-180, 180]

    // Classic/Mackerel tabby banding along theta + bullseye swirl on shoulder/flank (1020, 775)
    let sdx = x - 1015;
    let sdy = y - 775;
    let sr = sqrt(sdx * sdx + sdy * sdy);

    let wave = sin(theta * 9.5 + r * 0.22 + noise(x * 0.015, y * 0.015) * 55);
    let swirl = (sr < 135) ? sin(sr * 0.16 * 57.3) : 1;

    // Dorsal spine stripe near outer rim (r ~ 245..290)
    let isSpineStripe = (r > 235 && r < 278 && theta > -55 && theta < 75);

    if (isSpineStripe || wave < -0.38 || (sr < 120 && swirl < -0.35)) {
      return random() < 0.65 ? PAL.umberDeep : PAL.umber;
    } else if (wave < 0.08) {
      return random() < 0.55 ? PAL.amber : PAL.amberDeep;
    } else if (wave < 0.52) {
      return random() < 0.6 ? PAL.warmGrey : PAL.warmGreyDeep;
    } else {
      return random() < 0.55 ? PAL.buffWarm : PAL.warmGreyLight;
    }
  };

  // Build torso fur from ~1,350 short directional pencil strokes echoing the cardboard's grain
  for (let i = 0; i < 1350; i++) {
    let x = random(735, 1180);
    let y = random(580, 1110);
    if (!pointInPoly(x, y, torsoPts)) continue;

    // Skip center where head sits so we focus density on visible back/shoulder/haunch
    if (dist(x, y, 800, 830) < 115) continue;

    let dx = x - 875;
    let dy = y - 845;
    // Fur flows clockwise along the curled C-posture of the spine
    let baseAng = atan2(dy, dx) + 82 + (noise(x * 0.012, y * 0.012) - 0.5) * 24;
    let len = random(13, 24);
    let col = getTorsoTabbyCol(x, y);

    // Top shoulder edge catches flat diffuse warehouse light
    if (y < 645 && x > 820 && x < 1090 && random() < 0.45) {
      col = random() < 0.5 ? PAL.buffLight : PAL.buffWarm;
    }
    // Rightmost edge pressed against cardboard wall falls into warm umber shadow
    if (x > 1130 && random() < 0.55) {
      col = random() < 0.6 ? PAL.umber : PAL.umberDeep;
    }

    let bType = (col === PAL.umberDeep || col === PAL.umber) ? "2B" : (col === PAL.buffLight ? "2H" : "HB");
    let wt = (bType === "2H") ? random(0.2, 0.3) : random(0.28, 0.44);
    brush.set(bType, col, wt);
    brush.line(x, y, x + cos(baseAng) * len, y + sin(baseAng) * len);
  }

  // Body crease shadows (between shoulder and haunch, and along the belly tuck)
  brush.set("2B", PAL.umberDeep, 0.38);
  brush.spline([[940, 845], [1015, 875], [1085, 895]], 0.4);
  brush.spline([[885, 945], [965, 975], [1040, 980]], 0.4);

  // ---------------------------------------------------------------------------
  // B. TUCKED HIND LEG & PAW (Peeking out against the crumpled kraft paper)
  // ---------------------------------------------------------------------------
  let hindPawPts = [
    [618, 1020], [665, 982], [755, 972], [815, 1015],
    [775, 1072], [670, 1078], [620, 1052]
  ];
  let hpPoly = new brush.Polygon(hindPawPts);
  brush.noStroke();
  hpPoly.wash(PAL.buffWarm, 225);

  for (let i = 0; i < 240; i++) {
    let x = random(618, 815);
    let y = random(972, 1078);
    if (!pointInPoly(x, y, hindPawPts)) continue;
    let ang = 195 + (y - 1025) * 0.25 + random(-8, 8);
    let len = random(7, 14);
    let col = (x < 680)
      ? (random() < 0.65 ? PAL.buffLight : PAL.buff)
      : (sin(x * 3.8) < -0.2 ? PAL.umber : (random() < 0.5 ? PAL.amber : PAL.warmGrey));
    brush.set(x < 680 ? "2H" : "HB", col, random(0.22, 0.35));
    brush.line(x, y, x + cos(ang) * len, y + sin(ang) * len);
  }
  // Hind toe separations
  for (let t = 0; t < 3; t++) {
    let ty = 1008 + t * 18;
    brush.set("2B", PAL.umber, 0.3);
    brush.line(622 + t * 4, ty, 658 + t * 4, ty + 3);
  }

  // ---------------------------------------------------------------------------
  // C. CURLED BANDED TAIL (Wrapping along the bottom from right haunch to paws)
  // ---------------------------------------------------------------------------
  let tailSpine = [
    [1095, 1055], [1035, 1108], [945, 1135],
    [850, 1132], [765, 1110], [708, 1082]
  ];
  let tailUpper = [
    [1065, 1020], [1010, 1068], [935, 1090],
    [850, 1088], [775, 1070], [720, 1054]
  ];
  let tailLower = [
    [1120, 1085], [1055, 1142], [955, 1168],
    [845, 1165], [752, 1140], [696, 1104]
  ];
  let tailPolyPts = [...tailUpper, ...tailLower.slice().reverse()];
  let tailPoly = new brush.Polygon(tailPolyPts);
  brush.noStroke();
  tailPoly.wash(PAL.warmGrey, 235);

  // Directional fur strokes along the curled tail with dark umber rings & dark tip
  for (let i = 0; i < 420; i++) {
    let u = random(0, 1);
    let v = random(0, 1);
    let idx = constrain(u * (tailUpper.length - 1), 0, tailUpper.length - 1.001);
    let i0 = floor(idx);
    let f = idx - i0;
    let pTop = lerpPt(tailUpper[i0], tailUpper[i0 + 1], f);
    let pBot = lerpPt(tailLower[i0], tailLower[i0 + 1], f);
    let pt = lerpPt(pTop, pBot, v);

    let pNext = lerpPt(
      lerpPt(tailUpper[i0], tailUpper[i0 + 1], min(1, f + 0.1)),
      lerpPt(tailLower[i0], tailLower[i0 + 1], min(1, f + 0.1)),
      v
    );
    let tang = atan2(pNext[1] - pt[1], pNext[0] - pt[0]) + (v - 0.5) * 28 + random(-7, 7);

    // 6 dark tabby tail rings + solid dark umber tail tip (u > 0.86)
    let ringVal = sin(u * 6.2 * 360);
    let col;
    if (u > 0.85 || ringVal < -0.25) {
      col = random() < 0.7 ? PAL.umberDeep : PAL.umber;
    } else if (ringVal < 0.2) {
      col = random() < 0.55 ? PAL.amber : PAL.warmGreyDeep;
    } else {
      col = (v < 0.35) ? PAL.buffWarm : PAL.warmGreyLight;
    }

    let len = random(9, 16);
    brush.set(col === PAL.umberDeep ? "2B" : "HB", col, random(0.24, 0.38));
    brush.line(pt[0], pt[1], pt[0] + cos(tang) * len, pt[1] + sin(tang) * len);
  }

  // Shadow between tail and body
  brush.set("2B", PAL.umberBlack, 0.36);
  brush.spline(tailUpper, 0.45);

  // ---------------------------------------------------------------------------
  // D. TUCKED FRONT PAWS (Under the sleeping chin and cheek)
  // ---------------------------------------------------------------------------
  // Right Front Paw (viewer's right, tucked beside the right cheek)
  let rPawPts = [
    [875, 925], [975, 915], [1005, 965], [975, 1020], [885, 1025], [855, 975]
  ];
  let rpPoly = new brush.Polygon(rPawPts);
  brush.noStroke();
  rpPoly.wash(PAL.buffWarm, 230);

  for (let i = 0; i < 220; i++) {
    let x = random(855, 1005);
    let y = random(915, 1025);
    if (!pointInPoly(x, y, rPawPts)) continue;
    let ang = 135 + random(-10, 10);
    let len = random(7, 13);
    let isStripe = sin((y - 920) * 5.2) < -0.3 && y < 985;
    let col = (y > 985)
      ? (random() < 0.65 ? PAL.buffLight : PAL.buff)
      : (isStripe ? PAL.umber : (random() < 0.5 ? PAL.amberLight : PAL.warmGreyLight));
    brush.set(y > 985 ? "2H" : "HB", col, random(0.22, 0.34));
    brush.line(x, y, x + cos(ang) * len, y + sin(ang) * len);
  }

  // Left Front Paw (viewer's left, directly supporting the kitten's chin)
  let lPawPts = [
    [712, 942], [855, 945], [882, 995], [848, 1038], [735, 1035], [698, 990]
  ];
  let lpPoly = new brush.Polygon(lPawPts);
  brush.noStroke();
  lpPoly.wash(PAL.buffLight, 235);

  for (let i = 0; i < 280; i++) {
    let x = random(698, 882);
    let y = random(942, 1038);
    if (!pointInPoly(x, y, lPawPts)) continue;
    let ang = map(x, 700, 880, 115, 75) + random(-8, 8);
    let len = random(6, 12);
    let col;
    if (x > 745 && y > 968) {
      // Soft buff-white toes
      col = random() < 0.65 ? PAL.buffBright : PAL.buffLight;
    } else if (sin((x - 700) * 4.5) < -0.25) {
      col = PAL.umber;
    } else {
      col = random() < 0.5 ? PAL.amberLight : PAL.buffWarm;
    }
    brush.set(col === PAL.buffBright ? "2H" : "HB", col, random(0.2, 0.34));
    brush.line(x, y, x + cos(ang) * len, y + sin(ang) * len);
  }

  // Delicate toe clefts on the front paws
  let toeClefts = [
    [[768, 996], [762, 1032]],
    [[798, 998], [795, 1035]],
    [[828, 996], [826, 1033]],
    [[908, 985], [896, 1018]],
    [[936, 986], [925, 1020]]
  ];
  for (let tc of toeClefts) {
    brush.set("2B", PAL.umber, 0.3);
    brush.line(tc[0][0], tc[0][1], tc[1][0], tc[1][1]);
    brush.set("2H", PAL.buffBright, 0.24);
    brush.line(tc[0][0] + 3, tc[0][1], tc[1][0] + 3, tc[1][1]);
  }

  // ---------------------------------------------------------------------------
  // E. THE KITTEN'S HEAD, EARS, TABBY FACE & THE SINGLE PINK NOSE
  // ---------------------------------------------------------------------------
  // Soft shadow cast by the head onto the front paws and chest
  let headShadowPts = [[695, 920], [925, 925], [910, 978], [710, 972]];
  let hsPoly = new brush.Polygon(headShadowPts);
  brush.noStroke();
  hsPoly.wash(PAL.umberDeep, 145);

  // Head Silhouette Polygon
  let headPts = [
    [682, 745], [748, 695], [825, 690], [895, 712],
    [948, 775], [955, 852], [918, 920], [858, 958],
    [808, 968], [755, 954], [692, 908], [662, 832]
  ];
  let headPoly = new brush.Polygon(headPts);
  brush.noStroke();
  headPoly.wash(PAL.buffWarm, 235);
  brush.hatchStyle("kraft_marker", PAL.amberLight, 0.5);
  headPoly.hatch(14, -14, { rand: 0.06, continuous: true });
  brush.noHatch();

  // Left Ear (viewer's left) - drooped tenderly sideways in sleep
  let lEarPts = [[672, 778], [634, 688], [648, 646], [694, 658], [756, 708]];
  let lEarPoly = new brush.Polygon(lEarPts);
  brush.noStroke();
  lEarPoly.wash(PAL.warmGreyDeep, 230);

  // Inner shell of Left Ear (muted warm tan-buff, no pink so the nose remains the sole pink!)
  let lEarInnerPts = [[676, 765], [648, 690], [662, 666], [738, 712]];
  let lEarInnerPoly = new brush.Polygon(lEarInnerPts);
  brush.noStroke();
  lEarInnerPoly.wash(PAL.tanLight, 215);

  // Right Ear (viewer's right) - angled softly back
  let rEarPts = [[868, 712], [938, 662], [982, 666], [988, 708], [944, 785]];
  let rEarPoly = new brush.Polygon(rEarPts);
  brush.noStroke();
  rEarPoly.wash(PAL.umberLight, 230);

  let rEarInnerPts = [[888, 725], [945, 680], [972, 686], [938, 768]];
  let rEarInnerPoly = new brush.Polygon(rEarInnerPts);
  brush.noStroke();
  rEarInnerPoly.wash(PAL.tanLight, 200);

  // Ear fur strokes & long pale ear-furnishing tufts
  for (let i = 0; i < 220; i++) {
    // Left ear rim & back
    let t = random();
    let pRim = lerpPt([672, 778], [648, 646], t);
    let pTop = lerpPt([756, 708], [648, 646], t);
    let pt = lerpPt(pRim, pTop, random());
    let ang = -125 + random(-10, 10);
    let col = (t > 0.65) ? PAL.umberDeep : (random() < 0.5 ? PAL.amber : PAL.warmGrey);
    brush.set("HB", col, random(0.2, 0.32));
    brush.line(pt[0], pt[1], pt[0] + cos(ang) * 9, pt[1] + sin(ang) * 9);

    // Right ear rim & back (with pale buff thumbprint ocellus)
    let pRimR = lerpPt([868, 712], [982, 666], t);
    let pBotR = lerpPt([944, 785], [982, 666], t);
    let ptR = lerpPt(pRimR, pBotR, random());
    let angR = -28 + random(-10, 10);
    let colR = (t > 0.68) ? PAL.umberDeep : (t > 0.3 && t < 0.58 ? PAL.buffWarm : PAL.umber);
    brush.set("HB", colR, random(0.2, 0.32));
    brush.line(ptR[0], ptR[1], ptR[0] + cos(angR) * 9, ptR[1] + sin(angR) * 9);
  }

  // Long sweeping cream-buff ear furnishings streaming across the ear openings
  for (let i = 0; i < 48; i++) {
    let f = i / 47;
    let pL = lerpPt([742, 712], [676, 766], f);
    brush.set("2H", i % 2 === 0 ? PAL.buffBright : PAL.buffLight, random(0.18, 0.28));
    let angL = 198 + (f - 0.5) * 28 + random(-5, 5);
    let lenL = random(16, 28);
    brush.line(pL[0], pL[1], pL[0] + cos(angL) * lenL, pL[1] + sin(angL) * lenL);

    let pR = lerpPt([882, 718], [938, 772], f);
    let angR = -15 + (f - 0.5) * 25 + random(-5, 5);
    let lenR = random(14, 24);
    brush.line(pR[0], pR[1], pR[0] + cos(angR) * lenR, pR[1] + sin(angR) * lenR);
  }

  // ---------------------------------------------------------------------------
  // FACIAL FUR ARCHITECTURE (Short directional pencil strokes radiating from nose)
  // ---------------------------------------------------------------------------
  let noseCenter = [808, 908];

  let getFaceFurProps = (x, y) => {
    // 1. Nose bridge (x: 786..830, y: 835..908): ultra-short vertical amber & buff hairs
    if (x > 784 && x < 832 && y > 830 && y < 908) {
      let sideShade = abs(x - 808) > 16;
      return {
        col: sideShade ? PAL.umber : (random() < 0.6 ? PAL.amberLight : PAL.buffWarm),
        ang: -90 + (x - 808) * 0.8,
        len: random(4.5, 8.5),
        bName: "2H"
      };
    }

    // 2. Pale buff "spectacles" around the closed sleeping eyes
    let dLeftEye = dist(x, y, 746, 852);
    let dRightEye = dist(x, y, 874, 858);
    if (dLeftEye < 38 || dRightEye < 38) {
      let isLeft = dLeftEye < dRightEye;
      let ex = isLeft ? 746 : 874;
      let ey = isLeft ? 852 : 858;
      let ang = atan2(y - ey, x - ex) + (isLeft ? -25 : 25);
      return {
        col: random() < 0.65 ? PAL.buffBright : PAL.buffLight,
        ang: ang,
        len: random(6, 11),
        bName: "2H"
      };
    }

    // 3. Whisker pads & Chin (x: 745..870, y: 908..968)
    if (x > 745 && x < 872 && y >= 908) {
      let isChin = y > 946;
      return {
        col: isChin ? PAL.warmGreyLight : (random() < 0.7 ? PAL.buffBright : PAL.buffLight),
        ang: isChin ? 90 : (x < 808 ? 155 : 25),
        len: random(5, 9),
        bName: "2H"
      };
    }

    // 4. Forehead & Crown (y < 835): Classic Tabby "M" and 5 crown stripes
    if (y < 835) {
      // Normalize horizontal position across forehead centered at x = 812
      let u = (x - 812) / 95; // roughly -1.2 to +1.2
      // M-shape wave with 4 peaks/legs
      let mWave = cos(u * 3.2 * 180);
      let ang = -90 + u * 38 + random(-6, 6);
      let col;
      if (mWave > 0.35 && abs(u) < 1.05) {
        col = random() < 0.7 ? PAL.umberDeep : PAL.umber;
      } else if (mWave > -0.15) {
        col = random() < 0.6 ? PAL.amber : PAL.amberDeep;
      } else {
        col = random() < 0.55 ? PAL.warmGrey : PAL.buffWarm;
      }
      return {
        col: col,
        ang: ang,
        len: random(8, 15),
        bName: (col === PAL.umberDeep) ? "2B" : "HB"
      };
    }

    // 5. Fluffy Cheeks (left x < 765, right x > 855, y: 825..945)
    let isLeftCheek = x < 808;
    let cAng = isLeftCheek
      ? map(y, 820, 940, 165, 130)
      : map(y, 820, 940, 15, 50);

    // Classic tabby cheek pencil stripes (two dark arcs sweeping from outer eye across cheek)
    let stripe1 = abs((y - 865) - Math.abs(x - 808) * 0.22) < 7;
    let stripe2 = abs((y - 892) - Math.abs(x - 808) * 0.26) < 7;
    let col;
    if (stripe1 || stripe2) {
      col = random() < 0.7 ? PAL.umberDeep : PAL.umber;
    } else if (abs(x - 808) > 105) {
      col = random() < 0.55 ? PAL.buffLight : PAL.warmGreyLight;
    } else {
      col = random() < 0.5 ? PAL.amberLight : PAL.warmGrey;
    }

    return {
      col: col,
      ang: cAng + random(-7, 7),
      len: random(9, 16),
      bName: (stripe1 || stripe2) ? "2B" : "HB"
    };
  };

  // Render ~1,150 directional facial pencil strokes
  for (let i = 0; i < 1150; i++) {
    let x = random(660, 958);
    let y = random(688, 968);
    if (!pointInPoly(x, y, headPts)) continue;

    // Exclude the tiny pink nose triangle itself so it stays clean
    if (y > 904 && y < 933 && abs(x - 808) < 19) continue;

    let fp = getFaceFurProps(x, y);
    let wt = (fp.bName === "2H") ? random(0.18, 0.28) : random(0.24, 0.38);
    brush.set(fp.bName, fp.col, wt);
    brush.line(x, y, x + cos(fp.ang) * fp.len, y + sin(fp.ang) * fp.len);
  }

  // Reinforce the iconic Tabby "M" on the brow with crisp directional pencil clusters
  let mStrokes = [
    // Left outer leg of M
    [[748, 822], [756, 772]],
    // Left inner V-slope
    [[756, 772], [782, 804]],
    // Left center peak
    [[782, 804], [796, 764]],
    // Center valley above nose bridge
    [[796, 764], [810, 795]],
    [[810, 795], [824, 766]],
    // Right inner V-slope
    [[824, 766], [838, 806]],
    // Right peak
    [[838, 806], [864, 776]],
    // Right outer leg of M
    [[864, 776], [872, 826]]
  ];
  for (let seg of mStrokes) {
    for (let s = 0; s < 14; s++) {
      let t = s / 13;
      let p = lerpPt(seg[0], seg[1], t);
      let ang = -90 + (p[0] - 810) * 0.28 + random(-6, 6);
      brush.set("2B", s % 3 === 0 ? PAL.umber : PAL.umberDeep, random(0.26, 0.38));
      brush.line(p[0] + random(-2, 2), p[1] + random(-2, 2), p[0] + cos(ang) * 9, p[1] + sin(ang) * 9);
    }
  }

  // ---------------------------------------------------------------------------
  // CLOSED SLEEPING EYES (Tender downward arcs with dark lashes & spectacle rim)
  // ---------------------------------------------------------------------------
  // Left closed eye slit
  let leftEyePts = [[708, 840], [732, 858], [758, 862], [784, 850]];
  // Upper eyelid fold
  brush.set("HB", PAL.amberDeep, 0.32);
  brush.spline([[712, 832], [746, 849], [782, 842]], 0.5);
  // Dark lash line of closed sleeping eye
  brush.set("2B", PAL.umberBlack, 0.46);
  brush.spline(leftEyePts, 0.5);
  brush.set("rotring", PAL.umberBlack, 0.32);
  brush.spline(leftEyePts, 0.5);
  // Pale buff highlight directly along lower lid
  brush.set("2H", PAL.buffBright, 0.26);
  brush.spline([[712, 845], [746, 866], [782, 855]], 0.5);

  // Right closed eye slit
  let rightEyePts = [[836, 852], [862, 866], [888, 864], [912, 846]];
  brush.set("HB", PAL.amberDeep, 0.32);
  brush.spline([[838, 844], [875, 856], [910, 838]], 0.5);
  brush.set("2B", PAL.umberBlack, 0.46);
  brush.spline(rightEyePts, 0.5);
  brush.set("rotring", PAL.umberBlack, 0.32);
  brush.spline(rightEyePts, 0.5);
  brush.set("2H", PAL.buffBright, 0.26);
  brush.spline([[838, 857], [875, 870], [910, 851]], 0.5);

  // Outer eye corner tabby eyeliner flicks
  brush.set("2B", PAL.umberDeep, 0.36);
  brush.spline([[708, 840], [685, 846], [668, 862]], 0.4);
  brush.spline([[912, 846], [934, 855], [948, 874]], 0.4);

  // ---------------------------------------------------------------------------
  // THE SINGLE PINK NOSE (The sole pink note in the entire composition!)
  // ---------------------------------------------------------------------------
  let nosePts = [
    [790, 908], [808, 905], [826, 909],
    [822, 921], [808, 932], [794, 920]
  ];
  let nosePoly = new brush.Polygon(nosePts);
  brush.noStroke();
  nosePoly.wash(PAL.nosePink, 245);

  // Soft rose-pink pencil grain inside the nose pad
  for (let i = 0; i < 42; i++) {
    let nx = random(792, 824);
    let ny = random(906, 930);
    if (!pointInPoly(nx, ny, nosePts)) continue;
    let col = (ny < 914) ? PAL.noseHighlight : (ny > 922 ? PAL.noseShade : PAL.nosePink);
    brush.set("cpencil", col, 0.24);
    brush.line(nx - 1.5, ny, nx + 1.5, ny + 0.5);
  }

  // Diffuse warehouse window highlight on top of the nose leather
  brush.set("2H", PAL.noseHighlight, 0.32);
  brush.spline([[795, 910], [808, 908], [820, 911]], 0.4);

  // Dark umber skin rim framing the tabby nose leather (classic terracotta tabby nose liner)
  brush.set("2B", PAL.umberDeep, 0.32);
  brush.spline([[790, 908], [808, 905], [826, 909]], 0.4);
  brush.set("2B", PAL.umberBlack, 0.36);
  // Left & right nostrils + philtrum
  brush.line(792, 915, 801, 923);
  brush.line(824, 916, 815, 924);
  brush.line(808, 924, 808, 944);

  // Soft mouth curve under the whisker pads
  brush.set("2B", PAL.umberDeep, 0.32);
  brush.spline([[776, 948], [795, 945], [808, 943], [821, 946], [838, 950]], 0.4);

  // Whisker follicle dots on the plump cream whisker pads
  let follicleRows = [
    [[762, 924], [774, 926], [786, 927]],
    [[758, 934], [772, 936], [786, 937]],
    [[830, 928], [842, 927], [854, 925]],
    [[830, 938], [844, 937], [858, 935]]
  ];
  for (let row of follicleRows) {
    for (let pt of row) {
      brush.set("2B", PAL.umberDeep, 0.34);
      brush.line(pt[0] - 1.5, pt[1], pt[0] + 1.5, pt[1]);
    }
  }
}

// =============================================================================
// 4. LOWER-LEFT FLAP (FLAP C) WITH EXPOSED FLUTE WINDOW & CUT EDGE
// =============================================================================

function drawLowerLeftFlap() {
  // Cast shadow of Flap C onto the crumpled paper and box interior
  let flapCShadowPts = [[410, 440], [465, 445], [645, 1200], [585, 1200]];
  let fcsPoly = new brush.Polygon(flapCShadowPts);
  brush.noStroke();
  fcsPoly.wash(PAL.umberBlack, 145);

  let flapCPts = [[0, 500], [425, 435], [595, 1200], [0, 1200]];
  polyWashAndMarker(
    flapCPts,
    PAL.kraft,
    240,
    [PAL.kraft, PAL.kraftLight, PAL.kraftMid],
    -14,
    20,
    PAL.umberLight
  );
  sprinkleWoodPulpFlecks(flapCPts, 160, 0, 595, 435, 1200);

  // Score/fold crease line running parallel to the right edge of Flap C
  brush.set("marker", PAL.kraftDeep, 0.5);
  brush.line(355, 446, 520, 1200);
  brush.set("2H", PAL.buffWarm, 0.3);
  brush.line(360, 446, 525, 1200);

  // Cut corrugated cross-section along the right edge of Flap C (425, 435) -> (595, 1200)
  drawCorrugatedCutEdge([425, 435], [595, 1200], 13, 46);

  // EXPOSED FLUTE TEAR WINDOW ON FLAP C (where old shipping tape ripped the top kraft ply off)
  let cTearUpper = [
    [135, 685], [195, 662], [265, 650], [335, 638], [395, 642], [442, 655]
  ];
  let cTearLower = [
    [155, 795], [218, 785], [285, 765], [355, 755], [412, 742], [462, 735]
  ];
  drawExposedFluteBand(cTearUpper, cTearLower, 26, 20, false);
}

// =============================================================================
// 5. UPPER-RIGHT FLAP (FLAP B), CUT CORRUGATED EDGE & SMUDGED BARCODE LABEL
// =============================================================================

function drawUpperRightFlapAndLabel() {
  // Deep cast shadow thrown by Flap B onto the inner right wall and above the kitten
  let flapBShadowPts = [[665, 290], [1200, 525], [1200, 585], [645, 340]];
  let fbsPoly = new brush.Polygon(flapBShadowPts);
  brush.noStroke();
  fbsPoly.wash(PAL.umberBlack, 155);

  let flapBPts = [[540, 0], [1200, 0], [1200, 525], [665, 290]];
  polyWashAndMarker(
    flapBPts,
    PAL.kraftLight,
    240,
    [PAL.kraftLight, PAL.tanLight, PAL.kraft],
    24,
    20,
    PAL.kraftDeep
  );
  sprinkleWoodPulpFlecks(flapBPts, 165, 540, 1200, 0, 525);

  // Cut corrugated cross-section along the lower edge of Flap B (665, 290) -> (1200, 525)
  drawCorrugatedCutEdge([665, 290], [1200, 525], 14, 36);

  // Small corner tear on Flap B right above the kitten's shoulder exposing wavy flutes
  let bCornerUpper = [[965, 368], [1025, 385], [1085, 412], [1145, 438]];
  let bCornerLower = [[950, 412], [1012, 438], [1072, 466], [1135, 494]];
  drawExposedFluteBand(bCornerUpper, bCornerLower, 16, 14, false);

  // ---------------------------------------------------------------------------
  // WEATHERED SHIPPING LABEL WITH SMUDGED BARCODE
  // ---------------------------------------------------------------------------
  push();
  translate(915, 205);
  rotate(24);

  let lw = 290;
  let lh = 190;
  let x0 = -lw / 2;
  let y0 = -lh / 2;

  // Tiny cast shadow under the dog-eared bottom-left corner of the label
  let dogShadow = new brush.Polygon([
    [x0 - 4, y0 + lh - 38], [x0 + 38, y0 + lh + 5], [x0 - 2, y0 + lh + 6]
  ]);
  brush.noStroke();
  dogShadow.wash(PAL.umberDeep, 175);

  // Label polygon (with bottom-left corner dog-eared/peeled up)
  let labelPts = [
    [x0, y0],
    [x0 + lw, y0],
    [x0 + lw, y0 + lh],
    [x0 + 34, y0 + lh],
    [x0, y0 + lh - 34]
  ];
  polyWashAndMarker(
    labelPts,
    PAL.labelBase,
    242,
    [PAL.labelBase, PAL.labelAged],
    0,
    22,
    PAL.warmGreyLight
  );

  // Curled dog-ear triangle folded over
  let curlPts = [[x0, y0 + lh - 34], [x0 + 34, y0 + lh - 34], [x0 + 34, y0 + lh]];
  let curlPoly = new brush.Polygon(curlPts);
  brush.noStroke();
  curlPoly.wash(PAL.buffWarm, 235);
  brush.set("HB", PAL.umberLight, 0.28);
  brush.line(x0, y0 + lh - 34, x0 + 34, y0 + lh - 34);
  brush.line(x0 + 34, y0 + lh - 34, x0 + 34, y0 + lh);

  // Label border & internal parcel routing grid in faded rotring ink
  brush.set("rotring", PAL.warmGreyDark, 0.32);
  brush.line(x0 + 8, y0 + 8, x0 + lw - 8, y0 + 8);
  brush.line(x0 + lw - 8, y0 + 8, x0 + lw - 8, y0 + lh - 8);
  brush.line(x0 + 36, y0 + lh - 8, x0 + lw - 8, y0 + lh - 8);
  brush.line(x0 + 8, y0 + 8, x0 + 8, y0 + lh - 36);

  // Horizontal divider rules
  brush.line(x0 + 8, y0 + 46, x0 + lw - 8, y0 + 46);
  brush.line(x0 + 8, y0 + 78, x0 + lw - 8, y0 + 78);
  brush.line(x0 + 8, y0 + 162, x0 + lw - 8, y0 + 162);
  brush.line(x0 + 92, y0 + 8, x0 + 92, y0 + 78);

  // Heavy dark parcel routing block ("H2 / STD") in top-left box
  let blkPoly = new brush.Polygon([
    [x0 + 14, y0 + 14], [x0 + 84, y0 + 14], [x0 + 84, y0 + 40], [x0 + 14, y0 + 40]
  ]);
  brush.noStroke();
  blkPoly.wash(PAL.umberDeep, 220);

  // Simulated small tracking & address text lines in top-right box
  for (let row = 0; row < 3; row++) {
    let ry = y0 + 18 + row * 9;
    let rx = x0 + 102;
    while (rx < x0 + lw - 24) {
      let wLen = random(8, 26);
      brush.set("rotring", PAL.umber, 0.28);
      brush.line(rx, ry, min(rx + wLen, x0 + lw - 20), ry + random(-0.4, 0.4));
      rx += wLen + random(5, 9);
    }
  }

  // Secondary small routing marks in middle band
  for (let c = 0; c < 8; c++) {
    let bx = x0 + 18 + c * 31;
    brush.set("marker", PAL.umber, 0.35);
    brush.line(bx, y0 + 56, bx + 18, y0 + 56);
    brush.set("2H", PAL.warmGreyDark, 0.25);
    brush.line(bx, y0 + 66, bx + 22, y0 + 66);
  }

  // ---------------------------------------------------------------------------
  // THE SMUDGED BARCODE (Main Barcode Band: y0 + 84 to y0 + 148)
  // ---------------------------------------------------------------------------
  let bcLeft = x0 + 22;
  let bcRight = x0 + lw - 22;
  let bcTop = y0 + 85;
  let bcBot = y0 + 146;

  // Smudge zone centered around (x0 + 165, y0 + 115) running at -28 deg
  let bxCursor = bcLeft;
  let barIdx = 0;
  while (bxCursor < bcRight) {
    let isThick = (barIdx % 5 === 1 || barIdx % 7 === 3);
    let isMed = (barIdx % 3 === 0);
    let barWt = isThick ? 0.68 : (isMed ? 0.42 : 0.24);
    let gap = isThick ? 5.2 : (isMed ? 3.8 : 2.7);

    // Check proximity to the diagonal smudge center
    let dSmudge = abs((bxCursor - (x0 + 162)) * 0.75);
    if (dSmudge < 38) {
      // Inside the smudge: bars break up, fade, and smear sideways!
      let smearStrength = map(dSmudge, 0, 38, 1.0, 0.15);
      // Upper intact fragment of bar
      let cutTop = bcTop + random(8, 22) * (1 - smearStrength * 0.4);
      brush.set("rotring", PAL.umber, barWt * 0.85);
      brush.line(bxCursor, bcTop, bxCursor, cutTop);

      // Lower intact fragment of bar
      let cutBot = bcBot - random(8, 20) * (1 - smearStrength * 0.4);
      brush.set("rotring", PAL.umber, barWt * 0.85);
      brush.line(bxCursor, cutBot, bxCursor, bcBot);

      // Smeared middle section in warm grey & umber pencil/marker
      brush.set("HB", PAL.warmGreyDark, barWt * 1.1);
      brush.line(
        bxCursor + random(-2, 2),
        cutTop - 3,
        bxCursor + smearStrength * random(6, 14),
        cutBot + 3
      );
    } else {
      // Crisp barcode bar
      brush.set("rotring", PAL.umberBlack, barWt);
      brush.line(bxCursor, bcTop, bxCursor, bcBot);
      if (isThick) {
        brush.set("2B", PAL.umberDeep, 0.35);
        brush.line(bxCursor + 1.1, bcTop, bxCursor + 1.1, bcBot);
      }
    }

    bxCursor += gap;
    barIdx++;
  }

  // Directional smudge smear & raw paper abrasion scratch across the barcode
  for (let s = 0; s < 38; s++) {
    let sx = x0 + 105 + random(0, 115);
    let sy = y0 + 92 + (sx - (x0 + 105)) * 0.25 + random(-14, 14);
    let sLen = random(18, 42);
    let sAng = -16 + random(-8, 8);
    brush.set(s % 3 === 0 ? "charcoal" : "HB", s % 2 === 0 ? PAL.warmGreyDeep : PAL.umberLight, random(0.24, 0.42));
    brush.line(sx, sy, sx + cos(sAng) * sLen, sy + sin(sAng) * sLen);
  }
  // Abraded pale paper scratch cutting through the smudged bars
  for (let a = 0; a < 8; a++) {
    let ax = x0 + 125 + a * 8;
    let ay = y0 + 118 - a * 2.2 + random(-2, 2);
    brush.set("2H", PAL.labelBase, 0.34);
    brush.line(ax, ay, ax + 18, ay - 5);
  }

  // Human-readable tracking numbers below the barcode (partially smudged in middle)
  for (let d = 0; d < 16; d++) {
    let dx = bcLeft + 14 + d * 14;
    let dy = y0 + 154;
    let isSmudgedDigit = (d >= 7 && d <= 11);
    brush.set("rotring", isSmudgedDigit ? PAL.warmGrey : PAL.umberDeep, 0.26);
    brush.line(dx, dy - 3, dx + 5, dy - 3);
    brush.line(dx + 5, dy - 3, dx + 4, dy + 3);
    brush.line(dx, dy + 3, dx + 5, dy + 3);
  }

  pop();
}

// =============================================================================
// 6. MAIN UPPER-LEFT TORN FLAP (FLAP A) & HERO EXPOSED CORRUGATED FLUTE
// =============================================================================

function drawMainUpperLeftFlap() {
  // Upper tear lip (where the outer kraft liner sheet ends)
  let heroTearUpper = [
    [0, 505], [65, 512], [135, 488], [210, 462], [285, 428],
    [360, 404], [435, 368], [512, 342], [590, 308], [670, 282]
  ];

  // Lower tear lip (where the exposed corrugated inner flute itself tears off over the box interior)
  let heroTearLower = [
    [0, 582], [78, 594], [155, 568], [232, 544], [312, 506],
    [390, 478], [468, 442], [545, 405], [618, 365], [685, 326]
  ];

  // Deep dramatic cast shadow thrown by the ragged torn edge onto Flap C and the box interior
  let heroShadowChain = heroTearLower.map(p => [p[0] + 14, p[1] + 28]);
  let heroShadowPts = [...heroTearLower, ...heroShadowChain.slice().reverse()];
  let hsPoly = new brush.Polygon(heroShadowPts);
  brush.noStroke();
  hsPoly.wash(PAL.umberBlack, 165);

  // Main intact kraft surface of Flap A
  let flapAPts = [
    [0, 385], [540, 0], [670, 282],
    ...heroTearUpper.slice().reverse()
  ];
  polyWashAndMarker(
    flapAPts,
    PAL.kraft,
    242,
    [PAL.kraft, PAL.kraftLight, PAL.tanLight, PAL.kraftMid],
    -35,
    18,
    PAL.kraftDeep
  );
  sprinkleWoodPulpFlecks(flapAPts, 220, 0, 670, 0, 515);

  // Fold score crease along the upper-left outer edge of the box (0, 385) -> (540, 0)
  brush.set("marker", PAL.buffWarm, 0.55);
  brush.line(0, 388, 540, 3);
  brush.set("2H", PAL.buffLight, 0.32);
  brush.line(0, 386, 540, 1);
  brush.set("HB", PAL.kraftDeep, 0.3);
  brush.line(0, 394, 544, 7);

  // Second subtle Diagonal Box Crease across Flap A where it was bent back
  brush.set("marker", PAL.kraftDeep, 0.45);
  brush.line(120, 298, 415, 376);
  brush.set("2H", PAL.buffWarm, 0.28);
  brush.line(122, 294, 417, 372);

  // RENDER THE HERO EXPOSED CORRUGATED FLUTE BAND ACROSS THE DIAGONAL TEAR!
  drawExposedFluteBand(heroTearUpper, heroTearLower, 48, 32, true);
}

// =============================================================================
// 7. SCUFFED PACKING TAPE (BRIDGING FLAPS & HANGING TORN OVER THE EDGE)
// =============================================================================

function drawScuffedTape() {
  // ---------------------------------------------------------------------------
  // TAPE STRIP 1: Running down the seam between Flap A & Flap B, with a loose torn tail
  // ---------------------------------------------------------------------------
  let tape1Pts = [
    [435, 0], [535, 0], [748, 325], [768, 415],
    [728, 438], [685, 422], [652, 355]
  ];
  let t1Poly = new brush.Polygon(tape1Pts);

  // Cast shadow under the hanging loose tail of Tape 1 (below y = 300)
  let tailShadow = new brush.Polygon([
    [652, 355], [748, 325], [778, 428], [735, 452], [690, 436]
  ]);
  brush.noStroke();
  tailShadow.wash(PAL.umberBlack, 140);

  // Translucent amber-tan marker wash for the packing tape
  brush.noStroke();
  t1Poly.wash(PAL.tapeBase, 145);
  brush.hatchStyle("kraft_marker", PAL.tapeAmber, 0.58);
  t1Poly.hatch(14, 56, { rand: 0.03, continuous: true });
  brush.noHatch();

  // Longitudinal fiberglass reinforcement filaments inside the tape
  for (let f = 0.12; f <= 0.88; f += 0.15) {
    let pTop = lerpPt([435, 0], [535, 0], f);
    let pMid = lerpPt([652, 355], [748, 325], f);
    let pBot = lerpPt([685, 422], [768, 415], f);
    brush.set("2H", PAL.tapeHighlight, 0.2);
    brush.spline([pTop, pMid, pBot], 0.35);
  }

  // Crinkled air-bubbles, diagonal creases & warehouse scuff marks on Tape 1
  let wrinkles1 = [
    [[482, 48], [552, 38]],
    [[525, 118], [598, 95]],
    [[572, 195], [648, 178]],
    [[618, 272], [698, 248]],
    [[660, 342], [742, 320]],
    [[682, 388], [756, 374]]
  ];
  for (let w of wrinkles1) {
    // Specular buff-white crinkle ridge
    brush.set("2H", PAL.tapeHighlight, 0.34);
    brush.line(w[0][0], w[0][1], w[1][0], w[1][1]);
    // Tight dark shadow under the crinkle
    brush.set("HB", PAL.umberLight, 0.26);
    brush.line(w[0][0] + 2, w[0][1] + 3, w[1][0] + 2, w[1][1] + 3);
  }

  // Dirty warehouse scuffs across the tape
  for (let s = 0; s < 34; s++) {
    let u = random(0.1, 0.9);
    let v = random(0.1, 0.9);
    let pTop = lerpPt([435, 0], [535, 0], u);
    let pBot = lerpPt([685, 422], [768, 415], u);
    let sp = lerpPt(pTop, pBot, v);
    let ang = random(-35, 25);
    let len = random(8, 22);
    brush.set("HB", PAL.tapeScuff, random(0.2, 0.32));
    brush.line(sp[0], sp[1], sp[0] + cos(ang) * len, sp[1] + sin(ang) * len);
  }

  // Tape edges and serrated/torn bottom teeth
  brush.set("2H", PAL.tapeHighlight, 0.28);
  brush.spline([[435, 0], [652, 355], [685, 422]], 0.3);
  brush.set("HB", PAL.umberLight, 0.28);
  brush.spline([[535, 0], [748, 325], [768, 415]], 0.3);

  // Ragged serrated bottom edge of the hanging tape tail
  let teethPts = [];
  for (let t = 0; t <= 10; t++) {
    let u = t / 10;
    let bp = lerpPt([685, 422], [768, 415], u);
    let dy = (t % 2 === 0) ? 0 : 9;
    teethPts.push([bp[0], bp[1] + dy]);
  }
  brush.set("2H", PAL.tapeHighlight, 0.3);
  brush.spline(teethPts, 0.15);

  // ---------------------------------------------------------------------------
  // TAPE STRIP 2: Scuffed & partially peeled strip across Flap A
  // ---------------------------------------------------------------------------
  let tape2Pts = [
    [135, 315], [485, 165], [518, 232], [168, 382]
  ];
  let t2Poly = new brush.Polygon(tape2Pts);
  brush.noStroke();
  t2Poly.wash(PAL.tapeBase, 130);
  brush.hatchStyle("kraft_marker", PAL.tapeAmber, 0.48);
  t2Poly.hatch(15, -24, { rand: 0.04, continuous: true });
  brush.noHatch();

  // Crinkles and scuffs on Tape 2
  for (let k = 0; k < 7; k++) {
    let u = (k + 0.5) / 7;
    let pA = lerpPt([135, 315], [485, 165], u);
    let pB = lerpPt([168, 382], [518, 232], u + random(-0.04, 0.04));
    brush.set("2H", PAL.tapeHighlight, 0.3);
    brush.line(pA[0], pA[1], pB[0], pB[1]);
    brush.set("HB", PAL.tapeScuff, 0.24);
    brush.line(pA[0] + 3, pA[1] + 2, pB[0] + 3, pB[1] + 2);
  }
  brush.set("2H", PAL.tapeHighlight, 0.26);
  brush.line(135, 315, 485, 165);
  brush.set("HB", PAL.kraftDeep, 0.26);
  brush.line(168, 382, 518, 232);
}

// =============================================================================
// 8. FOREGROUND WHISKERS & DELICATE FINISHING TOUCHES
// =============================================================================

function drawFinalForegroundTouches() {
  // Long, graceful pale cream whiskers arching from the sleeping kitten's muzzle
  // Drawn last so they overlap the paws, tail, and dark box shadows with hyperreal crispness!
  let leftWhiskers = [
    [[774, 922], [705, 925], [632, 946]],
    [[768, 926], [692, 938], [612, 968]],
    [[762, 932], [688, 952], [615, 992]],
    [[772, 936], [708, 962], [645, 1006]],
    [[780, 940], [726, 968], [678, 1012]]
  ];

  let rightWhiskers = [
    [[842, 924], [912, 930], [986, 954]],
    [[848, 929], [924, 942], [1002, 974]],
    [[852, 934], [928, 956], [998, 995]],
    [[844, 938], [910, 965], [968, 1008]],
    [[836, 942], [892, 972], [942, 1012]]
  ];

  // Superciliary (brow) whiskers above the closed eyes
  let browWhiskers = [
    [[736, 826], [692, 792], [648, 782]],
    [[748, 822], [708, 782], [666, 766]],
    [[876, 830], [922, 796], [968, 788]],
    [[864, 826], [906, 788], [950, 772]]
  ];

  let allWhiskers = [...leftWhiskers, ...rightWhiskers, ...browWhiskers];
  for (let wPts of allWhiskers) {
    // Subtle dark shadow directly beneath each whisker
    let shPts = wPts.map(p => [p[0], p[1] + 1.8]);
    brush.set("2H", PAL.umberDeep, 0.2);
    brush.spline(shPts, 0.5);

    // Crisp ivory-buff whisker shaft
    brush.set("needle_pencil", PAL.buffBright, 0.85);
    brush.spline(wPts, 0.5);
    brush.set("2H", PAL.buffBright, 0.24);
    brush.spline(wPts, 0.5);
  }

  // Fuzzy backlit halo of fine kitten guard hairs along the crown, ears, and arched back
  for (let i = 0; i < 95; i++) {
    let t = i / 94;
    let bx, by, ang;
    if (t < 0.45) {
      // Along crown between ears
      let u = map(t, 0, 0.45, 0, 1);
      bx = lerp(742, 888, u);
      by = lerp(698, 712, u) - sin(u * 180) * 8;
      ang = -90 + (u - 0.5) * 40 + random(-8, 8);
    } else {
      // Along upper shoulder ridge
      let u = map(t, 0.45, 1, 0, 1);
      bx = lerp(820, 1085, u);
      by = lerp(608, 622, u) - sin(u * 180) * 24;
      ang = -45 + u * 65 + random(-8, 8);
    }
    let len = random(9, 17);
    brush.set("2H", i % 2 === 0 ? PAL.buffBright : PAL.buffLight, random(0.16, 0.25));
    brush.line(bx, by, bx + cos(ang) * len, by + sin(ang) * len);
  }
}
